// ==UserScript==
// @name         Lepra Mobile
// @namespace    lepra.mobile
// @version      1.1.32
// @description  Мобильная адаптация leprosorium.ru для iOS Safari
// @author       neokrasav4ik
// @homepageURL  https://github.com/neokrasav4ik/lepra-mobile
// @supportURL   https://github.com/neokrasav4ik/lepra-mobile/issues
// @updateURL    https://raw.githubusercontent.com/neokrasav4ik/lepra-mobile/main/lepra-mobile.user.js
// @downloadURL  https://raw.githubusercontent.com/neokrasav4ik/lepra-mobile/main/lepra-mobile.user.js
// @license      MIT
// @match        *://leprosorium.ru/*
// @match        *://*.leprosorium.ru/*
// @run-at       document-start
// @inject-into  auto
// @grant        none
// ==/UserScript==

/*
 * Что делает скрипт
 * -----------------
 * Лепрозорий свёрстан под фиксированную ширину с левой колонкой в 245px,
 * правой в 270-340px и без метатега viewport. На телефоне Safari рисует
 * страницу в виртуальном окне 980px и ужимает её — отсюда микрошрифт.
 *
 * Скрипт добавляет viewport, разбирает десктопную раскладку на одну колонку
 * и чинит элементы, которые были прибиты к координатам несуществующих колонок.
 * Плюс несколько своих удобств: навигация по комментариям, просмотрщик
 * картинок, тёмная тема.
 *
 * Чего скрипт НЕ делает
 * ---------------------
 * Не собирает и не передаёт никаких данных. Не обращается к сторонним
 * серверам. Не трогает куки, пароли и содержимое форм. Единственные сетевые
 * запросы — подгрузка превью видео с тех же адресов, откуда их берёт сама
 * лепра. Всё остальное — работа с DOM открытой страницы.
 */

(function () {
  'use strict';

  /* Внутри скрытого окна, которым грузится лента уведомлений (см. раздел
     4.2), перестраивать страницу не надо: человеку её не показывают, а
     второй проход по всему документу — лишняя работа и лишние наблюдатели.

     Но одно полезное дело там есть. Ленту в этом окне собирает скрипт
     лепры — своими запросами к своему API. Из главного окна их не видно:
     у окна собственное окружение и собственный fetch, и наш перехват
     туда не достаёт. Поэтому здесь ставится маленький самостоятельный
     писец: он ничего не меняет, только записывает метод, адрес и
     заголовки и складывает строки в массив главного окна — источник тот
     же, доступ прямой. Это и есть ответ на вопрос, чем звать API,
     ради которого иначе пришлось бы вручную снимать отчёт на странице
     уведомлений. */
  if (window.name === 'lm-pyn-frame') {
    /* Отметка ставится ДО писца и до всяких проверок: она отвечает на
       отдельный вопрос — запускается ли скрипт внутри окна вообще.
       Менеджеры юзерскриптов нередко внедряют только в верхний фрейм,
       и тогда пустой список вызовов означает не «лепра ничего не
       запрашивала», а «записывать было некому». */
    try {
      window.parent.lmPynRan = (window.parent.lmPynRan || 0) + 1;
    } catch (e) {}
    try { recordInFrame(); } catch (e) {}
    return;
  }

  /* Окно-почтальон. Через него из окна пыни уходит всё, что мы шлём на
     сервер лепры от имени человека: голос за комментарий и ответ на
     него. Имя окна историческое — заводилось оно под голосование, а имя
     переживает переименования хуже кода, и менять его значит трогать
     две строки в разных концах файла ради слова.
     Нужно оно потому, что уведомление может прийти из подлепры, а
     запрос уходит на ЕЁ домен: с главной это межсайтовый запрос. Отправить его можно только «простым» — без своего заголовка
     X-Requested-With, который лепра, судя по всему, и требует: на
     главном домене такой же запрос с заголовком проходит, а на чужом
     без него молча ничего не меняет. Прочитать ответ браузер тоже не
     даёт, так что и узнать об этом изнутри нельзя.
     Поэтому голосуем НЕ ОТТУДА. Открываем невидимое окно на нужном
     домене — там наш скрипт запускается сам, и для него запрос уже
     свой, со всеми заголовками и читаемым ответом. Разговариваем через
     postMessage: другого моста между окнами разных доменов нет.
     Проверка отправителя обязательна: принимаем только сообщения от
     своего же родителя и только с нашей меткой. */
  if (window.name === 'lm-vote-frame') {
    try {
      window.addEventListener('message', function (e) {
        var d = e.data;
        if (!d || e.source !== window.parent) return;

        if (d.lm !== 'send') return;
        /* Адрес и тело присылает родитель целиком. Раньше окно умело
           ровно одно действие — голос — и собирало тело само; с
           появлением ответа на комментарий действий стало два, и держать
           в окне знание о каждом значит править его при каждом новом.
           Окно теперь просто почтальон: несёт что дали и приносит
           ответ. */
        var body = d.body;
        fetch(d.path, {
          method: 'POST',
          credentials: 'include',
          headers: { 'Content-Type': 'application/x-www-form-urlencoded',
                     'X-Requested-With': 'XMLHttpRequest' },
          body: body
        }).then(function (r) {
          return r.text().then(function (txt) {
            e.source.postMessage({ lm: 'send-done', id: d.id,
                                   status: r.status, text: txt }, '*');
          });
        }).catch(function (err) {
          e.source.postMessage({ lm: 'send-done', id: d.id, status: 0,
                                 text: String(err && err.message || err) }, '*');
        });
      });
      window.parent.postMessage({ lm: 'vote-ready',
                                  origin: location.origin }, '*');
    } catch (e) {}
    return;
  }

  var VERSION = '1.1.32';

  /* ============================================================
     НАСТРОЙКИ
     ============================================================ */

  var CFG = {
    /* Ширина экрана, до которой работает адаптация. На широких экранах
       десктопная вёрстка лепры уместна сама по себе.
       Сравнивается с шириной ФИЗИЧЕСКОГО экрана, а не окна: скрипт стартует
       до применения viewport, когда Safari считает окно шириной 980, а при
       уменьшенном масштабе страницы — и вовсе за тысячу. */
    maxWidth: 1024,

    /* Видео.
       videoPreload: 'none'     — ничего не качать до нажатия плей
                     'metadata' — только заголовок файла (пара килобайт),
                                  зато известны пропорции и блок не прыгает
       videoPoster:  'frame' — коротко проиграть без звука и встать на паузу;
                               единственный способ, дающий первый кадр на iOS
                     'seek'  — только перемотка, легче, но кадра обычно нет
                     'none'  — не добывать кадр, будет пустой прямоугольник */
    videoPreload: 'metadata',
    videoPoster: 'frame',

    /* За сколько пикселей до экрана готовить медиа и сколько роликов
       обрабатывать одновременно. Оба числа влияют на трафик и на нагрев:
       подготовка десятков видео разом занимает главный поток. */
    lookAhead: 1200,
    maxParallelVideos: 2,
    posterFallbackDelay: 250,

    /* НАСТРОЙКА: останавливать ли ролик, уехавший за край экрана.
       Лепра этого не делает: запущенное видео продолжает играть, пока
       человек листает ленту дальше, — звук идёт из ниоткуда, а трафик
       и батарея тратятся на то, чего не видно.
       Останавливаем только полностью ушедшее: на пороге в половину
       ролик глох бы от случайного подскролла на строку.
       Пауза, а не остановка: место в ролике сохраняется, и вернувшись
       к нему, человек продолжает с того же кадра.
       Только <video>. Ролики в <iframe> (ютуб и соседи) остановить
       снаружи нечем: у них своё окружение, и без их собственного API
       остаётся разве что снять адрес — то есть перезагрузить плеер и
       потерять место. Это хуже, чем играющий за экраном звук.
       videoPauseOwn: false остановит и то, что запустили мы сами при
       добыче первого кадра, — но своё воспроизведение и так длится
       доли секунды и кончается паузой, а лишняя пауза посреди него
       может сбить добычу кадра. */
    videoPauseOff: true,
    videoPauseOwn: false,

    /* НАСТРОЙКА: выгружать ролики, уехавшие далеко за экран.
       Разобрано по отчёту с устройства, и цифры там не оставляли выбора:
       при 165 постах в ленте — 33 ролика, из них 32 за экраном,
       881 секунда видео в буферах и СЕМЬ РОЛИКОВ, качающих данные прямо
       сейчас. Ни один из них человек не смотрит и, пролистав, уже не
       посмотрит. Отсюда и жар, и трафик.
       preload=metadata тут не помогает: Safari трактует его свободно и
       дотягивает ролик до готовности к воспроизведению — в отчёте
       readyState=4 у тридцати из тридцати трёх.
       Выгрузка настоящая: снимаем источник и просим браузер начать
       заново с пустого места. Только так отменяется незавершённая
       закачка и освобождается буфер; preload='none' задним числом не
       делает ни того, ни другого.
       Место в ролике и его источник запоминаются, при возвращении в
       поле зрения всё восстанавливается.
       videoFreeAhead — за сколько экранов от края начинать выгружать.
       Два, а не ноль: рядом с экраном ролик должен быть готов к
       нажатию, иначе первый тап уйдёт в ожидание загрузки. */
    videoFree: true,
    /* Сколько миллисекунд после события load не выгружать ничего.

       Выгрузка решает, что ролик далеко, по положению прокрутки. При
       переходе «назад» браузер восстанавливает место не мгновенно, и в
       промежутке страница честно стоит наверху: наблюдатель видит все
       ролики дальше двух экранов и выгружает их — включая те, которые
       через мгновение окажутся под глазами. Место восстанавливается,
       ближняя граница возвращает их обратно, источник назначается
       заново, браузер перезагружает кадр. Это и есть перерисовка медиа,
       которую видно как моргание.

       Ждём, пока страница устоится. Полторы секунды ничего не стоят: за
       это время дальше двух экранов не улистать, а выгружать ролики,
       мимо которых ещё не прошли, незачем в любом случае. */
    videoFreeWait: 1000,
    videoFreeAhead: 2,
    /* Граница ВОЗВРАТА — ближе, чем граница выгрузки, и это не
       украшательство. С одной границей на оба решения ролик, стоящий у
       самой черты, выгружается и возвращается от любого дрожания: от
       подскролла на строку, от среза соседнего поста, от появившейся
       картинки. В отчёте с устройства это видно прямо: 60 выгрузок и 32
       возврата на 33 ролика — каждый успел съездить туда-обратно, и
       каждый возврат заново тянул заголовок с сервера.
       Две границы дают между собой мёртвую полосу: дальше двух экранов
       выгружаем, ближе одного возвращаем, между ними не делаем ничего.
       Пересечь обе за один подскролл нельзя. */
    videoBackAhead: 1,

    /* НАСТРОЙКА: показывать ли под роликом прямую ссылку на файл.
       В Safari вытащить адрес видео из плеера муторно: долгое нажатие
       открывает системное меню самого плеера, а не страницы. Отдельная
       ссылка решает это одним касанием.
       Адрес берётся тот же, что играет: currentSrc, а при его
       отсутствии — src или первый <source>. У роликов в <iframe> это
       адрес встроенного проигрывателя, а не файла, — по нему всё равно
       попадаешь на сам ролик, и это лучше, чем ничего. */
    videoLink: false,

    /* НАСТРОЙКА: до какой доли высоты экрана сокращать КОММЕНТАРИЙ в
       режиме «уплотняем посты и комментарии». Отдельное число от постового
       (discoCut) намеренно: комментарии короче постов, и одна доля на
       двоих либо не трогала бы длинные комментарии, либо кромсала бы
       посты.
       Сорок пять — примерно полтора десятка строк при экране 735, то
       есть развёрнутая мысль видна целиком, а простыня на три экрана
       сворачивается.
       Устройство среза проще, чем у постов, и это не упрощение ради
       упрощения. У поста подпись лежит ПОД телом, её высоту приходится
       вычитать из бюджета, а тело делится на текст до первой картинки,
       саму картинку и хвост. У комментария подпись — отдельный узел
       (.c_footer) рядом с телом (.c_body), и резать надо ровно тело:
       вычитать нечего, делить нечего.
       Scroll-connect в комментариях не работает — так задумано: в треде
       на тысячу комментариев стыковка превратилась бы из забавы в
       повинность. Разворачивает тап по стрелке. */
    commentCut: 45,

    /* НАСТРОЙКА: потолок высоты медиа в постах и комментариях — доля
       высоты экрана в процентах.
       Своего уменьшателя по высоте у нас до сих пор не было: картинки
       ограничивались только шириной (max-width: 100%), и вертикальная
       фотография занимала экран целиком, а иногда и больше. Читать
       ленту, где один кадр — один экран, невозможно: пост превращается
       в стену, между двумя абзацами текста лежит полтора экрана
       пролистывания.
       Уменьшается размер, а не качество: файл приходит тот же, меняются
       только его экранные размеры, и щипком деталь по-прежнему видна.
       Пропорции сохраняются сами — ширина у медиа auto, и потолок по
       высоте тянет её за собой.
       Порог один, а не два. Сперва задумывалось «трогать то, что выше
       80%, ужимая до 70%», но разница между двумя правилами и одним
       касается только медиа ростом между этими числами, а объяснять
       человеку в настройках пришлось бы два ползунка вместо одного.
       Одно число — оно же и есть то, что рисует схемофон в настройках.
       Действует ДО диско и независимо от него: диско накладывает свой,
       более жёсткий бюджет поверх, а на разуплотнённых постах и в
       комментариях работает только этот потолок.
       Роликов в <iframe> потолок не касается. Встроенные проигрыватели
       почти всегда широкие (16:9 при экране 393 — это 221 пиксель, до
       потолка далеко), а ширину им задаёт aspect-ratio: предел по
       высоте вступил бы с ним в спор и расплющил кадр.
       Единицы — vh, а не замер окна. В Safari на iOS 100vh отсчитывается
       от экрана с убранной адресной строкой и при прокрутке не меняется,
       то есть ведёт себя как замороженная высота (см. discoVh), только
       бесплатно. */
    mediaCut: 75,

    /* Тап по картинке. 'off' — ничего не делать: файлы у лепры
       полноразмерные, и деталь проще посмотреть щипком.
       'zoom' — узкие картинки разворачивать на всю ширину по тапу.
       В обоих случаях лепровский обработчик глушится: он подменяет узел
       и выбрасывает страницу наверх. */
    imageTap: 'off',

    /* Настройки searchTrim здесь больше нет. Она укорачивала поле поиска,
       пока оно стояло в шапке отдельной строкой и упиралось в соседа;
       поиск уехал в навигационную штуку, где ширину задаёт колонка, и
       отнимать пиксели стало не у чего и незачем. Вместе с настройкой
       убран и код замера в relayoutHeader. */

    /* НАСТРОЙКА: нижний предел ширины поля поиска в сжатой шапке страниц
       с вкладками («мои вещи», инбокс, избранное). Там поле делит строку
       со ссылками и отдаёт им место первым, но уже поля в сантиметр
       вводить нечего. Больше число — поле длиннее, ссылкам теснее. */
    tabsSearchMin: 74,

    /* НАСТРОЙКА: поле поиска в шапке и привязанный к нему динамический
       список лепры (она показывает найденное прямо во время набора).
       searchWide — растягивать ли поле влево до кромки экрана на время
       ввода. false вернёт поле в свою треть колонки; список при этом
       всё равно останется прижатым к краям, но встанет под коротким
       полем, а не под длинным.
       searchFocusFont — кегль поля на время ввода. Ниже шестнадцати
       Safari на iOS приближает страницу к полю при касании, и тогда
       список шире видимой части экрана, каким бы узким его ни сделать.
       Кегль поднимается по касанию, ДО фокуса: решение о приближении
       Safari принимает в момент нажатия.
       ВАЖНО: шестнадцать здесь — не готовое число, а требование к
       ТОМУ, ЧТО ВИДНО НА ЭКРАНЕ. Safari умеет масштабировать страницу
       целиком (меню «Аа»), и при 85% шестнадцатый кегль доходит до
       глаза тринадцатым с половиной — Safari считает такое поле мелким
       и всё равно приближает страницу, а раз окно раскладки при этом
       шире экрана (462 против 393), правый край с лупой уезжает за
       кромку. Поэтому настоящий кегль считается делением на масштаб
       (searchFontVar) и кладётся в переменную --lm-srch-font; при
       обычном стопроцентном масштабе получается ровно это число.
       searchFontMax — потолок на случай сильно уменьшенной страницы:
       при масштабе 50% деление дало бы тридцать два, и поле стало бы
       выше строки ссылок.
       searchListMin — нижний предел высоты списка. Клавиатура съедает
       больше половины экрана, и остатка иногда не хватает даже на две
       строчки; короткий список с прокруткой лучше полоски в палец.
       searchHold — сколько миллисекунд держать поле раскрытым после
       потери фокуса. Тап по строчке списка сначала снимает фокус с
       поля, и мгновенное схлопывание увело бы ссылку из-под пальца. */
    searchWide: true,
    searchFocusFont: 16,
    searchFontMax: 22,
    searchListMin: 160,
    searchHold: 350,
    /* searchTop — на сколько пикселей ниже верхней кромки экрана ставить
       поле, когда в него тапнули. Страница подкручивается так, чтобы всё
       место между полем и клавиатурой досталось списку: при поднятой
       клавиатуре видно меньше половины экрана, и каждая сотня пикселей
       выше поля — это две строчки найденного, которых не увидеть.
       searchScroll: false отключит подкрутку, если она мешает.
       searchLift — через сколько миллисекунд после первой буквы крутить.
       Ноль означает «следующим кадром»: к моменту ввода клавиатура уже
       стоит, Safari своё подтягивание закончил, и ждать больше нечего —
       нужен лишь кадр на пересчёт раскладки после раздвижки поля. */
    searchScroll: true,
    searchTop: 6,
    searchLift: 0,
    /* Строка запроса на странице /search/. Кегль 16 и выше — чтобы
       Safari не приближал экран (у лепры там 20, и это уже хорошо, но
       20 на телефоне занимает полстроки зря). */
    bigSearchField: 36,
    bigSearchFont: 17,

    /* НАСТРОЙКА: поля страницы по краям экрана — та самая узкая рамка,
       из-за которой текст не упирается в кромку. Число одно на весь
       скрипт: им же отмеряется, насколько растянуть кастомный фон
       подлепры, чтобы он доходил до краёв, а текст остался на месте. */
    pageEdge: 12,

    /* НАСТРОЙКА: высота полосы фона профиля между навигационной штукой и
       телом. По бокам и снизу фон занимает дежурные поля страницы
       (pageEdge) — те самые, что на подлепрах отданы кастомному фону.
       Ноль оставит только боковые полосы. У профилей без своей картинки
       обрамления нет в любом случае. */
    profileArt: 24,

    /* НАСТРОЙКА: кегль поля выбора порога постов («NORMAL (0)»,
       «NIGHTMARE (все)») и нижний предел, до которого его можно ужимать.
       Поле стоит в третьей колонке навигационной штуки, и ширину ему
       задаёт самый длинный вариант списка, а не выбранный. Треть строки
       при экране 393 — это 111 пикселей, а прописной «NIGHTMARE (все)»
       набором Verdana 12 просит около 130 вместе с рамкой и стрелкой.
       Поэтому кегль подбирается замером (fitThreshold): начинается с
       thresholdFont и опускается полупунктами, но не ниже
       thresholdFontMin — там уже нечитаемо, и честнее срезать хвост.
       Начальные тринадцать взяты не с потолка: столько же у поля поиска
       и у кнопок над ним, и в узкой колонке всё равно опустится, зато
       на широком экране (уменьшенный масштаб страницы) все четыре
       органа окажутся одного кегля.
       Verdana при равных числах выглядит крупнее Arial: очко буквы у неё
       0.545 кегля против 0.519. */
    thresholdFont: 13,
    thresholdFontMin: 10,

    /* НАСТРОЙКА: общая высота органов управления в третьей колонке
       навигационной штуки — кнопок, поля выбора порога и поля поиска.
       Число одно на всех, и это принципиально. Своей высоты у них нет
       ничего общего: кнопка набирается из отбивок и межстрочного и
       выходила 34, поле выбора Safari рисует по-своему (около 28), а
       полю поиска лепра прописала ровно 25. В столбике из четырёх
       прямоугольников одной ширины разнобой в девять пикселей виден
       сразу, а подгонять два элемента под третий — значит мерить
       чужую высоту в рантайме на каждой странице и надеяться, что
       следующая версия Safari нарисует поле выбора так же.
       Тридцать выбраны как середина между нынешними крайностями: и
       кнопке есть куда вписать строку тринадцатым кеглем, и поле
       поиска не выглядит распухшим.
       На время ввода поле поиска из этого правила выходит: там кегль
       поднимается до девятнадцати и выше, и жёсткая высота обрезала бы
       буквы (см. lm-search_font). */
    uiRow: 30,

    /* НАСТРОЙКА: автоподгрузка ленты.
       Лепра догружает следующую страницу кнопкой «Ещё? Ещё!» в конце
       ленты. На телефоне это лишний тап в конце каждого захода: долистал,
       нашёл кнопку, попал, подождал.
       Жмём её сами, когда до неё осталось feedAhead экранов. Именно её
       собственную кнопку, а не ходим на сервер сами: лепра при этом сама
       решает, что запрашивать, сама вставляет посты в нужное место и сама
       прячет кнопку, когда лента кончилась. Знать её API не нужно вовсе,
       и обновление лепры этого не сломает.
       feedAutoMax — сколько раз подряд подгружать без участия человека.
       Предел нужен не из-за трафика, а из-за памяти: сотня постов с
       картинками и роликами на телефоне заметна, а долистать ленту до
       конца в лепре нельзя в принципе. Исчерпав его, кнопка остаётся на
       месте и работает как раньше — руками.
       feedAhead в экранах, а не в пикселях: «два экрана вперёд» означает
       одно и то же количество чтения на любом телефоне и при любом
       масштабе, а «полторы тысячи пикселей» — нет. */
    feedAuto: true,
    feedAhead: 5,
    /* Три, а не пять. Лепра отдаёт по 42 поста за раз: пять подгрузок —
       это 210 постов, четыре десятка живых плееров и три четверти мегабайта
       разметки в одной вкладке. На устройстве до этого доходило, и
       телефон грелся. Три подгрузки дают 126 постов — уже много, но в
       пределах разумного для телефона.
       Число это — рычаг, а не истина: если выгрузка уехавших роликов
       окажется достаточной, его можно будет вернуть. */
    feedAutoMax: 3,
    feedWait: 45000,

    /* ВРЕМЕННО: гасить траурное оформление лепры.
       В августе 2026-го, после смерти Йована Савовича, лепра включила на
       всех страницах серый фон — отдельной таблицей стилей, которую
       вставляет ПЕРЕД своей основной. Отличить её можно по первым же
       правилам: они начинаются с `html .l-content`, а собственный CSS
       лепры приставку `html` не использует нигде.
       Гасим целиком, а не перекрашиваем фон обратно: кроме фона там
       переопределены десятки цветов, рамок и градиентов, и выборочная
       отмена превратилась бы в гонку правил.
       Это настройка на время, а не решение: когда лепра оформление
       снимет, находить будет нечего, и строка просто перестанет
       срабатывать. */
    mournOff: true,

    /* НАСТРОЙКА: кегль девиза подлепры («Филиал дурдома…») и нижний
       предел, до которого его можно ужимать. Девиз стоит по центру и
       никогда не переносится, поэтому длинный подгоняется по ширине
       экрана: сначала берётся subsiteTitle, и если строка не влезла —
       кегль уменьшается шагом в полпункта, но не ниже subsiteTitleMin.
       Ниже одиннадцати надпись перестаёт читаться, и остаток честнее
       обрезать многоточием, чем делать вид, что он виден. */
    subsiteTitle: 19,
    subsiteTitleMin: 11,

    /* НАСТРОЙКА: ширина окна подтверждения покупки («окно Чарли») в
       процентах от ширины экрана. Окно стоит по центру, а картинка с
       доской и тунцом растянута ровно по нему — поэтому число управляет
       и размером картинки тоже, а полей по краям не возникает.
       100 — во всю ширину экрана. */
    charleyArt: 90,

    /* НАСТРОЙКА: блок «что это такое» на странице званий (/fraud/ranks/).
       Четыре абзаца объяснения аукциона стоят ПЕРЕД таблицей и на телефоне
       занимают целый экран: до первого звания приходится листать.
       Сворачиваем его в строку с уголком. true — раскрывать сразу,
       false — держать свёрнутым. Дальше состояние помнится по нажатию,
       настройка задаёт только первое посещение. */
    ranksAbout: false,

    /* НАСТРОЙКА: страница нового поста.
       newPostBody — высота поля ввода в пикселях. У лепры она прописана
       прямо в разметке (200) и рассчитана на десктоп, где справа от поля
       стоит колонка опций и пустоты не остаётся. На телефоне опции ушли
       вниз, и поле — единственное, ради чего страницу открыли.
       newPostCats — в сколько колонок раскладывать список категорий.
       Две — предел для 393 пикселей: подпись вроде «Книги / Дизайн»
       в половину ширины уже переносится, но читается. Одна — если у
       подлепры длинные названия и переносится каждая вторая. */
    newPostBody: 240,
    newPostCats: 2,

    /* НАСТРОЙКА: свёрнутая строка навигационной штуки.
       navRow — её высота в пикселях. Двадцать девять — то, что было до
       появления герба: подпись в 13 пунктов с межстрочным 1.3 плюс по
       шесть на отбивки. Число ведущее: отбивки считаются от него, и
       гнездо герба растёт внутрь строки, а не раздвигает её.
       navIcon — сторона гнезда под герб. Двадцать один влезает в строку
       без её роста (остаётся по четыре на отбивки). Больше — строка
       начнёт расти; при navIcon от 30 отбивки кончаются совсем. */
    navRow: 29,
    navIcon: 21,

    /* НАСТРОЙКА: прыгалки — навигация по комментариям справа по центру.
       Вид взят у лепры: треугольники и маска, нарисованные в её же
       координатах (сетка 40×40), поэтому jumpSize меняет и размер
       значка, и площадь нажатия разом.
       jumpSize — сторона значка. У лепры 40, отступ справа 10, значки
       стоят вплотную друг к другу.
       jumpRight — отступ от правого края экрана.
       jumpGap — просвет между значками. У лепры нуля; на телефоне
       пара пикселей уменьшает промахи, не сдвигая столбик заметно.
       jumpColor, jumpEye — заливка значков и глаз маски, ровно как
       у лепры. Светло-серый на десктопе лежит в пустом поле справа,
       а на телефоне попадает на текст: если плохо видно, темнее.
       jumpHalo — белый ореол под значком. У лепры его нет и не нужно:
       там под значками пусто. Тут они висят над текстом поста, и без
       ореола светло-серый контур теряется в строчках. false вернёт
       чистый исходный вид. */
    jumpSize: 40,
    jumpRight: 10,
    jumpGap: 2,
    jumpColor: 'rgb(210,211,212)',
    jumpEye: 'rgb(236,34,39)',
    jumpHalo: true,

    /* НАСТРОЙКА: диско — сокращённый просмотр ленты. Длинные
       посты показываются началом, остальное свёрнуто; разворачивается
       стыковкой стрелки с гнездом (см. раздел 8.5).
       disco — доступен ли режим вообще. false убирает и кнопку.
       discoKeep — доля высоты экрана в процентах, ниже которой пост не
       трогаем совсем: короткий пост сокращать нечего, а мигание среза
       на полутора строчках раздражает. Считается ВМЕСТЕ с подписью.
       discoCut — до какой доли экрана сокращаем длинный пост, тоже с
       подписью: подпись остаётся целой и непрозрачной, поэтому её
       высота вычитается из бюджета, а не добавляется к нему. Считается
       от замороженной высоты окна (см. discoVh), а она берётся с
       поднятой адресной строкой, — поэтому доля от настоящего экрана
       выходит немного меньше заданной.
       discoMin — нижний предел бюджета тела в пикселях. Нужен на случай
       высокой подписи (она переносится на три строки) и увеличенного
       масштаба страницы: без предела бюджет мог бы уйти в ноль или
       минус, и от поста осталась бы одна полоса прозрачности.
       discoText — сколько процентов бюджета тела отдавать тексту, если
       после текста в посте есть картинка. Остаток достаётся картинке.
       Если картинки нет — текст занимает весь бюджет; если пост
       начинается с картинки — текста нет и делить нечего.
       discoFade — высота полосы постепенной прозрачности в пикселях.
       Градиент идёт только сверху вниз, в бока не расходится.
       discoDots — рисовать ли своё многоточие после обрезанного текста.
       discoMedia / discoVideo — что делать с первой картинкой и с
       плеером, когда они не влезают в остаток бюджета:
         'crop' — показать сверху, низ уходит под срез
         'fit'  — уменьшить целиком, чтобы влезло
       У картинки по умолчанию 'crop': уменьшенная вдвое картинка врёт о
       масштабе, а обрезанная честно говорит «дальше есть ещё». У видео
       'fit': обрезанный кадр играть неудобно, а вертикальный ролик,
       уменьшенный по высоте, виден целиком.
       discoFirst — сколько постов в начале ленты не сокращать. Ноль:
       поначалу первый пост оставляли целым, чтобы стыковка не
       приходилась на экран с шапкой, — но на устройстве вышло иначе.
       Целый пост в начале сбивает ритм ленты и заставляет листать ровно
       там, где человек только начал смотреть; а стыковаться на первом
       экране ничто не мешает.
       discoGain — сколько процентов высоты экрана пост обязан отдать,
       чтобы срез вообще имел смысл. Проверка идёт ПОСЛЕ среза, по
       настоящему замеру «было — стало», и если выгода мала, срез
       откатывается: полоса прозрачности с гнездом на посте, от которого
       спрятана пара строк, только мешает. Отбор по discoKeep один с
       этим не справляется — он смотрит на рост поста, а не на то,
       сколько удалось спрятать, а это разные вещи: пост из одной
       высокой картинки длинный, но прятать в нём нечего.
       Вдвоём числа дают такое правило: режем то, что выше discoKeep И
       отдаёт не меньше discoGain. При экране 735 это примерно посты
       выше 480 пикселей, то есть в две трети экрана и длиннее.
       discoAbove — сокращать ли посты, которые остались ВЫШЕ экрана.
       Прокрутка при этом возвращается ровно на ту величину, на которую
       пост укоротился, и видимое остаётся на месте. false оставит
       нетронутым всё, мимо чего человек успел пролистать. */
    disco: true,
    discoKeep: 50,
    discoCut: 55,
    discoMin: 120,
    discoText: 45,
    discoFade: 55,
    discoDots: true, /*по возможности сделать чтобы многоточие ставилось БЕЗ переноса его на новую строку*/
    discoMedia: 'crop',
    discoVideo: 'fit',
    discoFirst: 0,
    discoGain: 20,
    discoAbove: true,

    /* НАСТРОЙКА: гнездо под стрелку у полосы прозрачности. Размер и
       форма — те же, что у стрелки прыгалок (CFG.jumpSize и её
       треугольник), цвет обратный: стрелка светлая, гнездо тёмное.
       discoNest — цвет гнезда. Пустая строка означает «взять обратный
       к jumpColor»: тогда перекраска прыгалок тянет за собой и гнездо,
       и подбирать пару вручную не приходится.
       discoGlow — цвет ореола вокруг гнезда. */
    discoNest: '',
    discoGlow: 'rgba(255,214,0,.85)',

    /* НАСТРОЙКА: scroll-connect — стыковка прокруткой.
       Пока полоса прозрачности краткопоста далеко от середины экрана,
       на экране нет ничего. По мере приближения одновременно проявляются
       стрелка у левого края и гнездо у полосы; яркость обоих растёт по
       мере сближения. Совместить их прокруткой и подержать — пост
       раскрывается.
       discoZone — с какого расстояния от середины экрана (в пикселях)
       начинается проявление. Оно же управляет полосой, внутри которой
       скрипт вообще следит за положением: снаружи не работает ничего,
       ни обработчиков, ни замеров.
       discoDock — допуск стыковки в пикселях. Меньше — точнее и
       труднее попасть, особенно на инерции.
       discoHold — сколько миллисекунд держать совмещённым.
       discoArm — требовать ли, чтобы гнездо вошло в допуск ДВИЖЕНИЕМ.
       Защита от случайного срабатывания: без неё пост раскрывался бы
       сам, если человек остановился почитать ровно в этом месте.
       discoSpin — сколько миллисекунд идёт оборот при стыковке.
       discoTurns — сколько оборотов: 1 — на 360 с паузой на 180,
       2 — на 720 с паузой на 360. */
    discoZone: 110,
    discoCurve: 1.5,
    discoDock: 17,
    discoHold: 700,
    discoArm: true,
    discoSpin: 600,
    discoTurns: 1,

    /* НАСТРОЙКА: форма ответа в комментариях.
       replyBleed — выводить ли всплывшую форму из лесенки веток. Лепра
       вставляет её внутрь комментария, то есть на его отступе: ответ на
       комментарий шестого уровня получал бы поле на 78 пикселей уже
       нижней формы. true отматывает отступ назад отрицательным полем, и
       форма встаёт во всю ширину колонки независимо от уровня ветки;
       false оставит её по левому краю комментария.
       replyScroll — подкручивать ли страницу по тапу «ответить». Форма
       появляется под комментарием, то есть где-то посреди экрана, а
       снизу поднимается клавиатура: на поле ввода остаётся полоска в
       пару строк. Подкрутка ставит верх формы под верхнюю кромку, и всё
       место до клавиатуры достаётся полю.
       replyTop — на сколько пикселей ниже кромки ставить форму. */
    replyBleed: true,
    replyScroll: true,
    replyTop: 36,

    /* НАСТРОЙКА: гертруда в развёрнутой штуке — ширина картинки в
       пикселях. Больше трети ширины блока она всё равно не займёт:
       колонка её обрежет по своему краю. */
    gertruda: 118,

    /* НАСТРОЙКА: гертруда в тёмной теме. Гертруды бывают с прозрачным
       рваным краем и с тем же краем, нарисованным по сплошному листу.
       Вторым обратная инверсия возвращает лист вместе с рисунком, и на
       чёрной странице загорается белый прямоугольник.
         'auto'   — отдать инверсии, только если кайму снять не вышло
         'invert' — всегда: край чистый, рисунок негативом
         'keep'   — никогда: подлинные цвета, у непрозрачных белый лист
       Пока кайма снимается (gertrudaCut), эта настройка почти не нужна:
       у обрезанной картинки край и так прозрачный в обеих темах. */
    gertrudaDark: 'auto',

    /* НАСТРОЙКА: не переворачивать эмодзи в тёмной теме. Эмодзи у лепры
       не картинки, а текст, и общая инверсия красит их наравне с
       буквами: жёлтое лицо становится синим. Заворачиваем найденное в
       свой узел и возвращаем цвета обратной инверсией — см. раздел 6.5.
       false вернёт прежний вид, когда эмодзи переворачивались вместе со
       страницей. Обход при этом отключается целиком, вместе с
       обёртыванием: смысла заворачивать без плёнки нет. */
    emojiKeep: true,

    /* НАСТРОЙКА: ссылка на архив в левой колонке навигационной штуки.
       Архив живёт по адресу /archive/, и входа в него из шапки лепры
       нет вовсе — только из подвала, до которого на телефоне листать
       всю ленту. Ставим ссылку последней в столбике: нужна она редко, и
       место в начале ей ни к чему.
       Настройка, а не всегда: столбик тут короткий, и лишняя строка в
       нём заметна. */
    navArchive: true,

    /* НАСТРОЙКА: кегль полей ввода в формах комментария, с поправкой на
       масштаб страницы. Числа те же и по той же причине, что у поля
       поиска (см. searchFocusFont): шестнадцать — это требование к
       ТОМУ, ЧТО ВИДНО НА ЭКРАНЕ, а не к записи в стилях. При масштабе
       страницы 90% шестнадцатый кегль доходит до глаза четырнадцатым с
       небольшим, Safari считает поле мелким и приближает страницу к
       нему — а окно раскладки при этом шире экрана, и правый край формы
       вместе с крестиком уезжает за кромку.
       Настоящий кегль считается делением на масштаб (formFontVar) и
       кладётся в переменную --lm-form-font. При обычном стопроцентном
       масштабе получается ровно шестнадцать.
       Держим своей парой чисел, а не занимаем поисковые: поле поиска
       поднимает кегль только на время касания и возвращает обратно, а
       форма комментария живёт с ним постоянно — это разные повадки, и
       однажды их захочется настроить порознь.
       formFontMax — потолок на случай сильно уменьшенной страницы: при
       50% деление дало бы тридцать два. */
    formFont: 16,
    formFontMax: 22,

    /* НАСТРОЙКА: сворачивать форму нового комментария в конце треда.
       Лепра показывает её раскрытой; на телефоне это поле в двести
       пикселей с панелью кнопок в конце каждого треда, через которое
       приходится листать. Свёрнутая оставляет надпись «Я, пожалуй,
       напишу комментарий», по ней же и разворачивается.
       false вернёт леприно поведение — форма сразу раскрыта. */
    foldNewComment: true,

    /* НАСТРОЙКА: держать место на странице при возврате «назад».
         'auto' — только там, где браузер сам не справляется (Firefox)
         'on'   — всегда, для проверки
         'off'  — никогда, заводское поведение браузера
       Разбор — в разделе 9.5. На айфоне при 'auto' раздел молчит
       целиком, включая запись в хранилище. */
    backRestore: 'auto',

    /* НАСТРОЙКА: снимать ли у гертруды сплошную кайму. Картинки приходят
       непрозрачными: рваный край нарисован по сплошному полю, и оно —
       часть файла. Заливкой от краёв это поле вычитается и заменяется
       настоящей прозрачностью. Заливка, а не отбор по цвету: так не
       выбьет светлые пятна внутри рисунка — снимается только то, что
       связано с краем. */
    gertrudaCut: true,

    /* НАСТРОЙКА: пынь. В десктопе по нажатию на колокольчик всплывает
       окошко со списком, а на страницу уведомлений ведёт ссылка в его
       низу. На телефоне окошко не открывалось, и тап уходил прямо на
       страницу. pynPopup: true возвращает окошко — своё, но с лепровским
       содержимым; false оставляет прежний переход по ссылке.
       pynHeight — высота окошка в процентах экрана.
       pynFresh — сколько секунд считать загруженный список свежим:
       повторное открытие в эти секунды рисуется сразу, без загрузки.
       pynWait — сколько секунд ждать, пока лента соберётся в скрытом
       окне; дальше окно закрывается и человеку пишут, что не вышло.
       pynShade — насколько процентов затемнить страницу под окном.
       Лепра своё окно ничем не затемняет, но оно у неё маленькое и висит
       под колокольчиком; наше во всю ширину, и без подложки по краям
       торчит страница. Ноль уберёт затемнение совсем — закрывать тапом
       мимо окна это не мешает. */
    pynPopup: true,
    /* pynQuoteFont — кегль исходного комментария, раскрываемого шевроном.
       Шрифт у него Verdana, как у текста ответа рядом; при равном кегле
       Verdana рисуется крупнее Arial, поэтому число здесь и число в
       соседних правилах на Arial напрямую не сравниваются. */
    pynQuoteFont: 14,
    pynHeight: 78,
    pynFresh: 60,
    pynWait: 12,

    /* НАСТРОЙКА: слежение за пынями. Пока вкладка открыта и на переднем
       плане, скрипт спрашивает у лепры число непрочитанных и показывает
       плашку внизу, когда оно выросло. Спрашивается только счётчик:
       он ничего не отмечает прочитанным, в отличие от самой ленты, и
       весит несколько десятков байт.
       Работает только в открытой вкладке — фоновую вкладку телефон
       усыпляет, и уведомлений на экран блокировки отсюда не будет.
       pynWatch: false выключает слежение целиком.
       pynEvery — как часто спрашивать, секунд.
       pynToast — сколько секунд плашка висит, если её не трогать. */
    pynWatch: true,
    pynEvery: 60,
    pynToast: 9,

    /* Чем сообщать о новой пыни: 'push' — только плашка, 'ding' — только
       звук, 'both' — и то и другое.
       Звук синтезируется на месте, файла нет и не будет: скрипт
       принципиально не ходит на сторонние адреса, а тащить звук в
       разметку строкой — это десятки килобайт в каждой вкладке ради
       двух нот.
       Ноты именно две, короткая пара вверх: одиночный писк на телефоне
       теряется среди системных, а восходящая пара читается как «что-то
       пришло» и не похожа ни на будильник, ни на ошибку.
       ВАЖНО про iOS: звук не проиграется, пока на странице не было ни
       одного касания — Safari запрещает воспроизведение без участия
       человека. Разблокируем на первом же касании чего угодно (см.
       dingArm). Если человек открыл вкладку и не трогал её, первый
       дзинь пропадёт; плашка при этом покажется как обычно. */
    /* 'none' — не сообщать никак. Слежение при этом не выключается: оно
       заодно обновляет цифру у колокольчика, а она нужна и молчунам. */
    pynSound: 'push',

    /* Громкость дзиня, от нуля до единицы. Треть — не робость, а
       расчёт: звук короткий и высокий, на телефонном динамике он и на
       трети слышен отчётливо, а на полной громкости в тихой комнате
       воспринимается как сигнал тревоги. */
    dingVolume: 0.35,

    /* Где показывать плашку: 'bottom' или 'top'. Снизу палец ближе, но
       там же у Safari своя панель; сверху плашка спорит с шапкой и
       навигационной штукой. Правильного ответа нет — поэтому настройка. */
    pynToastSide: 'bottom',

    /* Как часто спрашивать о новом, пока окно пыни ОТКРЫТО, секунд.
       Обычные шестьдесят там слишком медленны: человек смотрит в ленту
       уведомлений именно тогда, когда ждёт ответа, и минута ожидания
       перед появлением строки — это не «реальное время».
       Пятнадцать можно себе позволить только потому, что спрашивается
       счётчик — несколько десятков байт и никаких отметок о прочтении.
       Тяжёлая перезагрузка ленты случается лишь тогда, когда счётчик
       вырос, то есть ровно столько раз, сколько пришло новых пыней. */
    pynLiveEvery: 15,

    /* НАСТРОЙКА: помнить свои голоса самим.
       Нужна потому, что поле user_vote в данных уведомлений отстаёт: в
       отчёте с устройства у комментария, за который голос отдан сегодня
       плюсом, лепра отдавала прежний минус, а у остальных сегодняшних
       голосов поля не было вовсе — и это не зависело от того, как голос
       отправлен, прямо или через окно. Своя память — единственный
       способ показать только что отданный голос нажатым.
       Проверено насквозь, чтобы не возвращаться:
         — кэш ни при чём: свой запрос с cache: 'no-store' даёт то же;
         — поле разбирается верно: у комментариев подлепр читается;
         — лёгкого источника у лепры нет. Единственный, где голос
           заполнен, — /api/posts/<id>/comments/, но per_page она
           игнорирует и отдаёт весь тред: на посте в 2804 комментария
           это 3,3 мегабайта ради одной цифры;
         — спросить ленту у подлепры (вдруг для неё главная «чужая» и
           поле заполнится) — не помогло, знает ровно столько же.
       voteMemory: false выключает память целиком: тогда подсветка идёт
       только по данным лепры, и голоса на главную не показываются
       вовсе. */
    voteMemory: true,

    /* НАСТРОЙКА: опытные возможности окна пыни.
       Голосование и ответ ходят через невидимое окно на нужном домене и
       шлют запросы от имени человека. Всё проверено, но это единственное
       место, где скрипт что-то ОТПРАВЛЯЕТ, а не только читает, — и
       человек вправе выключить это, не отказываясь от самого окна.
       По умолчанию выключено, и это осознанно: отправку от чужого имени
       нельзя включать за человека. Пусть он сам решит, что доверяет
       скрипту голосовать и отвечать своей рукой. */
    pynVote: false,
    pynReply: false,
    /* На сколько пикселей поднять плашку над низом экрана: внизу у Safari
       своя панель, и плашка вплотную к краю попадает под неё. */
    pynToastUp: 34,
    /* Предельная ширина плашки. Во всю ширину экрана она выглядит полосой
       поперёк страницы, а не всплывшим сообщением. */
    pynToastWide: 344,
    /* Писать в плашке, кто и в каком посте ответил. Для этого нужен ещё
       один запрос — за одним последним уведомлением, около четырёх с
       половиной килобайт. Скрипт один раз проверит, не гасит ли этот
       запрос счётчик, и если гасит — сам перейдёт на короткий текст. */
    pynText: true,
    /* Отмечать прочитанным то, что показано: уведомления в открытом окне
       пыни и на странице «все уведомления». Лепра сама этого не делает —
       у неё для этого отдельная кнопка, — но показанное сообщение по сути
       уже прочитано. Отмечаются только видимые, поимённо: в окне их
       двадцать последних, а непрочитанных бывает больше, и гасить то,
       чего человек не видел, мы не вправе. */
    pynAutoRead: true,
    pynShade: 60,

    /* НАСТРОЙКА: красить панели Safari — адресную строку сверху и полосу
       кнопок снизу — в цвет страницы. Сам Safari угадывает этот цвет по
       содержимому у верхней и нижней кромок экрана и пересчитывает его
       редко: любое затемнение поверх страницы (подложка окна покупки
       перекрывает обе кромки) оставляет панели чёрными и после закрытия
       окна, до следующей прокрутки. Явный цвет снимает угадывание.
       false — не вмешиваться в оформление браузера. */
    themeColor: true,

    /* Потолок на разовый обход DOM. Лепра тратит около 150 элементов
       на комментарий, поэтому тред на тысячу комментариев — это 150 тысяч
       узлов. Обходить их целиком незачем: вёрстка внутри комментариев
       однотипна и уже покрыта правилами CSS. */
    scanBudget: 6000,

    /* Отладочная панель: три тапа по левому верхнему углу или #lmdebug
       в адресе. Перед раздачей скрипта другим людям можно выключить. */
    debug: true,

    /* НАСТРОЙКА: светлые карточки на притемнённой странице вместо
       обратного. Заводское — как у лепры: страница белая, карточки чуть
       темнее её. Обратный набор кому-то читается легче: белое поле
       текста на сером фоне привычно по книгам и почте. */
    cardsLift: false,

    /* НАСТРОЙКА: навигационная штука остаётся на экране при прокрутке,
       под липкой плашкой вокатива. Свёрнутая полоска сама служит
       разделителем; развёрнутая при прокрутке сворачивается, чтобы не
       занимать экран, — даже если закреплена гвоздиком (гвоздик про то,
       раскрыта ли она при ЗАГРУЗКЕ страницы, и это разные вещи).
       Выключено по умолчанию: постоянная полоска — вкус на любителя, а
       без неё внизу плашки просто тонкая черта. */
    navSticky: false,

    /* НАСТРОЙКА: попап настроек по тапу в середину гертруды. Выключатель
       есть на случай, если тап однажды начнёт мешать чему-то другому в
       этом месте: убрать один флаг проще, чем выкорчёвывать обработчик. */
    settings: true,

    /* НАСТРОЙКА: какие разделы показывать в отчёте. Разделы копились под
       задачи, и почти все свои задачи пережили: подписи поста и
       комментария, шапка, поиск, профиль, фильтры — всё это давно
       сделано, а места в отчёте занимает столько, что нужное в нём
       приходится искать. Поэтому не удаляем, а гасим: понадобится —
       вернуть можно одним словом, и код, который умеет мерить нужное,
       никуда не делся.
       Отдельно про «наложения»: раздел честно находит пересечения, но
       на ленте с сокращёнными постами их десятки, и все ложные —
       тело поста считается пересекающим свою же подпись и гнездо. До
       поры, пока не понадобится снова, он только зашумляет отчёт.
       «Сетевые запросы» гасим по той же причине: они писались под
       разбор пыни, а показывают в основном яндексовую статистику. Если
       снова понадобится смотреть, куда и с какой задержкой ходит
       страница, — включить обратно.
       Журнал ошибок выключателя не имеет: он и есть первое, ради чего
       отчёт открывают. */
    report: {
      overflow: true,        /* вылезает за экран */
      prefs: true,           /* общие настройки: значение и откуда взято */
      votes: true,           /* голосовалки: замеры кнопок во всех местах */
      network: true,         /* сетевые запросы и перехваченные заголовки */
      pyn: true,             /* окно пыни, звук, голосование */
      floats: false,         /* плавающие колонки */
      overlaps: false,       /* наложения */
      media: false,          /* видео и плееры */
      disco: false,          /* диско */
      postFooter: false,     /* подпись поста */
      commentFooter: false,  /* подпись комментария */
      header: false,         /* шапка: приветствие */
      search: false,         /* поиск и динамический список */
      profile: false,        /* профиль */
      filters: false,        /* панель фильтров */
      layers: false,         /* слои поверх страницы */
      threads: false         /* лесенка комментариев */
    }
  };


  /* ============================================================
     ОБЩИЕ НАСТРОЙКИ НА ВСЕ ПОДДОМЕНЫ
     ============================================================

     localStorage у каждого поддомена свой. Подлепра — отдельный
     источник, и настройка, выставленная на главной, до неё не доходила:
     тёмная тема, режим уплотнения, scroll-connect и гвоздик навштуки
     жили в стольких экземплярах, сколько подлепр человек посетил.
     Правило простое: нажал — везде так.

     Общее хранилище у поддоменов ровно одно — кука на домене второго
     уровня. Тот же приём уже применён к токену для /ajax/ (см. раздел
     4.3), здесь он просто обобщён.

     Устройство. На каждый общий ключ своя кука с тем же именем.
     Одной общей записью было бы меньше возни, но тогда две вкладки на
     разных поддоменах, меняющие разные настройки, затирали бы друг
     другу всё разом: кука читается целиком и пишется целиком. По ключу
     на куку конфликт сужается до одной настройки, а её человек в двух
     вкладках одновременно не крутит.

     localStorage остаётся зеркалом, а не запасным вариантом: читается
     он только тогда, когда куки нет. Нужен он на случай, если куки
     запрещены — тогда всё работает как раньше, в пределах поддомена.

     Перенос со старого. Кука появляется не сразу: до первой записи её
     нет ни на одном поддомене, а localStorage со старыми значениями
     есть у каждого. Поэтому при первом чтении ключа, у которого куки
     ещё нет, локальное значение публикуется в куку. Побеждает та
     страница, которая откроется первой после обновления скрипта; дальше
     всё едино. Точнее решить нельзя — времени последней правки в
     localStorage не хранится, а гадать по значениям хуже, чем взять
     первое попавшееся и больше к вопросу не возвращаться.

     Чего здесь НЕТ и почему. Голоса (lm-votes) и токены — не настройки,
     а данные сессии; они уже помечены номером гражданина и живут по
     своим правилам. Кэш навбара (lm-blogs, lm-veg, lm-gertruda) —
     тоже не настройка: это память о том, что видели на ЭТОЙ странице, и
     общей ей быть незачем. Пенсне подлепры (lm-blogs_pince) осмысленно
     только на подлепре и у каждой своё. */

  var SHARED_KEYS = ['lm-dark', 'lm-cfg', 'lm-disco', 'lm-sc', 'lm-navthing'];

  /* Домен второго уровня: leprosorium.ru и для главной, и для любой
     подлепры. Кука с таким domain видна всем поддоменам сразу. */
  function baseDomain() {
    var parts = String(location.hostname || '').split('.');
    return parts.length > 2 ? parts.slice(-2).join('.') : location.hostname;
  }

  /* Год: настройка не должна пропадать оттого, что человек не заходил
     месяц. Каждая запись срок продлевает. */
  var PREF_AGE = 31536000;

  function prefCookieRead(key) {
    var raw;
    try {
      var m = new RegExp('(?:^|; )' +
        key.replace(/[-.]/g, '\\$&') + '=([^;]*)').exec(document.cookie || '');
      raw = m ? decodeURIComponent(m[1]) : null;
    } catch (e) { return null; }
    return raw;
  }

  function prefCookieWrite(key, value) {
    try {
      document.cookie = key + '=' + encodeURIComponent(value) +
        '; domain=.' + baseDomain() + '; path=/; max-age=' + PREF_AGE +
        '; samesite=lax';
    } catch (e) { /* куки запрещены — остаётся зеркало в localStorage */ }
  }

  /* Прочитать общую настройку. Возвращает null, если её нет нигде, —
     ровно как localStorage.getItem, чтобы вызывающий код не переписывать.

     Зеркало по ходу чтения приводится в согласие с кукой. Это не
     аккуратизм: без него получается воскрешение отменённой настройки.
     Человек меняет что-то на главной — на подлепре в зеркале остаётся
     прежнее значение. Пока кука жива, его никто не спрашивает; но стоит
     ей истечь или быть вычищенной, и подлепра прочитает своё старое
     зеркало И ОПУБЛИКУЕТ его в куку — то есть вернёт всем отменённую
     настройку. Сверка при чтении закрывает это раз и навсегда. Запись
     идёт только при расхождении, то есть в норме один раз за страницу. */
  function prefGet(key) {
    if (SHARED_KEYS.indexOf(key) >= 0) {
      var c = prefCookieRead(key);
      if (c !== null) {
        var mirror = null;
        try { mirror = localStorage.getItem(key); } catch (e) { return c; }
        if (mirror !== c) { try { localStorage.setItem(key, c); } catch (e) {} }
        return c;
      }
    }
    var v = null;
    try { v = localStorage.getItem(key); } catch (e) { return null; }
    /* Куки нет, а локальное значение есть — публикуем его на общий
       домен. Это и есть перенос со старого; делается один раз, дальше
       читаться будет уже кука. */
    if (v !== null && SHARED_KEYS.indexOf(key) >= 0) prefCookieWrite(key, v);
    return v;
  }

  function prefSet(key, value) {
    value = String(value);
    if (SHARED_KEYS.indexOf(key) >= 0) prefCookieWrite(key, value);
    try { localStorage.setItem(key, value); } catch (e) {}
  }

  /* Снятие настройки — это ПУСТАЯ кука, а не отсутствие куки, и разница
     принципиальная. Убранная кука означает «никто ещё ничего не решал»,
     и тогда prefGet честно возьмёт зеркало соседнего поддомена и вернёт
     всем отменённое значение — то самое воскрешение. Пустая кука
     означает «решено: заводское», и её видят все.
     Пустую строку все читатели понимают правильно: tuneLoad выходит по
     `if (!raw)`, parseInt('') даёт NaN и режим уплотнения ноль, а
     сравнения с '1' у остальных дают false. */
  function prefDel(key) {
    if (SHARED_KEYS.indexOf(key) >= 0) prefCookieWrite(key, '');
    try { localStorage.removeItem(key); } catch (e) {}
  }


  /* ============================================================
     СОХРАНЁННЫЕ НАСТРОЙКИ
     ============================================================

     Часть чисел из CFG человек крутит сам — попапом настроек. Хранятся
     они в localStorage одной записью и вливаются в CFG ЗДЕСЬ, до всего
     остального. Место выбрано не случайно: таблица стилей ниже собрана
     шаблонной строкой, и числа из CFG подставлены прямо в правила. Влить
     сохранённое позже — значит собрать CSS по умолчаниям, а работать по
     настройкам, то есть развести разметку со стилями.

     Отдельно про то, чего здесь нет. Числа, которые попап меняет НА ЛЕТУ
     (с живым предпросмотром), в правилах не подставляются, а вынесены в
     переменные CSS: подставленное шаблоном значение после сборки строки
     уже не изменить, а переменную можно переписать в любой момент. Такие
     помечены в таблице признаком cssVar.

     Таблица — не просто список разрешённых ключей. Она же задаёт пределы
     ползунков и значения по умолчанию для кнопки «сбросить», и держать
     их в одном месте с самой настройкой честнее, чем разложить по коду
     попапа: там их пришлось бы согласовывать вручную. */

  var TUNE = {
    /* до какой доли высоты экрана сокращать пост */
    discoCut:     { min: 35, max: 75, step: 1 },
    /* допуск стыковки scroll-connect в пикселях */
    discoDock:    { min: 6,  max: 30, step: 1 },
    /* до какой доли высоты экрана сокращать комментарий */
    commentCut:   { min: 25, max: 70, step: 1 },
    /* потолок высоты медиа, доля высоты экрана */
    mediaCut:     { min: 30, max: 100, step: 1, cssVar: '--lm-media-max', unit: 'vh' },
    /* Прямая ссылка под роликом. bool здесь — не значение по умолчанию,
       а признак типа: заводское значение берётся из CFG, как у всех
       остальных (см. TUNE_DEF). */
    videoLink:    { bool: true },
    navSticky:    { bool: true },
    /* Не bool, хотя значения те же два: попап показывает эту настройку
       не выключателем, а выбором из двух слов («Карточки» / «Фон»), а
       setChoice берёт варианты именно из list. Порядок в списке — это
       порядок кнопок в попапе, менять его нельзя, не поменяв подписи.
       Сохранённое от прежних версий переживает: список содержит те же
       true и false, и tuneLoad их находит. */
    cardsLift:    { list: [false, true] },
    navArchive:   { bool: true },
    /* чем сообщать о новой пыни */
    pynSound:     { list: ['push', 'ding', 'both', 'none'] },
    /* где показывать плашку */
    pynToastSide: { list: ['bottom', 'top'] },
    /* опытные возможности окна пыни */
    pynVote:      { bool: true },
    pynReply:     { bool: true }
  };

  /* Значения по умолчанию снимаем ДО слияния — иначе «сбросить» вернуло
     бы не заводское число, а то, что человек сохранил в прошлый раз. */
  var TUNE_DEF = {};
  (function () {
    for (var k in TUNE) if (TUNE.hasOwnProperty(k)) TUNE_DEF[k] = CFG[k];
  })();

  var TUNE_KEY = 'lm-cfg';

  /* Читаем с оглядкой: в хранилище может лежать что угодно — обрывок
     чужой записи, значение от старой версии скрипта, число за пределами
     ползунка. Каждый ключ проверяется отдельно, и негодный молча
     пропускается: одна испорченная настройка не должна отменять
     остальные и уж тем более ронять скрипт на первой строке. */
  function tuneLoad() {
    var raw = prefGet(TUNE_KEY);
    if (!raw) return;
    var data;
    try { data = JSON.parse(raw); } catch (e) { return; }
    if (!data || typeof data !== 'object') return;
    for (var k in TUNE) {
      if (!TUNE.hasOwnProperty(k) || !data.hasOwnProperty(k)) continue;
      var v = data[k], t = TUNE[k];
      if (typeof t.min === 'number') {
        v = parseFloat(v);
        if (!isFinite(v)) continue;
        v = Math.min(t.max, Math.max(t.min, v));
      } else if (t.list) {
        if (t.list.indexOf(v) < 0) continue;
      } else if (t.bool) {
        v = !!v;
      } else continue;
      CFG[k] = v;
    }
  }

  /* Пишем только отличия от заводских: так запись остаётся короткой, а
     смена значения по умолчанию в новой версии скрипта доходит до тех,
     кто эту настройку не трогал. */
  function tuneSave() {
    var out = {};
    for (var k in TUNE)
      if (TUNE.hasOwnProperty(k) && CFG[k] !== TUNE_DEF[k]) out[k] = CFG[k];
    /* Пусто — не «нечего писать», а «всё заводское», и запись надо
       СНЯТЬ: иначе сброшенная настройка вернулась бы с прошлой записи.
       Снимать приходится и с куки, и с зеркала — этим и занят prefDel. */
    if (Object.keys(out).length) prefSet(TUNE_KEY, JSON.stringify(out));
    else prefDel(TUNE_KEY);
  }

  /* Задать значение и сохранить. Возвращает то, что легло в CFG после
     обрезки по пределам, — попапу это нужно, чтобы ползунок не убегал
     за край при вводе с краю. */
  function tuneSet(key, value) {
    var t = TUNE[key];
    if (!t) return undefined;
    if (typeof t.min === 'number') {
      value = parseFloat(value);
      if (!isFinite(value)) return CFG[key];
      value = Math.min(t.max, Math.max(t.min, value));
    } else if (t.list) {
      if (t.list.indexOf(value) < 0) return CFG[key];
    } else if (t.bool) {
      value = !!value;
    }
    CFG[key] = value;
    tuneSave();
    tuneVar(key);
    /* Звук взводится один раз при загрузке — и только если он тогда был
       включён. Человек, включивший его в попапе, до перезагрузки
       оставался без звука: слушать первое касание было уже некому.
       Нажатие в попапе само и есть касание, поэтому здесь можно не
       ждать следующего, а сразу создать контекст. */
    if (key === 'pynSound' && (value === 'ding' || value === 'both')) {
      guard('dingArm', dingArm)();
      guard('dingWake', dingWake)();
    }
    return value;
  }

  /* Переписать переменную CSS для настроек с признаком cssVar. Значение
     из шаблонной строки после сборки уже не изменить, а переменную —
     можно в любой момент, и правило подхватит её тем же кадром. На этом
     и держится живой предпросмотр в попапе настроек: ползунок двигается,
     картинка на схемофоне и медиа на самой странице меняются вместе. */
  function tuneVar(key) {
    var t = TUNE[key];
    if (!t || !t.cssVar) return;
    document.documentElement.style.setProperty(
      t.cssVar, CFG[key] + (t.unit || ''));
  }

  function tuneReset(key) {
    if (!TUNE[key]) return undefined;
    CFG[key] = TUNE_DEF[key];
    tuneSave();
    tuneVar(key);
    return CFG[key];
  }

  tuneLoad();

  /* Какой из двух наборов тонов в ходу — классом на html. Оба лежат в
     таблице стилей, переключение мгновенное и обхода страницы не
     требует. Класс ставится здесь, до отрисовки: иначе страница мигнёт
     заводским набором и только потом перекрасится. */
  function applyCards() {
    var el = document.documentElement;
    if (el) el.classList.toggle('lm-cards2', !!CFG.cardsLift);
  }

  applyCards();

  /* Липкость навштуки — тоже классом на html, до отрисовки. */
  function applyNavStick() {
    var el = document.documentElement;
    if (el) el.classList.toggle('lm-navstick', !!CFG.navSticky);
  }

  applyNavStick();

  /* Ссылка на архив — тоже классом на html, а не пересборкой столбика.
     Узел строится всегда и всегда лежит на своём месте, видимостью
     заведует класс. Так переключатель в попапе действует тем же кадром,
     а не «со следующей страницы»; строить и выдёргивать узел на каждое
     нажатие значило бы держать две ветки кода вместо одной. */
  function applyNavArch() {
    var el = document.documentElement;
    if (el) el.classList.toggle('lm-arch', !!CFG.navArchive);
  }

  applyNavArch();




  /* ============================================================
     VIEWPORT — самое первое действие
     Ставится до любых проверок: если ниже что-то упадёт, страница
     всё равно останется читаемой, а не десктопной.
     ============================================================ */

  function setViewport() {
    try {
      var head = document.head || document.documentElement;
      var m = document.querySelector('meta[name="viewport"]');
      if (!m) {
        m = document.createElement('meta');
        m.name = 'viewport';
        head.appendChild(m);
      }
      m.content = 'width=device-width, initial-scale=1, viewport-fit=cover';
    } catch (e) {}
  }

  setViewport();
  document.addEventListener('DOMContentLoaded', setViewport);

  /* Ширину экрана берём после viewport и с запасными источниками:
     до установки метатега Safari отдаёт виртуальные 980px. */
  function screenWidth() {
    var candidates = [
      window.screen && window.screen.width,
      document.documentElement && document.documentElement.clientWidth,
      window.innerWidth
    ].filter(function (x) { return typeof x === 'number' && x > 0; });
    return candidates.length ? Math.min.apply(Math, candidates) : 400;
  }

  /* На широком экране адаптация не нужна. */
  if (screenWidth() > CFG.maxWidth) return;

  /* ============================================================
     СЛУЖЕБНОЕ
     ============================================================ */

  var LOG = [];

  function note(msg) {
    if (!CFG.debug) return;
    LOG.push(msg);
    if (LOG.length > 25) LOG.shift();
  }

  /* Обёртка вокруг проходов: одна упавшая функция не должна останавливать
     остальные, а сообщение об ошибке попадает в отчёт вместо тишины. */
  function guard(where, fn) {
    return function () {
      try {
        return fn.apply(this, arguments);
      } catch (e) {
        note('ОШИБКА в ' + where + ': ' + ((e && e.message) || e));
      }
    };
  }

  function sliceOf(nodes) { return Array.prototype.slice.call(nodes); }

  /* ------------------------------------------------------------
     ПЕРЕХВАТ ЗАПРОСОВ (только для отчёта)
     Хронология ресурсов показывает адрес, но не показывает ни метода,
     ни заголовков. Для пыни этого не хватило: по адресу из хронологии
     сервер отвечает 404 даже на заведомо рабочий /api/replacements/,
     значит лепра зовёт его как-то иначе. Подмена XMLHttpRequest и fetch
     это покажет — если скрипт живёт в том же окружении, что и лепра.
     Если ничего не перехватится, а хронология запросы показывает, —
     значит окружения разные, и это тоже ответ.
     Ставится до скриптов лепры: скрипт работает с document-start.
     ------------------------------------------------------------ */

  var NET = [];

  /* Шаблоны из /static/views/ и счётчики Яндекса лепра дёргает десятками,
     и они уже видны в хронологии ресурсов. Тут нужна суть — обращения к
     её API: чем именно она их зовёт и что при этом гасит счётчик. */
  function netSkip(url) {
    var u = String(url || '');
    return u.indexOf('/static/') >= 0 ||
           u.indexOf('mc.yandex') >= 0 ||
           u.indexOf('google') >= 0;
  }

  var NET_SEEN = 0;      /* сколько запросов прошло через хук вообще */
  var NET_NOISE = 0;     /* сколько из них отсеяно как шум */

  function netLog(url, line) {
    NET_SEEN++;
    if (netSkip(url)) { NET_NOISE++; return; }
    if (NET.length > 60) return;
    NET.push(line);
  }

  /* Тело запроса нужно целиком: если счётчик гасит POST, важно не только
     то, куда он идёт, но и что в нём. */
  function netBody(b) {
    try {
      if (!b) return '';
      if (typeof b === 'string') return b.slice(0, 200);
      if (typeof URLSearchParams !== 'undefined' && b instanceof URLSearchParams)
        return b.toString().slice(0, 200);
      return '[' + (b.constructor && b.constructor.name || 'тело') + ']';
    } catch (e) { return ''; }
  }

  function headerList(h) {
    var out = [];
    try {
      if (!h) return out;
      if (typeof h.forEach === 'function')
        h.forEach(function (v, k) { out.push(k + ': ' + v); });
      else
        Object.keys(h).forEach(function (k) { out.push(k + ': ' + h[k]); });
    } catch (e) {}
    return out;
  }

  function watchNet() {
    if (!CFG.debug) return;

    try {
      var X = window.XMLHttpRequest;
      if (X && X.prototype && !X.prototype.lmHooked) {
        X.prototype.lmHooked = true;
        var open = X.prototype.open,
            send = X.prototype.send,
            setH = X.prototype.setRequestHeader;

        X.prototype.open = function (m, u) {
          this.lmM = m; this.lmU = u; this.lmH = [];
          return open.apply(this, arguments);
        };
        X.prototype.setRequestHeader = function (k, v) {
          if (this.lmH) this.lmH.push(k + ': ' + v);
          return setH.apply(this, arguments);
        };
        X.prototype.send = function (data) {
          var self = this;
          var body = netBody(data);
          catchCsrf(self.lmU, body);
          self.addEventListener('load', function () {
            netLog(self.lmU,
                   'XHR ' + self.lmM + ' ' + String(self.lmU).slice(0, 110) +
                   '  → ' + self.status +
                   ' ' + Math.round((self.responseText || '').length / 1024) + 'КБ' +
                   (self.lmH && self.lmH.length ? '\n     ' + self.lmH.join('\n     ') : '') +
                   (body ? '\n     тело: ' + body : ''));
          });
          return send.apply(this, arguments);
        };
      }
    } catch (e) {}

    try {
      var f = window.fetch;
      if (f && !f.lmHooked) {
        var wrapped = function (input, init) {
          var u = (typeof input === 'string') ? input : (input && input.url);
          var m = (init && init.method) ||
                  (typeof input !== 'string' && input && input.method) || 'GET';
          var h = headerList((init && init.headers) ||
                             (typeof input !== 'string' && input && input.headers));
          var body = netBody((init && init.body) ||
                             (typeof input !== 'string' && input && input.body));
          catchCsrf(u, body);
          return f.apply(this, arguments).then(function (r) {
            netLog(u,
                   'fetch ' + m + ' ' + String(u).slice(0, 110) + '  → ' + r.status +
                   (h.length ? '\n     ' + h.join('\n     ') : '') +
                   (body ? '\n     тело: ' + body : ''));
            return r;
          });
        };
        wrapped.lmHooked = true;
        window.fetch = wrapped;
      }
    } catch (e) {}
  }

  watchNet();

  /* Писец для скрытого окна пыни — см. блок в самом начале. Отдельно от
     watchNet потому, что тот завязан на CFG и общий журнал, а здесь нужно
     нечто самостоятельное и заведомо безобидное: окно грузится ради ленты,
     и ломать его диагностикой нельзя. */
  function recordInFrame() {
    var box;
    try {
      box = window.parent.lmPynNet || (window.parent.lmPynNet = []);
    } catch (e) { return; }     /* другое окружение — записывать некуда */

    var put = function (line) { if (box.length < 40) box.push(line); };

    /* Заодно вытаскиваем csrf-токен. В скрытом окне работает скрипт
       лепры, и он шлёт mark_seen со своим токеном — а в главном окне
       взять его негде: в разметке его нет, а её скрипт туда не ходит. */
    /* Заодно ловим саму ленту уведомлений в виде данных. Скрипт лепры в
       этом окне и так запрашивает её у своего API — значит рейтинги
       комментариев уже приходят, и просить их отдельным запросом
       (полтораста килобайт) было бы расточительством. Берём готовое.
       Отдаём наружу как есть: разбирать здесь нечего, а в главном окне
       ждёт голосовалка, которой нужен только рейтинг. */
    var grabFeed = function (url, body) {
      try {
        if (String(url || '').indexOf('/api/my/notifications/?') < 0) return;
        var j = JSON.parse(body);
        if (j && j.notifications && j.notifications.length)
          window.parent.lmPynJson = j.notifications;
      } catch (e) {}
    };

    /* Токен для /ajax/ — второй, отдельный от того, что в JSON у /api/.
       В этом окне грузится /my/events/, и лепра шлёт там свои запросы;
       главное окно может стоять на главной ленте, где таких запросов
       нет вовсе. Передаём наружу. */
    var grabAjaxCsrf = function (url, body) {
      try {
        if (window.parent.lmAjaxCsrf) return;
        if (String(url || '').indexOf('/ajax/') < 0 || !body) return;
        var m = /(?:^|&)csrf_token=([^&]+)/.exec(String(body));
        if (!m) return;
        window.parent.lmAjaxCsrf = decodeURIComponent(m[1]);
      } catch (e) {}
    };

    var grabCsrf = function (body) {
      try {
        if (window.parent.lmCsrf || !body) return;
        var j = JSON.parse(body);
        if (j && typeof j.csrf_token === 'string' && j.csrf_token)
          window.parent.lmCsrf = j.csrf_token;
      } catch (e) {}
    };

    try {
      var X = window.XMLHttpRequest;
      if (X && X.prototype && !X.prototype.lmHooked) {
        X.prototype.lmHooked = true;
        var open = X.prototype.open,
            send = X.prototype.send,
            setH = X.prototype.setRequestHeader;

        X.prototype.open = function (m, u) {
          this.lmM = m; this.lmU = u; this.lmH = [];
          return open.apply(this, arguments);
        };
        X.prototype.setRequestHeader = function (k, v) {
          if (this.lmH) this.lmH.push(k + ': ' + v);
          return setH.apply(this, arguments);
        };
        X.prototype.send = function (data) {
          var self = this, body = netBody(data);
          grabCsrf(body);
          grabAjaxCsrf(self.lmU, body);
          self.addEventListener('load', function () {
            grabFeed(self.lmU, self.responseText);
            if (netSkip(self.lmU)) return;
            put('XHR ' + self.lmM + ' ' + String(self.lmU).slice(0, 110) +
                '  → ' + self.status +
                ' ' + Math.round((self.responseText || '').length / 1024) + 'КБ' +
                (self.lmH && self.lmH.length ? '\n     ' + self.lmH.join('\n     ') : '') +
                (body ? '\n     тело: ' + body : ''));
          });
          return send.apply(this, arguments);
        };
      }
    } catch (e) {}

    try {
      var f = window.fetch;
      if (f && !f.lmHooked) {
        var wrapped = function (input, init) {
          var u = (typeof input === 'string') ? input : (input && input.url);
          var m = (init && init.method) ||
                  (typeof input !== 'string' && input && input.method) || 'GET';
          var h = headerList((init && init.headers) ||
                             (typeof input !== 'string' && input && input.headers));
          var body = netBody((init && init.body) ||
                             (typeof input !== 'string' && input && input.body));
          grabCsrf(body);
          grabAjaxCsrf(u, body);
          return f.apply(this, arguments).then(function (r) {
            if (!netSkip(u))
              put('fetch ' + m + ' ' + String(u).slice(0, 110) + '  → ' + r.status +
                  (h.length ? '\n     ' + h.join('\n     ') : '') +
                  (body ? '\n     тело: ' + body : ''));
            return r;
          });
        };
        wrapped.lmHooked = true;
        window.fetch = wrapped;
      }
    } catch (e) {}
  }

  /* Метки «уже обработано» держим в WeakSet, а не в data-атрибутах:
     атрибут на каждом из десятков тысяч элементов — это лишняя память
     и лишняя работа для браузера. WeakSet не мешает сборке мусора. */
  /* если WeakSet почему-то недоступен, подменяем его совместимой заглушкой */
  var Marks = (typeof WeakSet === 'function') ? WeakSet : function () {
    this._k = '_lm' + Math.random().toString(36).slice(2);
    this.has = function (el) { return !!el[this._k]; };
    this.add = function (el) { el[this._k] = true; };
  };

  var seen = {
    scan:    new Marks(),   /* обойдено проверкой переполнения */
    unfloat: new Marks(),   /* проверено на обтекание */
    media:   new Marks(),   /* размеры медиа выставлены */
    obs:     new Marks(),   /* отдано наблюдателю видимости */
    poked:   new Marks(),   /* плеер разбужен */
    footer:  new Marks(),   /* подпись поста сокращена */
    userRow: new Marks(),   /* пункт списка граждан размечен */
    offscreen: new Marks(), /* ролик под наблюдением «уехал за экран» */
    vlink:   new Marks(),   /* ссылка под роликом поставлена */
    emoji:   new Marks()    /* эмодзи внутри обёрнуты */
  };

  /* Обход в глубину с отсечением поддеревьев. querySelectorAll возвращает
     плоский список и пропустить целую ветку не даёт, а TreeWalker даёт:
     внутренности комментариев обходить не нужно, их сотни тысяч. */
  function walk(from, skipSubtree, visit, budget) {
    /* фильтр передаём функцией, а не объектом с acceptNode:
       объектную форму принимают не все версии Safari */
    var w = document.createTreeWalker(from, 1 /* SHOW_ELEMENT */, function (el) {
      return skipSubtree(el) ? 2 /* FILTER_REJECT */ : 1 /* FILTER_ACCEPT */;
    });
    var n = 0;
    while (w.nextNode() && n < budget) { visit(w.currentNode); n++; }
    return n;
  }

  /* Внутрь комментариев и постов не заходим: там однотипная разметка,
     уже покрытая правилами, зато именно она даёт основную массу узлов. */
  function isBulk(el) {
    return el.classList &&
      (el.classList.contains('comment') || el.classList.contains('post'));
  }

  function root() {
    return document.getElementById('js-nonfooter') || document.body;
  }

  /* Из-за overflow-x на body прокрутку может вести не окно, а сам body.
     Поэтому читаем максимум из кандидатов, а пишем во все: подействует
     только настоящий. */
  function scrollTopNow() {
    return Math.max(
      window.pageYOffset || 0,
      (document.scrollingElement && document.scrollingElement.scrollTop) || 0,
      document.documentElement.scrollTop || 0,
      (document.body && document.body.scrollTop) || 0
    );
  }

  function scrollTopSet(y) {
    try { window.scrollTo(0, y); } catch (e) {}
    if (document.scrollingElement) document.scrollingElement.scrollTop = y;
    document.documentElement.scrollTop = y;
    if (document.body) document.body.scrollTop = y;
  }

  function docHeight() {
    return Math.max(
      document.documentElement.scrollHeight || 0,
      document.documentElement.offsetHeight || 0,
      (document.body && document.body.scrollHeight) || 0,
      (document.body && document.body.offsetHeight) || 0
    );
  }

  /* ============================================================
     2. СТИЛИ
     ============================================================ */

  /* Лесенка комментариев: у лепры шаг 28px, для телефона это слишком много.
     Шаг 13px, потолок на шестом уровне — дальше текста не остаётся. */
  function indentRules() {
    var out = [], i;
    for (i = 1; i <= 30; i++)
      out.push('#js-comments_holder .comment.indent_' + i +
               ' { padding-left: ' + Math.min(i * 13, 78) + 'px !important; }');
    return out.join('\n');
  }

  /* Форма ответа лежит внутри комментария и стоит на его отступе. Чтобы
     она вышла во всю ширину колонки, отступ надо отмотать назад — своим
     числом на каждую ступень лесенки, потому что общего «сколько там
     набежало» в CSS не выразить.
     Правила идут ОТДЕЛЬНОЙ функцией, а не приписаны к indentRules,
     нарочно: они спорят с width: 100% из раздела «форма ответа» и обязаны
     стоять ниже него по файлу. Иначе браузер разрешит спор по весу
     селектора (победит эта пара), а jsdom — по порядку объявления
     (победит width: 100%), и проверка начнёт врать. */
  function replyBleedRules() {
    if (!CFG.replyBleed) return '';
    var out = [], i, pad;
    for (i = 1; i <= 30; i++) {
      pad = Math.min(i * 13, 78);
      /* max-width снимаем обязательно: в правиле выше стоит 100%, и без
         этой строки он срезал бы calc обратно до ширины комментария —
         в jsdom незаметно (он не считает раскладку), в браузере видно. */
      out.push('#js-comments_holder .comment.indent_' + i + ' .b-comments_reply_block' +
               ' { margin-left: -' + pad + 'px !important;' +
               ' max-width: none !important;' +
               ' width: calc(100% + ' + pad + 'px) !important; }');
    }
    return out.join('\n');
  }

  /* ---- Оформление голосовалок ----

     Разобрано по спрайтам лепры, снятым с сохранённой страницы. Оказалось,
     что «оригинальные кнопки лепры» — это картинка 18×18, на которой
     нарисован светлый прямоугольник с рамкой в один пиксель и всё:
       vote_button.gif       заливка #f8f8f8, рамка #e6e6e6
       vote_button_hover.gif заливка та же,  рамка #cecece
     Плюс и минус — не часть картинки, а обычный текст в разметке
     («+» и «—») кеглем 10 цветом #cecece, у отданного голоса #666666.
     Карма устроена так же: коробка 26×26 #f5f5f5 без видимой рамки,
     знак #cecece, у отданного — рамка и знак #7d7d7d.

     Отсюда два вывода, из-за которых картинки лепры мы НЕ берём.

     Первый: брать нечего. Весь её вид — прямоугольник с рамкой, и в CSS
     он выражается точнее, чем картинкой: растровые 18×18 не растянуть
     под палец, а поля вокруг них пришлось бы городить отдельно.

     Второй, важнее: у лепры нажатое состояние не имеет заливки вовсе.
     Темнеют только рамка и знак. Это и есть ответ на «слишком
     контрастная заливка» — доведённый до предела.

     Знаки рисуем сами, полосками, а не буквами. Причина не в красоте:
     «+» и «—» стоят в кегельной площадке шрифта на разной высоте и
     разной ширины (у Verdana длинное тире шире плюса), и никакое
     выравнивание строки не поставит их в одну точку — центрируется
     строка, а не рисунок буквы. Полоски же кладутся от середины
     коробки, то есть попадают в центр по построению. Заодно минус
     перестаёт быть длинным тире и становится ровно такой же ширины,
     как перекладина плюса.

     Наборов какое-то время было три, для сравнения на устройстве.
     Выбран этот; лепровская палитра оказалась слишком тихой под пальцем,
     а её коробка 18×18 — мелкой. От лепры взято главное: нажатие
     показывается не чёрной плашкой, а приглушённой заливкой. */

  var VOTE_SKIN = {
    box: '#f4f4f2', edge: '#dcdcd8', ink: '#666666',
    onBox: '#c0bebe', onEdge: '#aeacac', onInk: '#1a1a1a'
  };

  /* Кнопка — площадь под палец, видимая коробка внутри рисуется
     псевдоэлементом. Разница в два пикселя: коробка 26, площадь 28.
     Кнопки в комментариях и под постами одного размера намеренно —
     разными они выглядели случайной небрежностью, а строку подписи
     лишние два пикселя не переносят (проверено на треде).
     Карма того же размера: разнобой в одну-две единицы читается как
     небрежность, а не как замысел. Столько же у кнопок в окне пыни. */
  var VOTE_GEOM = { tap: [28, 28], box: 26, karma: 28 };

  /* Списки селекторов перечислены поимённо и целиком, а не сведены к
     одному короткому. Причина в весе: общие правила голосования выше по
     файлу написаны в том числе через идентификатор
     (#js-comments_holder .comment .c_vote .vote_button), и правило вида
     `html .vote_button` им проиграло бы при обоих !important. Приписав
     тот же список с приставкой html, мы тяжелее каждого из них ровно на
     один элемент — и стоим ниже по файлу, то есть спор решается
     одинаково и в браузере (по весу), и в jsdom (по порядку). */
  var VOTE_BTN = ['#js-comments_holder .comment .c_vote .vote_button',
                  '.c_vote .vote_button_plus', '.c_vote .vote_button_minus',
                  '.post .dd .vote .vote_button', '.dd .vote .vote_button',
                  '.comment .vote_button', 'a.vote_button', '.vote_button'];
  var VOTE_RES = ['#js-comments_holder .comment .c_vote .vote_result',
                  '.post .dd .vote .vote_result', '.dd .vote .vote_result',
                  '.comment .vote_result', '.c_vote .vote_result', '.vote_result'];
  var VOTE_KRM = ['.b-user_karma .b-karma_button', '.b-karma_button'];

  /* Приставка по умолчанию — html: она даёт нашим правилам ровно на один
     элемент больше, чем у лепры, и этого хватает. В тёмной теме
     приставка другая (html.lm-dark), поэтому она третьим доводом, а не
     зашита внутрь. */
  function voteSel(list, suffix, prefix) {
    return list.map(function (s) {
      return (prefix || 'html ') + s + (suffix || '');
    }).join(',\n');
  }

  /* Одна полоска знака. Кладётся от середины коробки минусовыми полями, а
     не transform: тот в Safari на дробных величинах размывает край, а
     полоска толщиной в пиксель размытия не прощает. */
  function voteBar(w, h) {
    return 'content: \'\' !important; position: absolute !important;' +
           ' left: 50% !important; top: 50% !important;' +
           ' width: ' + w + 'px !important; height: ' + h + 'px !important;' +
           ' margin: -' + (h / 2) + 'px 0 0 -' + (w / 2) + 'px !important;' +
           ' background: currentColor !important;';
  }

  /* ---- Тёмная тема: цвета органов управления ----

     Тема сделана инверсией всей страницы, поэтому здесь нельзя просто
     написать нужный цвет: браузер его перевернёт. Пишем ДОПОЛНЕНИЕ —
     то, что после переворота даст задуманное. Этим и занята inv, а в
     вызовах стоят те числа, которые получатся на экране.

     Зачем вообще править. Светлая палитра построена на очень светлых
     серых: коробка голосовалки 244, её рамка 220, рамка карточки 220.
     После переворота это 11, 35 и 35 — почти чёрное на чёрном. Формально
     всё на месте, на деле органов управления не видно. Поднимаем их до
     тонов, которые на тёмном читаются и не режут глаз: коробки около
     сорока, рамки около семидесяти, знаки около ста восьмидесяти.

     Отдельная история — свечение карточки. В светлой теме оно светлое в
     середине и тёплое к краям; перевёрнутое, даёт тёмную середину и
     светлые края, то есть карточка выглядит продавленной. Поэтому в
     тёмной теме наборы меняются местами: берём тот, что рисовался для
     обратной схемы, и после переворота он ложится правильно. */
  function inv(v) { return 255 - v; }

  function invRgb(r, g, b) {
    return 'rgb(' + inv(r) + ',' + inv(g) + ',' + inv(b) + ')';
  }

  function darkRules() {
    var out = [];
    var D = 'html.lm-dark ';

    /* Красим и сам html, а не только body. Это и есть та полоса, где
       рамки «становились чёрными»: у html фон стоял чистым белым, после
       переворота — чистый чёрный, и он же уходит на холст под всей
       страницей. Пока body хватало высоты, холста не видно; ниже его
       коробки по бокам открывался этот чёрный, и карточки на нём
       смотрелись обведёнными в другой цвет.
       Тон один на все три узла: холст, body и обёртка. */
    /* html здесь не перечислен, хотя красить его тоже надо: у него уже
       есть своё правило выше (там инверсия), и второе с тем же
       селектором было бы дублем. Цвет холста задаём там же, где инверсию,
       через переменную — так он остаётся одним числом на все три узла. */
    out.push(':root { --lm-dark-page: ' + invRgb(21, 21, 21) + '; }');
    out.push('html.lm-dark.lm-cards2 { --lm-dark-page: ' + invRgb(38, 37, 34) + '; }');
    out.push(D + 'body,\n' + D + '.l-i-wrapper {\n' +
             '  background-color: var(--lm-dark-page) !important; }');
    out.push(D + '.post {\n' +
             '  background-color: ' + invRgb(32, 32, 32) + ' !important;\n' +
             '  background-image: ' + CARD_GLOW2 + ' !important;\n' +
             '  border-color: ' + invRgb(61, 61, 61) + ' !important; }');
    /* Карточка подлепры теми же тонами, что и пост. Без этого правила
       она не сломалась бы — общая инверсия страницы её всё равно
       затемнит, — но заводская заливка 250 переворачивается в 5, то
       есть карточка выходит ТЕМНЕЕ страницы (21), тогда как у поста тут
       же назначено обратное, 32 против 21. Две карточки на соседних
       страницах смотрелись бы по-разному нарисованными. */
    out.push(D + '.b-blogs_list .b-list_item,\n' +
             D + '.l-content_aside_subscriptions_top .b-subscriptions_aside_block {\n' +
             '  background-color: ' + invRgb(32, 32, 32) + ' !important;\n' +
             '  background-image: ' + CARD_GLOW2 + ' !important;\n' +
             '  border-color: ' + invRgb(61, 61, 61) + ' !important; }');
    out.push(D + '.c_i {\n' +
             '  background-color: ' + invRgb(32, 32, 32) + ' !important;\n' +
             '  background-image: ' + CARD_GLOW2 + ' !important; }');
    out.push(D + '.comment .c_i::before {\n' +
             '  border-color: ' + invRgb(61, 61, 61) + ' !important; }');

    out.push('html.lm-dark.lm-cards2 .post,\n' +
             'html.lm-dark.lm-cards2 .c_i,\n' +
             'html.lm-dark.lm-cards2 .b-blogs_list .b-list_item,\n' +
             'html.lm-dark.lm-cards2 .l-content_aside_subscriptions_top' +
             ' .b-subscriptions_aside_block {\n' +
             '  background-color: ' + invRgb(23, 23, 22) + ' !important;\n' +
             '  background-image: ' + CARD_GLOW + ' !important; }');

    out.push(voteSel(VOTE_BTN.concat(VOTE_KRM), '', D) + ' {\n' +
             '  color: ' + invRgb(178, 178, 178) + ' !important; }');
    out.push(voteSel(VOTE_BTN.concat(VOTE_KRM), '::before', D) + ' {\n' +
             '  background: ' + invRgb(44, 44, 44) + ' !important;\n' +
             '  border-color: ' + invRgb(71, 71, 71) + ' !important; }');
    out.push(voteSel(VOTE_BTN, '.vote_voted', D) + ',\n' +
             voteSel(VOTE_KRM, '.active', D) + ' {\n' +
             '  color: ' + invRgb(242, 242, 242) + ' !important; }');
    out.push(voteSel(VOTE_BTN, '.vote_voted::before', D) + ',\n' +
             voteSel(VOTE_KRM, '.active::before', D) + ' {\n' +
             '  background: ' + invRgb(78, 78, 78) + ' !important;\n' +
             '  border-color: ' + invRgb(107, 107, 107) + ' !important; }');
    out.push(voteSel(VOTE_RES, '', D) + ' {\n' +
             '  color: ' + invRgb(170, 170, 170) + ' !important; }');

    out.push('html.lm-dark.lm-stuck #lm-topbar {\n' +
             '  background: ' + invRgb(27, 27, 27) + ' !important;\n' +
             '  border-bottom-color: ' + invRgb(61, 61, 61) + ' !important; }');
    out.push(D + '.lm-navthing_row {\n' +
             '  background: ' + invRgb(47, 47, 47) + ' !important;\n' +
             '  color: ' + invRgb(196, 196, 196) + ' !important; }');
    out.push('html.lm-dark.lm-navpin #lm-navthing .lm-navthing_row::before {\n' +
             '  background: ' + invRgb(21, 21, 21) + ' !important; }');

    /* Заливка значков задана фигурам атрибутом, поэтому перекрываем
       правилом — иначе пришлось бы перерисовывать их при переключении. */
    out.push(D + '#lm-nav svg polygon,\n' + D + '.lm-dsc_nest svg polygon,\n' +
             D + '#lm-dsc_arrow svg polygon {\n' +
             '  fill: ' + invRgb(150, 150, 150) + ' !important; }');
    /* Белый ореол под значками после переворота становится чёрным и на
       тёмном не виден вовсе. Ставим тёмный — он перевернётся в светлый и
       снова будет отделять значок от того, что под ним. */
    out.push(D + '#lm-nav button svg,\n' + D + '.lm-dsc_nest svg,\n' +
             D + '.lm-navthing_pin svg {\n' +
             '  filter: drop-shadow(0 0 1px rgba(0,0,0,.95))\n' +
             '          drop-shadow(0 0 2px rgba(0,0,0,.8)) !important; }');

    out.push(D + '.lm-more::before {\n' +
             '  background: ' + invRgb(160, 160, 160) + ' !important; }');
    out.push(D + '.lm-more_box.lm-on .lm-icons {\n' +
             '  background: ' + invRgb(38, 38, 38) + ' !important;\n' +
             '  border-color: ' + invRgb(74, 74, 74) + ' !important; }');
    out.push(D + '.comment .c_footer .c_answer.lm-reply {\n' +
             '  color: ' + invRgb(165, 165, 165) + ' !important; }');

    /* Нажатое и выбранное. В светлой теме подсветка — серый 220 на белом,
       то есть «чуть темнее фона». После переворота это 35 на 21: чуть
       светлее фона, и разница в четырнадцать единиц на тёмном не видна
       вовсе — ни выбранная пиктограмма уплотнения, ни выбранный тип
       ленты, ни нажатые кнопки в попапе.
       На тёмном подсветка обязана быть заметно светлее, а не «чуть»:
       ставим 70 при фоне 21, то есть втрое дальше. Подпись на ней —
       почти белая, иначе тёмный текст на светлой плашке выглядит
       заплатой из другой темы. */
    var ON_BG = invRgb(70, 70, 70), ON_EDGE = invRgb(104, 104, 104),
        ON_INK = invRgb(238, 238, 238);
    out.push(D + '.lm-set_opt.lm-on,\n' + D + '.lm-set_switch.lm-on,\n' +
             D + '.lm-set_radio.lm-on,\n' +
             D + '.lm-navthing_extra .lm-disco_btn.lm-on,\n' +
             D + '.lm-navthing_extra .lm-disco_mode.lm-on,\n' +
             D + '.lm-navthing_extra .b-slider_scale_icon.js-feed_type_active {\n' +
             '  background: ' + ON_BG + ' !important;\n' +
             '  border-color: ' + ON_EDGE + ' !important;\n' +
             '  color: ' + ON_INK + ' !important; }');

    /* Кнопка темы. Её обводка в светлой палитре — 214, то есть после
       переворота 41: кружок сливается с плашкой. */
    /* Логотипы. Из общей инверсии картинки исключены — иначе фотографии
       в постах пошли бы негативом, — и логотип сохраняет подлинные
       цвета: на чёрном фоне он читается наклейкой. Отдать его инверсии
       нельзя по той же причине, по которой мы её и снимали: маска
       побелеет, звезда позеленеет, красивее не станет.
       Приглушаем прозрачностью: цвета остаются своими, но перестают
       кричать. Семьдесят процентов — граница, за которой логотип
       начинает выглядеть выключенным. */
    out.push(D + '.b-logo img,\n' + D + '.b-logo_subsite img {\n' +
             '  opacity: .7 !important; }');

    /* Липкости в тёмной теме нет. Причина внешняя: верхнюю полосу Safari
       красит по метатегу, и пока она догоняет цвет страницы, светлая
       липкая плашка под ней выглядит вторым, чужим слоем. С обычной
       шапкой этого не случается — она просто уезжает.
       Возвращаем всё в поток: и приветствие, и полоску навигации.
       Наблюдатели при этом продолжают работать вхолостую — ломать их
       ради выключенного режима не стоит, а признак «прокручено» в
       тёмной теме не ставится вовсе (см. setStuck). */
    out.push(D + '#lm-topbar,\n' +
             'html.lm-dark.lm-navstick #lm-navthing .lm-navthing_row {\n' +
             '  position: static !important; }');

    out.push(D + '#lm-theme {\n' +
             '  border-color: ' + invRgb(86, 86, 86) + ' !important;\n' +
             '  color: ' + invRgb(200, 200, 200) + ' !important; }');

    return out.join('\n');
  }

  function voteRules() {
    var out = [];
    var GLYPH = 9;                       /* длина перекладины знака */
    var s = VOTE_SKIN, g = VOTE_GEOM;

    /* Общая часть кнопки. Собрана в одно объявление вместе с размерами
       нарочно: разложенная на «сброс» и «геометрию», она дала бы два
       правила с одинаковым списком селекторов — то есть дубль, который
       проверка перед выдачей и ловит, и который однажды уже приводил к
       тихой отмене правил.
       font-size: 0 гасит текстовый знак и заодно пустой <em>, который
       лепра кладёт следом за ним.
       Сама кнопка не красится — она только ловит нажатие, а рисует
       псевдоэлемент. */
    var RESET =
      '  position: relative !important;\n' +
      '  font-size: 0 !important;\n' +
      '  display: inline-flex !important;\n' +
      '  align-items: center !important; justify-content: center !important;\n' +
      '  box-sizing: border-box !important;\n' +
      '  padding: 0 !important;\n' +
      '  background: none !important; border: 0 !important;\n' +
      '  border-radius: 0 !important;\n' +
      '  text-decoration: none !important;\n' +
      '  -webkit-tap-highlight-color: transparent !important;\n';

    out.push(voteSel(VOTE_BTN) + ' {\n' + RESET +
             '  width: ' + g.tap[0] + 'px !important; height: ' + g.tap[1] + 'px !important;\n' +
             '  min-width: 0 !important; margin: 0 1px !important;\n' +
             '  color: ' + s.ink + ' !important; }');

    /* Минус — одна полоска. */
    out.push(voteSel(['.vote_button', '.b-karma_button'], '::after') +
             ' {\n  ' + voteBar(GLYPH, 1) + ' }');
    /* Плюс — квадрат со стороной знака, внутри две полоски заливками.
       Вторым узлом было бы понятнее, но узлов всего два, и ::before у
       кнопки занят видимой коробкой. */
    out.push(voteSel(['.vote_button_plus', '.b-karma_button__plus'], '::after') +
             ' {\n' +
             '  width: ' + GLYPH + 'px !important; height: ' + GLYPH + 'px !important;\n' +
             '  margin: -' + (GLYPH / 2) + 'px 0 0 -' + (GLYPH / 2) + 'px !important;\n' +
             '  background-color: transparent !important;\n' +
             '  background-image:\n' +
             '    linear-gradient(currentColor, currentColor),\n' +
             '    linear-gradient(currentColor, currentColor) !important;\n' +
             '  background-size: ' + GLYPH + 'px 1px, 1px ' + GLYPH + 'px !important;\n' +
             '  background-position: center center !important;\n' +
             '  background-repeat: no-repeat !important; }');

    /* Видимая коробка */
    out.push(voteSel(VOTE_BTN, '::before') + ' {\n' +
             '  content: \'\' !important; position: absolute !important;\n' +
             '  left: 50% !important; top: 50% !important;\n' +
             '  width: ' + g.box + 'px !important; height: ' + g.box + 'px !important;\n' +
             '  margin: -' + (g.box / 2) + 'px 0 0 -' + (g.box / 2) + 'px !important;\n' +
             '  box-sizing: border-box !important;\n' +
             '  background: ' + s.box + ' !important;\n' +
             '  border: 1px solid ' + s.edge + ' !important;\n' +
             '  border-radius: 5px !important; }');

    /* Отданный голос. Заливку и рамку гасим здесь ещё раз, хотя они уже
       погашены в RESET: селектор с лишним классом .vote_voted тяжелее
       общего, и любое чужое правило, зацепившееся за этот класс,
       нарисовало бы фон по всей площади нажатия — мимо коробки. Один раз
       так уже вышло, см. пояснение в разделе «Голосование». */
    out.push(voteSel(VOTE_BTN, '.vote_voted') + ' {\n' +
             '  color: ' + s.onInk + ' !important;\n' +
             '  background: none !important; border: 0 !important; }');
    out.push(voteSel(VOTE_BTN, '.vote_voted::before') + ' {\n' +
             '  background: ' + s.onBox + ' !important;\n' +
             '  border-color: ' + s.onEdge + ' !important; }');

    /* Счётчик. Ширина не задаётся числом, а растёт от содержимого:
       фиксированные сорок пикселей хорошо смотрелись на «7250» и
       превращались в пустое поле на «7». Нижний предел равен высоте
       коробки — тогда однозначное число сидит в квадрате того же
       размера, что и кнопки рядом, а не в узкой щели. Поля по бокам
       нужны, чтобы длинное число не упиралось в знаки. */
    out.push(voteSel(VOTE_RES) + ' {\n' +
             '  min-width: ' + g.box + 'px !important; width: auto !important;\n' +
             '  height: ' + g.box + 'px !important; line-height: ' + g.box + 'px !important;\n' +
             '  padding: 0 3px !important; margin: 0 !important;\n' +
             '  font-size: 13px !important; font-weight: 600 !important;\n' +
             '  color: #555555 !important;\n' +
             '  background: none !important; border: 0 !important; }');

    /* Карма. Устройство то же, размер свой. */
    out.push(voteSel(VOTE_KRM) + ' {\n' + RESET +
             '  width: ' + g.karma + 'px !important; height: ' + g.karma + 'px !important;\n' +
             '  margin: 0 !important;\n' +
             '  color: ' + s.ink + ' !important; }');
    out.push(voteSel(VOTE_KRM, '::before') + ' {\n' +
             '  content: \'\' !important; position: absolute !important;\n' +
             '  left: 0 !important; top: 0 !important;\n' +
             '  right: 0 !important; bottom: 0 !important;\n' +
             '  box-sizing: border-box !important;\n' +
             '  background: ' + s.box + ' !important;\n' +
             '  border: 1px solid ' + s.edge + ' !important;\n' +
             '  border-radius: 5px !important; }');
    out.push(voteSel(VOTE_KRM, '.active') + ' {\n' +
             '  color: ' + s.onInk + ' !important;\n' +
             '  background: none !important; border: 0 !important; }');
    out.push(voteSel(VOTE_KRM, '.active::before') + ' {\n' +
             '  background: ' + s.onBox + ' !important;\n' +
             '  border-color: ' + s.onEdge + ' !important; }');

    return out.join('\n');
  }

  /* Герб «Блогов Империи» (empire_blogs.png) — файл 65×58, но рисунок в
     нём занимает только 39×38, начиная с точки (12, 10): шесть седьмых
     площади — прозрачные поля под вырез в фоновой подложке десктопной
     колонки. Оттого вписанный целиком герб и выходил втрое мельче
     гнезда: при гнезде в 24 на сам рисунок приходилось четырнадцать.
     Поэтому картинку не вписываем, а увеличиваем и обрезаем полями
     обёртки — в гнезде оказывается ровно рисунок.
     Числа — замер файла, а не подбор на глаз; если лепра его заменит,
     поля разъедутся, и мерить надо будет заново. */
  var CREST = { w: 65, h: 58, x: 12, y: 10, aw: 39, ah: 38 };
  /* Множитель считаем по ширине рисунка: гнездо квадратное, а рисунок
     почти квадратный, и по высоте он занимает 38/39 гнезда — оставшийся
     пиксель делим пополам сверху и снизу, чтобы стоял по центру. */
  var CREST_CSS = {
    w: (CREST.w / CREST.aw * 100).toFixed(2),
    x: (-CREST.x / CREST.aw * 100).toFixed(2),
    y: ((-CREST.y + (CREST.aw - CREST.ah) / 2) / CREST.aw * 100).toFixed(2)
  };

  /* Отбивка свёрнутой строки: столько, чтобы гнездо герба уместилось в
     заданную высоту строки. Семнадцать — высота самой подписи (13
     пунктов при межстрочном 1.3): пока гнездо ниже неё, высоту держит
     подпись, и отбивки считаются от неё. */
  var NAV_PAD = Math.max(0,
    Math.round((CFG.navRow - Math.max(CFG.navIcon, 17)) / 2));

  /* Общее скругление органов управления в третьей колонке. Число не своё:
     это скругление поля поиска у самой лепры (.b-header_search
     .i-form_text_input, border-radius: 5px). Кнопки, поле выбора порога и
     поле поиска стоят друг под другом, и разные радиусы в столбике видно
     сразу — поэтому берётся одно, и берётся у того элемента, который мы
     не рисовали сами. */
  var UI_R = 5;

  /* Скругление рамок поста и комментария. Число одно на четыре места, и
     держать его переменной пришлось не из аккуратности: кроме самой
     рамки его обязаны знать ещё три вещи, у которых углы свои. Заливка
     подсветки новых комментариев, цветная полоса вдоль комментария
     автора и красная рамка подсветки лепры нарисованы прямоугольниками
     поверх скруглённой коробки — и любое расхождение вылезает уголками.
     Разъехаться четырём числам легче лёгкого; переменная это исключает. */
  var FRAME_R = 8;

  /* Цвет рамок и внутренних разделителей. Тоже одним числом на все
     места: рамка поста, рамка комментария и черта между телом и
     подписью обязаны быть одного тона, иначе одна из них читается как
     ошибка. */
  var FRAME_C = 'rgb(220,217,209)';

  /* Кнопки в подвале формы комментария: «Закрыть» и отправка.
     Ширина и высота одни на обе и на отступ между ними, поэтому числа
     вынесены сюда, а не написаны по месту трижды. Разбор — у самих
     правил.
     28 по высоте — та же величина, что у кнопок голосования и у кнопок
     в попапе настроек: разнобой в пару пикселей читается небрежностью.
     76 по ширине — под слово YARRR! полужирным кеглем 12 с запасом на
     «Закрыть», которое чуть длиннее. */
  var FORM_BTN_W = 76;
  var FORM_BTN_H = 28;

  /* Значок обновления над лентой комментариев. Был 24 наравне с
     соседями по строке; соседи ушли под шеврон, и значок остался
     единственным — можно и нужно крупнее. 28 — та же величина, что у
     кнопок голосования и подвала формы. */
  var CF_ICON = 28;

  /* Фон карточки — поста и комментария. Страница у лепры чисто белая,
     и карточка на ней до сих пор была дыркой с обводкой: рамка есть,
     тела нет. Тон взят из палитры лепры (её серый — 244,244,242),
     осветлённый почти до белого: карточка должна отделяться от
     страницы, а не спорить с ней.

     Цвет сплошной, а не прозрачный, — в отличие от подложки подписи.
     Прозрачный тут дал бы разное на разных подлепрах, а карточка должна
     выглядеть одинаково везде. */
  var CARD_BG = 'rgb(250,249,246)';

  /* Обратный набор: карточка белая, страница под ней притемнена.
     Тона не выдуманы заново, а поменяны местами — страница получает
     примерно тот тон, что был у карточки, карточка становится чистой
     белой. Так переключение выглядит именно инверсией пары, а не
     сменой оформления. */
  /* Обратный набор: страница 231, карточка 253. Третьего тона под
     подпись подбирать не нужно — своего фона у неё больше нет, её
     отделяет край общего свечения карточки. */
  var PAGE_ALT = 'rgb(231,228,219)';
  var CARD_ALT = 'rgb(253,252,250)';

  /* Обратный набор: подсветка нажатого и заливка значков.

     Все эти тона подбирались когда-то на БЕЛОЙ странице, и подбирались
     по расстоянию до неё: подсветка нажатой кнопки 220 при фоне 255 —
     это «на тридцать пять темнее фона», обводка 170 — «на восемьдесят
     пять», светло-серый значок прыгалки 210 — «на сорок пять».

     В обратном наборе страница уже не 255, а 231. Те же самые числа
     превращаются в «на одиннадцать темнее» — то есть в ничто: нажатая
     кнопка перестаёт отличаться от ненажатой, а значок прыгалки тонет в
     фоне. Ровно это и видно на устройстве.

     Поэтому пересчитываем не сами тона, а расстояния: берём то же
     удаление от фона, что и в заводском наборе, и откладываем его от
     231. Так переключение схемы не меняет ощущения контраста, а только
     тон.

     Из подсветок здесь только те, что лежат НА СТРАНИЦЕ, — кнопки
     навигационной штуки. Кнопки попапа настроек стоят на своей плашке
     rgb(245,245,245), которая от схемы не зависит, и трогать их не
     надо. */
  var ALT_ON_BG   = 'rgb(196,193,185)';   /* 231 − 35 */
  var ALT_ON_EDGE = 'rgb(146,144,136)';   /* 231 − 85 */
  var ALT_EDGE    = 'rgb(166,163,155)';   /* 231 − 65, обводка ненажатой */
  var ALT_JUMP    = 'rgb(186,185,182)';   /* 231 − 45, значки прыгалок */

  /* Свечение карточки: радиальный переход от середины к краям.

     Пришло на смену подложке под подписью — прямоугольной полосе снизу,
     которую приходилось согласовывать с тремя вещами разом: с тоном
     карточки, с тоном страницы и сама с собой в обратном наборе, где
     она обязана была светлеть, а не темнеть. Три числа, связанные так,
     что подгонка одного ломала другое; на этом мы и застряли.

     Радиальный переход снимает вопрос целиком. У него нет края, который
     надо с чем-то согласовывать: подпись стоит внизу карточки, то есть
     там, где свечение и так слабее, и отделяется сама собой. В обратном
     наборе меняется только тон подложки, рисунок остаётся тем же.

     Тона прозрачные, а не готовые цвета: под свечением лежит либо
     карточка, либо леприна подсветка нового комментария, и плёнка
     обязана пропускать то, что под ней. Белая в середине, тёплая по
     краям — чёрная по краям дала бы ту самую грязь, из-за которой
     тёплый тон и появился.
     Центр смещён вверх (40% высоты): текст начинается сверху, и самая
     светлая часть должна приходиться на него. */
  var CARD_GLOW = 'radial-gradient(ellipse at 50% 40%,' +
                  ' rgba(255,255,255,.60) 0%, rgba(140,125,90,.055) 100%)';

  /* В обратном наборе свечение перевёрнуто: тёплое в середине, белое по
     краям. Не ради симметрии — ради подписи.

     Подпись стоит внизу карточки, то есть на краю свечения. В заводском
     наборе край тёмный, и подпись темнеет — как и задумано, карточка
     светлая. В обратном наборе карточка почти белая, и та же тёмная
     кромка уводила бы подпись к тону страницы, то есть к слиянию с
     фоном; это ровно то, на что ты жаловался, когда подложка была
     отдельной полосой.

     Перевёрнутое свечение решает и это, и вид самой карточки: белые
     края на притемнённой странице очерчивают её сами, а лёгкое тёплое
     пятно в середине не даёт большому белому полю казаться плоским. */
  var CARD_GLOW2 = 'radial-gradient(ellipse at 50% 40%,' +
                   ' rgba(140,125,90,.05) 0%, rgba(255,255,255,.60) 100%)';

  /* Подъём коробки подписи в тело. Коробка начинается выше своего
     содержимого на столько пикселей: отрицательное верхнее поле тянет
     её вверх, а равная ему добавка к внутреннему отступу возвращает
     текст на прежнее место. Двигается только коробка.
     Своего фона у подписи теперь нет, но подъём оставлен: он же задаёт
     расстояние от тела до подписи, а отрицательные поля по краям
     дотягивают её до рамки. */
  var FOOT_LIFT = 14;

  /* Длительность сворачивания панели и отъезда логаута, миллисекунды.
     Число одно на код и на таблицу стилей: код по нему снимает потолок
     высоты после перехода и пересчитывает высоту плашки, и разойдись
     они — первое случилось бы посреди движения.
     280 — верхняя граница приятного: короче выглядит рывком, длиннее
     начинает раздражать при каждой прокрутке. */
  var NAV_FOLD = 280;

  /* Просвет между органами третьей колонки. Число одно на два места, и
     держать его отдельной переменной пришлось не из любви к порядку.
     Колонка — флекс-столбец, а кнопки уплотнения лежат в собственной
     обёртке со своим просветом; пока чисел было два (8 снаружи и 4
     внутри), кнопка scroll-connect стояла ближе к пиктограммам, чем к
     полю выбора порога, — и палец, метивший в пиктограмму, попадал в
     неё. Разнобой был не виден на глаз как ошибка: просто «немного
     плотнее». Теперь просвет один, и разойтись им нечем. */
  var UI_GAP = 8;

  /* Размеры схемофона в попапе настроек. Объявлены ЗДЕСЬ, а не рядом с
     самим попапом, потому что на них ссылается таблица стилей — она
     собирается шаблонной строкой в самом начале, и объявление ниже по
     файлу дало бы в правилах «undefinedpx». Синтаксис при этом
     остаётся верным, и проверка такого не ловит: ровно та же история,
     что с пропавшими объявлениями переменных из записки. */
  var SET_PHONE_H = 186, SET_PHONE_W = 102;

  /* Рост короны у ника президента. Числом в двух местах: сама корона и
     вычет из потолка ширины ника — они обязаны совпадать, иначе при
     длинном нике пара переносится.
     Объявлено ЗДЕСЬ по той же причине, что и всё остальное в этом
     гнезде: шаблонная строка стилей собирается ниже. */
  var PRES_CROWN_W = 20;

  /* Общий кегль тех же органов. Число тоже лепровское: поле поиска в
     шапке набрано тринадцатью, и по нему равняются кнопки. У поля выбора
     порога кегль подбирается замером (fitThreshold) и опускается, когда
     «NIGHTMARE (все)» не влезает в колонку, — там тринадцать только
     начальное значение. */
  var UI_FONT = 13;

  var css = `
/* ============ НЕВИДИМОЕ ОСТАЁТСЯ НЕВИДИМЫМ ============ */
/* У <script>, <style>, <template> и <noscript> невидимость держится не
   на чём-то особенном, а на обычном display: none из встроенной
   таблицы браузера. Любое наше правило вида «display: … !important» на
   ГРУППУ детей перебивает её — и содержимое скрипта вываливается на
   страницу текстом.
   Именно так и случилось: лепра дописывает после сильно заминусованных
   комментариев маленький <script> с вызовом initCommentCollapse, а у
   нас на детей .c_footer стоит display: inline-block !important. На
   обычных комментариях скрипта нет, поэтому вылезало «периодически» —
   ровно на тех, где минусов набралось на сворачивание.
   Это страховка, а не единственная защита: при равном !important
   побеждает более весомый селектор, и групповое правило с тремя
   классами это перебьёт. Поэтому в самих групповых правилах невидимые
   теги исключены отдельно (см. .comment .c_footer > *). Здесь же —
   сеть на будущее: групповых правил с display у нас десятки, и
   следующее такое место найдётся само. */
script, style, template, noscript,
.comment script, .comment style,
.post script, .post style,
.c_footer script, .ddi script, .dd script {
  display: none !important; }

/* ============ КАРКАС ============ */
/* overflow-x держим только на body: на html он отдаёт прокрутку body,
   и тогда window.pageYOffset всегда ноль, а documentElement.scrollHeight
   равен высоте экрана. На этом когда-то сломалась навигация. */
html {
  /* Потолок высоты медиа. Переменной, а не числом прямо в правилах:
     подставленное шаблоном значение после сборки строки уже не
     изменить, а переменную попап настроек переписывает на лету. Здесь
     стоит начальное значение — заводское или то, что человек сохранил
     в прошлый раз (см. tuneLoad). */
  --lm-media-max: ${CFG.mediaCut}vh;
  /* Кегль полей ввода в формах комментария. Переменной, а не числом:
     он зависит от масштаба страницы, а тот меняется без перезагрузки.
     Здесь заводское значение — то, что получается при стопроцентном
     масштабе; настоящее ставит formFontVar. */
  --lm-form-font: ${CFG.formFont}px;
  /* Потолок ширины — доля, а не vw, и это починка формы, уезжавшей за
     правый край при уменьшенном масштабе страницы.

     Разбор был по одному числу. Тык по полю ввода нижней формы дал
     ширину 438 при полях страницы по 12 и border-box: 438 + 24 = 462.
     То есть 100vw вернул 462 в тот момент, когда CSS-ширина документа
     была другой. Safari на iOS считает vw не от текущей раскладки, а от
     видового окна, заданного метатегом, и масштаб страницы на него не
     влияет. При стопроцентном масштабе оба числа совпадают, и всё
     работает; стоит уменьшить масштаб — раскладка становится уже, а vw
     остаётся прежним, и обёртка оказывается на два-три десятка
     пикселей шире экрана. Крестик формы прибит к правому краю обёртки
     (right: 0) и уезжает вместе с ней — ровно то, что видно на снимке.

     Доля таких расхождений не знает: она считается от настоящего
     содержащего блока, а он у html — начальный, то есть та самая
     раскладка, по которой страница и рисуется.

     Числа для проверки печатаются в шапке отчёта: «100vw» рядом с
     CSS-шириной. Разойдутся — сразу видно, вернулось ли. */
  max-width: 100% !important;
  scroll-behavior: auto !important;
  overscroll-behavior-y: contain !important; }
body {
  /* Та же замена и по той же причине. Потолок тут по-прежнему нужен:
     без него широкий чужой узел растянул бы body, и overflow-x: hidden
     обрезал бы уже растянутое. */
  max-width: 100% !important; overflow-x: hidden !important;
  scroll-behavior: auto !important;
  overscroll-behavior-y: contain !important;
  position: relative !important;
  -webkit-text-size-adjust: 100% !important; }

/* Поля по краям вешаем на .l-wrapper: он есть на всех страницах лепры,
   в отличие от .l-i-content_main, которого нет в профиле и подсайтах. */
.l-wrapper, #js-nonfooter {
  /* Доля, не vw: см. разбор у правила html. Именно на этой обёртке
     расхождение и вылезало — она задаёт поля страницы, и её лишние
     двадцать пять пикселей доставались всему, что внутри. */
  min-width: 0 !important; max-width: 100% !important;
  padding-left: ${CFG.pageEdge}px !important;
  padding-right: ${CFG.pageEdge}px !important;
  box-sizing: border-box !important; }

/* Кастомное оформление подлепры лежит на .l-content: своя заливка и своя
   картинка. Поля страницы заданы выше, на .l-wrapper, то есть на два
   уровня выше по дереву — и по краям экрана оставалась белая рамка вокруг
   цветного содержимого. На белых подлепрах её не видно, на цветных она
   читается как ошибка вёрстки.
   Растягиваем .l-content на всю ширину отрицательными полями и возвращаем
   те же пиксели внутренним отступом: текст стоит ровно там же, где стоял,
   а фон доходит до кромки. Признак — класс l-custom_domain на body, лепра
   ставит его подлепрам со своим оформлением; на основном домене там
   l-base_domain, и правило не срабатывает. */
body.l-custom_domain .l-content {
  margin-left: -${CFG.pageEdge}px !important;
  margin-right: -${CFG.pageEdge}px !important;
  padding-left: ${CFG.pageEdge}px !important;
  padding-right: ${CFG.pageEdge}px !important; }

.l-i-wrapper      { padding-bottom: 20px !important; }
.l-content        { min-height: 0 !important; }
.l-content_aside  { display: none !important; }
.l-content_main   { margin-left: 0 !important; float: none !important;
                    width: auto !important; }
.l-i-content_main { margin-left: 0 !important; padding: 0 !important; }
/* Подвал у лепры прижат к низу окна приёмом «липкого подвала»: .l-i-wrapper
   резервирует под него 162 пикселя нижним отступом, а сам подвал теми же
   162 отъезжает вверх отрицательным полем. Отступ мы ужали до 20 (162 под
   две строчки ссылок — это дыра в треть экрана), а отрицательное поле
   осталось, и подвал наезжал на низ страницы на 142 пикселя. Раньше это
   не бросалось в глаза: слева и посередине подвала у нас скрыто, справа
   одна колонка ссылок, и накрывала она обычно пустое место под последним
   постом. Стало видно на Газманове — он высокий. Поле снимаем: подвал
   встаёт там, где кончается страница. */
.l-footer         { min-width: 0 !important; position: static !important;
                    height: auto !important; background: none !important;
                    margin-top: 0 !important; }

/* ============ ШАПКА ============ */
/* Порядок в строке: приветствие (гибкое) - переключатель темы - логотипы,
   затем навигация во всю ширину, затем две колонки со счётчиками и фильтром. */
.l-header {
  margin: 0 0 8px 0 !important; padding: 8px 0 12px !important;
  min-height: 0 !important;
  flex-wrap: wrap !important; align-items: flex-start !important;
  /* у лепры здесь space-between — он растаскивал приветствие,
     переключатель темы и логотипы по краям строки */
  justify-content: flex-start !important;
  border-bottom: 1px solid rgb(214, 212, 212) !important; }

/* выравнивание задаём явно: приветствие с логаутом всегда слева */
.l-header_tagline, .l-i-header_tagline, .b-header_tagline,
.l-header_tagline a { text-align: left !important; }
/* Липкая плашка вокатива. Устройство — у buildTopbar.

   Фона в покое нет намеренно: у самого верха страницы плашка ничем не
   должна отличаться от шапки, из которой её вынули. Фон и разделитель
   появляются, только когда она прилипла, — класс lm-stuck ставит
   наблюдатель за щупом.

   Слой 30: выше содержимого и выше поднятой карточки с раскрытым
   столбиком значков (у той 29), ниже попапа настроек и окна пыни.
   Плашка обязана быть сверху — она для того и липкая. */
#lm-topbar {
  position: -webkit-sticky !important; position: sticky !important;
  top: 0 !important; z-index: 30 !important;
  display: flex !important; flex-wrap: wrap !important;
  align-items: flex-start !important;
  /* От кромки до кромки: отрицательные поля в ширину дежурных полей
     страницы, они же возвращены внутренним отступом. Без этого фон
     прилипшей плашки кончался там же, где кончается колонка, и по бокам
     оставались светлые полосы — содержимое проезжало ровно в них.
     Числа те же, что у .l-wrapper: расходиться им нельзя. */
  margin: 0 -${CFG.pageEdge}px !important;
  padding: 2px ${CFG.pageEdge}px 4px !important;
  background: transparent !important;
  border-bottom: 1px solid transparent !important;
  transition: background-color .15s linear, border-color .15s linear,
              margin-bottom ${NAV_FOLD}ms cubic-bezier(.33,1,.68,1) !important; }

/* Щуп нулевой высоты над плашкой: по нему наблюдатель понимает, что
   страница прокручена. Ноль по высоте, но не display: none — скрытый
   узел наблюдателю не виден вовсе, и он молчал бы всегда. */
#lm-topbar_probe { height: 0 !important; margin: 0 !important; }

/* Прилипшая плашка. Фон — ровно фон страницы, тот же, что в дежурных
   полях по бокам. Сперва он был на пару тонов серее, чтобы плашка
   «слегка отделилась», и это оказалось ошибкой: плашка выделялась
   прямоугольником посреди страницы, а её края — ступеньками. Отделяет
   её линия снизу, и этого довольно; фон обязан быть незаметным.

   Заводской набор — белый; в обратном берём PAGE_ALT, ту же
   переменную, которой красится страница, чтобы они не разошлись. */
html.lm-stuck #lm-topbar {
  background: rgb(255,255,255) !important;
  border-bottom-color: ${FRAME_C} !important;
  /* Отбивка снизу ровно на ту высоту, которую теряет логаут.

     Без неё уход логаута двигал бы всю страницу. Плашка липкая, но
     место в потоке занимает своё, у самого верха документа; стала на
     строку ниже — и всё, что ниже, поднялось на эту строку. Происходит
     это на первых же пикселях прокрутки, то есть ровно там, где человек
     смотрит. Именно этот подскок и виден в первом скролле.

     Отбивка растёт ровно настолько, насколько уменьшается плашка, и с
     той же кривой и выдержкой. Сумма постоянна в каждом кадре —
     содержимое не сдвигается ни на пиксель. Сама отбивка лежит у верха
     документа и в прокрученном виде не видна.

     Величина берётся замером: у логаута своя высота строки, а масштаб
     страницы человек меняет. Запасные 24 — на первый кадр, пока замера
     ещё нет. */
  margin-bottom: var(--lm-topbar-drop, 24px) !important; }
html.lm-cards2.lm-stuck #lm-topbar {
  background: ${PAGE_ALT} !important; }

/* Замер. Классов два, и они разные по сроку жизни. lm-measure приводит
   плашку к прокрученному виду — снимается сразу после замера.
   lm-notrans гасит переходы и держится чуть дольше: до тех пор, пока
   восстановленная высота не будет засчитана. Сними их вместе — браузер
   увидит «было ноль, стало двадцать» и честно проиграет переход, то
   есть логаут разъедется на глазах. Подробности в topbarStuckH.
   Правила стоят рядом с настоящими, чтобы не разошлись: разойдись они,
   замер начал бы врать, а заметить это было бы нечем. */
html.lm-notrans #lm-topbar,
html.lm-notrans #lm-topbar .b-icon_button_logout { transition: none !important; }

html.lm-measure #lm-topbar .b-icon_button_logout { max-height: 0 !important; }

/* Логаут виден только у нетронутой шапки — см. buildTopbar. Уезжает
   высотой, а не display: тот срабатывает мгновенно, и плашка на ходу
   теряла строку разом, дёргая под собой всю страницу.
   display: block обязателен: у лепры это инлайновый блок, а инлайновому
   нулевая высота не мешает занимать строку — строку держит межстрочный
   интервал родителя, и полоса пустоты осталась бы на месте. */
#lm-topbar .b-icon_button_logout {
  display: block !important; overflow: hidden !important;
  max-height: var(--lm-logout-h, 24px) !important; opacity: 1 !important;
  transition: max-height ${NAV_FOLD}ms cubic-bezier(.33,1,.68,1),
              opacity ${Math.round(NAV_FOLD * 0.6)}ms linear !important; }
html.lm-stuck #lm-topbar .b-icon_button_logout {
  max-height: 0 !important; opacity: 0 !important; }

/* Отбивка снизу ровно на ту высоту, которую теряет логаут.

   Без неё уход логаута двигал бы всю страницу. Плашка липкая, но место
   в потоке занимает своё, у самого верха документа; стала на строку
   ниже — и всё, что ниже, поднялось на эту строку. А происходит это на
   первых же пикселях прокрутки, то есть ровно там, где человек смотрит.
   Именно этот подскок и виден в первом скролле.

   Отбивка растёт ровно настолько, насколько уменьшается плашка, и с той
   же кривой и выдержкой. Сумма постоянна в каждом кадре — содержимое не
   сдвигается ни на пиксель. Сама отбивка при этом лежит у верха
   документа и в прокрученном виде не видна, места на экране не занимает.

   Величина берётся замером: у логаута своя высота строки, а масштаб
   страницы человек меняет. Запасные 24 — на первый кадр, пока замера
   ещё нет. */




.l-header_tagline {
  order: 1 !important;
  /* база 0: длинная фраза не выталкивает логотип на новую строку,
     а растягивается по остатку ширины */
  flex: 1 1 0 !important; min-width: 0 !important;
  padding: 0 !important; margin: 2px 0 6px !important; }

#lm-theme {
  order: 2 !important; flex: 0 0 auto !important;
  align-self: flex-start !important;
  width: 34px !important; height: 34px !important;
  margin: 2px 8px 0 0 !important; padding: 0 !important;
  font-size: 17px !important; line-height: 32px !important;
  text-align: center !important; cursor: pointer !important;
  background: transparent !important;
  border: 1px solid rgb(214, 212, 212) !important;
  border-radius: 17px !important; }

.b-logo {
  order: 2 !important; flex: 0 0 auto !important;
  display: inline-block !important; position: static !important;
  align-self: flex-start !important;
  width: auto !important; text-align: left !important;
  margin: 0 0 0 10px !important; }
.b-logo img {
  display: inline-block !important;
  position: relative !important; top: -1px !important;
  width: auto !important; height: auto !important;
  max-height: 40px !important; max-width: 40px !important; }

/* Маска лепры на подсайте: переносится в шапку скриптом и встаёт рядом
   с логотипом подсайта, размером поменьше. */
.l-header .b-logo_subsite {
  order: 2 !important; flex: 0 0 auto !important;
  align-self: flex-start !important;
  position: static !important; float: none !important; width: auto !important;
  margin: 3px 0 0 16px !important; }
.l-header .b-logo_subsite img {
  position: relative !important; top: -1px !important;
  max-height: 32px !important; max-width: 32px !important;
  opacity: .85 !important; }

/* Строка ссылок: всегда в одну линию и по центру, на любом масштабе. */
.l-header_nav { order: 3 !important; flex: 0 0 100% !important;
                width: auto !important; padding: 0 !important;
                margin: 0 !important; line-height: 1.5 !important; }
.b-header_nav {
  display: flex !important; flex-wrap: nowrap !important;
  align-items: center !important; justify-content: center !important;
  gap: 0 8px !important; white-space: nowrap !important;
  font-size: 13px !important; line-height: 1.5 !important; }
.b-header_nav_link { flex: 0 0 auto !important; }
/* медали в навигации были absolute и ложились поверх соседнего текста */
.b-header_nav_link img { display: none !important; }
.b-header_nav_notifications { margin: 0 !important; padding: 0 !important; }
.b-header_nav_fraud { margin: 0 !important; }

/* Переключатель вида: три иконки были absolute от точки left:50%
   и ложились на выпадающий список. */
.b-posts_threshold {
  float: none !important; width: auto !important;
  min-width: 0 !important; min-height: 0 !important;
  flex: 1 1 160px !important; margin: 4px 0 !important; }
.b-index_navigation_holder {
  float: none !important; width: auto !important;
  padding: 6px !important; margin: 18px 0 6px !important;
  display: flex !important; flex-wrap: wrap !important;
  align-items: center !important; gap: 16px !important; }
.b-index_slider, .b-index_slider .b-slider_scale_icons {
  position: static !important; left: auto !important; top: auto !important;
  width: auto !important; height: auto !important;
  display: flex !important; align-items: center !important;
  justify-content: flex-end !important;
  gap: 18px !important; flex: 0 0 auto !important; }
.b-slider_scale_icon {
  position: relative !important; left: auto !important; top: auto !important;
  width: 26px !important; height: 26px !important;
  margin: 4px !important; flex: 0 0 auto !important; }
.b-index_view_about { display: none !important; }

/* Ниже — две строки по два блока. Все они переносятся скриптом прямо
   в .l-header: в исходной разметке они лежат в разных обёртках, а флекс
   умеет строить строку только из соседей по одному родителю.

   Раскладка теперь одна на все страницы — и на главной, и на подсайте:
   счётчики с приглашением написать пост, под ними поиск с порогом.
   На главной было иначе: приглашение занимало целую строку по центру,
   а ниже теснились счётчики, переключатель вида и поиск. Переключатель
   уехал в третью колонку навигационной штуки (см. ниже), пятый блок из
   шапки ушёл, и держать вторую раскладку стало не для чего. Заодно
   исчез набор правил вида .l-header > .b-index_slider ~ … — он опознавал
   главную по соседству с переключателем, а опознавать больше нечем и
   незачем.

   Основы в сумме дают 99% строки. Это и есть цементирование: остатка в
   один процент не хватит следующему блоку никогда, поэтому перенос
   происходит в одном и том же месте при любом масштабе, а не «пока
   помещается». Проценты флекс-основы считаются от содержимого, поля
   прибавляются сверху — поэтому у блоков с полями обязателен
   box-sizing: border-box. Без него пара 55+45 плюс поле в 8 пикселей
   давала 377 при строке в 369, и приглашение уезжало вниз. */
.l-header > .b-header_counters {
  order: 4 !important; flex: 1 1 54% !important;
  box-sizing: border-box !important;
  text-align: left !important; line-height: 1.5 !important;
  height: auto !important;
  /* Строка «N сайтов и M человек» набрана шрифтом в пикселях, а ширина
     колонки зависит от масштаба страницы: при увеличении окно в CSS-пикселях
     сужается, надпись перестаёт помещаться и переносится второй строкой —
     шапка от этого становится выше. Запрещаем перенос: строка остаётся
     одной при любом масштабе, а если места совсем нет, хвост срезается
     многоточием, и высота шапки всё равно не меняется. */
  white-space: nowrap !important;
  min-width: 0 !important;
  overflow: hidden !important; text-overflow: ellipsis !important;
  font-size: 12px !important;
  /* НАСТРОЙКА: первое число — насколько опустить эту надпись.
     Больше — ниже, меньше (можно отрицательное) — выше.
     Соседние блоки не двигаются: отступ только у неё. */
  margin: 8px 0 0 0 !important; }
/* внутри две ссылки — они тоже не должны рваться по своим пробелам */
.l-header > .b-header_counters a { white-space: nowrap !important; }

.l-header > .b-header_nav_new_post {
  order: 5 !important; flex: 1 1 45% !important;
  box-sizing: border-box !important; min-width: 0 !important;
  text-align: right !important; font-size: 12px !important;
  line-height: 1.5 !important;
  /* фраза стала короткой («Все ждут новый пост!»), но при увеличенном
     масштабе строка сужается — перенос всё равно запрещаем, иначе шапка
     подрастёт на строку; хвост при нужде срезается многоточием */
  white-space: nowrap !important;
  overflow: hidden !important; text-overflow: ellipsis !important;
  /* тот же отступ сверху, что у счётчиков рядом, — иначе строки текста
     в паре стоят на разной высоте */
  margin: 8px 0 0 !important; padding: 0 0 0 8px !important; }

/* Строка баланса магазина. В разметке лепры она лежит внутри того же
   приглашения написать пост, второй строкой после <br>, и потому попадала
   в правую колонку шириной 45%. «У вас на счету 0.00 ЛВ, пополнить счет.»
   — 39 знаков кеглем 12, это около 243 пикселей против примерно 200
   доступных при обычном масштабе и 169 при увеличенном. Перенос в колонке
   запрещён, ужимать нечего, вот хвост и уходил за край.
   Скрипт вынимает её из блока отдельным <div class="lm-balance">, и здесь
   она получает собственную строку шапки во всю ширину, по центру. Высота
   шапки от этого не меняется: две строки текста давал сам блок, теперь
   их дают блок и вынесенная строка.
   Перенос тут не запрещаем намеренно: в отличие от колонок, у строки во
   всю ширину при сильном увеличении масштаба перенос — меньшее зло, чем
   обрезанный хвост. */
.l-header > .lm-balance {
  order: 6 !important; flex: 0 0 100% !important;
  box-sizing: border-box !important; min-width: 0 !important;
  text-align: center !important; font-size: 12px !important;
  line-height: 1.5 !important;
  /* НАСТРОЙКА: первое число — насколько отбить строку от пары над ней.
     Было ноль (ровно так она стояла внутри блока), стало 3 — по просьбе,
     «прям немного». Ровно на эти 3 пикселя шапка и подросла. */
  margin: 3px 0 0 !important; padding: 0 !important; }

/* Правил вида .l-header > .b-header_search и .l-header > .b-posts_threshold
   здесь больше нет: обоих блоков в шапке не бывает. Поиск и порог постов
   уехали в третью колонку навигационной штуки следом за переключателем
   вида — там же и описаны. Единственное исключение — страницы с
   вкладками: на них поиск по-прежнему стоит в конце строки ссылок, и
   правила для этого случая лежат ниже, под заголовком про сжатую шапку.
   Дохлые правила в этом файле уже однажды прожили несколько версий
   незамеченными, поэтому убраны сразу, а не оставлены «на всякий». */

/* Порядок в форме поиска: лупа, затем поле, всё прижато к правому краю.
   Правила заданы одним блоком по id формы, а не по .l-header: во-первых,
   нужны и там, где шапка не перебрана скриптом; во-вторых, два набора
   правил на один элемент уже однажды дали зависимость от порядка. */
#js-header_search_form {
  display: flex !important; align-items: center !important;
  justify-content: flex-end !important; gap: 4px !important; }
/* Обёртка поля мерилась на 22 пикселя шире самого поля при нулевых
   отступах и без псевдоэлементов — откуда берётся её ширина, по цифрам
   так и не сошлось. display:contents убирает её коробку целиком:
   поле становится прямым флекс-элементом формы, и мерить больше нечего. */
#js-header_search_form .b-header_search_input_holder {
  display: contents !important; }
#js-header_search_form .b-header_search_input_holder::before,
#js-header_search_form .b-header_search_input_holder::after {
  content: none !important; display: none !important; }
/* Нижний предел, ниже которого поле сжиматься не должно: строкой выше
   ему разрешено уступать место счётчикам, а поле шириной в сантиметр
   бесполезно. */
#js-header_search_form .i-form_text_input {
  order: 2 !important; flex: 0 1 auto !important;
  min-width: 90px !important; margin: 0 !important; }
#js-header_search_form input[type="submit"] { display: none !important; }
#js-header_search_form .b-icon_button_search {
  order: 1 !important; flex: 0 0 auto !important;
  position: static !important; inset: auto !important; margin: 0 !important; }

/* Обратный порядок (поле, за ним лупа, всё влево) раньше задавался
   отсюда — для поиска, стоявшего в шапке отдельной строкой. Строки этой
   больше нет, а внутри навигационной штуки те же правила описаны своим
   блоком: селектор от .l-header тут не сработал бы вовсе. */

/* Опустевшие обёртки. Важно: у них нет order, а значит он равен нулю —
   такой блок встаёт в строке ПЕРЕД приветствием (order:1) и сдвигает его
   вправо на свою ширину. Именно поэтому приветствие казалось центрированным. */
.l-header_aside, .b-header_aside { order: 9 !important; }
.l-header_aside:empty, .b-header_aside:empty,
.b-index_navigation_holder:empty { display: none !important; }

/* ---- Сжатая шапка на страницах с панелью вкладок ----
   «Мои вещи», инбокс, избранное, настройки, социализм, приложения несут
   под шапкой собственную панель вкладок, где уже есть и «мои вещи», и
   «избранное», и инбокс. Сверху они дублируются, а высота на телефоне
   дороже полноты. Здесь шапка сжимается до двух строк: приветствие с
   логаутом, затем «Мои вещи N», инбокс, колокольчик и поиск.

   Признак страницы ставит скрипт классом lm-tabs на <html>. Из CSS его
   не вывести: панель вкладок лежит в разметке ПОСЛЕ шапки, а обратного
   соседа выбрать нечем. */
html.lm-tabs .b-header_counters,
html.lm-tabs .b-header_nav_new_post,
html.lm-tabs .lm-balance,
html.lm-tabs .b-header_nav_fraud,
html.lm-tabs .b-header_nav a[href*="/my/favourites"] {
  display: none !important; }

/* Поиск скрипт переносит в конец строки ссылок — тем же флекс-элементом,
   что и сами ссылки. Именно внутрь .b-header_nav, а не в .l-header:
   строка ссылок занимает всю ширину, и сосед по .l-header встал бы
   отдельной строкой, то есть ровно тем, от чего мы уходим.
   Штатные position/left у блока поиска сдвигали его на пиксель влево —
   внутри флекса это лишнее. */
html.lm-tabs .b-header_nav .b-header_search {
  flex: 1 1 auto !important; min-width: 0 !important;
  position: static !important; left: auto !important;
  margin: 0 0 0 4px !important; padding: 0 !important; }
/* Ширина поля задана лепрой в процентах от обёртки (86%), а обёртка у нас
   display:contents, то есть коробки не имеет. Переводим на флекс: поле
   занимает остаток строки и сжимается до предела из настроек. */
html.lm-tabs #js-header_search_form .i-form_text_input {
  width: auto !important; flex: 1 1 auto !important;
  min-width: ${CFG.tabsSearchMin}px !important; }
/* Лупа — справа от поля, а не слева. В базовом правиле порядок обратный
   (лупа первой), и пока поле стоит в своей трети колонки, это ничему не
   мешает. Здесь мешает: на время ввода форма оттягивается влево до
   кромки экрана и ложится поверх строки ссылок, и первым на «Мои вещи»
   наезжает именно значок — мелкий, с прозрачным полем вокруг, отчего
   выходит каша из лупы и букв. Поле, вставшее на то же место, закрывает
   ссылки своей белой заливкой — то есть выглядит как поле, которое
   раскрылось поверх, а не как наложение.
   Селектор тяжелее базового И стоит ниже по файлу: спор решается
   одинаково и по весу (браузер), и по порядку (jsdom). */
html.lm-tabs #js-header_search_form .i-form_text_input { order: 1 !important; }
html.lm-tabs #js-header_search_form .b-icon_button_search { order: 2 !important; }

/* ============ ЛЕНТА И ПОСТЫ ============ */
/* Белая полоса справа получалась из двух вложенных width:98%,
   плюс у поста было 270px внутреннего отступа под правую колонку. */
.b-posts_holder { width: 100% !important; padding-top: 0 !important; }
/* Пост в рамке — той же, что и комментарий: один пиксель, скругление
   восемь, цвет едва темнее фона.

   Здесь, в отличие от комментария, рамка нарисована прямо на узле, а не
   на псевдоэлементе, и это не разнобой, а разные условия. У комментария
   рамка на самой коробке раздвинула бы содержимое; тут внутренние поля
   всё равно приходится задавать заново, так что двух лишних пикселей
   никто не заметит. Плюс у лепры .post::before и ::after свободны не
   вполне: ::after она отводит под вертикальные линии веток.

   Три сопутствующие правки, без которых рамка выглядит нелепо.

   Первая: нижний отступ 30 пикселей у лепры внутренний. Он и разделял
   посты, пока границы не было; с рамкой он оказался бы ВНУТРИ неё —
   пустая полоса под подписью. Переносим разделение наружу, в margin.

   Вторая: боковые поля. Без них текст упирается в рамку. Восемь — как у
   комментария; картинки при этом теряют шестнадцать пикселей ширины,
   но с рамкой прижатая к ней вплотную картинка смотрится ошибкой.

   Третья: overflow. У лепры на посте overflow: hidden — старый способ
   обойти обтекание, при том что в разметке и так стоит <div class=clear>.
   Со скруглением он мешает: столбик значков, всплывающий из подписи
   вверх, на коротком посте обрезался бы по границе. Снимаем.

   box-sizing обязателен: без него рамка добавила бы два пикселя к
   ширине, и пост вылез бы за колонку. */
.post {
  float: none !important; width: auto !important;
  box-sizing: border-box !important;
  overflow: visible !important;
  padding: 6px 8px 8px !important;
  margin: 0 0 14px !important;
  border: 1px solid ${FRAME_C} !important;
  border-radius: ${FRAME_R}px !important;
  background-color: ${CARD_BG} !important;
  background-image: ${CARD_GLOW} !important; }
/* Заголовок и тело поста своих правых полей больше не требуют: их даёт
   рамка. */
.post .dt { padding-right: 0 !important; }
/* Подпись поста отделена от тела не чертой и не собственной подложкой,
   а краем общего свечения карточки: внизу оно слабее, и подпись темнеет
   сама. Черта тут была и убрана — на скруглённой коробке она читалась
   третьей линией подряд; подложка была и тоже убрана, см. CARD_GLOW.

   Поля отрицательные по краям и снизу: подпись должна дотягиваться до
   рамки, а не висеть внутри полей поста. Числа те же, что у полей
   .post (8 по бокам, 8 снизу), только со знаком минус — расходиться им
   нельзя, иначе подложка либо не достанет до рамки, либо вылезет за неё.

   Скругление снизу на пиксель меньше рамочного: подложка лежит ВНУТРИ
   рамки в один пиксель, и дуга у неё по определению чуть круче. С
   одинаковым радиусом между рамкой и подложкой в углах остаётся
   светлый серпик. */
.dd {
  position: relative !important;
  margin: ${6 - FOOT_LIFT}px -8px -8px !important;
  padding: ${5 + FOOT_LIFT}px 8px 5px !important;
  border-radius: 0 0 ${FRAME_R - 1}px ${FRAME_R - 1}px !important;
  /* Своего фона у подписи нет: её отделяет край свечения карточки.
     Отрицательные поля и скругление оставлены — они держат подпись в
     границах рамки и пригодятся, если фон когда-нибудь вернётся. */
  background: none !important;
  /* Жёлоба под голосовалку здесь больше нет, и это отдельная история.
     Раньше слева резервировалось 88 пикселей, а голосовалка ставилась
     туда абсолютно. Ширина жёлоба при этом была догадкой: настоящая
     ширина голосовалки зависит от числа знаков в счётчике, и на
     четырёхзначном рейтинге (7250 — такие в ленте попадаются) она
     переваливала за 88 и наезжала на слово «Написал». Значок закрепа
     сдвигал подпись ещё правее и делал наезд заметнее.
     Подобрать жёлоб пошире значило бы отдать пустое место всем постам
     ради нескольких; мерить каждый пост — платить раскладкой за то, что
     флекс делает бесплатно. Поэтому голосовалка теперь стоит в самой
     строке подписи первым элементом (её переносит туда moveVoteToFooter).
     Наехать ей больше не на что: соседи по флекс-строке не пересекаются
     по построению, а не помещается — строка переносится.
     Заодно ушла вторая жалоба: абсолютная голосовалка была прибита к
     верху блока, а подпись центрировалась внутри своей строки, и при
     переносе подписи на две строки они оказывались на разных уровнях
     взгляда. Соседи по одной строке с align-items: center такого не
     умеют. */
  /* Высота строки задана ниже, в правиле подписей поста: строки там
     переносятся часто, и 1.4 не хватало — соседние наезжали друг на
     друга. Держим её в одном месте, а не в двух. */
  /* Кегль здесь ни на что не влияет и оставлен для наследования теми
     редкими кусками .dd, что лежат мимо .ddi: у самой подписи он задан
     отдельным правилом ниже, потому что лепра ставит .post .ddi кегль
     10 напрямую, и наследование от .dd до него не доходит. */
  font-size: 13px !important; }

/* Подпись — флекс-строка: промежутки задавались пробелами в разметке
   и полями у ссылок, отсюда рыхлость и перенос крестика на третью строку.

   Кегль задан ЗДЕСЬ, а не унаследован от .dd, и это была настоящая
   ошибка, прожившая долго: у лепры кегль 10 задан прямо на .post .ddi
   — на самой подписи, без !important, но и без конкурентов с
   нашей стороны. Наше правило висело на родителе .dd, наследование до
   .ddi не доходило, и подпись всё это время рисовалась десятым кеглем,
   а не тринадцатым, как значилось в комментарии. Прошлая правка «13 →
   14» поэтому и не дала ничего видимого: менялось число, которое никого
   не касалось.
   Мораль: правило на родителе — не то же самое, что правило на
   элементе, если у элемента есть своё. Проверять надо вычисленный
   стиль того узла, о котором речь. */
.dd .ddi {
  display: flex !important; flex-wrap: wrap !important;
  align-items: center !important; gap: 2px 6px !important;
  font-size: 13px !important; line-height: 1.4 !important; }
.dd .b-post_controls {
  display: inline-flex !important; align-items: center !important;
  gap: 8px !important; white-space: nowrap !important; margin: 0 !important; }
/* Все значки подписи скрипт складывает в один контейнер .lm-icons.
   Раньше они лежали в двух разных обёртках лепры с разными метриками,
   и выровнять их правилами не удавалось: крестик всё время проваливался
   ниже. Соседи по одному флекс-боксу разъехаться не могут. */
.dd .lm-icons {
  display: inline-flex !important; align-items: center !important;
  gap: 10px !important; height: 16px !important;
  vertical-align: middle !important; }
.dd .lm-icons > span:not(.hidden):not(.b-post_interest_info),
.dd .lm-icons a:not(.hidden):not(.b-post_interest_info) {
  display: inline-flex !important;
  align-items: center !important; justify-content: center !important;
  align-self: center !important;
  /* У лепры .b-icon_button задан position:relative, и отдельным значкам
     приписаны сдвиги top. Внутри флекс-бокса это и разбрасывало их по
     вертикали: «?» уходил на 4px вверх, крестик на 7px вниз. */
  position: static !important; inset: auto !important;
  top: auto !important; bottom: auto !important;
  transform: none !important;
  height: 16px !important; line-height: 16px !important;
  font-size: 14px !important;
  margin: 0 !important; padding: 0 !important;
  text-decoration: none !important; }
.dd .lm-icons a i, .dd .lm-icons a b {
  position: static !important; top: auto !important;
  height: 16px !important; line-height: 16px !important;
  vertical-align: middle !important; }
/* неактивные значки лепра прячет классом — не мешаем */
.dd .lm-icons a.hidden { display: none !important; }
/* Справочная ссылка «?»: в ленте лепра её показывает, на телефоне она
   только занимает место. Скрытие вынесено и в исключение основного
   правила выше — иначе оно перебивало это по весу селектора. */
.b-post_interest_info,
.dd .lm-icons .b-post_interest_info { display: none !important; }
.dd .lm-icons svg {
  display: block !important; width: 14px !important; height: 14px !important; }
/* Перерисованные значки. Три правки, каждая снимает наследство того
   вида, в котором значок был до вектора.

   Фоновая картинка. У .post_icon и .c_icon рисунок лежал фоном
   (post-icon.gif), причём на странице поста лепра пишет его ИНЛАЙНОВЫМ
   стилем. Под нашим значком он остался бы вторым слоем; !important
   перебивает и правило, и инлайн.

   Заливка. У «прочитано» лепра красит фигуры правилом
   .b-mark_as_read_control .b-svg-icon svg * { fill: rgb(187,187,187) } —
   оно попадает и на наши контуры, залив их серым изнутри. Возвращаем
   fill: none и цвет обводки; звезда «из избранного» залита нарочно, и
   её исключаем поимённо, а не отменой правила целиком.

   Метрики. У .b-controls_button задана коробка 20 на 20 со сдвигом
   top: 7 и минусовыми полями — приём для строки, где значок сидел на
   базовой линии. В обойме высоту и центрирование задаёт флекс, а сдвиг
   уводил крестик вниз. */
.lm-ico_host {
  background-image: none !important;
  position: static !important; top: auto !important;
  margin: 0 !important; padding: 0 !important;
  /* Один тон на все значки обоймы. До вектора у каждого был свой: лепра
     красила крестик в 187, стрелку к родителю в 136, «в мои вещи»
     ссылочным синим, а страничку не красила вовсе — она была картинкой.
     Собранные в один столбик, они смотрелись набором из разных мест.
     Тот же серый, что и у самой точки, — значки и точка теперь одно
     семейство.
     currentColor у фигур внутри берётся отсюда, поэтому цвет задан
     один раз здесь, а не в каждом рисунке. */
  color: rgb(120,120,120) !important; }
.lm-ico_host svg.lm-ico *,
.dd .lm-icons .lm-ico_host svg.lm-ico *,
#js-comments_holder .lm-ico_host svg.lm-ico * {
  fill: none !important; stroke: currentColor !important; }
.lm-ico_host svg.lm-ico [fill="currentColor"],
.dd .lm-icons .lm-ico_host svg.lm-ico [fill="currentColor"],
#js-comments_holder .lm-ico_host svg.lm-ico [fill="currentColor"] {
  fill: currentColor !important; }
/* Пустые обёртки под фоновые спрайты лепры рисовали мелкие чёрточки по
   краям значков. Но в такой же <span class="b-svg-icon"> завёрнут svg
   галочки — поэтому скрываем только ПУСТЫЕ, по содержимому, а не по тегу. */
.dd .lm-icons a em:empty, .dd .lm-icons a span:empty { display: none !important; }

.dd .post_icon { margin: 0 !important; }
/* .c_show_user — декоративная точка лепры, на телефоне рисуется
   случайным глифом и сбивает высоту строки */
.dd .c_show_user { display: none !important; }
.b-paginator { padding: 20px 10px 40px !important; }
.b-post_tags {
  float: none !important; width: auto !important;
  padding-right: 0 !important; margin: 0 0 10px !important; }
.b-post_tags_form .i-form_text_input { width: 60% !important; }

.post .p_body, .comment .c_body {
  font-size: 17px !important; line-height: 1.45 !important;
  word-wrap: break-word !important; overflow-wrap: break-word !important; }
.post img, .comment img, .p_body img, .c_body img {
  max-width: 100% !important; width: auto !important; height: auto !important;
  /* Потолок высоты — см. CFG.mediaCut. Стоит здесь же, рядом с потолком
     ширины: обе величины про одно и то же — не дать медиа занять больше
     места, чем ему отведено. Пропорции сохраняются сами, ширина у
     картинки auto и следует за высотой.
     object-fit не нужен и вреден: он растянул бы картинку в коробку
     заданного размера, а нам нужно, чтобы уменьшилась сама коробка. */
  max-height: var(--lm-media-max, ${CFG.mediaCut}vh) !important; }

/* Узкое медиа — по центру колонки. Само по себе это вкусовщина, но с
   появлением потолка по высоте она перестала быть вкусовщиной: до него
   картинка почти всегда упиралась в ширину и стояла от края до края, а
   теперь высокая ужимается и по ширине — и висит у левого края, оставив
   справа пустую полосу в треть экрана.

   Центрируем не любую картинку в теле, а только ту, которую лепра сама
   пометила как содержимое (js-image_in_comments и её же увеличенный
   вариант). Разница существенная: блочное выравнивание строчной
   картинки выбросило бы её из строки, а в теле поста встречаются и
   такие — значки, стрелки, кнопки плеера. По сохранённым страницам все
   картинки-содержимое несут этот класс и всегда отбиты <br> в
   отдельную строку, так что превращение их в блок ничего не ломает.
   Если однажды попадётся нецентрованная — значит лепра выдала её без
   класса, и правило надо расширять по факту, а не наугад. */
.p_body img.js-image_in_comments, .c_body img.js-image_in_comments,
.p_body img.js-image_in_comments_original,
.c_body img.js-image_in_comments_original,
.b-media_player_preview_pic_holder img {
  display: block !important;
  margin-left: auto !important; margin-right: auto !important; }
.post iframe, .comment iframe, .b-video, .video_holder {
  max-width: 100% !important; }
pre, code { white-space: pre-wrap !important; word-break: break-word !important; }

/* у увеличенной картинки лепра прописывает width:3000px */
.c_body img.js-image_in_comments_original,
.p_body img.js-image_in_comments_original,
img.js-image_in_comments_original {
  width: auto !important; max-width: 100% !important; height: auto !important; }

/* Форма быстрого поста с кнопкой YARRR: скрыта, для создания поста
   есть отдельная кнопка в шапке. Чтобы вернуть — удалите эту строку. */
.b-new_post_miniform, .b-new_post_miniform_footer { display: none !important; }

/* ============ КОММЕНТАРИИ ============ */
.post_comments_page, #js-comments { padding: 0 !important; }
/* .b-post_comments у лепры имеет width:90% — десятая часть ширины уходила
   впустую, и комментарии не доходили до правого края. Панель навигации
   к этому отношения не имеет: она фиксированная и места не занимает. */
.b-post_comments, #js-comments_holder {
  width: 100% !important; max-width: 100% !important;
  box-sizing: border-box !important; }
/* Правого поля тут больше не снимаем: его задаёт рамка поста, а это
   правило тяжелее и обнуляло бы его только на странице треда — текст
   упирался бы в рамку на одной странице из восьми. Остальное лепре
   по-прежнему нужно поправить: у неё пост на этой странице плавающий и
   с полем под правую колонку. */
.post_comments_page .post {
  margin-right: 0 !important; width: auto !important;
  float: none !important; }
#js-comments_holder .comment { padding-bottom: 10px !important; }

/* Тонкая рамка вокруг каждого комментария. В длинном треде они иначе
   сливаются в сплошное полотно: отступы между ними есть, но глазу не за
   что зацепиться, и где кончился один и начался другой — видно только
   по подписи.

   Рисуем НЕ на .c_i, а на её псевдоэлементе, и это не хитрость, а
   единственный способ не тронуть раскладку. У лепры .c_i::before уже
   объявлен как position: absolute с inset: 0, сплошной рамкой нулевой
   толщины — заготовка под её собственную подсветку новых
   комментариев рамкой. То есть коробка нужного размера уже висит поверх
   комментария, ей остаётся задать толщину и цвет. Рамка на самой .c_i
   раздвинула бы её на два пикселя и сдвинула бы всё внутри; рамка на
   .comment обвела бы ещё и отступ ступеньки, то есть у вложенных веток
   начиналась бы у левого края экрана.

   pointer-events: none обязательно. Псевдоэлемент лежит поверх всего
   содержимого комментария и, будучи невидимым, исправно ловил бы
   нажатия — по ссылкам, по голосовалке, по чему угодно. Прозрачность не
   есть непроницаемость, у нас это уже было с кнопкой «наверх».

   Цвет почти белый: рамка должна разделять, а не расчерчивать. На
   подсвеченных комментариях (у лепры новые красятся фоном) она читается
   так же, потому что светлее любого из этих фонов ненамного.

   Низ .c_i у лепры прижат (padding-bottom: 1px), и подпись упиралась бы
   в рамку — добавляем воздуха снизу и по бокам. */
.comment .c_i {
  padding: 6px 8px 5px !important;
  /* Единственное объявление во всём файле БЕЗ !important, и намеренно.
     Подсветку новых комментариев лепра вешает на селектор
     .highlight2 .new .c_i — он тяжелее нашего, но обычный. С !important мы бы его
     перебили и погасили подсветку начисто: проверка это и показала,
     новый комментарий стал таким же, как все.
     Без !important расстановка правильная: у обычного комментария
     соперников нет и цвет берётся наш, у нового побеждает лепровский.

     Осторожно с проверкой этого места в jsdom: он решает споры правил
     по порядку объявления, а наша таблица стилей стоит в head после
     лепровской — значит, покажет наш цвет всегда, и на новом
     комментарии тоже. Браузер решит иначе, по весу. Единственный
     верный способ проверить — считать вес селекторов вручную (в
     проверках это делает winner из t-card.js). Не «чинить» это правило
     по показаниям jsdom. */
  background-color: ${CARD_BG};
  /* Свечение можно и важным: оно прозрачное и подсветку не закрывает, а
     пропускает. Важно тут именно то, что цвет и рисунок разведены по
     разным свойствам — иначе сокращённая запись погасила бы леприну
     заливку заодно с нашей. */
  background-image: ${CARD_GLOW} !important;
  /* Скругление на самой коробке, хотя рамку рисует псевдоэлемент. Оно
     нужно не рамке, а ЗАЛИВКЕ: новые комментарии лепра подсвечивает
     фоном на .c_i (в её настройках это «мерзкий цвет»), а фон красит
     всю коробку целиком, прямыми углами. Из-под скруглённой рамки такие
     углы торчали четырьмя жёлтыми треугольничками. Радиус обрезает фон
     по той же дуге. */
  border-radius: ${FRAME_R}px !important; }

/* Цветная полоса вдоль комментария автора поста. У лепры это
   .b-c_o — пустой блок на весь комментарий с рамкой только слева;
   цвет ей проставляется в разметке, поэтому трогаем лишь геометрию.
   Углы у неё тоже прямые, и слева она выезжала за дугу нашей рамки.

   pointer-events здесь не украшение, а починка: блок растянут на весь
   комментарий (inset: 0) и лежит поверх содержимого. Пока он был
   прямоугольным и незаметным, это выглядело как «в комментариях автора
   не нажимаются ссылки» — и на десктопе у лепры ровно так и есть. */

.comment .c_i .b-c_o {
  /* Толщина втрое против лепровского пикселя: на телефоне полоска в
     один пиксель на цветном фоне почти не читается, а смысл у неё
     ровно один — с одного взгляда отличить комментарий автора поста. */
  border-left-width: 3px !important;
  border-radius: ${FRAME_R}px !important;
  /* Полоса обязана лежать выше подложки подписи. По правилам отрисовки
     позиционированный узел и так рисуется после фонов блоков, но
     подложка у подписи не простая заливка, а градиент со своим
     скруглением, и полагаться на порядок фаз тут не хочется: стоит
     подписи по любой причине завести свой слой — и нижняя треть полосы
     окажется закрашенной. Собственный слой у полосы это исключает.
     Единица, а не больше: выше подложки, но ниже всего нашего. */
  z-index: 1 !important;
  pointer-events: none !important; }
.comment .c_i::before {
  border-width: 1px !important;
  border-color: ${FRAME_C} !important;
  border-radius: ${FRAME_R}px !important;
  pointer-events: none !important; }
${indentRules()}

/* Подпись в одну флекс-строку. div.ddi — блок, из-за него голосование
   уезжало на отдельную строку; display:contents убирает его собственный
   бокс, и ссылки попадают в общий ряд с кнопками. */
/* Подпись комментария того же семейства, что и подпись поста: тот же
   кегль, те же зазоры, то же центрирование. Раньше она была на пиксель
   мельче и на пиксель теснее — разница ничем не оправдывалась и просто
   читалась как небрежность.
   Голосовалка в подписи комментария стоит первой, как и у поста, —
   порядком, а не переносом узла (правило .comment .c_footer .vote ниже).

   Здесь же — отделение подписи от тела растушёванной подложкой, ровно
   как у поста. Отдельным правилом это было бы вторым объявлением того же
   селектора, то есть дублем; держим всё в одном месте.
   Поля отрицательные по краям и снизу: подпись должна дотягиваться до
   рамки, а не висеть внутри полей .c_i. Числа те же, что у полей .c_i
   (8 по бокам, 5 снизу), только со знаком минус — расходиться им
   нельзя, иначе подложка либо не достанет до рамки, либо вылезет.
   Скругление снизу на пиксель меньше рамочного: подложка лежит ВНУТРИ
   рамки в один пиксель, и дуга у неё чуть круче. С одинаковым радиусом
   в углах между рамкой и подложкой остаётся светлый серпик. */
.comment .c_footer {
  display: flex !important; flex-wrap: wrap !important;
  align-items: center !important;
  /* Просвет по вертикали нулевой: строки подписи разводит их
     собственный margin, а два источника отступа между одними и теми же
     узлами всегда кончаются двойным. По горизонтали 6 остаются — они
     работают внутри строки. */
  gap: 0 6px !important;
  line-height: 1.4 !important; font-size: 13px !important;
  margin: ${5 - FOOT_LIFT}px -8px -5px !important;
  padding: ${4 + FOOT_LIFT}px 8px 4px !important;
  border-radius: 0 0 ${FRAME_R - 1}px ${FRAME_R - 1}px !important;
  background: none !important; }

/* Лепра ставит кегль 10 и здесь, на .c_footer .ddi, — так что правило
   на родителе до подписи снова не дошло бы. Задаём на самом узле. */
.comment .ddi { font-size: 13px !important; }
/* :not(.b-button) — чтобы не перекрывать логику показа стрелок
   сворачивания: они управляются отдельными правилами ниже */
/* .ddi исключён: он должен остаться display:contents, иначе становится
   единственным блочным ребёнком флекса и всё содержимое подписи
   выстраивается обычным потоком в столбик. */
/* :not(script):not(style) обязательны, и это не перестраховка.
   Лепра дописывает после сильно заминусованных комментариев маленький
   <script> с вызовом initCommentCollapse — прямо в подпись. Невидимость
   у <script> держится на обычном display: none из встроенной таблицы
   браузера, и это правило её перебивало: код вываливался на страницу
   текстом. Вылезало «периодически» ровно потому, что скрипт есть не у
   всех комментариев, а только у свёрнутых по минусам.
   Общее правило «script, style { display: none !important }» тут не
   спасает: при равном !important побеждает более весомый селектор, а
   этот весомее. Исключать надо здесь. */
/* Строки подписи (.lm-fline) из этого правила исключены, и это не
   мелочь — на них оно ломало сразу две вещи. Строка обязана быть
   флексом: только тогда работают её просветы (gap) и выравнивание по
   центру. Правило переводило её в inline-block, флекс исчезал, и
   получалось ровно то, что видно глазом: слова в первой строке
   слипались (просветов нет), а сама подпись раздувалась по высоте
   (строчный поток вместо флекса, да ещё с двадцативосьмипиксельной
   голосовалкой внутри).
   Заодно правило пришлось продлить внутрь строк: после раскладки
   значки и ссылки лежат не прямыми детьми подвала, а внутри .lm-fline,
   и без этого потеряли бы приведение к общим метрикам. */
.comment .c_footer a:not(.b-button), .comment .ddi a:not(.b-button),
.comment .c_footer > *:not(.b-comment_thread_collapse):not(.ddi):not(.lm-fline):not(script):not(style),
.comment .c_footer .lm-fline > *:not(.b-comment_thread_collapse):not(script):not(style),
.comment .ddi > *:not(.b-comment_thread_collapse):not(script):not(style) {
  display: inline-block !important;
  padding: 1px 0 !important; margin: 0 !important; }

/* Шеврон сворачивания ветки скрыт целиком — правило внизу файла, в
   разделе про значки под точкой. Здесь раньше стояло полторы дюжины
   правил, приводивших его к общей высоте строки; все они относились к
   узлу, которого теперь не видно, и убраны.
   Класс .b-comment_thread_collapse при этом остаётся упомянутым в
   исключениях соседних правил (:not(...) выше и ниже): узел на месте,
   просто не показывается, и попади он под общее правило кнопок — занял
   бы в подписи целую строку пустоты. */


/* Кнопки управления постом: у лепры height:13px с обрезкой, а подпись
   поднята на 7px вверх. Класс общий, используется не только свёрнутыми
   ветками, поэтому правило нужно и при скрытом сворачивании. */
/* :not(.b-comment_thread_collapse) — у кнопки сворачивания веток тот же
   класс, а display:block заставлял её занимать целую строку в подписи. */
.b-post_my_post_controls_button:not(.b-comment_thread_collapse) {
  display: block !important; height: auto !important;
  overflow: visible !important; vertical-align: baseline !important; }
.b-comment_thread_collapse {
  height: auto !important; overflow: visible !important; }
.b-post_my_post_controls_button .b-button,
.b-post_my_post_controls_button .b-button_caption {
  position: static !important; top: auto !important;
  margin-left: 0 !important; }
.b-post_my_post_controls_button .b-button {
  display: inline-block !important; padding: 4px 0 !important; }
.b-post_my_post_controls_button .b-button_caption {
  white-space: normal !important; }

/* Обёртка .ddi растворяется: её содержимое становится прямыми элементами
   флекс-строки подписи. Объявлено после правил выше — иначе они его
   перебивали, и подпись рассыпалась в столбик. */
.comment .c_footer .ddi { display: contents !important; }

/* Показ одной из двух стрелок задаём сами и объявляем ПОСЛЕ всех правил
   для ссылок в подписи: так результат не зависит ни от специфичности,
   ни от порядка — оба фактора работают в одну сторону. */
#js-comments_holder .comment .b-button__collapse { display: none !important; }
#js-comments_holder .comment .b-comment_thread__collapse .b-button__collapse {
  display: inline-block !important; }
#js-comments_holder .comment .b-button__expand { display: inline-block !important; }
#js-comments_holder .comment .b-comment_thread__collapse .b-button__expand {
  display: none !important; }

/* Значки в подписи комментария: «поделиться», крестик и точка. У каждого
   свои метрики и position:relative от лепры, из-за чего крестик уходил
   с общей горизонтали. Приводим к одной высоте и гасим смещения. */
#js-comments_holder .c_footer .b-button_share,
#js-comments_holder .c_footer .b-icon_button_close,
#js-comments_holder .c_footer .b-controls_button {
  display: inline-flex !important;
  align-items: center !important; justify-content: center !important;
  align-self: center !important;
  position: static !important; inset: auto !important;
  top: auto !important; bottom: auto !important;
  height: 18px !important; line-height: 18px !important;
  font-size: 14px !important;
  margin: 0 !important; padding: 0 !important; }
#js-comments_holder .c_footer .b-button_icon,
#js-comments_holder .c_footer .b-svg-icon {
  display: inline-flex !important; align-items: center !important;
  position: static !important; height: 18px !important; }
#js-comments_holder .c_footer .b-button_share svg {
  display: block !important; width: 14px !important; height: 14px !important; }
/* Размер наших значков в подписи комментария. У поста то же самое даёт
   правило .dd .lm-icons svg; здесь своё, потому что списки селекторов
   у поста и комментария разные — см. разбор у столбика. Селектор с
   идентификатором заведомо тяжелее любого лепровского на этих узлах и
   стоит ниже них по файлу. */
#js-comments_holder .c_footer svg.lm-ico {
  display: block !important; width: 14px !important; height: 14px !important; }
/* обёртки значка «поделиться» сдвигали его вверх на пару пикселей */
#js-comments_holder .c_footer .b-button_share .b-button_icon,
#js-comments_holder .c_footer .b-button_share .b-svg-icon {
  position: static !important; top: auto !important;
  vertical-align: middle !important;
  height: 18px !important; line-height: 18px !important; }
#js-comments_holder .c_footer em:empty { display: none !important; }

/* кнопка обновления комментариев уезжала за левый край */
.b-comments_controls {
  padding-left: 0 !important; margin-left: 0 !important;
  display: flex !important; flex-wrap: wrap !important;
  gap: 2px 6px !important; font-size: 14px !important; }
.b-comments_controls a { display: inline-block !important;
                         padding: 6px 4px !important; }
.b-comments_controls > a.b-svg-icon,
.b-comments_controls a[data-key="refresh"] {
  position: static !important; float: none !important;
  margin: 0 !important; flex: 0 0 auto !important;
  /* Крупнее прежних 24: значок остался единственным в строке (всё
     остальное ушло под шеврон), и он же самое частое нажатие в треде. */
  width: ${CF_ICON}px !important; height: ${CF_ICON}px !important;
  padding: 0 !important; }
/* Жирнее. Стрелка обновления нарисована сплошной фигурой без обводки, и
   утолщать её нечем, кроме как обвести той же краской: обводка ложится
   по контуру и прибавляет каждой линии по полтолщины с каждой стороны.
   Полпункта в системе координат значка 20 на 20 — это примерно
   полтора пикселя на экране. */
.b-comments_controls a[data-key="refresh"] svg { overflow: visible !important; }
.b-comments_controls a[data-key="refresh"] svg path {
  stroke: currentColor !important;
  stroke-width: .5 !important;
  stroke-linejoin: round !important; }

/* ---- Спрятанные фильтры ----
   Устройство и причины — у cfBuild. Здесь только вид.

   Шеврон стоит в строке наравне со счётчиками, столбик ложится под ними
   во всю ширину: строка у лепры flex с переносом, и элемент с основой в
   сто процентов уходит на свою линию сам.
   order не трогаем: у пустого контейнера без него доля равна нулю и он
   встаёт перед всем, чему order задан, — эта грабля у нас записана.
   Порядок задаём разметкой, шеврон и столбик добавляются последними. */
.lm-cf_more {
  -webkit-appearance: none !important; appearance: none !important;
  flex: 0 0 auto !important;
  display: inline-flex !important; align-items: center !important;
  gap: 4px !important;
  margin: 0 !important; padding: 4px 8px !important;
  background: none !important;
  border: 1px solid rgb(205,205,205) !important;
  border-radius: ${UI_R}px !important;
  font-family: inherit !important; font-weight: normal !important;
  font-size: 13px !important; line-height: 1.2 !important;
  color: rgb(102,102,102) !important;
  -webkit-tap-highlight-color: transparent !important;
  touch-action: manipulation !important;
  cursor: pointer !important; }
/* Выбран один из спрятанных — шеврон подсвечен: иначе строка молчала бы
   о том, что лента отфильтрована. */
.b-comments_controls.lm-cf__on .lm-cf_more {
  background: rgb(220,218,218) !important;
  border-color: rgb(170,170,170) !important;
  color: rgb(20,20,20) !important; }
html.lm-cards2:not(.lm-dark) .b-comments_controls.lm-cf__on .lm-cf_more {
  background: ${ALT_ON_BG} !important;
  border-color: ${ALT_ON_EDGE} !important; }
/* Знак — подменой символа, а не поворотом. Тот же приём, что у пенсне:
   повёрнутый шеврон в Safari даёт полупиксельное размытие. */
.lm-cf_arrow::before { content: '▾' !important; font-size: 11px !important; }
.b-comments_controls.lm-cf__open .lm-cf_arrow::before {
  content: '▴' !important; }

.lm-cf_box {
  display: none !important;
  flex: 0 0 100% !important; width: 100% !important;
  box-sizing: border-box !important;
  margin: 4px 0 0 !important; padding: 6px 8px !important;
  background: rgb(250,250,250) !important;
  border: 1px solid rgb(214,214,214) !important;
  border-radius: ${UI_R}px !important; }
.b-comments_controls.lm-cf__open .lm-cf_box {
  display: flex !important; flex-direction: column !important;
  align-items: flex-start !important;
  gap: 2px !important; }
/* Пункты столбика — строками во всю ширину: так по ним попадаешь
   пальцем, а не по трём буквам подписи. */
.lm-cf_box a[data-key] {
  display: block !important; width: 100% !important;
  box-sizing: border-box !important;
  margin: 0 !important; padding: 7px 2px !important;
  white-space: normal !important; }
/* Поля ввода внутри столбика («автор» и поиск) — во всю строку. Кегль
   тот же, что у форм: ниже шестнадцати Safari приближает страницу при
   касании. */
.lm-cf_box .i-form_text_input_pure {
  width: 100% !important; box-sizing: border-box !important;
  font-size: var(--lm-form-font, ${CFG.formFont}px) !important;
  padding: 2px 0 !important; }

/* ============ ГОЛОСОВАНИЕ ============ */
/* Блок жил в левой колонке (left:-38px) и был скрыт до наведения мышью.
   Возвращаем в поток, делаем всегда видимым, кнопки — под палец. */
#js-comments_holder .comment .vote,
#js-comments_holder .comment .vote.c_vote,
.post .vote, .vote {
  position: static !important; inset: auto !important;
  display: inline-flex !important; align-items: center !important;
  width: auto !important; height: auto !important;
  vertical-align: middle !important; white-space: nowrap !important; }
.post .vote { margin: 0 !important; }

/* Голосование поста стоит в строке подписи обычным элементом. Правило
   объявлено ниже общего .post .vote и весомее его: при равной силе
   победило бы нижнее, и разбираться, какое именно, пришлось бы каждый
   раз заново.
   inset: auto снимается явно — у лепры блок абсолютный, и остаточные
   координаты сдвинули бы его внутри строки. */
.post .dd .vote, .dd .vote, div.dd .vote {
  position: static !important; inset: auto !important;
  margin: 0 !important; width: auto !important;
  flex: 0 0 auto !important; }
/* Место голосовалки в подписи комментария больше не задаётся стилями:
   она первая во второй строке, и это решает список CFOOT_ROW2 при
   раскладке. Стояло тут сперва прижатие к правому краю (не работало —
   перебивалось общим правилом детей подписи, где четыре :not() дают
   больший вес), потом order: -1; оба правила убраны, чтобы порядок
   задавался в одном месте, а не в двух. */

#js-comments_holder .comment .c_vote .vote_button,
#js-comments_holder .comment .c_vote .vote_result,
.c_vote .vote_button_plus, .c_vote .vote_button_minus,
.vote_button, .vote_result {
  position: static !important; inset: auto !important;
  visibility: visible !important; float: none !important;
  display: inline-block !important;
  width: auto !important; min-width: 34px !important;
  height: 28px !important; line-height: 26px !important;
  box-sizing: border-box !important;
  padding: 0 !important; margin: 0 2px !important;
  font-size: 13px !important; color: rgb(102,102,102) !important;
  text-align: center !important;
  background: rgb(244,244,242) !important;
  border: 1px solid rgb(220,220,216) !important;
  border-radius: 5px !important; }
/* Счётчик перечислен и выше, в общем блоке кнопок: там задаются размеры
   и типографика, здесь снимаются рамка с фоном. Это наслоение, а не
   дубликат — свести в одно правило можно только продублировав десяток
   свойств. */
/* порядок в строке: минус, счётчик, плюс — в разметке плюс идёт первым */
.vote_button_minus { order: 1 !important; }
.vote_button_plus  { order: 3 !important; }
/* Тяжёлого селектора с идентификатором тут нет намеренно: порядок в
   строке лепра не задаёт вовсе, спорить не с кем, а второе упоминание
   того же селектора дало бы дубль (он и вылез, когда селекторы
   комментариев перевели на общий контейнер). */
.c_vote .vote_result, .vote_result {
  order: 2 !important;
  background: none !important; border: 0 !important;
  font-weight: 600 !important; min-width: 30px !important; }

/* в комментариях кнопки чуть мельче, иначе строка переносится */
.comment .vote_button, .comment .vote_result {
  height: 24px !important; line-height: 22px !important;
  min-width: 28px !important; margin: 0 1px !important;
  font-size: 12px !important; }
.comment .vote_result { min-width: 24px !important; }
/* общее правило отступов для ссылок раздувало кнопки */
.comment .c_footer a.vote_button, .comment .ddi a.vote_button {
  padding: 0 !important; }

/* Кнопки голосования под постом компактнее общих. Объявлено последним
   в разделе: так правило выигрывает и по весу селектора, и по порядку. */
.dd .vote .vote_button, .post .dd .vote .vote_button {
  min-width: 24px !important; height: 24px !important;
  line-height: 22px !important; font-size: 13px !important;
  margin: 0 1px !important; }
.dd .vote .vote_result, .post .dd .vote .vote_result {
  min-width: 22px !important; font-size: 13px !important;
  margin: 0 1px !important; }

/* Отданный голос оформляется внизу файла, вместе со всей голосовалкой.
   Здесь стоял отдельный блок с тёмной заливкой; он снят, и снят не
   просто как устаревший — он ЛОМАЛ новое оформление, и поучительно
   почему. Селектор .post .dd .vote .vote_button.vote_voted весит на
   один класс больше, чем html .post .dd .vote .vote_button, которым
   рисуется кнопка. Кнопка у нас теперь только ловит нажатие, а красит
   её псевдоэлемент, — и старая заливка с рамкой ложились на всю
   площадь нажатия, вокруг настоящей коробки. Отсюда и бралась
   квадратная рамка вокруг нажатой кнопки.
   Пока наборы оформления выбирались классом на html, лишний класс в
   селекторе это перевешивал, и поломки не было видно. Класс ушёл
   вместе с выбором — поломка проявилась. Мораль прежняя: снимая
   приставку у селектора, надо пересчитать, с кем он теперь спорит. */

/* Наборы оформления голосовалок собраны не здесь, а в самом низу файла:
   правила кармы объявлены ниже этого раздела, и набор, стоящий тут,
   выигрывал бы у них по весу селектора, но проигрывал по порядку. В
   браузере победил бы набор, в проверке — карма, и расхождение было бы
   невидимым. Внизу оба фактора работают в одну сторону. */

/* ============ ФОРМА ОТВЕТА ============
   Одна и та же разметка в двух местах: постоянная форма под последним
   комментарием (#js-comments_add_block_bottom) и всплывающая по тапу
   «ответить» — её лепра вставляет последним потомком .comment.

   У лепры .b-comments_reply_block шириной 80% с нижним пределом 280px.
   На десктопе оставшаяся пятая часть уходит под правую колонку; на
   телефоне колонки нет, и это просто пустое место справа от поля ввода —
   единственного элемента страницы, которому ширина нужна вся.
   Плюс у формы внутри комментария своя левая отбивка в 28px
   (.comments_indent_holder .comment .b-comments_reply_block) — она
   складывалась с отступом самой ветки.

   Перечисляем и обёртки: контейнер с max-height ведёт разворот формы,
   и если ширину задать только внутреннему блоку, обёртка останется
   прежней и обрежет его. */
.b-comments_new_thread_comment_form,
.b-comments_reply_block_container,
.b-comments_reply_block,
.comments_indent_holder .comment .b-comments_reply_block {
  width: 100% !important; max-width: 100% !important;
  min-width: 0 !important; box-sizing: border-box !important;
  padding-left: 0 !important; padding-right: 0 !important;
  margin-left: 0 !important; margin-right: 0 !important; }

/* ---- Две кнопки в подвале формы ----

   У лепры внизу стоит одна кнопка — отправка, и она НЕ кнопка, а
   картинка: input type="image" с файлом yarrr.gif 54 на 20, на котором
   слово YARRR! уже нарисовано. Закрытие формы при этом живёт совсем в
   другом месте — крестиком в правом верхнем углу.

   Ставим обе рядом, «Закрыть» слева от отправки, и одинаковыми.

   Числа: кнопка 76 на 28. Двадцать пикселей лепровской картинки под
   палец мелковаты, а 28 — та же высота, что у наших кнопок голосования
   и в попапе, то есть размер, уже принятый в наборе.

   Разметку НЕ трогаем ни в одном месте, и это не осторожность вообще, а
   осторожность конкретная: на этом самом узле у лепры висит отправка
   комментария от имени человека. Обработчик мог быть навешен и прямо, и
   через делегирование с оговоркой о родителе — проверить нечем, а
   сломать отправку ради вида кнопки размен плохой.

   Отсюда весь приём. Нарисованное на картинке слово перекрасить
   нельзя, поэтому картинку гасим прозрачностью и рисуем своё слово под
   нею — псевдоэлементом на строке подвала.

   Прозрачность здесь взята НАРОЧНО, ровно за то свойство, из-за
   которого она однажды стоила нам круга отладки: погашенный до нуля
   элемент продолжает ловить нажатия. Тут это и нужно — палец попадает в
   настоящий input лепры, а видит наше слово.

   Место псевдоэлемента считается, а не подбирается. Строка подвала у
   лепры position: relative, выравнивание по правому краю, отбивок нет;
   в потоке в ней ровно один элемент — та самая картинка (ссылка
   «приложу картинку» рядом стоит абсолютно). Значит правый нижний угол
   строки и есть правый нижний угол кнопки, а размеры кнопки мы задали
   сами. Привязка получается точной по построению.

   Слово «Закрыть» — тоже псевдоэлементом, по прежней причине: крестик
   это текстовый узел внутри ссылки, и подмена через DOM пережила бы
   ровно до следующей перерисовки формы, а лепра собирает её заново на
   каждое «ответить». Кегль ноль на самой ссылке прячет крестик.

   Отступ справа у «Закрыть» — 84: ширина кнопки отправки плюс восемь
   просвета. Число одно на два места и потому вынесено в переменную. */

.b-comments_reply_block .b-comments_bottom_bar {
  position: relative !important;
  min-height: ${FORM_BTN_H}px !important;
  text-align: right !important; }

/* Кнопка отправки: наше слово поверх погашенной картинки. Нажатия
   сквозь него проходят — ловить их должен input под ним.

   Вид обеих кнопок описан двумя объявлениями подряд, а не одним
   селектором через запятую. Причина не в стиле: jsdom, на котором мы
   проверяем, при разборе группы с псевдоэлементом теряет и вторую её
   половину — кнопка «Закрыть» получала в проверке лепровские 20 на 20,
   хотя в браузере взяла бы наши 76 на 28. Правило, которое нельзя
   проверить, всё равно что правило, которого нет.
   Разойтись значениям негде: числа лежат в FORM_BTN_W/FORM_BTN_H,
   повторяются только имена свойств. */
.b-comments_reply_block .b-comments_bottom_bar::after {
  content: 'YARRR!' !important;
  display: block !important; position: absolute !important;
  right: 0 !important; bottom: 0 !important;
  pointer-events: none !important;
  box-sizing: border-box !important;
  width: ${FORM_BTN_W}px !important; height: ${FORM_BTN_H}px !important;
  background: rgb(252,251,249) !important;
  border: 1px solid rgb(198,196,192) !important;
  border-radius: ${UI_R}px !important;
  text-align: center !important;
  /* Свойства шрифта порознь, а не сокращением font: оно сбрасывает
     начертание и кегль разом, и стоящий следом font-weight в Safari
     теряется. */
  font-family: Verdana, Arial, sans-serif !important;
  font-size: 12px !important; font-weight: bold !important;
  line-height: ${FORM_BTN_H - 2}px !important;
  color: rgb(186,58,45) !important; }

/* Сама картинка: растянута по кнопке и погашена. Пределы лепры (100 и
   60) снимаем — иначе они не дали бы задать размер. */
.b-comments_reply_block .b-comments_reply_block_yarrr {
  width: ${FORM_BTN_W}px !important; height: ${FORM_BTN_H}px !important;
  max-width: none !important; max-height: none !important;
  margin: 0 !important; padding: 0 !important;
  border: 0 !important; background: none !important;
  opacity: 0 !important;
  position: relative !important; z-index: 2 !important;
  cursor: pointer !important; }

/* Кнопка «Закрыть». Остаётся на месте — абсолютно внутри обёртки
   формы, — но переезжает из правого верхнего угла в правый нижний, к
   соседке. Нижний край обёртки совпадает с нижним краем строки подвала:
   подвал у лепры последний в форме, а своих отбивок снизу у обёртки
   нет. */
.b-comments_reply_block .b-close_btn {
  display: block !important;
  top: auto !important; left: auto !important;
  bottom: 0 !important; right: ${FORM_BTN_W + 8}px !important;
  margin: 0 !important; padding: 0 !important;
  box-sizing: border-box !important;
  width: ${FORM_BTN_W}px !important; height: ${FORM_BTN_H}px !important;
  background: rgb(252,251,249) !important;
  border: 1px solid rgb(198,196,192) !important;
  border-radius: ${UI_R}px !important;
  text-align: center !important;
  text-decoration: none !important;
  font-size: 0 !important;
  -webkit-tap-highlight-color: transparent !important;
  touch-action: manipulation !important; }
.b-comments_reply_block .b-close_btn::before {
  content: 'Закрыть' !important;
  font-family: Verdana, Arial, sans-serif !important;
  font-size: 12px !important; font-weight: bold !important;
  line-height: ${FORM_BTN_H - 2}px !important;
  color: rgb(70,70,70) !important; }
.b-comments_reply_block .b-close_btn:active {
  background: rgb(236,234,232) !important; }

/* Ссылка «приложу картинку» стоит в той же строке абсолютно слева и
   ширины не имеет — при узком экране она дотягивалась бы до кнопок.
   Ограничиваем справа местом, которое кнопки занимают: 160 на них и
   двенадцать просвета. */
.b-comments_reply_block .b-file_uploader_button {
  max-width: calc(100% - ${FORM_BTN_W * 2 + 20}px) !important;
  line-height: 1.25 !important; }

/* Надпись «Я, пожалуй, напишу комментарий». У лепры кегль 18 и запрет
   переноса: при увеличенном масштабе страницы, когда ширина падает до
   340, строка уезжает за кромку. Перенос разрешаем, кегль чуть
   убавляем — восемнадцать здесь спорит с подписями комментариев над
   нею. */
.b-comments_controls_bottom { margin: 14px 0 !important; }
.b-comments_controls_new_comment {
  white-space: normal !important; font-size: 16px !important;
  line-height: 1.35 !important; display: inline-block !important; }


/* Отмотка лесенки — строго ПОСЛЕ правила выше, см. replyBleedRules. */
${replyBleedRules()}

/* ============ МЕДИА ============ */
.js-media_player, .b-media_player, .b-media_player_preview {
  width: auto !important; max-width: 100% !important;
  height: auto !important; aspect-ratio: auto !important; }
.js-media_player video, .js-media_player audio,
.comment video, .p_body video {
  /* Ширина auto, а не 100%, — и это принципиально для потолка высоты.
     У элемента с ЗАДАННОЙ шириной предел по высоте её не уменьшает:
     коробка становится ниже, ширина остаётся прежней, и вертикальный
     ролик просто оказывается в чёрной рамке по бокам. А при auto с
     обоими пределами браузер применяет к замещаемому элементу
     соразмерное сжатие — коробка уменьшается целиком, пропорции целы.
     Так же устроены и картинки строкой выше, так что заодно ушло
     расхождение между теми и другими.
     Платим тем, что ролик уже колонки останется своей ширины, а не
     растянется на всю. Для лепровских роликов это редкость, а
     растянутое вдвое видео всё равно выглядит мылом. */
  width: auto !important; max-width: 100% !important;
  height: auto !important;
  /* Тот же потолок, что и у картинок (CFG.mediaCut). Раньше здесь стояло
     жёсткое 80vh — число из тех времён, когда потолок был страховкой от
     совсем уж великанов, а не настройкой. Теперь величина одна на все
     медиа и крутится ползунком. */
  max-height: var(--lm-media-max, ${CFG.mediaCut}vh) !important;
  aspect-ratio: auto !important;
  /* По центру — по той же причине, что и картинки: ролик уже колонки
     теперь не редкость, а следствие потолка по высоте. Замещаемым
     элементам auto-поля работают только у блочных, поэтому display
     задаём явно; на видео это ничего не ломает — оно и так всегда
     стоит отдельной строкой внутри своего плеера. */
  display: block !important;
  margin-left: auto !important; margin-right: auto !important; }
.js-media_player video, .js-media_player iframe, .js-media_player embed,
.js-media_player object, .js-media_player > div { max-width: 100% !important; }
.b-media_player_preview_pic_holder img {
  max-width: 100% !important; height: auto !important; }

/* Прямая ссылка на файл под плеером. Мелкая и серая: она нужна изредка
   и мозолить глаза под каждым роликом в ленте не должна.
   Стоит ПО ЦЕНТРУ, а не в углу. Сперва была прижата вправо, под правый
   край плеера, — рассуждение было про взгляд, а надо было про палец: в
   углу экрана по ней неудобно попадать, особенно правой рукой в верхней
   половине страницы. Середина достаётся большим пальцем в любом хвате,
   а глаз мелкую серую строчку всё равно не встречает.
   Отбивки сверху и снизу заметные: строчка кеглем 11 без них собирает
   промахи по соседним ссылкам поста.
   Отдельный блок, а не строчный элемент: строчная ссылка склеилась бы
   с текстом поста, который идёт следом. */
.lm-vlink {
  display: block !important; width: auto !important;
  margin: 4px 0 10px !important; padding: 3px 0 !important;
  text-align: center !important;
  font-family: Verdana, Arial, sans-serif !important;
  font-size: 11px !important; line-height: 1.4 !important;
  color: rgb(136,136,136) !important;
  /* Подчёркивание — свойством текста, а не нижней рамкой: рамка у
     блочного элемента прочертила бы линию во всю ширину поста, а не под
     четырьмя буквами. */
  text-decoration: underline !important;
  -webkit-text-decoration-style: dotted !important;
  text-decoration-style: dotted !important; }

/* ============ ФОРМЫ ============ */
form table, form tbody, form tr, form td, form th {
  display: block !important; width: auto !important;
  max-width: 100% !important; box-sizing: border-box !important; }
input[type="text"], input[type="password"], input[type="email"],
textarea, select {
  /* 16px обязателен: при меньшем Safari зумит страницу на фокусе */
  font-size: 16px !important; max-width: 100% !important;
  box-sizing: border-box !important; }
input[type="radio"], input[type="checkbox"] {
  transform: scale(1.2); margin-right: 6px; }

/* Кегль полей ввода в формах комментария. Правило выше ставит всем
   полям ровно шестнадцать; здесь то же требование, но переменной — она
   учитывает масштаб страницы (разбор в описании CFG.formFont).

   Стоит НИЖЕ общего правила И тяжелее его на класс — оба условия
   обязательны. Браузер решает спор по весу, jsdom по порядку
   объявления, и совпасть они должны на одном и том же правиле; сперва
   этот блок стоял выше, и проверка показывала шестнадцать там, где
   браузер показал бы восемнадцать.

   Перечисляем и textarea, и текстовое поле: в форме есть и то, и
   другое (поле у загрузчика картинки), а приближает Safari то поле, в
   которое ткнули. */
.b-comments_reply_block textarea,
.b-comments_reply_block input[type="text"],
.b-comments_reply_block .i-form_text_input {
  font-size: var(--lm-form-font, ${CFG.formFont}px) !important; }

/* ============ СТРАНИЦА НОВОГО ПОСТА ============ */
/* Разметка формы — самая старая на лепре: одна таблица во всю страницу,
   внутри неё ещё четыре, ширины колонок процентами, раскраска атрибутами
   bgcolor. Общее правило «form table → block» её разбирает, но в блоки
   превращается и то, что должно стоять рядом: квадратик отдельной
   строкой, подпись к нему — следующей. Отсюда и размашистость.
   Поэтому таблицы не чиним, а разбираем в свою колонку — см. fixNewPost.
   Здесь только вид собранного. */
.lm-np { display: block !important; padding-top: 4px !important; }

/* Панель кнопок оформления — это ячейка таблицы, поэтому display задаём
   явно, поверх общего правила. Десять подписей в 13 пунктов занимают
   около 364 пикселей: в 393 они укладываются в строку впритык, при
   увеличенном масштабе страницы переносятся во вторую. Перенос и есть
   запасной вариант — обрезать в такой панели нечего. */
.lm-np #js-new_post_body_wysiwyg {
  display: flex !important; flex-wrap: wrap !important;
  align-items: center !important; gap: 6px 4px !important;
  padding: 0 0 6px !important; white-space: normal !important; }
.lm-np .b-textarea_editor_button {
  margin: 0 !important; padding: 3px 0 !important; font-size: 13px !important; }

/* Высота поля прописана у лепры в разметке — перебиваем своей.
   Кегль 16 обязателен: ниже Safari наезжает увеличением при касании. */
.lm-np #js-new_post_body {
  width: 100% !important; height: ${CFG.newPostBody}px !important;
  font-size: 16px !important; box-sizing: border-box !important;
  margin: 0 !important; }

/* Два списка под полем ввода. Кнопки стоят в одну строку, раскрытый
   список ложится под ними во всю ширину: в половину экрана подписи
   категорий не помещаются, а рвать их пополам ради симметрии незачем.
   Порядок в разметке — обе кнопки, потом обе группы, поэтому строка
   получается сама, без order. */
.lm-np_lists {
  display: flex !important; flex-wrap: wrap !important;
  gap: 6px !important; margin: 14px 0 0 !important; }
.lm-np_toggle {
  flex: 1 1 calc(50% - 3px) !important; min-width: 0 !important;
  box-sizing: border-box !important; display: block !important;
  text-align: left !important; margin: 0 !important;
  padding: 7px 24px 7px 9px !important; position: relative !important;
  font-family: inherit !important; color: inherit !important;
  background: rgba(0, 0, 0, 0.05) !important;
  border: 1px solid rgba(0, 0, 0, 0.15) !important;
  border-radius: 4px !important;
  -webkit-appearance: none !important; appearance: none !important; }
/* Если список остался один — занимает строку целиком, чтобы рядом
   не висела пустая половина. */
.lm-np_toggle:only-of-type { flex: 1 1 100% !important; }
/* Уголок — переключением содержимого, а не поворотом: у правого края
   узкой кнопки повёрнутый глиф заметно прыгает. */
.lm-np_toggle::after {
  content: '▾'; position: absolute !important; right: 8px !important;
  top: 50% !important; margin-top: -0.6em !important;
  font-size: 12px !important; opacity: 0.6 !important; }
.lm-np_toggle.lm-open::after { content: '▴'; }
.lm-np_toggle_t {
  display: block !important; font-size: 13px !important;
  font-weight: bold !important; line-height: 1.25 !important; }
/* Что в списке выбрано. Строка одна: длинное название категории
   обрезаем — тут это не поломка, полное видно в самом списке. */
.lm-np_toggle_v {
  display: block !important; font-size: 11px !important;
  line-height: 1.35 !important; opacity: 0.65 !important;
  white-space: nowrap !important; overflow: hidden !important;
  text-overflow: ellipsis !important; }
/* Группа пунктов: закрыта по умолчанию, открывается классом. */
.lm-np_group {
  display: none !important; flex-wrap: wrap !important;
  flex: 1 1 100% !important; gap: 3px !important;
  margin: 2px 0 4px !important; }
.lm-np_group.lm-open { display: flex !important; }
/* Квадратик с подписью — один пункт: порознь подпись отрывалась от
   своего квадратика на переносе. Подложка вместо lepr'овского bgcolor:
   его ячейки при разборе таблицы всё равно исчезают. */
.lm-np_opt {
  display: flex !important; align-items: flex-start !important;
  gap: 7px !important; padding: 6px 7px !important;
  box-sizing: border-box !important; min-width: 0 !important;
  background: rgba(0, 0, 0, 0.045) !important; border-radius: 3px !important; }
.lm-np_opt input { margin: 0 !important; flex: 0 0 auto !important; }
.lm-np_opt label {
  font-size: 13px !important; line-height: 1.35 !important;
  display: block !important; min-width: 0 !important; }
.lm-np_opt img { vertical-align: middle !important; }
/* Специальные опции — по одной в строку: подписи там фразами.
   Категории — в колонки, число берётся из CFG.newPostCats. */
.lm-np_flags .lm-np_opt { flex: 1 1 100% !important; }
.lm-np_cats .lm-np_opt {
  flex: 1 1 ${Math.max(0, 100 / CFG.newPostCats - 3).toFixed(1)}% !important; }

/* Строка отправки. Отбивка сверху вместо лепровского <hr>: он жил
   внутри таблицы и при разборе уходит вместе с ней. */
.lm-np_send {
  display: flex !important; align-items: center !important;
  gap: 12px !important; margin: 16px 0 0 !important;
  padding: 12px 0 4px !important;
  border-top: 1px solid rgba(0, 0, 0, 0.12) !important; }
/* Кнопка отправки у лепры — картинка 54×20. Пальцем в неё попасть можно,
   но с запасом: поля добавляют площади нажатия, не трогая саму картинку. */
.lm-np_send #js-new_post_submit {
  flex: 0 0 auto !important; padding: 9px 14px !important;
  border-radius: 4px !important; background: rgba(0, 0, 0, 0.06) !important; }

/* Загрузчик картинки. У лепры и кнопка «прикреплю», и панель выбора
   файла позиционированы абсолютно внутри контейнера, у которого своей
   высоты нет вовсе: на десктопе они просто лежат в пустом поле слева от
   кнопки отправки. В строке из двух элементов такой контейнер
   схлопывается в ноль, и надпись наезжает на то, что окажется под ней.
   Ставим обоих в поток. */
.lm-np_send #js-new_post_file {
  flex: 1 1 auto !important; width: auto !important; height: auto !important;
  min-width: 0 !important; margin: 0 !important; text-align: left !important; }
.lm-newpost .b-file_uploader_button,
.lm-newpost .b-file_uploader {
  position: static !important; margin: 0 !important; padding: 0 !important;
  font-size: 13px !important; }
.lm-newpost .b-file_uploader_browse_button {
  float: none !important; margin: 0 !important;
  padding: 0 10px 0 0 !important; }
/* «или перетащить сюда» на телефоне бессмысленно, но узел не прячем:
   похоже, лепра пишет в него имя выбранного файла, а скриптов её в
   сохранённой странице нет и проверить нечем. Пока просто убираем
   абсолютные координаты и нижний предел ширины в 200 пикселей. */
.lm-newpost .b-file_uploader_drag {
  position: static !important; display: inline !important;
  min-width: 0 !important; max-width: 100% !important;
  padding: 0 !important; font-size: 11px !important; }
.lm-newpost .b-new_post_delete_file { font-size: 11px !important; }
/* Табличка «Интернет включён» под формой — украшение, но 150 пикселей
   у правого края смотрятся обрезком. Ставим по центру. */
.lm-newpost #js-new_post_form + div[align="right"] { text-align: center !important; }



/* ============ СТРАНИЦА ПОИСКА ============ */
.b-search_form {
  white-space: normal !important; text-align: left !important;
  padding-top: 10px !important; }
.b-search_form .i-form_text_input {
  width: 100% !important; box-sizing: border-box !important; }
.b-search_form .b-icon_button_search { left: 0 !important;
                                       margin-left: 4px !important; }
.b-search_threshold {
  margin-right: 0 !important; padding-left: 0 !important;
  min-height: 0 !important; }
.b-search_threshold form { padding-left: 0 !important; }
.b-search_threshold form .i-form_text_input { width: 100% !important; }
.b-search_threshold form .b-search_threshold_settings .i-form_text_input {
  width: 100px !important; }
.b-search_form_submit {
  padding-top: 12px !important; line-height: 1.6 !important;
  display: flex !important; flex-wrap: wrap !important;
  align-items: center !important; gap: 8px !important; }
.b-search_form_container { margin-top: 12px !important;
                           padding-top: 14px !important; }
.b-subscriptions_search_form {
  width: auto !important; float: none !important;
  margin-bottom: 16px !important; }

/* переключатель режима был absolute и ложился на чекбоксы */
#js-search_settings_mode_toggle {
  position: static !important; inset: auto !important;
  float: none !important; display: inline-block !important;
  margin: 4px 0 10px !important; white-space: nowrap !important; }

.b-search_threshold_settings,
.b-search_threshold_settings .b-i-search_threshold_settings {
  display: flex !important; flex-wrap: wrap !important;
  align-items: center !important; gap: 8px 16px !important;
  line-height: 1.7 !important;
  margin-left: 0 !important; padding-left: 0 !important; }
.b-search_threshold_settings > *,
.b-search_threshold_settings .b-i-search_threshold_settings > *,
.b-search_threshold_settings span {
  position: static !important; inset: auto !important; float: none !important; }
.b-search_threshold_settings a,
.b-search_threshold_settings label {
  position: static !important; inset: auto !important; float: none !important;
  display: inline-flex !important; align-items: center !important;
  gap: 6px !important; white-space: nowrap !important; }
/* служебные поля статикой делать нельзя — они всплывут в поток */
.b-search_threshold_settings .pos_hidden,
.b-search_threshold_settings select.hidden,
.b-search_threshold_settings .hidden { display: none !important; }
.b-search_threshold_settings input[type="checkbox"],
.b-search_threshold_settings input[type="radio"] {
  position: static !important; margin: 0 !important; flex: 0 0 auto !important; }

/* ============ МОИ ВЕЩИ ============ */
/* Разделитель под подшапкой — парный к тому, что под шапкой страницы */
.b-my_posts_feed_controls {
  padding-bottom: 10px !important; margin-bottom: 12px !important;
  border-bottom: 1px solid rgb(214, 212, 212) !important; }
/* Строка с вводной фразой остаётся обычным текстом: поле выбора стоит
   внутри предложения, и флекс бы его оттуда вырвал — фраза встала бы
   блоком слева, поле отдельно справа. */
.b-my_posts_feed_controls p {
  line-height: 1.7 !important; margin: 0 0 6px !important; }
.b-my_posts_feed_controls select { vertical-align: middle !important; }

/* Строка из одних полей — флекс, и это не украшательство. В разметке
   лепры пробелы лежат не только МЕЖДУ пунктами, но и внутри них: перед
   чекбоксом и после каждого поля выбора. Инлайновый пробел рисуется
   шириной около четырёх пикселей, и к заданному интервалу их набегало
   два — по одному с каждой стороны стыка. У флекс-элементов пробельные
   узлы между ними не рисуются вовсе, а начальные и конечные пробелы
   внутри каждого элемента браузер срезает сам. Тогда интервал задан
   ровно в одном месте — в gap.
   Свободное место раздаётся между пунктами, а не копится справа — иначе
   поля жмутся к левому краю, а правая треть строки пустует.
   Перенос разрешён, но нужен редко: ширину полям скрипт задаёт по
   ВЫБРАННОМУ пункту списка (см. fitSelects), а не по самому длинному,
   и в обычном положении строка помещается целиком. Если же выбраны
   самые длинные варианты сразу в двух списках, пункт уезжает на вторую
   строку — это некрасиво ровно один раз, тогда как подрезанный текст
   в поле выглядит поломкой всегда. */
.b-my_posts_feed_controls p.lm-filters_row {
  display: flex !important; flex-wrap: wrap !important;
  align-items: center !important; gap: 4px 5px !important;
  justify-content: space-between !important; }
/* Подпись и её поле не разрывать: «За» вставало строкой выше своего
   поля, как только пункту не хватало ширины. */
.b-my_posts_feed_controls p.lm-filters_row > .b-my_posts_feed_controls_item {
  min-width: 0 !important; white-space: nowrap !important; }
.b-my_posts_feed_controls p.lm-filters_row >
  .b-my_posts_feed_controls_item:last-child {
  flex: 0 0 auto !important; }
.b-my_posts_feed_controls p.lm-filters_row select {
  max-width: 100% !important; }
/* В «моих вещах» поле сортировки лежит в строке само по себе, без
   обёртки лепры, то есть само является пунктом строки. Форменным
   элементам браузер задаёт нижний предел ширины по содержимому — снимаем,
   иначе строка не сожмётся вовсе. Сжатие здесь — запас на крайний
   случай: ширину полю скрипт уже подобрал по выбранному значению. */
.b-my_posts_feed_controls p.lm-filters_row > select {
  flex: 0 1 auto !important; min-width: 0 !important; }
/* Собственные отступы пунктов и полей снимаем целиком: у лепры они
   рассчитаны на широкую строку и складывались с нашими. */
.b-my_posts_feed_controls_item {
  margin: 0 !important; padding: 0 !important; }
.b-my_posts_feed_controls_item > select,
.b-my_posts_feed_controls_item > label,
.b-my_posts_feed_controls_item > input {
  margin: 0 !important; }
/* у чекбокса «только новое» лепра держит margin-left: 14px прямо
   в атрибуте style — снимаем, иначе к интервалу прибавляются её */
.b-my_posts_feed_controls_item input[type="checkbox"] {
  margin-left: 0 !important; }
/* чекбокс с подписью скрипт сводит сюда, чтобы подпись не отрывалась
   от квадратика при переносе */
.b-my_posts_feed_controls .lm-unread_row {
  display: flex !important; align-items: center !important;
  gap: 6px !important; margin-top: 4px !important; }
/* внутри строки из одних полей он идёт наравне с ними: свой отступ
   сверху ему там не нужен, а сжиматься ему нечем */
.b-my_posts_feed_controls p.lm-filters_row > .lm-unread_row {
  margin-top: 0 !important; flex: 0 0 auto !important; }
.b-my_posts_feed_controls .lm-unread_row input {
  margin: 0 !important; flex: 0 0 auto !important; }
.b-my_posts_feed_controls .lm-unread_row label {
  flex: 1 1 auto !important; }
/* На «избранном» чекбокс с подписью держит собственный узел лепры
   .b-check_item, и своей обёртки мы там не строим. Интервал между ними
   был начальным пробелом внутри подписи — после сокращения текста он
   пропал. Задаём его здесь, в одном месте, а собственные поля квадратика
   снимаем, чтобы величина интервала не складывалась из двух источников. */
.b-my_posts_feed_controls p.lm-filters_row .b-check_item {
  display: inline-flex !important; align-items: center !important;
  gap: 5px !important; white-space: nowrap !important; }
.b-my_posts_feed_controls p.lm-filters_row .b-check_item input,
.b-my_posts_feed_controls p.lm-filters_row .b-check_item label {
  margin: 0 !important; }

/* ============ ИНБОКС ============ */
/* «Написать инбокс» у лепры стоит в потоке слева, под панелью фильтров, и
   на широком экране этого хватает. На телефоне строка из значка и подписи
   теряется у самого края — единственное действие страницы выглядит как
   служебная сноска. Ставим её отдельной строкой по центру.
   Флекс, а не text-align: сама ссылка блочная, и центровать надо её,
   а не текст внутри. */
.b-inbox_write_link {
  position: static !important; float: none !important; clear: both !important;
  width: auto !important; margin: 4px 0 8px !important;
  display: flex !important; justify-content: center !important; }
.b-inbox_write_link > a {
  position: static !important; float: none !important;
  display: inline-flex !important; align-items: center !important;
  gap: 6px !important; }
/* значок внутри — такой же b-svg-icon, как в подписях: у лепры он
   позиционирован относительно и сдвинут по вертикали, внутри флекса
   это уводит его от подписи на пару пикселей */
.b-inbox_write_link .b-svg-icon {
  position: static !important; inset: auto !important;
  top: auto !important; margin: 0 !important;
  display: inline-flex !important; align-items: center !important;
  flex: 0 0 auto !important; }
.b-inbox_write_link .b-svg-icon svg { display: block !important; }
.b-inbox_write { width: 100% !important; box-sizing: border-box !important; }

/* ============ ПРОФИЛЬ ============ */
/* Блок пользователя был жёстко 1200px с минимумом 800px, плюс шесть
   абсолютно позиционированных вставок поверх друг друга.
   Боковые отступы снимаем вместе с ширинами: под аватар и колонку фона
   лепра держит поля в несколько десятков пикселей с каждой стороны, и на
   телефоне содержимое профиля оказывалось ужатым в середину экрана,
   заметно уже шапки и подвала. Поля страницы уже заданы на .l-wrapper. */
.b-user_block, .b-i-user_block,
.b-user_data, .b-i-user_data,
.b-user_data h2, .b-i-user_data h2,
.l-content_wrapper, .b-content_section,
.b-profile_left_col, .b-profile_right_col {
  width: auto !important; min-width: 0 !important; max-width: 100% !important;
  box-sizing: border-box !important; float: none !important;
  margin-left: 0 !important; margin-right: 0 !important;
  padding-left: 0 !important; padding-right: 0 !important; }
.b-user_data, .b-i-user_data, .b-info_block { display: block !important; }
/* h2 у лепры: display:flex, padding-right:195px под голосовалку кармы,
   white-space:nowrap и кегль 36px. Отступ снимаем, перенос разрешаем,
   кегль убавляем — имя в 36px занимало на телефоне почти всю ширину.
   Флекс оставляем: в эту же строку проход moveKarmaToName переносит
   голосовалку, а заметка с базой 100% уходит на строку ниже. */
.b-user_data h2, .b-i-user_data h2 {
  display: flex !important; flex-wrap: wrap !important;
  align-items: center !important; gap: 8px !important;
  margin-top: 0 !important;
  font-size: 24px !important; white-space: normal !important;
  line-height: 1.2 !important; }
.b-user_name-link {
  flex: 0 1 auto !important; min-width: 0 !important;
  word-break: break-word !important; }
.b-profile_left_col, .b-profile_right_col { line-height: 1.6 !important; }
/* карточка пользователя: 285px под аватар и поля под колонку контактов */
.b-userpic_wrapper, .b-userpic { width: auto !important; max-width: 100% !important; }
.b-userpic_image { max-width: 100% !important; height: auto !important; }
/* Подпись к картинке, приглашение и «редактировать» шли левым столбиком
   с полями по 16-30px под десктопную колонку в 330px. В одну колонку
   уместнее по центру и вплотную. */
.b-profile_left_col { text-align: center !important; }
.b-userpic_title { margin-bottom: 2px !important; }
.b-userpic_title_add { padding: 2px !important; }
.b-user_friends, .b-user_contacts {
  padding-right: 0 !important; margin-bottom: 4px !important;
  text-align: center !important; }
.b-user_parent { margin-bottom: 4px !important; }
.b-user_edit_info { margin-bottom: 6px !important; text-align: center !important; }
/* Серая полоса между шапкой и карточкой профиля — это фон .l-i-wrapper
   (#e1e1e1), видимый в зазоре под шапкой. Зазор мой: .l-header оставляет
   снизу 8px. На ленте это воздух между шапкой и первым постом, на профиле
   белая карточка начинается сразу, и полоска бросается в глаза. */
body.l-profile .l-header { margin-bottom: 1px !important; }

/* «#93307, с нами с …» — у лепры под этой строкой 30px пустоты: на широком
   экране в этот зазор попадает голосовалка кармы, прибитая абсолютно
   справа. В одну колонку голосовалка встаёт своей строкой, и зазор
   остаётся просто дырой в треть экрана. */
.b-user_data_registered { margin-bottom: 6px !important; }
/* содержимое профиля ниже вкладок: у лепры 38px сверху и 44px снизу
   плюс блоки с полями по 30-40px — на телефоне это экран пустоты */
.l-content_wrapper { padding-top: 14px !important; padding-bottom: 20px !important; }

/* Серая заливка профиля. У лепры их три слоя, одна поверх другой:
   .l-profile .l-i-wrapper красится в 204,204,204, а .b-i-user_block и
   .l-content_wrapper — в 245,245,245 поверх неё. На широком экране это
   рисует карточку профиля на тёмной подложке; на телефоне карточка
   занимает весь экран, и от замысла остаётся только грязноватый серый
   под всем содержимым, из-под которого наши рамки читаются плохо.

   Снимаем все три. Верхний слой (.l-i-wrapper) приводим к тому же
   белому, что и на прочих страницах, — не к прозрачному: он лежит на
   body, и прозрачность просто открыла бы тот же цвет, зато набор
   «светлые карточки» перестал бы им управлять (его правило целится
   именно в .l-i-wrapper). Два нижних гасим прозрачностью — им своего
   цвета не нужно вовсе, они лишь коробки.

   Правило .l-profile .l-i-wrapper весит два класса, наше — тоже два
   плюс !important, и оно ниже по файлу: спор решается одинаково при
   обоих подходах. */
body.l-profile .l-i-wrapper { background: rgb(255,255,255) !important; }
/* Селекторы уточнены родителем (body.l-profile) не для веса, а чтобы не
   повторить дословно список из правила ширин выше: два одинаковых
   селектора в собранной таблице — это дубль, который проверка ловит, и
   ловит справедливо: разнести настройки одного узла по двум правилам
   значит однажды забыть про второе. */
/* Гасим ЗАЛИВКУ, а не фон целиком. Разница здесь не стилистическая:
   картинку кастомного фона профиля лепра ставит инлайновым стилем на
   .b-user_block, и сокращённое background: none сносит её вместе с серым — а
   вернуть нечем, адрес есть только в разметке. Ровно на эти грабли мы
   уже наступали раньше, и рядом с .b-user_block по этой причине стоит
   background-color, а не background. Здесь повторено то же.
   .b-user_block в список не входит вовсе: его заливка снята выше, в
   правиле обрамления. */
/* Белая плашка под шапкой. У лепры .l-wide_header покрашен в чистый
   белый — на белой странице этого не видно, а в обратном наборе шапка
   осталась белым островом на притемнённом фоне. Тон страницы держит
   .l-i-wrapper, и второй источник того же цвета не нужен: гасим
   заливку, пусть просвечивает родитель. Заодно на профиле с кастомной
   картинкой шапка перестанет быть белой заплатой поверх узора. */
.l-wide_header { background-color: transparent !important; }

/* Подложка профиля с кастомной картинкой.

   Цвет — в тон карточек, а не лепровский серый 245: она тут работает
   подставкой под текст, то есть тем же, чем карточка поста в ленте.

   И полупрозрачная, чтобы узор чуть проступал. Прозрачность назначена
   ТОЛЬКО внешнему блоку. Вложенный .l-content_wrapper лежит внутри
   него, и та же плёнка на обоих сложилась бы в почти непрозрачную —
   ровно та ошибка, которую легко не заметить: каждая по отдельности
   выглядит нежной, а вместе они дают глухую заливку. Внутренний
   поэтому гасим совсем.

   Семьдесят пять процентов: узор заметно проступает, текст ещё держится.
   Ниже опускать не стоит — у kaiL узор синий с белым, контрастный, и
   это худший случай из встречавшихся. */
html.lm-profart body.l-profile .b-i-user_block {
  background-color: rgba(250,249,246,.75) !important;
  /* Дежурный отступ от края экрана. Раньше его давал сам блок с
     картинкой боковыми полями, но там они рисовали узор двумя полосами
     по краям; теперь подложка идёт от края до края, а отступ живёт
     внутри неё. На внешнем блоке подложки, не на внутреннем: они
     вложены друг в друга, и два отступа сложились бы вдвое. */
  padding-left: ${CFG.pageEdge}px !important;
  padding-right: ${CFG.pageEdge}px !important; }
html.lm-profart.lm-cards2 body.l-profile .b-i-user_block {
  background-color: rgba(253,252,250,.75) !important; }
html.lm-profart body.l-profile .l-content_wrapper {
  background-color: transparent !important; }

html:not(.lm-profart) body.l-profile .b-i-user_block,
html:not(.lm-profart) body.l-profile .b-user_data,
html:not(.lm-profart) body.l-profile .b-i-user_data,
html:not(.lm-profart) body.l-profile .b-content_section,
html:not(.lm-profart) body.l-profile .l-content_wrapper {
  background-color: transparent !important; }
.b-info_block, .b-user_citizen { margin-bottom: 16px !important; }
.b-user_stat { padding-bottom: 8px !important; margin-bottom: 8px !important; }
.b-userpic { margin-bottom: 6px !important; }
.b-profile_right_col { padding-bottom: 0 !important; }
.b-menu__profile .b-menu_list { float: none !important; margin-right: 0 !important; }

/* Фон профиля. Держит его .b-user_block — обёртка вокруг всего профиля,
   от карточки до вкладок и содержимого. У лепры на нём: padding-top 46px
   под полосу фона, серая заливка rgb(204,204,204) на случай, когда
   картинки нет, размер cover и attachment: fixed — на десктопе картинка
   стоит на месте, а карточка в 80% ширины едет по ней.
   На телефоне карточка занимает всю ширину, и 46 пикселей сверху были
   просто серой полосой, поэтому раньше фон гасился целиком. Теперь он
   остаётся тонким обрамлением: полоса сверху и поля по краям.

   Картинку лепра ставит ИНЛАЙНОВЫМ стилем, поэтому background-image
   здесь не трогаем ни в каком виде: правило с !important перебило бы
   инлайновый стиль, и вернуть картинку из CSS было бы уже нечем — адрес
   лежит только в разметке. Гасим только заливку.

   Размер — по ширине, а не cover: элемент высотой в несколько экранов,
   и cover растянул бы картинку до неузнаваемой мути ради нижнего края.
   При 100% ширины видна верхушка картинки в натуральных пропорциях, а
   ниже она повторяется — фоны профилей это обычно узор, а не портрет.
   Attachment: fixed снимаем — на iOS он ненадёжен, а смысла в нём нет:
   карточка по фону больше не ездит. */
.b-user_block {
  padding: 0 !important;
  background-color: transparent !important;
  background-attachment: scroll !important;
  background-size: 100% auto !important;
  background-position: center top !important;
  background-repeat: repeat-y !important;
  min-height: 0 !important; height: auto !important; }
/* Класс ставит markProfileArt, увидев инлайновую картинку: без неё
   обрамление было бы пустой полосой в цвет страницы.
   Устройство то же, что у кастомного фона подлепры: растягиваем блок на
   ширину экрана отрицательными полями и возвращаем те же пиксели
   внутренним отступом. Картинка занимает дежурные белые поля страницы, а
   тело профиля остаётся ровно той же ширины, что и без обрамления.
   max-width снимаем отдельно: общее правило выше держит на этом блоке
   100%, то есть ширину БЕЗ полей, и растянуться до кромок он бы не смог —
   вылез бы влево на двенадцать пикселей и не достал справа. */
.b-user_block.lm-art {
  max-width: none !important;
  margin-left: -${CFG.pageEdge}px !important;
  margin-right: -${CFG.pageEdge}px !important;
  /* Только сверху и снизу. Боковых полей больше нет: узор в них рисовал
     по краям экрана две вертикальные полосы, и подложка оказывалась
     карточкой с резкой кромкой. Теперь она идёт от края до края, а
     картинка остаётся полосой сверху — там она читается заголовком, а
     не рамкой.
     Дежурные поля страницы, которые эти пиксели раньше и занимали,
     перенесены внутрь подложки — правило ниже. */
  padding: ${CFG.profileArt}px 0 ${CFG.pageEdge}px !important; }

.b-user_data { padding-top: 14px !important; padding-bottom: 20px !important; }

.b-user_note_container {
  position: static !important; display: block !important;
  flex: 1 1 100% !important; width: auto !important;
  max-width: 100% !important; margin: 2px 0 0 !important;
  padding-left: 0 !important; }
.b-user_note, #js-usernote {
  position: static !important; display: block !important;
  width: auto !important; max-width: none !important; min-width: 0 !important;
  white-space: normal !important; padding: 2px 0 !important;
  box-sizing: border-box !important; }

/* карма: обёртка плавала вправо с отрицательными полями по всем сторонам,
   значение и кнопки висели абсолютно друг на друге */
.b-user_votes_wrapper {
  position: static !important; float: none !important;
  width: auto !important; height: auto !important; margin: 4px 0 6px !important; }
.b-user_karma {
  position: relative !important; height: auto !important;
  display: inline-flex !important; align-items: center !important;
  gap: 6px !important; }
.b-user_karma .b-karma_value {
  position: static !important; width: auto !important;
  height: auto !important; margin: 0 !important; }
.b-user_karma .b-karma_controls {
  position: static !important; width: auto !important;
  height: auto !important; margin: 0 !important;
  display: inline-flex !important; gap: 4px !important; }
.b-user_karma .b-karma_button {
  position: static !important; width: 22px !important; height: 22px !important;
  line-height: 20px !important; font-size: 13px !important; }
/* Ошибка прежних версий: нижний блок кнопок я счёл дубликатом верхнего и
   скрыл. На деле сверху два минуса, снизу два плюса — на телефоне карму
   можно было только убавить. Показываем обе группы одной строкой:
   [− −] значение [+ +], порядок в разметке уже такой. */
.b-user_karma .b-karma_controls__bot { display: inline-flex !important; }
/* Голосовалка, перенесённая в строку с именем: прижата к правому краю.
   Правило стоит НИЖЕ общего .b-user_votes_wrapper и специфичнее его —
   побеждает и по весу селектора, и по порядку объявления.
   Кегль задаём явно: внутри h2 голосовалка наследовала его 24px, отчего
   «41» и знаки выглядели как заголовок. */
.b-i-user_data h2 .b-user_votes_wrapper {
  flex: 0 0 auto !important; margin: 0 0 0 auto !important;
  font-size: 13px !important; line-height: 1.2 !important; }
.b-i-user_data h2 .b-karma_value,
.b-i-user_data h2 .b-karma_value_inner {
  font-size: 13px !important; line-height: 20px !important;
  height: 22px !important; min-width: 30px !important; }
/* Имя ужимается с многоточием, а не переносит голосовалку на строку ниже:
   при масштабе 110% и выше пара «имя + карма» перестаёт помещаться. */
.b-i-user_data h2 .b-user_name-link {
  flex: 0 1 auto !important; min-width: 0 !important;
  overflow: hidden !important; text-overflow: ellipsis !important;
  white-space: nowrap !important; word-break: normal !important;
  font-size: 22px !important; }

/* Окно со списком проголосовавших (тап по счётчику кармы, а на постах и
   комментариях — по числу голосов). У лепры оно шириной 410px и прибито
   к середине голосовалки со сдвигом вправо:
   .b-votes_popup { position:absolute; right:50%; margin-right:-192px }
   Расчёт десктопный — там голосовалка стоит в середине широкой карточки.
   На телефоне она прижата к правому краю строки с именем, и окно вылезало
   за экран дважды: собственной шириной (410 при CSS-ширине экрана 393)
   и сдвигом на 192px. Ширину ограничиваем экраном прямо здесь, чтобы окно
   не мигало широким до первого замера; горизонтальный сдвиг доводит
   проход fitVotesPopup — из CSS его не вычислить, он зависит от того,
   где именно на строке оказалась голосовалка. */
.b-votes_popup {
  width: 410px !important; max-width: calc(100vw - 12px) !important;
  box-sizing: border-box !important; }
/* Поля внутри окна — 30px слева и 40px справа — оставлены под стрелки
   листания (сами стрелки шириной 21px). На узком окне это седьмая часть
   ширины под пустоту, а список имён и так в две колонки. */
.b-votes_popup .b_users_table_holder {
  padding-left: 24px !important; padding-right: 26px !important; }
.b-votes_popup .b_users_table-list { max-width: none !important; }

/* Пенсне — родная кнопка разворота панели заметок. У лепры это картинка
   75×75, прибитая абсолютно слева от жёлтого поля (left:0, top:-5px).
   Слева от поля на телефоне места нет, поэтому ставим её в поток первой
   в строке и уменьшаем до 30px. */
.b-user_public_notes_logo {
  display: block !important; position: static !important;
  width: 30px !important; height: 30px !important; top: auto !important;
  flex: 0 0 auto !important; margin: 0 !important;
  background-size: contain !important;
  background-position: center center !important; }

/* «Показать авторов» у лепры — не текст, а полоса-картинка 158×34 со
   сдвигом margin-left:133px под ширину десктопной колонки. Оставляем
   подпись, картинку и сдвиг убираем. */
.b-user_public_notes__opened .b-user_public_notes_authors {
  display: inline-flex !important; align-items: center !important;
  position: static !important; overflow: visible !important;
  width: auto !important; height: auto !important;
  margin: 0 !important; padding: 0 !important;
  background: none !important; line-height: 1.3 !important;
  font-size: 12px !important; flex: 0 0 auto !important; }
/* Чекбокс «публиковать заметки» и переключатель «по рейтингу / по дате» —
   одной строкой, прижаты вправо. У лепры оба прибиты абсолютно
   (top:31px right:160px и top:30px right:0) к ширине, которой на телефоне нет. */
.b-user_public_notes {
  display: flex !important; flex-wrap: wrap !important;
  align-items: center !important; gap: 6px 10px !important;
  width: auto !important; margin: 8px 0 !important; padding-left: 0 !important; }
.b-user_public_notes_switcher {
  margin-left: auto !important; }
.b-user_public_notes_switcher, .b-user_public_notes_sorting {
  position: static !important; float: none !important;
  width: auto !important; flex: 0 0 auto !important;
  display: inline-flex !important; align-items: center !important;
  gap: 6px !important; margin-top: 0 !important; margin-bottom: 0 !important;
  padding: 0 !important; }
.b-user_public_notes_switcher label,
.b-user_public_notes_sorting_button { margin: 0 !important; }

.b-user_public_notes_list, .b-user_public_notes_list ul {
  width: auto !important; margin-left: 0 !important; padding-left: 0 !important; }
/* список заметок — со своей строки на всю ширину, иначе он встаёт
   четвёртым элементом той же строки и жмётся в узкую колонку */
.b-user_public_notes_list {
  flex: 1 1 100% !important; margin-top: 8px !important; }
/* Строка «пенсне + жёлтое поле», которую собирает groupNotesRow.
   Пенсне держим у верхнего края: в развёрнутом виде поле высотой
   в несколько экранов, и кнопка по центру уехала бы из виду. */
.lm-notes-row {
  display: flex !important; align-items: flex-start !important;
  gap: 8px !important; flex: 1 1 100% !important; width: 100% !important; }
.lm-notes-row .b-user_public_notes_list {
  flex: 1 1 auto !important; min-width: 0 !important; margin-top: 0 !important; }
/* Пенсне у верхнего края строки, но со сдвигом: свёрнутое поле высотой 48,
   кнопка 30 — половина разницы и есть 9px. В развёрнутом виде поле высотой
   в несколько экранов, и центровать по нему нельзя: кнопка уехала бы
   из виду, поэтому сдвиг фиксированный, а не align-items: center. */
.lm-notes-row .b-user_public_notes_logo { margin-top: 9px !important; }

/* Кнопка продления гражданства — по центру колонки. display:table даёт
   ширину по содержимому, и поля auto её центруют; у inline-элемента
   auto-поля не работают. */
.b-user_citizen_extend {
  display: table !important; margin: 8px auto 0 !important; }
/* Пара «публиковать заметки» + сортировка: прижата вправо, при нехватке
   места переносится целиком, а не по одному элементу. */
.lm-notes-controls {
  display: flex !important; align-items: center !important;
  gap: 10px !important; flex: 0 0 auto !important;
  margin-left: auto !important; }
.lm-notes-controls .b-user_public_notes_switcher { margin-left: 0 !important; }

/* В свёрнутом виде остаются пенсне и последняя заметка: у лепры кнопка
   авторов и переключатели относятся к раскрытой панели, а сложенные в
   одну строку над одной заметкой они выглядели набором ярлыков без повода. */
.b-user_public_notes:not(.b-user_public_notes__opened) .b-user_public_notes_authors,
.b-user_public_notes:not(.b-user_public_notes__opened) .b-user_public_notes_switcher,
.b-user_public_notes:not(.b-user_public_notes__opened) .b-user_public_notes_sorting,
.b-user_public_notes:not(.b-user_public_notes__opened) .lm-notes-controls,
.b-user_public_notes:not(.b-user_public_notes__opened) .vote {
  display: none !important; }
/* поля внутри жёлтого поля: 60px по бокам и 100px справа у текста
   оставлены под стрелки листания и голосовалку, на телефоне это половина
   ширины экрана под пустоту */
.b-user_public_notes_list ul { padding: 8px 10px !important; }
.b-user_public_notes_list li { padding-bottom: 0 !important; }
.b-user_public_notes_list_note_body { padding-right: 0 !important; }
/* В развёрнутой панели заметки идут списком — им нужен зазор между собой */
.b-user_public_notes__opened .b-user_public_notes_list li {
  padding-bottom: 10px !important; }
.b-user_public_notes_list_note { margin-left: 0 !important; }
.b-user_public_notes_list_previous { display: none !important; }

.b-profile_search .i-form_text_input,
#js-profile_search_input,
.i-form_text_input_profile_search,
.i-form_text_input_profile_search_domains {
  width: 100% !important; max-width: 100% !important;
  box-sizing: border-box !important; }
.b-profile_search_controls { position: static !important; }

/* вкладка смены фона позиционировалась с right:-32px, то есть заведомо
   за краем родителя — на телефоне до неё не дотянуться */
.b-user_backgrounds, .b-user_backgrounds_toggle { display: none !important; }

/* ============ АРХИВ ============ */
/* Лента архива имела 330px отступа справа под правую колонку: на телефоне
   постам оставалось меньше двухсот пикселей, отсюда крошечные превью
   и наезжающие друг на друга подписи. */
.b-posts_archive { padding-right: 0 !important; }
.b-archive_heading {
  padding: 10px 0 16px !important; font-size: 1.3em !important; }
.b-archive_navigation {
  width: auto !important; box-sizing: border-box !important;
  padding: 6px !important; }
.b-archive_bottom_navigation {
  margin: 20px 0 !important; padding: 20px 0 !important; }
.b-archive_previous_day_bottom { padding: 6px 10px !important; }
/* календарь архива */
.b-archive_calendar, .b-archive_calendar table {
  width: 100% !important; max-width: 100% !important;
  box-sizing: border-box !important; }
/* Сам календарь свёрстан на 280 пикселей: коробка 280, ячейка дня ровно
   сорок, подсказка снизу опять 280. В 393 это влезает, но оставляет
   справа пустую треть — а календарь тут единственный орган управления,
   и по нему тычут пальцем.
   Отдаём ему всю ширину, а ячейку задаём долей: семь ячеек по 14.28%
   складываются в строку при любой ширине экрана, включая уменьшенный
   масштаб страницы.
   Доля работает, потому что между ячейками в разметке НЕТ пробелов —
   строчно-блочные элементы стоят вплотную, и лишнего просвета, который
   у inline-block съедает четвёртый пиксель и роняет седьмую ячейку на
   вторую строку, здесь не возникает. Проверено по разметке, а не на
   глаз. */
.b-calendar { width: 100% !important; box-sizing: border-box !important; }
.b-calendar_hint { width: auto !important; }
.b-calendar_month_header .b-calendar_day,
.b-calendar_month_days .b-calendar_day {
  width: 14.28% !important; box-sizing: border-box !important; }

/* ============ ДЕМОКРАТИЯ (Белый дом) ============ */
/* Страница собрана реактом и свёрстана в две колонки по половине ширины
   с обтеканием. Всё остальное на ней — числа под десктопную тысячу:
   отрицательные поля обёрток (−24 у колонок, −20 у устава), отступ 220
   у последней колонки таблицы, попап импичмента 519×340 с привязкой к
   середине через отрицательные поля.

   Своего класса странице не заводим: имена p-democracy__* больше нигде
   не встречаются, и признак «мы на демократии» вычисляется из них
   самих. Лишний класс — это лишний проход и лишнее место, где можно
   разойтись с разметкой. */

/* Колонки в столбик. Отрицательное поле обёртки снимаем вместе с
   обтеканием: оно вытягивало содержимое левее полей страницы, и без
   колонок это просто сдвиг всего блока за кромку.
   Правило, а не расчёт на unfloatWide: тот сработал бы (половина
   экрана больше его порога в 40%), но зависеть от замера там, где
   ответ известен заранее, незачем. */
.p-democracy__columns-wrapper {
  margin-left: 0 !important; margin-bottom: 20px !important; }
.p-democracy__column {
  float: none !important; width: auto !important;
  border-right: 0 !important; margin-right: 0 !important;
  padding-left: 0 !important; }

/* Заголовок. У лепры 27 пунктов по картинке-подложке; на телефоне это
   две строки на полэкрана. Кегль тот же, что у заголовка архива.

   С подложкой пришлось разобраться отдельно, и разбор был по размеру
   файла: regular-title.jpg — 558×70. У лепры коробка выходит примерно в
   72 пикселя (отбивки 19 и 20 плюс строка в 27 пунктов), то есть ровно
   под высоту картинки. Ужав кегль и отбивки, я сделал коробку в 49 — и
   нижние два десятка пикселей картинки просто обрезались краем блока.
   Со стороны это и выглядит как «подпись снизу наезжает на картинку»:
   наезжает не подпись, картинке не хватило места.

   Лечим двумя правилами сразу, и оба нужны. Нижний предел высоты — 70,
   натуральная высота файла: меньше неё коробка не станет ни при каком
   кегле. И background-size: contain — потому что 558 шире доступных
   четырёхсот с небольшим, и при натуральном размере картинку срезало бы
   уже справа. contain вписывает её целиком: на нашей ширине она
   уменьшается примерно до 413×52 и внутри семидесяти помещается с
   запасом, ничего не теряя.
   cover, стоявший здесь раньше, делает обратное — заполняет коробку,
   обрезая лишнее. Для декоративной заливки это верно, а тут в картинке
   нарисован текст. */
.p-democracy__header { margin-bottom: 16px !important; }
.p-democracy__header-main {
  font-size: 20px !important; line-height: 1.25 !important;
  padding: 12px 0 12px 10px !important; margin-bottom: 14px !important;
  min-height: 70px !important; box-sizing: border-box !important;
  background-size: contain !important;
  background-position: left top !important; }
.p-democracy__header-sub {
  font-size: 13px !important; line-height: 1.4 !important; }

.p-democracy__container { padding: 12px !important; }
.p-democracy__title { padding: 10px 0 !important; }
.p-democracy__closed-subdomains-indicator { margin-bottom: 12px !important; }
/* Отбивка списка имён у лепры 20; на трети экрана это заметная доля. */
.react .b-user-list { padding-left: 14px !important; }
.p-democracy__inbox { margin: 12px 0 !important; }

/* Двач-режим. Подпись отбита слева на 90 под картинку 77×66, которая
   лежит в псевдоэлементе, — отбивку оставляем (без неё подпись легла бы
   на картинку), а вертикальную ужимаем: тридцать сверху и снизу под
   одну строку это полсантиметра пустоты с каждой стороны. */
.p-democracy__anonymous { padding: 14px 0 !important; }
.p-democracy__anonymous-indicator {
  padding: 22px 0 22px 84px !important; }

/* Кнопка импичмента. Высота у лепры прибита числом (33) при строке 37 —
   на телефоне подпись переносится и вылезает за кнопку. Отдаём высоту
   содержимому. */
.p-democracy__impeach { margin-bottom: 24px !important; }
.p-democracy__impeach-button {
  height: auto !important; line-height: 1.2 !important;
  font-size: 18px !important; padding: 8px 14px !important;
  margin-bottom: 8px !important; }
.p-democracy__impeach-text { line-height: 1.4 !important; }

.p-democracy__press { padding-top: 8px !important; }
/* Лента твиттера приходит чужим кадром неизвестной ширины. */
.b-twitter { max-width: 100% !important; overflow: hidden !important; }
.b-twitter iframe { max-width: 100% !important; }

/* Устав. Таблицу НЕ разбираем в блоки, хотя общее правило форм такое
   умеет: здесь ячейки объединены по строкам (rowspan), и «Ещё
   дополнительные голоса и сливочный соус!» относится сразу к двум
   ступеням кармы. В столбик это превратилось бы в набор строк без
   связи, то есть в потерю смысла. Оставляем две колонки: первая
   набрана числами и не переносится, второй достаётся остальное.
   Отступ 220 у последней колонки — под десктопную ширину; снимаем. */
.b-sparja { margin-left: 0 !important; padding-bottom: 30px !important; }
.b-sparja table { width: 100% !important; }
.b-sparja__title { margin-bottom: 16px !important; }
.b-sparja thead tr { height: 44px !important; }
.b-sparja th, .b-sparja td {
  padding: 4px 6px !important; font-size: 12px !important; }
.b-sparja th span, .b-sparja td span { font-size: 15px !important; }
.b-sparja__indent td:last-child,
.b-sparja__indent th:last-child { padding-left: 6px !important; }
/* Спаржа. У лепры коробка нулевой ширины, а картинка вывешена из неё
   абсолютно вправо-вниз — приём для колонки в 220 пикселей, на телефоне
   картинка уезжает за кромку. Возвращаем обе в поток.
   Селекторы лепры (.b-sparja div и .b-sparja div img) весят больше
   наших, поэтому здесь !important обязателен — на одном весе мы бы
   проиграли. */
.b-sparja__image {
  position: static !important; width: auto !important;
  height: auto !important; }
.b-sparja__image img {
  position: static !important; max-width: 100% !important;
  /* Потолок высоты. Файл sparja.png — 209×416, то есть полэкрана в
     высоту. У лепры этого не видно: там коробка нулевая, а картинка
     вывешена из неё абсолютно и на высоту строки не влияет. Вернув её
     в поток, мы вернули и все её четыреста шестнадцать пикселей —
     ступень кармы «250 / 3» вымахала на пол-экрана.
     Ширину не задаём: при потолке по высоте и width: auto браузер
     ужимает замещённый элемент соразмерно, как и медиа в постах. */
  height: auto !important; width: auto !important;
  max-height: 120px !important; }

/* Попап импичмента. У лепры коробка 519×340, прибитая к середине окна
   отрицательными полями в половину своих размеров — приём, который на
   узком экране уводит её левый край далеко за кромку.
   Ставим от краёв теми же полями, что у страницы, а высоту отдаём
   содержимому с потолком: и картинка, и две кнопки должны поместиться,
   но простыней окно быть не должно.
   Отрицательное поле контейнера (−128) снимаем: оно поднимает пустую
   обёртку поверх подвала, когда попап закрыт. */
html body .b-portal__container { margin-top: 0 !important; }
.p-democracy__impeach-popup {
  position: fixed !important;
  top: 8vh !important; bottom: auto !important;
  left: ${CFG.pageEdge}px !important; right: ${CFG.pageEdge}px !important;
  width: auto !important; height: auto !important;
  max-height: 84vh !important; overflow: auto !important;
  margin: 0 !important; padding-bottom: 14px !important;
  box-sizing: border-box !important; }
.p-democracy__impeach-popup img {
  max-width: 100% !important; height: auto !important; }
.p-democracy__impeach-popup-close {
  top: 8px !important; right: 8px !important; }
/* Кнопки в попапе по 155 пикселей: вдвоём это 310 плюс поля, и на узком
   экране вторая уезжает. Ширину отдаём подписи. */
.p-democracy__impeach-button_popup {
  width: auto !important; margin: 6px 5px !important; }

/* подписи постов: строки переносятся часто, тесная высота строки
   заставляла соседние строки наезжать друг на друга */
.dd { line-height: 1.6 !important; }
.dd .b-note { line-height: 1.4 !important; }

/* ============ ВКЛАДКИ (мои вещи, профиль, настройки) ============ */
/* Свёрстаны CSS-таблицей: ячейки таблицы не переносятся в принципе,
   строка обязана уместиться целиком. Переводим на флекс. */
/* верхний отступ блока: вместе с полем шапки давал пустую полосу
   под разделителем */
.b-menu { margin-top: 0 !important; padding-top: 0 !important; }
.b-menu_list {
  display: block !important; width: auto !important;
  height: auto !important; margin-bottom: 8px !important; }
.b-menu_list_row {
  display: flex !important; flex-wrap: wrap !important; gap: 6px !important; }
.b-menu_list_link, span.b-menu_list_link {
  display: inline-block !important; flex: 0 0 auto !important;
  padding: 7px 12px !important; margin: 0 !important; }
.b-menu_list_text { height: auto !important; line-height: 1.4 !important; }
.b-menu_list_link_content { float: none !important; margin-right: 0 !important; }
.b-menu_list_link__last { width: auto !important; }

/* Активная вкладка отличается от соседних фоном rgb(241,240,241) против
   белого — полтора процента яркости. На бумаге это разница, на телефоне
   при боковом свете её нет вовсе. Затемняем фон и рамку настолько, чтобы
   вкладка читалась сразу, но не выглядела нажатой кнопкой.
   Нижнюю границу оставляем цветом самой вкладки, как у лепры: так она
   «открывается» в содержимое, а не обводится со всех сторон.
   Профиль и панель-кнопки не трогаем: там своё оформление активной
   вкладки — залитая серым с белым текстом и рамка без заливки. */
.b-menu:not(.b-menu__profile):not(.b-menu__buttons) .b-menu_list_link_active,
.b-menu:not(.b-menu__profile):not(.b-menu__buttons) .b-menu_list_link_active:hover {
  background-color: rgb(223, 221, 223) !important;
  border-color: rgb(184, 182, 184) rgb(184, 182, 184)
                rgb(223, 221, 223) !important;
  color: rgb(40, 40, 40) !important; }

/* Четыре вкладки профиля с общими полями по 12px не помещались в 369px и
   переносились. При масштабе страницы 110% ширина падает до ~333, поэтому
   считаем с запасом: кегль 11, поля 5, зазор 3 — вся четвёрка около 280. */
.b-menu__profile .b-menu_list_row { gap: 3px !important; }
.b-menu__profile .b-menu_list_link {
  padding: 6px 5px !important; font-size: 11px !important;
  white-space: nowrap !important; flex: 0 1 auto !important; }
.b-menu__profile .b-menu_list_link i { font-size: 10px !important; }

/* ============ МАГАЗИН (/fraud/) ============ */
/* ---- Строка ссылок под навигационной штукой ----
   Шесть пунктов набраны Verdana в 12.8 с полями по 12 — это 642 пикселя
   с зазорами при доступных 369, и они ложились в ТРИ строки, причём
   третью занимал один знак вопроса: вторая недобирала восьми пикселей
   (377 против 369). Мерить эту строку по Arial нельзя — Verdana идёт по
   0.545 кегля против 0.519, и при равных числах она заметно шире.

   Ужимаем кегль, поля и зазор, а самый длинный пункт сокращаем в
   shortenTabs. Тогда 488 вместо 642, и две строки держатся не только при
   100%, но и при масштабе страницы 125%, когда доступных остаётся 316. */
.b-menu_fraud .b-menu_list_row { gap: 4px !important; }
.b-menu_fraud .b-menu_list_link, .b-menu_fraud span.b-menu_list_link {
  padding: 6px 9px !important; font-size: 12px !important;
  line-height: 1.15 !important; white-space: nowrap !important; }
/* Знак вопроса свои поля держит на вложенной ссылке — иначе они
   складывались бы с полями пункта и он выходил бы вдвое шире прочих. */
.b-menu_fraud .b-menu_list_link__last { padding: 0 !important; }
.b-menu_fraud .b-menu_list_link_content {
  padding: 6px 9px !important; border-radius: 3px !important; }
/* Тунец остаётся, но вписывается в строку. У лепры он 28×40 при кнопке
   в 29 — то есть выше её, и торчал вверх на дюжину пикселей, наезжая на
   строку над собой. Пропорции сохраняем: 28×24/40 = 17. */
.b-menu_fraud .b-charlie_item { padding-left: 20px !important; }
.b-menu_fraud .b-charlie_item i {
  width: 17px !important; height: 24px !important;
  background-size: 17px 24px !important;
  margin-top: -12px !important; }

/* ---- Общее для всех страниц магазина ----
   Кегль полей ввода. У лепры они идут по 12–14, а всё, что ниже 16,
   Safari на iOS встречает наездом камеры при касании: страница
   прыгает масштабом, и вернуть его обратно нечем. Ставим 16 всему
   разделу разом — по одному правилу на страницу их набиралось шесть,
   и каждая новая форма приносила бы седьмое. */
html.lm-fraud input[type="text"], html.lm-fraud input[type="password"],
html.lm-fraud input[type="email"], html.lm-fraud input[type="tel"],
html.lm-fraud input[type="number"], html.lm-fraud textarea,
html.lm-fraud select { font-size: 16px !important; }
/* Поля с шириной в пикселях под десктопную колонку — их на страницах
   магазина россыпь (500, 450, 130). Ширину отдаём содержимому, но с
   рамками в расчёте: иначе поле во всю карточку вылезает на их толщину. */
html.lm-fraud input[type="text"], html.lm-fraud input[type="password"],
html.lm-fraud textarea {
  max-width: 100% !important; box-sizing: border-box !important; }

/* Подменю разделов («Пополнение счета | Переводы | История операций»,
   «Приветствия | Смена никнейма | Будка…»): отступ слева в 20 пикселей
   рассчитан на логотип магазина, стоящий выше и левее. Справа его нет,
   и на телефоне строка стояла несимметрично. */
.b-fraud_sub_navigation {
  padding: 12px 0 0 !important; font-size: 12px !important;
  line-height: 1.7 !important; }

/* Обёртки содержимого: 96% ширины оставляли полосу справа и ничего не
   давали взамен, отступ слева в 18 и верхний в 43 — тот же логотип.
   Правило держим на классе страницы: .b-tabs_content лепра использует и
   в профиле, и в настройках, а их я не проверял. */
html.lm-fraud .b-tabs_content, html.lm-fraud .b-inner_container {
  width: auto !important; padding-left: 0 !important;
  padding-right: 0 !important; padding-top: 0 !important; }

/* Ширина документа 882 при экране 393 бралась не из содержимого, а из двух
   нижних пределов: min-width 770 у витрины и min-width 870 у отдела с
   мерчем. Всё остальное в отчёте — следствие: колонки, отступы, кегли и
   ширины полей считаются от этой ширины, поэтому чинить их по одному
   бессмысленно, пока стоят пределы. */
.b-fraud_showcase {
  min-width: 0 !important; margin: 0 0 16px !important;
  padding: 0 !important; }
.b-fraud_market { min-width: 0 !important; padding-left: 0 !important; }
.b-fraud_quick_block {
  padding: 0 0 0 4px !important; margin: 0 0 24px !important; }

/* Три колонки товаров — в одну. Порог unfloatWide сюда не дотягивается:
   треть от 369 — это 123 пикселя, меньше 40% экрана. */
.b-fraud_showcase_col { float: none !important; width: auto !important; }
/* Карточки и их обёртка залиты одним и тем же серым, и в столбик они
   слипаются в сплошное полотно. На десктопе их разделяли колонки. */
.b-fraud_showcase_col .b-fraud_showcase_product {
  border-bottom: 1px solid rgb(224, 224, 224) !important; }

/* Отбивка заголовка сверху в 44 пикселя и сдвиг витрины вправо на 41
   были рассчитаны на логотип магазина, который лежит выше и левее. */
.b-fraud_showcase_caption {
  font-size: 15px !important; line-height: 1.35 !important;
  margin: 0 0 10px !important; padding: 10px 0 0 !important; }
.b-fraud_logo { margin: 10px 0 12px !important; max-width: 100% !important; }

/* Карточка гражданства: тунец нарисован фоном размером 227×332 и отодвигал
   текст на 275 пикселей — на экране 393 под сам текст оставалось меньше
   сотни. Картинку уменьшаем втрое, отступ вместе с ней. */
.b-fraud_showcase_pro {
  padding-left: 100px !important; padding-right: 12px !important;
  background-size: 84px auto !important;
  background-position: 8px 12px !important; }

.b-fraud_showcase_product { font-size: 13px !important; }
.b-fraud_showcase_product h1 {
  font-size: 18px !important; line-height: 1.25 !important;
  padding-top: 10px !important; }
.b-fraud_showcase_product h2 { font-size: 16px !important; }
.b-i-fraud_showcase_product,
.b-i-fraud_showcase_product_description { padding: 10px 12px !important; }

/* Формы покупки: кегль полей 18 и ширины в пикселях заданы под карточку
   в треть от 770. Ширину отдаём содержимому, но с рамками в расчёте —
   иначе поле шириной во всю карточку вылезает на толщину рамки. */
.b-fraud_showcase .i-form_text_input,
.b-fraud_showcase .i-form_textarea {
  max-width: 100% !important; box-sizing: border-box !important; }
.b-fraud_showcase_product_form .b-hidden_content {
  padding: 14px 12px 12px !important; }
.b-fraud_showcase_product_form_price { font-size: 18px !important; }
.b-fraud_showcase_pro_new_sublepro_form .b-hidden_content {
  width: auto !important; padding: 14px 0 16px !important; }
.b-fraud_showcase_pro_new_sublepro_form .i-form_text_input {
  width: 150px !important; }
.b-fraud_showcase_pro_new_sublepro_form label {
  margin-right: 6px !important; }
.b-fraud_showcase_pro_new_sublepro_link i { font-size: 15px !important; }
.b-fraud_showcase .b-pro_acc_prolongation_friend_form { padding-left: 0 !important; }
/* поля наружу по 20 пикселей с каждой стороны — под широкую карточку */
.b-fraud_showcase_ranks_rebuy { margin: 0 !important; }

/* ============ ЗВАНИЯ (/fraud/ranks/) ============ */
/* Отступ слева в 20 пикселей рассчитан на логотип магазина, который лежит
   выше и левее содержимого. Справа его нет, поэтому на телефоне текст
   стоит несимметрично: слева 32 пикселя от края, справа 12. */
.b-fraud_text { padding: 14px 0 0 !important; }

/* ---- Строка «у вас нет должности» и галочка ----
   Оба куска — inline, и на десктопе стоят в одну строку. На телефоне
   галочка «не хочу званий от других» переносится и её подпись отрывается
   от квадратика. Ставим отдельной строкой. */
.b-ranks_current { margin-bottom: 12px !important; font-size: 13px !important; }
.b-block_external_ranks { display: block !important; margin: 6px 0 0 !important; }

/* ---- Форма «Добавить должность» ----
   Заголовок набран кеглем 30: одна надпись «Добавить должность:» — это
   296 пикселей при доступных 369, и поле в 25% ширины (92) уже не влезало
   в ту же строку. Дальше в той же строке шли поле ника фиксированной
   ширины 130, «за», поле цены 50, «ЛВ» и кнопка — всё это ломалось
   вперемешку. Кегль сбавляем, а поле должности пускаем отдельной
   строкой блоком: тогда предложение читается «Добавить должность: /
   <поле> / <ник> за <N> ЛВ» и переносы получаются по смыслу, а не по
   тому, где кончилось место.
   Шестнадцать у полей обязательны: ниже Safari на iOS наезжает
   увеличением при касании. */
.b-ranks_add_form { margin-bottom: 18px !important; }
.b-ranks_add_form h1 {
  font-size: 15px !important; line-height: 2 !important;
  margin: 0 0 4px !important; }
.b-ranks_add_form .b-ranks_input_rank {
  display: block !important; width: 100% !important;
  box-sizing: border-box !important;
  font-size: 16px !important; text-align: left !important;
  margin: 3px 0 6px !important; }
.b-ranks_add_form .b-ranks_input_username {
  width: 45% !important; max-width: 170px !important;
  box-sizing: border-box !important; font-size: 16px !important; }
.b-ranks_add_form .b-ranks_input_value {
  width: 62px !important; box-sizing: border-box !important;
  font-size: 16px !important; }
/* кнопка — картинка 54×20, у лепры она сидит на базовой линии текста */
.b-ranks_add_form .b-ranks_input_yarrr {
  margin-left: 8px !important; vertical-align: middle !important; }

/* ---- Блок объяснения: строка с уголком ----
   Уголок — переключением содержимого, а не поворотом: у правого края
   повёрнутый глиф заметно прыгает. */
.lm-ranks_about {
  display: block !important; width: 100% !important;
  box-sizing: border-box !important; text-align: left !important;
  position: relative !important; margin: 0 !important;
  padding: 9px 28px 9px 12px !important;
  font-family: inherit !important; font-size: 13px !important;
  color: inherit !important;
  background: rgb(236, 237, 239) !important;
  border: 0 !important; border-radius: 4px !important;
  -webkit-appearance: none !important; appearance: none !important; }
.lm-ranks_about:not(.lm-open) { margin-bottom: 14px !important; }
.lm-ranks_about.lm-open { border-radius: 4px 4px 0 0 !important; }
.lm-ranks_about::after {
  content: '▾'; position: absolute !important; right: 10px !important;
  top: 50% !important; margin-top: -0.6em !important;
  font-size: 12px !important; opacity: 0.6 !important; }
.lm-ranks_about.lm-open::after { content: '▴'; }
.lm-ranks_about:not(.lm-open) + .b-ranks_about { display: none !important; }
.b-ranks_about {
  padding: 2px 12px 4px !important; margin: 0 0 14px !important;
  border-radius: 0 0 4px 4px !important;
  font-size: 13px !important; line-height: 1.45 !important; }
.b-ranks_about h3 {
  font-size: 16px !important; line-height: 1.25 !important;
  margin: 0 0 6px !important; }
.b-ranks_about p { margin: 0 0 8px !important; }

/* ---- Таблица званий ----
   Четыре колонки с полями по 15 с каждой стороны требуют 595 пикселей при
   доступных 369: должность 146, ник 146, история 222, цена 81. Ячейки
   таблицы не переносятся целиком, поэтому браузер жмёт каждую по буквам —
   отсюда и «криво». Разворачиваем строку в две:

       должность                              2025 ЛВ
       ник   с 1 Марта 2021 перекупалась 2 раза

   Перелом строки делаем пустым флекс-элементом на 100% ширины: он занимает
   целую строку и уносит всё, что после него, вниз. Порядок задаём
   свойством order, а не перестановкой узлов, — разметку лепра
   перерисовывает своим скриптом при сортировке и по кнопке «Ещё». */
.b-ranks_table { display: block !important; width: auto !important; }
.b-ranks_table tbody { display: block !important; }
.b-ranks_table tr {
  display: flex !important; flex-wrap: wrap !important;
  align-items: baseline !important; gap: 2px 8px !important; }
.b-ranks_table_stat::after {
  content: '' !important; flex: 0 0 100% !important;
  height: 0 !important; order: 2 !important; }

/* Рамку и поля переносим с ячеек на строку: у ячеек они умножались на
   четыре и съедали 120 пикселей из 369.
   Селектор с tbody взят не для красоты: у лепры есть правило
   .b-ranks_table .b-ranks_table_stat_my td весом в два класса — своё
   звание она подчёркивает красным. Ровно по весу спор решался бы
   порядком объявления, а jsdom и браузер считают его по-разному, поэтому
   берём заведомо больший вес. */
.b-ranks_table tbody .b-ranks_table_stat td {
  display: block !important; border: 0 !important; padding: 0 !important;
  width: auto !important; }
.b-ranks_table tbody .b-ranks_table_stat {
  padding: 9px 0 8px !important;
  border-bottom: 1px solid rgb(224, 224, 224) !important; }
.b-ranks_table tbody .b-ranks_table_stat_my {
  border-bottom-color: rgb(255, 0, 0) !important; }

.b-ranks_table tbody .b-ranks_table_rank {
  order: 1 !important; flex: 1 1 auto !important; min-width: 0 !important;
  font-size: 15px !important; line-height: 1.25 !important; }
/* Цена — то, ради чего сюда приходят: по ней и перекупают. Держим её
   в конце первой строки и не даём сжиматься. */
.b-ranks_table tbody .b-ranks_table_price {
  order: 1 !important; flex: 0 0 auto !important;
  font-size: 15px !important; font-weight: bold !important;
  line-height: 1.25 !important; text-align: right !important; }
.b-ranks_table tbody .b-ranks_table_username {
  order: 3 !important; flex: 0 0 auto !important; font-size: 13px !important; }
.b-ranks_table tbody .b-ranks_table_history {
  order: 4 !important; flex: 1 1 auto !important; min-width: 0 !important;
  font-size: 11px !important; line-height: 1.3 !important;
  opacity: 0.6 !important; }

/* Заголовки колонок — это переключатели сортировки (по ним есть
   обработчик у лепры, а подчёркиванием она их и помечает). Строкой
   таблицы им быть больше незачем, но кнопками остаться надо. */
.b-ranks_table tbody th {
  display: block !important; border: 0 !important;
  padding: 5px 8px !important; border-radius: 4px !important;
  background: none !important; }
.b-ranks_table tbody th.b-active {
  background-color: rgb(224, 226, 230) !important; }
.b-ranks_table tbody th span { font-size: 12px !important; }
.b-ranks_table tbody th.b-active span { text-decoration: none !important; }

/* Поле, в которое превращается цена при перекупке. Кегль у лепры 14 —
   ниже порога, за которым Safari наезжает увеличением на касание.
   Высота 34 с таким же межстрочным раздвигала строку вдвое. */
.b-ranks_table .js-ranks_new_price_holder_table {
  height: auto !important; line-height: 1.25 !important; }
.b-ranks_table .js-ranks_new_price_holder input {
  font-size: 16px !important; width: 66px !important;
  box-sizing: border-box !important; }

/* «Ещё» — плавающая кнопка шириной по содержимому. Плавание снимаем
   (под ним пустая строка от .clear), кнопку растягиваем: она одна внизу
   длинного списка, и промахиваться по ней незачем. */
.b-ranks_table_more {
  float: none !important; display: block !important;
  height: auto !important; text-align: center !important;
  margin: 12px 0 0 !important; padding: 11px 14px !important;
  border-radius: 4px !important; }
.b-ranks_cols { margin-bottom: 20px !important; }

/* ============ ОПЕРАЦИИ С ЛВ (/fraud/refuel/) ============ */
/* Снизу у контейнера 170 пикселей пустоты — почти пол-экрана ни подо что.
   На десктопе она уравновешивала высокую правую колонку, в одну колонку
   это просто дыра перед подвалом. */
.b-refuel_container { padding: 16px 0 24px !important; }
/* Две колонки 62/38 — в одну. Правая под порог unfloatWide не попадает:
   38% от 369 — это 140 пикселей, меньше 40% экрана. */
.b-refuel_container .b-left_col, .b-refuel_container .b-right_col {
  float: none !important; width: auto !important;
  padding: 0 !important; }
.b-refuel_container .b-right_col { margin-top: 20px !important; }

.b-fraud_refuel { font-size: 15px !important; }
.b-fraud_refuel form { margin-bottom: 16px !important; }
.b-fraud_refuel .i-form_text_input { width: 90px !important; }
.b-fraud_refuel_fz54_contact .i-form_text_input { width: 100% !important; }
.b-fraud_refuel_fz54_contact { font-size: 12px !important; }
/* Кнопки оплаты: два блока по 150 в inline-block. Логотипы 127×27 и
   128×24 в них влезают, а вот сдвиг самой кнопки на -5 пикселей влево
   ставил её мимо центра своего блока — это заметно, когда блоки стоят
   парой. */
.b-fraud_refuel_pay_button .b-button {
  margin-left: 0 !important; padding: 8px 14px !important; }

/* Курс — шутка, набранная 53 пикселями с запретом переноса: «1 ЛВ = 1
   РУБ» это 300 пикселей текста плюс 74 полей, то есть 374 при доступных
   369, и плашка вылезала за экран. Ужимаем ровно настолько, чтобы она
   осталась крупной и при масштабе 125%: 216 текста плюс 40 полей. */
.b-refuel_rate {
  font-size: 38px !important; padding: 18px 20px !important;
  text-align: center !important; margin: 8px 0 10px !important; }
.b-refuel_rate em { font-size: 26px !important; }
.b-refuel_rate_desc { font-size: 12px !important; line-height: 1.45 !important; }

/* ============ ПРОФ. АККАУНТ (/fraud/professional/) ============ */
/* Заголовок в 29 пикселей с отбивкой сверху в 48 и дата в 24 — на
   десктопе это шапка страницы во всю ширину, на телефоне «Вы —
   гражданин Лепрозория.» занимало две строки, а дата под ним — три. */
.b-fraud_members h2 {
  font-size: 21px !important; line-height: 1.25 !important;
  padding-top: 16px !important; margin-bottom: 10px !important; }
.b-payed_duration {
  font-size: 16px !important; line-height: 1.35 !important;
  margin-bottom: 18px !important; }

/* Блок продления был жёстко 600 пикселей — переполнение на 231 при
   доступных 369, и оно тянуло за собой ширину всего документа. */
.b-pro_acc_prolongation { width: auto !important; font-size: 13px !important; }
/* Отступ слева держит красную руку: она 32x34 и прибита абсолютно к
   левому краю. Отбивка снизу в 34 между двумя абзацами — десктопный
   воздух. */
.b-pro_acc_prolongation_text {
  padding-left: 38px !important; margin-bottom: 16px !important;
  line-height: 1.4 !important; }
.b-fraud_members .b-pro_acc_prolongation_friend_form {
  padding-left: 38px !important; }
.fraud_members_payed_text { font-size: 13px !important; line-height: 1.5 !important; }

/* Вопросы-ответы. Заголовок «У меня есть вопросы!» — 24 пикселя с полем
   снизу в 43, и это при том, что сам список свёрнут: до нажатия на
   странице стоял пустой отступ в полсотни пикселей. */
.b-fraud_members_questions {
  margin-top: 24px !important; padding-bottom: 20px !important; }
.b-fraud_members_questions h3 {
  font-size: 17px !important; line-height: 1.3 !important;
  padding: 16px 0 18px !important; }
.b-members_questions h4 { margin-top: 16px !important; line-height: 1.3 !important; }
.b-members_questions p { padding-bottom: 14px !important; line-height: 1.5 !important; }
/* Образец меню с Чарли — картинка 271x78 обтеканием справа. Рядом с ней
   на текст оставалось меньше сотни пикселей. */
.b-charley_in_menu_sample {
  float: none !important; display: block !important;
  max-width: 100% !important; height: auto !important;
  margin: 0 0 12px !important; }

/* ============ ЗАМЕНЫ (/fraud/replacements/) ============ */
/* 85% ширины без центрирования: справа оставалась полоса в 55 пикселей,
   а полезной ширины внутри полей по 20 выходило 274 из 369. */
.b-fraud_replace { width: auto !important; padding: 16px 0 !important; }
/* Заголовок в 28 пикселей — «Замена слов и фраз в Лепрозории на 1 день!»
   это 641 пиксель текста, то есть три строки. Красный кружок с ценой
   лежит ВНУТРИ заголовка строчным блоком 120x120 и на десктопе стоит
   справа от него; в узкой колонке он попадает в поток текста, поэтому
   уменьшаем его вместе с кеглем и уводим отдельной строкой. */
.b-fraud_replace_caption {
  font-size: 20px !important; line-height: 1.3 !important;
  margin-bottom: 14px !important; }
.b-fraud_replace_price {
  display: block !important; width: 84px !important; height: 84px !important;
  line-height: 84px !important; font-size: 19px !important;
  margin: 10px 0 0 !important; }

/* Форма замены: два поля по 28% — это по 77 пикселей, куда не помещается
   даже подсказка «другое». Подписи и поля ставим столбиком во всю
   ширину. */
.b-fraud_replace_form { padding: 16px 14px !important; }
.b-fraud_replace_form_label {
  display: block !important; margin: 0 0 3px !important;
  font-size: 13px !important; }
.b-fraud_replace_form_input {
  display: block !important; width: 100% !important;
  box-sizing: border-box !important; margin-bottom: 12px !important; }
.b-fraud_replace_form_submit { margin-top: 4px !important; }
.b-fraud_replace_description {
  margin-bottom: 20px !important; font-size: 13px !important;
  line-height: 1.5 !important; }

/* Проверялка замен: поле ввода и окно вывода по 35% строчными блоками,
   то есть на десктопе рядом. В 369 пикселях рядом им не встать.
   Раскрытие ведёт лепра через max-height — механику не трогаем. */
.b-fraud_replace_checker_form { margin-bottom: 20px !important; }
.b-fraud_replace_checker_form_input {
  display: block !important; width: 100% !important;
  box-sizing: border-box !important; height: 110px !important;
  margin-bottom: 8px !important; }
.b-fraud_replace_checker_form_output {
  display: block !important; width: 100% !important;
  box-sizing: border-box !important; }
.b-fraud_replace_checker_toggle { font-size: 16px !important; }

/* ============ ОСНОВНЫЕ ВЕЩИ (/fraud/greetings/) ============ */
/* Форма приветствий — две колонки 60/39 с разделительной чертой между
   ними. У гражданина без денег на счету лепра не выводит ни одной из
   них, но левая остаётся в разметке пустой, а нижний предел высоты у
   неё 186 пикселей плюс отбивка сверху 25 — полэкрана пустоты сразу под
   подписью «сначала пополните счет».
   Отступ между колонками задаём полем, а не отбивкой: пустая колонка с
   одним лишь полем схлопывается сама, отбивка осталась бы видна. */
.b-fraud_greetings { padding: 8px 0 16px !important; }
.b-fraud_greetings .b-settings_left_col,
.b-fraud_greetings .b-settings_right_col {
  float: none !important; width: auto !important; max-width: none !important;
  min-height: 0 !important; margin: 0 !important;
  padding: 0 !important; border: 0 !important; }
.b-fraud_greetings .b-settings_right_col { padding-top: 16px !important; }
.b-fraud_greetings .b-form_field { margin-bottom: 14px !important; }

/* ---- Окно подтверждения покупки («окно Чарли») ----
   Открывается на любой покупке: продление гражданства, звания, никнейм.
   Держатель прибит к верху экрана и высотой в один пиксель, а само окно
   выходит из него наружу и задано шириной 666 — то есть в полтора экрана.
   Крестик закрытия у него absolute от правого края окна, поэтому уезжал
   за экран вместе с ним, а закрыть окно больше нечем: подложка тапы
   не принимает, и остаётся только «назад».

   Держатель при этом ровно 393 в ширину, поэтому общая подгонка слоёв
   его не трогала — она смотрит на рамку, а виновато содержимое. */
#charley_holder .charley {
  /* Ширину окна задаём настройкой, а картинку кладём ровно по окну.
     Раньше окно было во весь экран, а картинка занимала долю его ширины,
     и справа оставалась полоса заливки шириной в эту разницу — она и
     выглядела торчащей подложкой. Теперь лишнего места нет вовсе. */
  width: ${CFG.charleyArt}% !important; max-width: 100% !important;
  /* auto по бокам — окно снова по центру. У лепры здесь margin: -200px
     auto 0, и обнулять боковые поля было незачем: вправо окно уезжало
     не из-за них, а из-за ширины в 666 пикселей. */
  margin-left: auto !important; margin-right: auto !important;
  min-height: 0 !important;
  /* Доска с тунцом и КРЕСТИК ЗАКРЫТИЯ — всё одна картинка 660×318.
     Отдельного значка у крестика нет: .close — просто прозрачный
     квадрат 51×51 поверх нарисованного. Поэтому масштабировать можно
     только по ширине: cover обрезал картинку сбоку, и крестик, который
     нарисован у правого края, пропадал — тап работал, а видно не было.
     Если окно выше картинки, низ добирается цветом самой доски: он
     замерен по ней и одинаков в середине и у края, шва не будет. */
  background-size: 100% auto !important;
  background-color: rgb(44, 44, 44) !important; }

/* Отступ слева был 200 пикселей — ровно под тунца в натуральную величину.
   На картинке тунец нарисован до 148-го пикселя из 660, то есть занимает
   22% ширины; картинка растянута по ширине окна, значит те же 22% окна
   при любом экране. Отсюда 24%: те же 22 плюс небольшой зазор до текста.
   Справа оставляем место крестику — его квадрат 51 пиксель. */
#charley_holder .charley_inner {
  padding: 14px 56px 12px 24% !important; }
#charley_holder .text {
  font-size: 14px !important; line-height: 1.35 !important;
  margin-bottom: 10px !important; }
#charley_holder .yes, #charley_holder .no { font-size: 15px !important; }
#charley_holder .password_holder {
  font-size: 12px !important; margin: 6px 0 !important; }
/* Кегль поля был 8 пикселей. Ниже 16 Safari на iOS наезжает камерой на
   поле при касании, поэтому именно 16, а не «покрупнее». */
#charley_holder .password_holder input {
  font-size: 16px !important; width: 110px !important;
  padding: 2px 4px !important; }
#charley_holder .close { right: 2px !important; top: 2px !important; }

/* ============ ЧАРЛИ (вкладка с тунцом) ============ */
/* Страница собрана из трёх плавающих колонок под ширину около 900 пикселей:
   тунец 184px слева, текст с отступом ровно в эти 184, ниже «важная
   информация» в половину строки и колонка подлепрозориев в 39%. На
   телефоне из этого выходит текст в двести пикселей шириной, пустая
   колонка справа и дата, вылезающая за экран. */

/* 96% оставляли полосу справа и ничего не давали взамен */
.b-inner_container { width: auto !important; }
.b-pro_account_container { padding-bottom: 8px !important; }

/* Тунец остаётся слева обтекаемым блоком, но вдвое уже: 184 пикселя из
   393 — это половина экрана под картинку с подписью. Отступ слева у
   текста снимаем совсем. Тогда текст идёт справа от тунца, а закончив
   его высоту — продолжается под ним во всю ширину, вместо того чтобы
   стоять узкой колонкой до самого низа. Нижние поля по 80 пикселей
   выравнивали колонки между собой и здесь дают только пустоту. */
.b-pro_acc_charlie {
  width: 116px !important; margin: 0 12px 6px 0 !important; }
.b-pro_acc_charlie img { max-width: 100% !important; height: auto !important; }
.b-pro_acc_charlie p { width: auto !important; line-height: 1.35 !important; }
.b-pro_acc_text {
  margin: 0 !important; padding: 0 !important;
  font-size: 13px !important; line-height: 1.5 !important; }

/* «Крупно и красным» — шутка, набранная 48 пикселями. Дата в них выходит
   за экран (412 пикселей при окне 393) и разгоняет ширину всего документа
   до 441. Кегль сбавляем, но перепад между строкой и датой оставляем:
   без него от шутки ничего не остаётся. */
.b-pro_acc_info {
  float: none !important; width: auto !important;
  padding: 10px 0 8px !important; }
.b-pro_acc_info p { margin: 0 0 6px !important; line-height: 1.4 !important; }
.b-pro_acc_info .b-pro_acc_expire {
  font-size: 15px !important; line-height: 1.3 !important;
  padding-top: 4px !important; }
.b-pro_acc_info .b-pro_acc_expire .b-valid_till { font-size: 15px !important; }
.b-pro_acc_info .b-pro_acc_expire em { font-size: 22px !important; }

/* Колонка подлепрозориев: 39% ширины, у гражданина без своих подлепр
   пустая — тогда это просто плавающий пустой блок, сдвигающий соседей.
   Порог unfloatWide до неё не дотягивается: 138 пикселей меньше 40%
   экрана, поэтому снимаем обтекание правилом.
   Отступ сверху задаём полем, а не отбивкой: у гражданина без своих
   подлепр блок пуст, и пустой блок с одним лишь полем схлопывается сам
   в ноль высоты, тогда как отбивка осталась бы видимой полосой.
   Проверка :empty здесь не годится: внутри блока лежит перевод строки. */
.b-pro_acc_subs {
  float: none !important; width: auto !important;
  padding-top: 0 !important; margin-top: 8px !important; }

/* Строка ссылок под вкладками — обычный текст с разделителями */
.b-my_posts_feed_controls_navigation {
  font-size: 12px !important; line-height: 1.6 !important; }

/* ============ ПОДСАЙТЫ ============ */
.l-header_subsite { padding-left: 0 !important; }
.l-content_aside_subsite { display: none !important; }
/* Девиз подсайта. Тридцать пикселей десктопа на телефоне давали три
   строки — при том, что это подпись, а не заголовок страницы.
   Стоит по центру и никогда не переносится: девиз — единая фраза, и
   разорванный на две-три строки он читается как обрывок ленты, а не как
   подпись подлепры. Уместить его в строку одним CSS нельзя, кегль
   подбирает fitSubsiteHeader по замеру; здесь только начальное значение.
   overflow: hidden — страховка на случай, если подгонка не отработала
   (кегль ещё не подобран, замер дал ноль, проход упал): без неё nowrap
   растягивает страницу вбок и ломает всю ленту, а не одну надпись. */
.b-subsite_header {
  /* Три пикселя снизу — не отбивка, а место под тень: overflow: hidden
     режет её вместе с содержимым, и без поля у надписи снизу тень
     обрывалась. Отбивку на те же три уменьшили, общая высота прежняя. */
  padding: 4px 0 3px 0 !important; margin: 0 0 1px 0 !important;
  font-size: ${CFG.subsiteTitle}px !important; line-height: 1.2 !important;
  text-align: center !important;
  white-space: nowrap !important;
  overflow: hidden !important; text-overflow: ellipsis !important;
  /* заголовок часто лежит поверх фотографии */
  text-shadow: 0 1px 2px rgba(255,255,255,.9) !important; }
.b-subsite_header a { padding: 0 !important; margin-left: 0 !important; }
/* дубликат логотипа: тот, что в шапке, лепра рисует своими средствами */
.b-subsite_logo { display: none !important; }
.l-content__subsite .b-archive_heading { padding-right: 0 !important; }

/* Полоса оформления подлепры под её заглавием. Устройство — у
   buildSubsiteBand; здесь только раскладка.
   Высоту ставит скрипт замером картинки, а до замера полоса нулевая:
   заранее выделенное место при неудачной загрузке осталось бы дырой.
   Повтор по горизонтали и привязка к левому верхнему углу — как было у
   лепры: картинки эти рисуются с расчётом на бесконечную ленту вправо. */
#lm-subband {
  display: block !important;
  height: 0 !important;
  margin: 4px -${CFG.pageEdge}px 8px !important;
  background-repeat: repeat-x !important;
  background-position: left top !important;
  pointer-events: none !important; }

/* Белое поле тела подлепры. Это НЕ чужое оформление и не наш промах —
   правило лепровское, из её общей таблицы: узел .l-content__subsite
   покрашен там в чистый белый. На светлой теме его не видно, страница тоже
   белая. А в наших схемах оно вылезает сразу: в обратной («светлые
   карточки на тёмном») тело остаётся белым, и притемняется только
   шапка; в тёмной теме белое становится чёрным поверх нашего тона.
   Поэтому гасим: фон под карточками должен задавать один узел на всю
   страницу, а не два разных на разных её половинах. */
.l-content__subsite { background-color: transparent !important; }
.b-new_sublepra { width: auto !important; padding: 12px 0 !important; }

/* правая колонка в 330px оставляла ленте около сорока пикселей.
   Полосы сверху и снизу: свёрнутое пенсне — это одна строка между девизом
   и лентой, и без верхней черты она читалась началом ленты, а не отдельным
   блоком. Отбивка сверху в три пикселя — чтобы черта не липла к девизу;
   вместе с самой чертой подпись пенсне опускается на четыре пикселя. */
.b-subdomain_aside_right {
  float: none !important; width: auto !important;
  margin: 3px 0 10px !important; padding-bottom: 0 !important;
  border-top: 1px solid rgb(226, 224, 222) !important;
  border-bottom: 1px solid rgb(226, 224, 222) !important; }
/* Распорки под снятые обтекания: своей высоты у них нет, но каждая
   рвёт схлопывание полей соседей и добавляет строку пустоты.
   Селектор нарочно не прямой: собранное пенсне переносит содержимое
   колонки на уровень ниже, в .lm-pince_body, и «>» перестал бы попадать. */
.b-subdomain_aside_right .clear { display: none !important; }
.b-subdomain_aside_subscribe {
  height: auto !important; overflow: visible !important;
  margin-bottom: 0 !important; }
.b-subdomain_aside_subscribe .b-subscribe_button {
  float: none !important; width: auto !important; margin: 0 0 2px !important; }
.b-subdomain_aside_subscribe_additional {
  float: none !important; width: auto !important; margin-top: 2px !important; }
.b-subdomain_aside_subscribe_expand {
  position: static !important; left: auto !important; top: auto !important;
  transform: none !important; display: inline-block !important;
  margin-left: 6px !important; }
.b-subdomain_settings_button { right: 4px !important; top: 4px !important; }
.b-subdomain_aside_right .b-domain_popup_controls {
  margin-bottom: 2px !important; }

/* Описание подлепры — свободный текст, набранный правлением вручную.
   У лепры это правая колонка: float, 286px ширины и 30px поля справа.
   Обтекание здесь снимаем правилом, а не эвристикой unfloatWide: в
   свёрнутом пенсне блок скрыт, ширина у него нулевая, и проверка
   «шире 40% экрана» не сработает — а пометку «просмотрено» проход
   уже поставит, и после разворота никто сюда не вернётся. */
.b-domain_description {
  float: none !important; width: auto !important;
  padding: 0 !important; margin: 0 !important;
  border-bottom: 0 !important;
  font-size: 13px !important; line-height: 1.45 !important; }
/* Абзацы там разделены парами <br>. На десктопной колонке это выглядит
   списком, на телефоне — двойным межстрочным на весь блок. Вторую
   строку убираем: одинарного разрыва хватает. */
.b-domain_description br + br { display: none !important; }

/* ---- Простое пенсне ----
   Свод правил и ссылок подлепры, сложенный в одну строку. Название —
   по волшебному пенсне в профиле: там таким же нажатием разворачивается
   лента заметок. */
.lm-pince {
  display: flex !important; align-items: center !important; gap: 7px !important;
  width: 100% !important; box-sizing: border-box !important;
  margin: 0 !important; padding: 5px 0 !important;
  background: none !important; border: 0 !important;
  -webkit-appearance: none !important; appearance: none !important;
  /* Шорткат font: inherit здесь стоял и съедал заданный ниже кегль:
     он сбрасывает font-size последним значением из наследования. */
  font-family: inherit !important; font-weight: normal !important;
  font-size: 13px !important; line-height: 1.3 !important;
  color: inherit !important;
  text-align: left !important; cursor: pointer !important;
  -webkit-user-select: none !important; user-select: none !important;
  -webkit-tap-highlight-color: transparent !important; }
/* Стёкла и шеврон одной ширины — как в навигационной штуке. Подпись
   растягивается на остаток строки и центруется в нём; поскольку по краям
   от неё отведено поровну (30 + отбивка с каждой стороны), середина
   остатка и есть середина строки. Прежде подпись стояла сразу за
   стёклами, а шеврон уходил вправо полем auto. Ширина 30 — по стеклу:
   svg нарисован как раз в 30 пикселей. */
.lm-pince_glass, .lm-pince_arrow { flex: 0 0 30px !important; }
.lm-pince_glass { display: block !important; }
.lm-pince_label {
  flex: 1 1 auto !important; min-width: 0 !important;
  text-align: center !important; }
/* Шеврон у правого края строки. */
.lm-pince_arrow {
  margin-left: 0 !important; text-align: right !important;
  font-size: 10px !important;
  color: rgb(130, 130, 130) !important; }
/* Развёрнутое состояние — сменой знака, а не поворотом. Поворот идёт
   вокруг середины коробки шеврона, а сам знак прижат к её правому краю:
   на 30 пикселях ширины он перепрыгивал бы к левому, и шеврон при
   каждом развороте гулял по строке. Знак пишем содержимым псевдоэлемента,
   поэтому в разметке span пустой. */
.lm-pince_arrow::before { content: '▾' !important; }
.lm-pince__open .lm-pince_arrow::before { content: '▴' !important; }
.lm-pince_body { padding: 2px 0 8px !important; }

/* Левая колонка подсайта — управляющий, правление, блоги империи.
   Общим правилом выше она скрыта: на десктопе это столбец в 245px с
   фоновой картинкой bg_left.png, а поля в 45-65 пикселей у пунктов
   отбиты под нарисованные на ней завитки. Текст в ней ровно тот же
   «о подлепре», поэтому в теле пенсне она разворачивается — без
   картинки, без полей и без трёх декоративных подложек поверх.
   Правило заведомо весомее скрывающего (два класса против одного) и
   стоит ниже по файлу: иначе jsdom и браузер решили бы спор по-разному. */
.lm-pince_body .l-content_aside_subsite {
  display: block !important; float: none !important;
  width: auto !important; min-height: 0 !important;
  background: none !important;
  margin: 6px 0 0 !important; padding: 6px 0 0 !important;
  border-top: 1px solid rgb(238, 236, 234) !important; }
.lm-pince_body .b-aside_item {
  padding: 0 !important; margin: 0 0 5px !important;
  min-height: 0 !important; }
.lm-pince_body .b-aside_president a,
.lm-pince_body .b-aside_president b { font-size: 14px !important; }
.lm-pince_body .b-aside_president p {
  margin: 0 !important; font-size: 11px !important; }
.lm-pince_body .b-aside_government a,
.lm-pince_body .b-aside_imperial_blogs strong,
.lm-pince_body .b-aside_imperial_blogs a { font-size: 13px !important; }
.lm-pince_body .b-aside_imperial_blogs strong {
  padding-left: 0 !important; margin-bottom: 2px !important; }
.lm-pince_body .b-aside_imperial_blogs ul { margin: 0 !important; }
.lm-pince_body .b-aside_imperial_blogs li {
  padding-left: 0 !important; margin-bottom: 0 !important; }
/* подложки — вырезанные куски той самой фоновой картинки колонки */
.lm-pince_body .b-aside_president_bg,
.lm-pince_body .b-aside_imperial_blogs_bg { display: none !important; }
.b-subdomain_aside_right:not(.lm-pince__open) .lm-pince_body {
  display: none !important; }

/* ============ КНОПКА ПОДПИСКИ ============ */
/* Кнопка устроена так: значок лежит абсолютно в начале строки, а подпись
   к нему («подписаться» / «отписаться») раскрывается с нулевой ширины
   по наведению мыши. На телефоне наведения нет, поэтому от кнопки
   оставался один серый значок в двадцать пикселей: у неподписанного
   плюс, у подписанного шеврон вниз, который читается как «раскрыть
   список», а не как состояние. Понять, подписан ли ты, было нельзя,
   а тап сразу выполнял действие.
   Разворачиваем подпись насовсем — ровно то, что на десктопе показывает
   наведение, включая замену шеврона на минус у подписанного. Значок при
   этом должен встать в поток: раскрытая подпись растёт вправо и абсолютным
   блоком легла бы поверх числа подписчиков. */
.b-subscribe_button {
  display: inline-flex !important; align-items: center !important; }
.b-subscribe_button_icon {
  position: static !important; top: auto !important; left: auto !important;
  display: inline-flex !important; align-items: center !important;
  height: 24px !important; padding: 0 5px !important;
  flex: 0 0 auto !important; }
.b-subscribe_button_hover_text::after,
.js-subscribed .b-subscribe_button_hover_text::after {
  max-width: 100px !important; padding-left: 5px !important;
  padding-right: 0 !important; }
.js-subscribed .b-subscribe_button_icon span[data-name="subscribed"] {
  display: none !important; }
.js-subscribed .b-subscribe_button_icon span[data-name="unsubscribe"] {
  display: inline-block !important; }
/* число подписчиков отступало на 32 пикселя от левого края — обходило
   значок, которого там больше нет */
.b-subscribe_button_text {
  position: static !important; left: auto !important;
  line-height: 1.3 !important; padding-left: 7px !important; }

/* ============ СПИСОК ПОДСАЙТОВ (underground) ============ */
/* Тело пункта занимало 50% ширины, описание плавало на 45%, счётчики
   стояли абсолютно на 40, 52 и 64 процентах — всё складывалось в кашу. */
.b-list_item { padding-bottom: 8px !important; }
.b-list_item_body { width: auto !important;
                    padding: 12px 0 12px 78px !important; }
.b-list_item_logo { top: 12px !important; left: 2px !important; }
/* Описание и дополнительные настройки лепра сворачивает через max-height: 0,
   но отбивки вокруг них при этом остаются видимыми — 26 пикселей воздуха
   на пункт, а пунктов на странице четыре десятка. Поля даём только
   раскрытому пункту. */
.b-list_item_blog_description {
  float: none !important; width: auto !important; margin: 0 !important; }
.b-list_item_blog_controls_additional { margin: 0 !important; }
.b-list_item__opened .b-list_item_blog_description {
  margin: 6px 0 2px !important;
  font-size: 13px !important; line-height: 1.4 !important; }
.b-list_item__opened .b-list_item_blog_controls_additional {
  margin-top: 8px !important; }
.b-list_item_blog_stats {
  position: static !important; width: auto !important;
  display: flex !important; flex-wrap: wrap !important;
  gap: 4px 14px !important; margin: 4px 0 6px !important; }
.b-list_item_blog_stats_posts,
.b-list_item_blog_stats_comments,
.b-list_item_blog_stats_subscribers {
  position: static !important; left: auto !important; top: auto !important;
  width: auto !important; text-align: left !important; }
.b-list_item_blog_toggle_expand { right: 4px !important; top: 12px !important; }
.b-list_item_user_karma {
  position: static !important; width: auto !important;
  text-align: left !important; }
.b-list_item_blog_controls label { display: inline !important;
                                   margin-left: 4px !important; }
.b-list_item_blog_controls p { margin: 0 0 8px !important; }
.b-list_item__user { margin-right: 0 !important; }
.b-subscriptions_random { display: none !important; }

/* Список подлепр карточками — теми же, что посты и комментарии. Числа
   не подобраны заново, а взяты из общих переменных: рамка, скругление,
   заливка и свечение те же, что у .post. Иначе через месяц одно из
   четырёх разойдётся с остальными и никто не вспомнит, какое верное.

   Отбивка между карточками 8, а не 14, как у постов. Карточка поста
   занимает пол-экрана, и четырнадцать между такими — просвет; здесь
   карточка в шестьдесят пикселей, и тот же просвет читался бы дырой.
   Восемь — тот же порядок, что и внутренние поля карточки, то есть
   список выглядит рядом коробок, а не россыпью.

   Правила ниже намеренно привязаны к .b-blogs_list: те же классы
   .b-list_item носит список граждан, у него своя разметка и своя
   ширина. */
.b-blogs_list .b-list_item {
  display: flex !important; flex-direction: column !important;
  box-sizing: border-box !important;
  padding: 6px 8px 8px !important; margin-bottom: 8px !important;
  border: 1px solid ${FRAME_C} !important;
  border-radius: ${FRAME_R}px !important;
  background-color: ${CARD_BG} !important;
  background-image: ${CARD_GLOW} !important; }
/* Описание лежит в разметке ПЕРЕД телом: на десктопе оно уплывало вправо
   и логотипу не мешало, а без обтекания встало бы первой строкой пункта —
   поверх логотипа, который позиционирован абсолютно. Меняем порядок. */
.b-blogs_list .b-list_item_body {
  order: 1 !important; padding: 0 0 0 54px !important; }
.b-blogs_list .b-list_item_blog_description { order: 2 !important; }
/* распорка под обтекание; во флекс-колонке она встала бы первым элементом */
.b-blogs_list .b-list_item > .clear { display: none !important; }
/* Герб отсчитывается от коробки карточки, а не от её содержимого, —
   поэтому его угол выставлен ровно по полям карточки (6 и 8). Тогда
   отбивка тела слева в 54 (44 герб плюс 10 просвета) отсчитывается от
   того же места и даёт ровный просвет; при left: 0 герб залезал бы на
   рамку. Верхнюю отбивку тела при этом снимаем совсем: её задаёт поле
   карточки, а два источника отступа между одними и теми же узлами
   всегда кончаются двойным. */
.b-blogs_list .b-list_item_logo {
  width: 44px !important; height: 44px !important;
  top: 6px !important; left: 8px !important; }
/* Адрес, название и создатель занимали три строки из четырёх. Адрес и
   название читаются как одна строка, разделителя у лепры нет — ставим сами. */
.b-blogs_list .b-list_item_body_text { line-height: 1.3 !important; }
.b-blogs_list .b-list_item h5 { display: inline !important;
                                margin: 0 !important; }
.b-blogs_list .b-list_item_blog_prefix { font-size: 13px !important; }
.b-blogs_list .b-list_item_blog_prefix::after {
  content: ' · ' !important; color: rgb(160, 160, 160) !important; }
.b-blogs_list .b-list_item_blog_creator {
  display: block !important; margin: 1px 0 0 !important;
  font-size: 12px !important; }
.b-blogs_list .b-list_item_blog_controls { margin-top: 3px !important; }
/* Ссылкой подписки у лепры служит вся строка целиком, вместе с числом
   подписчиков: оно выглядит подписью, а работает кнопкой, и промах по
   пункту списка молча менял подписку. Оставляем нажимаемым только сам
   значок с подписью; тап по числу уходит пункту и раскрывает описание.
   Событие с значка всплывает до ссылки, обработчик лепры не задет. */
.b-blogs_list .b-subscribe_button { pointer-events: none !important; }
.b-blogs_list .b-subscribe_button_icon { pointer-events: auto !important; }

/* Строка режимов, сортировки и поиска. Поле поиска в 300 пикселей плавало
   вправо с отбивкой в 40, списки несли поля по 10 — три уровня, ни один
   не совпадал с краем пунктов списка. */
.b-underground_nav { margin: 6px 0 8px !important; padding: 0 !important; }
.b-underground_nav ul { margin: 0 !important; padding: 0 !important; }
.b-underground_nav_mode li { padding: 3px 7px !important;
                             margin: 0 4px 0 0 !important;
                             font-size: 14px !important; }
.b-underground_nav_sort { display: block !important;
                          margin: 7px 0 0 !important; }
.b-underground_nav_sort li { margin-right: 14px !important; }
.b-menu_underground_search { float: none !important;
                             display: block !important;
                             margin: 8px 0 0 !important; }
.b-menu_underground_search form {
  width: auto !important; margin: 0 !important;
  display: flex !important; align-items: center !important; }
/* Кегль поля берём тот же, что у форм комментария, и по той же причине:
   у лепры тут 14, Safari считает такое поле мелким и при касании
   приближает к нему страницу — а окно раскладки шире экрана, и правый
   край формы вместе с кнопкой поиска уезжает за кромку.
   Переменная, а не число: шестнадцать — требование к тому, ЧТО ВИДНО НА
   ЭКРАНЕ. При масштабе страницы 85% шестнадцатый кегль доходит до глаза
   четырнадцатым, и приближение возвращается. --lm-form-font считает
   formFontVar делением на visualViewport.scale и пересчитывает при
   каждой смене масштаба; на этой странице она уже есть — функция
   зовётся в fullPass, а не по месту. Запасное значение в var() — на
   случай, если переменной почему-то нет. */
.b-menu_underground_search .i-form_text_input {
  width: auto !important; flex: 1 1 auto !important;
  font-size: var(--lm-form-font, ${CFG.formFont}px) !important; }
.l-subscription_list .b-load_more_posts_button {
  margin-bottom: 16px !important; }

/* Врезка с подлепрой дня (Девито) — первой на странице, над списком.
   Отсчитывалась от левой колонки в 245 пикселей: на телефоне это
   отжимало её к правому краю в вертикальную полоску. Отбивка снизу в
   60 — расчёт на пустое поле рядом с колонкой.

   Дальше делаем её той же карточкой, что и пункты списка под ней: она
   и есть подлепра, только вынутая наверх, и выглядеть иначе ей незачем.
   Числа взяты из тех же переменных и повторяют устройство карточки
   списка один в один — герб абсолютно в углу по полям коробки, текст с
   отбивкой в 54 (44 герб плюс 10 просвета).
   Своя заливка rgb(246,245,245) при этом снимается: карточка красится
   общими CARD_BG и свечением, а серая подложка под ними давала третий
   тон, которого больше нигде нет. */
.l-content_aside_subscriptions_top { margin: 0 0 8px !important; }
.l-content_aside_subscriptions_top .b-subscriptions_aside_block {
  box-sizing: border-box !important;
  padding: 6px 8px 8px !important; margin: 0 !important;
  border: 1px solid ${FRAME_C} !important;
  border-radius: ${FRAME_R}px !important;
  background-color: ${CARD_BG} !important;
  background-image: ${CARD_GLOW} !important; }
/* Герб. У лепры он просто absolute без координат и размера — то есть
   стоит там, где пришёлся бы в потоке, и во всю свою натуральную
   величину. Задаём то же гнездо, что у карточек списка.
   object-fit, а не одна ширина: файл может оказаться не квадратным, и
   тогда жёсткие 44 на 44 его сплющили бы. */
.l-content_aside_subscriptions_top .b-subscriptions_aside_block img {
  top: 6px !important; left: 8px !important;
  width: 44px !important; height: 44px !important;
  object-fit: contain !important; margin: 0 !important; }
/* Название, описание и кнопка подписки — с той же отбивкой, что и тело
   карточки списка. У лепры тут 75: место под герб в 64. */
.l-content_aside_subscriptions_top .b-subscriptions_aside_block h3 {
  padding-left: 54px !important; margin: 0 !important;
  font-size: 15px !important; line-height: 1.3 !important; }
.l-content_aside_subscriptions_top .b-subscriptions_aside_block p {
  padding-left: 54px !important; margin-top: 2px !important;
  font-size: 13px !important; line-height: 1.35 !important; }
.l-content_aside_subscriptions_top .b-subscribe_button {
  margin-left: 54px !important; }

/* ============ ПРАВЛЕНИЕ ПОДЛЕПРЫ (/controls/) ============ */
/* Страница прав и доступа. Вся её раскладка — одна таблица: обёртка
   .b-controls_columns объявлена display: table, строка — table-row,
   а каждая колонка — table-cell шириной в четверть. Колонок в строке
   четыре («Человек с кнопкой», «Читают», «Пишут», «Забаненные»), и на
   телефоне это четыре полоски по девяносто пикселей, в которых ники
   стоят с запретом переноса.
   Разбираем в столбик: строке и обёртке возвращаем блочность, колонке —
   полную ширину.

   Модификаторы колонок перечислены поимённо и все сразу, хотя на
   странице, по которой я это писал, встретился только базовый класс.
   Причина в том, что страница у каждого своя: приложенная снята НЕ
   владельцем подлепры, и у неё показаны четыре панели из полутора
   десятков. У владельца тут же появляются оформление подсайта
   (.b-controls_columns__subsite_design, где колонки ещё и плавающие),
   три колонки вместо четырёх (__three_columns с шириной 33%), широкая
   и узкая (_wide 50%, _small 30%) и колонка с чертой слева (__frame).
   Все они — тот же табличный каркас, и без них панель владельца
   осталась бы в четверть экрана. Перечисление именами, а не отбором по
   куску класса: отбор задел бы .b-controls_columns_row, у которого свои
   правила, и однажды заденет что-нибудь ещё. */
.b-controls_columns,
.b-controls_columns__three_columns,
.b-controls_columns__subsite_design.b-controls_columns,
.b-controls_columns_row,
.b-controls_columns__subsite_design .b-controls_columns_row {
  display: block !important;
  width: auto !important; position: static !important; }
.b-controls_column,
.b-controls_columns__three_columns .b-controls_column,
.b-controls_columns__subsite_design .b-controls_column,
.b-controls_column_wide,
.b-controls_column_small {
  display: block !important;
  width: auto !important; max-width: none !important;
  float: none !important; }
/* Черта между панелями. В таблице их разделяли столбцы, в столбик они
   слились бы в сплошную простыню из заголовков и списков. Цвет и приём
   те же, что у пунктов списка подлепр.
   Последней черта не нужна: под ней подвал, а не следующая панель. */
.b-controls_column {
  padding-bottom: 10px !important; margin-bottom: 10px !important;
  border-bottom: 1px solid rgb(226, 224, 222) !important; }
.b-controls_column:last-child {
  padding-bottom: 0 !important; margin-bottom: 0 !important;
  border-bottom: 0 !important; }
/* Внутренние обёртки колонок. Отбивки у них расчитаны на соседство по
   горизонтали: 16 слева у .b-column_inner, 40 справа у .b-controls_inner,
   36 и 18 по бокам у именованных вариантов, черта слева у __frame — всё
   это разделяло колонки, стоявшие рядом. В столбик разделяет черта
   выше, а отбивки только отжимают содержимое от края экрана. */
.b-column_inner,
.b-controls_inner,
.b-controls_column__center .b-controls_inner,
.b-controls_column__right .b-controls_inner,
.b-controls_column__left .b-controls_inner,
.b-blog_controls_side_controls .b-controls_inner {
  padding-left: 0 !important; padding-right: 0 !important; }
.b-controls_column__frame .b-column_inner { border-left: 0 !important; }

/* Обёртка страницы. 90% ширины оставляли справа пустую десятину, а
   отбивка снизу в 70 — расчёт на подвал, которого на телефоне под
   страницей нет. */
.b-controls_container {
  width: auto !important; padding-bottom: 16px !important; }
/* Тело вкладки. Отбивка сверху в 43 — место под панель вкладок, которая
   у лепры стоит на нём внахлёст абсолютно; у нас она в потоке, и это
   место пустует. Ширина 96% — та же лишняя десятина справа. */
.b-tabs_content {
  width: auto !important; padding: 0 !important; }
.b-tabs_content_section { margin-top: 12px !important; }
.b-controls_section { padding-bottom: 16px !important; }
/* Строка про латышей. Минусовая отбивка сверху втягивала её в те самые
   43 пикселя под панелью вкладок. Пустоты больше нет — минус убираем,
   иначе строка наезжает на панель. */
.b-latvian_access { margin: 0 0 12px !important; }
.b-latvian_access label { vertical-align: middle !important; }

/* Заголовок панели. 18 у лепры — кегль для колонки в четверть широкого
   экрана; здесь он спорит с заголовком подлепры над страницей. */
.b-controls_subtitle {
  font-size: 16px !important; margin: 0 0 5px !important; }

/* Плашка владельца. Поля по 30 с боков — под колонку; ник кеглем 24
   рядом с заголовком в 16 читался главным на странице, хотя главное
   тут права, а не имя. */
.b-owner_box {
  padding: 10px 12px !important; margin-bottom: 12px !important;
  border-radius: ${UI_R}px !important; }
.b-owner_box_name { font-size: 19px !important; }
.b-domain_creation { margin-bottom: 8px !important; }

/* Списки граждан. Отбивка справа в 27 — место под крестик «выгнать»,
   который лепра показывает по наведению; на телефоне наведения нет.
   Перенос строк разрешаем: ники бывают длинные, а nowrap в узкой
   колонке выдавливал их за край. */
.b-blog_controls_users ul {
  margin: 0 0 8px !important; padding: 0 !important; }
.b-blog_controls_users li { white-space: normal !important; }
.b-blog_controls_users ul.b-government_list { margin-left: 12px !important; }
.b-blog_controls_users ul.b-government_list__sub { margin-left: 24px !important; }
/* Поле ввода ника в 75% ширины — доля от колонки, которой больше нет.
   Кегль 11 Safari считает мелким и приближает к нему страницу. */
.b-blog_controls_users .i-form_text_input,
.b-domain_settings_form .i-form_text_input {
  width: auto !important; max-width: 100% !important;
  box-sizing: border-box !important;
  font-size: var(--lm-form-font, ${CFG.formFont}px) !important; }
/* Отбивка полей внутри панели. 24 у лепры — расчёт на широкую колонку;
   между собой поля разводим десяткой. У последнего снимаем: расстояние
   до следующей панели задаёт черта колонки, а два источника отступа
   между одними и теми же узлами всегда кончаются двойным.
   На приложенной странице поле в колонке всегда одно, но у владельца
   их бывает несколько подряд — потому не ноль. */
.b-controls_column .b-form_field { margin-bottom: 10px !important; }
.b-controls_column .b-form_field:last-child { margin-bottom: 0 !important; }

/* «Инбокс правительству». Плавала влево с очисткой — приём для колонки;
   в столбик из-за float она вываливалась из потока, и черта панели
   проходила поверх неё. Ставим строкой: значок и подпись по центру
   друг относительно друга. */
.b-moderators_inbox {
  display: inline-flex !important; align-items: center !important;
  gap: 6px !important;
  float: none !important; clear: none !important;
  height: auto !important; padding: 6px 10px !important;
  margin: 6px 0 0 !important;
  border-radius: ${UI_R}px !important; }
.b-moderators_inbox .b-svg-icon__inbox { top: 0 !important; }
/* Пояснение под забаненными. Отбивка сверху в 24 — на телефоне это
   пустая строка между списком и текстом о нём. */
.b-form_field_description__ban { padding-top: 8px !important; }
.b-government_container .b-form_field_description {
  padding-top: 8px !important; padding-bottom: 10px !important; }
/* Колонка с формами передачи и амнистии: ширины в пикселях и долях,
   плюс плавание — то же самое и по той же причине. */
.b-form_field_domain__handover { width: auto !important; }
.b-amnesia_container .b-form_field {
  float: none !important; width: auto !important; margin-right: 0 !important; }

/* ============ СПИСОК ГРАЖДАН (/users/) ============ */
/* Пункт списка раскидан по десктопной сетке: тело на 40% ширины, карма
   абсолютно на правых десяти процентах, а между ними — блок описания,
   плавающий вправо на 50% ширины с отбивкой ещё в 10% и нижним пределом
   высоты в 100 пикселей. Описание почти всегда пустое (лепра отдаёт его
   классом __empty и подгружает по нажатию), поэтому на телефоне каждый
   гражданин занимал сто с лишним пикселей, из которых больше половины —
   пустое место. Хуже того, unfloatWide видел плавающую колонку шире 40%
   экрана и честно снимал ей обтекание — пустой блок разворачивался уже
   во всю ширину. Здесь float снят правилом, поэтому проход его пропустит:
   он выходит на первом же элементе с float: none.

   Собираем пункт в три строки: логин с кармой, имя с городом, счётчики. */
.b-users_list_users .b-list_item {
  position: relative !important;
  display: flex !important; flex-wrap: wrap !important;
  padding: 6px 16px 7px 50px !important; margin: 0 !important;
  border-bottom: 1px solid rgb(226, 224, 222) !important;
  border-radius: 0 !important; box-shadow: none !important; }
.b-users_list_users .b-list_item_logo {
  width: 40px !important; height: 40px !important;
  top: 8px !important; left: 0 !important;
  border-radius: 3px !important; z-index: 2 !important; }
/* z-index у тела намеренно auto, а не число: с числом тело заводит свой
   слой, и поднятые ссылки внутри него уже не могут перекрыть подложку
   описания. С auto слоя нет — ссылки всплывают на уровень карточки,
   а всё остальное тело оказывается под подложкой, и тап по нему
   разворачивает карточку. */
.b-users_list_users .b-list_item_body {
  order: 1 !important; flex: 1 1 100% !important;
  position: relative !important; z-index: auto !important;
  width: auto !important; min-width: 0 !important;
  padding: 0 52px 0 0 !important; }
.b-users_list_users .b-list_item_body_text { line-height: 1.3 !important; }
.b-users_list_users .b-list_item > .clear { display: none !important; }

.b-users_list_users .b-list_item h5 { margin: 0 !important; }
.b-users_list_users .b-list_item h5 a.c_user { font-size: 16px !important; }
/* Имя и город лепра ставит блоками — две строки на четыре слова. Сводим
   в одну; разделитель вешает скрипт, и только когда имя не пустое. */
.b-users_list_users .b-list_item_user_name {
  display: inline !important; font-size: 12px !important;
  margin: 0 !important; }
.b-users_list_users .b-list_item_user_residence {
  display: inline !important; font-size: 12px !important;
  margin: 0 !important; }
.b-users_list_users .lm-after_name::before {
  content: ' · ' !important; color: rgb(160, 160, 160) !important; }
.b-users_list_users .b-list_item_user_docs { margin-top: 1px !important; }
.b-users_list_users .b-list_item_user_docs a { margin-right: 9px !important; }
/* Карма — единственное число в пункте, ей место у логина, а не отдельной
   строкой внизу, куда её отправляло общее правило для списка подлепр.
   Отсчитывается от тела пункта, под неё же в теле отведено поле справа. */
.b-users_list_users .b-list_item_user_karma {
  position: absolute !important; right: 0 !important; top: 1px !important;
  width: auto !important; text-align: right !important;
  font-size: 13px !important; color: rgb(90, 90, 90) !important; }

/* Раскрытое и свёрнутое-с-текстом описание идут обычным потоком под телом. */
.b-users_list_users .b-list_item_user_description {
  order: 2 !important; flex: 1 1 100% !important;
  float: none !important; width: auto !important; margin: 0 !important;
  min-height: 0 !important; padding: 2px 0 0 !important;
  font-size: 12px !important; line-height: 1.35 !important; }
.b-users_list_users .b-list_item_user_description_info {
  padding: 4px 0 2px !important; }
.b-users_list_users .b-list_item_user_description_info > * {
  margin-bottom: 8px !important; }
/* Свёрнутое описание — это не блок, а кнопка: нажатие на него подгружает
   подробности о гражданине. Растягиваем его подложкой на весь пункт,
   а ссылки поднимаем над ним, чтобы они остались нажимаемыми. Так тап
   мимо ссылки раскрывает карточку, и лишней высоты это не стоит.
   Класс lm-open ставит скрипт, когда лепра положила внутрь содержимое:
   на случай, если она раскроет блок, не сняв с него __empty.
   Правило стоит НИЖЕ общего и весит больше — иначе браузер и проверка
   в jsdom разошлись бы: первый считает по весу, вторая по порядку. */
.b-users_list_users .b-list_item_user_description__empty:not(.lm-open),
.b-users_list_users .b-list_item_user_description.lm-collapsed {
  position: absolute !important; top: 0 !important; right: 0 !important;
  bottom: 0 !important; left: 0 !important;
  float: none !important; width: auto !important; margin: 0 !important;
  min-height: 0 !important; padding: 0 !important; z-index: 1 !important; }
/* Обратно лепра карточку не сворачивает — обработчик у неё только на
   разворот. Сворачиваем своим классом: содержимое прячем, блок снова
   становится подложкой-кнопкой на всю карточку. */
.b-users_list_users .b-list_item_user_description.lm-collapsed > * {
  display: none !important; }
.b-users_list_users .b-list_item h5 a,
.b-users_list_users .b-list_item_user_name,
.b-users_list_users .b-list_item_user_docs a {
  position: relative !important; z-index: 2 !important; }
/* Указатель раскрытия у лепры — белый треугольник посреди пустого блока:
   на белом фоне его не видно, он проявляется наведением, которого на
   телефоне нет. Перекрашиваем и уводим к правому краю. */
.b-users_list_users .b-list_item .b-list_item_user_description__empty::after,
.b-users_list_users .b-list_item .b-list_item_user_description__folded::after {
  top: 50% !important; left: auto !important; right: 3px !important;
  margin: -3px 0 0 !important;
  border-width: 6px 5px 0 !important;
  border-color: rgb(178, 178, 178) transparent transparent !important; }
.b-users_list_users .b-list_item_user_description.lm-open:not(.lm-collapsed)::after {
  transform: rotate(180deg) !important; }

/* Шапка раздела: заголовок в 30 пунктов, два блока настроек, плавающих
   влево с отбивкой в 40, поле поиска фиксированной ширины в 300 и общий
   отступ слева в 12 пикселей — он не совпадал с краем пунктов списка,
   у которых своих полей нет. */
.b-users_list_caption {
  font-size: 20px !important; padding: 0 !important;
  margin: 6px 0 10px !important; }
.b-users_list_section {
  float: none !important; margin: 0 !important; }
.b-users_list_search { padding-left: 0 !important; margin-bottom: 8px !important; }
.b-users_list_search form {
  display: flex !important; align-items: center !important; }
/* 16 пунктов — нижний предел, при котором Safari на iOS не наезжает
   увеличением при касании поля. */
.b-users_list_search .i-form_text_input {
  width: auto !important; flex: 1 1 auto !important; min-width: 0 !important;
  font-size: 16px !important; }
/* Три строки настроек — «искать среди заметок» с двумя полями, «Был» с
   тремя чекбоксами и сортировка — сводятся каждая в одну линию. Ширину
   заранее не посчитать: она зависит от масштаба страницы, который скрипту
   не виден, и от выбранных пунктов в полях. Поэтому раскладку задаём
   флексом, а подгонку кегля делает fitUsersRows по факту замера.
   flex-wrap оставлен намеренно: это последняя ступень, до неё доходит
   только когда кегль упёрся в пол. Подрезанный текст выглядит поломкой
   всегда, перенос — один раз. */
.b-users_list_filters,
.b-users_list_filters + .b-users_list_flags,
.b-users_list_sorting {
  display: flex !important; flex-wrap: wrap !important;
  align-items: center !important;
  padding-left: 0 !important; font-size: 13px !important; }
.b-users_list_filters {
  gap: 6px 9px !important; padding-bottom: 8px !important; }
.b-users_list_filters + .b-users_list_flags {
  gap: 6px 8px !important; margin-bottom: 8px !important; }
.b-users_list_sorting {
  gap: 4px 6px !important; margin-bottom: 4px !important; }
/* Чекбокс «искать среди заметок» лежит у лепры в отдельном блоке над
   полями. Скрипт переносит блок внутрь строки, а сам блок убираем из
   раскладки: он нужен только чтобы держать узлы вместе и не терять
   обработчик лепры, а место в строке должны занимать его дети. */
.b-users_list_filters > .b-users_list_flags { display: contents !important; }
/* «мои заметки» лепра открывает галочкой «искать среди заметок» — пункт
   появляется уже после подгонки строки, поэтому ему сразу отводим свою
   линию, а не отбираем ширину у соседей. */
.b-users_list_filters .b-users_list_flags > span:not(.lm-chk) {
  flex: 1 1 100% !important; }
/* Квадратик с подписью — один пункт строки: порознь подпись отрывалась
   от чекбокса на переносе. */
.lm-chk {
  display: inline-flex !important; align-items: center !important;
  gap: 5px !important; white-space: nowrap !important;
  flex: 0 0 auto !important; }
.lm-chk input, .lm-chk label {
  margin: 0 !important; font-size: inherit !important; }
.lm-flag_prefix, .lm-sort_prefix {
  flex: 0 0 auto !important; white-space: nowrap !important; }
/* Форменным элементам браузер задаёт нижний предел ширины по содержимому —
   снимаем, иначе строка не сожмётся вовсе. Ширину полю подбирает
   fitSelect по выбранному пункту. */
.b-users_list_filters select {
  flex: 0 1 auto !important; min-width: 0 !important; max-width: 100% !important;
  margin: 0 !important; font-size: inherit !important; }
.b-users_list_sorting ul {
  display: flex !important; flex-wrap: wrap !important;
  align-items: center !important; gap: 4px !important;
  margin: 0 !important; padding: 0 !important; }
.b-users_list_sorting li {
  padding: 2px 5px !important; margin: 0 !important;
  font-size: inherit !important; white-space: nowrap !important; }
.b-users_list_users { margin-bottom: 8px !important; }
.b-load_more_posts_button__users {
  margin: 12px 0 16px !important; padding: 8px 0 10px 14px !important; }

/* ============ УВЕДОМЛЕНИЯ («Пынь») ============ */
/* Лента отсчитывалась от левой колонки (left:245px), резервировала 340px
   под боковую панель и требовала минимум 446px ширины. */
.b-notification-feed {
  left: 0 !important; right: 0 !important;
  width: auto !important; max-width: 100vw !important;
  box-sizing: border-box !important; }
.b-notification-feed_layout_popup {
  min-width: 0 !important; width: auto !important;
  max-width: 100vw !important; box-sizing: border-box !important; }
.b-notification-feed_inner,
.b-notification-feed_layout_popup .b-notification-feed_inner {
  margin: 0 !important; max-width: 100% !important; }
.b-notification-feed_content { margin-left: 0 !important; }
.b-notification-feed_sidebar, .b-notification-feed_fixed {
  position: static !important; width: auto !important;
  padding-left: 0 !important; }
.b-notification-feed__footer { width: auto !important; }
.b-notification-feed_layout_popup .b-notification-item {
  padding-left: 12px !important; padding-right: 10px !important; }
.b-notification { margin: 2px 8px !important; }

/* Страница уведомлений. Лента лежит последним потомком body и прибита
   абсолютно: top ей считает скрипт лепры от высоты своей шапки (вышло
   112 пикселей), а у нас шапка другая и выше — лента наезжала на неё.
   Ставим в поток; сам узел переносится в главную колонку скриптом,
   иначе статичный блок встал бы ниже подвала. */
.b-notification-feed_layout_page {
  position: static !important; top: auto !important;
  min-height: 0 !important; }
.b-notification-item {
  padding: 9px 10px 9px 38px !important; line-height: 18px !important; }
.b-notification-item_icon { margin-left: -30px !important; }
/* Внутри пункта было четыре отбивки по 5–10 пикселей: под шапкой со
   значком, под строкой «кто ответил», над подписью и под ней. На экране
   в 393 это давало полтора пункта на высоту одного. */
.b-notification-item_header {
  margin-left: 0 !important; margin-bottom: 0 !important; }
.b-notification-item_message { margin-bottom: 4px !important; }
.b-notification-item_footer {
  margin-left: 0 !important;
  margin-top: 4px !important; padding-bottom: 0 !important; }
.b-notification-item_mention_comment_text { word-break: break-word !important; }
/* Три раздела шли строкой по 30 пикселей высотой, с отбивками под
   десктопную колонку в 320. Ставим столбиком и обнуляем всю цепочку
   обёрток: у сайдбара своя отбивка (.b-right_sidebar margin-top),
   у секции своя, у списка своя — по отдельности каждая мелочь, вместе
   полпальца пустоты. */
.b-notification-feed_layout_page .b-notification-feed_sidebar,
.b-notification-feed_layout_page .b-notification-feed_fixed,
.b-notification-feed_layout_page .b-notification-settings {
  margin: 0 !important; padding: 0 !important; }
.b-notification-feed_layout_page .b-notification-settings_list {
  display: block !important; margin: 0 !important; padding: 0 !important; }
.b-notification-feed_layout_page .b-notification-settings_separator {
  display: none !important; }
.b-notification-feed_layout_page .b-notification-settings_category {
  line-height: 22px !important; height: auto !important;
  font-size: 13px !important; margin: 0 !important; padding: 0 !important; }
/* Ячейка внутри пункта была шириной во всю строку и высотой ровно в 40 —
   от этого счётчик уходил под название отдельной строкой. */
.b-notification-feed_layout_page .b-notification-settings_category_content {
  width: auto !important; height: auto !important;
  white-space: nowrap !important; }
.b-notification-feed_layout_page .b-notification-settings_category_icon {
  height: 20px !important; width: 20px !important;
  margin: 1px 4px 0 0 !important; }
.b-notification-feed_layout_page .b-notification-settings_category_icon svg {
  height: 20px !important; width: 20px !important; }
/* Отбивка в 36 пикселей и невидимая (opacity: 0, но display: block)
   ссылка «Показать отписки» давали пустую полосу почти в палец высотой. */
.b-notification-feed_layout_page .b-notification-unsubscriptions {
  display: flex !important; flex-wrap: wrap !important;
  align-items: center !important; gap: 2px 14px !important;
  font-size: 13px !important; line-height: 22px !important;
  margin: 0 !important;
  padding: 0 0 6px !important;
  border-bottom: 1px solid #ebebeb !important; }
.b-notification-unsubscriptions_link.hidden { display: none !important; }
.b-notification-mark_link, .b-notification-unsubscriptions_link {
  margin-bottom: 0 !important; }

/* ============ ПЫНЬ: своё окошко ============ */
/* У лепры по нажатию на колокольчик всплывает окно со списком, а внизу
   у него ссылка на страницу целиком. На телефоне оно не открывается, да
   и рассчитано на мышь: минимум 446 пикселей ширины, а прокрутка ленты
   включается только под наведением (:hover). Поэтому окно своё, а
   содержимое — леприно, загруженное со страницы уведомлений. */
html.lm-pyn_on .b-notification-feed_layout_popup { display: none !important; }
#lm-pyn {
  position: fixed !important; top: 0 !important; left: 0 !important;
  right: 0 !important; bottom: 0 !important;
  z-index: 2147483000 !important;
  display: flex !important; align-items: flex-start !important; }
/* Своё окно лепра ничем не затемняет — оно у неё маленькое и висит под
   колокольчиком. У нас во всю ширину экрана, и без подложки по краям
   торчала бы страница. Держим её еле заметной; CFG.pynShade: 0 уберёт
   совсем, тогда тап мимо окна всё равно закрывает. */
.lm-pyn_shade {
  position: absolute !important; top: 0 !important; left: 0 !important;
  right: 0 !important; bottom: 0 !important;
  background: rgba(0, 0, 0, ${CFG.pynShade / 100}) !important; }
/* Рамка и подвал — как у лепровского окна уведомлений:
   .b-notification-feed_layout_popup — рамка 1px rgb(215,215,215) без
   скруглений и без строки заголовка; .b-notification-feed__footer —
   полоса 42px цветом rgb(224,224,226), надписи 12px rgb(37,37,37)
   с отступом 20 по краям. */
.lm-pyn_box {
  position: relative !important; z-index: 1 !important;
  margin: 6px !important; width: 100% !important; box-sizing: border-box !important;
  max-height: ${CFG.pynHeight}vh !important;
  display: flex !important; flex-direction: column !important;
  overflow: hidden !important;
  background: #fff !important;
  border: 1px solid #d7d7d7 !important;
  box-shadow: 0 2px 10px rgba(0, 0, 0, .25) !important; }
.lm-pyn_body {
  flex: 1 1 auto !important; overflow-y: auto !important;
  -webkit-overflow-scrolling: touch !important;
  background: #fff !important; }
.lm-pyn_note {
  padding: 20px 12px !important; text-align: center !important;
  color: #777 !important; font: 13px/1.4 Arial, sans-serif !important; }
.lm-pyn_bar {
  flex: 0 0 auto !important; display: flex !important;
  align-items: center !important; justify-content: space-between !important;
  gap: 10px !important;
  height: 42px !important; padding: 0 14px !important;
  box-sizing: border-box !important;
  background: #e0e0e2 !important; }
/* Верхняя отделена снизу, нижняя сверху — иначе на белой ленте панель
   и первое уведомление сливаются в одну полосу. */
.lm-pyn_bar__head { border-bottom: 1px solid #d7d7d7 !important; }
.lm-pyn_bar__foot { border-top: 1px solid #d7d7d7 !important; }
/* Кнопка закрытия — на месте лепровского «Отметить всё как прочитанное»
   (та без её скрипта не работает, а закрывать окно на телефоне чем-то
   надо: строки заголовка у лепры нет). */
.lm-pyn_bar a, .lm-pyn_close {
  flex: 0 0 auto !important;
  font: 12px/42px Arial, sans-serif !important; color: #252525 !important;
  text-decoration: none !important; white-space: nowrap !important;
  background: none !important; border: 0 !important; padding: 0 !important;
  cursor: pointer !important;
  -webkit-tap-highlight-color: rgba(85, 110, 140, .2) !important; }
#lm-pyn .b-notification-item { font-size: 13px !important; }

/* Голосовалка в окне пыни. Стоит в желобке слева, под значком типа
   уведомления, — тем же приёмом, что и сам значок у лепры: плавает
   влево с отрицательным полем в 36, то есть выходит в отступ, который
   уведомление и так оставляет. Ничего чужого при этом не двигается.
   clear: left обязателен — иначе голосовалка встала бы РЯДОМ со
   значком, а не под ним: оба плавающие.
   Кнопки 26: желобок шириной 36, крупнее не влезает, а меньше делать
   нельзя — это отправка голоса, попасть плюсом вместо минуса нельзя.
   Цвет ответа: зелёная рамка — ушло, красная — не вышло. Держим
   состояние на самой голосовалке, а не на кнопке: у пары общий исход. */
.lm-pyn_vote {
  float: left !important; clear: left !important;
  margin: 4px 0 0 -36px !important;
  display: flex !important; flex-direction: column !important;
  gap: 3px !important; }
/* Размер тот же, что у голосовалок на странице (VOTE_GEOM.tap). Здесь
   он записан числом, а не подставлен переменной: правила окна пыни
   собраны своим блоком и от голосовалок лепры не зависят — но если тот
   размер поменяется, менять надо и здесь. */
.lm-pyn_vote_btn {
  width: 28px !important; height: 28px !important;
  padding: 0 !important; margin: 0 !important;
  -webkit-appearance: none !important; appearance: none !important;
  background: #fff !important;
  border: 1px solid rgb(200,200,200) !important;
  border-radius: ${UI_R}px !important;
  font: 15px/1 Verdana, Arial, sans-serif !important;
  color: rgb(90,90,90) !important;
  -webkit-tap-highlight-color: transparent !important;
  touch-action: manipulation !important;
  cursor: pointer !important; }
/* «Ответить» и форма под ним. Кнопка ставится в подвал уведомления,
   рядом с прочими его значками, — там же, где она стоит у лепры на
   странице уведомлений (её собственную мы убираем: её обработчик живёт
   на той странице, а не в нашем окне).
   Поле ввода кеглем 16: ниже этого Safari на iOS наезжает увеличением
   при касании, и окно уезжает вбок. Это уже разбиралось на поле пароля
   в магазине. */
/* «Ответить» остаётся в строке подвала, но с заметным отступом от
   значка-ссылки на комментарий: рядом с ним оно собирало промахи — два
   разных действия в полутора сантиметрах друг от друга, и оба ведут в
   разные места.
   Пробовал ставить по середине отдельной строкой — вышло размашисто:
   лишняя строка на каждом из двадцати уведомлений съедала экран, а
   выигрыш был только в промахах. Отступа в двадцать пикселей хватает,
   и высота остаётся прежней. */
.lm-pyn_answer {
  -webkit-appearance: none !important; appearance: none !important;
  display: inline !important;
  background: none !important; border: 0 !important;
  padding: 0 !important; margin: 0 0 0 20px !important;
  font-family: Verdana, Arial, sans-serif !important;
  font-size: 12px !important;
  color: rgb(85,110,140) !important;
  text-decoration: underline !important;
  -webkit-text-decoration-style: dotted !important;
  text-decoration-style: dotted !important;
  -webkit-tap-highlight-color: transparent !important;
  touch-action: manipulation !important;
  cursor: pointer !important; }
.lm-pyn_answer:active { color: rgb(40,60,90) !important; }

/* Форма — та же, что у лепры в посте под «ответить». Числа сняты с её
   собственных правил (.b-comments_add_textarea .i-form_text_input):
   кремовое поле rgb(243,240,223), светлая рамка rgb(235,235,235),
   скругление 5, отбивка 3/3/3/8. Никакой своей рамки вокруг формы у
   неё нет — поле лежит прямо на странице, — поэтому и у нас её нет.
   Первая попытка была не той: я взял .i-form_textarea (это форма поста,
   а не комментария) и добавил серую коробку с кнопками в прописных
   буквах. Выглядело как чужая вставка, и правильно.
   Высоту берём меньше её двухсот: двести — это на пол-экрана, а в
   окне пыни форма должна оставить на виду и само уведомление.
   Кегль вынужденно шестнадцать вместо её четырнадцати: ниже этого
   Safari на iOS наезжает увеличением при касании и уводит окно вбок. */
.lm-pyn_form {
  margin: 6px 0 4px !important;
  padding: 0 !important;
  background: none !important; border: 0 !important; }
.lm-pyn_area {
  display: block !important; width: 100% !important;
  box-sizing: border-box !important;
  margin: 0 0 5px !important;
  padding: 3px 3px 3px 8px !important;
  height: 84px !important;
  font: 16px/1.35 verdana, sans-serif !important;
  color: #000 !important;
  background: rgb(243,240,223) !important;
  border: 1px solid rgb(235,235,235) !important;
  border-radius: 5px !important;
  -webkit-appearance: none !important; appearance: none !important;
  outline: none !important;
  resize: vertical !important; }
.lm-pyn_area:focus { box-shadow: none !important; color: #000 !important; }
.lm-pyn_form_row {
  display: flex !important; align-items: center !important;
  gap: 6px !important; }
.lm-pyn_form_say {
  flex: 1 1 auto !important; min-width: 0 !important;
  font-family: verdana, sans-serif !important;
  font-size: 11px !important;
  color: rgb(110,110,110) !important; }
/* Кнопки — текстовыми ссылками, как у неё в строке над полем
   (.b-textarea_editor_button: серые rgb(119,119,119), кегль мелкий).
   Прямоугольных кнопок в её форме ответа нет вовсе: отправку она
   делает картинкой YARRR, а всё прочее — ссылками. Картинку взять
   неоткуда (она своя у каждой подлепры), поэтому отправка тоже
   ссылкой, но полужирной — чтобы главное действие читалось первым.
   Отбивка сверху и снизу оставлена: ссылка кеглем 12 без неё
   собирает промахи. */
.lm-pyn_form_btn {
  -webkit-appearance: none !important; appearance: none !important;
  flex: 0 0 auto !important;
  padding: 4px 2px !important; margin: 0 0 0 12px !important;
  /* Свойства порознь, а не сокращением font: оно сбрасывает начертание
     и кегль разом, и стоящий следом font-weight в Safari теряется. Та
     же грабля, что была с font: inherit. */
  font-family: verdana, sans-serif !important;
  font-size: 12px !important;
  font-weight: bold !important;
  background: none !important; border: 0 !important;
  color: rgb(85,110,140) !important;
  text-decoration: underline !important;
  -webkit-text-decoration-style: dotted !important;
  text-decoration-style: dotted !important;
  -webkit-tap-highlight-color: transparent !important;
  touch-action: manipulation !important;
  cursor: pointer !important; }
.lm-pyn_form_btn:active { color: rgb(40,60,90) !important; }
.lm-pyn_form_btn[disabled] { opacity: .5 !important; }
.lm-pyn_form_btn__off {
  font-weight: normal !important;
  color: rgb(119,119,119) !important; }

.lm-pyn_vote_num {
  text-align: center !important;
  font: 11px/1 Verdana, Arial, sans-serif !important;
  color: rgb(110,110,110) !important;
  min-height: 11px !important; }
.lm-pyn_vote_btn:active { background: rgb(225,225,225) !important; }
.lm-pyn_vote_btn.lm-on {
  background: rgb(220,218,218) !important;
  color: rgb(20,20,20) !important; }
.lm-pyn_vote.lm-wait .lm-pyn_vote_btn { opacity: .5 !important; }
.lm-pyn_vote.lm-ok .lm-pyn_vote_btn.lm-on {
  border-color: rgb(110,170,110) !important; }
.lm-pyn_vote.lm-bad .lm-pyn_vote_btn.lm-on {
  border-color: rgb(200,110,110) !important; }

/* Плашка о новых пынях. Внизу, а не вверху: сверху шапка и навигационная
   штука, а внизу палец ближе. Оформление — как у окна пыни, чтобы это
   читалось одним семейством, а не двумя разными затеями. */
#lm-pyntoast {
  position: fixed !important;
  left: 6px !important; right: 6px !important;
  bottom: calc(${CFG.pynToastUp}px + env(safe-area-inset-bottom, 0px)) !important;
  /* Не во всю ширину: строка в 393 пикселя выглядит полосой поперёк
     экрана, а не всплывшим сообщением. Поля слева и справа оставлены,
     чтобы на узком экране плашка всё же не упиралась в края. */
  max-width: ${CFG.pynToastWide}px !important;
  margin: 0 auto !important;
  z-index: 2147482000 !important;
  box-sizing: border-box !important;
  /* Цвет — тот же, что у подвала окна пыни, чтобы всё это читалось
     одним семейством: rgb(224,224,226) с рамкой rgb(215,215,215). */
  background: #e0e0e2 !important;
  border: 1px solid #d7d7d7 !important;
  box-shadow: 0 2px 10px rgba(0, 0, 0, .25) !important; }
/* Плашка сверху. Не «то же самое, только top вместо bottom»: снизу
   мешает панель Safari (её обходит pynToastUp и безопасная зона),
   сверху — своя адресная строка и наша шапка. Отступ здесь считается от
   безопасной зоны сверху плюс та же величина: под адресной строкой
   плашка должна начинаться там же, где начинается содержимое страницы.
   Тень разворачиваем вниз — она должна падать от плашки на страницу, а
   не вверх в пустоту. */
#lm-pyntoast.lm-top {
  top: calc(${CFG.pynToastUp}px + env(safe-area-inset-top, 0px)) !important;
  bottom: auto !important;
  box-shadow: 0 2px 10px rgba(0, 0, 0, .25) !important; }
/* Текст переносится, но не больше трёх строк: дальше плашка начинает
   спорить с окном, ради которого её и жмут. */
.lm-pyntoast_text {
  display: -webkit-box !important;
  -webkit-line-clamp: 3 !important;
  -webkit-box-orient: vertical !important;
  overflow: hidden !important;
  width: 100% !important; box-sizing: border-box !important;
  background: none !important; border: 0 !important;
  margin: 0 !important; padding: 9px 32px 9px 12px !important;
  text-align: left !important;
  font: 13px/17px Arial, sans-serif !important;
  color: rgb(37, 37, 37) !important;
  cursor: pointer !important;
  -webkit-tap-highlight-color: rgba(85, 110, 140, .2) !important; }
/* Крестик уведён в угол: будь он рядом в строке, текст пришлось бы
   держать в одну строку — а он теперь в три. */
.lm-pyntoast_close {
  position: absolute !important; top: 0 !important; right: 0 !important;
  background: none !important; border: 0 !important;
  color: #8a8a8a !important;
  font: 15px/1 Arial, sans-serif !important;
  padding: 8px 10px !important; }
#lm-pyn .b-notification-item_footer { padding-bottom: 0 !important; }

/* Ссылки внутри ленты лепра красит правилом .b-notification-feed a —
   а этого предка у нас нет: в окно переносится только внутренний узел
   ленты (#js-notification-feed-main). Из-за этого все ссылки в окне
   падали на общесайтовый тёмно-оливковый a { color: rgb(51,51,0) }.
   Повторяем её цвет. */
#lm-pyn a { color: rgb(85, 110, 140) !important; }
/* Название поста лепра выводит без подчёркивания (.b-notification-item__post
   { text-decoration: none }), и рядом с обычным текстом того же кегля оно
   ссылкой не читается — в отличие от логина и «N комментариев» в той же
   строке, которые подчёркнуты. Цвет у него был правильный с самого
   начала; не хватало именно подчёркивания. */
.b-notification-item__post { text-decoration: underline !important; }

/* Раскрытие исходного комментария по шеврону. Сам комментарий лежит в
   разметке всегда; лепра держит его свёрнутым инлайновой высотой и
   раскрывает своим скриптом. На странице уведомлений её скрипт на месте
   и делает это сам — поэтому переключение классом только для окна, где
   его нет: правило height: auto на странице развернуло бы разом все. */
#lm-pyn .b-notification-item_parent_comment {
  display: none !important; height: auto !important; }
#lm-pyn .b-notification-item_parent_comment.lm-open {
  display: block !important; }
.lm-pyn_roll { cursor: pointer !important; }
/* Поворот, а не подмена значка: у лепры для этого шеврона уже объявлены
   и inline-block, и transform-origin: 50% 50%, и переход — квадратный
   значок крутится на месте и никуда не прыгает. */
#lm-pyn .lm-pyn_roll.lm-open .b-roll_parent_comment {
  transform: rotate(180deg) !important; }

/* Вид самого исходного комментария — одинаковый в окне и на странице:
   приходит он с разметкой треда, где кегль крупнее окружающего.
   Шрифт — Verdana, как у текста ответа под ним (лепра задаёт его
   в .b-notification-item_mention_comment_text). Это существеннее, чем
   кажется: Verdana при равном кегле рисуется заметно крупнее Arial,
   и цитата в 13px Arial выглядела мельче ответа в 13px Verdana,
   хотя числа совпадали. */
/* Фон светлее непрочитанного уведомления (у лепры rgb(244,244,242)) не
   годится: цитата внутри такого пункта слилась бы с ним. Берём чуть
   темнее и нейтральнее — заметно и на белом прочитанном, и на тёплом
   непрочитанном. Поля по кругу, иначе заливка липнет к тексту. */
/* Серых здесь два, и они не должны спорить. Непрочитанное уведомление
   лепра красит в rgb(244,244,242) — тёплый и очень бледный. Цитата
   заметно темнее и чуть холоднее: восемнадцать ступеней разницы плюс
   другой оттенок, чтобы на непрочитанном пункте она читалась отдельным
   блоком, а не пятном той же природы. */
.b-notification-item_parent_comment .comment {
  margin: 6px 0 2px !important; padding: 6px 10px !important;
  background: rgb(226, 226, 230) !important;
  border-left: 2px solid #b9b9c0 !important; }
.b-notification-item_parent_comment .c_body {
  font-family: verdana, sans-serif !important;
  font-size: ${CFG.pynQuoteFont}px !important;
  line-height: 1.45 !important; }
.b-notification-item_parent_comment .c_footer,
.b-notification-item_parent_comment .ddi {
  font-size: 12px !important; line-height: 18px !important; }
.b-notification-item_parent_comment .c_body img,
.b-notification-item_parent_comment .c_body video,
.b-notification-item_parent_comment .c_body iframe {
  max-width: 100% !important; height: auto !important; }
/* Голосование, «ответить», «поделиться» и сворачивание ветки лепра
   внутри исходного комментария прячет — работать им там нечем. Но её
   правило без !important, а наши общие правила для комментариев (вернуть
   голосовалку в поток, кнопки под палец) с !important, и они это скрытие
   перебивали: появлялись кнопки, которые ничего не делают. */
.b-notification-item_parent_comment .vote,
.b-notification-item_parent_comment .c_answer,
.b-notification-item_parent_comment .c_show_user,
.b-notification-item_parent_comment .b-button,
.b-notification-item_parent_comment .b-comment_thread_collapse {
  display: none !important; }

/* Значок-страничка в конце подписи уведомления — ссылка на сам ответ.
   Значок берём леприн, тот же .c_icon с post-icon.gif, что стоит перед
   «Написал» в комментариях: своей картинки заводить незачем, а вид
   получается ровно как на странице поста. По умолчанию лепра его
   прячет (display: none), в комментариях его открывает наше общее
   правило для ссылок подписи — здесь открываем отдельно. */
.b-notification-item_footer .lm-note_go {
  display: inline-block !important;
  width: 20px !important; height: 18px !important;
  margin: 0 0 0 2px !important;
  vertical-align: middle !important; }

/* ============ СКРЫТОЕ ============ */
.b-navthing_holder, .b-chat, .b-chat_open,
.b-footer_left_col, .b-footer_futurico, .b-gertruda,
.b-content_top_shadow, .b-tags, .b-cloud,
.b-subs_ads_on_index, .b-subs_ads_on_index__wrapper,
.b-subs_ads_overflow_holder, .b-subs_ads { display: none !important; }
/* Реклама подсайтов: у неё padding-right:329px, на телефоне это давало
   пустую колбасу в 800px высотой. Чтобы вернуть в сжатом виде, удалите
   .b-subs_ads* из списка выше и раскомментируйте это:
   .b-subs_ads_overflow_holder { padding-right: 0 !important; }
   .b-subs_ads_on_index { margin-right: 0 !important; } */

/* ============ СВОИ ЭЛЕМЕНТЫ ============ */
/* Навигация по комментариям. Родная (.b-comments_navigation) после первого
   нажатия перехватывала тапы по всей странице, поэтому скрыта. */
.b-comments_navigation, #js-comments_navigation { display: none !important; }

#lm-nav {
  position: fixed !important; right: ${CFG.jumpRight}px !important;
  top: 50% !important;
  transform: translateY(-50%) !important; z-index: 30 !important;
  display: flex !important; flex-direction: column !important;
  gap: ${CFG.jumpGap}px !important;
  /* коробка тапы не ловит — иначе перекрывала бы ссылки под собой */
  pointer-events: none !important; }
#lm-nav button, #lm-theme {
  /* при долгом удержании Safari предлагал выделить символ на кнопке */
  -webkit-user-select: none !important; user-select: none !important;
  -webkit-touch-callout: none !important;
  -webkit-tap-highlight-color: transparent !important;
  touch-action: manipulation !important; }
/* Кнопка — только площадь нажатия: ни фона, ни рамки, весь вид несёт
   значок внутри. -webkit-appearance снимаем явно, иначе Safari рисует
   свою серую капсулу поверх заданного background. */
#lm-nav button {
  pointer-events: auto !important;
  width: ${CFG.jumpSize}px !important; height: ${CFG.jumpSize}px !important;
  padding: 0 !important; margin: 0 !important;
  -webkit-appearance: none !important; appearance: none !important;
  background: none !important; border: 0 !important;
  border-radius: 0 !important; box-shadow: none !important;
  display: block !important; cursor: pointer !important;
  opacity: 1 !important; transition: opacity .3s !important; }
#lm-nav button svg {
  display: block !important;
  width: 100% !important; height: 100% !important; }
${CFG.jumpHalo ? `#lm-nav button svg {
  filter: drop-shadow(0 0 1px rgba(255,255,255,.95))
          drop-shadow(0 0 2px rgba(255,255,255,.8)) !important; }` : ''}
/* Нижняя стрелка — та же картинка, повёрнутая, как у лепры. Поворот
   здесь безопасен: значок квадратный и стоит в квадратной кнопке,
   прыгать при вращении нечему. */
#lm-nav .lm-nav_down svg { transform: rotate(180deg) !important; }
/* Неактивная кнопка — прозрачность лепры (0.3), не серый цвет:
   перекрашивать пришлось бы каждую фигуру отдельно. */
#lm-nav button.lm-off { opacity: .3 !important; cursor: default !important; }
#lm-nav button:active:not(.lm-off) { opacity: .55 !important; }
/* одиночная кнопка «наверх»: появляется, когда отлистан хотя бы экран */
/* Прозрачность — не невидимость. Погашенная до нуля кнопка продолжает
   ловить нажатия, и сорок на сорок у правого края по центру экрана
   съедали тап по всему, что под них попадало. Поймалось на третьем
   значке переключателя типа ленты: при стопроцентном масштабе третья
   колонка навигационной штуки доходит до правого края, и значок
   оказывался ровно под погашенной кнопкой; при 85% раскладка другая, и
   всё работало. Отсюда и «работает на одном масштабе, не работает на
   другом» — искать надо было не в значке.
   Гасим нажимаемость вместе с прозрачностью и возвращаем вместе с ней.
   Правило видимого состояния тяжелее (три условия против двух) И стоит
   ниже по файлу: спор решается одинаково и по весу, и по порядку. */
#lm-nav.lm-nav__top { opacity: 0 !important; transition: opacity .2s !important; }
#lm-nav.lm-nav__top button { pointer-events: none !important; }
#lm-nav.lm-nav__top.lm-visible { opacity: 1 !important; }
#lm-nav.lm-nav__top.lm-visible button { pointer-events: auto !important; }

/* Увеличение картинки прямо в посте. Раньше здесь был оверлей поверх
   страницы, но он блокировал прокрутку через overflow:hidden на body —
   на iOS это теряет позицию прокрутки и после закрытия выбрасывает
   наверх, а кнопка закрытия попадала в зону логотипа. */
img.lm-zoomed {
  width: 100% !important; max-width: 100% !important;
  height: auto !important; cursor: zoom-out !important; }

/* ---- Навигационная штука ----
   Серую черту под шапкой заменяет строка-переключатель: свёрнутая, она и
   есть разделитель, развёрнутая — отдаёт то, что на десктопе лежит в левой
   колонке главной. Устройство то же, что у простого пенсне подлепр, но
   подпись стоит по центру: этот блок не принадлежит ленте под ним, он
   разделяет шапку и ленту.
   Черту у шапки снимаем классом на html, а не безусловным правилом: если
   блок построить не вышло, разделитель останется прежним. */
html.lm-navthing_on .l-header {
  margin-bottom: 0 !important; border-bottom: 0 !important; }

#lm-navthing { margin: 0 0 10px !important; }
/* На профиле эта отбивка и есть та серая полоса под строкой: сквозь неё
   виден фон .l-i-wrapper, а он у лепры на профиле rgb(204,204,204). К
   картинке владельца полоса отношения не имеет — потому и оставалась
   серой на профилях со своим фоном. Убираем: под строкой начинается
   обрамление профиля, а на профилях без картинки — сразу карточка. */
body.l-profile #lm-navthing { margin-bottom: 0 !important; }
.lm-navthing_row {
  display: flex !important; align-items: center !important; gap: 6px !important;
  width: 100% !important; box-sizing: border-box !important;
  margin: 0 !important; padding: ${NAV_PAD}px 8px !important;
  /* Тот же серый, каким показано нажатое состояние кнопок и выбранный
     значок переключателя ленты. Раньше здесь был свой оттенок на два
     тона светлее, и в одном блоке оказывалось три разных серых. */
  background: rgb(220, 218, 218) !important;
  border: 0 !important; border-radius: 0 !important;
  -webkit-appearance: none !important; appearance: none !important;
  /* Шорткат font: inherit сбрасывает кегль последним значением из
     наследования — свойства перечисляем по одному, как у пенсне. */
  font-family: inherit !important; font-weight: normal !important;
  font-size: 13px !important; line-height: 1.3 !important;
  color: rgb(70, 70, 70) !important; text-align: center !important;
  cursor: pointer !important;
  -webkit-user-select: none !important; user-select: none !important;
  -webkit-tap-highlight-color: transparent !important; }
/* Пиктограмма и шеврон одной ширины: иначе подпись между ними встаёт
   сдвинутой на разницу их размеров, а не по середине строки.
   Значок — герб «Блогов Империи», тот самый, что внутри стоял слева от
   заголовка. Гнездо работает окошком: картинка внутри увеличена так,
   чтобы её рисунок (39 из 65 пикселей ширины файла) занял гнездо
   целиком, а прозрачные поля ушли под обрезку. Проценты считаются от
   стороны гнезда, поэтому размер меняется одной настройкой navIcon.
   max-width: none обязателен — общее правило для картинок в теле
   страницы иначе прижмёт герб к ста процентам, и увеличение пропадёт.
   Если герба нет ни на странице, ни в памяти, гнездо остаётся пустым:
   место под него нужно всё равно, иначе подпись съедет вправо. */
.lm-navthing_icon, .lm-navthing_arrow {
  flex: 0 0 ${CFG.navIcon}px !important; }
.lm-navthing_icon {
  display: block !important; position: relative !important;
  width: ${CFG.navIcon}px !important; height: ${CFG.navIcon}px !important;
  overflow: hidden !important; line-height: 0 !important; }
.lm-navthing_icon img {
  display: block !important; position: absolute !important;
  left: ${CREST_CSS.x}% !important; top: ${CREST_CSS.y}% !important;
  width: ${CREST_CSS.w}% !important; height: auto !important;
  max-width: none !important; max-height: none !important;
  margin: 0 !important; }
.lm-navthing_arrow {
  font-size: 10px !important; text-align: right !important;
  color: rgb(120, 120, 120) !important; }
.lm-navthing_label {
  flex: 1 1 auto !important; min-width: 0 !important;
  text-align: center !important; }
/* Развёрнутое состояние — сменой знака, а не поворотом. Поворот идёт
   вокруг середины коробки шеврона, а знак прижат к её правому краю: на
   двадцати пикселях ширины он перепрыгивал к левому, и шеврон при каждом
   развороте уезжал на полтора сантиметра. Знак пишем содержимым
   псевдоэлемента, поэтому в разметке span пустой — как у пенсне. */
.lm-navthing_arrow::before { content: '▾' !important; }
#lm-navthing.lm-navthing__open .lm-navthing_arrow::before {
  content: '▴' !important; }

/* Тело панели фона своего не имеет: пусть просвечивает фон страницы.
   Не «белый», а прозрачный — на профиле и на подсайтах со своим
   оформлением фон под шапкой не белый, и любое постоянное число
   оказалось бы там заплаткой.
   Серая черта снизу — та самая, что раньше шла под шапкой: у неё и цвет
   взят оттуда же. Стоит на теле, а не на всём блоке, поэтому в свёрнутом
   виде её нет — там разделителем работает сама серая плашка. */
.lm-navthing_body {
  /* Не display: none, а нулевая высота с обрезкой. Разница в том, что
     display переключается мгновенно: при сворачивании на ходу страница
     разом теряла полэкрана высоты и дёргалась под пальцем. Высота
     анимируется, и уезжает панель плавно.

     Потолок высоты в 1200 — цифра заведомо большая, а не настоящая:
     настоящую до раскрытия не измерить, а переход требует конкретного
     числа (от auto браузер анимировать не умеет). Плата за запас —
     первая треть перехода идёт вхолостую, поэтому кривая ease и
     недлинная выдержка: на глаз это незаметно. Если панель когда-нибудь
     перерастёт 1200 пикселей, у неё обрежется низ, и чинить надо будет
     здесь.

     visibility гасим отдельно от высоты: у обрезанного по нулю блока
     содержимое всё ещё доступно для нажатий и для чтения с экрана. */
  display: block !important;
  overflow: hidden !important;
  max-height: 0 !important; visibility: hidden !important;
  padding: 0 8px !important;
  background: transparent !important;
  /* Черты снизу больше нет. Она осталась от времён, когда лента шла
     сплошным полотном и панель отделяла верх страницы от тела. Теперь
     тело — карточки со своими рамками, и линия перед первой из них
     читается лишней. */
  border: 0 !important;
  font-size: 13px !important; line-height: 1.5 !important;
  /* Кривая easeOutCubic: быстрое начало, мягкое торможение. Обычный
     ease тормозит и в начале, отчего движение читается вязким, а
     linear останавливается как отрезанный. */
  transition: max-height ${NAV_FOLD}ms cubic-bezier(.33,1,.68,1),
              padding ${NAV_FOLD}ms cubic-bezier(.33,1,.68,1),
              visibility 0s linear ${NAV_FOLD}ms !important; }
#lm-navthing.lm-navthing__open .lm-navthing_body {
  /* Потолок здесь запасной: настоящую высоту навешивает инлайном
     navFold, померив содержимое. Это значение работает, только если
     класс поставили мимо него — например при сборке страницы. */
  max-height: 1200px !important; visibility: visible !important;
  padding: 10px 8px !important;
  transition: max-height ${NAV_FOLD}ms cubic-bezier(.33,1,.68,1),
              padding ${NAV_FOLD}ms cubic-bezier(.33,1,.68,1),
              visibility 0s linear 0s !important; }

/* Три равные колонки: ссылки, гертруда, пока пустая третья. Доли
   задаём через flex: 1 1 0px — то есть делим не остаток, а всю ширину:
   при 1 1 auto колонки поделили бы только свободный ход, и ширина
   каждой зависела бы от длины названий подлепр. Место под третью
   колонку должно стоять на месте независимо от содержимого соседей.
   min-width: 0 обязателен: у флекс-элемента нижний предел ширины по
   умолчанию равен ширине содержимого, и длинное название подлепры
   раздуло бы первую колонку за свою треть. */
.lm-navthing_top {
  display: flex !important; align-items: flex-start !important;
  gap: 10px !important; }
.lm-navthing_links, .lm-navthing_pic, .lm-navthing_extra {
  flex: 1 1 0px !important; min-width: 0 !important; }
/* Блоги Империи. У лепры отбивка слева 45 пикселей — под герб, прибитый
   абсолютно в левый верхний угол, плюс ещё по 20 у заголовка и пунктов
   списка: там оставлено место под крестик «отписаться». Двадцатки убираем
   вместе с крестиком (см. ниже), а отбивку под герб — вместе с гербом:
   он теперь стоит в свёрнутой строке слева от подписи «Навигационная
   штука», и держать его копию внутри незачем. Столбик ссылок встаёт
   вплотную к левому краю блока.
   Ширина 140 и черта снизу приходят от .b-aside_item — того же элемента. */
.lm-navthing_links .b-aside_imperial_blogs {
  width: auto !important; min-height: 0 !important;
  margin: 0 !important; padding: 0 !important;
  border-bottom: 0 !important; }
/* Герб внутри прячем, а не удаляем: узел леприн, и хотя он декоративный,
   выдёргивать чужие узлы из разметки ради косметики не стоит. */
.lm-navthing_links .b-aside_imperial_blogs_bg { display: none !important; }
/* Блок власти: президент и вход в Белый дом в общей рамке.
   Обводка, а не черта под ними: пара эта про одно — кто правит и куда
   идти смотреть, — а список подлепр под нею про другое, и рамка
   разделяет их честнее линии. Тон рамки тот же, что у карточки:
   другого серого в наборе заводить незачем.
   По центру: внутри рамки левый край держать не за что, а строки тут
   короткие и разной длины.
   Отбивка снизу отделяет рамку от списка; своих отбивок ни у президента
   внутри, ни у заголовка при этом нет — их задаёт эта коробка. */
.lm-navthing_gov {
  margin: 0 0 8px !important;
  padding: 6px 6px 7px !important;
  border: 1px solid ${FRAME_C} !important;
  border-radius: ${UI_R}px !important;
  text-align: center !important; }
/* display: block обязателен — strong строчный, и у него собственная
   ширина по буквам; блоком он занимает строку целиком, и выравнивание
   от рамки достаётся ему как надо. Своей раскладки лепра на этом узле
   не держит, внутри одна ссылка. */
/* Кегль и начертание — как у ника президента строкой выше: это
   равноправная строка блока, а не заголовок над ним. Полужирное
   начертание strong снимаем явно — оно у него от встроенной таблицы
   браузера, а не от лепры, и без сброса «Белый дом» выделялся бы
   вдвойне: и жиром, и размером. */
.lm-navthing_gov strong {
  display: block !important;
  margin: 3px 0 0 !important; padding: 0 !important;
  font-weight: normal !important;
  font-size: 13px !important; }
.lm-navthing_links .b-aside_imperial_blogs ul { margin: 0 !important; }
.lm-navthing_links .b-aside_imperial_blogs li {
  padding-left: 0 !important; margin-bottom: 3px !important; }
.lm-navthing_links .b-aside_imperial_blogs a { font-size: 13px !important; }
/* Президент — первой строкой столбика. У лепры блок отбит слева на 65
   пикселей под портрет, который лежит там же абсолютно; портрет прячем
   (в колонку шириной в треть экрана он не встанет), отбивку снимаем.
   Кегль ника 17 у неё рассчитан на боковую колонку — здесь он был бы
   вдвое крупнее соседнего списка; ставим тот же 13, что и у ссылок.
   Подпись под ником мельче и серее: это пояснение, а не ссылка. */
/* Отбивок у президента нет вовсе: расстояние до заголовка задаёт его
   собственная верхняя отбивка, а расстояние до края — поля рамки. Два
   источника отступа между одними и теми же узлами всегда кончаются
   двойным. */
.lm-navthing_links .b-aside_president {
  width: auto !important; min-height: 0 !important;
  margin: 0 !important; padding: 0 !important;
  border-bottom: 0 !important; }
.lm-navthing_links .b-aside_president_bg { display: none !important; }
/* Ник подрос с 13 до 15: рядом с ним встала корона, и при прежнем кегле
   она выглядела не значком при имени, а картинкой, к которой имя
   приписано мелким шрифтом.

   display: inline-block — вот из-за чего корона оказывалась НАД ником, а
   не слева. У лепры на этой ссылке стоит display: block, то есть она
   занимает строку целиком, и вставленный перед ней значок вытесняется
   на строку выше. Строчный блок ставит их соседями по одной строке, а
   выключка по центру у рамки уже есть.

   Менять display чужому узлу мы обычно не беремся — на нём у лепры
   держится раскладка. Здесь случай безопасный и разобран отдельно:
   блочной ссылку сделали ради обрезки длинного ника многоточием
   (overflow: hidden плюс text-overflow: ellipsis, а они требуют
   небудь-строчного), и inline-block это свойство сохраняет полностью.
   Внутри ссылки один текстовый узел, больше на ней ничего не висит.

   Потолок ширины — вычитанием, а не 100%: сотня процентов считается от
   рамки целиком, и при длинном нике пара «корона плюс имя» вылезала бы
   за неё и переносилась. Вычитаем ровно место короны с её отбивкой. */
.lm-navthing_links .b-aside_president a,
.lm-navthing_links .b-aside_president b { font-size: 15px !important; }
.lm-navthing_links .b-aside_president a {
  display: inline-block !important;
  vertical-align: middle !important;
  max-width: calc(100% - ${PRES_CROWN_W + 4}px) !important; }
/* Подпись под ником — 10 вместо 11. Это две строки пояснения («Президент
   Грузии», «с 26.02 по 22.02»), они самые длинные в узкой колонке и
   переносились; и это самое неважное, что в блоке есть.
   Верхняя отбивка 3, а не 1: корона опущена на два пикселя и выходит за
   нижний край своей строки ровно на столько же. Сдвиг сделан свойством
   top, а оно раскладку не трогает — то есть место под короной никто не
   освободит, и отбивку приходится задавать здесь. */
.lm-navthing_links .b-aside_president p {
  margin: 3px 0 0 !important;
  font-size: 10px !important; line-height: 1.3 !important;
  color: rgb(110,110,110) !important; }
/* Корона. Строчный блок, а не блок: она сосед ника по одной выключенной
   по центру строке, и центруются они вместе.
   Выравнивание по середине строчного ящика, а не по базовой линии: у
   svg базовой линии нет, и по умолчанию он сел бы нижним краем на
   линию букв, то есть выше нужного на добрую треть.
   Дальше опускаем ещё на два: по чистой середине строки корона
   вставала чуть выше глазной линии имени. Сдвигаем свойством top у
   relative, а не отбивкой: top ничего не двигает в потоке, то есть
   строка не становится выше и соседи не разъезжаются. Место под эти
   два пикселя отдаёт подпись — см. её отбивку выше.
   Отбивка справа отделяет корону от имени; слева отбивки нет —
   расстояние до края рамки задают её поля, а два источника отступа
   между одними и теми же узлами всегда кончаются двойным. */
.lm-crown {
  display: inline-block !important;
  position: relative !important; top: 2px !important;
  width: ${PRES_CROWN_W}px !important; height: ${PRES_CROWN_W}px !important;
  margin: 0 4px 0 0 !important; padding: 0 !important;
  vertical-align: middle !important;
  flex: 0 0 auto !important; }
.lm-crown svg {
  display: block !important;
  width: ${PRES_CROWN_W}px !important; height: ${PRES_CROWN_W}px !important; }
/* Ссылка на архив. Кегль и отбивка — как у пунктов списка выше, чтобы
   строка читалась продолжением столбика, а не приклеенной снизу
   врезкой. Блочная: строчная встала бы в одну строку с последним
   пунктом списка, если у того короткое имя.
   По умолчанию скрыта — показывает её класс на html, см. applyNavArch.
   Прячем display'ем, а не прозрачностью: погашенная до нуля ссылка
   продолжает ловить нажатия, и это уже стоило нам одного круга на
   кнопке «наверх». */
.lm-navthing_arch { display: none !important; }
html.lm-arch .lm-navthing_arch {
  display: block !important;
  margin-top: 3px !important; padding-left: 0 !important;
  font-size: 13px !important; }
/* Крестик «отписаться» лепра показывает по .b-aside_imperial_blogs
   li:hover. Я считал, что на телефоне это правило мёртвое, — оказалось
   нет: Safari после тапа по ссылке оставляет на пункте состояние hover,
   крестик выезжает и висит до следующего тапа в стороне.
   Убираем совсем, а не отодвигаем: это действие разрушающее — подлепра
   уходит из списка — и держать его под тем самым пальцем, которым только
   что открывали ссылку, не стоит. К тому же в копии, восстановленной из
   памяти на внутренних страницах, крестика нет вовсе, и список вёл бы
   себя по-разному в зависимости от страницы.
   Селектор нарочно с :hover: правило лепры весит три класса и элемент,
   ровно столько же весило бы моё без него, и спор решался бы порядком
   объявления — то есть по-разному в браузере и в проверке. */
.lm-navthing_links .b-aside_imperial_blogs li:hover .b-close_btn,
.lm-navthing_links .b-aside_imperial_blogs .b-close_btn {
  display: none !important; }
/* Гертруда. Ширина постоянная: подгонка под высоту столбика ссылок
   убрана — в трёх равных колонках картинка, растущая от длины чужого
   списка, ломала бы саму сетку.
   Предел по колонке всё равно нужен: при увеличенном масштабе страницы
   треть экрана уже 118 пикселей, и без max-width картинка вылезла бы
   на соседнюю колонку. Поле auto — на случай обратный: колонка шире
   картинки, и та встаёт по её середине.
   position: relative — гнездо для гвоздика поверх картинки. */
.lm-navthing_pic { min-width: 0 !important; }
/* Гнездо по размеру картинки. Нужно ради гвоздика: колонка бывает шире
   картинки (при 462 — 142 против 118), и отсчитанный от колонки левый
   край угодил бы левее самой картинки, рядом с ней, а не на неё.
   Гнездо ужимается по картинке, поэтому её угол и угол гнезда — одно и
   то же место при любой ширине колонки. */
.lm-navthing_gert {
  position: relative !important;
  width: ${CFG.gertruda}px !important; max-width: 100% !important;
  margin: 0 auto !important; }
.lm-navthing_gert img {
  display: block !important;
  width: 100% !important; max-width: 100% !important;
  height: auto !important; margin: 0 !important; }

/* Третья колонка — всё управление лентой: переключатель вида («только
   заглавная», «заглавная и подсайты», «только подсайты»), под ним порог
   постов («NORMAL (0)», «NIGHTMARE (все)»), под ним поиск с лупой. Все
   трое пришли из нижней строки шапки, и это её последняя строка: шапка
   сократилась до приветствия, ссылок и пары «счётчики — приглашение».

   Подписи «Тип контента» больше нет. В одиночку переключатель без неё
   был бы тремя загадочными значками, а в наборе из трёх органов
   управления читается по соседям — и любая надпись над одним из них
   выглядела бы заголовком ко всей колонке.

   Колонка — флекс сверху вниз. Порядок задан разметкой, а не order:
   переставлять тут нечего, а лишнее свойство пришлось бы держать
   согласованным с кодом. Зазор 8 — между разнородными органами, у
   которых своих отбивок нет.

   Ширина: треть строки при экране 393 — это 119 пикселей (393 минус 16
   отбивок тела, минус 20 на два зазора между колонками, делить на три).
   Переключатель занимает 98 (три значка по 26 плюс два зазора по 10;
   в шапке зазоры были 18 и у значков ещё по 4 отбивки — в сумме 138,
   что сюда бы не влезло). Поле выбора и поиск тянутся по колонке. */
.lm-navthing_extra {
  display: flex !important; flex-direction: column !important;
  align-items: stretch !important; gap: ${UI_GAP}px !important; }
.lm-navthing_extra .b-index_slider,
.lm-navthing_extra .b-index_slider .b-slider_scale_icons {
  justify-content: center !important;
  flex-wrap: wrap !important; gap: 10px !important; }
.lm-navthing_extra .b-slider_scale_icon {
  margin: 0 !important; border-radius: ${UI_R}px !important; }
/* Выбранный значок лепра красит в rgb(220,218,218) — тот же серый, что
   у нажатых кнопок, так что перекрашивать нечего. А вот наведение на
   телефоне вредит: Safari оставляет состояние hover на значке после
   тапа, и серым горят сразу два — выбранный и последний нажатый.
   Гасим подсветку у всех, кроме выбранного; селектор тяжелее лепровского
   и стоит ниже по файлу, так что спор решается одинаково и по весу, и
   по порядку. */
.lm-navthing_extra .b-slider_scale_icon:hover:not(.js-feed_type_active) {
  background-color: transparent !important; }

/* Порог постов. Базовое правило выше даёт ему flex: 1 1 160px — оно
   писалось для строки шапки, где 160 были ОСНОВОЙ ПО ШИРИНЕ. Здесь
   направление колонки, и то же число стало бы основой по ВЫСОТЕ:
   пустая форма распухла бы на полтора сантиметра. Поэтому flex сбрасываем
   явно, а не полагаемся на то, что он «про ширину».
   У лепры блок плавающий и с нижним пределом ширины в 270 — снимаем и
   это: колонка вчетверо уже. */
.lm-navthing_extra .b-posts_threshold {
  flex: 0 0 auto !important; float: none !important;
  width: auto !important; min-width: 0 !important; min-height: 0 !important;
  margin: 0 !important; padding: 0 !important; }
/* Форма у лепры position: relative — держала абсолютно прибитый
   переключатель, которого в ней больше нет. */
.lm-navthing_extra .b-posts_threshold form {
  position: static !important; margin: 0 !important; padding: 0 !important; }
/* Ширину полю выбора задаёт самый длинный вариант («NIGHTMARE (все)»),
   а не выбранный, — то есть само оно шире колонки. Прижимаем к её
   ширине: в свёрнутом виде длинный вариант срежется, в раскрытом списке
   Safari покажет его целиком. */
.lm-navthing_extra .b-posts_threshold select {
  display: block !important;
  width: 100% !important; max-width: 100% !important;
  box-sizing: border-box !important; margin: 0 !important;
  /* Начальный кегль — из CFG.thresholdFont. Дальше его подбирает
     замером fitThreshold: длинный вариант в треть строки не влезает. */
  font-size: ${CFG.thresholdFont}px !important;
  border-radius: ${UI_R}px !important;
  /* Общая высота столбика — см. CFG.uiRow. Поле выбора Safari рисует по
     своим правилам, и без явной высоты оно единственное из четырёх
     оказывалось на пару пикселей ниже соседей. */
  height: ${CFG.uiRow}px !important; }

/* Поиск. Порядок обратный базовому: поле, за ним лупа, связка прижата
   влево — как было в шапке отдельной строкой.
   Нижний предел ширины поля (90 в базовом правиле) здесь снят совсем:
   при увеличенном масштабе, когда CSS-ширина экрана падает до 340,
   треть строки равна 101, и поле с пределом вылезло бы на гертруду.
   Пусть сжимается вместе с колонкой — это ровно тот случай, когда
   узкое поле лучше сломанной сетки. Ширину 86% от лепры тоже снимаем:
   обёртка у нас display: contents, коробки не имеет, и проценты
   считаются от формы — то есть поле никогда не занимало бы остаток. */
.lm-navthing_extra .b-header_search {
  flex: 0 0 auto !important; min-width: 0 !important;
  position: static !important; left: auto !important;
  margin: 0 !important; padding: 0 !important; }
.lm-navthing_extra #js-header_search_form {
  justify-content: flex-start !important;
  /* Лупа ниже поля, и при растяжке по умолчанию она вытянулась бы во всю
     высоту строки вместе со своей подложкой. Ставим по центру. */
  align-items: center !important; }
.lm-navthing_extra #js-header_search_form .i-form_text_input {
  order: 1 !important; flex: 1 1 auto !important;
  width: auto !important; min-width: 0 !important;
  box-sizing: border-box !important;
  border-radius: ${UI_R}px !important;
  height: ${CFG.uiRow}px !important; }
.lm-navthing_extra #js-header_search_form .b-icon_button_search {
  order: 2 !important; }

/* Заливка. На главной оба блока приезжают с жёлтой подложкой (на
   подлепрах её нет), а по сохранённой странице источник не сошёлся: в
   таблицах лепры на эти узлы ложатся серый 245 у поля выбора, белый у
   поля ввода и прозрачный у всех обёрток — жёлтого там нет ни в одном
   правиле. Ближайший похожий оттенок в её палитре — rgb(246,239,210):
   им покрашены общее правило для любых select и выпадашка быстрого
   поиска. Гадать, кто из них добрался до экрана, смысла нет: задаём
   заливку явно всем узлам обоих блоков, и любое правило из таблиц
   лепры перекрывается независимо от того, какое именно виновато.

   Значков переключателя это не касается: у активного значка подложка
   rgb(220,218,218) — она и показывает выбранный тип ленты. */
.lm-navthing_extra .b-posts_threshold,
.lm-navthing_extra .b-posts_threshold .b-i-posts_threshold,
.lm-navthing_extra .b-posts_threshold form,
.lm-navthing_extra .b-header_search,
.lm-navthing_extra #js-header_search_form,
.lm-navthing_extra #js-header_search_form .b-header_search_input_holder {
  background: transparent !important; }
.lm-navthing_extra .b-posts_threshold select,
.lm-navthing_extra #js-header_search_form .i-form_text_input {
  background-color: rgb(255, 255, 255) !important;
  background-image: none !important; }

/* Овощебаза. У лепры это блок в 213px, а подпись отбита слева на 64
   пикселя под завиток фоновой картинки колонки, которой здесь нет.
   Показываем только с непустым списком замен: пустая жёлтая плашка —
   это подпись к тому, чего нет. Класс ставится проверкой (syncVeg), а
   не безусловным правилом, потому что список приходит позже разметки. */
.lm-navthing_veg { display: none !important; margin-top: 10px !important; }
.lm-navthing_veg.lm-on { display: block !important; }
.lm-navthing_veg .b-aside_replacements {
  width: auto !important; margin: 0 !important; }
.lm-navthing_veg .b-aside_replacements_header {
  margin: 0 !important; font-size: 13px !important; }
.lm-navthing_veg .b-aside_replacements_list_items,
.lm-navthing_veg .b-aside_replacements_list_counter {
  margin-left: 0 !important; }
.lm-navthing_veg .b-aside_replacements_list_item { padding-left: 0 !important; }
.lm-navthing_veg .b-aside_replacements_list_item_rating {
  position: static !important; }

/* Гвоздик — по верху средней колонки, поверх гертруды. Кнопка своего фона
   не имеет: закреплено или нет, видно по самому значку — стоит прямо или
   наклонён и приглушён. Галка, стоявшая тут раньше, отнимала строку и
   звала взгляд синим пятном, а смотреть в этом блоке надо не на неё.
   Абсолют считается от гнезда картинки, а не от колонки: угол должен
   быть у гертруды, а не у пустого места рядом с нею.
   top и left — отступ КНОПКИ от угла картинки. Сам значок внутри кнопки
   стоит ещё на 3 ниже и на 3.5 правее: у svg поле сверху, а по ширине
   он 15 при кнопке 22. То есть при нуле здесь линии значка всё равно
   отходят от угла картинки на три пикселя.
   Дальше двигать — отрицательными числами, значок выйдет за картинку. */
.lm-navthing_pin {
  position: absolute !important; z-index: 2 !important;
  top: -5.8px !important; left: -6.9px !important;
  width: 22px !important; height: 22px !important;
  margin: 0 !important; padding: 0 !important;
  background: none !important; border: 0 !important;
  -webkit-appearance: none !important; appearance: none !important;
  color: rgb(90, 90, 90) !important;
  line-height: 0 !important; cursor: pointer !important;
  -webkit-tap-highlight-color: transparent !important;
  touch-action: manipulation !important; }
/* Белая обводка значка: под ним теперь не ровный светлый фон блока, а
   картинка, и на тёмной гертруде серый гвоздик пропадал бы совсем.
   Тень в два прохода — один даёт слишком жидкий ореол. */
.lm-navthing_pin svg {
  display: block !important; margin: 3px auto 0 !important;
  filter: drop-shadow(0 0 1.5px rgba(255,255,255,.95))
          drop-shadow(0 0 1.5px rgba(255,255,255,.95)) !important;
  transition: transform .15s !important; }
/* Откреплено: гвоздик вынут и лежит боком. Приглушение неглубокое: под
   значком картинка, и на пёстрой гертруде более бледный он терялся. */
.lm-navthing_pin:not(.lm-on) { opacity: .55 !important; }
.lm-navthing_pin:not(.lm-on) svg {
  transform: rotate(-40deg) !important; }

/* ============ ПОИСК: РАСКРЫТИЕ ПОЛЯ И ДИНАМОПОИСК ============ */
/* Поле поиска стоит то в третьей колонке навигационной штуки, то в конце
   строки ссылок сжатой шапки — шириной в треть экрана и прижатое к
   разным краям. Само по себе это терпимо: вводят в него редко. Но к
   полю привязан динамический поиск лепры — список найденного, который
   всплывает под полем прямо во время набора. Место и размер списка лепра
   считает своим скриптом и пишет инлайном; в сохранённой странице там
   было width: 376px; top: 84px; right: 72px — то есть отсчёт от правого
   края окна шириной под тысячу. На телефоне список выходил за экран, и
   с ним половина каждой строчки.

   Правим с трёх сторон.

   Первое: на время ввода поле растягивается влево до кромки экрана.
   Оттяжка — отрицательное левое поле у ФОРМЫ. Форма внутри
   .b-header_search обычный блочный элемент, и отрицательное левое поле
   ровно на столько же увеличивает её ширину: блок в потоке остаётся на
   месте, колонка и соседи не пересчитываются, а форма просто наезжает
   поверх гертруды. Величину даёт скрипт переменной --lm-srch-pull:
   в CSS её не вычислить, левый край поля свой на каждой странице.

   Второе: кегль на время ввода — 16. Safari приближает страницу к
   любому полю мельче шестнадцати, и на приближённом экране список был
   бы обрезан независимо от его ширины. Высоту поля при этом не трогаем:
   у лепры она 25 с рамкой и отбивками, внутрь остаётся 19 — ровно
   строка шестнадцатым кеглем. Так касание не двигает ничего по
   вертикали, и верх списка не съезжает.

   Третье: сам список прижимается к обоим краям экрана, а высота ему
   отмеряется от низа поля до верхней кромки клавиатуры (--lm-qs-max).
   Внутренняя обёртка .b-quick_search у лепры прокручиваемая, поэтому
   лишнее не обрезается, а листается. Высоту ей лепра тоже пишет
   инлайном (height: 585px) — снимаем, иначе предел не сработает.
   ВАЖНО: max-height самого контейнера не трогаем ни при каких условиях.
   Им лепра список и закрывает — гасит до нуля с переходом; наш предел
   поверх оставил бы список открытым навсегда.

   Класс lm-search_qs ставится при первом касании поля и больше не
   снимается. Снимать его нельзя: тап по строчке списка сначала снимает
   фокус с поля, и если в этот миг вернуть списку лепровы координаты,
   строчка уедет из-под опускающегося пальца. По той же причине
   отложено и схлопывание поля — см. searchHold. */
/* Два состояния, а не одно. По касанию поле ничего не делает, кроме
   курсора, — раздвигать его до того, как человек начал вводить, значит
   двигать страницу на пустом месте: в поле можно ткнуть и передумать.
   Единственное, что приходится сделать сразу, — поднять кегль
   (lm-search_font): решение о приближении Safari принимает в момент
   нажатия, и после фокуса менять что-либо уже поздно. По вертикали это
   ничего не двигает, у поля своя высота в 25 с местом ровно под строку
   шестнадцатым кеглем. Раздвижка и подкрутка (lm-search_wide) ждут
   первой буквы — то есть того мгновения, когда список и правда нужен. */
html.lm-search_font #js-header_search_form .i-form_text_input,
html.lm-search_font .b-header_search .i-form_text_input {
  font-size: var(--lm-srch-font, ${CFG.searchFocusFont}px) !important;
  /* Высоту больше не держим в 19: кегль теперь плавающий (при
     уменьшенном масштабе страницы он поднимается до девятнадцати и
     выше), и жёсткая строка обрезала бы у букв низ. Поле растёт само,
     а нижний предел оставляет прежнюю высоту там, где кегль остался
     шестнадцатым. Верх списка от этого не съезжает: он меряется по
     нижней кромке поля уже после подъёма кегля. */
  line-height: normal !important;
  height: auto !important; min-height: 25px !important;
  box-sizing: border-box !important; }
html.lm-search_wide #js-header_search_form,
html.lm-search_wide .b-header_search form {
  position: relative !important; z-index: 4 !important;
  margin-left: var(--lm-srch-pull, 0px) !important; }
html.lm-search_wide #js-header_search_form .i-form_text_input,
html.lm-search_wide .b-header_search .i-form_text_input {
  flex: 1 1 auto !important; width: auto !important; min-width: 0 !important; }
/* Список. Селектор по классу, а не по id: id у контейнера один на
   страницу, но правило должно работать и там, где лепра назовёт его
   иначе. Слой выше прыгалок (30) — список теперь во всю ширину, и
   треугольники навигации попали бы прямо на строчки. */
html.lm-search_qs .b-quick_search_container {
  left: ${CFG.pageEdge}px !important; right: ${CFG.pageEdge}px !important;
  width: auto !important; max-width: none !important;
  box-sizing: border-box !important;
  z-index: 50 !important;
  top: var(--lm-qs-top, 0px) !important; }
html.lm-search_qs .b-quick_search {
  height: auto !important;
  max-height: var(--lm-qs-max, 40vh) !important;
  /* Прокрутку задаём явно, хотя она есть и у лепры: у неё это
     двузначное overflow: hidden auto, и опираться на разбор сокращения
     там, где от него зависит, обрежется список или залистается, не стоит. */
  overflow-y: auto !important; }

/* Закрытие списка. Своего закрытия у лепры на телефоне нет: тап мимо
   списка на десктопе снимает фокус с поля мышью, а на телефоне список
   так и висит поверх страницы с введённым текстом внутри поля.
   Закрываем двумя способами — тапом мимо и крестиком.

   Крестик нужен именно из-за подкрутки: поле уезжает под верхнюю кромку,
   снизу стоит клавиатура, список занимает всё между ними — тапать «мимо»
   становится некуда. Кнопку вешает скрипт (ensureQsClose) прямо в
   контейнер списка: он позиционирован, значит он же и система координат.

   Прячем список классом, а не инлайновым стилем: инлайн лепра
   переписывает своим скриптом на каждой букве, и спор с ним шёл бы по
   кругу. Класс снимается при следующем касании поля — то есть список
   выключен ровно до тех пор, пока в нём нет нужды. */
html.lm-search_off .b-quick_search_container { display: none !important; }
.lm-qs_close {
  position: absolute !important; top: 0 !important; right: 0 !important;
  z-index: 3 !important;
  width: 34px !important; height: 34px !important;
  margin: 0 !important; padding: 0 !important;
  background: none !important; border: 0 !important;
  -webkit-appearance: none !important; appearance: none !important;
  font: 21px/34px Arial, sans-serif !important;
  color: rgb(120, 120, 120) !important; text-align: center !important;
  cursor: pointer !important;
  -webkit-tap-highlight-color: transparent !important;
  touch-action: manipulation !important; }

/* ============ СТРАНИЦА БОЛЬШОГО ПОИСКА ============ */
/* /search/. Верстка рассчитана на широкое окно и держится на абсолютном
   позиционировании: у .b-search_header отбивка справа в 185 пикселей, и в
   этот карман положены кнопка YARRR (top 15, right 15) и переключатель
   «простой/сложный» (top 70, right 185). На телефоне карман съедает
   половину строки, а строка запроса, растянутая на «оставшееся», выходит
   в палец шириной.

   Переставляем в столбец: поле, кнопка, переключатель, «точное
   совпадение». Порядок задан order по флексу, а не перестановкой узлов:
   разметку страницы ведёт скрипт лепры (он переключает режимы
   простой/сложный/результаты атрибутами js-toggle), и двигать под ним
   узлы — напрашиваться на разъезд.

   Кнопку тянем во всю ширину. Её три слоя (сама кнопка и два
   псевдоэлемента) нарисованы градиентами с точками остановки в пикселях
   от высоты — 38, 39, 41; высоту поэтому не трогаем вовсе, только
   ширину. Иначе поплывут все три подсветки разом.

   ВНИМАНИЕ: display у .b-search_settings и .b-search_results не трогать.
   Ими лепра переключает режимы правилом .b-search [js-toggle] с
   display: none !important, и наш display поверх намертво раскрыл бы
   скрытое. Отбивки и ширины править можно, display — нет. */
#js-search.b-search { padding-right: 0 !important; }
/* Газманов. Лежит не внутри поиска, а последним соседом в .l-wrapper —
   то есть ровно перед подвалом, где ему и место. Мешало только то, как он
   там держится: absolute, right 0, 452 пикселя ширины и z-index 3, а
   низом лепра его двигает своим скриптом (в разметке остаётся
   bottom: 162px). На телефоне это лишняя горизонтальная тяга и картинка
   поверх текста.

   Ставим в поток. Спрайт 452×900 — три кадра по 300, лепра выбирает кадр
   атрибутом data-emotion и сдвигом фона в пикселях. Пиксели привязаны к
   натуральной величине, поэтому при масштабировании считаем в процентах:
   при background-size: 100% auto картинка ровно втрое выше рамки, и
   процент отсчитывается от разницы — кадры приходятся на 0, 50 и 100.

   display задан жёстко: лепра прячет Газманова классом hidden и
   показывает по приходу результатов. На форме без результатов он теперь
   виден тоже — картинка украшает подвал, а не сообщает о чём-либо. */
#js-search_toasty.b-search_toasty {
  display: block !important;
  position: static !important;
  right: auto !important; bottom: auto !important; z-index: auto !important;
  width: 100% !important; max-width: 452px !important;
  height: auto !important; aspect-ratio: 452 / 300 !important;
  margin: 10px auto 0 !important;
  background-size: 100% auto !important;
  background-position: 0 0 !important; }
#js-search_toasty.b-search_toasty[data-emotion="1"] {
  background-position: 0 50% !important; }
#js-search_toasty.b-search_toasty[data-emotion="2"] {
  background-position: 0 100% !important; }

/* Внутренности: три колонки в одну, отбивки вдвое, поля под палец.
   Мелкие поля у лепры кеглем 13 — Safari приближает страницу к любому
   мельче шестнадцати, а на этой странице их полтора десятка, и каждое
   касание дёргало бы экран. Ширины подняты следом за кеглем: дате нужно
   десять знаков. */
#js-search .b-search_settings { padding: 0 !important; font-size: 13px !important; }
#js-search .b-search_section { margin: 10px 0 !important; }
#js-search .b-search_section:last-child { display: block !important; }
#js-search .b-search_section_block {
  width: 100% !important; float: none !important;
  padding: 10px 0 0 !important;
  border-left: 0 !important;
  border-top: 1px solid rgb(230, 230, 230) !important; }
#js-search .b-search_section_block:first-child {
  padding-top: 0 !important; border-top: 0 !important; }
#js-search .b-search_section_block_part { margin-bottom: 10px !important; }
#js-search .b-search_settings label {
  min-height: 20px !important; margin-right: 0 !important;
  margin-top: 3px !important; }
#js-search .b-search_settings h3 { margin-bottom: 5px !important; }
#js-search .i-form_text_input { font-size: 16px !important; }
#js-search .b-search_settings .i-form_text_input__short { width: 84px !important; }
#js-search .b-search_settings .b-search_dates .i-form_text_input__short {
  width: 112px !important; }
#js-search .b-search_settings label span s input[type="text"][name="link_to"] {
  width: 100% !important; max-width: 220px !important; }
#js-search .b-search_sort { padding-left: 0 !important; }
#js-search .b-search_docs_results { margin-left: 0 !important; }
#js-search .b-results_filter {
  margin-left: 0 !important;
  padding-bottom: 8px !important; margin-bottom: 8px !important; }
#js-search .b-load_more_button_container { margin-left: 0 !important; }

#js-search .b-search_header {
  display: flex !important; flex-direction: column !important;
  align-items: stretch !important; gap: 6px !important;
  padding: 0 !important; }
/* Кнопка ОБЯЗАНА остаться позиционированной. Её жёлтая заливка и надпись
   нарисованы двумя псевдоэлементами с position: absolute и координатами
   от кнопки; со static кнопка перестаёт быть для них системой отсчёта,
   отсчёт уходит к ближайшему позиционированному предку — .b-search_header
   — и оба слоя остаются в его левом верхнем углу, поверх строки ввода.
   Поэтому relative, а не static: из потока кнопка не выпадает, а
   координаты absolute у лепры сбрасываем поимённо. */
#js-search .b-search_header button.b-button__gradient {
  order: 2 !important;
  position: relative !important; top: auto !important; right: auto !important;
  margin: 0 !important; width: 100% !important; }
#js-search .b-search_header button.b-button__gradient::before {
  width: calc(100% - 2px) !important; }
#js-search .b-search_header button.b-button__gradient::after {
  width: 100% !important; }
/* Нажатие лепра рисует сдвигом на пиксель, но на этой странице она делает
   это через position: absolute; top: 16px — в столбце кнопка от такого
   улетает. Возвращаем сдвиг, который и был задуман. */
#js-search .b-search_header button.b-button__gradient:active,
#js-search .b-search_header button.b-button__gradient:hover:active {
  position: relative !important; top: 1px !important; }
#js-search .b-search_header input[type="text"] {
  order: 1 !important; width: 100% !important; margin: 0 !important;
  height: ${CFG.bigSearchField}px !important;
  font-size: ${CFG.bigSearchFont}px !important;
  box-sizing: border-box !important; }
#js-search .b-search_header a#js-search_settings_mode_toggle {
  order: 3 !important;
  position: static !important; top: auto !important; right: auto !important;
  align-self: flex-start !important; }
#js-search .b-search_settings .b-search_header label {
  order: 4 !important;
  margin: 0 !important; min-height: 0 !important; }

/* Раздвижка строки запроса с первой буквы — то же, что и в шапке, только
   тянуть приходится в обе стороны: это поле стоит посреди колонки, а не
   прижато к краю. Оттяжки считает скрипт, каждую по своей стороне. */
html.lm-search_big #js-search .b-search_header {
  margin-left: var(--lm-big-l, 0px) !important;
  margin-right: var(--lm-big-r, 0px) !important; }

/* ============ ДИСКО ============ */
/* Сокращённый просмотр ленты. Правила лежат ниже всех остальных нарочно:
   они спорят с общими правилами постов (высота тела, видимость медиа), и
   спор должен решаться одинаково и по весу селектора, и по порядку —
   иначе проверка в jsdom разойдётся с браузером.

   Две кнопки друг над другом в третьей колонке, под поиском: «DISCO» —
   сокращённые посты, «scroll-connect» — микрогеймификация поверх них.
   Нажимаются по отдельности, подписи не меняются: состояние показывает
   подложка того же оттенка, каким лепра подсвечивает выбранный значок
   переключателя типа ленты.
   Слипание нажатых кнопок в одну область убрано намеренно. Оно
   говорило «эти двое — одно целое», а это неправда: режимы разные, и
   scroll-connect скоро перестанет быть придатком к диско (диско
   становится тремя пиктограммами). Пусть промежуток стоит всегда.
   Кегль: «scroll-connect» — четырнадцать знаков, набором Verdana это
   около 95 пикселей вместе с отбивками, то есть строка влезает в
   колонку при экране 393 (111) и упирается в неё при увеличенном
   масштабе (93). Поэтому не просто nowrap: лишнее срезается
   многоточием, а не выпирает за рамку. */
/* Просвет тот же, что и между органами колонки (UI_GAP): обёртка эта —
   деталь устройства, а не смысловая группа, и человек должен видеть
   один ровный столбик, а не «пиктограммы с кнопкой» отдельно от
   остального. */
.lm-navthing_extra .lm-disco_pad {
  flex: 0 0 auto !important;
  display: flex !important; flex-direction: column !important;
  gap: ${UI_GAP}px !important; }
/* Три пиктограммы уплотнения — строкой, как значки типа ленты внизу
   колонки. Размеры и зазор взяты оттуда же (26 и 10): два ряда значков
   в одной колонке обязаны выглядеть одним семейством, иначе колонка
   разваливается на «наши кнопки» и «кнопки лепры».
   Высота строки равна высоте значка, а не CFG.uiRow: uiRow — про
   столбик прямоугольных органов (поле выбора, поле ввода, кнопка), а
   значки живут по своим правилам, и растянутый до тридцати квадрат
   перестал бы быть квадратом. */
.lm-navthing_extra .lm-disco_modes {
  display: flex !important; justify-content: center !important;
  align-items: center !important;
  flex-wrap: wrap !important; gap: 10px !important; }
.lm-navthing_extra .lm-disco_mode {
  flex: 0 0 auto !important;
  width: 26px !important; height: 26px !important;
  padding: 0 !important; margin: 0 !important;
  display: flex !important; align-items: center !important;
  justify-content: center !important;
  -webkit-appearance: none !important; appearance: none !important;
  border: 0 !important; background: transparent !important;
  border-radius: ${UI_R}px !important;
  -webkit-tap-highlight-color: transparent !important;
  touch-action: manipulation !important;
  cursor: pointer !important; }
/* Выбранный — тем же серым, каким лепра красит выбранный значок ленты. */
.lm-navthing_extra .lm-disco_mode.lm-on {
  background: rgb(220, 218, 218) !important; }
.lm-navthing_extra .lm-disco_mode:active {
  background: rgb(236, 234, 234) !important; }
.lm-navthing_extra .lm-disco_mode svg {
  display: block !important; width: 24px !important; height: 24px !important; }
.lm-navthing_extra .lm-disco_btn {
  /* Флекс, а не блок: высота теперь задана числом (CFG.uiRow), и строку
     внутри надо ставить по центру — отбивками этого не сделать, они
     считаются от кегля, а он у соседей разный. */
  display: flex !important; align-items: center !important;
  width: 100% !important; height: ${CFG.uiRow}px !important;
  box-sizing: border-box !important;
  margin: 0 !important; padding: 0 2px !important;
  -webkit-appearance: none !important; appearance: none !important;
  border: 1px solid rgb(190, 188, 188) !important;
  border-radius: ${UI_R}px !important;
  background: rgb(255, 255, 255) !important;
  color: inherit !important;
  /* Свойства шрифта перечисляем по одному. Шорткат font: inherit,
     стоявший здесь раньше, в Safari сбрасывал кегль обратно к
     унаследованному, и кнопки набирались тринадцатью вместо заданных
     одиннадцати — а рядом стоящее поле поиска тринадцатью и набрано,
     так что расхождение вылезло не на них, а на порогах. Та же грабля
     уже описана у свёрнутой строки навигационной штуки. */
  font-family: inherit !important; font-weight: normal !important;
  font-size: ${UI_FONT}px !important; line-height: 1.25 !important;
  /* Подпись прижата влево: кнопки стоят первыми в столбике, и левый край
     у них общий с полем выбора порога и полем поиска под ними. */
  text-align: left !important; padding-left: 8px !important;
  white-space: nowrap !important;
  overflow: hidden !important; text-overflow: ellipsis !important;
  min-width: 0 !important;
  -webkit-user-select: none !important; user-select: none !important;
  -webkit-tap-highlight-color: transparent !important;
  touch-action: manipulation !important;
  cursor: pointer !important; }
.lm-navthing_extra .lm-disco_btn.lm-on {
  background: rgb(220, 218, 218) !important;
  border-color: rgb(160, 158, 158) !important; }
.lm-navthing_extra .lm-disco_btn:active {
  background: rgb(236, 234, 234) !important; }
/* Scroll-connect без DISCO смысла не имеет: сокращённых постов нет, гнёздам
   стоять негде. Поэтому кнопка не просто ничего не делает, а выглядит
   недоступной — приглушена и не ловит нажатия. Своё состояние она при
   этом помнит: включат DISCO — вернётся нажатой. */
.lm-navthing_extra .lm-disco_btn[disabled] {
  opacity: .45 !important;
  background: rgb(255, 255, 255) !important;
  cursor: default !important; pointer-events: none !important; }
/* Сокращённый пост. position: relative — гнездо под стрелку стоит
   поверх поста и отсчитывается от него: внутрь тела его класть нельзя,
   тело обрезано и затянуто маской, и гнездо растворилось бы вместе с
   низом картинки. */
.lm-disco_post { position: relative !important; }

/* Тело: высоту задаёт скрипт замером (у каждого поста своя подпись),
   здесь только обрезка и полоса прозрачности. Маска, а не накладка
   цветом: под постом бывает и белый фон, и тёмная тема с инверсией, и
   своё оформление подлепры — маске всё равно, какого цвета то, что она
   проявляет. Задаётся обеими записями: Safari понимает только с
   приставкой, Firefox — обе. */
.lm-disco_post .dt {
  overflow: hidden !important;
  -webkit-mask-image: linear-gradient(to bottom,
    #000 calc(100% - ${CFG.discoFade}px), transparent 100%) !important;
  mask-image: linear-gradient(to bottom,
    #000 calc(100% - ${CFG.discoFade}px), transparent 100%) !important; }

/* Сокращённый комментарий. Устроен проще поста: режется ровно тело
   (.c_body), подпись рядом не трогается. Система координат для стрелки —
   сам комментарий, поэтому relative на нём, а не на теле: тело обрезано
   и затянуто маской, и стрелка внутри него растворилась бы вместе с
   нижними строчками.
   Полоса прозрачности та же и той же высоты, что у постов: два разных
   среза на одной странице не встречаются, но привыкать человек будет к
   одному виду. */
.lm-disco_comment { position: relative !important; }
.lm-disco_comment .c_body {
  overflow: hidden !important;
  -webkit-mask-image: linear-gradient(to bottom,
    #000 calc(100% - ${CFG.discoFade}px), transparent 100%) !important;
  mask-image: linear-gradient(to bottom,
    #000 calc(100% - ${CFG.discoFade}px), transparent 100%) !important; }
/* Положение стрелки такое же, как у постов, — левый край. Соблазн
   сдвинуть её на отступ ветки был, но левый край честнее: абсолютные
   координаты отсчитываются от поля комментария, то есть ДО лесенки, и
   стрелки во всём треде выстраиваются в один столбик независимо от
   глубины. Столбик находишь глазом сразу; стрелка, гуляющая по
   горизонтали вслед за ступенью, каждый раз ищется заново. */

/* Текст до первой картинки. Высота — целое число строк (её считает
   скрипт), чтобы срез не приходился на половину буквы. */
.lm-disco_post .lm-dsc_lead { overflow: hidden !important; }
/* Многоточие — своё, отдельной строкой под обрезанным текстом: у обрезки
   по высоте своего знака нет, а троеточие внутри строки пришлось бы
   врезать в чужой текст. */
.lm-disco_post .lm-dsc_dots {
  display: block !important;
  font-size: 17px !important; line-height: 1.2 !important;
  letter-spacing: 2px !important;
  opacity: .65 !important; }
/* Хвост после первой картинки прячем только тогда, когда он всё равно
   не попал бы в видимую часть: так браузер не качает картинки, которых
   не видно. Если же после обрезки текста и картинки до среза осталось
   место, хвост оставляем в потоке — пусть заполняет бюджет и режется
   общим потолком. Иначе краткопосты выходили разной высоты: у одного
   картинка доходила до среза, у другого кончалась на середине, и пост
   был на треть ниже соседа. */
.lm-disco_post .lm-dsc_hide { display: none !important; }
/* Медиа в режиме 'fit' — вписываем целиком в остаток бюджета. Высоту
   ставит скрипт, здесь только снимаем лепровские жёсткие размеры. */
.lm-disco_post .lm-dsc_fit {
  height: auto !important; width: auto !important;
  max-width: 100% !important; }

/* Метка у полосы прозрачности. Один и тот же узел в двух видах.
   Без scroll-connectа это стрелка вниз — светло-серая, как у прыгалок
   справа, с белым ореолом (иначе светлый контур теряется в строчках);
   по ней и разворачивают пост тапом.
   С scroll-connectом она становится гнездом: тот же силуэт, но заливка
   обратная (тёмная) и вокруг свечение — в него предстоит вводить
   стрелку прокруткой. */
.lm-dsc_nest {
  position: absolute !important; z-index: 4 !important;
  left: 0 !important;
  width: ${CFG.jumpSize}px !important; height: ${CFG.jumpSize}px !important;
  padding: 0 !important; margin: 0 !important;
  -webkit-appearance: none !important; appearance: none !important;
  background: none !important; border: 0 !important;
  -webkit-tap-highlight-color: transparent !important;
  touch-action: manipulation !important;
  cursor: pointer !important; }
.lm-dsc_nest svg {
  display: block !important; width: 100% !important; height: 100% !important;
  transform: rotate(180deg) !important;
  filter: drop-shadow(0 0 1px rgba(255,255,255,.95))
          drop-shadow(0 0 2px rgba(255,255,255,.8)) !important; }
/* Заливку задаём правилом, а не атрибутом фигуры: у одного узла два
   вида, и переключать их классом на <html> проще, чем перерисовывать
   значок при каждом нажатии кнопки. */
.lm-dsc_nest svg polygon { fill: ${CFG.jumpColor} !important; }
.lm-dsc_nest:active { opacity: .55 !important; }

/* Обёртка под оборот. Крутится она, а не значок и не кнопка: у значка
   свой поворот на 180 (треугольник лепры смотрит вверх), у стрелки —
   свой сдвиг на половину высоты, и всё это одним свойством transform
   не уживается — последнее объявление затирает предыдущие. */
.lm-dsc_spin {
  display: block !important; width: 100% !important; height: 100% !important; }
.lm-dock .lm-dsc_spin {
  animation: lm-dsc_turn ${CFG.discoSpin}ms ease-in-out 1 !important; }
/* Оборот с микропаузой на половине: доходит до ${180 * CFG.discoTurns}
   градусов, замирает на десятую долю времени и доворачивает. */
@keyframes lm-dsc_turn {
  0%   { transform: rotate(0deg); }
  45%  { transform: rotate(${180 * CFG.discoTurns}deg); }
  55%  { transform: rotate(${180 * CFG.discoTurns}deg); }
  100% { transform: rotate(${360 * CFG.discoTurns}deg); }
}

/* Scroll-connect: пока полоса прозрачности далеко от середины экрана, на
   экране нет ничего. Прозрачность обоих ведёт скрипт, поэтому здесь
   только исходное состояние — и запрет на нажатия: в этом режиме пост
   разворачивают стыковкой, а не тапом, и невидимая кнопка поверх поста
   только перехватывала бы касания по видео под нею. */
html.lm-sconnect .lm-dsc_nest {
  opacity: 0 !important; pointer-events: none !important; }
html.lm-sconnect .lm-dsc_nest svg polygon {
  fill: ${CFG.discoNest || 'rgb(45,44,43)'} !important; }
html.lm-sconnect .lm-dsc_nest svg {
  filter: drop-shadow(0 0 2px ${CFG.discoGlow})
          drop-shadow(0 0 5px ${CFG.discoGlow}) !important; }

/* Стрелка. Одна на всю страницу, стоит у левого края по середине
   экрана. Светло-серая с белым ореолом — та же, что у прыгалок справа;
   тап по ней ничего не делает и делать не должен, поэтому касания
   сквозь неё проходят. */
#lm-dsc_arrow {
  position: fixed !important; top: 50% !important; left: 0 !important;
  width: ${CFG.jumpSize}px !important; height: ${CFG.jumpSize}px !important;
  margin-top: -${CFG.jumpSize / 2}px !important;
  z-index: 29 !important;
  opacity: 0 !important; pointer-events: none !important; }
#lm-dsc_arrow svg {
  display: block !important; width: 100% !important; height: 100% !important;
  transform: rotate(180deg) !important;
  filter: drop-shadow(0 0 1px rgba(255,255,255,.95))
          drop-shadow(0 0 2px rgba(255,255,255,.8)) !important; }
#lm-dsc_arrow svg polygon { fill: ${CFG.jumpColor} !important; }

/* ============ ТЁМНАЯ ТЕМА ============ */
/* Инверсия с поворотом тона. Своей тёмной палитры у лепры нет, а ручная
   перекраска сотни классов рассыпалась бы на подсайтах с их стилями.
   Картинки и видео инвертируются обратно, чтобы остаться нормальными. */
html.lm-dark {
  filter: invert(1) hue-rotate(180deg) !important;
  /* Фон холста. Стояло чистое белое, которое после переворота давало
     чистый чёрный, — и по бокам страницы, ниже коробки body, открывалась
     полоса другого тона: карточки на ней выглядели обведёнными не тем
     цветом. Это и есть «рамки чернеют к концу первого экрана».
     Значение приходит переменной, которую задаёт раздел цветов тёмной
     темы: там же красятся body и обёртка, и все три обязаны совпадать. */
  background: var(--lm-dark-page, #fff) !important; }
html.lm-dark img, html.lm-dark video, html.lm-dark iframe,
html.lm-dark canvas, html.lm-dark embed, html.lm-dark object,
html.lm-dark .b-list_item_logo, html.lm-dark .b-userpic,
html.lm-dark [style*="background-image"] {
  filter: invert(1) hue-rotate(180deg) !important; }
/* Гертруды бывают двух пород. Одни — png с настоящей прозрачностью:
   рваный край сделан альфа-каналом, и под ним видно страницу. Другие —
   jpeg, где прозрачности нет вовсе и тот же рваный край нарисован по
   белому листу; лист — часть картинки, а не подложка под ней.
   На светлой теме разницы не видно: страница тоже белая. А обратная
   инверсия возвращает картинке подлинные цвета вместе с этим листом —
   и на почерневшей странице вокруг такой гертруды загорается белый
   прямоугольник.
   Вычесть белое отдельно нельзя: инверсия монотонна, она переворачивает
   либо всё, либо ничего, и «всё, кроме белого» ею не выражается.
   Смешивание тоже мимо — под элементом лежит белый фон страницы ДО
   общей инверсии, а с белым и multiply, и screen вырождаются в
   тождество.
   Поэтому непрозрачную гертруду отдаём общей инверсии: лист уходит в
   чёрный и сливается со страницей. Платим тем, что рисунок идёт
   негативом — для декоративной картинки это дешевле светящейся заплаты
   в пол-ладони. Прозрачных это не касается: у них край и так честный,
   и подлинные цвета им сохраняем.
   Класс ставит prepGertruda, когда снять кайму не удалось.
   Правило весомее
   предыдущего (три класса против одного) И стоит ниже — иначе браузер и
   проверка решили бы спор по-разному. */
html.lm-dark .lm-navthing_gert.lm-opaque img { filter: none !important; }

/* Эмодзи. Узел ставит проход fixEmoji (раздел 6.5); здесь только
   возврат цветов — тот же приём, что и у картинок строкой выше.
   Плёнка висит на html.lm-dark, поэтому в светлой теме узел ничего не
   делает и заворачивать можно всегда, не переобходя страницу при
   переключении темы.
   display оставляем строчным: эмодзи стоит посреди строки, и
   inline-block отнял бы у неё возможность перенестись по этому месту.
   Safari плёнку на строчном узле рисует — проверено на устройстве
   (если вдруг нет, лечится строкой display: inline-block). */
html.lm-dark .lm-emo {
  filter: invert(1) hue-rotate(180deg) !important; }

/* Корона у президента. Цвета у неё заданы прямо в фигурах — золото,
   синяя шапка, красные камни, — и общий переворот страницы сделал бы её
   ядовито-голубой. Возвращаем подлинные цвета тем же приёмом, что у
   картинок и эмодзи выше. Селектор один, без .lm-navthing_links: значок
   живёт только там, а лишний класс в селекторе ничего не уточняет. */
html.lm-dark .lm-crown {
  filter: invert(1) hue-rotate(180deg) !important; }

/* ============ ПОПАП НАСТРОЕК ============ */
/* Слой выше всего нашего, кроме плашки о пыни: настройки перекрывают
   страницу целиком, но сообщение о новом ответе перекрывать не должны —
   оно короткое и само уходит. */
/* Поля по бокам прежние, сверху и снизу — четыре пикселя вместо
   двенадцати. Затемнение вокруг окна и так есть, а высота здесь дороже
   воздуха: раздел «Разное» подрос, и на стопроцентном масштабе окно
   стало упираться в прокрутку. */
#lm-set {
  position: fixed !important; inset: 0 !important;
  z-index: 2147481000 !important;
  background: rgba(0, 0, 0, .45) !important;
  display: flex !important; align-items: center !important;
  justify-content: center !important;
  padding: 4px ${CFG.pageEdge}px !important;
  box-sizing: border-box !important;
  overflow: auto !important; }
.lm-set_win {
  /* Ширину задаём долей экрана, а не пикселями. Раньше стояло 380: при
     стопроцентном масштабе это ровно экран, а при 90% окно раскладки
     становится 437 — и та же цифра выглядела узкой колонкой посреди
     затемнения. Доля ведёт себя одинаково на любом масштабе. Потолок в
     520 оставлен на случай широкого экрана, где окно во всю ширину
     превратилось бы в простыню. */
  /* Потолок высоты — доля, а не 94vh, и это та же починка, что была у
     ширины. vh в Safari считается от видового окна, заданного метатегом,
     и за масштабом страницы не следует; доля считается от настоящего
     содержащего блока — то есть от затемнения, которое прибито к краям
     экрана. Заодно окно берёт всю доступную высоту вместо 94 процентов:
     вместе с сузившимися полями это те самые пол-сотни пикселей, из-за
     которых на стопроцентном масштабе появлялась прокрутка. */
  width: 100% !important; max-width: min(520px, 100%) !important;
  max-height: 100% !important; overflow: auto !important;
  box-sizing: border-box !important;
  background: rgb(245,245,245) !important;
  border: 1px solid rgb(200,200,200) !important;
  border-radius: ${UI_R + 3}px !important;
  box-shadow: 0 4px 22px rgba(0,0,0,.35) !important;
  font-family: Verdana, Arial, sans-serif !important;
  color: rgb(40,40,40) !important; }
/* Отбивка разделов. Нижние три («Уведомления», «Другое»,
   «Икспириментальное») — это строки «подпись — кнопки», и им нужно
   ровно столько высоты, сколько занимает кнопка. Прежние десять сверху
   и снизу на каждый раздел плюс шесть под заголовком набирали почти
   сотню пикселей пустоты, которую окно отнимало у верхнего раздела —
   единственного, где место действительно работает. */
.lm-set_block {
  padding: 6px ${CFG.pageEdge}px !important;
  border-bottom: 1px solid rgb(222,222,222) !important; }
/* По центру. Раздел — это подпись и под ней ряды «слева название,
   справа кнопки»; прижатый влево заголовок вставал в один столбец с
   названиями рядов и читался таким же рядом, только без кнопок.
   По центру он явно над ними, а не среди них.
   Заголовку левой колонки верхнего раздела выключка ничего не меняет:
   колонка шириной ровно в него (он самый широкий её ребёнок и стоит
   nowrap), центрировать внутри собственной ширины нечего. */
.lm-set_head {
  font-size: 12px !important; line-height: 1.25 !important;
  text-align: center !important;
  color: rgb(90,90,90) !important; margin-bottom: 3px !important; }
/* Верхнему разделу отбивку возвращаем: там три столбца, и прижимать
   схемофон к линейкам незачем. */
.lm-set_top { padding: 7px ${CFG.pageEdge}px !important; }

/* Верхний блок — три столбца: выбор, ползунок, схемофон. Именно flex, а
   не таблица: у среднего столбца ширина фиксирована поворотом ползунка,
   у правого — размером схемофона, и растягиваться должен только левый. */
/* По центру, а не по верху. Схемофон высокий, ползунок и колонка кнопок
   ниже его; при выравнивании по верху под ними оставалась пустая
   ступенька в полсотни пикселей, и раздел читался как недорисованный. */
.lm-set_top {
  display: flex !important; align-items: center !important;
  gap: 10px !important; }
/* Ползунок вплотную к схемофону: общий просвет ряда здесь лишний. */
.lm-set_mid { margin-left: -6px !important; }
/* Колонка кнопок узкая: подписи теперь короткие («медиа-контент»,
   «посты», «комментарии»), и место, которое она занимала, отдано
   схемофону — он и есть то, ради чего раздел существует. */
/* Ширину колонке не задаём — она равна самому широкому ребёнку, то есть
   заголовку. Так «Максимальная высота» гарантированно встаёт в строку,
   а кнопки под ним тянутся ровно до его края: подобранное на глаз число
   разъезжалось бы с заголовком при любой смене кегля или слов. */
.lm-set_left { flex: 0 0 auto !important; }
/* Заголовку колонки просвет больше общего: под ним сразу первая кнопка,
   и при общей тройке они читались одной строкой в две линии. Остальным
   заголовкам столько не нужно — под ними подписи, а не нажимаемое. */
.lm-set_left .lm-set_head {
  white-space: nowrap !important;
  margin-bottom: 9px !important; }
.lm-set_mid { flex: 0 0 auto !important; }
.lm-set_phone {
  flex: 1 1 auto !important; min-width: 0 !important;
  display: flex !important; flex-direction: column !important;
  align-items: center !important; justify-content: center !important; }

.lm-set_radio, .lm-set_reset, .lm-set_opt, .lm-set_switch, .lm-set_close {
  -webkit-appearance: none !important; appearance: none !important;
  font-family: Verdana, Arial, sans-serif !important;
  -webkit-tap-highlight-color: transparent !important;
  touch-action: manipulation !important;
  cursor: pointer !important; box-sizing: border-box !important; }
.lm-set_radio {
  display: block !important; width: 100% !important;
  text-align: left !important;
  margin: 0 0 5px !important; padding: 7px 9px !important;
  font-size: 13px !important; line-height: 1.2 !important;
  background: #fff !important;
  border: 1px solid rgb(205,205,205) !important;
  border-radius: ${UI_R}px !important;
  color: rgb(60,60,60) !important; }
.lm-set_radio.lm-on {
  background: rgb(220,218,218) !important;
  border-color: rgb(170,170,170) !important;
  color: rgb(20,20,20) !important; }
.lm-set_reset {
  margin-top: 4px !important; padding: 5px 10px !important;
  font-size: 11px !important;
  background: #fff !important;
  border: 1px solid rgb(205,205,205) !important;
  border-radius: ${UI_R}px !important;
  color: rgb(90,90,90) !important; }

/* Вертикальный ползунок — поворотом. Обёртка задаёт место, которое
   повёрнутый элемент занял бы в потоке: сам он после transform из
   потока не выпадает, но и размеров своих не меняет, поэтому ширина и
   высота обёртки заданы явно и накрест. */
.lm-set_spin {
  width: 34px !important; height: ${SET_PHONE_H}px !important;
  display: flex !important; align-items: center !important;
  justify-content: center !important; }
.lm-set_slider {
  width: ${SET_PHONE_H}px !important; margin: 0 !important;
  transform: rotate(90deg) !important; }

/* Ползунки. Собственный вид Safari убираем целиком — иначе ручку не
   увеличить: её размер задаётся только через псевдоэлемент, а он
   работает лишь при снятом appearance. Раз сняли — рисуем и дорожку,
   иначе от ползунка останется одна ручка на пустом месте.
   Ручка крупная (28): попасть в неё надо пальцем, а на повёрнутом
   ползунке промах ещё и уводит значение в другую сторону. */
.lm-set_slider, .lm-set_flat {
  -webkit-appearance: none !important; appearance: none !important;
  background: transparent !important;
  height: 28px !important; padding: 0 !important; }
.lm-set_slider::-webkit-slider-runnable-track,
.lm-set_flat::-webkit-slider-runnable-track {
  height: 6px !important; border-radius: 3px !important;
  background: rgb(212,212,212) !important; }
.lm-set_slider::-webkit-slider-thumb,
.lm-set_flat::-webkit-slider-thumb {
  -webkit-appearance: none !important; appearance: none !important;
  width: 28px !important; height: 28px !important;
  margin-top: -11px !important;
  border-radius: 50% !important;
  background: #fff !important;
  border: 1px solid rgb(155,155,155) !important;
  box-shadow: 0 1px 3px rgba(0,0,0,.3) !important; }
.lm-set_val {
  font-size: 11px !important; text-align: center !important;
  color: rgb(90,90,90) !important; margin-top: 4px !important; }

/* Раздел точности стоит В ДВЕ КОЛОНКИ: слева заголовок, ползунок и
   число, справа дорожка значков. Столбиком (заголовок сверху во всю
   ширину, под ним ряд) он занимал на шестнадцать пикселей больше, а
   дорожка при этом всё равно вдвое выше ползунка — то есть справа от
   неё зияло пустое место ровно той высоты, которой не хватало кнопке
   «Закрыть» внизу окна. Теперь заголовок и число живут в этом месте.
   Плата — заголовок выключен по центру своей колонки, а не всего
   раздела, и стоит чуть левее прочих. */
.lm-set_dock {
  display: flex !important; align-items: center !important;
  gap: 10px !important; }
.lm-set_dockcol {
  flex: 1 1 auto !important; min-width: 0 !important; }
/* Ползунок во всю ширину колонки. Раньше он был флекс-элементом самой
   строки и тянулся сам; теперь он в колонке блочным потоком, и ширину
   надо задать. */
.lm-set_flat {
  width: 100% !important; min-width: 0 !important;
  box-sizing: border-box !important; }
/* Своя отбивка у раздела точности: обе меньше общей. Причина в дорожке
   значков — её высота взята с запасом на самый большой допуск, и при
   обычных значениях сверху и снизу остаётся свободное поле, которое
   общая отбивка удваивала. */
.lm-set_dock_block {
  padding-top: 4px !important; padding-bottom: 2px !important; }
.lm-set_dock_block .lm-set_head { margin-bottom: 1px !important; }

/* Дорожка значков. Стрелка и гнездо в НАСТОЯЩЕМ размере, ${CFG.jumpSize}
   на ${CFG.jumpSize}, — и это не украшательство. Допуск тут показан
   расстоянием между двумя предметами, а расстояние читается только
   вместе с их размером: те же семнадцать пикселей между значками в
   сорок и между значками в двадцать четыре выглядят совершенно
   по-разному, и уменьшенная картинка врала про то, насколько точно надо
   попасть. Раз врёт — она бесполезна, ради неё раздел и заведён.

   Высота с запасом на самый большой допуск — иначе при движении
   ползунка вправо блок рос бы и раздел прыгал. А пара внутри стоит ПО
   ЦЕНТРУ: при малом допуске она иначе прижималась бы к верху, и под ней
   зияла бы пустая треть блока — так и вышло в первой сборке.
   Ширина шире значка: у гнезда есть свечение, и оно выходит за края. */
.lm-set_dockpic {
  flex: 0 0 auto !important;
  width: ${CFG.jumpSize + 16}px !important;
  /* Высота = значок плюс самый большой допуск (30, см. TUNE.discoDock).
     Ровно столько, сколько нужно самому широкому расхождению центров:
     при допуске 30 пара стоит с просветом в 10, при малом — наезжает
     друг на друга, и в обоих случаях дорожка одной высоты. */
  height: ${CFG.jumpSize + 30}px !important;
  display: flex !important; flex-direction: column !important;
  align-items: center !important; justify-content: center !important; }
.lm-set_arrow, .lm-set_nest {
  width: ${CFG.jumpSize}px !important; height: ${CFG.jumpSize}px !important;
  margin: 0 auto !important; }
.lm-set_arrow svg, .lm-set_nest svg {
  display: block !important;
  width: ${CFG.jumpSize}px !important; height: ${CFG.jumpSize}px !important; }

/* Отбивка между рядами: 3 давали строки почти впритык, и раздел из
   четырёх пунктов читался сплошным блоком. 6 разводит их настолько,
   чтобы взгляд цеплялся за пункт, и настолько мало, чтобы попап не
   вырос на лишний ряд по высоте. */
.lm-set_row {
  display: flex !important; align-items: center !important;
  gap: 8px !important; margin-bottom: 6px !important; }
.lm-set_row:last-child { margin-bottom: 0 !important; }
.lm-set_label {
  flex: 1 1 auto !important; min-width: 0 !important;
  font-size: 12px !important; color: rgb(60,60,60) !important; }
.lm-set_choice {
  flex: 0 0 auto !important; display: flex !important; gap: 4px !important; }
.lm-set_opt, .lm-set_switch {
  padding: 4px 8px !important; font-size: 11px !important;
  background: #fff !important;
  border: 1px solid rgb(205,205,205) !important;
  border-radius: ${UI_R}px !important;
  color: rgb(80,80,80) !important; }
/* Погашенный ряд: подпись и кнопки бледнее, нажатия не проходят. Сама
   выбранная кнопка подсветку сохраняет — значение-то никуда не делось,
   просто сейчас ни на что не влияет. */
.lm-set_row.lm-off { opacity: .42 !important; }
.lm-set_row.lm-off .lm-set_opt { pointer-events: none !important; }
.lm-set_opt.lm-on, .lm-set_switch.lm-on {
  background: rgb(220,218,218) !important;
  border-color: rgb(170,170,170) !important;
  color: rgb(20,20,20) !important; }

/* Отклик на нажатие. Без него кнопки попапа молчат: подсветку касания
   Safari мы у них сняли (-webkit-tap-highlight-color: transparent),
   иначе она рисовала синий прямоугольник поверх скруглений. Взамен —
   своё затемнение. Особенно нужно «сбросить»: у остальных кнопок
   результат виден сразу — подсветилась другая, сменилась надпись, — а
   сброс на заводское значение может вообще ничего не изменить, если
   человек его уже не менял, и тогда без отклика непонятно, сработало
   ли нажатие вовсе.
   Правило ниже правил выбранного состояния и тяжелее их: нажатие
   должно быть видно и на уже выбранной кнопке. */
.lm-set_radio:active, .lm-set_reset:active,
.lm-set_opt:active, .lm-set_switch:active, .lm-set_close:active {
  background: rgb(196,194,194) !important;
  border-color: rgb(150,150,150) !important;
  color: rgb(20,20,20) !important; }

/* Подвал: пять пикселей вместо семи. Кнопка «Закрыть» и так с полями в
   восемь, воздух вокруг неё берётся из них — а лишняя пара пикселей
   сверху и снизу это ровно та высота, которой кнопке не хватало, чтобы
   уместиться в окне на стопроцентном масштабе. */
.lm-set_foot {
  padding: 5px !important; text-align: center !important; }
.lm-set_close {
  padding: 8px 22px !important; font-size: 13px !important;
  background: #fff !important;
  border: 1px solid rgb(190,190,190) !important;
  border-radius: ${UI_R}px !important;
  color: rgb(40,40,40) !important; }

/* ============ ВСПЛЫВАЮЩАЯ ПОДСКАЗКА ============ */
/* Плашка одна на весь скрипт, лежит в body и позиционируется от начала
   документа (см. showHint). Появляется и уходит с переходом, но не
   исчезает из потока насовсем: display: none сбросил бы переход, а
   нулевая прозрачность с pointer-events: none и не мешает нажатиям, и
   позволяет померить ширину плашки до показа — она нужна, чтобы
   поставить подсказку по центру значка.
   Слой выше прыгалок (30) и ниже динамического списка поиска (50):
   подсказка перекрывает страницу, но не орган, ради которого страницу
   и открыли. */
#lm-hint {
  position: absolute !important;
  z-index: 40 !important;
  max-width: 240px !important;
  padding: 6px 9px !important;
  border-radius: ${UI_R}px !important;
  background: rgba(40,40,40,.92) !important;
  color: rgb(245,245,245) !important;
  font-family: Verdana, Arial, sans-serif !important;
  font-size: 12px !important; line-height: 1.3 !important;
  text-align: center !important;
  pointer-events: none !important;
  opacity: 0 !important; transition: opacity .15s !important;
  -webkit-user-select: none !important; user-select: none !important; }
#lm-hint.lm-on { opacity: 1 !important; }

/* ============ ОТЛАДОЧНАЯ ПАНЕЛЬ ============ */
#lm-debug {
  position: fixed !important; left: 0; right: 0; bottom: 0;
  max-height: 60vh; overflow: auto; z-index: 2147483647;
  padding: 8px; background: #101010; color: #6f6;
  font: 11px/1.35 monospace; white-space: pre-wrap;
  border-top: 3px solid #6f6; }
#lm-debug button { font: 13px monospace; padding: 8px 12px; margin: 0 6px 8px 0; }

/* Подпись поста в две строки. Сами строки — флекс с переносом: если
   содержимое не влезло, оно переносится внутри своей строки, а не
   перемешивается с чужой.
   flex-basis: 100% заставляет каждую занять всю ширину подписи, то есть
   встать одна под другой. Ширину именно так, а не переносом через
   вставку-распорку: распорка это лишний узел на каждый пост, а нам их
   и так по сорок три на экран ленты.
   Просвет между строками — три пикселя: строки связаны по смыслу, и
   разрывать их сильнее, чем слова внутри строки, незачем. */
.dd .ddi .lm-fline {
  display: flex !important; flex-wrap: wrap !important;
  align-items: center !important;
  flex: 1 1 100% !important;
  gap: 2px 6px !important;
  min-width: 0 !important; }
.dd .ddi .lm-fline__2 { margin-top: 3px !important; }

/* То же для подписи комментария. Селектор отдельный, потому что строки
   там висят прямо на .c_footer, а не внутри .ddi. */
.comment .c_footer .lm-fline {
  display: flex !important; flex-wrap: wrap !important;
  align-items: center !important;
  flex: 1 1 100% !important;
  gap: 2px 6px !important;
  /* Своя высота строки, а не унаследованные 1.4 от подвала: во второй
     строке стоит голосовалка ростом 28, и полуторный интервал добавлял
     к нему ещё воздуха сверху и снизу. Единица прижимает строку к
     содержимому, а разводит их margin — величина, которую видно. */
  line-height: 1.15 !important;
  min-width: 0 !important; }
.comment .c_footer .lm-fline__2 { margin-top: 1px !important; }

/* Название подлепры во второй строке. Рамку рисует сама лепра
   (.b-post_domain: рамка в пиксель, скругление 3, поля по два) —
   трогать её незачем, но нужно не дать ссылке сжаться при переносе и
   выровнять её по высоте с голосовалкой рядом: у голосовалки 28
   пикселей, и ссылка в 15 висела бы у её верхнего края. */
.dd .ddi .lm-fline__2 a.b-post_domain {
  flex: 0 0 auto !important;
  display: inline-flex !important; align-items: center !important;
  height: 20px !important; padding: 0 5px !important;
  white-space: nowrap !important; }

/* ============ ОБРАТНЫЙ НАБОР ТОНОВ ============
   Светлые карточки на притемнённой странице. Перекрашиваем ровно два
   места: фон страницы и фон карточки. Всё остальное — рамка, подложка
   подписи, растушёвка — держится на прозрачности и подстраивается само.
   Ради этого подложка и задана плёнкой, а не готовым цветом.

   Страницу красим по двум узлам сразу: у лепры белый висит и на body, и
   на .l-i-wrapper, а второй закрывает первый на всю высоту содержимого.
   Покрасить только body значило бы получить нужный тон лишь на полях.

   Раздел внизу файла: правила фона карточки объявлены выше, и здешние
   обязаны их перебивать. */
html.lm-cards2 body,
html.lm-cards2 .l-i-wrapper { background: ${PAGE_ALT} !important; }
html.lm-cards2 .post {
  background-color: ${CARD_ALT} !important;
  background-image: ${CARD_GLOW2} !important; }
/* Карточка подлепры — тем же набором и по тем же причинам, что и пост.
   Отдельным правилом, а не приписыванием селектора к .post: у постов
   ниже есть свои продолжения (рамка комментария, подсветка новых), и
   общий селектор пришлось бы таскать по всем ним. Вес (три класса)
   тяжелее базового правила карточки (два), и стоит оно ниже по файлу —
   спор решается одинаково и в браузере, и в проверке. */
html.lm-cards2 .b-blogs_list .b-list_item,
html.lm-cards2 .l-content_aside_subscriptions_top .b-subscriptions_aside_block {
  background-color: ${CARD_ALT} !important;
  background-image: ${CARD_GLOW2} !important; }
/* Без !important, ровно по той же причине, что и основной фон
   комментария: леприну подсветку новых перебивать нельзя.

   И селектор нарочно короткий — .c_i вместо .comment .c_i. Отказ от
   !important сам по себе не спас: с двумя классами наше правило весило
   ровно столько же, сколько лепровское правило подсветки из трёх
   классов, а при
   равном весе побеждает то, что ниже по файлу, — то есть наше. Подсветка
   новых комментариев в обратном наборе пропадала, в заводском работала,
   и разница была именно в этом лишнем классе.
   Теперь у нас два веса против трёх лепровских: обычный комментарий
   красим мы (наш селектор всё ещё тяжелее основного правила карточки),
   новый — лепра. Свечение поверх прозрачное и подсветку не закрывает. */
html.lm-cards2 .c_i {
  background-color: ${CARD_ALT};
  background-image: ${CARD_GLOW2} !important; }

/* Рамку вокруг комментария в обратном наборе снимаем. Она рассчитана
   на карточку темнее страницы: там линия отделяет светлое от тёмного.
   Здесь карточка светлее фона и отделяется сама, а линия остаётся
   лишней — да ещё её верх подъедает белая растушёвка подписи, и выходит
   неряшливо. У поста рамка остаётся: он крупный, и без неё край
   теряется.
   border-width, а не border: цвет и скругление пусть лежат в одном
   месте, на случай если рамку когда-нибудь вернут. */
html.lm-cards2 .comment .c_i::before { border-width: 0 !important; }

/* Контраст органов управления в обратном наборе. Причина и способ
   расчёта — рядом с ALT_ON_BG.

   :not(.lm-dark) обязателен. Обратный набор сочетается с тёмной темой
   (есть отдельные правила html.lm-dark.lm-cards2), и там страница уже
   не 231, а почти чёрная; свои тона у тёмной темы посчитаны отдельно, и
   здешние их только испортили бы.

   Правила стоят НИЖЕ исходных и тяжелее их ровно на один класс (html.
   lm-cards2 против голого .lm-navthing_extra …), так что спор решается
   одинаково и по весу, и по порядку. */
html.lm-cards2:not(.lm-dark) .lm-navthing_extra .lm-disco_btn {
  border-color: ${ALT_EDGE} !important; }
html.lm-cards2:not(.lm-dark) .lm-navthing_extra .lm-disco_btn.lm-on {
  background: ${ALT_ON_BG} !important;
  border-color: ${ALT_ON_EDGE} !important; }
html.lm-cards2:not(.lm-dark) .lm-navthing_extra .lm-disco_mode.lm-on,
html.lm-cards2:not(.lm-dark) .lm-navthing_extra
  .b-slider_scale_icon.js-feed_type_active {
  background: ${ALT_ON_BG} !important; }

/* Значки прыгалок и стрелка стыковки. Заливка задана фигурам атрибутом
   (её ставит svgNode из CFG.jumpColor), поэтому перекрываем правилом —
   иначе пришлось бы перерисовывать значки при переключении схемы. Тот
   же приём, что и в тёмной теме.
   Глаз маски (ellipse, красный) не трогаем: он и на притемнённой
   странице виден, а перекрашенный перестал бы быть глазом. */
html.lm-cards2:not(.lm-dark) #lm-nav svg polygon,
html.lm-cards2:not(.lm-dark) #lm-dsc_arrow svg polygon {
  fill: ${ALT_JUMP} !important; }


/* Звёздочки «золотого» поста. У лепры это спрайт 52 на 12 — пять
   мелких звёзд в ряд, отрезок общей картинки sprite.png. Пять штук в
   подписи занимают места больше, чем счётчик комментариев, а говорят
   ровно одно: пост золотой. Меняем на одну, покрупнее.

   Рисуем символом ★ (U+2605), а не картинкой: у него, в отличие от
   многих значков, нет эмодзи-начертания — iOS показывает именно знак, а
   не цветную наклейку. Спрайт при этом гасим полностью, вместе с
   размерами: они заданы под пять звёзд.
   Цвет приглушённо-золотой, в тон тёплой палитры карточки; лепровский
   спрайт ярче, но рядом с бледной подписью он кричал бы.
   Подсказка со счётом голосов остаётся — она в атрибуте title. */
.stars {
  width: auto !important; height: auto !important;
  top: 0 !important; margin: 0 !important;
  background: none !important;
  font-size: 15px !important; line-height: 1 !important;
  color: rgb(206,164,58) !important; }
/* Знак вписан прямо, а не escape-последовательностью: таблица стилей
   собирается шаблонной строкой JavaScript, и запись знака кодом со
   слэшем она
   разберёт как восьмеричную — синтаксическая ошибка на весь файл. */
.stars::before { content: '★'; }

/* ============ ПОДПИСЬ: ЗНАЧКИ ПОД ТОЧКОЙ ============
   Подпись всегда краткая: «Написал звание имя, вчера в 13.26», рядом
   голосовалка и счётчик комментариев, всё прочее — под точкой.

   Некоторое время это было настройкой с полным видом на выбор. Настройки
   не стало: полный вид не выиграл ни в одном случае, а две ветки
   оформления стоили вдвое дороже в поддержке.

   Раздел стоит внизу файла по той же причине, что и голосовалки:
   правила подписей разбросаны по разделам «Лента и посты» и
   «Комментарии», и эти обязаны перебивать оба. Внизу вес селектора и
   порядок объявления работают в одну сторону. */

/* Точка. Кружок рисуем псевдоэлементом, а не символом «•»: символ в
   разных шрифтах сидит на разной высоте, и центрировать его пришлось бы
   подбором — та же история, что со знаками голосовалки.
   Площадь нажатия 26 на 26, как у кнопок голосования. */
.lm-more_box {
  display: inline-flex !important; align-items: center !important;
  position: relative !important; }
.lm-more {
  display: inline-flex !important;
  align-items: center !important; justify-content: center !important;
  position: relative !important;
  width: 26px !important; height: 26px !important;
  padding: 0 !important; margin: 0 !important;
  -webkit-appearance: none !important; appearance: none !important;
  background: none !important; border: 0 !important;
  font-size: 0 !important; cursor: pointer !important;
  -webkit-tap-highlight-color: transparent !important; }
.lm-more::before {
  content: '' !important; position: absolute !important;
  left: 50% !important; top: 50% !important;
  width: 4px !important; height: 4px !important;
  margin: -2px 0 0 -2px !important;
  background: rgb(120,120,120) !important;
  border-radius: 50% !important; }
/* Нажатая точка обводится — иначе непонятно, откуда всплыл столбик. */
.lm-more_box.lm-on .lm-more::before {
  box-shadow: 0 0 0 4px rgba(120,120,120,.25) !important; }

/* Столбик всплывает ВВЕРХ от точки, а не вниз: подпись стоит внизу
   поста, и раскрытый вниз столбик уехал бы под следующий.
   z-index выше ленты, но ниже наших слоёв: столбик перекрывает соседние
   посты, а попап настроек и окно пыни перекрывают его. */
.lm-more_box .lm-icons { display: none !important; }
.lm-more_box.lm-on .lm-icons {
  display: flex !important; flex-direction: column !important;
  align-items: stretch !important;
  position: absolute !important;
  left: 50% !important; bottom: 24px !important;
  transform: translateX(-50%) !important;
  z-index: 28 !important;
  gap: 0 !important; height: auto !important; width: auto !important;
  padding: 4px !important; margin: 0 !important;
  background: rgb(250,250,250) !important;
  border: 1px solid rgb(214,212,212) !important;
  border-radius: 6px !important;
  box-shadow: 0 2px 8px rgba(0,0,0,.18) !important; }

/* Значки внутри столбика. Списков селекторов тут три, и это не
   перестраховка, а расчёт: в строке подписи значки размечены разными
   правилами с разным весом — у поста .dd .lm-icons с парой :not(),
   у комментария правила с идентификатором #js-comments_holder .c_footer.
   Одно короткое правило проиграло бы обоим, и значки в столбике
   остались бы каждый со своей высотой и своим отступом — ровно то, что
   видно на снимках: столбик в три этажа с провалами между значками.
   Приписываем к каждому конкуренту свой селектор потяжелее.

   Коробка одна на все значки — 34 на 34 с флекс-центрированием внутри.
   Центрирование, а не выравнивание по строке: часть значков это svg,
   часть — текстовые глифы (крестик, звёздочка), часть — фоновая
   картинка. По базовой линии они не совпадут никогда, по центру коробки
   совпадают всегда. */
.lm-more_box.lm-on .lm-icons > *,
html .dd .lm-more_box.lm-on .lm-icons > *,
html #js-comments_holder .lm-more_box.lm-on .lm-icons > * {
  display: flex !important;
  align-items: center !important; justify-content: center !important;
  box-sizing: border-box !important;
  width: 34px !important; height: 34px !important;
  min-width: 0 !important; min-height: 0 !important;
  max-height: none !important;
  padding: 0 !important; margin: 0 !important;
  position: static !important; inset: auto !important;
  top: auto !important; bottom: auto !important;
  float: none !important; transform: none !important;
  line-height: 1 !important; font-size: 15px !important;
  text-align: center !important; text-decoration: none !important;
  vertical-align: middle !important;
  background-position: center center !important;
  background-repeat: no-repeat !important; }

/* Неактивные значки. Лепра держит в подписи обе половины каждой пары —
   «в мои вещи» и «из моих вещей», «в избранное» и «из избранного», — и
   гасит ненужную классом hidden. В строке это скрытие уже прописано, но
   правило столбика выше оказалось тяжелее и вернуло погашенное на
   экран: в столбике из трёх значков стало семь, причём парами
   противоположных по смыслу.
   Поэтому гасим отдельно и тяжелее — с .lm-on в селекторе, чтобы быть
   заведомо весомее правила размеров. Справочный вопросик тем же
   правилом: на телефоне он бесполезен и в строке уже скрыт. */
.lm-more_box.lm-on .lm-icons > .hidden,
.lm-more_box.lm-on .lm-icons > .b-post_interest_info,
html .dd .lm-more_box.lm-on .lm-icons > .hidden,
html .dd .lm-more_box.lm-on .lm-icons > .b-post_interest_info,
html #js-comments_holder .lm-more_box.lm-on .lm-icons > .hidden,
html #js-comments_holder .lm-more_box.lm-on .lm-icons > .b-post_interest_info {
  display: none !important; }

/* Обёртки внутри значка (у лепры их бывает две-три: .b-button,
   .b-button_icon, .b-svg-icon) тоже растягиваем и центрируем, иначе
   рисунок сидит в углу своей обёртки, а обёртка — по центру коробки. */
.lm-more_box.lm-on .lm-icons > * > *,
html .dd .lm-more_box.lm-on .lm-icons > * > *,
html #js-comments_holder .lm-more_box.lm-on .lm-icons > * > * {
  display: flex !important;
  align-items: center !important; justify-content: center !important;
  position: static !important; inset: auto !important;
  top: auto !important; margin: 0 !important; padding: 0 !important;
  width: auto !important; height: auto !important;
  line-height: 1 !important; }

.lm-more_box.lm-on .lm-icons svg,
html .dd .lm-more_box.lm-on .lm-icons svg,
html #js-comments_holder .lm-more_box.lm-on .lm-icons svg {
  display: block !important;
  width: 18px !important; height: 18px !important; }

/* Пустые обёртки под фоновые спрайты лепры рисуют в столбике мелкие
   чёрточки — в строке они уже скрыты, здесь скрываем отдельно: селектор
   строки к столбику не подходит. */
.lm-more_box.lm-on .lm-icons em:empty,
.lm-more_box.lm-on .lm-icons span:empty:not([class]) { display: none !important; }

/* «Ответить» значком. Площадь нажатия как у кнопок голосования, сам
   значок крупный — 20 при 26 площади: по нему целятся чаще, чем по
   чему-либо ещё в подписи, и мелкий тут был бы издевательством.
   Цвет берётся от подписи (в svg стоит currentColor), поэтому в тёмной
   теме отдельного правила не нужно. */
.comment .c_footer .c_answer.lm-reply,
#js-comments_holder .c_footer .c_answer.lm-reply {
  display: inline-flex !important;
  align-items: center !important; justify-content: center !important;
  width: 26px !important; height: 26px !important;
  min-width: 0 !important; padding: 0 !important; margin: 0 !important;
  font-size: 0 !important; line-height: 1 !important;
  color: rgb(102,102,102) !important;
  text-decoration: none !important;
  -webkit-tap-highlight-color: transparent !important; }
.comment .c_footer .c_answer.lm-reply svg,
#js-comments_holder .c_footer .c_answer.lm-reply svg {
  display: block !important;
  width: 20px !important; height: 20px !important;
  /* Подъём на два пикселя — поправка оптическая, а не геометрическая.
     Коробка значка отцентрирована по строке верно, но рисунок в ней
     несимметричен: остриё стрелки на середине, а крючок уходит вниз, и
     вся масса чернил оказывается ниже центра. Глаз ловит массу, а не
     геометрию, — отсюда ощущение, что значок просел относительно даты.
     Двигаем сам рисунок, не коробку: площадь нажатия должна остаться на
     общей линии со своими соседями. */
  position: relative !important; top: -2px !important; }

/* Точка в подписи комментария, наоборот, опускается на два пикселя.
     Причина зеркальная: у строки цифр под базовой линией остаётся
     пустое место выносных элементов, чернила сидят выше середины
     строки, и математически отцентрированная точка читается задранной.
     Поправка только в подписи комментария: в подписи поста точка стоит
     во второй строке рядом с голосовалкой, а не с текстом, и равняться
     ей нужно по знакам кнопок — там центр как раз геометрический. */
.comment .c_footer .lm-more::before,
#js-comments_holder .c_footer .lm-more::before {
  margin-top: 0 !important; }

/* Декоративная точка лепры: в подписи поста скрыта давно, в подписи
   комментария оставалась. Рядом с нашей точкой-кнопкой две точки подряд
   читаются как одна сломанная — убираем. */
.comment .c_footer .c_show_user,
#js-comments_holder .c_footer .c_show_user { display: none !important; }
/* (Из общего правила метрик выше .c_show_user убран: приводить к общей
   высоте узел, которого не видно, незачем, а второе упоминание того же
   селектора — это дубль, который проверка перед выдачей ловит.) */

/* Шеврон сворачивания ветки в краткой подписи лишний — по просьбе.
   Значок-странички у поста и у комментария уехал в обойму ещё при
   сборке, отдельно прятать его не надо. */
.comment .c_footer .b-comment_thread_collapse { display: none !important; }

/* Липкая навигационная планка.

   Смысл всей этой правки: НИЧЕГО не анимировать. Когда палец ведёт
   страницу вверх, происходят четыре разных движения — уезжают строки
   шапки, уезжает раскрытая панель, подтягивается лента, а потом
   страница едет дальше по инерции. У каждого свой ход и своё время
   остановки. Любая попытка изобразить это переходами обречена: переход
   отыгрывает заданные ему миллисекунды и с пальцем совпасть не может.
   Три захода на такую подделку и дали ту дёрганость, от которой мы
   уходили.

   Всё это браузер делает сам, бесплатно и в точности за пальцем, если
   просто правильно расставить липкости. Каждое из четырёх движений —
   обычная прокрутка обычного потока:

     1. Строки шапки (ссылки, счётчики, приглашение) лежат в потоке и
        уезжают под липкое приветствие. Оно непрозрачно и выше по слою —
        они скрываются за ним и упираются в него.
     2. Раскрытая панель лежит в потоке НИЖЕ полоски, а полоска липкая.
        Панель уезжает вверх и проходит ЗА полоской: та позиционирована,
        то есть рисуется поверх обычного потока. Упирается панель ровно
        в полоску.
     3. Лента идёт следом за панелью, с естественным отставанием в её
        высоту, и тоже упирается в полоску.
     4. Дальше едет вся страница — это уже просто прокрутка.

   Липкой стала ПОЛОСКА, а не весь блок. В этом всё отличие от прежнего
   захода: пока липким был блок целиком, панель прилипала вместе с ним и
   уехать не могла — приходилось увозить её вручную, чем мы и мучились.

   display: contents на самом блоке — не украшение. Липкий элемент
   держится в пределах родителя, а родитель полоски — блок навштуки,
   высотой в полоску плюс панель: полоска отлипла бы, едва панель
   уедет. Свойство убирает у блока собственную коробку, и родителем для
   полоски становится контейнер страницы — высокий. Побочно исчезают
   поля блока, поэтому отбивка снизу перенесена на панель.

   Оговорка про профиль: там в контейнере лежит одна шапка, а карточка
   гражданина висит соседом выше. Полоска отлипнет, едва уедет шапка.
   Разобрано в комментарии у buildNavthing. */
html.lm-navstick #lm-navthing { display: contents !important; }

html.lm-navstick #lm-navthing .lm-navthing_row {
  position: -webkit-sticky !important; position: sticky !important;
  top: var(--lm-topbar-h, 44px) !important;
  z-index: 29 !important; }

/* От кромки до кромки — но только на прокрутке.

   Полоса во всю ширину нужна прилипшей: без неё по бокам остаются
   светлые полосы в ширину полей страницы, и содержимое едет ровно в
   них. А в покое полоска — часть страницы и обязана стоять в общей
   колонке, как все. Раньше поля стояли безусловно, и в момент включения
   настройки полоска прыгала на двенадцать пикселей влево, никуда не
   уезжая.

   Признак — тот же lm-stuck, что и у приветствия: он включается с
   первым же пикселем прокрутки, то есть полоска расширяется в начале
   движения, а не посреди него. Отступы растут ровно на столько,
   насколько уходят поля, — содержимое полоски не сдвигается. */
html.lm-stuck.lm-navstick #lm-navthing .lm-navthing_row {
  /* Ширина считается явно, и к этому пришлось идти через две ошибки.

     В общем правиле у полоски width: 100% — ширина берётся от родителя
     и от полей не зависит вовсе: левое поле просто сдвигает коробку
     влево, правое добавляет пустоты справа. Отсюда смещение вместо
     растяжения.

     width: auto тоже не годится: родитель полоски — флекс-контейнер
     лепры, а во флексе auto означает «по содержимому», то есть полоска
     сжималась до текста и переносилась в две строки.

     Остаётся посчитать: сто процентов плюс оба поля страницы. С
     box-sizing: border-box отступы входят внутрь, так что полоска ровно
     дотягивается до кромок экрана и ни на пиксель дальше. */
  width: calc(100% + ${2 * CFG.pageEdge}px) !important;
  margin-left: -${CFG.pageEdge}px !important;
  margin-right: -${CFG.pageEdge}px !important;
  padding-left: ${8 + CFG.pageEdge}px !important;
  padding-right: ${8 + CFG.pageEdge}px !important; }

/* Щуп нулевой высоты перед полоской: по нему видно, прилипла ли она.
   Не display: none — скрытый узел наблюдателю не виден вовсе. */
#lm-navthing_probe { height: 0 !important; margin: 0 !important; }

/* Заглушка над прилипшей полоской.

   На быстрой прокрутке телефон обновляет положение липких элементов не
   каждый кадр. Полоска на мгновение уезжает вверх вместе со страницей,
   под приветствие, и в этот миг на её месте показывается то, что лежит
   ниже, — низ раскрытой панели. Выглядит как выброс из-под планки.

   Закрыть это перекраской нельзя: панель честно лежит ниже полоски, и
   никакой порядок слоёв не поможет, когда сама полоска сместилась.
   Поэтому вешаем над полоской непроницаемую полосу в цвет страницы:
   уехать на её высоту полоска теперь может незаметно.

   Появляется заглушка только когда полоска прилипла: до этого над ней
   стоит нижняя строка шапки, и полоса в цвет страницы закрыла бы её
   собой. Момент ловит щуп.

   Высота с большим запасом, и это ничего не стоит: заглушка целиком
   лежит под приветствием, а оно выше по слою и непрозрачно. Двадцати
   четырёх не хватало — на быстрой прокрутке телефон успевает прилепить
   полоску чуть не доехав до места, и промах бывает больше. */
html.lm-navpin #lm-navthing .lm-navthing_row::before {
  content: '' !important; position: absolute !important;
  left: 0 !important; right: 0 !important;
  bottom: 100% !important; height: 320px !important;
  background: rgb(255,255,255) !important;
  pointer-events: none !important; }
html.lm-cards2.lm-navpin #lm-navthing .lm-navthing_row::before {
  background: ${PAGE_ALT} !important; }

/* Уехавшая под полоску панель показывается свёрнутой: шеврон обязан
   говорить правду о том, что будет по нажатию. */
#lm-navthing.lm-navthing__open.lm-navthing__past .lm-navthing_arrow::before {
  content: '▾' !important; }

/* Панель, вызванная посреди ленты. Выпадает из-под прилипшей полоски
   поверх содержимого — прокручивать страницу наверх ради неё было бы
   грубо, человек читает здесь.

   position: fixed, а не absolute: absolute считался бы от навштуки, а
   та осталась наверху документа. Отсчёт от края экрана — единственный,
   который в этом положении что-то значит.

   Слой 28 — ниже полоски (29) и приветствия (30), выше содержимого:
   панель выпадает ИЗ-ПОД полоски, а не поверх неё.

   Тень снизу, потому что панель висит над лентой и без неё непонятно,
   где она кончается. В обычном положении тени нет: там панель часть
   страницы, а не всплывшее окно. */
html.lm-navstick #lm-navthing.lm-navthing__drop .lm-navthing_body {
  position: fixed !important;
  top: calc(var(--lm-topbar-h, 44px) + var(--lm-navrow-h, 28px)) !important;
  left: 0 !important; right: 0 !important;
  z-index: 28 !important;
  max-height: none !important; margin: 0 !important;
  background: rgb(255,255,255) !important;
  box-shadow: 0 6px 14px rgba(0,0,0,.16) !important; }
html.lm-cards2.lm-navstick #lm-navthing.lm-navthing__drop .lm-navthing_body {
  background: ${PAGE_ALT} !important; }

/* Панель остаётся в потоке и своей липкости не имеет — уезжает сама,
   вместе со страницей. Слоя ей тоже не задаём: непозиционированный
   элемент рисуется ниже позиционированной полоски, что нам и нужно.
   Отбивка снизу — та, что была у блока: display: contents отобрал у
   него коробку вместе с полями. */
html.lm-navstick #lm-navthing .lm-navthing_body {
  margin-bottom: 10px !important; }

/* Раздел про липкую навштуку стоит здесь, а не рядом с плашкой вокатива,
   и это не вкусовщина. Собственные правила навштуки (её поля, отступы
   полоски) объявлены гораздо ниже плашки, и лежи эти правила там же,
   вышло бы обычное расхождение: по весу селектора побеждали бы наши, а
   по порядку — её. Браузер показал бы одно, проверка другое, и поймать
   такое можно только вручную. Внизу оба фактора работают в одну сторону.

============ ГОЛОСОВАЛКИ: НАБОРЫ ОФОРМЛЕНИЯ ============
   Самым последним в файле, и это не вкусовщина. Правила голосования
   разбросаны по трём разделам: кнопки и счётчик — в «Голосовании»,
   карма — в «Профиле», ниже. Набор обязан перебивать оба, а он тяжелее
   их по весу селектора; поставь его в середину — и по весу победит он,
   а по порядку (как считает jsdom) местами карма. Внизу оба фактора
   работают в одну сторону, и проверка показывает то же, что телефон.
   Устройство наборов — у voteRules. */
${voteRules()}

/* ============ ТЁМНАЯ ТЕМА: ЦВЕТА ОРГАНОВ ============
   Собирается кодом, устройство и числа — у darkRules. Стоит самым
   последним: обязана перебивать и общие правила, и наборы голосовалок,
   и оба набора тонов карточек. */
${darkRules()}

/* ============ НОВЫЙ КОММЕНТАРИЙ: БЕЗ СВЕЧЕНИЯ ============
   Лепра подсвечивает новые комментарии заливкой карточки — в её
   настройках это «серым фоном», rgb(247,247,247). Наша карточка
   rgb(250,249,246), то есть разница в три единицы: подсветку не видно
   вовсе. В обратном наборе карточка 253, разница шесть — тоже почти
   ничего.

   Красить новые сами мы не можем: заливка на .c_i намеренно оставлена
   без !important, чтобы леприна подсветка побеждала (см. долгий
   комментарий там же), и подменять её значило бы отобрать у человека
   выбор из четырёх вариантов в настройках сайта.

   Поэтому отличаем не цветом, а рисунком: у нового комментария гасим
   свечение. Обычная карточка идёт от светлого в середине к тёплому по
   краям, новая остаётся ровной — «плоская среди светящихся». Разница
   заметна при любом наборе тонов и при любой из четырёх подсветок,
   включая «никак».

   Селектор нарочно тяжёлый и стоит в самом конце файла. Перебить нужно
   четыре объявления свечения сразу: заводское на .comment .c_i,
   обратного набора на html.lm-cards2 .c_i, тёмной темы и её же в
   обратном наборе (html.lm-dark.lm-cards2 .c_i — три класса при
   элементе). Здесь четыре класса при элементе, то есть тяжелее каждого
   из них, И ниже всех по файлу: браузер решит спор по весу, jsdom по
   порядку, и решат одинаково.

   Гасим только рисунок, не заливку: цвет по-прежнему выбирает лепра. */
html .comments .comment.new .c_i {
  background-image: none !important; }
`;

  function injectCss() {
    if (document.getElementById('lepra-mobile-css')) return;
    var s = document.createElement('style');
    s.id = 'lepra-mobile-css';
    s.textContent = css;
    (document.head || document.documentElement).appendChild(s);
  }

  injectCss();
  document.addEventListener('DOMContentLoaded', injectCss);

  /* ============================================================
     3. ПОЧИНКА ПЕРЕПОЛНЕНИЯ
     Отлавливает то, что не попало в правила по имени: чужие стили
     подсайтов, редкие страницы, будущие изменения вёрстки.
     ============================================================ */

  /* .plupload — невидимый слой загрузчика файлов: контейнер с opacity:0 и
     полем input внутри, у которого font-size 999px, чтобы палец попадал
     куда угодно. Он честно вылезает за экран и накладывается на область
     перетаскивания, но увидеть его нельзя, а в отчёте он занимал место
     настоящих поломок. */
  var SKIP = 'svg,path,polygon,em,i,.comment,.b-svg-icon,#lm-debug,#lm-debug *,' +
             '.plupload,.plupload *';

  function scanOverflow(rescanAll) {
    var W = document.documentElement.clientWidth, out = [];

    walk(root(), isBulk, function (el) {
      if (!rescanAll && seen.scan.has(el)) return;
      seen.scan.add(el);
      if (el.matches && el.matches(SKIP)) return;
      var r = el.getBoundingClientRect();
      if (!r.width || !r.height) return;
      if (r.left >= -2 && r.right <= W + 2) return;
      var cs = getComputedStyle(el);
      if (cs.position === 'fixed' || cs.visibility === 'hidden') return;
      out.push({ el: el, cs: cs, r: r });
    }, CFG.scanBudget);

    return out;
  }

  function fixOverflow() {
    var W = document.documentElement.clientWidth;
    scanOverflow(false).forEach(function (b) {
      var el = b.el, cs = b.cs;
      /* Окно голосов правит fitVotesPopup — по замеру и сдвигом. Общий
         починщик поставил бы ему max-width:100% от .b-user_karma, а это
         полсотни пикселей: окно сплющилось бы в столбик. В отчёт оно
         при этом попадает как обычно — регрессию видно будет. */
      if (el.closest && el.closest('.b-votes_popup')) return;
      /* Поле поиска в шапке — тоже наше хозяйство. На время ввода оно
         раздвигается влево отрицательным полем формы, а это ровно то,
         что общий починщик считает поломкой: он ставит форме
         max-width: 100%, то есть прижимает её к ширине родителя — и
         раздвижка перестаёт работать. Спорить с ним из таблицы стилей
         нельзя: инлайновое !important перебить нечем.
         Поймалось не сразу: в навигационной штуке форма занимает всю
         колонку и под починщика не попадает, а на страницах с вкладками
         она стоит в конце строки ссылок узким хвостом — там и попала.
         В отчёт форма при этом ходит как раньше: если она однажды
         вылезет за экран по-настоящему, это будет видно. */
      if (el.closest && el.closest('.b-header_search, #js-header_search_form')) return;
      el.style.setProperty('max-width', '100%', 'important');
      el.style.setProperty('box-sizing', 'border-box', 'important');
      if (parseFloat(cs.paddingRight) > 40)
        el.style.setProperty('padding-right', '8px', 'important');
      if (parseFloat(cs.paddingLeft) > 40)
        el.style.setProperty('padding-left', '8px', 'important');
      if (parseFloat(cs.marginLeft) < 0)
        el.style.setProperty('margin-left', '0', 'important');
      if (parseFloat(cs.marginRight) < 0)
        el.style.setProperty('margin-right', '0', 'important');
      if (cs.position === 'absolute' && b.r.left < -2)
        el.style.setProperty('left', '0', 'important');
      /* Элементы, которым ширину задал сам скрипт (поле поиска, поля
         выбора в панели фильтров), не трогаем: иначе этот проход
         возвращал бы им исходную длину. */
      if (b.r.width > W && !el.dataset.lmWidth)
        el.style.setProperty('width', 'auto', 'important');
    });
  }

  /* Широкие плавающие колонки. У подсайтов свои таблицы стилей со своими
     !important, поэтому правим инлайном — его из CSS не перебить. */
  var ASIDE_SEL = '.b-subdomain_aside_right, .b-subdomain_aside_subscribe, ' +
                  '.b-subdomain_aside_subscribe_additional, ' +
                  '.b-subscribe_button, .l-content_aside, .b-tags, ' +
                  /* внутри свёрнутого пенсне ширина нулевая, и мерить
                     описание бесполезно — снимаем обтекание безусловно */
                  '.b-domain_description';

  function unfloatWide() {
    var W = document.documentElement.clientWidth;
    /* Пока раскладки нет, ширина всех элементов нулевая, а ноль проходит
       проверку «меньше 40% экрана» ровно наоборот — сравнение с нулевым
       порогом истинно, и обтекание снималось со всего подряд, включая
       узкие блоки, которым оно нужно. Мерить до раскладки нечего. */
    if (!W) return;
    var host = root();

    var force = function (el) {
      el.style.setProperty('float', 'none', 'important');
      el.style.setProperty('width', 'auto', 'important');
      el.style.setProperty('max-width', '100%', 'important');
      el.style.setProperty('margin-left', '0', 'important');
      el.style.setProperty('margin-right', '0', 'important');
    };

    host.querySelectorAll(ASIDE_SEL).forEach(function (el) {
      if (seen.unfloat.has(el)) return;
      seen.unfloat.add(el);
      force(el);
    });

    /* Любая чужая колонка шире 40% экрана. Внутрь комментариев не заходим
       и каждый просмотренный элемент помечаем: иначе следующий проход
       заново считает стили всего документа. */
    walk(host, isBulk, function (el) {
      if (seen.unfloat.has(el)) return;
      if (!/^(DIV|ASIDE|SECTION|UL)$/.test(el.tagName)) return;
      seen.unfloat.add(el);
      var cs = getComputedStyle(el);
      if (cs.cssFloat === 'none') return;
      if (el.getBoundingClientRect().width < W * 0.4) return;
      force(el);
    }, CFG.scanBudget);
  }

  /* Заметка в профиле: inline-block с flex-grow внутри флекса получал
     нулевую ширину и переносился по одной букве. Кто именно режет ширину,
     из CSS не видно, поэтому правим инлайном по цепочке предков.
     Заодно снимаем боковые отступы: ширину они не задают, но сдвигают
     текст к середине экрана. */

  /* Пустую заметку лепра заполняет подсказкой «Место для заметок. Заметки
     могут быть видны всем гражданам.» — на телефоне это четыре строки ради
     одной мысли. Оставляем первое предложение.
     Полный текст возвращаем на место при первом же касании: лепра узнаёт
     подсказку по совпадению строки и очищает поле перед вводом. Не вернём —
     сокращённая фраза уедет в заметку как её содержимое. */
  var NOTE_HINT = 'Место для заметок';
  var NOTE_HINT_RE = /^Место для заметок\.\s*Заметки могут быть видны/i;

  function noteEl() { return document.querySelector('#js-usernote, .b-user_note'); }

  function noteText(el) {
    return (el.textContent || '').replace(/\u00a0/g, ' ').replace(/\s+/g, ' ').trim();
  }

  function shortenNoteHint(el) {
    if (!el || !NOTE_HINT_RE.test(noteText(el))) return;   /* своя заметка — не трогаем */
    el.dataset.lmHint = el.textContent;                    /* исходная строка, до буквы */
    el.textContent = NOTE_HINT;
  }

  function restoreNoteHint(el) {
    if (!el || !el.dataset.lmHint) return;
    if (noteText(el) !== NOTE_HINT) return;                /* человек уже что-то ввёл */
    el.textContent = el.dataset.lmHint;
  }

  /* Возврат полного текста по касанию оставлял его на месте навсегда, если
     ввод так и не открылся: focusout не приходит, потому что фокуса не
     было. Через секунду проверяем, редактирует ли человек заметку, и если
     нет — сокращаем обратно. */
  function noteEditing(el) {
    if (!el) return false;
    if (el.classList.contains('active')) return true;
    if (el.querySelector('input, textarea')) return true;
    return !!(document.activeElement && el.contains(document.activeElement));
  }

  function maybeShortenNote() {
    var el = noteEl();
    if (el && !noteEditing(el)) shortenNoteHint(el);
  }

  var noteTimer = null;

  function scheduleNoteRecheck(ms) {
    clearTimeout(noteTimer);
    noteTimer = setTimeout(maybeShortenNote, ms || 900);
  }

  function fixUserNote() {
    var note_ = noteEl();
    if (!note_) return;

    shortenNoteHint(note_);

    if (!note_.dataset.lmNote) {
      note_.dataset.lmNote = '1';
      /* слушаем на погружении: обработчик лепры висит на самой заметке,
         и к моменту его вызова полный текст должен быть на месте */
      ['pointerdown', 'touchstart', 'mousedown', 'focusin'].forEach(function (ev) {
        document.addEventListener(ev, function (e) {
          var el = noteEl();
          if (el && e.target && (e.target === el || el.contains(e.target))) {
            restoreNoteHint(el);
            scheduleNoteRecheck(900);
          }
        }, true);
      });
      /* ушли из поля — лепра вернула подсказку целиком, сокращаем снова */
      document.addEventListener('focusout', function () {
        scheduleNoteRecheck(300);
      }, true);
    }

    var el = note_, steps = 0;
    while (el && steps < 6) {
      if (el === document.body ||
          el.classList.contains('l-i-wrapper') ||
          el.classList.contains('b-user_block')) break;
      /* h2 оставляем флексом: в нём имя и голосовалка стоят рядом,
         а display:block свёл бы их в две строки */
      if (el.tagName !== 'H2')
        el.style.setProperty('display', 'block', 'important');
      el.style.setProperty('position', 'static', 'important');
      el.style.setProperty('float', 'none', 'important');
      el.style.setProperty('width', 'auto', 'important');
      el.style.setProperty('max-width', 'none', 'important');
      el.style.setProperty('min-width', '0', 'important');
      el.style.setProperty('box-sizing', 'border-box', 'important');
      el.style.setProperty('margin-left', '0', 'important');
      el.style.setProperty('margin-right', '0', 'important');
      el.style.setProperty('padding-left', '0', 'important');
      el.style.setProperty('padding-right', '0', 'important');
      el = el.parentElement;
      steps++;
    }
  }

  /* Прохода, который искал серую полосу по признакам, здесь больше нет.
     Он был написан вслепую, пока не было таблицы стилей лепры, и находил
     не то: под определение «широкий узел без текста» попал сам аватар
     (285×285) и слой загрузчика поверх него — картинка пропадала со
     страницы. Причина полосы оказалась в одном правиле CSS
     (.b-user_block: padding-top 46px и серая заливка), и закрыта там же. */

  /* Голосовалка кармы у лепры прибита абсолютно к правому верхнему углу
     карточки (top:47px right:35px), под неё же в h2 оставлено 195px поля.
     В одну колонку она вставала отдельной строкой под датой регистрации.
     Переносим её в строку с именем — там она и стояла на десктопе. */
  function moveKarmaToName() {
    var h2 = document.querySelector('.b-i-user_data h2, .b-user_data h2');
    var karma = document.querySelector('.b-user_votes_wrapper');
    if (!h2 || !karma || karma.parentElement === h2) return;
    var name = h2.querySelector('.b-user_name-link');
    if (name && name.nextSibling) h2.insertBefore(karma, name.nextSibling);
    else h2.appendChild(karma);
  }

  /* Окно со списком проголосовавших.

     Лепра создаёт его по тапу и ставит абсолютно: right:50% от голосовалки
     плюс сдвиг вправо на 192px. На десктопе голосовалка в середине широкой
     карточки, и окно ложится под неё. На телефоне голосовалка прижата
     к правому краю строки с именем — окно уезжает за экран, документ
     становится шире окна, и страница перемасштабируется.

     Ширину ограничивает CSS, здесь остаётся горизонтальный сдвиг. Двигаем
     именно сдвигом (transform), а не координатами и полями, по двум
     причинам. Первая: лепра сама меряет окно, чтобы решить, показать его
     сверху или снизу (класс js-bottom), а transform не меняет ни
     offsetLeft, ни offsetWidth — её замеры остаются верными. Вторая:
     менять left/right пришлось бы наперегонки с её же расстановкой.

     Перед замером прошлый сдвиг снимаем: иначе на втором проходе мерилось
     бы уже сдвинутое окно и оно уползало бы дальше с каждым разом. */

  var POPUP_GAP = 6;          /* зазор от края экрана */
  var POPUP_ARROW_EDGE = 8;   /* насколько близко хвостик пускаем к углу */

  /* К чему окно относится. Для кармы берём сам счётчик: попадание хвостика
     в него виднее всего. Для голосовалок постов и комментариев — предок,
     от которого лепра его и позиционировала. */
  function popupAnchor(p) {
    if (p.classList.contains('b-votes_popup_karma'))
      return document.querySelector('.b-user_karma .b-karma_value') ||
             document.querySelector('.b-user_karma');
    return p.offsetParent || p.parentElement;
  }

  /* ============================================================
     СЛОИ ПОВЕРХ СТРАНИЦЫ
     ============================================================ */

  /* Модальные окна лепры — подтверждение пароля при покупке, диалоги
     подтверждения — размечает и позиционирует её собственный скрипт уже
     после нажатия: ширина и координаты приходят инлайном в пикселях,
     посчитанные от ширины документа. На телефоне документ шире экрана,
     и окно уезжает вправо вместе с кнопкой закрытия — а закрыть его
     больше нечем, потому что страница под ним обесточена.

     Разбирать конкретный класс нечем: скрипта лепры в сохранённой
     странице нет, а разметки до нажатия не существует. Поэтому правим
     не по имени, а по признаку — всплывший поверх страницы блок, что
     шире экрана или начинается за его краем. Это заодно закрывает все
     прочие окна лепры, до которых мы ещё не добрались. */

  function isOverlay(el) {
    var cs = getComputedStyle(el);
    if (cs.position !== 'fixed' && cs.position !== 'absolute') return false;
    var z = parseInt(cs.zIndex, 10);
    return z >= 100;                       /* ниже сотни — не окна, а мелочь */
  }

  /* Слои ищем по всему документу, а не среди прямых потомков body.
     Первая попытка смотрела только их, и модальное окно не нашлось:
     лепра вставляет его в глубину разметки, а не рядом с ней. Обход
     идёт тем же walk с отсечением комментариев и постов — иначе на
     длинном треде это сотня тысяч замеров стиля. */
  function eachLayer(visit, budget) {
    if (!document.body) return;
    walk(document.body, isBulk, function (el) {
      if (/^lm-/.test(el.id || '')) return;
      if (!isOverlay(el)) return;
      var r = el.getBoundingClientRect();
      if (!r.width || !r.height) return;
      visit(el, r);
    }, budget || CFG.scanBudget);
  }

  function squeezeOverlay(el, W) {
    var r = el.getBoundingClientRect();
    if (!r.width || !r.height) return false;
    if (r.width <= W && r.left >= -1 && r.right <= W + 1) return false;

    /* Ширину задаём замеренным числом, а не 100vw: vw в Safari не
       следует за масштабом страницы (разбор у правила html), а W сюда
       пришёл из clientWidth — то есть из настоящей раскладки. */
    el.style.setProperty('max-width', W + 'px', 'important');
    el.style.setProperty('box-sizing', 'border-box', 'important');
    el.style.setProperty('left', '0', 'important');
    el.style.setProperty('margin-left', '0', 'important');
    el.style.setProperty('margin-right', '0', 'important');
    /* Ширину в пикселях лепра пишет инлайном — снимаем её же способом. */
    if (el.style.width) el.style.setProperty('width', 'auto', 'important');
    return true;
  }

  function fitOverlays() {
    var W = document.documentElement.clientWidth;
    if (!W) return;
    eachLayer(function (el) { squeezeOverlay(el, W); });
  }

  function fitVotesPopup() {
    var W = document.documentElement.clientWidth;

    sliceOf(document.querySelectorAll('.b-votes_popup')).forEach(function (p) {
      p.style.removeProperty('transform');
      /* .invisible — служебное состояние лепры: окно отнесено на -10000px,
         чтобы измерить его невидимым. Мерить его бессмысленно. */
      if (p.classList.contains('invisible')) return;

      var r = p.getBoundingClientRect();
      if (!r.width || !r.height) return;

      var dx = 0;
      if (r.right > W - POPUP_GAP) dx = (W - POPUP_GAP) - r.right;
      if (r.left + dx < POPUP_GAP) dx = POPUP_GAP - r.left;
      if (dx)
        p.style.setProperty('transform',
                            'translateX(' + Math.round(dx) + 'px)', 'important');

      /* Хвостик пузыря лепра ставит числом от правого края окна (121px для
         кармы, 24px для поста). После сдвига он показывал бы в пустоту,
         поэтому наводим его на голосовалку по замеру, а не по числу.
         Обоим хвостикам, верхнему и нижнему: какой из них показать,
         лепра решает классом js-bottom, и это её дело. */
      var a = popupAnchor(p);
      if (!a) return;
      var ar = a.getBoundingClientRect();
      if (!ar.width) return;

      var left = r.left + dx;
      sliceOf(p.querySelectorAll('.b-votes_popup_arrow')).forEach(function (t) {
        var tw = t.getBoundingClientRect().width || 28;
        var x = ar.left + ar.width / 2 - left - tw / 2;
        x = Math.max(POPUP_ARROW_EDGE,
                     Math.min(r.width - tw - POPUP_ARROW_EDGE, x));
        t.style.setProperty('left', Math.round(x) + 'px', 'important');
        t.style.setProperty('right', 'auto', 'important');
      });
    });
  }

  /* Когда мерить. Окно появляется по тапу, а список голосовавших приходит
     ответом сервера уже после — от одного замера толку мало. Отдельный
     наблюдатель за всем документом ради этого не нужен: тап и так проходит
     через document, и по нему заводим короткую серию проверок. Слушатель
     на перехвате, чтобы обработчик лепры не успел его отменить. */
  var popupWatched = false;

  function watchVotesPopup() {
    if (popupWatched || !document.body) return;
    popupWatched = true;
    var run = guard('fitVotesPopup', fitVotesPopup);
    document.addEventListener('click', function (e) {
      var t = e.target;
      if (!t || !t.closest) return;
      if (!t.closest('.b-karma_value, .vote, .b-votes_popup')) return;
      [0, 60, 200, 500, 1200].forEach(function (ms) { setTimeout(run, ms); });
    }, true);
  }

  /* «Гражданин Лепрозория до 3 Сентября 2027» — строка на две строки
     экрана, из которых половина уходит на слова, известные и без того.
     Оставляем «Гражданство до 03.09.27», полную дату кладём в подсказку.
     Узел даты забираем ДО того, как переписать заголовок: textContent
     сносит всех детей, и потом вставлять было бы уже нечего. */
  function compactCitizen() {
    var box = document.querySelector('.b-user_citizen');
    if (!box || box.dataset.lmCitizen) return;
    var h3 = box.querySelector('h3');
    if (!h3) return;
    box.dataset.lmCitizen = '1';

    var date = h3.querySelector('.js-date');
    if (!date) { h3.textContent = 'Гражданство'; return; }

    var full = (date.textContent || '').trim();
    var epoch = parseInt(date.getAttribute('data-epoch_date'), 10);
    if (epoch) {
      var d = new Date(epoch * 1000);
      if (!isNaN(d.getTime())) {
        date.title = full;
        date.textContent = pad2(d.getDate()) + '.' + pad2(d.getMonth() + 1) +
                           '.' + String(d.getFullYear()).slice(2);
      }
    }
    h3.textContent = 'Гражданство до ';
    h3.appendChild(date);
  }

  /* Пенсне и жёлтое поле должны стоять в одной строке, как на десктопе,
     а переключатели — выше. Одним флексом с переносом это не выражается:
     строки набираются жадно, и порядок узлов у лепры другой. Поэтому
     собираем пенсне и список в свою строку-обёртку.
     Обработчик разворота вешает скрипт лепры прямо на узел пенсне —
     перенос узла его сохраняет, слушатели переезжают вместе с элементом. */
  function groupNotesRow() {
    var box = document.querySelector('.b-user_public_notes');
    if (!box) return;
    var logo = box.querySelector('.b-user_public_notes_logo');
    var list = box.querySelector('.b-user_public_notes_list');
    if (!logo || !list) return;

    /* Чекбокс и сортировка — в общую обёртку. Порознь они набираются в
       строки жадно: «показать авторов» (128) и чекбокс (152) влезали в
       одну строку, а сортировке (138) места уже не оставалось, и она
       уходила третьей строкой к левому краю. Вместе они переносятся и
       прижимаются вправо одной парой. */
    var sw = box.querySelector('.b-user_public_notes_switcher');
    var sort = box.querySelector('.b-user_public_notes_sorting');
    if (sw && sort && !(sw.parentElement &&
        sw.parentElement.classList.contains('lm-notes-controls'))) {
      var ctl = document.createElement('div');
      ctl.className = 'lm-notes-controls';
      box.insertBefore(ctl, sw);
      ctl.appendChild(sw);
      ctl.appendChild(sort);
    }

    if (logo.parentElement && logo.parentElement.classList.contains('lm-notes-row')) return;

    var row = document.createElement('div');
    row.className = 'lm-notes-row';
    box.appendChild(row);
    row.appendChild(logo);
    row.appendChild(list);
  }

  /* ============================================================
     СПИСОК ГРАЖДАН (/users/)
     ============================================================ */

  /* Имя и город сведены в одну строку правилами, но разделитель между
     ними в CSS не выразить: поле имени у лепры может быть пустым, и
     ::before на городе дал бы строку, начинающуюся с точки. Ставим метку
     только там, где слева от неё действительно что-то есть.

     Заодно снимаем подложку-кнопку со свёрнутого описания, если лепра
     положила внутрь содержимое, не тронув класс __empty: раскрытый текст
     оказался бы в блоке нулевой высоты поверх карточки. Проверка идёт по
     элементам-потомкам — пустое описание у лепры содержит один перевод
     строки, и :empty на нём не срабатывает. */
  /* Квадратик и его подпись сводим в один узел: порознь они идут по
     строке двумя пунктами, и подпись отрывается от чекбокса на переносе.
     Между ними у лепры лежит перевод строки — его убираем, иначе он
     останется висеть лишним пробелом внутри пары. */
  function wrapCheckbox(inp) {
    if (!inp || !inp.id || !inp.parentNode) return null;
    if (inp.parentNode.classList.contains('lm-chk')) return inp.parentNode;
    var lab = inp.parentNode.querySelector('label[for="' + inp.id + '"]');
    if (!lab || lab.parentNode !== inp.parentNode) return null;

    var pair = document.createElement('span');
    pair.className = 'lm-chk';
    inp.parentNode.insertBefore(pair, inp);
    pair.appendChild(inp);
    var n = pair.nextSibling;
    while (n && n !== lab) {
      var next = n.nextSibling;
      if (n.nodeType === 3 && !n.nodeValue.trim()) n.parentNode.removeChild(n);
      n = next;
    }
    pair.appendChild(lab);
    return pair;
  }

  /* Общий кусок подписи выносим в начало строки: «был президентом, был
     министром, был пресс-секретарём» — три лишних слова на строку,
     в которую и без них едва помещаются три чекбокса. Полный текст
     остаётся в подсказке. */
  function stripPrefix(el, re) {
    var t = (el.textContent || '').replace(/\u00a0/g, ' ').trim();
    var m = t.match(re);
    if (!m) return false;
    if (!el.title) el.title = t;
    el.textContent = m[1];
    return true;
  }

  function fixUsersList() {
    var box = document.querySelector('.b-users_list_users');
    if (!box) return;

    sliceOf(box.querySelectorAll('.b-list_item_user_residence')).forEach(function (r) {
      if (seen.userRow.has(r)) return;
      seen.userRow.add(r);
      var body = r.parentNode;
      var name = body && body.querySelector('.b-list_item_user_name');
      var has = function (el) {
        return !!el && (el.textContent || '').replace(/\u00a0/g, ' ').trim() !== '';
      };
      if (has(name) && has(r)) r.classList.add('lm-after_name');
    });

    sliceOf(box.querySelectorAll('.b-list_item_user_description__empty'))
      .forEach(function (d) {
        if (d.children.length) d.classList.add('lm-open');
        else d.classList.remove('lm-open');
      });
  }

  /* Строка первая: «искать среди заметок» с полями пола и гражданства.
     Чекбокс лежит у лепры в своём блоке над полями — переносим блок
     целиком, вместе со скрытым пунктом «мои заметки» и обработчиком,
     который его открывает. Сам блок из раскладки убран правилом
     display: contents, поэтому в строку встают его дети. */
  function buildUsersRows() {
    var filters = document.querySelector('.b-users_list_filters');
    if (!filters) return;

    var notes = document.getElementById('js-users_search_user_notes');
    if (notes) {
      var flags = notes.closest('.b-users_list_flags');
      if (flags && flags.parentNode !== filters)
        filters.insertBefore(flags, filters.firstChild);
      wrapCheckbox(notes);
      wrapCheckbox(document.getElementById('js-users_search_my_notes'));
    }

    /* Строка вторая: «Был» и три чекбокса. Берём соседа строки полей —
       по классу его от перенесённого блока заметок не отличить. */
    var was = filters.nextElementSibling;
    if (was && was.classList.contains('b-users_list_flags') && !was.dataset.lmWas) {
      was.dataset.lmWas = '1';
      var pre = '';
      sliceOf(was.querySelectorAll('input[type="checkbox"]')).forEach(function (inp) {
        var pair = wrapCheckbox(inp);
        var lab = pair && pair.querySelector('label');
        if (!lab) return;
        var t = (lab.textContent || '').replace(/\u00a0/g, ' ').trim();
        if (stripPrefix(lab, /^(?:был)\s+(.+)$/i)) pre = 'Был';
      });
      if (pre) {
        var p = document.createElement('span');
        p.className = 'lm-flag_prefix';
        p.textContent = pre;
        was.insertBefore(p, was.firstChild);
      }
    }

    /* Строка третья: сортировка. Слово «Сортировать:» лежит голым
       текстовым узлом — заворачиваем, иначе оно не станет пунктом
       флекс-строки и мерить в подгонке будет нечего. */
    var sort = document.querySelector('.b-users_list_sorting');
    if (sort && !sort.dataset.lmSort) {
      sort.dataset.lmSort = '1';
      sliceOf(sort.childNodes).forEach(function (n) {
        if (n.nodeType === 3 && n.nodeValue.trim()) sort.removeChild(n);
      });
      var sp = document.createElement('span');
      sp.className = 'lm-sort_prefix';
      sp.title = 'Сортировать по';
      sp.textContent = 'Сортировать по';
      sort.insertBefore(sp, sort.firstChild);
    }
    if (sort) {
      sliceOf(sort.querySelectorAll('li a, li strong')).forEach(function (a) {
        if (a.dataset.lmSort) return;
        a.dataset.lmSort = '1';
        stripPrefix(a, /^по\s+(.+)$/i);
      });
    }
  }

  /* ---- Подгонка строк настроек в одну линию ----
     Считать заранее нечего: доступная ширина зависит от масштаба
     страницы, который скрипту не виден, а ширина полей — от выбранных
     пунктов. Меряем по факту и ужимаем ступенями, каждый раз начиная
     от исходного кегля: иначе на повороте экрана строка осталась бы
     мелкой, хотя места стало больше. */
  var ROW_UNITS = '.lm-chk, .lm-flag_prefix, .lm-sort_prefix, select, li';
  var ROW_STEPS = [1, 0.92, 0.85, 0.78];

  /* Пункты строки разной высоты, и по верхнему краю их не сравнить:
     при выравнивании по центру поле выбора выше подписи, а тапом
     это не отличить от переноса. Сравниваем середины. */
  function sameLine(list) {
    var mid = [], i, r;
    for (i = 0; i < list.length; i++) {
      r = list[i].getBoundingClientRect();
      if (!r.width || !r.height) continue;   /* скрытые пункты не в счёт */
      mid.push(r.top + r.height / 2);
    }
    if (mid.length < 2) return true;
    return Math.max.apply(null, mid) - Math.min.apply(null, mid) <= 4;
  }

  /* Последние ступени для строки сортировки. Одним кеглем её не спасти:
     «Сортировать по» занимает столько же, сколько два варианта вместе,
     а «комментариям» — самое длинное слово в ряду. Убираем по одному и
     только когда кегль уже дошёл до предпоследней ступени. Полный текст
     держим в data-атрибуте, а не в подсказке: в подсказке лежит исходная
     подпись лепры вместе с предлогом, и вернуть из неё нечего. */
  function sortStages() {
    var sort = document.querySelector('.b-users_list_sorting');
    if (!sort) return [];
    return [
      [sort.querySelector('.lm-sort_prefix'), 'по'],
      [sort.querySelector('li[data-sorting="comments_count"] a, ' +
                          'li[data-sorting="comments_count"] strong'), 'комментам']
    ];
  }

  function sortShorten(full) {
    var st = sortStages(), hit = false, i, el;
    for (i = 0; i < st.length; i++) {
      el = st[i][0];
      if (!el) continue;
      if (full) {
        if (el.dataset.lmFull && el.textContent !== el.dataset.lmFull) {
          el.textContent = el.dataset.lmFull;
          hit = true;
        }
        continue;
      }
      if (el.textContent === st[i][1]) continue;
      if (!el.dataset.lmFull) el.dataset.lmFull = el.textContent;
      el.textContent = st[i][1];
      return true;              /* по одной ступени за раз */
    }
    return hit;
  }

  function fitUsersRow(row, shorten) {
    if (!row) return;
    /* До загрузки шрифта ширины подписей другие, и мерить рано. */
    if (document.fonts && document.fonts.status !== 'loaded') return;

    var base = parseFloat(row.dataset.lmBase);
    if (!(base > 0)) {
      base = parseFloat(getComputedStyle(row).fontSize);
      if (!(base > 0)) return;
      row.dataset.lmBase = base;
    }
    if (shorten) shorten(true);

    for (var i = 0; i < ROW_STEPS.length; i++) {
      row.style.setProperty('font-size',
                            (base * ROW_STEPS[i]).toFixed(1) + 'px', 'important');
      fitSelects();
      if (sameLine(sliceOf(row.querySelectorAll(ROW_UNITS)))) return;
      /* Сокращение подписи — только с третьей ступени кегля: убавить
         кегль на восьмую долю заметно меньше, чем урезать слово.
         По одной подписи на ступень, самая безобидная первой. */
      if (i >= 2 && shorten && shorten(false) &&
          sameLine(sliceOf(row.querySelectorAll(ROW_UNITS)))) return;
    }
    /* Дальше ужимать нечем: перенос честнее нечитаемого кегля. */
  }

  function fitUsersRows() {
    var filters = document.querySelector('.b-users_list_filters');
    if (!filters) return;
    fitUsersRow(filters, null);
    var was = filters.nextElementSibling;
    if (was && was.classList.contains('b-users_list_flags')) fitUsersRow(was, null);
    fitUsersRow(document.querySelector('.b-users_list_sorting'), sortShorten);
  }

  /* ---- Сворачивание карточки ----
     У лепры обработчик только на разворот: раскрытая карточка обратно
     не закрывается ничем. Свой переключатель ведём своим классом.
     Слушаем в фазе перехвата и гасим событие там же: обработчик лепры
     висит на самом блоке описания, то есть в фазе всплытия сработал бы
     раньше нашего и развернул карточку тем же нажатием. */
  var cardTapBound = false;

  function watchUserCards() {
    if (cardTapBound || !document.querySelector('.b-users_list_users')) return;
    cardTapBound = true;
    document.addEventListener('click', function (e) {
      var t = e.target;
      if (!t || !t.closest) return;
      var d = t.closest('.b-list_item_user_description');
      if (!d || !d.closest('.b-users_list_users')) return;
      if (t.closest('a')) return;
      /* Пока лепра не положила внутрь содержимое, сворачивать нечего —
         первое нажатие должно дойти до её обработчика. */
      if (!d.children.length) return;
      d.classList.toggle('lm-collapsed');
      e.stopPropagation();
      e.preventDefault();
    }, true);
  }


  /* ============================================================
     ПОДСАЙТЫ: ПРОСТОЕ ПЕНСНЕ
     ============================================================ */

  /* Правая колонка подлепры (.b-subdomain_aside_right) — кнопка подписки,
     настройки уведомлений, облако тегов и вольный текст правления со
     ссылками. На десктопе это столбец сбоку от ленты; развёрнутый в одну
     колонку, он у иных подлепр занимает два экрана до первого поста.
     Складываем его целиком под одну строку — «простое пенсне», по образцу
     волшебного пенсне в профиле.

     Порог постов сюда не попадает: buildNavthing уносит его в третью
     колонку навигационной штуки раньше, поэтому пенсне собирается ПОСЛЕ
     неё. (В шапку порог уходил до 0.9.109 — там его больше не бывает.) */

  var PINCE_KEY = 'lm-pince';

  /* Стёкла рисуем разметкой, а не картинкой: pincenez_logo.png лежит на
     основном домене, а подлепра — это отдельный поддомен, и за него
     пришлось бы ходить запросом. Заодно значок красится вместе с текстом
     и переворачивается тёмной темой сам, без исключения из инверсии. */
  var PINCE_SVG =
    '<svg class="lm-pince_glass" viewBox="0 0 46 20" width="30" height="13" ' +
    'aria-hidden="true" focusable="false">' +
    '<g fill="none" stroke="currentColor" stroke-width="2" ' +
    'stroke-linecap="round"><circle cx="12" cy="11" r="7"/>' +
    '<circle cx="32" cy="11" r="7"/><path d="M19 11h6"/>' +
    '<path d="M5 8C3 4 1 3 1 3"/><path d="M39 8c4-1 6 4 3 7"/></g></svg>';

  function pinceOpen() {
    try { return localStorage.getItem(PINCE_KEY) === '1'; } catch (e) { return false; }
  }

  function buildSubsitePince() {
    var aside = document.querySelector('.b-subdomain_aside_right');
    if (!aside || aside.dataset.lmPince) return;
    /* Пустая колонка встречается: у молодой подлепры нет ни описания,
       ни тегов, и тогда строка-переключатель нечего разворачивать. */
    if (!aside.textContent.replace(/\s/g, '')) return;
    aside.dataset.lmPince = '1';

    var body = document.createElement('div');
    body.className = 'lm-pince_body';
    while (aside.firstChild) body.appendChild(aside.firstChild);

    /* Левая колонка подсайта скрыта общим правилом — переносим её в
       конец тела: описание подлепры важнее её управляющего, а внизу
       текст колонки читается продолжением, а не врезкой. */
    var left = document.querySelector('.l-content_aside_subsite');
    if (left) body.appendChild(left);

    var btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'lm-pince';
    btn.innerHTML = PINCE_SVG +
      '<span class="lm-pince_label">Простое пенсне</span>' +
      /* знак шеврона — в CSS: он меняется по состоянию */
      '<span class="lm-pince_arrow"></span>';

    aside.appendChild(btn);
    aside.appendChild(body);

    var open = pinceOpen();
    aside.classList.toggle('lm-pince__open', open);
    btn.setAttribute('aria-expanded', open ? 'true' : 'false');

    btn.addEventListener('click', function (e) {
      e.preventDefault();
      var on = !aside.classList.contains('lm-pince__open');
      aside.classList.toggle('lm-pince__open', on);
      btn.setAttribute('aria-expanded', on ? 'true' : 'false');
      try { localStorage.setItem(PINCE_KEY, on ? '1' : '0'); } catch (err) {}
    });
  }


  /* ---- Звания (/fraud/ranks/) ----
     Две вещи, которые одним CSS не делаются.

     Первая — блок объяснения аукциона: четыре абзаца перед таблицей,
     на телефоне это целый экран до первого звания. Сворачиваем его в
     строку с уголком; состояние помним, как у пенсне.

     Вторая — подсказка в поле новой должности. Поле уехало отдельной
     строкой, и подпись «Добавить должность:» осталась выше; без
     подсказки внутри непонятно, чем это поле отличается от соседнего
     поля ника. Заодно называем предел длины: он написан только в
     свёрнутом объяснении. */

  var ABOUT_KEY = 'lm-ranks-about';

  function aboutOpen() {
    try {
      var v = localStorage.getItem(ABOUT_KEY);
      if (v === '1') return true;
      if (v === '0') return false;
    } catch (e) {}
    return !!CFG.ranksAbout;
  }

  function fixRanks() {
    var about = document.querySelector('.b-ranks_about');
    if (about && !about.dataset.lmAbout) {
      about.dataset.lmAbout = '1';
      var btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'lm-ranks_about';
      btn.textContent = 'Как это устроено';
      about.parentNode.insertBefore(btn, about);

      var open = aboutOpen();
      btn.classList.toggle('lm-open', open);
      btn.setAttribute('aria-expanded', open ? 'true' : 'false');

      btn.addEventListener('click', function (e) {
        e.preventDefault();
        var on = !btn.classList.contains('lm-open');
        btn.classList.toggle('lm-open', on);
        btn.setAttribute('aria-expanded', on ? 'true' : 'false');
        try { localStorage.setItem(ABOUT_KEY, on ? '1' : '0'); } catch (err) {}
      });
    }

    var rank = document.querySelector('.b-ranks_input_rank');
    if (rank && !rank.getAttribute('placeholder'))
      rank.setAttribute('placeholder', 'должность, до 25 знаков');
  }


  /* ---- Обрамление профиля ----
     Картинку фона лепра ставит инлайновым стилем на .b-user_block.
     Читаем именно инлайновый стиль, а не вычисленный: в вычисленном
     лежала бы и лепровская заглушка, и отличить «своя картинка» от
     «ничего» стало бы нельзя. Класс снимаем, если картинки нет, —
     владелец мог убрать её, а страница обновиться без перезагрузки. */
  function markProfileArt() {
    var block = document.querySelector('.b-user_block');
    if (!block) return;
    var img = block.style.backgroundImage;
    var has = !!img && img !== 'none';
    block.classList.toggle('lm-art', has);
    /* Тот же признак дублируется на html, и не для удобства. Серую
       подложку профиля (.b-i-user_block и соседи) мы гасим — на пустом
       профиле она только грязнит. Но на профиле с картинкой эта самая
       подложка и есть подставка под текст: сними её, и текст ляжет
       прямо на яркую картинку и станет нечитаем, а полупрозрачные её
       слои дадут вместо фона мутное пятно посередине.
       Правило гашения поэтому висит на html:not(.lm-profart), а класс
       нужен на общем предке — с .b-user_block его не достать: подложка
       ему не потомок, а сосед по дереву выше. */
    document.documentElement.classList.toggle('lm-profart', has);
  }


  /* ---- Девиз подлепры одной строкой ----
     Выключка по центру и запрет переноса стоят в CSS, но уместить фразу
     в строку правилами нельзя: длина у девизов любая — от «Йода» до
     «Филиал дурдома. Научная секция диодов.». Кегль подбираем замером.

     Считать надо каждый раз заново, от начального значения: у Den масштаб
     страницы меняется прямо на ходу, CSS-ширина гуляет от 462 до 340, и
     подгонка, наложенная на прежнюю, ушла бы вниз ступенями и обратно
     уже не поднялась. */
  var titleWidth = 0;   /* при какой ширине экрана считали в прошлый раз */

  function fitSubsiteHeader() {
    var h = document.querySelector('.b-subsite_header');
    if (!h) return;
    var a = h.querySelector('a') || h;

    /* Вокруг надписи в разметке лежат табуляция и перевод строки. На
       выключке по левому краю они не видны, а по центру входят в замер:
       строка считается шире, чем есть, и кегль выходит мельче нужного.
       Чистим один раз — дальше текст свой. */
    if (!h.dataset.lmTitle) {
      h.dataset.lmTitle = '1';
      var txt = (a.textContent || '').replace(/\s+/g, ' ').trim();
      if (txt) a.textContent = txt;
    }

    var W = h.clientWidth;
    /* Ноль означает «мерить нечем»: страница ещё не оформлена или блок
       скрыт. Сравнение с нулём прошло бы как «влезает» при любом кегле. */
    if (!W) return;

    var base = CFG.subsiteTitle, min = CFG.subsiteTitleMin, size = base;
    h.style.setProperty('font-size', base + 'px', 'important');
    var w = a.getBoundingClientRect().width;

    if (w > W) {
      /* Первое приближение — по пропорции: ширина строки растёт вместе с
         кеглем почти линейно. «Почти» — из-за округления глифов по
         пикселям, поэтому дальше несколько шагов по полпункта вниз. */
      size = Math.max(min, Math.floor(base * (W / w) * 2) / 2);
      h.style.setProperty('font-size', size + 'px', 'important');
      for (var i = 0; i < 8 && size > min &&
                      a.getBoundingClientRect().width > W; i++) {
        size = Math.max(min, size - 0.5);
        h.style.setProperty('font-size', size + 'px', 'important');
      }
    }

    titleWidth = document.documentElement.clientWidth;
  }


  /* ---- Подписи вариантов порога ----
     Полное название самого длинного варианта в колонку не помещается ни
     при каком читаемом кегле: «NIGHTMARE (все)» просит около 130
     пикселей при 111 доступных. Число в скобках — уточнение к слову, а
     не само слово, поэтому в свёрнутом поле показываем только слово, а
     скобку возвращаем на время, пока список раскрыт: там ширина уже не
     наша забота, список рисует система во всю ширину экрана.

     Полный текст держим в data-атрибуте узла, а не собираем обратно из
     сокращённого: восстановить «(все)» по слову «nightmare» нечем.
     Заодно нормализуем пробелы — в разметке лепры подписи набраны с
     переводами строк и табуляцией, и они входят в замер ширины.

     Разворачиваем по трём событиям сразу. Все они приходят ДО того, как
     система построит список: touchstart — раньше всех, mousedown — если
     палец оказался мышью или отладочным кликом, focus — если до поля
     добрались с клавиатуры. Подмена текста успевает в любом случае.
     Сворачиваем по blur и change. change на пороге у лепры означает
     отправку формы и перезагрузку, но полагаться на это не стоит. */
  var THRESHOLD_NOTE = /\s*\([^()]*\)\s*$/;

  function thresholdFull(sel, on) {
    for (var i = 0; i < sel.options.length; i++) {
      var o = sel.options[i], full = o.dataset.lmFull;
      if (!full) {
        full = (o.textContent || '').replace(/\s+/g, ' ').trim();
        o.dataset.lmFull = full;
      }
      var brief = full.replace(THRESHOLD_NOTE, '');
      /* Вариант без скобки (если такой попадётся) остаётся как есть:
         пустая подпись хуже длинной. */
      o.textContent = (on || !brief) ? full : brief;
    }
    /* Признак для fitThreshold: пока список раскрыт, мерить нельзя —
       подписи в нём длинные, и кегль ушёл бы вниз ни за чем. */
    sel.dataset.lmOpen = on ? '1' : '';
  }

  function prepThreshold() {
    var sel = document.querySelector('.lm-navthing_extra .b-posts_threshold select');
    if (!sel || sel.dataset.lmLabels) return;
    sel.dataset.lmLabels = '1';
    thresholdFull(sel, false);
    ['touchstart', 'mousedown', 'focus'].forEach(function (ev) {
      sel.addEventListener(ev, function () {
        guard('thresholdFull', thresholdFull)(sel, true);
      }, true);
    });
    ['blur', 'change'].forEach(function (ev) {
      sel.addEventListener(ev, function () {
        guard('thresholdFull', thresholdFull)(sel, false);
      }, true);
    });
  }


  /* ---- Поле выбора порога постов ----
     Ширину полю задаёт самый длинный вариант списка, а не выбранный: на
     главной это «nightmare (все)», на подсайтах — «NIGHTMARE (все)»
     прописными, что заметно шире. В строке шапки под поле уходила её
     половина, и запаса хватало; в третьей колонке навигационной штуки
     ему отведена треть — при экране 393 это 111 пикселей вместе с рамкой
     и стрелкой, и длинный вариант туда не помещается.

     Подбираем кегль замером, как у девиза: ставим полю естественную
     ширину (в CSS ему задано 100% колонки, то есть готовый ответ «ровно
     столько, сколько дали», по которому ничего не узнать), смотрим,
     сколько оно просит, и опускаем кегль полупунктами, пока не влезет.
     Ниже CFG.thresholdFontMin не идём — там уже нечитаемо, и честнее
     срезать хвост.

     Считаем каждый раз от CFG.thresholdFont, а не от текущего значения:
     иначе повторные вызовы (поворот, смена масштаба, новый проход)
     уводили бы кегль вниз ступенями и обратно он бы не поднялся.

     Свёрнутую панель не меряем вовсе: тело у неё display: none, все
     прямоугольники нулевые, и проверка «влезает ли» прошла бы при любом
     кегле. Выходим на нуле — подгонка случится при разворачивании.

     Ширину, на которой считали в прошлый раз, запоминаем: функция висит
     на resize, а Safari шлёт resize и от прячущейся адресной строки, то
     есть при обычной прокрутке. Пока колонка той же ширины, пересчитывать
     нечего — и замеры при скролле не идут. */
  var thresholdCol = 0;

  function fitThreshold() {
    var col = document.querySelector('.lm-navthing_extra');
    var sel = col && col.querySelector('.b-posts_threshold select');
    if (!sel) return;
    /* Список раскрыт — в нём стоят полные подписи, и мерить по ним
       значит подогнать кегль под то, что видно только в раскрытом
       состоянии, где ширина колонки ни при чём. */
    if (sel.dataset.lmOpen === '1') return;
    var W = col.clientWidth;
    if (!W || W === thresholdCol) return;

    var base = CFG.thresholdFont, min = CFG.thresholdFontMin, size = base;
    sel.style.setProperty('width', 'auto', 'important');
    sel.style.setProperty('font-size', size + 'px', 'important');
    for (var i = 0; i < 10 && size > min &&
                    sel.getBoundingClientRect().width > W; i++) {
      size = Math.max(min, size - 0.5);
      sel.style.setProperty('font-size', size + 'px', 'important');
    }
    /* Ширину возвращаем колонке: подгонка касается только кегля. */
    sel.style.removeProperty('width');
    thresholdCol = W;
  }


  /* ============================================================
     ПОИСК: РАСКРЫТИЕ ПОЛЯ И ДИНАМИЧЕСКИЙ СПИСОК
     ============================================================ */

  /* Решение целиком описано в CSS, рядом с правилами. Здесь только то,
     что селектором не выражается: три числа, которые скрипт кладёт в
     переменные на <html>, и события, по которым он их пересчитывает. */

  var srchWatched = false;
  var srchPullSeen = '';   /* обстоятельства последнего замера оттяжки */
  var srchTimer = null;

  function searchInput() {
    return document.querySelector(
      '#js-header_search_input, .b-header_search input[type="search"], ' +
      '.b-header_search input[type="text"]');
  }

  function searchForm() {
    var inp = searchInput();
    return inp ? (inp.form || (inp.closest && inp.closest('form'))) : null;
  }

  /* Возвращает true, если замер удался. По этому ответу ставится класс:
     правила списка ссылаются на переменные, и включать их до того, как
     переменные посчитаны, значит один раз показать список у начала
     документа. */
  function searchVars() {
    var inp = searchInput();
    if (!inp) return false;
    var st = document.documentElement.style;
    var open = document.documentElement.classList.contains('lm-search_wide');
    var f = searchForm();

    /* Оттяжку меряем только по НЕРАСКРЫТОМУ полю. У раскрытого левый край
       уже стоит у кромки, оттяжка вышла бы нулевой, и следующий же
       пересчёт (их два: по клавиатуре и по повороту) схлопнул бы поле
       обратно посреди набора. */
    if (f && !open) {
      var rf = f.getBoundingClientRect();
      if (rf.width) {
        st.setProperty('--lm-srch-pull',
          '-' + Math.max(0, Math.round(rf.left) - CFG.pageEdge) + 'px');
        /* Что именно померили — в отчёт. Оттяжка живёт до конца жизни
           страницы, а замер разовый: если она разойдётся с сегодняшним
           положением формы, по этим числам сразу видно, в какой момент
           и при какой ширине окна она была снята. Одного значения
           переменной для этого не хватало. */
        srchPullSeen = Math.round(rf.left) + '/' + Math.round(rf.right) +
          ' при окне ' + (window.innerWidth || 0) +
          ' и масштабе ' + (srchScaleSeen || 1).toFixed(3);
      }
    }

    var r = inp.getBoundingClientRect();
    if (!r.height) return false;

    /* Верх списка. Лепра кладёт контейнер прямым потомком body, а body у
       нас position: relative без полей и рамок — значит верх отсчитывается
       от начала ДОКУМЕНТА, а не от экрана, и к низу поля надо прибавить
       прокрутку. Прибавляем через scrollTopNow: из-за overflow-x на body
       прокрутку иногда ведёт не окно, а сам body. */
    st.setProperty('--lm-qs-top',
      Math.round(r.bottom + scrollTopNow() + 1) + 'px');

    /* Высота списка. Клавиатура окно не уменьшает: innerHeight остаётся
       прежним, а видно из него меньше половины. Настоящую нижнюю кромку
       знает только visualViewport, и его offsetTop с getBoundingClientRect
       в одной системе координат — оба отсчитаны от окна раскладки.
       Вычитаем подвал списка («показать все результаты» — 40) и рамку. */
    var vv = window.visualViewport;
    var bottom = vv ? vv.offsetTop + vv.height : (window.innerHeight || 0);
    var avail = Math.round(bottom - r.bottom - CFG.pageEdge - 44);
    st.setProperty('--lm-qs-max',
      Math.max(CFG.searchListMin, avail) + 'px');
    return true;
  }

  /* Подкрутка страницы: поле уводится под верхнюю кромку, и всё, что
     ниже, достаётся списку. Мгновенно и только мгновенно: плавная
     прокрутка в этом скрипте запрещена (складывалась сама с собой и
     уносила страницу на десятки тысяч пикселей). */
  function searchLiftPage(el) {
    if (!CFG.searchScroll) return;
    var inp = el || searchInput();
    if (!inp) return;
    var r = inp.getBoundingClientRect();
    if (!r.height) return;
    var y = Math.max(0, Math.round(scrollTopNow() + r.top - CFG.searchTop));
    /* Порог, а не безусловная запись: страница уже может стоять как надо
       (Safari сам подтягивает поле), и лишняя запись — это лишний рывок. */
    if (Math.abs(y - scrollTopNow()) < 3) return;
    scrollTopSet(y);
  }

  function qsBox() { return document.querySelector('.b-quick_search_container'); }

  /* Крестик в углу списка. Контейнер лепра держит в разметке постоянно и
     наполняет заново на каждой букве, поэтому проверяем не «создавали ли
     мы кнопку когда-то», а «лежит ли она в контейнере сейчас». */
  function ensureQsClose() {
    var box = qsBox();
    if (!box) return;
    var b = box.querySelector('.lm-qs_close');
    if (b && b.parentNode === box) return;
    b = document.createElement('button');
    b.type = 'button';
    b.className = 'lm-qs_close';
    b.setAttribute('aria-label', 'закрыть поиск');
    b.textContent = '×';
    b.addEventListener('click', function (e) {
      e.preventDefault();
      guard('searchDismiss', searchDismiss)();
    });
    box.appendChild(b);
  }

  /* Полное закрытие: список прячется, поле схлопывается, клавиатура
     уходит. Введённый текст остаётся — закрывают список именно затем,
     чтобы вернуться к странице, не потеряв набранное. */
  function searchDismiss() {
    var inp = searchInput();
    if (srchTimer) { clearTimeout(srchTimer); srchTimer = null; }
    if (inp && document.activeElement === inp && inp.blur) inp.blur();
    var cl = document.documentElement.classList;
    cl.remove('lm-search_wide');
    cl.remove('lm-search_font');
    cl.add('lm-search_off');
  }

  /* Тап пришёлся мимо поиска? Внутрь списка и внутрь формы не считается:
     первое — выбор строчки, второе — правка запроса. */
  function outsideSearch(t) {
    if (!t || !t.closest) return false;
    return !t.closest('.b-header_search, #js-header_search_form, ' +
                      '.b-quick_search_container, #js-search .b-search_header');
  }

  /* Кегль поля на время ввода — с поправкой на масштаб страницы.
     Safari смотрит не на число в CSS, а на то, сколько кегль занимает на
     экране: при масштабе 85% шестнадцатый доходит до глаза
     тринадцатым с половиной, и приближение всё равно случается. А оно
     здесь дороже, чем кажется: окно раскладки при уменьшенном масштабе
     ШИРЕ экрана (462 против 393), и приближённый экран показывает не
     всю его ширину — правый край с лупой и весь динамический список
     уезжают за кромку.
     Масштаб берём у visualViewport: другого источника нет, а этот
     отдаёт ровно то отношение, по которому Safari и принимает решение.
     Записываем сразу и для отчёта — при следующей жалобе будет видно,
     какой масштаб стоял в момент касания, а не в момент снятия отчёта. */
  var srchScaleSeen = 0;

  function searchFontVar() {
    var vv = window.visualViewport;
    var k = (vv && vv.scale) ? vv.scale : 1;
    srchScaleSeen = k;
    var px = Math.ceil(CFG.searchFocusFont / k);
    px = Math.min(CFG.searchFontMax, Math.max(CFG.searchFocusFont, px));
    document.documentElement.style.setProperty('--lm-srch-font', px + 'px');
  }

  /* Касание поля. Делает ровно одно: поднимает кегль, чтобы Safari не
     приближал страницу. Всё остальное ждёт первой буквы. */
  function searchOpen() {
    if (!CFG.searchWide || !searchInput()) return;
    if (srchTimer) { clearTimeout(srchTimer); srchTimer = null; }
    searchFontVar();
    document.documentElement.classList.add('lm-search_font');

    /* Касание не всегда кончается фокусом: с поля можно начать протяжку
       страницы. Кегль в этом случае так и остался бы поднятым. */
    setTimeout(function () {
      var a = document.activeElement;
      if (!a || (a !== searchInput() && !isBigSearchField(a)))
        guard('searchClose', searchClose)();
    }, 500);
  }

  /* Первая буква. Здесь поле раздвигается, страница подкручивается и
     включаются правила списка. */
  function searchType() {
    if (!CFG.searchWide || !searchInput()) return;
    if (srchTimer) { clearTimeout(srchTimer); srchTimer = null; }

    var cl = document.documentElement.classList;
    /* Пересчёт кегля здесь не лишний: касание могло и не дойти (фокус
       ставят и клавишей «дальше» с соседнего поля), а масштаб страницы
       человек меняет когда угодно, в том числе между касанием и первой
       буквой. */
    searchFontVar();
    cl.add('lm-search_font');
    /* Список мог быть выключен предыдущим закрытием — включаем обратно. */
    cl.remove('lm-search_off');

    /* Раздвигаем один раз. Дальше на каждую букву только освежаем замеры:
       иначе на каждое нажатие вешался бы свой отложенный подъём страницы,
       и они складывались бы — ровно та беда, из-за которой в этом скрипте
       запрещена плавная прокрутка. */
    if (cl.contains('lm-search_wide')) {
      searchVars();
      ensureQsClose();
      return;
    }

    if (!searchVars()) return;
    cl.add('lm-search_qs');
    cl.add('lm-search_wide');
    ensureQsClose();

    /* Замер и подкрутка — следующим кадром: раздвижка поля меняет
       раскладку, и мерить надо уже её. Порядок внутри важен: сколько
       места осталось списку, зависит от того, куда уехала страница. */
    setTimeout(function () {
      if (!document.documentElement.classList.contains('lm-search_wide')) return;
      guard('searchLiftPage', searchLiftPage)();
      guard('searchVars', searchVars)();
      guard('ensureQsClose', ensureQsClose)();
    }, CFG.searchLift);
  }

  function searchClose() {
    if (srchTimer) return;
    srchTimer = setTimeout(function () {
      srchTimer = null;
      /* Фокус мог вернуться, пока мы ждали. Полей два — в шапке и на
         странице большого поиска. */
      var a = document.activeElement;
      if (a && (a === searchInput() || isBigSearchField(a))) return;
      var cl = document.documentElement.classList;
      cl.remove('lm-search_wide');
      cl.remove('lm-search_font');
      cl.remove('lm-search_big');
    }, CFG.searchHold);
  }

  function isSearchField(t) {
    return !!(t && t.tagName === 'INPUT' && t.closest &&
              t.closest('.b-header_search, #js-header_search_form'));
  }

  /* Строка со счётом результатов. «По вашему запросу найдено 0 постов и 0
     комментариев» на телефоне переносится на две строки, а первые три
     слова не сообщают ничего: и так понятно, по чьему запросу. Убираем их
     — остаток встаёт в одну строку.

     Правим текстовый узел, а не прячем правилом: узел голый, лежит прямо
     в .b-results_filter рядом со счётчиками, и селектором его не взять.
     Строку лепра переписывает заново при каждом ответе сервера, поэтому
     проход повторяемый — он трогает только то, что ещё не поправлено. */
  function shortenSearchStats() {
    var box = document.querySelector('.b-results_filter');
    if (!box) return;
    for (var n = box.firstChild; n; n = n.nextSibling) {
      if (n.nodeType !== 3) continue;
      var t = n.nodeValue;
      if (t.indexOf('По вашему запросу') < 0) continue;
      n.nodeValue = t.replace(/\s*По вашему запросу\s+найдено\s*/, 'Найдено ');
    }
  }

  /* --- строка запроса на странице большого поиска --- */

  /* Другое поле и другая задача. Динамического списка у него нет, значит
     мерить верх и высоту нечему; нужно только раздвинуть его до кромок и
     увести страницу наверх, чтобы клавиатура не выдавливала форму. */
  function bigSearchInput() {
    return document.querySelector('#js-search .b-search_header input[type="text"]');
  }

  function isBigSearchField(t) {
    return !!(t && t.tagName === 'INPUT' && t.closest &&
              t.closest('#js-search .b-search_header'));
  }

  function bigSearchType() {
    if (!CFG.searchWide) return;
    var inp = bigSearchInput();
    if (!inp) return;
    var cl = document.documentElement.classList;
    if (cl.contains('lm-search_big')) return;   /* раздвигаем один раз */

    var r = inp.getBoundingClientRect();
    var W = document.documentElement.clientWidth || window.innerWidth || 0;
    if (!r.width || !W) return;
    /* Тянем в обе стороны: поле стоит посреди колонки, и отступы слева и
       справа свои у каждой страницы (подсайт, масштаб, полоса прокрутки). */
    var st = document.documentElement.style;
    st.setProperty('--lm-big-l',
      '-' + Math.max(0, Math.round(r.left) - CFG.pageEdge) + 'px');
    st.setProperty('--lm-big-r',
      '-' + Math.max(0, Math.round(W - r.right) - CFG.pageEdge) + 'px');
    cl.add('lm-search_big');

    setTimeout(function () {
      if (document.documentElement.classList.contains('lm-search_big'))
        guard('searchLiftPage', searchLiftPage)(bigSearchInput());
    }, CFG.searchLift);
  }

  function watchSearch() {
    if (!CFG.searchWide || srchWatched) return;
    srchWatched = true;

    /* Касание, а не только фокус: кегль надо поднять ДО того, как Safari
       решит приближать страницу, а решает он это по нажатию. Обработчик
       на документе и в фазе перехвата — поле переезжает между шапкой и
       навигационной штукой, и вешать слушателя на него самого значило бы
       вешать заново после каждого переноса. */
    document.addEventListener('touchstart', function (e) {
      if (isSearchField(e.target)) guard('searchOpen', searchOpen)();
    }, true);
    document.addEventListener('focusin', function (e) {
      if (isSearchField(e.target)) guard('searchOpen', searchOpen)();
    }, true);
    document.addEventListener('focusout', function (e) {
      if (isSearchField(e.target) || isBigSearchField(e.target))
        guard('searchClose', searchClose)();
    }, true);

    /* Тап мимо поиска закрывает список. Слушаем и касание, и нажатие:
       касание — чтобы закрыть до того, как палец отпустят, нажатие — для
       мыши и для случаев, когда касание до нас не доходит.
       Ничего не отменяем: тап мимо остаётся обычным тапом, он и по ссылке
       может прийтись. Мы только убираем за собой. */
    ['touchstart', 'click'].forEach(function (kind) {
      document.addEventListener(kind, function (e) {
        var cl = document.documentElement.classList;
        if (!cl.contains('lm-search_qs') || cl.contains('lm-search_off')) return;
        if (!outsideSearch(e.target)) return;
        guard('searchDismiss', searchDismiss)();
      }, true);
    });

    /* Крестик живёт в контейнере, который лепра наполняет заново на каждой
       букве. Ставим его и по вводу тоже — на случай, если она перепишет
       контейнер целиком. */
    /* Ввод — то самое мгновение, ради которого всё и затевалось: список
       у лепры появляется именно с первой буквы. Слушаем каждую, а не
       только первую: searchType сам различает первый раз и последующие,
       а стирание текста до пустого поля список закрывает — и следующая
       буква должна открыть его заново. */
    document.addEventListener('input', function (e) {
      if (isSearchField(e.target)) { guard('searchType', searchType)(); return; }
      if (isBigSearchField(e.target)) guard('bigSearchType', bigSearchType)();
    }, true);

    /* Клавиатура выезжает и уезжает не мгновенно, и всё это время высота
       видимой части меняется, а resize у window молчит: окно-то прежнее. */
    if (window.visualViewport)
      window.visualViewport.addEventListener('resize', function () {
        var vv = window.visualViewport;
        var cl = document.documentElement.classList;
        if (cl.contains('lm-search_big')) {
          if (vv.height < (window.innerHeight || 0) * 0.8)
            guard('searchLiftPage', searchLiftPage)(bigSearchInput());
          return;
        }
        if (!cl.contains('lm-search_wide')) return;
        /* Крутим только когда клавиатура ПОДНЯЛАСЬ: то же событие приходит
           и когда она уходит, и подкрутка на прощание дёрнула бы страницу
           уже без всякой пользы. Признак — видно заметно меньше окна. */
        if (vv.height < (window.innerHeight || 0) * 0.8)
          guard('searchLiftPage', searchLiftPage)();
        guard('searchVars', searchVars)();
      });
  }


  /* ============================================================
     СТРАНИЦА «МОИ ВЕЩИ»
     ============================================================ */

  /* Панель фильтров — два абзаца сплошного инлайнового потока. На узком
     экране вводная фраза занимала две строки, а подпись чекбокса
     переносилась под сам чекбокс. Фразу сокращаем, чекбокс с подписью
     заворачиваем в отдельную флекс-строку: перенос подписи тогда идёт
     по её собственному краю, а не по краю колонки. */
  /* Подписи пунктов, вариантов сортировки и ссылок подпанели рассчитаны
     на десктопную строку шириной в семьсот пикселей. На телефоне под ту
     же строку остаётся треть экрана, и каждая лишняя буква — это перенос
     на вторую строку. Длинные варианты заменяем короткими, полный текст
     уходит в подсказку. Меняется только видимая надпись: value полей
     выбора лепра шлёт на сервер, его не трогаем нигде.

     Замена по точному совпадению, а не по вхождению: в панели фильтров
     лежит вводная фраза «моих вещей», и она должна остаться как есть.
     По той же причине безопасно проходить и по текстовым узлам:
     разделители « | » ни с чем не совпадут. */
  var SHORT = [
    /* инбокс */
    [/^по\s+последним\s+комментариям$/i, 'по комментариям'],
    /* мои вещи */
    [/^только\s+новые\s+посты\s+и\s+комментарии$/i, 'только новые'],
    /* избранное */
    [/^по\s+дате\s+поста$/i,          'по посту'],
    [/^по\s+дате\s+добавления$/i,     'по добавлению'],
    [/^публиковать\s+в\s+профайле$/i, 'в профайле'],
    /* чарли: строка ссылок под вкладками */
    [/^подлепрозорий$/i,   'подлепра'],
    [/^почтовый\s+ящик$/i, 'почтовый ящик'],
    [/^игнор-лист$/i,      'игнор-лист'],
    [/^скрытые\s+посты$/i, 'скрытое']
  ];

  function shortLabel(s) {
    var t = (s || '').replace(/\u00a0/g, ' ').trim();
    for (var i = 0; i < SHORT.length; i++)
      if (SHORT[i][0].test(t)) return SHORT[i][1];
    return null;
  }

  function shortenIn(box, sel) {
    if (!box) return;
    sliceOf(box.querySelectorAll(sel)).forEach(function (el) {
      /* Только конечные узлы. Если активный пункт окажется ссылкой внутри
         strong, под выборку попадут оба, внешний обработается первым — и
         замена текста снесла бы ссылку вместе с разметкой. */
      if (el.children && el.children.length) return;
      var t = (el.textContent || '').replace(/\u00a0/g, ' ').trim();
      var s = shortLabel(t);
      if (s === null) return;
      /* Подсказку вешаем только когда есть что подсказывать: часть замен
         меняет лишь регистр, и всплывающая копия той же надписи мешает. */
      if (!el.title && s.length < t.length) el.title = t;
      el.textContent = s;
    });
  }

  /* Строка ссылок под вкладками у Чарли: «Подлепрозорий | Почтовый ящик |
     Игнор-лист | Скрытые посты». Текущий раздел лепра выводит не ссылкой,
     а тегом strong с серой подложкой — поэтому обход только по ссылкам
     сокращал три пункта из четырёх, а на открытом разделе возвращалось
     полное название. Берём и то и другое, плюс голые текстовые узлы:
     разметка активного пункта у лепры непостоянна, а точное совпадение
     не даст задеть лишнее.

     Живёт отдельно от панели фильтров: на разделах Чарли обёртки
     .b-my_posts_feed_controls может не быть вовсе, и привязка к ней
     оставила бы страницу без сокращений. */
  function shortenSubNav() {
    sliceOf(document.querySelectorAll('.b-my_posts_feed_controls_navigation'))
      .forEach(function (nav) {
        shortenIn(nav, 'a, strong, b, em, span');
        /* Активный пункт лепра иногда выводит вообще без обёртки — голым
           текстом. Тогда название и следующий за ним разделитель лежат в
           одном текстовом узле, и целиком он ни с чем не совпадёт.
           Поэтому режем узел по вертикальной черте и примеряем замену к
           каждому куску, сохраняя окружающие пробелы: без них пункты
           слиплись бы с разделителями. */
        sliceOf(nav.childNodes).forEach(function (n) {
          if (n.nodeType !== 3) return;
          var hit = false;
          var out = n.nodeValue.split('|').map(function (p) {
            var s = shortLabel(p);
            if (s === null) return p;
            hit = true;
            return p.match(/^\s*/)[0] + s + p.match(/\s*$/)[0];
          });
          if (hit) n.nodeValue = out.join('|');
        });
      });
  }

  function fixMyThings() {
    var box = document.querySelector('.b-my_posts_feed_controls');
    if (!box || box.dataset.lmMyThings) return;
    box.dataset.lmMyThings = '1';

    /* «В ваших вещах — все, к чему вы имели отношение за последние
       [месяц]» — предложение длиной в строку, хотя вся его смысловая
       нагрузка в предлоге перед полем выбора. Полный текст уходит в
       подсказку узла-обёртки ниже. */
    var period = box.querySelector('#js-my_things_period');
    if (period) {
      var t = period.previousSibling;
      while (t && t.nodeType !== 3) t = t.previousSibling;
      if (t && /отношение/.test(t.nodeValue))
        t.nodeValue = 'За ';
    }

    /* Пункты панели фильтров: сама таблица замен и обход — общие,
       см. SHORT и shortenIn выше. */
    shortenIn(box, 'option, label');

    /* Подписи «Показывать» и «Сортировать» занимали больше места, чем сами
       поля, хотя выбранное значение («все», «по дате») и так читается без
       них. Убираем только текстовые узлы с точным совпадением: вводная
       фраза «моих вещей» лежит в этой же строке и должна остаться. */
    var w = document.createTreeWalker(box, NodeFilter.SHOW_TEXT, null, false);
    var caption = [], node;
    while ((node = w.nextNode())) {
      var tag = node.parentNode && node.parentNode.nodeName;
      if (tag === 'SELECT' || tag === 'OPTION') continue;
      if (/^(показывать|сортировать)$/i.test(
            node.nodeValue.replace(/\u00a0/g, ' ').trim()))
        caption.push(node);
    }
    caption.forEach(function (n) { n.parentNode.removeChild(n); });

    /* Пункты панели — инлайновые span'ы, между ними в разметке лежат
       переводы строк. Пробел между инлайновыми элементами рисуется, и к
       заданному отступу молча прибавлялось ещё четыре-пять пикселей.
       Убираем только чисто пробельные узлы, у которых с обеих сторон
       стоит пункт панели: вводная фраза «моих вещей» так не пострадает. */
    sliceOf(box.querySelectorAll('.b-my_posts_feed_controls_item'))
      .forEach(function (it) {
        var n = it.nextSibling;
        if (!n || n.nodeType !== 3 || n.nodeValue.trim()) return;
        var after = n.nextSibling;
        while (after && after.nodeType === 3 && !after.nodeValue.trim())
          after = after.nextSibling;
        if (after && after.nodeType === 1 &&
            after.classList.contains('b-my_posts_feed_controls_item'))
          n.parentNode.removeChild(n);
      });

    /* Отступ чекбокса лепра пишет прямо в атрибут style. Правило с
       !important его перебивает, но убрать источник надёжнее: тогда
       величина интервала видна в одном месте, а не спорит в двух. */
    sliceOf(box.querySelectorAll('input[type="checkbox"][style]'))
      .forEach(function (el) {
        el.style.removeProperty('margin-left');
        if (!el.getAttribute('style')) el.removeAttribute('style');
      });

    /* Чекбокс с подписью сводим в один узел: дальше он идёт по строке
       как единое целое и подпись не отрывается от квадратика.
       Только там, где они лежат прямо в абзаце («мои вещи»). На инбоксе
       их и так держит вместе собственный span лепры, и лишняя обёртка
       там только сдвинула бы их на свои отступы. */
    var chk = box.querySelector('p > input[type="checkbox"]');
    var lab = chk && chk.id && box.querySelector('label[for="' + chk.id + '"]');
    if (chk && lab && chk.parentNode === lab.parentNode) {
      var pair = document.createElement('span');
      pair.className = 'lm-unread_row';
      chk.parentNode.insertBefore(pair, chk);
      pair.appendChild(chk);
      /* между ними лежит &nbsp; — иначе останется висеть пустой строкой */
      var n = pair.nextSibling;
      while (n && n !== lab) {
        var next = n.nextSibling;
        if (n.nodeType === 3 && !n.nodeValue.trim()) n.parentNode.removeChild(n);
        n = next;
      }
      pair.appendChild(lab);
    }

    /* «Мои вещи»: панель разбита на два абзаца — предлог с периодом в
       первом, сортировка с чекбоксом во втором. После сокращения фразы
       обе строки заняты едва наполовину, поэтому сводим их в одну.
       Предлог с полем периода заворачиваем в общий узел: иначе при
       раздаче свободного места предлог уедет к левому краю, а его поле —
       к середине строки, и связь между ними потеряется. */
    if (period && period.parentNode && period.parentNode.nodeName === 'P') {
      var p1 = period.parentNode;
      var grp = document.createElement('span');
      grp.className = 'b-my_posts_feed_controls_item';
      grp.title = 'Всё, к чему вы имели отношение за выбранный срок';
      p1.insertBefore(grp, p1.firstChild);
      var n = grp.nextSibling, done = false;
      while (n && !done) {
        var next = n.nextSibling;
        done = (n === period);
        if (n.nodeType === 3 && !n.nodeValue.trim()) p1.removeChild(n);
        else grp.appendChild(n);
        n = next;
      }

      sliceOf(box.querySelectorAll('p')).forEach(function (p) {
        if (p === p1) return;
        sliceOf(p.childNodes).forEach(function (node) {
          if (node.nodeType === 3 && !node.nodeValue.trim()) return;
          p1.appendChild(node);
        });
        p.parentNode.removeChild(p);
      });
    }

    /* Строки панели бывают двух видов, и обращаться с ними надо
       по-разному. Строка из одних полей (обе на инбоксе, вторая в «моих
       вещах») держится в одну линию и растягивается по ширине. Строка с
       вводной фразой остаётся обычным текстом: поле выбора стоит внутри
       предложения, и превращать её во флекс нельзя — фраза оторвётся от
       поля и встанет отдельным блоком.
       Признак — есть ли среди прямых потомков непробельный текст. */
    sliceOf(box.querySelectorAll('p')).forEach(function (p) {
      var bare = sliceOf(p.childNodes).some(function (n) {
        return n.nodeType === 3 && n.nodeValue.trim();
      });
      var units = p.querySelectorAll(
        'select, .lm-unread_row, .b-my_posts_feed_controls_item').length;
      if (!bare && units > 1) p.classList.add('lm-filters_row');
    });
  }


  /* Подписи вкладок рассчитаны на широкую строку. На телефоне каждая лишняя
     буква — это перенос всего ряда, поэтому две самые длинные сокращаем.
     Число приглашений подставляет сервер, поэтому вытаскиваем его из текста
     и склоняем сами. */
  function pluralRu(n, one, few, many) {
    var a = Math.abs(n) % 100, b = a % 10;
    if (a > 10 && a < 20) return many;
    if (b > 1 && b < 5) return few;
    if (b === 1) return one;
    return many;
  }

  function shortenTabs() {
    document.querySelectorAll('.b-menu_list_link').forEach(function (a) {
      if (a.dataset.lmTab) return;
      var t = (a.textContent || '').replace(/\u00a0/g, ' ').trim();
      if (/приглашени/.test(t)) {
        var m = t.match(/\d+/);
        a.dataset.lmTab = '1';
        a.textContent = m
          ? m[0] + ' ' + pluralRu(+m[0], 'инвайт', 'инвайта', 'инвайтов')
          : 'нет инвайтов';
      } else if (/личная информация/.test(t)) {
        a.dataset.lmTab = '1';
        a.textContent = 'настройки';
      } else if (/профессиональн/i.test(t)) {
        /* Самый длинный пункт меню магазина: 24 знака Verdana плюс место
           под тунца — 219 пикселей из 369, и с ним строка ломалась
           натрое. Подпись лежит текстовым узлом рядом с пустым <i>, в
           котором фоном нарисован тунец, поэтому переписываем сам
           текстовый узел: замена textContent снесла бы <i> с картинкой. */
        var host = a.querySelector('.b-charlie_item') || a;
        var tn = sliceOf(host.childNodes).filter(function (n) {
          return n.nodeType === 3 && n.textContent.trim();
        })[0];
        if (tn) {
          a.dataset.lmTab = '1';
          if (!a.title) a.title = t;
          tn.textContent = 'Проф. аккаунт';
        }
      }
    });
  }


  /* Ширину поля выбора браузер берёт по САМОМУ ДЛИННОМУ пункту списка,
     а показывает выбранный. У сортировки список меряется по «по
     комментариям», а стоит обычно «по времени» — сорок лишних пикселей
     пустоты справа от значения, и так в каждом поле. На широкой строке
     это незаметно, на телефоне из-за этого не помещался чекбокс.
     Считаем ширину по выбранному пункту. Служебную часть поля (стрелка,
     собственные поля, рамка) не угадываем: меряем копию поля вне строки,
     где на неё не действует сжатие, и вычитаем из её ширины ширину
     самого длинного текста. Остаток и есть служебная часть — точно,
     без подгонки под конкретный браузер. */
  function textWidth(probe, s) {
    probe.textContent = s;
    return probe.getBoundingClientRect().width;
  }

  function fitSelect(sel) {
    if (!sel.options || sel.options.length < 2) return;
    var cs = getComputedStyle(sel);

    var probe = document.createElement('span');
    probe.style.cssText = 'position:absolute!important;left:-9999px!important;' +
                          'top:0!important;visibility:hidden!important;' +
                          'white-space:pre!important';
    probe.style.fontFamily = cs.fontFamily;
    probe.style.fontSize = cs.fontSize;
    probe.style.fontWeight = cs.fontWeight;
    probe.style.fontStyle = cs.fontStyle;
    probe.style.letterSpacing = cs.letterSpacing;
    document.body.appendChild(probe);

    var widest = 0, cur = 0;
    for (var i = 0; i < sel.options.length; i++) {
      var t = sel.options[i].textContent || '';
      var wt = textWidth(probe, t);
      if (wt > widest) widest = wt;
      if (i === sel.selectedIndex) cur = wt;
    }
    probe.parentNode.removeChild(probe);
    if (!widest) return;

    /* Служебная часть постоянна для поля — считаем её один раз. */
    var chrome = parseFloat(sel.dataset.lmChrome);
    if (!(chrome >= 0)) {
      var copy = sel.cloneNode(true);
      copy.removeAttribute('id');
      copy.style.cssText = 'position:absolute!important;left:-9999px!important;' +
                           'top:0!important;visibility:hidden!important;' +
                           'width:auto!important;max-width:none!important;' +
                           'min-width:0!important;flex:none!important';
      document.body.appendChild(copy);
      chrome = copy.getBoundingClientRect().width - widest;
      copy.parentNode.removeChild(copy);
      if (!(chrome >= 0)) return;
      sel.dataset.lmChrome = chrome;
    }

    sel.dataset.lmWidth = '1';
    sel.style.setProperty('width', Math.ceil(cur + chrome) + 'px', 'important');
  }

  /* Вызывается на каждом полном проходе: шрифт мог догрузиться и сместить
     замеры, а выбранное значение — смениться. Считать дёшево: полей два,
     обходов списка столько же. */
  function fitSelects() {
    sliceOf(document.querySelectorAll(
        '.lm-filters_row select, .b-users_list_filters select'))
      .forEach(function (sel) {
        fitSelect(sel);
        if (sel.dataset.lmFitBound) return;
        sel.dataset.lmFitBound = '1';
        sel.addEventListener('change', function () { fitSelect(sel); });
      });
  }

  /* Строка фильтров при масштабе страницы 110% и выше перестаёт помещаться
     и переносит чекбокс на вторую строку. Считать заранее нечего: ширина
     полей зависит от выбранных пунктов, а доступная — от масштаба, который
     скрипту не виден. Поэтому меряем по факту — по вертикальной отбивке
     между первым и последним пунктом — и ужимаем ступенями, пока не сойдётся.
     Ступень применяется только если она помогла: иначе панель мельчала бы
     впустую там, где не помещается ничто. */
  function rowWrapped(row) {
    var k = row.children;
    if (k.length < 2) return false;
    return k[k.length - 1].getBoundingClientRect().top -
           k[0].getBoundingClientRect().top > 4;
  }

  function fitFiltersRow() {
    var row = document.querySelector('.b-my_posts_feed_controls p.lm-filters_row');
    if (!row) return;
    /* До загрузки шрифта ширины подписей другие, и мерить рано: строка
       могла бы «не поместиться» на ровном месте, а укороченная подпись
       обратно уже не вернётся. */
    if (document.fonts && document.fonts.status !== 'loaded') return;
    if (!rowWrapped(row)) return;

    /* Ступень первая: подпись чекбокса. Полный текст уже лежит в подсказке,
       а фильтр в этой панели ровно один — «новые» ни с чем не спутать. */
    var lab = row.querySelector('.lm-unread_row label');
    if (lab && (lab.textContent || '').trim() !== 'новые') {
      lab.textContent = 'новые';
      if (!rowWrapped(row)) return;
    }

    /* Ступень вторая: кегль всей панели. Поля выбора после этого надо
       обмерить заново — их ширину скрипт задаёт в пикселях по выбранному
       пункту, и от прежнего кегля она осталась бы великовата. */
    var box = row.closest('.b-my_posts_feed_controls');
    if (box && box.dataset.lmSmall !== '1') {
      box.dataset.lmSmall = '1';
      box.style.setProperty('font-size', '92%', 'important');
      fitSelects();
      if (!rowWrapped(row)) return;
    }

    /* Дальше ужимать нечем: перенос честнее подрезанного текста. */
  }


  /* ============================================================
     ПОДПИСИ ПОСТОВ И ВЕТОК
     ============================================================ */

  function pad2(n) { return (n < 10 ? '0' : '') + n; }

  /* Русское склонение по числу. Три формы: 1 комментарий, 2 комментария,
     5 комментариев. Одиннадцать-четырнадцать — исключение, они берут
     последнюю форму независимо от последней цифры. */
  function plural(n, one, few, many) {
    var d10 = n % 10, d100 = n % 100;
    if (d100 >= 11 && d100 <= 14) return many;
    if (d10 === 1) return one;
    if (d10 >= 2 && d10 <= 4) return few;
    return many;
  }

  function clock(d) { return pad2(d.getHours()) + '.' + pad2(d.getMinutes()); }

  function dateFull(d) {
    return pad2(d.getDate()) + '.' + pad2(d.getMonth() + 1) + '.' +
           String(d.getFullYear()).slice(2) + ' в ' + clock(d);
  }

  /* Человеческая дата для сокращённой подписи.

     Ровно пять ступеней, других нет:
       только что       — меньше часа
       час назад        — второй час
       сегодня в hh.mm
       вчера в hh.mm
       dd.mm.yy в hh.mm

     «Два часа назад» и «три часа назад» были и убраны: они длиннее, чем
     «сегодня в 12.00», ради которого ступень часов и заводилась. Час —
     единственный случай, где словами короче.

     Минутная ступень («5 минут назад») была и убрана по просьбе. Ценой
     тому — «только что» длиной в час: сорокаминутной давности запись
     подписана так же, как минутной. Это осознанный размен на короткую
     строку, а не недосмотр.

     Дни недели («во вторник в 12.00») тоже были и тоже убраны: это была
     самая длинная запись из всех возможных, длиннее полной даты, ради
     которой всё и затевалось.

     «Сегодня» и «вчера» считаются по КАЛЕНДАРНОМУ дню, а не по «меньше
     суток назад». В час ночи запись пятичасовой давности сделана вчера
     вечером, и «сегодня в 20.00» было бы враньём — поэтому после
     ступени часов сравниваем номера дней, а не разницу в секундах.

     now передаётся отдельным доводом ради проверки: иначе таблицу
     случаев пришлось бы гонять по настоящим часам. */
  function humanDate(epoch, now) {
    var d = new Date(epoch * 1000);
    if (isNaN(d.getTime())) return '';
    var n = now ? new Date(now) : new Date();
    var diff = Math.floor((n.getTime() - d.getTime()) / 1000);

    /* Часы устройства могут отставать от серверных, и тогда свежая
       запись оказывается «из будущего». Показывать отрицательное время
       незачем — это просто «только что». */
    if (diff < 3600) return 'только что';

    if (diff < 7200) return 'час назад';

    /* Номер календарного дня: полночь по местному времени. */
    var day = function (x) {
      return Math.floor(new Date(x.getFullYear(), x.getMonth(), x.getDate()).getTime() / 86400000);
    };
    var back = day(n) - day(d);

    if (back <= 0) return 'сегодня в ' + clock(d);
    if (back === 1) return 'вчера в ' + clock(d);
    return dateFull(d);
  }

  /* Дата в подписи — человеческая. Точная остаётся в подсказке: леприн
     текст («20 Августа 2026 в 21.29») там информативнее нашего
     dd.mm.yy, и терять его незачем.

     Некоторое время оба вида лежали в разметке разными спанами, а
     показывал нужный класс на html: предполагалась настройка «полная /
     сокращённая». Настройки не стало — сокращённый вид оказался лучше
     во всех случаях, — и второй спан вместе с ней: на треде в четыреста
     комментариев это четыреста лишних узлов ради вида, который никто не
     увидит.

     Сторожим не меткой, а сравнением с тем, что записали. Лепра
     переписывает содержимое .js-date своим скриптом; при обычной метке
     после такой перезаписи дата навсегда застыла бы в лепровском виде —
     метка на месте, значит «уже сделано». Сравнение это ловит: текст не
     наш, стало быть надо переписать. */
  function shortenDate(el) {
    var epoch = parseInt(el.getAttribute('data-epoch_date'), 10);
    if (!epoch) return;
    var d = new Date(epoch * 1000);
    if (isNaN(d.getTime())) return;

    var soft = humanDate(epoch);
    if (!soft || el.dataset.lmDate === el.textContent) return;

    var txt = (el.textContent || '').trim();
    if (txt) el.title = txt;
    el.textContent = soft;
    el.dataset.lmDate = soft;
  }

  /* Подпись поста занимала две широких строки. Сокращаем: домен без
     хвоста .leprosorium.ru, дата числами, длинные ссылки — значками. */
  /* Таблица глифов подписи (⊕ ⊖ ☆ ★) отсюда убрана: все значки обоймы
     теперь рисуются вектором одним пером — см. ICON_BODY и vectorIcons
     выше. */

  /* «129 комментариев / 2 новых» -> «129 / 2 новых».
     Если новых нет — остаётся «129 комментариев».
     Если все новые, лепра пишет «777 новых комментариев» -> «777 комментариев». */
  function compactCommentCount(ddi) {
    var total = null, fresh = null;

    sliceOf(ddi.querySelectorAll('a')).forEach(function (a) {
      var t = (a.textContent || '').trim();
      if (/^\d+\s+нов/.test(t)) fresh = a;
      else if (/^\d+\s+комментари/.test(t)) total = a;
    });

    var num = function (el) {
      var m = (el.textContent || '').match(/\d+/);
      return m ? m[0] : null;
    };

    /* Жирным выделяем непрочитанное. Лепра делает это то классом
       b-all_new_comments_link, то обёрткой <strong>, а иногда не делает
       вовсе — поэтому проставляем сами, по смыслу. */
    var bold = function (el, on) {
      el.style.setProperty('font-weight', on ? '700' : '400', 'important');
    };

    if (total && fresh) {
      var n = num(total), f = num(fresh);
      if (!n || !f) return;
      total.title = (total.textContent || '').trim();
      total.textContent = n;
      fresh.textContent = f + ' ' + plural(+f, 'новый', 'новых', 'новых');
      bold(total, false);        /* всего — обычным */
      bold(fresh, true);         /* новые — жирным */
      return;
    }

    /* только «N новых комментариев» — значит новые все */
    if (fresh && !total) {
      var k = num(fresh);
      if (!k) return;
      fresh.title = (fresh.textContent || '').trim();
      /* Число лепра склоняет сама, но мы это слово пересобираем и
         обязаны склонять тоже: «24 комментариев» вылезало именно
         отсюда. */
      fresh.textContent = k + ' ' +
        plural(+k, 'комментарий', 'комментария', 'комментариев');
      bold(fresh, true);         /* все непрочитаны — жирным целиком */
      return;
    }

    /* только «N комментариев» — новых нет, выделять нечего */
    if (total && !fresh) bold(total, false);
  }

  /* Значок «только новые комментарии» — свой, лепра такого не даёт.
     Ведёт на тот же пост с фильтром ?unread=on, и ведёт ВСЕГДА, даже
     когда новых в посте нет: ссылка «N новых» появляется у лепры только
     при непрочитанном, а зайти в пост с этим фильтром бывает нужно и
     после того, как счётчик обнулился.

     Рисунок — облачко реплики с точкой внутри: «комментарии, а в них
     новое». Рисуем сами, а не берём готовый глиф, по той же причине,
     что и у стрелки ответа: у подходящих символов Юникода есть
     эмодзи-начертание, и iOS показывает цветную наклейку вместо знака
     в тон подписи.

     Обводка, а не заливка: толщина линии не зависит от того, как
     сложится путь, и значок остаётся ровным на любом размере — в строке
     он 14 пикселей, во всплывающем столбике 18. currentColor — чтобы
     брать цвет подписи и не краситься отдельно в тёмной теме. */
  var UNREAD_SVG =
    '<svg viewBox="0 0 20 20" fill="none" stroke="currentColor"' +
    ' stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"' +
    ' aria-hidden="true">' +
    '<rect x="2.6" y="3.4" width="14.8" height="10.4" rx="2.6"/>' +
    '<path d="M6.6 13.8 L6.6 17.4 L10.6 13.8"/>' +
    '<circle cx="10" cy="8.6" r="1.5" fill="currentColor" stroke="none"/>' +
    '</svg>';

  /* Адрес поста. Берём у ссылок на комментарии, а при их отсутствии —
     у значка-странички: на странице самого поста блока ссылок нет, а
     значок есть, и фильтр там тоже к месту.
     Строку запроса и якорь срезаем: у ссылки «N новых» уже стоит
     ?unread=on, и без обрезки вышло бы два вопросительных знака подряд.
     Ссылки-пустышки лепры (href оканчивается на '#') не в счёт — по
     ним никуда не попадёшь. */
  function postUrl(ddi) {
    var a = ddi.querySelector('.b-post_comments_links a[href]') ||
            ddi.querySelector('a.post_icon[href]');
    var u = a && a.getAttribute('href');
    if (!u || u.charAt(u.length - 1) === '#') return '';
    return u.split('#')[0].split('?')[0];
  }

  function unreadIcon(ddi) {
    var base = postUrl(ddi);
    if (!base) return null;
    var a = document.createElement('a');
    a.className = 'lm-unread';
    a.setAttribute('href', base + '?unread=on');
    a.title = 'только новые комментарии';
    a.innerHTML = UNREAD_SVG;
    return a;
  }

  /* Значки лежат в двух обёртках .b-post_controls с разными метриками.
     Собираем их в один свой контейнер: так они становятся соседями по
     флекс-боксу и выравниваются по центру гарантированно. */
  function groupFooterIcons(ddi) {
    /* Только span: у галочки «прочитано» тот же класс b-post_controls,
       но это самостоятельная ссылка. Разбирая её как обёртку, скрипт
       вынимал из неё svg и возвращал пустой остаток — отсюда смещение. */
    var boxes = sliceOf(ddi.querySelectorAll('span.b-post_controls'));

    /* Часть значков (галочка «прочитано» и подобные) лежит не в обёртке,
       а прямо в подписи отдельными элементами со своим svg. Их тоже
       забираем, иначе они остаются со своими метриками и уезжают. */
    var loose = sliceOf(ddi.children).filter(function (el) {
      if (el.classList.contains('lm-icons')) return false;
      if (boxes.indexOf(el) >= 0) return false;   /* это обёртка, её разбирают выше */
      if (el.classList.contains('b-post_pinned_icon')) return false;   /* метка «закреплён» */
      if (el.classList.contains('b-post_comments_links')) return false;
      if (el.classList.contains('js-date')) return false;
      if (el.classList.contains('c_user')) return false;
      if (!/^(A|SPAN)$/.test(el.tagName)) return false;
      if (!el.querySelector('svg')) return false;
      return !(el.textContent || '').trim();      /* только значки без текста */
    });

    if (!boxes.length && !loose.length) return;

    /* Свой значок собираем ДО того, как что-то переехало: адрес поста
       берётся из узлов, которые ниже уходят в обойму, и после переезда
       искать их в подписи было бы уже негде. */
    var unread = unreadIcon(ddi);

    var holder = document.createElement('span');
    holder.className = 'lm-icons';

    boxes.forEach(function (box) {
      sliceOf(box.children).forEach(function (child) { holder.appendChild(child); });
      if (box.parentNode) box.parentNode.removeChild(box);
    });
    loose.forEach(function (el) { holder.appendChild(el); });

    /* Значок-страничка (ссылка на сам пост) лежит в начале подписи и под
       общий отбор не попадает: у него не svg, а фоновая картинка. Берём
       его отдельно и кладём в ту же обойму. В полном виде это меняет его
       место — был в начале строки, стал в конце вместе с прочими
       значками; в сокращённом иначе и нельзя, там вся обойма прячется
       под точку целиком, а один значок снаружи выглядел бы забытым. */
    var icon = ddi.querySelector('.post_icon');
    if (icon) holder.appendChild(icon);

    /* Наш значок — последним. Столбик всплывает ВВЕРХ, то есть последний
       в разметке оказывается ближним к точке: под тем самым пальцем,
       которым её только что нажали. */
    if (unread) holder.appendChild(unread);

    wrapMore(ddi, holder);
  }

  /* Значки подписи комментария. Устроены иначе, чем у поста: обёрток
     .b-post_controls тут обычно нет, значки лежат прямо в .ddi
     отдельными ссылками с известными классами. Поэтому берём их по
     списку, а не отбором «ссылка со значком внутри»: в подписи
     комментария такому описанию отвечает и шеврон сворачивания ветки, а
     он никуда переезжать не должен — у него своё место и своя судьба
     (в сокращённом виде он прячется). */
  /* .c_show_user в список не входит намеренно: это декоративная точка
     лепры, на телефоне она рисуется случайным глифом. В подписи поста мы
     её давно прячем, а в подписи комментария она осталась — и рядом с
     нашей точкой-кнопкой две точки подряд читались бы как одна
     сломанная. Прячем и здесь, правилом внизу файла. */
  /* ---- Векторные значки подписи ----

     Всё, что лежит под точкой, нарисовано здесь и одним пером: контур,
     currentColor, система координат 20 на 20, скруглённые концы. До
     этого в обойме соседствовали три разные породы значков — текстовые
     глифы (⊕, ☆, ×, ↑), фоновые картинки (post-icon.gif, спрайт) и
     собственные svg лепры сплошной заливкой, — и в столбике они стояли
     каждый своего роста, веса и цвета.

     Почему не глифы. У ⊕, ☆ и прочих в Юникоде есть эмодзи-начертание,
     и iOS показывает цветную наклейку вместо знака в тон подписи; кроме
     того, каждый шрифт сажает их на свою высоту, и центрировать в
     коробке приходилось бы подбором. Та же причина, по которой «ответить»
     стало значком, — см. REPLY_SVG.

     Почему контур, а не заливка. У обводки толщина линии не зависит от
     того, как сложится путь, и значок остаётся ровным на любом размере:
     в строке он 14 пикселей, во всплывающем столбике 18.

     currentColor — чтобы значок брал цвет подписи и не пришлось красить
     его отдельно в тёмной теме и в обратном наборе тонов.

     «Похожесть» соблюдена намеренно: плюс и минус в кружке — это те же
     ⊕ и ⊖, что стояли раньше; звёздочка пустая и залитая — те же ☆ и ★;
     стрелка вверх, крестик, страничка, галочка и стрелка из лотка
     повторяют то, что рисовала лепра. Человек не должен переучиваться. */
  var ICON_STAR =
    'M10.00 2.90 L11.85 7.75 L17.04 8.01 L13.00 11.27 L14.35 16.29' +
    ' L10.00 13.45 L5.65 16.29 L7.00 11.27 L2.96 8.01 L8.15 7.75 Z';

  var ICON_BODY = {
    /* в мои вещи / из моих вещей — плюс и минус в кружке */
    interest_in:  '<circle cx="10" cy="10" r="7"/>' +
                  '<path d="M10 6.6 V13.4 M6.6 10 H13.4"/>',
    interest_out: '<circle cx="10" cy="10" r="7"/><path d="M6.6 10 H13.4"/>',
    /* в избранное / из избранного — звезда пустая и залитая */
    fav_in:  '<path d="' + ICON_STAR + '"/>',
    fav_out: '<path d="' + ICON_STAR + '" fill="currentColor"/>',
    /* скрыть. Толщина своя, 2.1 вместо общей 1.8: две диагонали
       размываются сглаживанием сильнее прямых линий, и на четырнадцати
       пикселях крестик выходил заметно бледнее соседей. */
    close:  '<path stroke-width="2.1" d="M6 6 L14 14 M14 6 L6 14"/>',
    /* к родительскому комментарию — стрелка вверх (была глифом ↑) */
    parent: '<path d="M10 16.2 V4.4 M5.2 9.2 L10 4.4 L14.8 9.2"/>',
    /* ссылка на сам пост или комментарий — листок с загнутым углом.
       Строчек внутри нет намеренно: на четырнадцати пикселях они
       сливались в серое пятно и листок переставал читаться листком. */
    post:   '<path d="M5.2 2.9 H11.4 L14.8 6.3 V17.1 H5.2 Z"/>' +
            '<path d="M11.2 3 V6.4 H14.7"/>',
    /* пометить прочитанным — галочка в кружке */
    read:   '<circle cx="10" cy="10" r="7"/>' +
            '<path d="M6.6 10.2 L9 12.6 L13.6 7.6"/>',
    /* поделиться — стрелка вверх из лотка, как у лепры */
    share:  '<path d="M10 12.8 V4.2"/><path d="M6.7 7.5 L10 4.2 L13.3 7.5"/>' +
            '<path d="M5.2 11.4 V16 H14.8 V11.4"/>'
  };

  function iconSvg(name) {
    var body = ICON_BODY[name];
    if (!body) return '';
    return '<svg class="lm-ico" viewBox="0 0 20 20" fill="none"' +
           ' stroke="currentColor" stroke-width="1.8"' +
           ' stroke-linecap="round" stroke-linejoin="round"' +
           ' aria-hidden="true">' + body + '</svg>';
  }

  /* Какой значок какому узлу. Список общий на пост и комментарий:
     половина классов встречается и там, и там, а держать два почти
     одинаковых перечня — верный способ однажды поправить один и забыть
     про другой.
     Порядок важен: .b-icon_button_close должен опознаться РАНЬШЕ
     .b-controls_button, потому что крестик носит оба класса сразу, а
     .b-controls_button — это ещё и обёртка под спрайт. */
  var ICON_MAP = [
    ['.b-post_my_post_controls_button_in_interest',    'interest_in'],
    ['.b-post_my_post_controls_button_out_interest',   'interest_out'],
    ['.b-post_my_post_controls_button_in_favourites',  'fav_in'],
    ['.b-post_my_post_controls_button_out_favourites', 'fav_out'],
    ['.b-icon_button_close',    'close'],
    ['.b-mark_as_read_control', 'read'],
    ['.b-button_share',         'share'],
    ['.c_parent',               'parent'],
    ['.post_icon',              'post'],
    ['.c_icon',                 'post']
  ];

  /* Перерисовка. Меняем СОДЕРЖИМОЕ узла, а не сам узел: на узле висят
     обработчики лепры (пометить прочитанным, добавить в избранное), и
     подменять его нельзя — тот же приём и по той же причине, что в
     iconifyAnswer.

     Полный текст уходит в title: у части значков он был единственным
     пояснением («в мои вещи»), и после замены на картинку от него не
     должно остаться пусто.

     Идемпотентность по нашей же метке, а не по длине текста: после
     первой замены текста в узле нет вовсе, и проверка «текст короче
     трёх знаков» пропустила бы узел навсегда — но и любой чужой
     значок тоже. Метка отвечает ровно на тот вопрос, который задан.

     Шеврон сворачивания ветки не трогаем: он носит класс
     .b-post_my_post_controls_button, под отбор не попадает, но лежит
     рядом — оговорка на случай, если список однажды расширят. */
  function vectorIcons(root) {
    for (var i = 0; i < ICON_MAP.length; i++) {
      var sel = ICON_MAP[i][0], name = ICON_MAP[i][1];
      var list = root.querySelectorAll(sel);
      for (var j = 0; j < list.length; j++) {
        var el = list[j];
        if (el.querySelector('svg.lm-ico')) continue;
        if (el.closest('.b-comment_thread_collapse')) continue;
        var text = (el.textContent || '').replace(/\s+/g, ' ').trim();
        if (text && !el.title) el.title = text;
        el.classList.add('lm-ico_host');
        el.innerHTML = iconSvg(name);
      }
    }
  }

  var C_ICONS = ['.c_icon', '.c_parent', '.b-button_share',
                 '.b-icon_button_close', '.b-controls_button'];

  /* «Ответить» словом занимало в подписи больше места, чем голосовалка.
     Заменяем значком — стрелка с крючком, привычная по почте и
     мессенджерам.

     Рисуем сами, а не берём символ ↩ (U+21A9): у него в Юникоде есть
     эмодзи-начертание, и iOS по умолчанию показывает именно его —
     цветную картинку не в тон подписи. Заставить показать текстовый
     вариант можно только добавочным символом-модификатором, и полагаться
     на это в интерфейсе не хочется.

     Обводка, а не заливка: у обводки толщина линии не зависит от того,
     как сложится путь, и значок остаётся ровным на любом размере.
     currentColor — чтобы значок брал цвет подписи и не пришлось красить
     его отдельно в тёмной теме. */
  var REPLY_SVG =
    '<svg viewBox="0 0 20 20" fill="none" stroke="currentColor"' +
    ' stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"' +
    ' aria-hidden="true">' +
    '<path d="M8 5 L3 10 L8 15"/>' +
    '<path d="M3.6 10 H10 a6 6 0 0 1 6 6"/></svg>';

  function iconifyAnswer(footer) {
    var a = footer.querySelector('.c_answer');
    if (!a || a.querySelector('svg')) return;
    var text = (a.textContent || '').trim();
    if (text) a.title = text;
    a.classList.add('lm-reply');
    a.innerHTML = REPLY_SVG;
  }

  function groupCommentIcons(footer) {
    var ddi = footer.querySelector('.ddi') || footer;
    if (ddi.querySelector('.lm-icons')) return;

    var found = [];
    C_ICONS.forEach(function (sel) {
      sliceOf(ddi.querySelectorAll(sel)).forEach(function (el) {
        if (el.closest('.b-comment_thread_collapse')) return;   /* шеврон не трогаем */
        if (found.indexOf(el) < 0) found.push(el);
      });
    });
    if (!found.length) return;

    var holder = document.createElement('span');
    holder.className = 'lm-icons';
    found.forEach(function (el) { holder.appendChild(el); });

    /* Кладём в .ddi, а не в .c_footer: .ddi объявлен display: contents,
       то есть его дети и так прямые участники строки, зато голосовалка —
       сосед .ddi — остаётся после обоймы, как и была. Положи мы обойму в
       подвал, она встала бы ЗА голосовалкой. */
    wrapMore(ddi, holder);
  }

  /* Обойма значков и точка рядом с ней. В полном виде видна обойма, в
     сокращённом — точка, а обойма всплывает по нажатию столбиком.
     Оба узла есть в разметке всегда: переключение вида — это класс на
     html, и перестраивать под него страницу не надо.

     Точка — кнопка, а не ссылка: у ссылки лепра перехватывает нажатия
     на уровне документа, и наш обработчик пришлось бы обходить её. */
  function wrapMore(host, holder) {
    var box = document.createElement('span');
    box.className = 'lm-more_box';

    var dot = document.createElement('button');
    dot.type = 'button';
    dot.className = 'lm-more';
    dot.setAttribute('aria-label', 'остальные значки');
    dot.setAttribute('aria-expanded', 'false');

    box.appendChild(dot);
    box.appendChild(holder);
    host.appendChild(box);
  }

  /* Закрытие по нажатию мимо. Слушатель один на документ, а не по одному
     на каждую точку: подписей на странице сотни, и трёхсот слушателей
     ради одного всплывающего столбика было бы много.
     Ставится один раз; nажатие по самой точке переключает её, нажатие по
     значку внутри столбика оставляет его открытым (иначе значок закрылся
     бы раньше, чем сработал), всё прочее — закрывает всё. */
  var moreBound = false;

  /* Открытый столбик всплывает над соседними записями, а соседи у лепры
     позиционированы (.post и .c_i — position: relative). У позиционированных
     соседей своя очередь отрисовки, и следующий по разметке рисуется ПОВЕРХ
     предыдущего независимо от z-index внутри него: столбик у нижнего края
     поста оказывается под следующим постом, и снаружи это выглядит как
     «точка не нажимается».
     Поднимаем не сам столбик, а запись, в которой он живёт: только у неё
     есть шанс встать выше соседей. Возвращаем как было при закрытии —
     оставленный z-index у каждой второй записи разложил бы ленту слоями. */
  function moreLift(box, on) {
    var host = box.closest('.post, .comment');
    if (!host) return;
    if (on) {
      host.style.setProperty('position', 'relative', 'important');
      host.style.setProperty('z-index', '29', 'important');
    } else {
      host.style.removeProperty('z-index');
      host.style.removeProperty('position');
    }
  }

  function moreShut(box) {
    if (!box) return;
    box.classList.remove('lm-on');
    var d = box.querySelector('.lm-more');
    if (d) d.setAttribute('aria-expanded', 'false');
    moreLift(box, false);
  }

  function watchMore() {
    if (moreBound || !document.body) return;
    moreBound = true;
    document.addEventListener('click', function (e) {
      var dot = e.target.closest && e.target.closest('.lm-more');
      var open = document.querySelector('.lm-more_box.lm-on');
      if (dot) {
        e.preventDefault();
        e.stopPropagation();
        var box = dot.parentElement;
        var was = box.classList.contains('lm-on');
        if (open && open !== box) moreShut(open);
        if (was) { moreShut(box); return; }
        box.classList.add('lm-on');
        dot.setAttribute('aria-expanded', 'true');
        moreLift(box, true);
        return;
      }
      if (!open) return;
      if (e.target.closest && e.target.closest('.lm-more_box')) return;
      moreShut(open);
    }, true);
  }

  /* Даты в подписях комментариев — тот же краткий формат, что и у постов. */
  /* Где лежат комментарии. На странице треда это #js-comments — обёртка
     со ступеньками веток и панелью навигации. Но точно такие же
     комментарии лепра показывает списком на /my/comments/,
     /users/<кто>/comments/ и /users/<кто>/favs/, и там #js-comments нет
     вовсе: комментарии лежат прямо в #js-comments_holder.

     Раньше всё было привязано к #js-comments — и обходы, и три десятка
     правил, — поэтому на страницах-списках подписи оставались
     лепровскими: ни человеческой даты, ни точки со значками, ни наших
     кнопок голосования. Ровно то расхождение, про которое речь.

     Общим оказался holder: на треде он вложен внутрь #js-comments, на
     списках стоит сам по себе. Селекторы переведены на него все разом —
     вес тот же (один идентификатор), а совпадают они теперь везде. */
  function commentsHost() {
    return document.getElementById('js-comments_holder') ||
           document.getElementById('js-comments');
  }

  /* Подписи комментариев: дата в двух видах и обойма значков.
     Метка ставится на подвал, а не на дату: раньше помечалась дата, и
     обойму пришлось бы сторожить отдельной меткой. Один узел — одно
     решение «уже разобрано».
     Проверка на .lm-icons внутри groupCommentIcons всё равно нужна: на
     догруженных ветках подвал новый, а сработать проход может дважды. */
  /* Подпись комментария в две строки — по образцу подписи поста.
     Первая: «Написал» и имя. Вторая: голосовалка, дата, значок ответа,
     точка со значками.

     Разбиение отдельной функцией, а не общей с постом: у поста строки
     собираются внутри .ddi, а тут .ddi объявлен display: contents и сам
     по себе не коробка — строки приходится вешать на .c_footer, а
     содержимое вынимать из .ddi. Списки того, что уходит во вторую
     строку, тоже разные. Общая функция получилась бы из сплошных
     «если пост — то так, иначе эдак», а это не общность, а два разных
     алгоритма в одном теле. */
  var CFOOT_ROW2 = ['.vote', '.c_date', '.c_answer', '.lm-more_box'];

  function splitCommentFooter(footer) {
    if (footer.querySelector('.lm-fline')) return;

    var r1 = document.createElement('span');
    r1.className = 'lm-fline lm-fline__1';
    var r2 = document.createElement('span');
    r2.className = 'lm-fline lm-fline__2';

    CFOOT_ROW2.forEach(function (sel) {
      sliceOf(footer.querySelectorAll(sel)).forEach(function (el) {
        if (el.closest('.lm-fline')) return;
        r2.appendChild(el);
      });
    });

    /* Остальное — в первую строку. Забираем и то, что лежит прямо в
       подвале, и то, что внутри .ddi: коробки из неё всё равно нет, а
       после переноса она останется пустой и никому не помешает. */
    var rest = sliceOf(footer.childNodes);
    var ddi = footer.querySelector('.ddi');
    if (ddi) rest = rest.concat(sliceOf(ddi.childNodes));
    rest.forEach(function (n) {
      if (n === r1 || n === r2) return;
      if (n.nodeType === 1 && n.classList.contains('ddi')) return;
      if (n.nodeType === 3 && !n.nodeValue.replace(/[\s\u00a0]/g, '')) {
        if (n.parentNode) n.parentNode.removeChild(n);
        return;
      }
      r1.appendChild(n);
    });

    footer.appendChild(r1);
    footer.appendChild(r2);
  }

  function compactCommentFooters() {
    var host = commentsHost();
    if (!host) return;
    host.querySelectorAll('.c_footer').forEach(function (foot) {
      if (seen.footer.has(foot)) return;
      seen.footer.add(foot);
      foot.querySelectorAll('.js-date').forEach(shortenDate);
      iconifyAnswer(foot);
      vectorIcons(foot);
      groupCommentIcons(foot);
      splitCommentFooter(foot);
    });
  }

  /* Голосовалка лежит соседом подписи, а не внутри неё: у лепры это два
     блока в .dd, и голосовалка выведена из потока в левую колонку.
     Переносим её первым элементом в саму строку подписи — там она
     становится обычным соседом остальных и подчиняется тем же правилам
     переноса и выравнивания (подробности в CSS, у правила .dd).

     Идемпотентность здесь бесплатная: после переноса узел уже не
     ребёнок .dd, и второй вызов просто не найдёт, что переносить.
     Перебираем прямых детей, а не querySelector: класс vote носит и
     голосовалка комментария, а в поисках по всему поддереву на странице
     треда нашлась бы чужая. */
  function moveVoteToFooter(ddi) {
    var dd = ddi.parentElement;
    if (!dd || !dd.classList.contains('dd')) return;
    var vote = null;
    sliceOf(dd.children).forEach(function (el) {
      if (!vote && el.classList && el.classList.contains('vote')) vote = el;
    });
    if (!vote) return;
    ddi.insertBefore(vote, ddi.firstChild);
  }

  /* Подпись поста в две строки.

     Первая — только про то, кто и когда: метка закрепа, «Написал звание
     имя», дата. Вторая — про то, что с постом делать и что с ним уже
     сделали: голосовалка, подлепра, звёздочки, счётчик комментариев,
     точка со значками.

     Закреп стоит первым в первой строке, перед «Написал»: это не
     действие и не итог, а свойство самой записи, и читается оно раньше
     всего остального — как маркер на полях.

     Почему не переносом флекса с order. Порядок во флекс-строке можно
     задать свойством order, но только элементам: «Написал звание» —
     это голый текстовый узел, а безымянные элементы, в которые флекс их
     заворачивает, order не принимают. Пришлось бы заворачивать текст в
     свой узел, то есть всё равно перестраивать разметку, — тогда уж
     честными строками, которые видно в отладчике.

     Порядок во второй строке задаём списком, а не порядком в разметке:
     в разметке голосовалка уже первая (мы её туда перенесли), закреп
     идёт до подлепры, а нужен после. Список читается как требование, а
     не как побочный результат.

     Идемпотентность — по наличию своей строки: второй вызов увидит
     .lm-fline и выйдет. Метка на .ddi тоже есть, но эта проверка нужна
     отдельно: на догруженных постах подпись новая, а сработать проход
     может дважды. */
  var FOOT_ROW2 = ['.vote', 'a.b-post_domain',
                   '.stars', '.b-post_comments_links', '.lm-more_box'];

  function splitPostFooter(ddi) {
    if (ddi.querySelector('.lm-fline')) return;

    var r1 = document.createElement('span');
    r1.className = 'lm-fline lm-fline__1';
    var r2 = document.createElement('span');
    r2.className = 'lm-fline lm-fline__2';

    FOOT_ROW2.forEach(function (sel) {
      sliceOf(ddi.querySelectorAll(sel)).forEach(function (el) {
        if (el.closest('.lm-fline')) return;      /* уже забран списком выше */
        r2.appendChild(el);
      });
    });

    /* Всё оставшееся — в первую строку, в том порядке, в каком лежало.
       Пустые текстовые узлы выбрасываем: во флекс-строке каждый из них
       становится безымянным элементом и добавляет зазор. */
    sliceOf(ddi.childNodes).forEach(function (n) {
      if (n.nodeType === 3 && !n.nodeValue.replace(/[\s\u00a0]/g, '')) {
        ddi.removeChild(n);
        return;
      }
      r1.appendChild(n);
    });

    /* Закреп — первым в первой строке. Ставим после раскладки, а не
       списком до неё: в разметке он лежит в начале подписи, то есть в
       r1 попал бы и так, но не обязательно первым — перед ним у лепры
       иногда оказывается пустой текстовый узел, а после раскладки
       порядок задаём мы. */
    var pin = r1.querySelector('.b-post_pinned_icon');
    if (pin && pin !== r1.firstChild) r1.insertBefore(pin, r1.firstChild);

    ddi.appendChild(r1);
    ddi.appendChild(r2);
  }

  function compactPostFooters() {
    document.querySelectorAll('.dd .ddi').forEach(function (ddi) {
      if (seen.footer.has(ddi)) return;
      seen.footer.add(ddi);

      moveVoteToFooter(ddi);

      var domain = ddi.querySelector('a.b-post_domain');
      if (domain) {
        var full = (domain.textContent || '').trim();
        var short = full.split('.')[0];
        if (short && short !== full) {
          domain.title = full;
          domain.textContent = short;
        }
        /* Предлог «в» перед названием подлепры лепра пишет отдельным
           текстовым узлом. В строку он не влезает по смыслу: подлепра
           уезжает во вторую строку, к голосовалке, и «в» осталось бы
           висеть в конце первой сиротой. Убираем узел, а не прячем
           стилем: пустой текстовый узел во флекс-строке всё равно
           создаёт безымянный элемент и лишний зазор. */
        /* Предлог у лепры не один: «в кино», но «на дваче» — она
           выбирает его по названию подлепры. Ловим оба. */
        var prev = domain.previousSibling;
        while (prev && prev.nodeType === 3 &&
               /^[\s\u00a0]*(в|на)?[\s\u00a0]*$/.test(prev.nodeValue)) {
          var dead = prev;
          prev = prev.previousSibling;
          dead.parentNode.removeChild(dead);
        }
      }

      ddi.querySelectorAll('.js-date').forEach(shortenDate);

      vectorIcons(ddi);

      compactCommentCount(ddi);
      groupFooterIcons(ddi);
      splitPostFooter(ddi);

      /* косая черта между «в мои вещи» и «в избранное» теперь лишняя */
      ddi.querySelectorAll('.b-post_controls').forEach(function (box) {
        sliceOf(box.childNodes).forEach(function (n) {
          if (n.nodeType === 3 && n.nodeValue.trim() === '/') n.nodeValue = ' ';
        });
      });
    });
  }

  /* ============================================================
     4. ПЕРЕСТРОЙКА ШАПКИ
     ============================================================ */

  /* Страницы, под шапкой которых лепра рисует панель вкладок: «мои вещи»,
     инбокс, избранное, настройки, социализм, приложения, инвайты.
     Опознаём по Чарли — он стоит в этой панели предпоследней вкладкой и
     больше нигде не встречается. Запасной признак — адрес: панель приходит
     вместе с разметкой, но первый проход идёт до полной загрузки, и на
     медленной сети её может ещё не быть, а класс нужен сразу, иначе шапка
     мигнёт полной. */
  function isTabsPage() {
    if (document.querySelector('.b-menu .b-menu_list_link__charlie')) return true;
    return /(^|\.)leprosorium\.ru$/i.test(location.hostname) &&
           /^\/my(\/|$)/.test(location.pathname);
  }

  function markTabsPage() {
    if (isTabsPage()) document.documentElement.classList.add('lm-tabs');
  }

  /* Класс страниц магазина. Нужен для правил, которые касаются всего
     раздела разом (кегли полей ввода), а общего контейнера у магазина
     нет: у каждой страницы своя обёртка со своим именем. */
  function markFraudPage() {
    if (/(^|\.)leprosorium\.ru$/i.test(location.hostname) &&
        /^\/fraud(\/|$)/.test(location.pathname))
      document.documentElement.classList.add('lm-fraud');
  }

  /* ---- Липкая плашка вокатива ----

     Первая строка шапки — приветствие по имени, переключатель темы и
     логотипы — остаётся на экране при прокрутке. Это вокатив: он
     называет человека по имени, и уезжать ему незачем. Остальные строки
     шапки (ссылки, колокольчик, счётчики, приглашение написать пост)
     уходят как раньше — у них есть свои постоянные места, а
     уведомления приходят пынью.

     Почему плашка — отдельный узел, а не sticky прямо на .l-header.
     Липкий элемент держится в пределах СВОЕГО родителя: как только
     родитель уедет вверх, уедет и он. Первая строка живёт внутри
     .l-header, а шапка низкая — плашка отлипла бы через полсотни
     пикселей прокрутки. Поэтому строку выносим в свой блок и кладём
     прямым потомком .l-i-wrapper: эта обёртка высотой во всю страницу,
     и в её пределах плашка держится до конца.

     Логотипы и переключатель темы переезжают вместе с приветствием.
     Ссылка «логаут» остаётся, но видна только пока страница не
     прокручена: наверху, вместе с полной шапкой, она на своём месте, а
     в прилипшей плашке занимала бы вторую строку — то есть удваивала
     высоту того, что и так всегда на экране. Прячется правилом, а не
     удаляется: выход из аккаунта должен оставаться доступным. */
  function buildTopbar() {
    var header = document.querySelector('.l-header');
    var host = document.querySelector('.l-i-wrapper');
    if (!header || !host) return;

    var bar = document.getElementById('lm-topbar');
    if (!bar) {
      bar = document.createElement('div');
      bar.id = 'lm-topbar';
      /* Щуп — пустая полоска над плашкой. По нему наблюдатель понимает,
         прокручена ли страница: щуп ушёл за верхний край, значит плашка
         прилипла. Так обходимся без слушателя прокрутки, а он у нас под
         запретом — прокрутка не должна ничего запускать. */
      var probe = document.createElement('div');
      probe.id = 'lm-topbar_probe';
      host.insertBefore(probe, host.firstChild);
      host.insertBefore(bar, probe.nextSibling);
      watchTopbar(probe);
    }

    /* Переезжают по списку, а не «всё подряд»: в шапке остаются строки,
       которым место там. Порядок внутри плашки задаёт CSS. */
    ['.l-header_tagline', '#lm-theme', '.b-logo', '.b-logo_subsite']
      .forEach(function (sel) {
        sliceOf(document.querySelectorAll(sel)).forEach(function (el) {
          if (el.parentElement !== bar) bar.appendChild(el);
        });
      });

  }

  /* Наблюдатель за щупом. Пока щуп виден — страница у самого верха и
     плашка ничем не отличается от шапки. Ушёл — плашка прилипла, и ей
     нужен фон с деликатным разделителем, иначе содержимое поедет
     сквозь неё.
     rootMargin в ноль и порог в ноль: интересует ровно момент, когда
     щуп пересекает верхнюю кромку экрана. */
  /* Порог срабатывания сдвинут на несколько пикселей вниз, и это не
     подгонка, а лечение вполне определённой болячки.

     Щуп стоит у самого верха документа, то есть граница «видно / не
     видно» проходила ровно по нулю прокрутки. А ноль — это то место,
     где iOS паркует страницу после отскока: вернулись к шапке,
     ударились, отскочили, встали. В момент удара положение колеблется
     вокруг нуля, наблюдатель честно срабатывает туда-обратно, и логаут
     успевает моргнуть.

     Шесть пикселей уводят границу от точки парковки настолько, что
     колебание её не достаёт. Плата — первые шесть пикселей прокрутки
     плашка ещё без фона; на глаз это неразличимо, потому что за шесть
     пикселей под неё ничего не успевает заехать. */
  var STUCK_EDGE = 6;

  function watchTopbar(probe) {
    if (!('IntersectionObserver' in window)) return;
    new IntersectionObserver(function (recs) {
      var seen = recs[recs.length - 1];
      if (!seen.isIntersecting) setStuck(true);
    }, { rootMargin: STUCK_EDGE + 'px 0px 0px 0px', threshold: 0 }).observe(probe);

    /* Второй наблюдатель, за тем же щупом, но с другой границей. Это и
       есть гистерезис: прилипаем на шести пикселях, отлипаем на двух.

       Одной границей не обойтись, и проверять положение прокрутки прямо
       в обработчике — тоже: на медленном возврате наблюдатель
       срабатывает один раз, на пяти пикселях, проверка его отклоняет, а
       второго раза не будет, потому что пересечение больше не меняется.
       Логаут в таком случае не возвращался вовсе.

       С двумя наблюдателями каждое событие — настоящее пересечение
       настоящей границы, и ждать нечего. Между двумя и шестью пикселями
       лежит мёртвая полоса, в которую попадает качание страницы при
       отскоке. Тот же приём, что у выгрузки роликов: там две границы
       спасли от шестидесяти выгрузок на тридцать три ролика. */
    new IntersectionObserver(function (recs) {
      var seen = recs[recs.length - 1];
      if (seen.isIntersecting) setStuck(false);
    }, { rootMargin: '2px 0px 0px 0px', threshold: 0 }).observe(probe);
  }

  /* Тишина в плашке на время сборки страницы.

     Жалоба: при переходе «назад» верх экрана моргает и слегка дёргается.
     Разобрано так. Плашка теряет логаут не мгновенно, а переходом в
     NAV_FOLD миллисекунд — это сделано нарочно, чтобы при обычной
     прокрутке строка уезжала плавно, а не пропадала рывком.

     При обычном открытии страницы это не видно: страница стоит вверху,
     плашка в полном виде, а прилипает она уже под пальцем, когда
     человек сам крутит.

     При возврате «назад» всё наоборот. Браузер восстанавливает место, и
     страница оказывается прокрученной ДО того, как мы успели поставить
     признак «прокручено». Наблюдатель за щупом ставит его следом — и
     переход честно играет свои 280 миллисекунд посреди уже собранной
     страницы. Это и есть моргание: логаут схлопывается на глазах, а
     вместе с ним на несколько пикселей ходит всё, что под плашкой.

     Чинить состояние не надо — оно правильное. Надо убрать анимацию
     этого состояния на время, пока страница ещё устаканивается.
     Гасим переходы на первые доли секунды: любое переключение в этом
     окне происходит мгновенно и незаметно, а дальше всё как было.

     Приём заведомо безопасный: класс не меняет НИ ОДНОГО состояния и не
     трогает раскладку, он гасит только переход. Сломать липкость им
     нельзя по построению.

     Заводим окно и по pageshow тоже. Если Safari отдаст страницу из
     своего кэша назад-вперёд, скрипт не перезапустится вовсе — а
     перерисовка всё равно будет, и слушатель, повешенный в прошлой
     жизни страницы, доживёт до неё и сработает. */
  function setStuck(on) {
    var el = document.documentElement;
    /* В тёмной теме липкости нет вовсе (см. CSS), а значит и признаку
       «прокручено» взяться неоткуда: с ним плашка теряла бы логаут и
       обрастала отбивкой, ничего при этом не удерживая. */
    if (isDark()) on = false;
    if (el.classList.contains('lm-stuck') === on) return;
    el.classList.toggle('lm-stuck', on);
    /* Высота плашки меняется вместе с состоянием: логаут уезжает, и она
       становится на строку ниже. Липкая навштука прилипает на эту
       высоту, значит переменные надо пересчитать — но не сейчас, а когда
       переход доиграет, иначе померим середину движения. */
    setTimeout(guard('syncTopbarVars', syncTopbarVars), NAV_FOLD + 40);
  }

  /* Развёрнутая навштука при прокрутке сворачивается: на экране ей
     оставаться незачем, а места она занимает пол-экрана. Наверху
     возвращается к тому, что велит гвоздик.

     Сигналом служит тот же щуп, что и для плашки, — отдельного
     слушателя прокрутки не заводим, он у нас под запретом. Заодно это
     значит, что «прокручено» здесь и там понимается одинаково.

     Делаем только при включённой липкости: без неё навштука и так
     уезжает вверх вместе со страницей, и сворачивать нечего — а
     свернувшись, она встретила бы человека закрытой при возврате
     наверх, чего он не просил. */
  /* ---- Два наблюдателя вокруг липкой планки ----

     Первый следит за тем, прилипла ли полоска. Щуп — пустая полоска
     нулевой высоты прямо перед ней; ушёл за верхний край, значит
     полоска села на своё место под приветствием. Класс нужен ради
     заглушки (см. CSS): ставить её раньше нельзя, она закрыла бы
     нижнюю строку шапки.

     Второй следит за самой панелью: когда она целиком ушла под полоску,
     состояние надо показать свёрнутым — иначе шеврон продолжает
     обещать «нажми, чтобы закрыть» на том, чего уже не видно. Границу
     считаем не по краю экрана, а по нижней кромке полоски: панель
     скрывается за ней, а не за краем. Отсюда отрицательный отступ у
     корня наблюдения. */
  function watchNavPin() {
    var box = document.getElementById('lm-navthing');
    if (!box || !('IntersectionObserver' in window)) return;
    var row = box.querySelector('.lm-navthing_row');
    var body = box.querySelector('.lm-navthing_body');
    if (!row || box.dataset.lmNavwatch) return;
    box.dataset.lmNavwatch = '1';

    var probe = document.createElement('div');
    probe.id = 'lm-navthing_probe';
    box.insertBefore(probe, row);

    /* Оба наблюдателя пересобираются вместе и по одной причине: их
       границы отсчитываются от высоты приветствия, а та гуляет от
       масштаба страницы и поворота устройства. Готовый отступ у
       наблюдателя не меняется, значит нужен новый.

       Про щуп полоски отдельно. Отступ у него не для точности, а
       потому, что без него класс включался ПОЗДНО. Полоска садится на
       высоте приветствия, а щуп в этот момент ещё виден — он уходит за
       край экрана только когда прокрутишь ещё столько же. То есть
       заглушка появлялась через полсотни пикселей после того, как
       понадобилась, — отсюда и «немного помогла». Отступ ровно в высоту
       приветствия сдвигает срабатывание на нужный миг. */
    var made = -1;

    var remake = function () {
      var tb = topbarStuckH();
      var rowH = Math.round(row.getBoundingClientRect().height);
      /* Нулевой замер не повод остаться без наблюдателей: ставим с
         нулевым отступом, метку «сделано» не выставляем — при следующем
         проходе, когда раскладка посчитается, всё пересоберётся с
         настоящими границами. */
      if (tb && Math.abs(tb - made) < 4) return;
      made = tb || -1;

      if (watchNavPin.pin) watchNavPin.pin.disconnect();
      watchNavPin.pin = new IntersectionObserver(function (recs) {
        var seen = recs[recs.length - 1];
        document.documentElement.classList.toggle('lm-navpin', !seen.isIntersecting);
      }, { rootMargin: (-tb) + 'px 0px 0px 0px', threshold: 0 });
      watchNavPin.pin.observe(probe);

      if (!body) return;
      if (watchNavPin.obs) watchNavPin.obs.disconnect();
      watchNavPin.obs = new IntersectionObserver(function (recs) {
        var seen = recs[recs.length - 1];
        box.classList.toggle('lm-navthing__past', !seen.isIntersecting);
      }, { rootMargin: (-(tb + rowH)) + 'px 0px 0px 0px', threshold: 0 });
      watchNavPin.obs.observe(body);
    };
    remake();
    watchNavPin.remake = remake;
  }

  /* Панель, вызванная посреди ленты, показывается прямо тут — выпадает
     из-под прилипшей полоски поверх содержимого. Возвращать страницу
     наверх ради неё было бы грубо: человек читает здесь.

     Закрывается первым же движением прокрутки. Слушатель одноразовый:
     повесил, дождался, снял. Постоянного слушателя прокрутки заводить
     незачем — режим этот живёт секунды. */
  function armDropClose(box) {
    var off = function () {
      window.removeEventListener('scroll', off);
      box.classList.remove('lm-navthing__drop');
    };
    setTimeout(function () {
      window.addEventListener('scroll', off, { passive: true, once: true });
    }, 0);
  }

  /* Плавное сворачивание и разворачивание панели.

     Высоту меряем, а не берём с потолка. Раньше в CSS стоял запас в 1200
     пикселей — переход шёл от нуля к нему, а настоящее содержимое
     кончалось пикселе на трёхсотом. Выходило, что видимая часть движения
     проскакивала за пятую долю времени, а остальные четыре пятых панель
     просто стояла: на глаз это и есть «дёрнулось и замерло».
     С измеренной высотой скорость движения ровная от начала до конца.

     Закрытие требует двух шагов. Нельзя просто поставить ноль: у
     свойства сейчас значение none или потолок, а от них браузер
     анимировать не станет — нужна конкретная величина, от которой
     ехать. Поэтому сперва фиксируем текущую высоту числом, потом
     принудительно заставляем пересчитать раскладку (чтение offsetHeight
     — как раз способ это сделать), и только затем ставим ноль.

     После разворота ограничение снимаем совсем: панель может подрасти
     сама — подгрузятся замены овощебазы или развернётся выпадашка, — и
     застывший потолок обрезал бы ей низ.

     Инлайновая запись идёт с пометкой important: в таблице стилей
     max-height тоже важное, а без пометки инлайн ему проиграл бы. */
  function navFold(box, open) {
    var body = box.querySelector('.lm-navthing_body');
    var btn = box.querySelector('.lm-navthing_row');
    if (btn) btn.setAttribute('aria-expanded', open ? 'true' : 'false');
    if (!body) { box.classList.toggle('lm-navthing__open', open); return; }

    /* При липкой планке высотой не управляем вовсе — панель там выведена
       из потока и уезжает сдвигом (см. CSS). Вся эта возня с замером и
       потолком нужна только обычному режиму, где панель раздвигает
       содержимое. Если бы она осталась и здесь, инлайновая высота
       переспорила бы правило и панель застыла бы полосой. */

    /* Ноль означает не «панель пустая», а «померить не удалось»: так
       бывает у скрытого поддерева и всегда в проверочной среде. С нулём
       вместо высоты панель осталась бы закрытой до конца перехода и
       раскрылась рывком; лучше отдать дело запасному потолку в таблице
       стилей — он грубее, но не ломает. */
    var h = body.scrollHeight;

    if (open) {
      if (h) body.style.setProperty('max-height', h + 'px', 'important');
      else body.style.removeProperty('max-height');
      box.classList.add('lm-navthing__open');
      clearTimeout(navFold.timer);
      navFold.timer = setTimeout(function () {
        if (box.classList.contains('lm-navthing__open'))
          body.style.setProperty('max-height', 'none', 'important');
      }, NAV_FOLD + 40);
      return;
    }

    clearTimeout(navFold.timer);
    if (h) {
      body.style.setProperty('max-height', h + 'px', 'important');
      void body.offsetHeight;
    }
    box.classList.remove('lm-navthing__open');
    body.style.setProperty('max-height', '0px', 'important');
  }

  /* Высота липкой плашки — для тех, кто прокручивает страницу к цели:
     цель, поставленная в самый верх экрана, окажется под плашкой.
     Меряем, а не считаем: высота зависит от длины приветствия, которое
     на узком экране переносится на две строки. */
  /* Высота логаута. Меряем, пока он раскрыт, и запоминаем: когда он
     уедет, мерить будет нечего, а число понадобится именно тогда. */
  var logoutH = 0;

  /* На сколько плашка укорачивается, прилипнув. Считается замером, см.
     syncTopbarVars. */
  var topbarDrop = 0, topbarDropAt = -1;
  /* Высота прилипшей плашки и ширина экрана, на которой её мерили. */
  var topbarLean = 0, topbarLeanAt = -1;

  function topbarH() {
    var bar = document.getElementById('lm-topbar');
    if (!bar) return 0;
    var r = bar.getBoundingClientRect();
    return r.height > 0 ? Math.round(r.height) : 0;
  }

  /* Высота плашки в ПРИЛИПШЕМ виде, то есть без логаута.

     Именно она нужна всем, кто прилипает под плашкой. Обычный замер даёт
     высоту с логаутом, пока страница не прокручена, и полоска садилась
     сперва на это место, а через треть секунды — когда логаут уезжал и
     замер повторялся — подпрыгивала на его высоту. Со стороны это
     выглядело как заминка в нескольких пикселях от места слипки; на
     самом деле полоска доезжала честно, просто место успевало
     измениться.

     Вычитаем сразу, и величина перестаёт зависеть от того, прокручена
     страница или нет. */
  function topbarStuckH() {
    var bar = document.getElementById('lm-topbar');
    var el = document.documentElement;
    if (!bar || !el) return 0;
    /* Прокручено — меряем прямо, без ухищрений, и запоминаем. */
    if (el.classList.contains('lm-stuck')) {
      var now = Math.round(bar.getBoundingClientRect().height);
      if (now > 0) { topbarLean = now; topbarLeanAt = window.innerWidth; }
      return now;
    }

    /* Ответ на эту ширину экрана уже известен. Кэш тут не роскошь:
       функцию зовут и настройка переменных, и пересборка наблюдателей, и
       каждый из четырёх проходов при загрузке, — а замер стоит пересчёта
       раскладки и на миг трогает разметку. Величина меняется только
       вместе с раскладкой, то есть при повороте устройства и смене
       масштаба страницы, и то и другое видно по ширине. */
    if (topbarLean > 0 && topbarLeanAt === window.innerWidth) return topbarLean;

    /* Страница не прокручена, а нужна высота прокрученного вида. Первым
       заходом я её вычислял — из полной вычитал высоту логаута, — и
       промахивался на несколько пикселей. Причина в схлопывании полей:
       у логаута нулевой высоты верхнее и нижнее поле сливаются и с его
       соседями, и с родительским, и потеря высоты выходит НЕ равной его
       собственной. Насколько именно — зависит от кегля и масштаба
       страницы, то есть предсказать нельзя.

       Поэтому не вычисляем, а меряем: на миг надеваем класс, который
       приводит плашку к прокрученному виду, снимаем замер и класс
       снимаем. Всё в одном куске кода, без ожиданий, — браузер не
       успевает ничего нарисовать.

       Классов два, и это не небрежность. lm-measure схлопывает логаут и
       снимается сразу; lm-notrans гасит переходы и держится дольше — до
       тех пор, пока восстановленная высота не будет засчитана. Сними их
       вместе, и браузер увидит только итог: было ноль, стало двадцать, —
       и честно проиграет переход, то есть логаут разъедется на глазах.
       Проходов при загрузке четыре, отсюда и брались подряд несколько
       микродёргов. Чтение размера между снятием классов заставляет
       пересчитать раскладку прямо сейчас, пока переходы ещё выключены. */
    el.classList.add('lm-notrans');
    el.classList.add('lm-measure');
    var h = Math.round(bar.getBoundingClientRect().height);
    el.classList.remove('lm-measure');
    void bar.offsetHeight;
    el.classList.remove('lm-notrans');
    if (h > 0) { topbarLean = h; topbarLeanAt = window.innerWidth; }
    return h > 0 ? h : 0;
  }

  /* Высота свёрнутой навштуки, если она липкая. Меряем строку, а не весь
     блок: развёрнутый блок высотой в пол-экрана, а прилипает и занимает
     место постоянно только его верхняя полоска. */
  function navStickH() {
    if (!CFG.navSticky) return 0;
    var row = document.querySelector('#lm-navthing .lm-navthing_row');
    if (!row) return 0;
    var r = row.getBoundingClientRect();
    return r.height > 0 ? Math.round(r.height) : 0;
  }

  /* Обе высоты нужны и коду (приземление прокрутки), и таблице стилей
     (навштука прилипает под плашкой, то есть на её высоте). Значение
     одно, поэтому и источник один: меряем в JS, отдаём в CSS
     переменной. Записываем только при изменении — свойство трогает
     раскладку, а проходов много. */
  function syncTopbarVars() {
    var el = document.documentElement;
    if (!el) return;

    /* Насколько плашка укорачивается, прилипнув. Это НЕ высота логаута,
       и разница здесь стоила отдельного круга.

       Логаут схлопывается в ноль, но его поля никуда не деваются: они
       сливаются с соседскими и родительским, и плашка теряет на
       несколько пикселей меньше, чем он сам занимал. Отбивка, которой мы
       эту потерю возмещаем, была равна высоте логаута — то есть на те же
       несколько пикселей больше, чем надо. Документ на каждом
       переключении подпрыгивал, прокрутка вслед за ним переезжала через
       порог наблюдателя, наблюдатель переключал класс обратно — и всё
       повторялось. Отсюда и двойной дёрг, и моргание логаута, и то же
       самое в конце загрузки страницы.

       Считаем разность двух замеров: полного вида и прилипшего. Считаем
       только пока страница не прокручена — в прокрученном виде полного
       замера уже не сделать, — и запоминаем. */
    var stuckNow = el.classList.contains('lm-stuck');
    if (!stuckNow && topbarDropAt !== window.innerWidth) {
      var full = topbarH(), lean = topbarStuckH();
      if (full > 0 && lean > 0 && full > lean) {
        topbarDrop = full - lean;
        topbarDropAt = window.innerWidth;
      }
    }
    if (topbarDrop > 0) {
      var dv = topbarDrop + 'px';
      if (el.style.getPropertyValue('--lm-topbar-drop') !== dv)
        el.style.setProperty('--lm-topbar-drop', dv);
    }

    var out = document.querySelector('#lm-topbar .b-icon_button_logout');
    if (out) {
      var oh = Math.round(out.getBoundingClientRect().height);
      if (oh > 0) logoutH = oh;
      /* Пишем только настоящее число. Нулём здесь легко всё испортить: у
         свойства есть запасное значение в правиле, а записанный ноль его
         перебьёт — логаут схлопнется в ничто ещё до прокрутки. Ровно та
         же осторожность, что и с высотой плашки. */
      if (logoutH > 0) {
        var ov = logoutH + 'px';
        if (el.style.getPropertyValue('--lm-logout-h') !== ov)
          el.style.setProperty('--lm-logout-h', ov);
      }
    }

    var row = document.querySelector('#lm-navthing .lm-navthing_row');
    if (row) {
      var rh = Math.round(row.getBoundingClientRect().height);
      if (rh > 0) {
        var rv = rh + 'px';
        if (el.style.getPropertyValue('--lm-navrow-h') !== rv)
          el.style.setProperty('--lm-navrow-h', rv);
      }
    }

    var n = topbarStuckH();
    /* Ноль не пишем. Он означает не «плашки нет», а «раскладка ещё не
       посчитана» — так бывает при самом раннем проходе и всегда в
       проверочной среде, где все прямоугольники нулевые. Записанный
       ноль хуже отсутствия: у переменной есть запасное значение в самом
       правиле, и без записи навштука прилипнет примерно верно, а с
       нулём — поверх плашки. */
    if (!n) return;
    var h = n + 'px';
    if (el.style.getPropertyValue('--lm-topbar-h') !== h)
      el.style.setProperty('--lm-topbar-h', h);
  }

  /* ---- Оформление подлепры ----

     Подлепра может завести своё оформление: цвет ленты, фон под
     карточками, свои шрифты и рамки. Подключается оно отдельной
     таблицей стилей — <link href="…/custom_css"> — и приходит ПОСЛЕ
     лепровской, то есть перебивает почти всё, включая наши тона.
     С двумя наборами карточек это несовместимо: наша схема строится на
     трёх согласованных тонах (страница, карточка, подпись), а чужая
     заливка вклинивается в середину и рушит их отношение.

     Гасим источник, а не последствия. Перечислять чужие правила
     бессмысленно: у каждой подлепры они свои, их не видно заранее, и
     список пришлось бы дополнять вечно. Один выключатель на таблицу
     закрывает вопрос независимо от содержимого.

     disabled, а не удаление узла: удалить — значит поспорить со
     скриптом лепры, если он однажды решит эту ссылку проверить.
     Выключенная таблица остаётся на месте и просто не применяется, а
     заодно браузер не станет её и загружать, если успеть до загрузки.

     Успеть помогает наблюдатель за head: ссылка появляется по ходу
     разбора страницы, и ловим мы её в тот же миг, а не проходом
     позже — иначе оформление успело бы мигнуть. */
  /* Что из чужого оформления оставляем. Заглавие подлепры — её лицо:
     «Филиал дурдома. Научная секция диодов» набрано своим шрифтом и
     цветом, и без них подлепра перестаёт отличаться от соседней.
     Всё остальное — заливки ленты, рамки карточек, фоны комментариев —
     спорит с нашей схемой тонов и уходит.

     Список нарочно широкий: заглавие красят кто во что горазд — кто по
     классу, кто просто по h1 внутри тела. Взять лишнее правило не
     страшно, наши тона объявлены с !important и своё возьмут; а не
     взять нужное значит потерять лицо подлепры, чего мы и избегаем.

     Проверить это по сохранённым страницам нельзя: Chrome кладёт в
     архив пустой custom_css — как и инлайновые скрипты. Поэтому в отчёт
     выводится счёт удалённых правил: если заглавие потеряется, сразу
     видно, промахнулся список или таблица и правда пуста.

     .cls- в списке — не про подлепры: этим классом лепра красит фигуры
     внутри своих значков, и объявление лежит во встроенной таблице,
     которую мы теперь тоже прореживаем. Удалив его, мы обесцветили бы
     колокольчик. */
  var SUBSITE_KEEP =
    /b-subsite_header|b-subsite_logo|js-subsite_logo|b-gertruda|b-subdomain|\bh1\b|\.cls-/i;

  /* Приставка html в начале селектора (или любой его части через
     запятую) — подпись чужого оформления: только ради веса она там и
     стоит. См. разбор в killSubsiteCss. */
  var HTML_FIRST = /(^|,)\s*html(?![\w-])/i;

  /* Какие таблицы считаем чужим оформлением.

     Разбор архива поправил моё прежнее представление. Я думал, что
     оформление подлепры целиком лежит в custom_css, — на деле там пусто,
     а настоящий дизайн приходит ДВУМЯ отдельными таблицами, которые
     стоят в head ПЕРЕД лепровской. Перебивают они её не порядком, а
     весом: все их правила написаны с приставкой html, ровно чтобы
     обойти all.css с более ранней позиции.

     Поэтому опознаём не по имени файла, а по исключению: берём все
     подключённые таблицы своего домена, кроме лепровской (она лежит в
     /static/) и кроме нашей. Чужие домены отпадают сами — к их правилам
     браузер не пускает, и попытка чтения бросает исключение.

     Встроенные <style> не трогаем вовсе: оформление приходит ссылками, а
     в инлайновых у лепры лежат мелочи вроде заливки значков. */
  function isSubsiteSheet(l) {
    if (!l || l.id === 'lepra-mobile-css') return false;
    var href = l.getAttribute('href') || '';
    if (/\/static\//.test(href)) return false;          /* all.css лепры */
    /* Встроенный <style> — тоже оформление, и это главное открытие
       последнего захода. Сперва я их пропускал, считая, что дизайн
       приходит только ссылками: в сохранённой странице он и правда
       лежал ссылками. Оказалось, это работа Chrome — при сохранении он
       выносит содержимое <style> в отдельные части архива и подменяет
       их ссылками на cid. На живой странице это встроенные таблицы, и
       мимо них проходило всё.
       Сравнение с 'STYLE' в верхнем регистре отсекает заодно <style>
       внутри svg: у тех имя тега строчное, и трогать их не надо —
       там лежит заливка лепровских значков. */
    if (!href) return l.tagName === 'STYLE';
    try {
      /* Своя таблица или чужая — решает не адрес, а доступность правил:
         к чужому домену браузер не пустит. Заодно отсеиваются шрифты
         Google, которые тоже подключены ссылкой. */
      if (l.sheet && l.sheet.cssRules) return true;
    } catch (e) { return false; }
    /* Ещё не загрузилась — считаем своей, придержим до выяснения. */
    return !/^https?:\/\//.test(href) ||
           href.indexOf(location.hostname) >= 0;
  }

  /* Все таблицы страницы, кроме нашей и лепровской: и ссылки, и
     встроенные. Список один на прореживание и на отчёт — иначе они
     разойдутся в понимании того, что считать оформлением. */
  function subsiteSheets() {
    return sliceOf(document.querySelectorAll('link[rel~="stylesheet"], style'))
      .filter(isSubsiteSheet);
  }

  /* Картинка, которую оформление кладёт полосой под заголовок. У
     автоподлепры это протектор шины во всю ширину, у других своё — но
     приём один: background-image на .l-content с повтором по
     горизонтали. Полоса эта — часть лица подлепры наравне с заглавием,
     и терять её вместе с заливками жалко.
     Забираем адрес ДО удаления правила: после удаления взять его будет
     неоткуда. */
  var subsiteArt = '';

  function killSubsiteCss() {
    var found = false;
    subsiteSheets().forEach(function (l) {
      found = true;
      if (l.dataset.lmDone) return;

      /* Пока таблица не загрузилась, править в ней нечего. Но и
         применяться ей нельзя — иначе чужое оформление мигнёт на первом
         кадре.

         Раньше я её выключал (disabled), и это оказалось ошибкой,
         которая тихо ломала всё остальное: выключенную таблицу браузер
         НЕ ЗАГРУЖАЕТ. Она так и оставалась без правил, прореживать было
         нечего, а картинку полосы неоткуда взять. Со стороны выглядело
         как «оформление отключилось, но и полоса не появилась» — ровно
         то, что и было видно на устройстве.

         Правильный способ — сказать, что таблица не для этого носителя:
         `media="not all"`. Такую браузер загружает, но не применяет.
         Дождавшись загрузки, прореживаем и возвращаем носитель на
         место. Слушатель вешаем на КАЖДУЮ такую ссылку, а не на первую
         найденную: оформление приходит двумя таблицами. */
      var sheet = null;
      try { sheet = l.sheet; } catch (e) { sheet = null; }
      if (!sheet) {
        /* У встроенной таблицы правила есть всегда; нет их — значит узел
           пустой, и ждать нечего. Придерживать носителем имеет смысл
           только внешнюю. */
        if (l.tagName === 'STYLE') { l.dataset.lmDone = '0/0'; return; }
        if (l.getAttribute('media') !== 'not all') {
          l.dataset.lmMedia = l.getAttribute('media') || '';
          l.setAttribute('media', 'not all');
          l.addEventListener('load', guard('killSubsiteCss', killSubsiteCss),
                             { once: true });
        }
        return;
      }

      /* Прореживание вместо выключения. Выключить таблицу целиком проще,
         но вместе с заливками уходит и заглавие. Правила лежат в
         таблице того же домена, что и страница, поэтому читать и
         удалять их нам можно — на чужом домене браузер к cssRules не
         пустил бы, и это единственная причина, по которой приём вообще
         работает.
         Идём с конца: удаление сдвигает номера, и обход вперёд
         пропускал бы каждое второе правило. */
      var rules;
      try { rules = sheet.cssRules; } catch (e) { l.disabled = true; return; }
      var inline = (l.tagName === 'STYLE');
      var gone = 0, kept = 0;
      for (var i = rules.length - 1; i >= 0; i--) {
        var sel = rules[i].selectorText || '';
        /* Правила без селектора (@font-face, @media, @import) оставляем:
           шрифт заглавия объявляется как раз через @font-face, а
           разбирать вложенные @media ради заливок не стоит — их всё
           равно перекрывают наши правила с !important. */
        if (!sel || SUBSITE_KEEP.test(sel)) { kept++; continue; }
        /* Во ВСТРОЕННОЙ таблице выметаем только правила с приставкой
           html, и это не осторожность, а починка архива.

           Разбор был такой. На архиве календарь приезжал россыпью: дни
           недели слипались в «пнвтсрчтптсбвс», числа шли одной строкой
           за край экрана, месяц с годом становились маркированным
           списком. Выглядело как наша поломка раскладки, а оказалось
           проще: вся раскладка календаря (.b-calendar*, ширина ячейки в
           сорок пикселей, две колонки управления по половине) живёт во
           ВСТРОЕННОЙ таблице стилей страницы — и мы её выметали
           начисто. Отсюда и «скорявило после некоторых изменений»:
           изменение было ровно одно — мы начали прореживать <style>.

           Различить чужое оформление и раскладку страницы можно по той
           самой примете, ради которой прореживание и затевалось.
           Оформление подлепры перебивает all.css не порядком, а весом:
           каждое её правило написано с приставкой html. Раскладка
           страницы такой приставки не имеет — ей не с чем спорить.
           Признак надёжный: обе встроенные таблицы, которые есть на
           КАЖДОЙ странице (набор тонов и «html .l-content
           background-image: none»), написаны через html и уходят как
           прежде, а таблица календаря остаётся.

           Внешних ссылок это послабление не касается: там наоборот,
           таблица целиком чужая, и выметать надо всё. */
        if (inline && !HTML_FIRST.test(sel)) { kept++; continue; }
        /* Полосу под заголовком запоминаем перед удалением правила. */
        if (!subsiteArt && /\.l-content(?![_a-z-])/.test(sel)) {
          var img = rules[i].style && rules[i].style.backgroundImage;
          var m = img && /url\(\s*["']?([^"')]+)/.exec(img);
          if (m) subsiteArt = m[1];
        }
        try { sheet.deleteRule(i); gone++; } catch (e) {}
      }
      /* Возвращаем носитель: правила проредили, показывать оставшееся
         можно. Пустая строка означает «атрибута не было» — тогда его и
         не ставим, чтобы разметка осталась как была. */
      if (l.dataset.lmMedia) l.setAttribute('media', l.dataset.lmMedia);
      else l.removeAttribute('media');
      l.disabled = false;
      l.dataset.lmDone = gone + '/' + (gone + kept);
    });
    return found;
  }

  var subsiteCssWatched = false;

  function watchSubsiteCss() {
    if (subsiteCssWatched) return;
    var head = document.head || document.documentElement;
    if (!head || !('MutationObserver' in window)) return;
    subsiteCssWatched = true;
    killSubsiteCss();
    /* Наблюдателя держим до конца разбора страницы: таблиц оформления
       две, и появляются они не одновременно. Ожидание загрузки каждой
       вешает сама killSubsiteCss, здесь только поиск новых ссылок. */
    var obs = new MutationObserver(function () { killSubsiteCss(); });
    /* Только прямые дети head: ссылки на таблицы лежат там, а subtree
       заставил бы наблюдателя просыпаться на каждом узле страницы. */
    obs.observe(head, { childList: true });
    /* Отпускаем наблюдателя, когда страница собрана: если ссылки нет к
       этому времени, её и не будет, а висящий наблюдатель — это забытый
       наблюдатель. */
    window.addEventListener('load', function () { obs.disconnect(); }, { once: true });
  }

  /* Полоса оформления под заглавием подлепры.

     Ставим своим узлом, а не оставляем правило лепры: у неё картинка
     висит фоном на .l-content, то есть под всей лентой сразу, и вместе
     с ней приезжает заливка, спорящая с нашими тонами. Свой узел даёт
     ровно то, что нужно, — декоративную полосу на своём месте.

     Высоту берём натуральную, замером самой картинки: она у каждой
     подлепры своя, а растянутый или обрезанный протектор выглядит
     ошибкой. Предел в сто пикселей — на случай, если кто-то положит
     туда полотно во весь экран.

     От кромки до кромки теми же полями, что у плашки: полоса рисовалась
     во всю ширину окна, и вписанная в колонку она читалась бы картинкой
     в тексте, а не оформлением. */
  function buildSubsiteBand() {
    if (!subsiteArt) return;
    var head = document.querySelector('.b-subsite_header');
    if (!head) return;
    var band = document.getElementById('lm-subband');
    if (band) return;

    band = document.createElement('div');
    band.id = 'lm-subband';
    band.style.setProperty('background-image', 'url("' + subsiteArt + '")', 'important');
    head.parentNode.insertBefore(band, head.nextSibling);

    var probe = new Image();
    probe.onload = function () {
      var h = Math.min(100, probe.naturalHeight || 0);
      if (h > 0) band.style.setProperty('height', h + 'px', 'important');
    };
    probe.src = subsiteArt;
  }

  function relayoutHeader() {
    var header = document.querySelector('.l-header');
    if (!header) return;

    /* На подсайте лепра подменяет картинку логотипа на оформление подсайта,
       но адрес оставляет свой — выходит картинка подсайта со ссылкой на
       leprosorium.ru. Выбираем по классу: id="js-logo" у лепры продублирован
       на обоих логотипах, полагаться на него нельзя. */
    var host = location.hostname;
    if (/\.leprosorium\.ru$/i.test(host)) {
      var own = document.querySelector('.l-header a.b-logo:not(.b-logo_subsite)');
      if (own && !own.dataset.lmHref) {
        own.dataset.lmHref = '1';
        own.setAttribute('href', location.protocol + '//' + host + '/');
        own.setAttribute('title', 'главная ' + host.split('.')[0]);
      }
    }

    /* Маска лепры на подсайте лежит снаружи шапки, прямым потомком
       .l-header_subsite, и потому рисуется строкой ниже слева. */
    var subLogo = document.querySelector('.b-logo_subsite');
    if (subLogo && !subLogo.dataset.lmMoved) {
      subLogo.dataset.lmMoved = '1';
      subLogo.setAttribute('href', 'https://leprosorium.ru/');
      subLogo.setAttribute('title', 'главная Лепрозория');
      header.appendChild(subLogo);
    }

    /* Каждая строка шапки — самостоятельный блок. В разметке лепры они
       лежат в разных обёртках, а флекс строит строку только из соседей
       по одному родителю, поэтому переносим их прямо в .l-header. */
    var tabsPage = document.documentElement.classList.contains('lm-tabs');

    /* В списке остались только счётчики и приглашение написать пост.
       Переключатель вида, порог постов и поиск уезжают в третью колонку
       навигационной штуки — забирает их там buildNavthing, а не эта
       функция: здесь они сначала оказались бы в шапке, и вынимать их
       пришлось бы вторым движением за тот же проход.
       Исключение — страницы с вкладками: там поиск остаётся в шапке, в
       конце строки ссылок, и его переносит блок ниже. */
    ['.b-header_nav_new_post', '.b-header_counters'].forEach(function (sel) {
      var el = document.querySelector(sel);
      if (el && !el.dataset.lmMoved && el.parentElement !== header) {
        el.dataset.lmMoved = '1';
        header.appendChild(el);
      }
    });

    /* Приглашение написать пост. На главной лепра пишет «Лепрозорий ждёт
       новый пост!», на подсайтах — «Все ждут новый пост!». Раскладка
       шапки теперь общая, а фраза оставалась разной, и на главной она
       была ощутимо длиннее соседних счётчиков — в паре из двух блоков
       это уже видно. Берём подсайтную.

       Правим текстовый узел, а не весь блок: слово «пост» у лепры —
       ссылка на /asylum, и переписывание textContent снесло бы её.
       Меняется только начало фразы, всё после ссылки остаётся своим.
       Метка на блоке нужна потому, что проходов несколько, а замена
       после первой уже не совпадёт и молча ничего не сделает — ровно
       тот случай, из-за которого раньше пропадали объявления переменных. */
    var invite = header.querySelector('.b-header_nav_new_post') ||
                 document.querySelector('.b-header_nav_new_post');
    if (invite && !invite.dataset.lmPhrase) {
      sliceOf(invite.childNodes).forEach(function (n) {
        if (n.nodeType !== 3) return;
        var t = n.nodeValue;
        var s = t.replace(/Лепрозорий\s+жд[ёе]т/, 'Все ждут');
        if (s !== t) { n.nodeValue = s; invite.dataset.lmPhrase = '1'; }
      });
    }

    /* В магазине лепра дописывает в тот же блок вторую строку — «У вас на
       счету N ЛВ, пополнить счет», отделяя её тегом <br>. Блок стоит правой
       колонкой в 45% ширины с запретом переноса, а строка баланса заведомо
       длиннее колонки (замеры в CSS рядом с правилом .lm-balance), и хвост
       уезжал за край.
       Вынимаем всё, что стоит после <br>, в отдельный блок и вешаем его
       строкой шапки во всю ширину — раскладку задаёт CSS.
       Перебираем прямых детей, а не querySelector('br'): вложенный где-то
       в глубине <br> дал бы «следующих соседей» не того уровня, и переезд
       унёс бы половину чужого узла. */
    splitBalance(header);

    /* Сжатая шапка: из строки ссылок ушли «Магазин», «Избранное» и
       приглашение написать пост, место освободилось — ставим туда поиск.
       Единственное место, где поиск остаётся в шапке; на всех прочих
       страницах его забирает навигационная штука. Метка lmMoved для неё
       и выставляется: по ней buildNavthing понимает, что блок уже
       пристроен, и второй раз его не дёргает. */
    if (tabsPage) {
      var navBox = header.querySelector('.b-header_nav');
      var srch = document.querySelector('.b-header_search');
      if (navBox && srch && srch.parentElement !== navBox) {
        srch.dataset.lmMoved = '1';
        navBox.appendChild(srch);
      }
    }

    buildTopbar();
    buildSubsiteBand();
    syncTopbarVars();
    guard('watchNavPin', watchNavPin)();
    if (watchNavPin.remake) guard('navRemake', watchNavPin.remake)();

    hideEmptyAside();
  }

  /* Обёртка .l-header_aside держит счётчики и поиск. Пустеет она теперь в
     два приёма: счётчики забирает шапка, поиск — навигационная штука, а
     та строится позже. Поэтому проверка вынесена сюда и вызывается
     обоими: пока внутри осталось хоть что-то из этих двух, обёртка
     нужна — иначе при неудачном переносе вместе с ней исчезли бы и
     счётчики, и поиск.
     Прячем, а не оставляем как есть: у обёртки нет order, то есть он
     равен нулю, и в строке шапки она вставала ПЕРЕД приветствием,
     сдвигая его вправо на свою ширину. */
  /* Вынос второй строки приглашения написать пост (строки баланса) в
     самостоятельный блок шапки. Метка на блоке обязательна: проходов
     несколько, а после первого <br> в блоке уже нет — второй вызов просто
     не нашёл бы, что делить, но лишний пустой .lm-balance создать бы успел.

     Слепое место: под рукой была только страница магазина, поэтому условие
     общее — «есть <br>, после него есть текст». Если лепра где-то ещё
     разобьёт тегом <br> саму фразу про новый пост, её хвост тоже уедет
     отдельной строкой. Ничего не сломается, но выглядеть будет странно;
     тогда условие придётся сузить. */
  function splitBalance(header) {
    var invite = header.querySelector('.b-header_nav_new_post');
    if (!invite || invite.dataset.lmBalance) return;

    var br = null;
    sliceOf(invite.childNodes).forEach(function (n) {
      if (!br && n.nodeType === 1 && n.tagName === 'BR') br = n;
    });
    if (!br) return;

    var row = document.createElement('div');
    row.className = 'lm-balance';
    var n;
    while ((n = br.nextSibling)) row.appendChild(n);
    br.parentNode.removeChild(br);

    invite.dataset.lmBalance = '1';
    if (row.textContent.trim()) header.appendChild(row);
  }

  function hideEmptyAside() {
    var aside = document.querySelector('.l-header_aside');
    if (aside && !aside.querySelector('.b-header_counters, .b-header_search'))
      aside.style.setProperty('display', 'none', 'important');
  }

  /* ============================================================
     ПОПАП НАСТРОЕК
     ============================================================

     Вызывается тапом по середине гертруды. Место выбрано не от
     безысходности: в третьей колонке свободных пикселей нет, отдельная
     кнопка отняла бы у неё строку, а картинка стоит на каждой странице
     и ничего собой не значит — тап по ней до сих пор не делал ничего.
     Края её при этом остаются свободными: в левом верхнем углу гвоздик,
     и середина взята с запасом от него.

     Запасной вход — долгое нажатие по свёрнутой строке навигационной
     штуки: гертруды может не оказаться (внутренние страницы, пустой
     кэш), и остаться без настроек из-за отсутствия картинки нельзя.

     Устройство попапа. Все органы читают и пишут одну и ту же таблицу
     TUNE: ползунки берут из неё пределы, «сбросить» — заводское
     значение, переключатели — список допустимого. Ни одного числа в
     разметке попапа нет, иначе они разъехались бы с настройками при
     первой же правке CFG. */

  var SET_ROWS = [
    { key: 'mediaCut',   label: 'медиа-контент', kind: 'media' },
    { key: 'discoCut',   label: 'посты',         kind: 'post' },
    { key: 'commentCut', label: 'комментарии',   kind: 'comment' }
  ];

  var setPick = 'mediaCut';       /* какой ряд выбран радиокнопкой */
  var setApplyTimer = null;

  function setClose() {
    var w = document.getElementById('lm-set');
    if (w) w.remove();
  }

  /* Применить изменение к самой странице. Для медиа достаточно
     переменной CSS — она уже переписана в tuneSet, и картинки меняются
     тем же кадром. Для срезов нужна пересборка, а она дорогая: на
     длинной ленте это сотни замеров. Поэтому с задержкой — пока палец
     ведёт ползунок, пересобирать нечего, схемофон показывает результат
     и без этого. */
  function setApply(key) {
    if (key === 'mediaCut') return;
    if (setApplyTimer) clearTimeout(setApplyTimer);
    setApplyTimer = setTimeout(function () {
      setApplyTimer = null;
      guard('discoRestore', discoRestore)();
      guard('discoScan', discoScan)();
      guard('discoScanComments', discoScanComments)();
    }, 300);
  }

  /* Схемофон: рамка телефона и внутри неё полоса содержимого сверху.
     Доля полосы равна настройке — то есть человек видит буквально то,
     что настраивает, а не абстрактную шкалу. Верх полосы прибит к верху
     экрана, двигается только низ: содержимое в ленте тоже растёт
     сверху вниз. */
  function setPhone() {
    var svg = svgNode('svg', {
      viewBox: '0 0 ' + SET_PHONE_W + ' ' + SET_PHONE_H,
      width: String(SET_PHONE_W), height: String(SET_PHONE_H),
      xmlns: SVG_NS, 'aria-hidden': 'true'
    });
    svg.appendChild(svgNode('rect', {
      x: '1', y: '1', width: String(SET_PHONE_W - 2), height: String(SET_PHONE_H - 2),
      rx: '7', fill: '#fff', stroke: 'rgb(150,150,150)', 'stroke-width': '2'
    }));
    /* Полоса содержимого прибита к верху экрана: в ленте контент тоже
       растёт сверху вниз, и двигаться должен только низ. */
    var fill = svgNode('rect', {
      x: String(SET_PHONE_PAD), y: String(SET_PHONE_PAD),
      width: String(SET_PHONE_W - SET_PHONE_PAD * 2), height: '10',
      rx: '2', fill: 'rgb(150,170,200)'
    });
    fill.setAttribute('data-lm-fill', '1');
    svg.appendChild(fill);
    return svg;
  }

  var SET_PHONE_PAD = 8;   /* поле между рамкой телефона и содержимым */

  function setPhoneDraw(svg, percent) {
    var fill = svg.querySelector('[data-lm-fill]');
    if (!fill) return;
    var inner = SET_PHONE_H - SET_PHONE_PAD * 2;
    fill.setAttribute('height', String(Math.max(3, Math.round(inner * percent / 100))));
  }

  function setBlock(title) {
    var b = document.createElement('div');
    b.className = 'lm-set_block';
    if (title) {
      var h = document.createElement('div');
      h.className = 'lm-set_head';
      h.textContent = title;
      b.appendChild(h);
    }
    return b;
  }

  /* Переключатель из списка: подпись и ряд кнопок. Значения берутся из
     TUNE, подписи передаются рядом — в TUNE им не место, там устройство
     настройки, а не её перевод на русский. */
  /* onPick — что сделать после выбора. Нужен, чтобы один переключатель
     мог влиять на другой: выбор «звуком» или «никак» обесценивает
     вопрос, с какой стороны показывать плашку. */
  function setChoice(key, title, names, onPick) {
    var row = document.createElement('div');
    row.className = 'lm-set_row';
    var lab = document.createElement('div');
    lab.className = 'lm-set_label';
    lab.textContent = title;
    row.appendChild(lab);

    var box = document.createElement('div');
    box.className = 'lm-set_choice';
    (TUNE[key].list || []).forEach(function (v, i) {
      var b = document.createElement('button');
      b.type = 'button';
      b.className = 'lm-set_opt';
      b.textContent = names[i];
      b.classList.toggle('lm-on', CFG[key] === v);
      b.addEventListener('click', function () {
        if (row.dataset.lmOff) return;      /* ряд погашен — нечего решать */
        tuneSet(key, v);
        sliceOf(box.children).forEach(function (o) { o.classList.remove('lm-on'); });
        b.classList.add('lm-on');
        if (onPick) onPick(v);
      });
      box.appendChild(b);
    });
    row.appendChild(box);
    return row;
  }

  /* Погасить или вернуть ряд целиком. Не удаляем и не прячем: строка,
     исчезающая при выборе соседа, дёргает высоту попапа и заставляет
     гадать, куда она делась. Погашенный ряд остаётся на месте и молча
     объясняет, что сейчас он ни на что не влияет. */
  function setRowOff(row, off) {
    if (!row) return;
    if (off) row.dataset.lmOff = '1'; else delete row.dataset.lmOff;
    row.classList.toggle('lm-off', !!off);
  }

  function setToggle(key, title) {
    var row = document.createElement('div');
    row.className = 'lm-set_row';
    var lab = document.createElement('div');
    lab.className = 'lm-set_label';
    lab.textContent = title;
    var b = document.createElement('button');
    b.type = 'button';
    b.className = 'lm-set_switch';
    var draw = function () {
      b.classList.toggle('lm-on', !!CFG[key]);
      b.textContent = CFG[key] ? 'показываем' : 'не показываем';
    };
    b.addEventListener('click', function () { tuneSet(key, !CFG[key]); draw(); });
    draw();
    row.appendChild(lab);
    row.appendChild(b);
    return row;
  }

  function openSettings() {
    setClose();

    var wrap = document.createElement('div');
    wrap.id = 'lm-set';

    var win = document.createElement('div');
    win.className = 'lm-set_win';

    /* --- верх: уплотнения --- */
    var top = setBlock(null);
    top.classList.add('lm-set_top');

    var left = document.createElement('div');
    left.className = 'lm-set_left';
    var h = document.createElement('div');
    h.className = 'lm-set_head';
    h.textContent = 'Максимальная высота';
    left.appendChild(h);

    var slider = document.createElement('input');
    slider.type = 'range';
    slider.className = 'lm-set_slider';

    var phone = setPhone();

    var radios = [];
    var redraw = function () {
      var t = TUNE[setPick];
      slider.min = String(t.min);
      slider.max = String(t.max);
      slider.step = String(t.step || 1);
      slider.value = String(CFG[setPick]);
      setPhoneDraw(phone, CFG[setPick]);
      radios.forEach(function (r) {
        r.el.classList.toggle('lm-on', r.key === setPick);
      });
      val.textContent = CFG[setPick] + '%';
    };

    var val = document.createElement('div');
    val.className = 'lm-set_val';

    SET_ROWS.forEach(function (r) {
      var b = document.createElement('button');
      b.type = 'button';
      b.className = 'lm-set_radio';
      b.textContent = r.label;
      b.addEventListener('click', function () { setPick = r.key; redraw(); });
      radios.push({ key: r.key, el: b });
      left.appendChild(b);
    });

    var reset = document.createElement('button');
    reset.type = 'button';
    reset.className = 'lm-set_reset';
    reset.textContent = 'сбросить';
    reset.addEventListener('click', function () {
      tuneReset(setPick);
      redraw();
      setApply(setPick);
    });
    left.appendChild(reset);

    /* Ползунок вертикальный — поворотом, а не свойством. Вертикальную
       раскладку ползунка Safari на iOS не поддерживает ни через
       appearance, ни через writing-mode; поворот работает везде и
       одинаково. Обёртка держит место: повёрнутый элемент занимает в
       потоке своё исходное, горизонтальное, место.
       Поворот по часовой, а не против: так меньшее значение
       оказывается СВЕРХУ, и движение пальца вверх ужимает содержимое —
       одновременно с полосой на схемофоне, которая тоже уходит вверх. */
    slider.addEventListener('input', function () {
      var v = tuneSet(setPick, slider.value);
      setPhoneDraw(phone, v);
      val.textContent = v + '%';
      setApply(setPick);
    });

    var spin = document.createElement('div');
    spin.className = 'lm-set_spin';
    spin.appendChild(slider);

    var mid = document.createElement('div');
    mid.className = 'lm-set_mid';
    mid.appendChild(spin);

    /* Число ставим под схемофоном, а не под ползунком. Под ползунком оно
       висело само по себе и сбивало выравнивание всего ряда; под
       схемофоном оно подпись к тому, что человек и разглядывает. */
    var right = document.createElement('div');
    right.className = 'lm-set_phone';
    right.appendChild(phone);
    right.appendChild(val);

    /* Порядок: кнопки — схемофон — ползунок. Ползунок стоит вплотную к
       схемофону справа, потому что двигают его, глядя на схемофон:
       палец и картинка должны быть рядом, а не через колонку. */
    top.appendChild(left);
    top.appendChild(right);
    top.appendChild(mid);
    win.appendChild(top);

    /* --- scroll-connect --- */
    /* Заголовок собираем сами, а не через setBlock: он уходит ВНУТРЬ
       левой колонки, к ползунку и числу, а не встаёт над строкой во всю
       ширину. Разбор — у правил .lm-set_dock: дорожка значков вдвое выше
       ползунка, и заголовок с числом занимают место, которое иначе
       пустовало бы рядом с ней. */
    var dock = setBlock(null);
    dock.classList.add('lm-set_dock_block');
    var dockRow = document.createElement('div');
    dockRow.className = 'lm-set_dock';
    var dockCol = document.createElement('div');
    dockCol.className = 'lm-set_dockcol';
    var dockHead = document.createElement('div');
    dockHead.className = 'lm-set_head';
    dockHead.textContent = 'Точность scroll-connect';
    dockCol.appendChild(dockHead);
    var dockPic = document.createElement('div');
    dockPic.className = 'lm-set_dockpic';
    /* Значки настоящие — те же, что летают по странице: тот же
       треугольник, тот же размер, те же цвета, то же свечение у гнезда.
       Нарисовать вместо них пару рамочных треугольников было проще, но
       тогда картинка показывала бы не то, что происходит: у гнезда есть
       свечение, и именно по нему человек ловит попадание.
       Размер обязан быть настоящим и по второй причине: допуск показан
       расстоянием между двумя предметами, а расстояние читается только
       вместе с их размером. Уменьшенные значки при том же расхождении
       выглядели куда дальше друг от друга, чем на самом деле, — то есть
       картинка врала про то, насколько точно надо попасть. */
    var mkTri = function (cls, fill, glow) {
      var b = document.createElement('div');
      b.className = cls;
      var svg = svgNode('svg', {
        viewBox: '0 0 40 40',
        width: String(CFG.jumpSize), height: String(CFG.jumpSize),
        xmlns: SVG_NS, 'aria-hidden': 'true'
      });
      svg.appendChild(svgNode('polygon', { fill: fill, points: JUMP_TRIANGLE }));
      /* Поворот на 180 — как у настоящих. Треугольник лепры нарисован
         остриём вверх, а на странице и стрелка, и гнездо смотрят вниз;
         без поворота картинка в настройках стояла кверху ногами. */
      svg.style.transform = 'rotate(180deg)';
      if (glow) svg.style.filter =
        'drop-shadow(0 0 2px ' + CFG.discoGlow + ') drop-shadow(0 0 5px ' + CFG.discoGlow + ')';
      b.appendChild(svg);
      return b;
    };
    var dockArrow = mkTri('lm-set_arrow', CFG.jumpColor, false);
    var dockNest = mkTri('lm-set_nest', CFG.discoNest || 'rgb(45,44,43)', true);
    dockPic.appendChild(dockArrow);
    dockPic.appendChild(dockNest);

    var dockSlider = document.createElement('input');
    dockSlider.type = 'range';
    dockSlider.className = 'lm-set_flat';
    dockSlider.min = String(TUNE.discoDock.min);
    dockSlider.max = String(TUNE.discoDock.max);
    dockSlider.step = '1';
    dockSlider.value = String(CFG.discoDock);

    var dockVal = document.createElement('div');
    dockVal.className = 'lm-set_val';

    /* Картинка показывает допуск в НАСТОЯЩИХ пикселях: стрелка и гнездо
       разъезжаются ровно на то расстояние, которое скрипт считает
       попаданием. Абстрактная шкала «точность 30%» не сказала бы
       ничего — а два значка в пальце друг от друга говорят сразу. */
    var dockDraw = function () {
      dockVal.textContent = CFG.discoDock + 'px';
      /* Расстояние между ЦЕНТРАМИ значков, а не между их коробками.
         Допуск стыковки — это и есть разрешённое расхождение центров:
         скрипт считает попаданием, когда середина гнезда отстоит от
         середины стрелки не больше чем на discoDock. Первая сборка
         отодвигала гнездо на discoDock от НИЗА стрелки, то есть центры
         расходились на сорок пикселей сверх допуска — картинка врала
         втрое и вдобавок требовала вдвое больше места по высоте.
         Правильный сдвиг отрицательный: значки должны наезжать друг на
         друга, и чем точнее допуск, тем сильнее. Это и есть правда —
         в момент стыковки они почти совпадают.
         Вычитается CFG.jumpSize — рост значка: расстояние между
         центрами равно «отбивка плюс рост», и чтобы центры разошлись
         ровно на discoDock, отбивке остаётся разница.
         setProperty с весом, а не присваивание: в правилах у этих
         значков стоит margin: 0 auto !important, и обычный инлайновый
         стиль его не перебивает — ползунок двигался, значение
         применялось, а картинка стояла на месте. */
      dockNest.style.setProperty('margin-top',
        (CFG.discoDock - CFG.jumpSize) + 'px', 'important');
    };
    dockSlider.addEventListener('input', function () {
      tuneSet('discoDock', dockSlider.value);
      dockDraw();
    });
    dockDraw();

    dockCol.appendChild(dockSlider);
    dockCol.appendChild(dockVal);
    dockRow.appendChild(dockCol);
    dockRow.appendChild(dockPic);
    dock.appendChild(dockRow);
    win.appendChild(dock);

    /* --- уведомления --- */
    var note = setBlock('Уведомления пыни');
    var sideRow = setChoice('pynToastSide', 'Плашка', ['снизу', 'сверху']);
    var sideSync = function () {
      /* Плашка показывается при «плашкой» и «и так и так». При «звуком»
         и «никак» её нет вовсе, и спрашивать про её сторону бессмысленно. */
      setRowOff(sideRow, CFG.pynSound === 'ding' || CFG.pynSound === 'none');
    };
    /* Сторона плашки — ПЕРВЫМ рядом, «чем сообщать» — вторым, хотя
       зависимость обратная: гаснет сторона, а гасит её выбор способа.
       Порядок при этом читается сверху вниз как «плашка снизу, и
       сообщать ею», то есть от того, что видно, к тому, чем это
       вызвано. Ряд, который гаснет, стоит над своей причиной, а не под
       ней, — и погасание сразу видно тем же взглядом, каким нажимали.
       На устройство это не влияет: sideSync зовётся из обработчика
       pynSound по ссылке, а не по соседству в разметке. Но собрать
       sideRow всё равно надо РАНЬШЕ — на него ссылается sideSync. */
    note.appendChild(sideRow);
    note.appendChild(setChoice('pynSound', 'Сообщать',
      ['плашкой', 'звуком', 'и так и так', 'никак'], sideSync));
    sideSync();
    win.appendChild(note);

    /* --- разное --- */
    var other = setBlock('Разное');

    /* Притемнение — первым пунктом раздела: из всего здешнего оно одно
       меняет вид страницы целиком, а не отдельную мелочь.

       Переключатель из двух слов вместо «показываем / не показываем».
       Настройка отвечает не на вопрос «показывать ли», а на вопрос
       «что именно темнее» — и пара «Карточки / Фон» отвечает на него
       прямо, тогда как «не показываем» требовало держать в голове, что
       именно считается заводским.
       «Карточки» — это cardsLift === false, то есть заводское поведение
       лепры: страница белая, карточки чуть темнее. «Фон» — обратный
       набор.

       Свой слушатель ставится ПОСЛЕ навешенного setChoice и потому
       срабатывает вторым — когда CFG уже обновлён. Применить класс
       раньше записи значения означало бы применить прошлое. */
    var cardsRow = setChoice('cardsLift', 'Сделать чуть темнее',
                             ['Карточки', 'Фон'], applyCards);
    other.appendChild(cardsRow);

    other.appendChild(setToggle('videoLink', 'Ссылка «Link» под видео-роликом'));

    var navRow = setToggle('navSticky', 'Планка навигации при скролле');
    navRow.querySelector('.lm-set_switch')
      .addEventListener('click', function () {
        applyNavStick();
        guard('syncTopbarVars', syncTopbarVars)();
      });
    other.appendChild(navRow);

    /* Свой слушатель после setToggle — по той же причине, что и у
       карточек: он срабатывает вторым, когда CFG уже переписан. */
    var archRow = setToggle('navArchive', 'Архив в навигационной штуке');
    archRow.querySelector('.lm-set_switch')
      .addEventListener('click', function () { applyNavArch(); });
    other.appendChild(archRow);

    win.appendChild(other);

    /* Отдельным разделом, а не в «Другом»: тут не удобства, а
       единственное место, где скрипт что-то отправляет от имени
       человека. Пусть это будет видно. */
    var lab = setBlock('Икспириментальное');
    lab.appendChild(setToggle('pynVote', 'Голосовалка в пыне'));
    lab.appendChild(setToggle('pynReply', 'Ответики в пыне'));
    win.appendChild(lab);

    var foot = document.createElement('div');
    foot.className = 'lm-set_foot';
    var close = document.createElement('button');
    close.type = 'button';
    close.className = 'lm-set_close';
    close.textContent = 'Закрыть';
    close.addEventListener('click', setClose);
    foot.appendChild(close);
    win.appendChild(foot);

    /* Тап по затемнению — тоже закрытие. На самом окне нажатие
       останавливаем, иначе попадание мимо органа закрывало бы попап. */
    wrap.addEventListener('click', setClose);
    win.addEventListener('click', function (e) { e.stopPropagation(); });

    wrap.appendChild(win);
    (document.body || document.documentElement).appendChild(wrap);
    redraw();
  }

  /* Открыть по тапу в середину гертруды. Середина считается долями, а не
     пикселями: картинка у каждого своя, и в пикселях «серединой» у
     широкой вышла бы полоска, а у узкой — почти вся. */
  function bindSettings(nest) {
    if (!CFG.settings || !nest || nest.dataset.lmSet) return;
    nest.dataset.lmSet = '1';
    nest.addEventListener('click', function (e) {
      var r = nest.getBoundingClientRect();
      if (!r.width || !r.height) return;
      var x = (e.clientX - r.left) / r.width;
      var y = (e.clientY - r.top) / r.height;
      if (x < 0.3 || x > 0.7 || y < 0.3 || y > 0.7) return;
      e.preventDefault();
      e.stopPropagation();
      guard('openSettings', openSettings)();
    });
  }

  /* ============================================================
     ВСПЛЫВАЮЩИЕ ПОДСКАЗКИ
     ============================================================

     Значки без подписей — переключатель типа ленты, дальше пиктограммы
     уплотнения — на десктопе объясняются наведением мыши. На телефоне
     наведения нет, а место под постоянные подписи в трети колонки взять
     негде: девятипиксельный текст под значками лепра и рисует, и он там
     нечитаем.

     Поэтому подсказка по тапу. Плашка одна на весь скрипт: показывать
     их можно только по одной, а держать по узлу на каждый значок —
     лишние узлы и лишний разбор, кому какая принадлежит.

     Тап по значку почти всегда что-то делает (переключает ленту,
     перезагружает её), поэтому подсказка вешается на touchstart и
     показывается НЕМЕДЛЕННО, до всякой перезагрузки: иначе человек
     увидел бы её на четверть секунды или не увидел вовсе. Обработчик
     пассивный и ничего не отменяет — родное действие значка должно
     произойти как ни в чём не бывало.

     Текст, где можно, берётся из самой разметки: у значков ленты лепра
     кладёт подпись в .b-index_view_about, мы её только прячем. Так
     подсказка не разойдётся с тем, что лепра называет этими режимами,
     если она поменяет формулировки. */

  var HINT_MS = 1600;
  var hintTimer = null;

  function hintBox() {
    var b = document.getElementById('lm-hint');
    if (b) return b;
    b = document.createElement('div');
    b.id = 'lm-hint';
    b.setAttribute('aria-hidden', 'true');
    (document.body || document.documentElement).appendChild(b);
    return b;
  }

  function showHint(el, text) {
    if (!text) return;
    var b = hintBox();
    b.textContent = text;
    b.classList.add('lm-on');

    /* Координаты — документные: плашка лежит в body, а он у нас
       position: relative без полей. Прибавляем прокрутку через
       scrollTopNow: из-за overflow-x на body её иногда ведёт не окно. */
    var r = el.getBoundingClientRect();
    var W = document.documentElement.clientWidth || 0;
    b.style.setProperty('left', '0px', 'important');   /* до замера ширины */
    var bw = b.getBoundingClientRect().width;
    var left = Math.round(r.left + r.width / 2 - bw / 2);
    left = Math.max(CFG.pageEdge, Math.min(left, W - CFG.pageEdge - bw));
    b.style.setProperty('left', left + 'px', 'important');
    b.style.setProperty('top',
      Math.round(r.bottom + scrollTopNow() + 6) + 'px', 'important');

    if (hintTimer) clearTimeout(hintTimer);
    hintTimer = setTimeout(function () {
      hintTimer = null;
      b.classList.remove('lm-on');
    }, HINT_MS);
  }

  /* Повесить подсказку на значок. Метка в dataset, а не в WeakSet:
     значки переключателя лепра при смене ленты подменяет целиком, и
     метка вместе с узлом должна уходить. */
  function bindHint(el, text) {
    if (!el || el.dataset.lmHint) return;
    el.dataset.lmHint = '1';
    el.addEventListener('touchstart', function () {
      guard('showHint', showHint)(el, text);
    }, { passive: true });
    /* Мышь — для проверки на настольном браузере; на телефоне это
       событие приходит после touchstart и попадает в тот же таймер. */
    el.addEventListener('click', function () {
      guard('showHint', showHint)(el, text);
    });
  }

  /* Значки типа ленты. Текст лепры («заглавная и подсайты») содержит
     ссылку на общий список подлепр — берём только слова. */
  function mountFeedHints() {
    sliceOf(document.querySelectorAll('.lm-navthing_extra .b-slider_scale_icon'))
      .forEach(function (icon) {
        var about = icon.querySelector('.b-index_view_about');
        var text = about ? about.textContent.replace(/\s+/g, ' ').trim() : '';
        if (!text) return;
        bindHint(icon, text);
      });
  }

  /* ============================================================
     4.1. НАВИГАЦИОННАЯ ШТУКА
     ============================================================ */

  /* Строка на месте серого разделителя под шапкой. Внутри — то, до чего
     на телефоне иначе не добраться: ссылки навигационной штуки лепры
     (сама она нарисована картинкой 642×377 с абсолютно размеченными
     поверх пустыми <a> — переносить её как есть некуда), гертруда и
     овощебаза из левой колонки главной.

     Строится ПОСЛЕ relayoutHeader: та переносит в шапку порог постов и
     счётчики, и вставлять блок за шапку имеет смысл, когда шапка собрана. */

  var NAV_KEY = 'lm-navthing';    /* закреплено ли (открывать сразу) */
  var GERT_KEY = 'lm-gertruda';   /* последняя увиденная гертруда */

  /* Значок свёрнутой строки — герб «Блогов Империи», тот же файл, что
     лепра кладёт внутрь блока. Нарисованного компаса тут больше нет:
     свой значок ни на что на странице не похож, а герб уже связан
     смыслом с содержимым — строка развернётся именно в него.
     Берём адрес, а не сам узел: узел леприн и прибит абсолютно в угол
     своего блока, а в памяти на внутренних страницах его вообще нет —
     остаётся только адрес из записи. */
  function crestSrc() {
    var img = document.querySelector('.b-aside_imperial_blogs_bg');
    var src = img && img.getAttribute('src');
    if (src && src.slice(0, 5) !== 'data:') return src;
    var saved = cachedBlogs();
    return (saved && saved.i) || '';
  }

  /* Гвоздик. Одно и то же начертание для обоих положений: откреплённый —
     тот же значок, наклонённый и приглушённый правилом. Две разные
     картинки пришлось бы держать согласованными по толщине линий. */
  var PIN_SVG =
    '<svg viewBox="0 0 24 24" width="15" height="15" ' +
    'aria-hidden="true" focusable="false">' +
    '<g fill="none" stroke="currentColor" stroke-width="2" ' +
    'stroke-linecap="round" stroke-linejoin="round">' +
    '<path d="M9 3h6"/><path d="M10 3v7l-3 3.5V15h10v-1.5L14 10V3"/>' +
    '<path d="M12 15v6"/></g></svg>';

  var BLOGS_KEY = 'lm-blogs';     /* последний увиденный список подлепр */
  var PRES_KEY = 'lm-president';  /* последний увиденный блок президента */
  var BLOGS_URL = 'https://leprosorium.ru/underground/';
  var ARCHIVE_URL = 'https://leprosorium.ru/archive/';
  var DEMOCRACY_URL = 'https://leprosorium.ru/democracy/';
  var VEG_KEY = 'lm-veg';         /* были ли у овощебазы замены */
  var VEG_URL = 'https://leprosorium.ru/fraud/replacements/';

  function vegWasOn() {
    try { return localStorage.getItem(VEG_KEY) === '1'; } catch (e) { return false; }
  }

  /* Овощебаза жива, только если в ней есть замены. Разметку лепра отдаёт
     всегда — и заголовок, и пустой список, — поэтому решает не наличие
     блока, а наличие пунктов.
     Прячем блок целиком классом, а не разбираем его: список у лепры
     наполняется её скриптом уже после разметки, и если он придёт позже,
     достаточно вернуть класс — восстанавливать удалённые узлы не надо.
     Состояние запоминаем: на внутренних страницах блока нет вовсе, и
     решать там нечем, кроме прошлого захода на главную. Записываем
     только когда блок настоящий — иначе внутренняя страница затирала бы
     память нулём просто потому, что овощебазы на ней не бывает. */
  function syncVeg() {
    var veg = document.querySelector('.lm-navthing_veg');
    if (!veg) return;
    var box = veg.querySelector('.b-aside_replacements');
    var on;
    if (box) {
      on = !!box.querySelector('.b-aside_replacements_list_item');
      try { localStorage.setItem(VEG_KEY, on ? '1' : '0'); } catch (e) {}
    } else {
      /* восстановленная по памяти ссылка — её кладём, только если в
         прошлый раз замены были; пусто здесь значит «не показывать» */
      on = !!veg.firstChild;
    }
    veg.classList.toggle('lm-on', on);
  }

  function navAlways() {
    return prefGet(NAV_KEY) === '1';
  }

  /* Гертруда лежит только в разметке главной, а блок нужен на всех
     страницах. Запоминаем последнюю увиденную картинку и на прочих
     страницах показываем её: она и так меняется от захода к заходу,
     так что вчерашняя — не ошибка, а просто предыдущая. */
  function rememberGertruda() {
    var img = document.querySelector('.b-gertruda img');
    var src = img && img.getAttribute('src');
    if (!src || src.slice(0, 5) === 'data:') return;
    try { localStorage.setItem(GERT_KEY, src); } catch (e) {}
  }

  function cachedGertruda() {
    try { return localStorage.getItem(GERT_KEY) || ''; } catch (e) { return ''; }
  }

  /* Гертруда приходит непрозрачной. Рваный край у неё нарисован по
     сплошному полю, и это поле — часть файла, а не подложка под ним:
     померено на живом примере, все четыре угла с альфой 255.
     На белой странице поле читается прямоугольной обложкой под
     картинкой, а в тёмной теме обратная инверсия возвращает его вместе
     с рисунком, и оно светится.

     Вычитаем поле сами. Заливкой от краёв, а не отбором по цвету:
     светлые пятна внутри рисунка отбором пробило бы насквозь, а
     заливка снимает только то, что связано с краем картинки.
     Цвет поля не задан заранее — берётся самый частый по периметру.
     Край поля мягкий (сжатие размывает границу на пару пикселей),
     поэтому альфа не двоичная: до NEAR — насквозь, от FAR — совсем
     непрозрачно, между ними линейно. Двоичная оставляла бы по контуру
     кайму исходного цвета.
     Готовое кладём обратно в ту же картинку адресом data: — поэтому
     rememberGertruda и запоминает адрес ДО этого, иначе в память ушёл
     бы обрезанный вариант вместо ссылки.

     Всё это требует чтения пикселей чужого домена, то есть его
     разрешения. Не разрешит — копия не загрузится, сработает onerror и
     останется как было. Каждый исход пишем в журнал: тут уже дважды
     подводили догадки вместо цифр. */
  var GERT_NEAR = 10;   /* ближе этого к цвету поля — насквозь */
  var GERT_FAR = 45;    /* дальше — не трогаем */
  var GERT_MAXPX = 4000000;

  function prepGertruda(nest, img, src) {
    if (CFG.gertrudaDark === 'invert') { nest.classList.add('lm-opaque'); return; }

    function fallback(why) {
      note('гертруда: ' + why +
           (CFG.gertrudaDark === 'auto' ? ' — отдаём инверсии' : ''));
      if (CFG.gertrudaDark === 'auto') nest.classList.add('lm-opaque');
    }

    if (!src || !('Image' in window)) return;

    var probe = new window.Image();
    probe.crossOrigin = 'anonymous';

    probe.onload = guard('gertPixels', function () {
      var w = probe.naturalWidth, h = probe.naturalHeight;
      if (!w || !h) { fallback('копия без размеров'); return; }
      if (w * h > GERT_MAXPX) { fallback('великовата, ' + w + '×' + h); return; }

      var cv = document.createElement('canvas');
      cv.width = w; cv.height = h;
      var cx = cv.getContext('2d');
      if (!cx) { fallback('холст недоступен'); return; }
      cx.drawImage(probe, 0, 0);
      var id = cx.getImageData(0, 0, w, h), D = id.data;

      /* Уже с прозрачным краем — вычитать нечего. */
      var cor = [0, (w - 1) * 4, (h - 1) * w * 4, ((h - 1) * w + w - 1) * 4];
      var clear = false, ci;
      for (ci = 0; ci < 4; ci++) if (D[cor[ci] + 3] < 250) clear = true;
      if (clear) { note('гертруда: край уже прозрачный'); return; }

      if (!CFG.gertrudaCut) { fallback('обрезка выключена'); return; }

      /* Самый частый цвет по периметру. */
      var tally = {}, best = -1, key = -1, x, y, i, k;
      function ring(x2, y2) {
        i = (y2 * w + x2) * 4;
        k = (D[i] << 16) | (D[i + 1] << 8) | D[i + 2];
        tally[k] = (tally[k] || 0) + 1;
        if (tally[k] > best) { best = tally[k]; key = k; }
      }
      for (x = 0; x < w; x++) { ring(x, 0); ring(x, h - 1); }
      for (y = 0; y < h; y++) { ring(0, y); ring(w - 1, y); }
      var kr = (key >> 16) & 255, kg = (key >> 8) & 255, kb = key & 255;

      /* Заливка от краёв. Помечаем ДО постановки в очередь, поэтому
         каждая точка попадает в неё не больше раза — стек заведомо
         влезает в w*h. */
      function far(p) {
        var dr = D[p] - kr; if (dr < 0) dr = -dr;
        var dg = D[p + 1] - kg; if (dg < 0) dg = -dg;
        var db = D[p + 2] - kb; if (db < 0) db = -db;
        return dr > dg ? (dr > db ? dr : db) : (dg > db ? dg : db);
      }
      var n = w * h;
      var seen = new Uint8Array(n);
      var stack = new Int32Array(n);
      var sp = 0, cut = 0;
      function push(c) {
        if (seen[c]) return;
        if (far(c * 4) >= GERT_FAR) return;
        seen[c] = 1; stack[sp++] = c;
      }
      for (x = 0; x < w; x++) { push(x); push((h - 1) * w + x); }
      for (y = 0; y < h; y++) { push(y * w); push(y * w + w - 1); }

      while (sp) {
        var c = stack[--sp];
        var d = far(c * 4);
        var a = d <= GERT_NEAR ? 0
              : Math.round(255 * (d - GERT_NEAR) / (GERT_FAR - GERT_NEAR));
        D[c * 4 + 3] = a;
        if (a < 255) cut++;
        var cx2 = c % w, cy2 = (c - cx2) / w;
        if (cx2 > 0) push(c - 1);
        if (cx2 < w - 1) push(c + 1);
        if (cy2 > 0) push(c - w);
        if (cy2 < h - 1) push(c + w);
      }

      var part = cut / n;
      var num = 'поле rgb(' + kr + ',' + kg + ',' + kb + '), снято ' +
                Math.round(part * 100) + '% площади';
      /* Съело почти всю картинку — значит цвет поля совпал с рисунком.
         Пустая обрезка тоже ни к чему: картинка и так до краёв. */
      if (part > 0.85) { fallback(num + ' — слишком много, не режем'); return; }
      if (part < 0.005) { fallback(num + ' — каймы нет'); return; }

      cx.putImageData(id, 0, 0);
      img.setAttribute('src', cv.toDataURL('image/png'));
      note('гертруда: ' + num + ' — кайма снята');
    });

    probe.onerror = function () {
      fallback('пиксели не прочитать, домен не разрешил чтение');
    };

    probe.src = src;
  }

  /* «Блоги Империи» — тоже только на главной (и в левой колонке подлепры).
     Запоминаем не разметку, а разобранные данные: заголовок, герб и пары
     «адрес — название». Собранная обратно из них копия заведомо не внесёт
     в страницу ничего, кроме текста и адресов, — в отличие от innerHTML,
     который вернул бы на страницу произвольную разметку из хранилища.

     Счётчик «0/524» и крестик «отписаться» в запись не идут намеренно:
     число непрочитанного к следующей странице уже неверно, а крестик без
     скрипта лепры — просто нерабочий значок. */
  /* ---- Президент из памяти ----

     Блок президента лепра кладёт в правую колонку, а колонки этой нет
     на целых разделах: в профиле, в магазине, на внутренних страницах.
     Список подлепр там же и по той же причине отсутствует — его мы
     давно храним и восстанавливаем, а президента до сих пор нет, и в
     рамке «Белый дом» стоял один, без имени. Заводим ему такую же
     память.

     Храним разобранное, а не разметку. Причина не в размере: у блока
     внутри лежит герб (.b-aside_president_bg), который мы всё равно
     прячем, и класс js-date на датах, за который берётся скрипт лепры.
     Сохранив разметку целиком, мы принесли бы на чужую страницу оба, а
     нужны нам три вещи — имя, адрес и две строчки подписи.

     Строки подписи режем ПО <br>, а не по textContent: у лепры это
     «Президент Грузии» и «с 26.02 по 22.02», разделённые переводом
     строки, и склеенные в одну они читались бы кашей.

     Даты в копии застывают до следующего захода на страницу с правой
     колонкой. Это та же плата, что и за список подлепр: срок
     президентства меняется раз в год, а колонка попадается на глаза
     при первом же возвращении на главную. */

  /* Корона слева от ника президента.

     Своя отрисовка, а не картинка лепры. Картинка есть — это
     .b-aside_president_bg, файл president_.png 50 на 49, — но взять её
     нельзя по двум причинам сразу. Первая: на подлепрах в этом узле
     лежит не корона, а собственный герб подлепры, и значок получался бы
     разный на разных доменах. Вторая: блока президента нет на целых
     разделах (профиль, магазин, внутренние страницы), мы восстанавливаем
     его из памяти, и пришлось бы хранить ещё и адрес картинки.
     Нарисованная корона одна и та же везде и ничего не требует от
     страницы.

     Рисунок повторяет лепровский: обод с камнями, тёмно-синяя шапка под
     золотыми дужками, держава с крестом сверху и меховая опушка внизу.
     Опушка соболиная, а не жемчужная, как на лепровской картинке:
     бледно-серая полоска на светлом фоне рамки читалась не основанием
     короны, а пустотой под ней — корона будто висела в воздухе.
     Система координат 20 на 20 — та же, что у прочих наших значков.

     Цвета заданы прямо в фигурах, а не currentColor: корона тем и
     корона, что золотая, и в тон серой подписи она была бы просто
     кляксой. Плата за это — правило в тёмной теме: страница там
     переворачивается целиком, и значок надо перевернуть обратно, как
     картинки и эмодзи. */
  var PRES_CROWN =
    '<svg viewBox="0 0 20 20" xmlns="http://www.w3.org/2000/svg"' +
    ' aria-hidden="true">' +
    '<path d="M4.3 12.6 C4.3 8.6 6.9 6.6 10 6.6 C13.1 6.6 15.7 8.6 15.7 12.6 Z"' +
    ' fill="#2c2168"/>' +
    '<path d="M4.3 12.6 C4.3 8.6 6.9 6.6 10 6.6 C13.1 6.6 15.7 8.6 15.7 12.6"' +
    ' fill="none" stroke="#dda42a" stroke-width="1.6"/>' +
    '<path d="M10 6.6 L10 12.6" stroke="#dda42a" stroke-width="1.3"/>' +
    '<rect x="2.5" y="12" width="15" height="3.8" rx="1.1" fill="#e8b334"/>' +
    '<circle cx="6" cy="13.9" r="0.9" fill="#c0392b"/>' +
    '<circle cx="10" cy="13.9" r="0.9" fill="#2f6fb5"/>' +
    '<circle cx="14" cy="13.9" r="0.9" fill="#c0392b"/>' +
    '<rect x="2.1" y="15.5" width="15.8" height="2.2" rx="1.1" fill="#6b4a2b"/>' +
    '<circle cx="10" cy="5.2" r="1.5" fill="#e8b334"/>' +
    '<rect x="9.2" y="0.6" width="1.6" height="3.8" rx="0.5" fill="#e8b334"/>' +
    '<rect x="7.9" y="1.6" width="4.2" height="1.6" rx="0.5" fill="#e8b334"/>' +
    '</svg>';

  /* Ставится и на перенесённый узел лепры, и на копию из памяти —
     поэтому отдельной функцией, а не строкой в каждой ветке.
     Перед ссылкой, а не в начало блока: в начале блока у лепры лежат
     пробельные текстовые узлы, и корона отъехала бы от ника на их
     ширину. Строка блока выключена по центру, корона и ник — соседи по
     ней, и центруются вместе.
     Метка на случай повторного прохода: столбик собирается один раз, но
     дешевле проверить, чем однажды получить две короны. */
  function presCrown(box) {
    if (!box || box.querySelector('.lm-crown')) return;
    var a = box.querySelector('a');
    if (!a) return;
    var c = document.createElement('span');
    c.className = 'lm-crown';
    c.setAttribute('aria-hidden', 'true');
    c.innerHTML = PRES_CROWN;
    box.insertBefore(c, a);
  }

  function readPres(el) {
    var a = el.querySelector('a');
    if (!a) return null;
    var lines = [], cur = '';
    var pp = el.querySelector('p');
    if (pp) {
      sliceOf(pp.childNodes).forEach(function (n) {
        if (n.nodeType === 1 && n.tagName === 'BR') { lines.push(cur); cur = ''; return; }
        cur += (n.textContent || '');
      });
      lines.push(cur);
    }
    return {
      t: (a.textContent || '').replace(/\s+/g, ' ').trim(),
      u: a.getAttribute('href') || '',
      l: lines.map(function (x) { return x.replace(/\s+/g, ' ').trim(); })
              .filter(function (x) { return x; })
    };
  }

  function rememberPres(el) {
    var data = readPres(el);
    if (!data || !data.t) return;
    try { localStorage.setItem(PRES_KEY, JSON.stringify(data)); } catch (e) {}
  }

  function cachedPres() {
    try {
      var raw = localStorage.getItem(PRES_KEY);
      var data = raw && JSON.parse(raw);
      return (data && data.t && data.u) ? data : null;
    } catch (e) { return null; }
  }

  /* Классы лепры оставляем: по ним написаны и её правила, и наши, и обе
     копии — родная и восстановленная — выглядят одинаково. Герб не
     переносим вовсе: в колонке шириной в треть экрана он всё равно
     скрыт правилом. */
  function makePres(data) {
    var box = document.createElement('div');
    box.className = 'b-aside_item b-aside_president';
    var a = document.createElement('a');
    a.setAttribute('href', data.u);
    a.textContent = data.t;
    box.appendChild(a);
    if (data.l && data.l.length) {
      var pp = document.createElement('p');
      data.l.forEach(function (line, i) {
        if (i) pp.appendChild(document.createElement('br'));
        pp.appendChild(document.createTextNode(line));
      });
      box.appendChild(pp);
    }
    return box;
  }

  function readBlogs(el) {
    var head = el.querySelector('strong a') || el.querySelector('a');
    if (!head) return null;
    var pic = el.querySelector('.b-aside_imperial_blogs_bg');
    var data = {
      t: (head.textContent || '').trim(),
      u: head.getAttribute('href') || BLOGS_URL,
      i: (pic && pic.getAttribute('src')) || '',
      l: []
    };
    sliceOf(el.querySelectorAll('li')).forEach(function (li) {
      var a = li.querySelector('a:not(.b-close_btn)');
      var u = a && a.getAttribute('href');
      if (!a || !u || u.charAt(u.length - 1) === '#') return;
      data.l.push({ t: (a.textContent || '').trim(), u: u });
    });
    return data;
  }

  function rememberBlogs(el) {
    var data = readBlogs(el);
    if (!data) return;
    try { localStorage.setItem(BLOGS_KEY, JSON.stringify(data)); } catch (e) {}
  }

  function cachedBlogs() {
    try {
      var raw = localStorage.getItem(BLOGS_KEY);
      var data = raw && JSON.parse(raw);
      return (data && data.t && data.l) ? data : null;
    } catch (e) { return null; }
  }

  /* Классы лепры оставляем: герб, кегли и отступы описаны ими, и правила
     выше правят обе копии — родную и восстановленную — одинаково.
     Идентификатор картинки не переносим: на главной он уже занят. */
  function makeBlogs(data) {
    var box = document.createElement('div');
    box.className = 'b-aside_item b-aside_imperial_blogs';
    if (data.i) {
      var pic = document.createElement('img');
      pic.className = 'b-aside_imperial_blogs_bg';
      pic.setAttribute('src', data.i);
      pic.setAttribute('alt', '');
      box.appendChild(pic);
    }
    var head = document.createElement('strong');
    var a = document.createElement('a');
    a.setAttribute('href', data.u);
    a.textContent = data.t;
    head.appendChild(a);
    box.appendChild(head);

    var ul = document.createElement('ul');
    data.l.forEach(function (item) {
      var li = document.createElement('li');
      var link = document.createElement('a');
      link.setAttribute('href', item.u);
      link.textContent = item.t;
      li.appendChild(link);
      ul.appendChild(li);
    });
    box.appendChild(ul);
    return box;
  }

  function buildNavthing() {
    if (document.getElementById('lm-navthing')) return;
    var header = document.querySelector('.l-header');
    if (!header || !header.parentNode) return;

    rememberGertruda();

    var box = document.createElement('div');
    box.id = 'lm-navthing';

    var btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'lm-navthing_row';

    var icon = document.createElement('span');
    icon.className = 'lm-navthing_icon';
    var crest = crestSrc();
    if (crest) {
      var crestImg = document.createElement('img');
      crestImg.setAttribute('src', crest);
      crestImg.setAttribute('alt', '');
      icon.appendChild(crestImg);
    }
    var label = document.createElement('span');
    label.className = 'lm-navthing_label';
    label.textContent = 'Навигационная штука';
    /* знак шеврона — в CSS: он меняется по состоянию */
    var arrow = document.createElement('span');
    arrow.className = 'lm-navthing_arrow';
    btn.appendChild(icon);
    btn.appendChild(label);
    btn.appendChild(arrow);

    var body = document.createElement('div');
    body.className = 'lm-navthing_body';

    var top = document.createElement('div');
    top.className = 'lm-navthing_top';

    /* Гвоздик — по верху средней колонки, поверх гертруды. Своей ячейки
       у него больше нет: она была распоркой между двумя колонками, а в
       сетке из трёх равных долей распирать нечего. */
    var pin = document.createElement('button');
    pin.type = 'button';
    pin.className = 'lm-navthing_pin';
    pin.innerHTML = PIN_SVG;

    var links = document.createElement('div');
    links.className = 'lm-navthing_links';
    var blogs = document.querySelector('.b-aside_imperial_blogs');
    if (blogs) {
      rememberBlogs(blogs);
      links.appendChild(blogs);
    } else {
      var saved = cachedBlogs();
      if (saved) links.appendChild(makeBlogs(saved));
      /* Ни разметки, ни записи — первый заход не с главной. Пусто и
         ладно: столбик всё равно не схлопнется, ниже в нём блок власти
         и ссылка на архив, а они есть всегда. */
    }

    /* ---- Блок власти ----
       Президент и вход в Белый дом, обведённые общей рамкой. Своей
       обёрткой, а не двумя правилами по месту: рамка должна охватывать
       оба, а лежат они на разной глубине — президент отдельным блоком
       правой колонки, заголовок внутри блока блогов. Общего родителя у
       них нет, и одним CSS такую рамку не нарисовать.

       Заголовок ведёт в Белый дом, а не в общий список подлепр.
       Причина простая: «Блоги Империи» — ссылка на /underground/, ровно
       та же, что «N сайтов» в шапке, то есть дубль; а входа на страницу
       демократии из шапки нет вовсе.

       Заголовок ВЫНИМАЕМ из блока блогов, оставляя там один список.
       Узел леприн, но за ним у неё ничего не закреплено: обработчики
       отписки висят на пунктах списка, а не на заглавии. Список при
       этом остаётся на своём месте, ниже рамки.

       Текст и адрес меняем ПОСЛЕ rememberBlogs: в память должно лечь
       то, что отдала лепра, иначе на следующей странице мы прочитали бы
       из неё собственную подмену и потеряли настоящий адрес. */
    var gov = document.createElement('div');
    gov.className = 'lm-navthing_gov';

    /* Президент. Есть разметка — переносим узлом и заодно запоминаем;
       нет (профиль, магазин, внутренние страницы — правой колонки там
       не бывает) — собираем копию из памяти. Устройство памяти и то,
       почему храним разобранное, — у readPres. */
    var pres = document.querySelector('.b-aside_president');
    if (pres) {
      /* Корону вешаем ПОСЛЕ rememberPres: в память должно лечь то, что
         отдала лепра. Иначе на следующей странице мы прочитали бы из
         неё собственную вставку — та же оговорка и по той же причине,
         что у заголовка блогов ниже. */
      rememberPres(pres);
      presCrown(pres);
      gov.appendChild(pres);
    } else {
      var savedPres = cachedPres();
      if (savedPres) {
        var copyPres = makePres(savedPres);
        presCrown(copyPres);
        gov.appendChild(copyPres);
      }
    }

    var head = links.querySelector('.b-aside_imperial_blogs strong');
    if (head) {
      var headLink = head.querySelector('a');
      if (headLink) {
        headLink.setAttribute('href', DEMOCRACY_URL);
        headLink.textContent = 'Белый дом';
      }
      gov.appendChild(head);
    } else {
      /* Блока блогов на странице не было — собираем заголовок сами, той
         же разметкой: правила оформления одни на оба случая. */
      var mine = document.createElement('strong');
      var mineLink = document.createElement('a');
      mineLink.setAttribute('href', DEMOCRACY_URL);
      mineLink.textContent = 'Белый дом';
      mine.appendChild(mineLink);
      gov.appendChild(mine);
    }

    links.insertBefore(gov, links.firstChild);

    /* Архив — последней строкой столбика. Строим всегда, показываем по
       классу lm-arch (см. applyNavArch): переключатель в попапе должен
       действовать сразу, а не со следующей страницы.
       Адрес абсолютный, на главный домен. Относительный '/archive/' на
       подлепре увёл бы в её собственный архив, а он есть не у всех и
       называется тем же словом — то есть ссылка вела бы то туда, то
       сюда в зависимости от того, откуда нажали. */
    var arch = document.createElement('a');
    arch.className = 'lm-navthing_arch';
    arch.setAttribute('href', ARCHIVE_URL);
    arch.textContent = 'Архив';
    links.appendChild(arch);

    top.appendChild(links);

    /* Переносим саму картинку, а не блок .b-gertruda с нею внутри: у
       лепры картинка завёрнута в ссылку на главную, и вместе с блоком
       переехала бы и ссылка. Тап по гертруде теперь не делает ничего —
       на главную ведёт маска в шапке, а картинка тут просто картинка.
       Заодно отпадает нужда возвращать .b-gertruda из-под общего
       правила скрытия: пустой блок остаётся лежать где лежал.
       Картинка с адресом data: не в счёт — лепра ставит такую заглушкой
       до подгрузки настоящей (см. rememberGertruda). */
    var pic = document.createElement('div');
    pic.className = 'lm-navthing_pic';
    var nest = document.createElement('div');
    nest.className = 'lm-navthing_gert';
    bindSettings(nest);
    var gert = document.querySelector('.b-gertruda img');
    if (gert && (gert.getAttribute('src') || '').slice(0, 5) !== 'data:') {
      nest.appendChild(gert);
      prepGertruda(nest, gert, gert.getAttribute('src'));
    } else {
      var cached = cachedGertruda();
      if (cached) {
        var img = document.createElement('img');
        img.setAttribute('src', cached);
        img.setAttribute('alt', '');
        nest.appendChild(img);
        prepGertruda(nest, img, cached);
      }
    }
    /* Гвоздик кладём последним и внутрь гнезда: он стоит поверх картинки,
       а не рядом. Колонку добавляем всегда, даже без картинки, — она
       держит и гвоздик, и свою треть ширины. */
    nest.appendChild(pin);
    pic.appendChild(nest);
    top.appendChild(pic);

    /* Третья колонка — органы управления лентой, сверху вниз:
       переключатель вида, порог постов, поиск.

       Переключатель лежит в разметке ВНУТРИ формы порога, хотя к ней
       отношения не имеет: порог уходит на сервер полем формы, а тип
       ленты лепра переключает своим скриптом по id #js-index_slider.
       Поэтому вынимаем его ПЕРВЫМ, а форму переносим следом — иначе она
       уехала бы вместе с ним внутри и порядок в колонке сложился бы
       обратный задуманному.

       Ничего не копируем: переносим узлы как есть, обработчики при этом
       сохраняются. Копия в память, в отличие от гертруды и списка
       подлепр, не кладётся ни для одного из троих — восстановленная,
       она была бы картинкой без обработчиков и формой без адреса, то
       есть набором органов управления, которые ничего не делают.

       Место колонка держит в любом случае: доли заданы flex: 1 1 0, и
       пустой элемент получает ровно треть. Переключателя нет нигде,
       кроме главной, — на подсайтах и внутренних страницах в колонке
       останутся порог с поиском, и это правильно: переключать там
       нечего. */
    var extra = document.createElement('div');
    extra.className = 'lm-navthing_extra';

    /* Переключатель вида вынимаем ПЕРВЫМ, хотя стоять он будет
       четвёртым: в разметке лепры он лежит ВНУТРИ формы порога, и если
       сначала перенести форму, он уедет вместе с нею внутрь. Вынули —
       и дальше кладём в нужном порядке. */
    var slider = document.querySelector('.b-index_slider');
    var th = document.querySelector('.b-posts_threshold');

    /* Поиск. Метка lmMoved стоит только там, где его уже пристроила
       шапка, — на страницах с вкладками, в конце строки ссылок. Там он
       и остаётся: строка у него своя, и дублировать поиск в двух местах
       незачем. Проверяем метку, а не класс страницы: признак «блок уже
       на месте» честнее признака «страница такая-то», и если перенос в
       шапку почему-то не состоялся, поиск подберёт эта колонка. */
    var srch = document.querySelector('.b-header_search');
    if (srch && srch.dataset.lmMoved) srch = null;

    /* Порядок сверху вниз: кнопки диско, порог постов, поиск,
       переключатель вида. Сверху то, что набрано словами и прижато к
       левому краю, — три прямоугольника одной ширины и одного
       скругления читаются как столбик; тройка значков внизу, по центру,
       столбик закрывает и ни с чем не спорит. Задаётся порядок
       разметкой, а не свойством order: тогда он виден прямо здесь и не
       требует держать два места согласованными.
       Кнопки диско сюда не кладём: их вешает отдельный проход, и первым
       ребёнком — см. discoMountButtons и причину там же. */
    if (th) extra.appendChild(th);
    if (srch) extra.appendChild(srch);
    if (slider) extra.appendChild(slider);

    top.appendChild(extra);
    body.appendChild(top);

    var veg = document.createElement('div');
    veg.className = 'lm-navthing_veg';
    var vegBox = document.querySelector('.b-aside_replacements');
    if (vegBox) {
      /* Список замен лепра наполняет своим скриптом по id — перенос узла
         этому не мешает, getElementById найдёт его и на новом месте. */
      veg.appendChild(vegBox);
    } else if (vegWasOn()) {
      /* Блока на странице нет. Запасную ссылку кладём только если в
         прошлый раз замены были: иначе на внутренних страницах висела бы
         жёлтая плашка от овощебазы, которой человек не пользуется. */
      var vegLink = document.createElement('a');
      vegLink.className = 'b-aside_replacements_header';
      vegLink.setAttribute('href', VEG_URL);
      vegLink.textContent = 'Овощебаза';
      veg.appendChild(vegLink);
    }
    body.appendChild(veg);

    box.appendChild(btn);
    box.appendChild(body);
    /* Где поставить. Для липкости важно, чтобы родитель был высоким:
       липкий элемент держится только в его пределах, и как только
       родитель уедет, полоска отлипнет и уедет с ним.

       На главной шапка лежит в .l-i-content_main вместе со всей лентой —
       родитель высокий, ставим прямо за шапкой, и всё.

       На подлепрах иначе: шапка живёт в своей обёртке .l-header_subsite,
       а лента — в соседней .l-content. Полоска, поставленная за шапкой,
       отлипала на высоте этой обёртки, то есть у заглавия подлепры или у
       пенсне. Поднимаем её на уровень выше — туда, где обе обёртки
       соседи, — и родителем становится .l-i-wrapper во всю страницу.
       Порядок на экране при этом не меняется: обёртка шапки кончается
       ровно там, где полоска и стояла.

       Признак «родитель высокий» — содержит ли он ленту или комментарии.
       Проверять по именам обёрток было бы гаданием: у профиля, треда и
       разделов они свои. */
    var feed = document.getElementById('js-posts_holder') ||
               document.getElementById('js-comments_holder');
    var host = header.parentNode;
    if (feed && !host.contains(feed)) {
      var wrap = document.querySelector('.l-i-wrapper');
      var lift = host;
      while (lift && lift.parentNode !== wrap) lift = lift.parentNode;
      if (wrap && lift) { wrap.insertBefore(box, lift.nextSibling); host = null; }
    }
    if (host) host.insertBefore(box, header.nextSibling);
    document.documentElement.classList.add('lm-navthing_on');

    /* Поиск ушёл отсюда, и обёртка .l-header_aside могла опустеть только
       что: relayoutHeader проверял её, когда поиск ещё лежал внутри. */
    guard('hideEmptyAside', hideEmptyAside)();

    /* Гвоздик — про состояние при загрузке страницы, а не про текущий вид:
       свернуть закреплённый блок пальцем можно, но на следующей странице
       он снова развернётся. Этим он отличается от пенсне, которое просто
       помнит последнее положение. */
    function showPin(on) {
      pin.classList.toggle('lm-on', on);
      pin.setAttribute('aria-pressed', on ? 'true' : 'false');
      pin.setAttribute('title', on ? 'закреплено' : 'откреплено');
    }

    var pinned = navAlways();
    showPin(pinned);
    /* При сборке ставим состояние без перехода: анимировать нечего, а
       раскрывающаяся на глазах при загрузке панель выглядит нелепо.
       Поэтому классом напрямую, минуя navFold, и потолок снимаем сразу. */
    box.classList.toggle('lm-navthing__open', pinned);
    if (pinned) body.style.setProperty('max-height', 'none', 'important');
    btn.setAttribute('aria-expanded', pinned ? 'true' : 'false');

    btn.addEventListener('click', function (e) {
      e.preventDefault();

      /* Панель уже уехала под полоску, а класс всё ещё «раскрыта»:
         сворачивать нечего, показать — есть что. Возвращаем страницу к
         тому месту, где панель начинается, и оставляем её раскрытой.
         Иначе нажатие «раскрыть» раскрывало бы её вне экрана, где-то
         вверху, и выглядело бы как отказ работать.
         Прокрутка мгновенная — плавная у нас запрещена: она копит
         анимации и уносит страницу на десятки тысяч пикселей. */
      /* Уже выпала — второй тап убирает. */
      if (box.classList.contains('lm-navthing__drop')) {
        box.classList.remove('lm-navthing__drop');
        return;
      }

      /* Панель уехала под полоску, а мы посреди ленты: показываем её
         здесь же, выпадением из-под полоски. */
      if (box.classList.contains('lm-navthing__past')) {
        box.classList.add('lm-navthing__drop');
        box.classList.add('lm-navthing__open');
        body.style.removeProperty('max-height');
        btn.setAttribute('aria-expanded', 'true');
        armDropClose(box);
        return;
      }

      var on = !box.classList.contains('lm-navthing__open');
      navFold(box, on);
      /* Кегль поля выбора порога подбирается замером, а мерить можно
         только раскрытую панель: у свёрнутой все прямоугольники нулевые.
         Поэтому подгонка идёт здесь, сразу после разворачивания. */
      if (on) {
        guard('prepThreshold', prepThreshold)();
        guard('fitThreshold', fitThreshold)();
      }
    });

    pin.addEventListener('click', function (e) {
      e.preventDefault();
      var on = !pin.classList.contains('lm-on');
      showPin(on);
      prefSet(NAV_KEY, on ? '1' : '0');
    });

    /* Наблюдатель — на сам блок овощебазы, а не на общий: тот повешен на
       ленту или тред и до навигационной штуки не достаёт, а список замен
       приходит как раз добавлением узлов внутрь блока. */
    guard('syncVeg', syncVeg)();
    if (veg.querySelector('.b-aside_replacements') && 'MutationObserver' in window)
      new MutationObserver(guard('syncVeg', syncVeg))
        .observe(veg, { childList: true, subtree: true });
  }

  /* ============================================================
     4.2. ПЫНЬ
     ============================================================ */

  /* В десктопе колокольчик открывает окно поверх страницы, а на саму
     страницу уведомлений ведёт ссылка в его низу. На телефоне тап уходил
     прямо на страницу — окно лепры не открывалось.

     Чинить лепровское нечем: скрипта, который его строит, в сохранённой
     странице нет, а по её CSS видно, что окно рассчитано на мышь —
     min-width: 446px и прокрутка ленты только под наведением
     (.b-notification-feed_inner:hover { overflow-y: scroll }). Поэтому
     окно своё, а содержимое берём готовое: грузим страницу уведомлений
     и переносим оттуда ленту.

     Что переносится, то и должно работать. Всё, что у лепры держится на
     её скрипте (отписки, «ответить», «развернуть», отметка о прочтении),
     на перенесённых узлах обработчиков не получит, поэтому вырезается:
     кнопка, которая ничего не делает, хуже отсутствующей.

     Откуда берётся лента. Первая попытка запрашивала /my/events/ и
     разбирала ответ — в нём ленты не оказалось вовсе: сервер отдаёт
     30 КБ каркаса, а список собирает уже скрипт лепры, вытягивая шаблоны
     из /static/views/notifications/ и данные из /api/my/notifications/.
     Пойти этим же путём не вышло: тот же адрес, теми же куками, тем же
     методом отвечает 404 — чем именно лепра его зовёт, установить пока
     не удалось. Поэтому лента собирается её же скриптом в скрытом окне
     на ту же страницу, а мы забираем готовые узлы. Дороже одного
     запроса, зато не зависит от разгадки API. */

  var PYN_PAGE = '/my/events/';
  /* НАЙДЕНО ПОЗЖЕ, ВАЖНО ДЛЯ БУДУЩЕЙ ПЕРЕДЕЛКИ.
     Лента уведомлений собирается скрытым окном потому, что когда-то
     запрос к API отдавал 404 и причину найти не удалось. Проба API
     (pynProbe) на живом устройстве показала, что API работает:
       GET /api/my/notifications/?per_page=1&page=1  →  200
     — при тех же заголовках X-Futuware-UID/SID, что и счётчик. Без
     заголовков — 404; вот откуда взялась та ошибка.
     В ответе есть всё, чего не хватало разметке: id комментария и
     поста, текущий рейтинг, подсайт, а в _links — готовые адреса для
     mark_read и отписки. То есть голосовалку и «ответить» в окне пыни
     можно строить по данным, а не выковыривать из чужой разметки, и
     реальное время делается опросом одной последней записи вместо
     перезагрузки всей ленты окном.
     Окно пока не трогаем — оно работает. Но начинать пункт про
     голосовалку и ответ надо отсюда, а не с разметки. */
  var PYN_FRAME = 'lm-pyn-frame';   /* по нему скрипт узнаёт себя в окне */
  var pynData = null;       /* разобранный кусок ленты и набор значков */
  var pynAt = 0;            /* когда он загружен */
  var pynBusy = false;
  var pynFrame = null;
  var pynFrames = 0;        /* сколько раз создавалось скрытое окно */

  function onEventsPage() {
    return /^\/my\/events(\/|$)/.test(location.pathname);
  }

  /* Куда уходить, если окно не сложилось. Ссылка у пыни абсолютная и
     ведёт на главный домен — её и берём, а не свой адрес. */
  function pynHref() {
    var a = document.querySelector('a.js-header_button_events');
    return (a && a.getAttribute('href')) ||
           'https://leprosorium.ru' + PYN_PAGE;
  }

  /* Подпись уведомления собрана из кусков, разделённых точками. Часть
     кусков уходит, и точки остаются висеть по краям и парами. */
  function dropStrayDots(f) {
    var dot = function (el) {
      return !!el && el.classList.contains('b-notification-item_footer-delimiter');
    };
    var prevDot = true;                 /* начало строки — ведущая точка лишняя */
    sliceOf(f.children).forEach(function (el) {
      if (dot(el) && prevDot) { el.remove(); return; }
      prevDot = dot(el);
    });
    var last = f.children[f.children.length - 1];
    if (dot(last)) last.remove();
  }

  /* Ссылка на сам ответ. У лепры она уже есть в первой строке — название
     поста ведёт прямо на якорь этого комментария; берём её же, чтобы не
     собирать адрес из кусков. Запасной вариант — ссылка «N комментариев»
     плюс идентификатор из подписи: он и есть номер ответа. */
  function noteGoHref(item) {
    var post = item.querySelector('.b-notification-item__post');
    if (post && post.getAttribute('href')) return post.getAttribute('href');
    var link = item.querySelector('.b-notification-item_comments-link');
    if (!link || !link.getAttribute('href')) return null;
    var base = link.getAttribute('href').replace(/#.*$/, '');
    var foot = item.querySelector('.b-notification-item_footer');
    return foot && foot.id ? base + '#' + foot.id : base;
  }

  /* Значок вешаем до снятия идентификаторов: номер ответа лежит именно
     в id подписи, и после чистки собрать запасной адрес будет нечем. */
  function addNoteIcon(item) {
    var foot = item.querySelector('.b-notification-item_footer');
    if (!foot || foot.querySelector('.lm-note_go')) return;
    var href = noteGoHref(item);
    if (!href) return;
    var a = document.createElement('a');
    a.className = 'c_icon lm-note_go';
    a.setAttribute('href', href);
    a.setAttribute('title', 'Перейти к этому комментарию');
    foot.appendChild(a);
  }

  function addNoteIcons(root) {
    sliceOf(root.querySelectorAll('.b-notification-item')).forEach(addNoteIcon);
  }

  function pynClean(box) {
    sliceOf(box.querySelectorAll(
      '.b-notification-item_unsubscribe-menu,' + /* отписки */
      '.b-notification-item_mark-read,' +        /* отметка о прочтении */
      '.b-notification-item_answer-message,' +   /* «Отправлено» */
      '.b-notification-item_footer_answer,' +    /* «ответить» */
      '.js-roll_action'                          /* «развернуть» / «свернуть» */
    )).forEach(function (el) { el.remove(); });

    /* Без «развернуть» обрезанный текст показывать незачем — оставляем
       полный, он лежит рядом под классом hidden. */
    sliceOf(box.querySelectorAll('.js-roll_snippet'))
      .forEach(function (el) { el.remove(); });
    sliceOf(box.querySelectorAll('.js-roll_full'))
      .forEach(function (el) { el.classList.remove('hidden'); });

    sliceOf(box.querySelectorAll('.b-notification-item_footer'))
      .forEach(dropStrayDots);

    /* Раскрытие исходного комментария — как в десктопном окне лепры:
       шеврон слева от слова «комментарий», по нажатию под первой строкой
       разворачивается тот комментарий, на который ответили. Сам он в
       разметке уже есть, свёрнут инлайновой высотой.

       Лепровские классы js-… снимаем, а свой ставим: её обработчики
       живут на той же странице, куда мы вставляем окно, и делегированный
       обработчик подхватил бы наши узлы — с чужим data-notification и без
       её внутреннего состояния. Пунктирное подчёркивание .b-roll_down
       оставляем: теперь нажатие снова что-то делает. */
    sliceOf(box.querySelectorAll('.js-roll_parent_comment'))
      .forEach(function (el) {
        el.classList.remove('js-roll_parent_comment',
                            'js-roll_parent_comment__up');
        el.classList.add('lm-pyn_roll');
      });
    sliceOf(box.querySelectorAll('.b-notification-item_parent_comment'))
      .forEach(function (el) {
        el.classList.remove('js-notification-item_parent_comment');
        /* Свёрнутость лепра держит двумя способами: на странице классом
           hidden, в своём окне — инлайновой высотой. Снимаем оба и
           управляем видимостью сами, чтобы не зависеть от того, какой
           из них достанется. */
        el.classList.remove('hidden');
        el.removeAttribute('style');
        el.removeAttribute('data-height');
      });

    addNoteIcons(box);

    /* Номер комментария и его домен переписываем в атрибуты ДО снятия id.
       Сами кнопки здесь вешать нельзя: pynFill копирует ленту через
       importNode, а копия узлов обработчиков не наследует — в первой
       сборке кнопки строились и выглядели правильно, но на нажатия не
       отвечали вовсе. Атрибуты копирование переживают. */
    pynMarkIds(box);

    /* Совпадение id с настоящими комментариями страницы сломало бы и
       якоря, и поиск по id в скрипте лепры: у уведомлений id родительских
       комментариев те же, что у комментариев в треде. Набор значков это
       не затрагивает — он лежит отдельным узлом и чистке не подлежит. */
    sliceOf(box.querySelectorAll('[id]'))
      .forEach(function (el) { el.removeAttribute('id'); });
  }

  /* --- голосование прямо из окна пыни --- */

  /* Адреса подсмотрены в живом запросе лепры (report.network), а не
     угаданы:
       POST <домен>/ajax/vote/comment/
       doc=<id комментария>&vote=1|-1&csrf_token=<токен>
     Домен здесь не наш: уведомление может прийти из подлепры, и лепра
     в таком случае шлёт запрос НА ЕЁ домен. Берём его из ссылки на
     комментарий в самом уведомлении — она уже абсолютная и ведёт куда
     надо.
     Межсайтовый запрос при этом получается «простым» (form-urlencoded,
     без своих заголовков), то есть уходит без предварительной проверки
     и сервером обрабатывается. А вот ПРОЧИТАТЬ ответ браузер даст
     только если лепра пришлёт разрешающие заголовки, а этого никто не
     обещал. Поэтому: свой домен — читаем ответ и показываем результат
     честно; чужой — отправляем и считаем удачей, пока не доказано
     обратное. Что именно вышло, пишем в отчёт (pynVoteLog): гадать об
     этом второй раз не придётся. */
  var pynVoteLog = [];

  function pynVoteOrigin(item) {
    var a = item.querySelector('a[href*="/comments/"]');
    var href = a && a.getAttribute('href');
    if (!href) return location.origin;
    try { return new URL(href, location.href).origin; }
    catch (e) { return location.origin; }
  }

  function pynVoteSend(origin, id, vote, done) {
    /* Именно ajax-токен: тот, что для /api/, здесь отвергается. */
    var token = ajaxCsrf();
    if (!token) return done(false,
      'нет токена для /ajax/ — лепра ещё не отправляла своих запросов', null);
    var body = 'doc=' + encodeURIComponent(id) +
               '&vote=' + encodeURIComponent(vote) +
               '&csrf_token=' + encodeURIComponent(token);
    /* ВСЕ голоса уходят через окно на нужном домене — и чужие, и свои.
       Началось это с чужих: межсайтовый запрос отправляется только
       «простым», без X-Requested-With, лепра такой молча не исполняет,
       а ответ браузер не показывает — понять неудачу изнутри нечем.
       Через окно запрос становится обычным: со всеми заголовками и с
       читаемым ответом.
       Свои прямым запросом тоже работали. Но два пути к одному действию
       — это две механики, которые надо помнить и чинить порознь, а на
       отладке они уже успели разойтись в поведении. Один путь дешевле:
       на своём домене страница окна берётся из кэша браузера, и само
       окно создаётся один раз за жизнь страницы. */
    return voteViaFrame(origin, body, done);
  }

  function pynMarkIds(box) {
    sliceOf(box.querySelectorAll('.b-notification-item')).forEach(function (item, i) {
      var foot = item.querySelector('.b-notification-item_footer[id]');
      var id = foot && foot.getAttribute('id');
      if (!/^\d+$/.test(id || '')) return;
      item.setAttribute('data-lm-cid', id);
      item.setAttribute('data-lm-origin', pynVoteOrigin(item));
      item.setAttribute('data-lm-idx', String(i));
      /* Номер поста лепра держит в адресе ссылки на комментарий:
         .../comments/571398/#62861267. Из данных его тоже можно взять,
         но данные приходят позже разметки, а атрибут нужен уже сейчас —
         и переживает копирование importNode. */
      var a = item.querySelector('a[href*="/comments/"]');
      var m = a && /\/comments\/(\d+)/.exec(a.getAttribute('href') || '');
      if (m) item.setAttribute('data-lm-pid', m[1]);
    });
  }

  /* Рейтинг комментария. Берём из данных, пойманных в скрытом окне
     (lmPynJson). Сначала по номеру комментария, если лепра его в данных
     держит; иначе по порядку — лента в разметке и лента в данных идут
     из одного запроса и совпадают строка в строку.
     Не нашли — возвращаем null, и голосовалка встаёт без числа: соврать
     нулём было бы хуже, чем промолчать. */
  var pynMatchWay = {};      /* id → как нашлись данные, для отчёта */

  function pynComment(item) {
    var list;
    try { list = window.lmPynJson; } catch (e) { list = null; }
    if (!list || !list.length) return null;
    var cid = item.getAttribute('data-lm-cid');
    for (var i = 0; i < list.length; i++) {
      var c = list[i] && list[i].data && list[i].data.comment;
      if (c && String(c.id) === cid) { pynMatchWay[cid] = 'по номеру'; return c; }
    }
    pynMatchWay[cid] = 'ПО ПОРЯДКУ';
    /* Запасной путь — по порядку: лента в разметке и лента в данных
       приходят из одного запроса и совпадают строка в строку. Нужен на
       случай, если у какого-то вида уведомлений номер в данных лежит
       иначе. */
    var idx = parseInt(item.getAttribute('data-lm-idx'), 10);
    return (list[idx] && list[idx].data && list[idx].data.comment) || null;
  }

  /* Свой голос из данных. Поле user_vote приходит не всегда числом: у
     одного гражданина в отчёте стояло user_vote=-1, у другого —
     user_vote{}, то есть объект. Разбираем оба вида, а внутри объекта
     ищем первое же осмысленное число.
     Именно на этом всё и держалось: проверка «это число» отбрасывала
     объект целиком, поле считалось отсутствующим, и ни один прежний
     голос не подсвечивался. Своя память была лечением следствия. */
  function pynMyVote(data) {
    if (!data) return 0;
    var v = data.user_vote;
    if (typeof v === 'number') return v;
    if (typeof v === 'string' && v !== '' && isFinite(+v)) return +v;
    if (v && typeof v === 'object') {
      /* Сперва по знакомым именам, потом — первое число в объекте:
         имя поля внутри мы не видели, а угадывать вслепую уже
         обходилось дорого. */
      var names = ['value', 'vote', 'sign', 'rating', 'weight', 'my_vote'];
      for (var i = 0; i < names.length; i++)
        if (typeof v[names[i]] === 'number') return v[names[i]];
      for (var k in v)
        if (v.hasOwnProperty(k) && typeof v[k] === 'number') return v[k];
      /* Логический вид: {up: true} / {down: true}. */
      if (v.up === true || v.plus === true) return 1;
      if (v.down === true || v.minus === true) return -1;
    }
    return 0;
  }

  /* Свежие данные ленты — своим запросом, мимо кэша.
     Данные мы до сих пор брали те, что запросило скрытое окно. Запрос
     это обычный GET, и браузер вправе отдать его из кэша — а в отчёте
     user_vote приходил пустым ровно у тех комментариев, за которые
     голос отдан недавно, и заполненным у старых. Признак кэша прямой.
     Просим то же самое сами, с cache: 'no-store' и с меткой времени в
     адресе: одного из двух обычно хватает, но лепра отвечает и на GET
     с лишним параметром, а стоит это ничего.
     Запрос один на открытие окна, не на каждое уведомление. */
  var pynFreshFrom = 'окно';

  function pynFresh(cb) {
    var h = apiAuth();
    if (!h) return cb(false, 'нет ключей');
    var url = location.origin + '/api/my/notifications/?per_page=20&page=1&_=' +
              Date.now();
    fetch(url, { credentials: 'include', cache: 'no-store', headers: h })
      .then(function (r) { return r.json(); })
      .then(function (j) {
        if (!j || !j.notifications || !j.notifications.length)
          return cb(false, 'пустой ответ');
        try { window.lmPynJson = j.notifications; } catch (e) {}
        pynFreshFrom = 'свой запрос';
        cb(true, j.notifications.length + ' записей');
      })
      .catch(function (e) { cb(false, String(e && e.message || e)); });
  }

  /* --- ответ на комментарий прямо из окна пыни --- */

  /* Адрес и поля подсмотрены в живом запросе лепры (report.network):
       POST <домен>/ajax/comment/yarrr/
       wtf=&parent=<комментарий>&post=<пост>&body=<текст>&csrf_token=…
     Пустое wtf в её теле есть — не выясняли, зачем оно ей, но шлём как
     есть: воспроизводить чужой запрос надо целиком, а не в той части,
     которая кажется понятной.
     Отправка через то же окно, что и голос: одна дорога на все
     действия, и на подлепру ответ уходит так же, как на главную. */
  var pynReplyLog = [];

  function pynReplyRead(txt) {
    var raw = String(txt || '').slice(0, 200);
    var j = null;
    try { j = JSON.parse(txt); } catch (e) {}
    if (j && (j.status === 'ERR' || j.error || j.errors))
      return { ok: false, why: 'отказ: ' + JSON.stringify(j).slice(0, 140) };
    /* Ответ на удачную отправку у лепры — разметка нового комментария,
       то есть не JSON вовсе. Пустой ответ считаем неудачей: сказать про
       него нечего, а делать вид, что всё хорошо, — худшее из решений. */
    if (!j && raw) return { ok: true, why: 'разметка, ' + raw.length + '+ знаков' };
    if (j) return { ok: true, why: 'JSON без отказа' };
    return { ok: false, why: 'пустой ответ' };
  }

  function pynReplySend(item, text, done) {
    var cid = item.getAttribute('data-lm-cid');
    var pid = item.getAttribute('data-lm-pid');
    var origin = item.getAttribute('data-lm-origin') || location.origin;
    if (!cid || !pid) return done(false, 'нет номера комментария или поста');
    var token = ajaxCsrf();
    if (!token) return done(false, 'нет токена для /ajax/');

    var body = 'wtf=' +
               '&parent=' + encodeURIComponent(cid) +
               '&post=' + encodeURIComponent(pid) +
               '&body=' + encodeURIComponent(text) +
               '&csrf_token=' + encodeURIComponent(token);

    sendViaFrame(origin, '/ajax/comment/yarrr/', body,
      function (status, txt, oops) {
        if (oops) return done(false, oops);
        var res = pynReplyRead(txt);
        pynReplyLog.push(cid + ' → ' + (res.ok ? 'отправлен' : 'не вышел') +
                         ' (HTTP ' + status + ', ' + res.why + ')');
        if (pynReplyLog.length > 8) pynReplyLog.shift();
        done(res.ok, res.why);
      });
  }

  /* Форма ответа. Раскрывается под уведомлением по нажатию на «ответить»
     и сворачивается обратно. Строится по требованию, а не сразу для всех
     двадцати: два десятка textarea в окне — это два десятка полей ввода,
     которые Safari будет держать живыми без всякой нужды. */
  function pynReplyForm(item, place) {
    var open = item.querySelector('.lm-pyn_form');
    if (open) { open.parentNode.removeChild(open); return; }

    var form = document.createElement('div');
    form.className = 'lm-pyn_form';

    var area = document.createElement('textarea');
    area.className = 'lm-pyn_area';
    area.setAttribute('rows', '3');
    area.setAttribute('placeholder', 'ответ…');

    var row = document.createElement('div');
    row.className = 'lm-pyn_form_row';

    var say = document.createElement('span');
    say.className = 'lm-pyn_form_say';

    var send = document.createElement('button');
    send.type = 'button';
    send.className = 'lm-pyn_form_btn';
    send.textContent = 'Отправить';

    var drop = document.createElement('button');
    drop.type = 'button';
    drop.className = 'lm-pyn_form_btn lm-pyn_form_btn__off';
    drop.textContent = 'Отмена';
    drop.addEventListener('click', function (e) {
      e.preventDefault(); e.stopPropagation();
      form.parentNode.removeChild(form);
    });

    send.addEventListener('click', function (e) {
      e.preventDefault(); e.stopPropagation();
      var text = (area.value || '').trim();
      if (!text) { say.textContent = 'пусто'; return; }
      if (form.dataset.lmBusy) return;
      form.dataset.lmBusy = '1';
      say.textContent = 'отправляю…';
      send.disabled = true;

      guard('pynReplySend', pynReplySend)(item, text, function (ok, why) {
        delete form.dataset.lmBusy;
        send.disabled = false;
        if (!ok) { say.textContent = 'не вышло: ' + why; return; }
        say.textContent = 'отправлено';
        area.value = '';
        /* Форму убираем не сразу: человек должен увидеть, что ответ
           ушёл. Полторы секунды — ровно чтобы прочесть слово. */
        setTimeout(function () {
          if (form.parentNode) form.parentNode.removeChild(form);
        }, 1500);
      });
    });

    row.appendChild(say);
    row.appendChild(drop);
    row.appendChild(send);
    form.appendChild(area);
    form.appendChild(row);
    place.parentNode.insertBefore(form, place.nextSibling);
    area.focus();
  }

  function pynReplies(box) {
    if (!CFG.pynReply) return;
    sliceOf(box.querySelectorAll('.b-notification-item[data-lm-cid][data-lm-pid]'))
      .forEach(function (item) {
        if (item.querySelector('.lm-pyn_answer')) return;
        var foot = item.querySelector('.b-notification-item_footer');
        if (!foot) return;
        var a = document.createElement('button');
        a.type = 'button';
        a.className = 'lm-pyn_answer';
        a.textContent = 'ответить';
        a.addEventListener('click', function (e) {
          e.preventDefault(); e.stopPropagation();
          guard('pynReplyForm', pynReplyForm)(item, foot);
        });
        foot.appendChild(a);
      });
  }

  var pynVoteMounted = 0, pynRateFound = 0, pynVoteMine = 0;
  /* Свои голоса — с запоминанием НА ДОЛГО, не только до перезагрузки.
     На странице поста лепра рисует нажатую кнопку потому, что состояние
     голоса приходит в самой разметке. У уведомлений источник другой —
     поле user_vote в данных API, — и оно про наши свежие голоса молчит.
     Отчего именно, доподлинно неизвестно: у комментария подлепры оно
     менялось вслед за голосом, у комментариев главной — нет. Гадать
     дальше смысла нет: своё мы знаем точно, лучше любого источника.
     Храним по гражданам: под другим сюда заглядывать нечего.
     Список подрезаем — иначе он растёт с каждым голосом бесконечно, а
     нужен он только для тех уведомлений, что ещё показываются в ленте;
     двухсот с запасом хватает на два десятка видимых. */
  var VOTES_KEY = 'lm-votes';
  var VOTES_MAX = 200;
  var pynVoteCast = {};     /* id комментария → отданный нами голос */
  var pynRateCast = {};     /* id комментария → рейтинг после него */
  var pynVoteOrder = [];    /* порядок, чтобы подрезать самые старые */

  function votesLoad() {
    if (!CFG.voteMemory) return;
    var raw = null;
    try { raw = localStorage.getItem(VOTES_KEY); } catch (e) { return; }
    if (!raw) return;
    var j = null;
    try { j = JSON.parse(raw); } catch (e) {}
    if (!j || j.uid !== currentUid() || !j.list) {
      try { localStorage.removeItem(VOTES_KEY); } catch (e) {}
      return;
    }
    j.list.forEach(function (r) {
      if (!r || !r.id) return;
      pynVoteCast[r.id] = r.v;
      if (typeof r.r === 'number') pynRateCast[r.id] = r.r;
      pynVoteOrder.push(r.id);
    });
  }

  var votesSaved = 0, votesFail = '';

  function votesSave(id, sign, rating) {
    if (!CFG.voteMemory) return;
    votesSaved++;
    if (!pynVoteCast.hasOwnProperty(id)) pynVoteOrder.push(id);
    pynVoteCast[id] = sign;
    if (typeof rating === 'number') pynRateCast[id] = rating;
    while (pynVoteOrder.length > VOTES_MAX) {
      var old = pynVoteOrder.shift();
      delete pynVoteCast[old];
      delete pynRateCast[old];
    }
    var list = pynVoteOrder.map(function (k) {
      var r = { id: k, v: pynVoteCast[k] };
      if (pynRateCast.hasOwnProperty(k)) r.r = pynRateCast[k];
      return r;
    });
    try {
      localStorage.setItem(VOTES_KEY,
        JSON.stringify({ uid: currentUid(), list: list }));
    } catch (e) {
      /* Писать некуда — проживёт до перезагрузки. Причину показываем в
         отчёте: молчаливая потеря памяти уже стоила нам одного круга. */
      votesFail = String(e && e.message || e);
    }
  }

  /* --- голос через окно на чужом домене --- */

  var voteFrames = {};        /* домен → окно */
  var voteReady = {};         /* домен → готово ли */
  var voteWaits = {};         /* номер запроса → отзвон */
  var voteQueue = {};         /* домен → отложенные до готовности */
  var voteSeq = 0;

  function voteListen() {
    if (voteListen.on) return;
    voteListen.on = true;
    window.addEventListener('message', guard('voteMsg', function (e) {
      var d = e.data;
      if (!d || !d.lm) return;
      if (d.lm === 'vote-ready') {
        voteReady[d.origin] = true;
        (voteQueue[d.origin] || []).forEach(function (fn) { fn(); });
        voteQueue[d.origin] = [];
        return;
      }
      if (d.lm !== 'send-done') return;
      var cb = voteWaits[d.id];
      if (!cb) return;
      delete voteWaits[d.id];
      cb(d.status, d.text);
    }));
  }

  function voteFrame(origin) {
    if (voteFrames[origin]) return voteFrames[origin];
    var f = document.createElement('iframe');
    f.name = 'lm-vote-frame';
    f.setAttribute('aria-hidden', 'true');
    f.style.cssText = 'position:absolute;left:-9999px;top:0;width:1px;height:1px;border:0;';
    /* Страницу берём заведомо лёгкую. Подойдёт любая, лишь бы отдалась
       разметкой: наш скрипт запускается на ней сам, а больше от неё
       ничего не нужно. */
    f.src = origin + '/my/';
    (document.body || document.documentElement).appendChild(f);
    voteFrames[origin] = f;
    return f;
  }

  /* Отправить что угодно через окно на нужном домене. Одна дорога для
     всех действий: голос, ответ и что появится дальше. Отдаёт сырой
     ответ — разбирать его вызывающему виднее. */
  function sendViaFrame(origin, path, body, done) {
    voteListen();
    voteFrame(origin);
    var id = ++voteSeq;

    var timer = setTimeout(function () {
      if (!voteWaits[id]) return;
      delete voteWaits[id];
      done(0, '', 'окно на ' + origin + ' не ответило');
    }, 15000);

    voteWaits[id] = function (status, txt) {
      clearTimeout(timer);
      done(status, txt, '');
    };

    var go = function () {
      try {
        voteFrames[origin].contentWindow.postMessage(
          { lm: 'send', id: id, path: path, body: body }, origin);
      } catch (e) {
        clearTimeout(timer);
        delete voteWaits[id];
        done(0, '', 'окно не приняло сообщение: ' + (e && e.message));
      }
    };
    if (voteReady[origin]) go();
    else (voteQueue[origin] = voteQueue[origin] || []).push(go);
  }

  function voteViaFrame(origin, body, done) {
    sendViaFrame(origin, '/ajax/vote/comment/', body,
      function (status, txt, oops) {
        if (oops) return done(false, oops, null);
        var res = pynVoteRead(txt);
        done(res.ok, 'через окно ' + origin + ', HTTP ' + status + ', ' + res.why,
             res.rating);
      });
  }

  /* Разбор ответа на голос. Формы ответа мы не видели, поэтому разбор
     терпимый: ищем признак ошибки, ищем число, похожее на рейтинг, и
     честно говорим, чего не поняли. Всё, что не разобрали, попадает в
     отчёт целиком — по нему форма и уточнится. */
  function pynVoteRead(txt) {
    var raw = String(txt || '').slice(0, 300);
    var j = null;
    try { j = JSON.parse(txt); } catch (e) {}
    if (!j) return { ok: !!raw && raw.indexOf('error') < 0, rating: null,
                     why: raw ? 'ответ не JSON: ' + raw.slice(0, 120) : 'пустой ответ' };

    if (j.error || j.errors || j.status === 'error')
      return { ok: false, rating: null,
               why: 'отказ: ' + JSON.stringify(j).slice(0, 120) };

    /* Рейтинг лепра может назвать по-разному — перебираем известные
       имена, а если не нашли, отдаём ответ целиком в отчёт. */
    var names = ['rating', 'vote_result', 'result', 'value', 'sum'];
    for (var i = 0; i < names.length; i++) {
      var v = j[names[i]];
      if (typeof v === 'number') return { ok: true, rating: v, why: 'рейтинг ' + v };
      if (v && typeof v.rating === 'number')
        return { ok: true, rating: v.rating, why: 'рейтинг ' + v.rating };
    }
    return { ok: true, rating: null,
             why: 'рейтинг не найден в ответе: ' + JSON.stringify(j).slice(0, 140) };
  }

  function pynVotes(box) {
    if (!CFG.pynVote) return;
    pynVoteMounted = 0; pynRateFound = 0; pynVoteMine = 0;
    sliceOf(box.querySelectorAll('.b-notification-item[data-lm-cid]')).forEach(function (item) {
      var id = item.getAttribute('data-lm-cid');
      if (item.querySelector('.lm-pyn_vote')) return;

      var origin = item.getAttribute('data-lm-origin') || location.origin;
      var data = pynComment(item);
      var rating = data && typeof data.rating === 'number' ? data.rating : null;
      /* Рейтинг после своего голоса помним по той же причине, что и сам
         голос: в кэшированных данных он ещё прежний. */
      if (CFG.voteMemory && pynRateCast.hasOwnProperty(id)) rating = pynRateCast[id];
      if (rating !== null) pynRateFound++;
      /* Свой прежний голос лепра держит в данных полем user_vote —
         нашлось перебором полей в отчёте, а не догадкой. Показываем его
         нажатым: иначе непонятно, голосовал ты уже или нет, и легко
         ткнуть второй раз в то же самое. */
      var mine = pynMyVote(data);
      /* Свои голоса, отданные из этого же окна, помним отдельно и
         ставим поверх данных. Причина: лента уведомлений приходит
         обычным GET к API, и браузер вправе отдать её из кэша — тогда
         в данных лежит снимок ДО голосования, и только что нажатая
         кнопка при следующем открытии окна оказывается ненажатой.
         Так и было: подсвечивался единственный голос, отданный в
         прошлую загрузку страницы, а все сегодняшние — нет. */
      if (CFG.voteMemory && pynVoteCast.hasOwnProperty(id)) mine = pynVoteCast[id];

      var vote = document.createElement('div');
      vote.className = 'lm-pyn_vote';

      var mk = function (sign, text) {
        var b = document.createElement('button');
        b.type = 'button';
        b.className = 'lm-pyn_vote_btn';
        b.textContent = text;
        b.addEventListener('click', function (e) {
          e.preventDefault();
          e.stopPropagation();
          /* Переголосовать лепра позволяет, и мы тоже: замок держится
             только на время запроса. Первая сборка запирала пару
             навсегда после первого нажатия — плюс проходил, а сменить
             его на минус было уже нечем.
             Повторное нажатие ТОЙ ЖЕ кнопки не делаем: на странице оно у
             лепры отменяет голос, но каким телом она это шлёт, мы не
             видели, а угадывать в отправке — последнее дело. */
          if (vote.dataset.lmBusy) return;
          if (parseInt(vote.dataset.lmVote || '0', 10) === sign) return;
          vote.dataset.lmBusy = '1';
          vote.classList.add('lm-wait');
          pynVoteSend(origin, id, sign, function (ok, why, fresh) {
            delete vote.dataset.lmBusy;
            vote.classList.remove('lm-wait', 'lm-ok', 'lm-bad');
            vote.classList.add(ok ? 'lm-ok' : 'lm-bad');
            if (ok) {
              vote.dataset.lmVote = String(sign);
              sliceOf(vote.querySelectorAll('.lm-pyn_vote_btn'))
                .forEach(function (o) { o.classList.remove('lm-on'); });
              b.classList.add('lm-on');
              /* Новое число — ТОЛЬКО из ответа сервера. Прибавлять
                 единицу нельзя: вес голоса у каждого свой и растёт с
                 кармой — у новичка плюс один, у старожила может быть
                 три. Не пришло числа — ставим точку: честное «не знаю»
                 лучше правдоподобного вранья. */
              votesSave(id, sign, typeof fresh === 'number' ? fresh : null);
              if (typeof fresh === 'number') num.textContent = String(fresh);
              else num.textContent = '\u00b7';
            }
            pynVoteLog.push(id + ' ' + (sign > 0 ? '+' : '−') + ' → ' +
                            (ok ? 'ушёл' : 'не вышло') + ' (' + why + ')');
            if (pynVoteLog.length > 12) pynVoteLog.shift();

            /* Сразу после удачного голоса спрашиваем ленту заново и
               смотрим, что лепра теперь говорит про ЭТОТ комментарий.
               Это ответ на единственный оставшийся вопрос: заполняет ли
               она user_vote вообще или там всегда пусто. Раньше это
               выяснялось перепиской и снимками с устройства; теперь
               отвечается само, одним нажатием.
               Полторы секунды — чтобы сервер успел записать голос:
               мгновенный повторный запрос честно вернул бы прежнее
               состояние, и мы бы обвинили не то. */
            if (ok) setTimeout(guard('pynVoteCheck', function () {
              pynFresh(function (fine) {
                var head = id + ' — проверка после голоса: ';
                if (!fine) { pynVoteLog.push(head + 'лента не перезапросилась'); return; }
                var again = null, list = null;
                try { list = window.lmPynJson; } catch (e) {}
                (list || []).forEach(function (n) {
                  var c = n && n.data && n.data.comment;
                  if (c && String(c.id) === id) again = c;
                });
                pynVoteLog.push(head + (again
                  ? 'user_vote=' + JSON.stringify(again.user_vote) +
                    ' → ' + pynMyVote(again) + ', рейтинг ' + again.rating
                  : 'этого комментария в ленте больше нет'));
                if (pynVoteLog.length > 20) pynVoteLog.shift();
              });
            }), 1500);
          });
        });
        return b;
      };

      /* Число между кнопками — как у комментария на странице. После
         своего голоса поправляем его сами: сервер новое значение в
         ответе не возвращает, а перезагружать всю ленту ради одной
         цифры незачем. */
      var num = document.createElement('div');
      num.className = 'lm-pyn_vote_num';
      num.textContent = rating === null ? '' : String(rating);

      var plus = mk(1, '+'), minus = mk(-1, '\u2212');
      vote.appendChild(plus);
      vote.appendChild(num);
      vote.appendChild(minus);
      if (mine) pynVoteMine++;
      if (mine > 0) { plus.classList.add('lm-on'); vote.dataset.lmVote = '1'; }
      else if (mine < 0) { minus.classList.add('lm-on'); vote.dataset.lmVote = '-1'; }
      pynVoteMounted++;

      /* Кладём в ШАПКУ уведомления, следом за её значком, и повторяем
         приём самой лепры: значок у неё плавает влево с полем -36, то
         есть стоит в желобке, оставленном отступом самого уведомления.
         Голосовалка встаёт туда же, под значок.
         Первая сборка вместо этого ставила голосовалку первым ребёнком
         уведомления и переводила его во флекс — и разложила по
         столбцам шапку, текст и подпись, то есть всю ленту. Урок общий:
         менять display у чужого узла нельзя, у лепры на нём держится
         вся внутренняя раскладка; встраиваться надо её же способом. */
      var head = item.querySelector('.b-notification-item_header');
      if (head) head.appendChild(vote);
      else item.insertBefore(vote, item.firstChild);
      item.classList.add('lm-pyn_voted');
    });
  }

  /* force — не брать сохранённое, идти на сервер обязательно.
     Из-за отсутствия этого признака слежение за новыми пынями молчало:
     оно исправно замечало рост счётчика и звало перезагрузку, а та
     возвращала ту же ленту из памяти — свежесть-то не истекла. Внешне
     выглядело как «пуши приходят, а в окно ничего не подгружается».
     Второе, что здесь было не так: при занятом окне вызов молча терялся
     вместе с отзвоном. Слежение ставило замок перед вызовом и снимало
     его в отзвоне — и, не дождавшись, оставалось запертым навсегда.
     Теперь занятость отвечает честно, и замок снимается. */
  function pynLoad(cb, force) {
    if (!force && pynData && Date.now() - pynAt < CFG.pynFresh * 1000)
      return cb(pynData);
    if (pynBusy) return cb(null, 'окно уже загружается');
    pynBusy = true;

    var timer = null;
    var done = function (data, why) {
      pynBusy = false;
      if (timer) clearInterval(timer);
      if (pynFrame && pynFrame.parentNode) pynFrame.remove();
      pynFrame = null;
      cb(data, why);
    };

    var fr = document.createElement('iframe');
    pynFrames++;
    pynFrame = fr;
    fr.setAttribute('name', PYN_FRAME);
    fr.setAttribute('aria-hidden', 'true');
    fr.setAttribute('src', location.protocol + '//' + location.host + PYN_PAGE);
    /* Не display: none и не размер в пиксель: скрипт лепры при сборке
       ленты меряет раскладку, и в схлопнутом окне мерить ему нечего.
       Поэтому окно нормального размера, просто унесено за край. */
    fr.style.cssText = 'position:fixed;left:-10000px;top:0;width:420px;' +
                       'height:900px;border:0;opacity:0;pointer-events:none;';
    document.body.appendChild(fr);

    var t0 = Date.now();

    var look = function () {
      var d = null;
      try { d = fr.contentDocument; } catch (e) {}
      var main = d && d.querySelector('#js-notification-feed-main');
      if (main && main.querySelector('.b-notification-item')) {
        /* Забираем немедленно и к себе: после удаления окна его документ
           пропадает, и узлы, оставленные там, станут непригодны. */
        var mine = document.importNode(main, true);
        pynClean(mine);
        /* Набор значков лежит рядом с лентой, а не внутри неё, и на
           обычной странице есть свой блок с тем же классом — но в нём
           только три значка шапки (icon_inbox и соседи). Поэтому берём
           набор строго из ленты и проверяем не класс, а нужный символ:
           раньше проверка по классу находила шапочный набор, импорт
           пропускался, и в окне не рисовались ни значки уведомлений,
           ни шеврон разворота. */
        var sp = d.querySelector('#js-notification-feed .b-notification-svg-font');
        pynData = { main: mine,
                    sprite: sp ? document.importNode(sp, true) : null };
        pynAt = Date.now();
        return done(pynData, null);
      }
      if (Date.now() - t0 > CFG.pynWait * 1000)
        done(null, d ? 'лента не собралась за ' + CFG.pynWait + ' с'
                     : 'страница уведомлений не открылась');
    };

    timer = setInterval(guard('pynLook', look), 200);
  }

  function pynClose() {
    pynLiveStop();
    var w = document.getElementById('lm-pyn');
    if (w) w.remove();
  }

  /* --- реальное время в открытом окне --- */

  /* Пока окно открыто, спрашиваем счётчик чаще обычного и, если он
     вырос, перезагружаем ленту уведомлений.
     Почему перезагрузка целиком, а не подстановка одной новой строки.
     Лента собирается скрытым окном лепры — отдельной строки оттуда не
     достать, а собрать её самим значило бы повторить чужую разметку со
     всеми её значками и шевронами, и разойтись с ней при первом же
     обновлении лепры. Перезагрузка дороже, но случается она ровно
     столько раз, сколько пришло новых пыней, а не каждые пятнадцать
     секунд.
     Положение прокрутки при этом сохраняется: новые строки лепра
     кладёт сверху, и без восстановления список прыгал бы к началу
     каждый раз, когда кто-то отвечает, — прямо из-под читающего. */
  var pynLiveTimer = null;
  var pynLiveSeen = -1;
  var pynLiveBusy = false;
  var pynLiveTicks = 0;     /* сколько раз спрашивали — для отчёта */
  var pynLiveLog = '';      /* чем кончилась последняя подгрузка */

  function pynLiveStop() {
    if (pynLiveTimer) clearInterval(pynLiveTimer);
    pynLiveTimer = null;
    pynLiveSeen = -1;
    pynLiveBusy = false;
  }

  function pynLiveStart(body) {
    pynLiveStop();
    if (!CFG.pynWatch || !apiAuth()) return;
    pynCount(function (res) { if (res) pynLiveSeen = res.total; });

    pynLiveTimer = setInterval(guard('pynLive', function () {
      /* Окна нет — значит закрыли не через pynClose (перешли по ссылке,
         сменилась страница). Убираемся сами. */
      if (!document.getElementById('lm-pyn')) return pynLiveStop();
      if (document.visibilityState === 'hidden') return;
      if (pynLiveBusy) return;
      pynLiveTicks++;

      pynCount(function (res) {
        if (!res || !document.getElementById('lm-pyn')) return;

        /* Правило срабатывания.
           Сравнение с запомненной отметкой оказалось хрупким: пока окно
           открыто, показанное отмечается прочитанным (pynAutoRead), и
           счётчик всё время ходит туда-сюда между нулём и единицей. Любое
           расхождение отметки с этим качанием — например, если отметка
           снялась ДО того, как отметилось прочитанное, — и первая новая
           пынь молча пропускалась. Отладить это по одной строке отчёта
           нельзя: качание разное от захода к заходу.
           Поэтому бухгалтерии больше нет. При включённом pynAutoRead всё
           показанное в окне уже отмечено прочитанным, значит ЛЮБОЕ
           непрочитанное — это то, чего в окне нет. Перезагружаем и не
           сравниваем ни с чем. После перезагрузки автоотметка снова
           обнулит счётчик, так что и зацикливания не будет.
           Отметку продолжаем вести только там, где автоотметка выключена:
           там счётчик сам не падает, и без сравнения окно перезагружалось
           бы каждые пятнадцать секунд без конца. */
        var fire;
        if (CFG.pynAutoRead) {
          fire = res.total > 0;
        } else {
          if (pynLiveSeen < 0) { pynLiveSeen = res.total; return; }
          fire = res.total > pynLiveSeen;
          if (res.total < pynLiveSeen) pynLiveSeen = res.total;
        }
        pynLiveSeen = res.total;
        if (!fire) return;
        pynLiveBusy = true;

        var keep = body.scrollTop;
        /* Обязательно свежую: сохранённая живёт минуту (CFG.pynFresh), а
           новая пынь приходит когда придёт. */
        pynLoad(function (data, why) {
          pynLiveBusy = false;
          pynLiveLog = data ? 'подгружено' : ('не вышло: ' + (why || '?'));
          if (!document.getElementById('lm-pyn')) return;
          if (!data) return;                   /* не вышло — оставляем как было */
          var before = body.scrollHeight;
          if (!pynFill(body, data)) return;
          /* Восстанавливаем не прежнее число, а прежнее РАССТОЯНИЕ ДО
             ПРОЧИТАННОГО: сверху добавились строки, и старое значение
             прокрутки показало бы уже не то место. Насколько лента
             выросла — на столько и опускаемся. */
          body.scrollTop = keep + Math.max(0, body.scrollHeight - before);
        }, true);
      });
    }), CFG.pynLiveEvery * 1000);
  }

  function pynFill(body, data) {
    if (!data) return false;

    /* Значки уведомлений нарисованы через <use xlink:href="#notification_…">,
       а сами svg лежат в отдельном наборе — на прочих страницах его нет,
       и без него в ленте были бы пустые места. Ищем по конкретному
       символу: блок с тем же классом на странице есть всегда, но с
       другим содержимым. */
    if (data.sprite && !document.getElementById('notification_answers'))
      document.body.appendChild(document.importNode(data.sprite, true));

    body.textContent = '';
    var main = document.importNode(data.main, true);
    if (!main.querySelector('.b-notification-item')) {
      var empty = document.createElement('div');
      empty.className = 'lm-pyn_note';
      empty.textContent = 'Пока ничего';
      body.appendChild(empty);
      return true;
    }
    body.appendChild(main);
    /* Кнопки — только теперь, на живой копии: importNode обработчиков не
       переносит (см. pynMarkIds). */
    guard('pynVotes', pynVotes)(main);
    guard('pynReplies', pynReplies)(main);
    guard('autoRead', autoRead)(main);
    return true;
  }

  /* Показанное считаем прочитанным. Класс снимаем сразу, не дожидаясь
     ответа сервера: иначе подсветка непрочитанного гасла бы через
     секунду после открытия и мигала бы на глазах. */
  /* Пока подсветку снимали, повторов быть не могло: второй проход просто
     не находил непрочитанных. Теперь класс остаётся на месте — а полный
     проход отрабатывает пять раз за загрузку, и на странице уведомлений
     одно и то же уведомление отмечалось трижды подряд. Держим список
     уже отправленных. */
  var markedIds = {};

  function autoRead(root) {
    if (!CFG.pynAutoRead) return;
    var ids = unreadIds(root).filter(function (id) { return !markedIds[id]; });
    if (!ids.length) return;
    ids.forEach(function (id) { markedIds[id] = true; });
    if (!csrfToken()) return note('нечем отметить прочитанным: нет токена');
    /* Подсветку непрочитанного не снимаем: ради неё окно и открывают —
       видно, что именно пришло нового. Гасить её незачем и не нужно:
       на сервере уведомления теперь прочитаны, и в следующий раз лента
       придёт уже без этого класса. */
    markRead(ids, function (okCount) {
      if (okCount < ids.length) {
        note('отмечено прочитанным ' + okCount + ' из ' + ids.length);
        /* Не вышло — забываем, чтобы следующий проход попробовал снова. */
        ids.forEach(function (id) { delete markedIds[id]; });
      }
      headerMuted = true;
      setHeaderCount(0);
      pynCount(function (res) { if (res) setSeen(res.total); });
    });
  }

  /* Обе панели одинаковые, поэтому собираются одной функцией: разойдись
     они хоть надписью, хоть порядком кнопок — это читалось бы как две
     разные панели, а не одна и та же сверху и снизу. */
  function pynBar(kind) {
    var bar = document.createElement('div');
    bar.className = 'lm-pyn_bar lm-pyn_bar__' + kind;

    var close = document.createElement('button');
    close.type = 'button';
    close.className = 'lm-pyn_close';
    close.textContent = 'Закрыть';
    close.addEventListener('click', pynClose);
    bar.appendChild(close);

    /* Кнопки «Всё прочитано» здесь нет намеренно: показанное окно и так
       отмечает свои уведомления прочитанными, поимённо. Кнопка была бы
       либо тем же самым второй раз, либо отметкой того, чего человек не
       видел, — а это уже не его решение, а наше. */

    var all = document.createElement('a');
    all.setAttribute('href', pynHref());
    all.textContent = 'Все уведомления';
    bar.appendChild(all);

    return bar;
  }

  function pynOpen() {
    if (document.getElementById('lm-pyn')) { pynClose(); return; }
    if (!document.body) return;

    /* Открыл окно — значит увидел всё, что в нём есть. Без этого плашка
       сообщила бы о тех же пынях ещё раз при следующем опросе. */
    /* Лепра, показав свою ленту, опустошает счётчик, хотя прочитанными
       уведомления не отмечает: перезагрузка возвращает цифру. Делаем то
       же — иначе после нашего окна цифра висела бы, а после лепровской
       страницы нет, и было бы непонятно, кто из них врёт. Отметить
       по-настоящему можно кнопкой в подвале окна (см. ниже). */
    headerMuted = true;
    guard('pynSeenNow', function () {
      setHeaderCount(0);
      pynCount(function (res) { if (res) setSeen(res.total); });
    })();

    var wrap = document.createElement('div');
    wrap.id = 'lm-pyn';

    var shade = document.createElement('div');
    shade.className = 'lm-pyn_shade';
    shade.addEventListener('click', pynClose);
    /* Страницу под окном не глушим через overflow: hidden на body — на
       iOS это теряет позицию прокрутки и выбрасывает наверх (см. историю
       просмотрщика картинок). Хватает того, что палец на подложке не
       тащит страницу. */
    shade.addEventListener('touchmove', function (e) { e.preventDefault(); },
                           { passive: false });

    var box = document.createElement('div');
    box.className = 'lm-pyn_box';

    var body = document.createElement('div');
    body.className = 'lm-pyn_body';
    /* Обработчик — на самой ленте, а не на каждом шевроне: список
       наполняется позже, а при повторном открытии — заново. */
    body.addEventListener('click', guard('pynRoll', function (e) {
      var t = e.target;
      if (!t || !t.closest) return;
      var roll = t.closest('.lm-pyn_roll');
      if (!roll) return;
      e.preventDefault();
      var item = roll.closest('.b-notification-item');
      var pc = item && item.querySelector('.b-notification-item_parent_comment');
      if (!pc) return;
      roll.classList.toggle('lm-open', pc.classList.toggle('lm-open'));
    }));
    var note = document.createElement('div');
    note.className = 'lm-pyn_note';
    note.textContent = 'Загружаю…';
    body.appendChild(note);

    /* Панель управления и сверху, и снизу. Причина не в красоте: при
       несжатом виде Safari нижняя панель окна нередко оказывается за
       краем и не сразу доступна, а ужимать окно по высоте — значит
       оставить на ленту совсем мало места. Верхняя всегда под рукой. */
    box.appendChild(pynBar('head'));
    box.appendChild(body);
    box.appendChild(pynBar('foot'));
    wrap.appendChild(shade);
    wrap.appendChild(box);
    document.body.appendChild(wrap);

    pynLoad(function (data, why) {
      if (!document.getElementById('lm-pyn')) return;   /* успели закрыть */
      if (pynFill(body, data)) return;
      /* Раньше отсюда шёл переход на страницу уведомлений: окно мигало
         и пропадало, а почему — оставалось неизвестным. Теперь причина
         остаётся на виду, а уйти на страницу можно ссылкой снизу. */
      body.textContent = '';
      var bad = document.createElement('div');
      bad.className = 'lm-pyn_note';
      bad.textContent = 'Список не загрузился: ' + (why || 'неизвестно');
      body.appendChild(bad);
    });

    /* Слежение запускаем сразу, не дожидаясь первой загрузки: счётчик
       спрашивается отдельно от ленты, и его отметку надо снять именно
       на момент открытия. */
    guard('pynLiveStart', pynLiveStart)(body);

    /* И тут же просим свежие данные мимо кэша. Придут — перерисуем
       голосовалки: лента к тому времени уже стоит, а голосовалки
       строятся по данным. */
    var redraw = function () {
      if (!document.getElementById('lm-pyn')) return;
      sliceOf(body.querySelectorAll('.lm-pyn_vote'))
        .forEach(function (v) { v.parentNode.removeChild(v); });
      guard('pynVotes', pynVotes)(body);
    };

    guard('pynFresh', pynFresh)(function (ok) { if (ok) redraw(); });
  }

  if (CFG.pynPopup) {
    document.documentElement.classList.add('lm-pyn_on');
    document.addEventListener('click', function (e) {
      var t = e.target;
      if (!t || !t.closest) return;
      var a = t.closest('a.js-header_button_events');
      if (!a) return;
      /* На самой странице уведомлений окно ни к чему: лента и так перед
         глазами, а ссылка ведёт на неё же. */
      if (onEventsPage()) return;
      e.preventDefault();
      e.stopPropagation();
      if (e.stopImmediatePropagation) e.stopImmediatePropagation();
      guard('pynOpen', pynOpen)();
    }, true);
  }

  /* Страница уведомлений: лента лежит последним потомком body и прибита
     абсолютно, top ей считает скрипт лепры под свою шапку. Позиционирование
     снято в CSS, но статичный блок на месте последнего потомка body встал
     бы ниже подвала — поэтому переносим его в главную колонку. */
  function fixEventsPage() {
    var feed = document.getElementById('js-notification-feed');
    if (!feed) return;
    var main = document.querySelector('.l-i-content_main');
    if (main && feed.parentNode !== main) main.appendChild(feed);
    feed.style.removeProperty('top');
    /* Ленту собирает скрипт лепры уже после загрузки, поэтому значки
       довешиваем и здесь, и в лёгком проходе: к первому полному проходу
       пунктов ещё нет. Повторный вызов безвреден — addNoteIcon выходит,
       если значок уже стоит. */
    addNoteIcons(feed);
    guard('autoRead', autoRead)(feed);
  }


  /* ---- Страница нового поста ----
     Форма собрана из пяти вложенных таблиц. Общее правило «form table →
     block» их разбирает, но заодно разрывает пары «квадратик — подпись»:
     они лежат в соседних ячейках, и каждая становится своей строкой.
     Чинить это правилами нельзя — пары надо держать вместе, а ячейки
     соседями не выбираются.

     Поэтому таблицы разбираем сами: узлы, за которые держится скрипт
     лепры (панель кнопок с её id, поле, загрузчик, кнопка отправки),
     переносим целиком, пары собираем в отдельные пункты, остаток
     выбрасываем. Порядок свой: панель — поле — два свёрнутых списка
     (категории и специальные опции) — отправка.

     Клонировать ничего нельзя: на узлах висят обработчики лепры,
     переживает их только перенос. */

  function newPostForm() {
    var f = document.querySelector('#js-new_post_form');
    if (!f) return null;
    /* Форма быстрого поста в ленте носит те же id, но она скрыта и
       разбирать её незачем. Как именно она обёрнута, по сохранённой
       странице не видно — поэтому отсекаем и по предку, и по потомку. */
    if (f.closest && f.closest('.b-new_post_miniform')) return null;
    if (f.querySelector('.b-new_post_miniform')) return null;
    return f.querySelector('#js-new_post_body') ? f : null;
  }

  /* Пара «квадратик — подпись». wrapCheckbox для этого не годится:
     там input и label лежат в одном родителе, здесь всегда в разных
     ячейках, и связывает их только атрибут for. */
  function npPair(f, inp) {
    var pair = document.createElement('span');
    pair.className = 'lm-np_opt';
    var lab = inp.id ? f.querySelector('label[for="' + inp.id + '"]') : null;
    pair.appendChild(inp);
    if (lab) pair.appendChild(lab);
    return pair;
  }

  /* Заголовки групп лепра размечает по-разному: «Cпециальные опции:» —
     жирным начертанием внутри ячейки (буква C в начале латинская, поэтому
     ищем со второй), «Выберите категорию …» — просто текстом ячейки.
     Ни класса, ни общего тега у них нет, так что ищем по тексту.
     Годится только самый глубокий подходящий узел: у всех ячеек-обёрток
     текст ровно тот же. */
  function npHeadText(f, re) {
    var all = f.querySelectorAll('b, td');
    for (var i = 0; i < all.length; i++) {
      if (!re.test(all[i].textContent || '')) continue;
      if (all[i].querySelector('b, td, table')) continue;
      return all[i];
    }
    return null;
  }

  /* Название списка берём у лепры, но чистим: пояснение в скобках
     («Посты без категории автоматически получают …») занимало на телефоне
     три строки ради того, что и так понятно, а двоеточие в подписи
     свёрнутого списка лишнее. Если разметка изменится и заголовок не
     найдётся — своё название. */
  function npTitle(head, def) {
    if (!head) return def;
    var small = head.querySelector('.small, i, span');
    if (small && small.parentNode) small.parentNode.removeChild(small);
    var t = (head.textContent || '').replace(/\s+/g, ' ')
              .replace(/\s*:\s*$/, '').trim();
    return t || def;
  }

  function npPairs(f, sel) {
    var list = f.querySelectorAll(sel), out = [];
    for (var i = 0; i < list.length; i++) out.push(npPair(f, list[i]));
    return out;
  }

  /* Список: кнопка с названием и сама группа пунктов. В разметку они
     кладутся врозь (сначала обе кнопки, потом обе группы), поэтому
     возвращаем пару, а расставляет уже fixNewPost.
     Кнопке обязателен type="button": без него она внутри формы работает
     кнопкой отправки, и первое же нажатие отправило бы пустой пост. */
  function npList(key, title, items) {
    if (!items.length) return null;
    var btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'lm-np_toggle lm-np_toggle-' + key;
    var t = document.createElement('span');
    t.className = 'lm-np_toggle_t';
    t.textContent = title;
    var v = document.createElement('span');
    v.className = 'lm-np_toggle_v';
    btn.appendChild(t);
    btn.appendChild(v);

    var g = document.createElement('div');
    g.className = 'lm-np_group lm-np_' + key;
    for (var i = 0; i < items.length; i++) g.appendChild(items[i]);

    btn.addEventListener('click', function () {
      btn.classList.toggle('lm-open', g.classList.toggle('lm-open'));
    });
    return { btn: btn, box: g };
  }

  /* Подпись под названием: что в списке выбрано. Без неё свёрнутый список
     прячет и сам выбор — категорию поставил, закрыл, и проверить нечем,
     кроме как открыть заново. */
  function npValue(lists, key, text) {
    var v = lists.querySelector('.lm-np_toggle-' + key + ' .lm-np_toggle_v');
    if (v) v.textContent = text;
  }

  function npStatus(lists) {
    var cats = lists.querySelector('.lm-np_cats');
    if (cats) {
      var on = cats.querySelector('input:checked');
      var lab = on && on.id && cats.querySelector('label[for="' + on.id + '"]');
      var name = lab ? (lab.textContent || '').replace(/\s+/g, ' ').trim() : '';
      npValue(lists, 'cats', on ? (name || 'выбрана') : 'без категории');
    }
    var flags = lists.querySelector('.lm-np_flags');
    if (flags) {
      var n = flags.querySelectorAll('input:checked').length;
      npValue(lists, 'flags', n ? 'выбрано: ' + n : 'ничего');
    }
  }

  function fixNewPost() {
    var f = newPostForm();
    if (!f) return;
    document.documentElement.classList.add('lm-newpost');
    if (f.querySelector('.lm-np')) return;      /* уже разобрано */

    /* Заголовок подлепры и полосу её оформления выносим ИЗ формы —
       наружу, перед неё.

       На подлепре лепра кладёт <h1 class="b-subsite_header"> внутрь
       самой формы (на главной его нет вовсе), а relayoutHeader к этому
       времени успевает пристроить рядом с ним полосу #lm-subband — она
       строится сразу после заголовка, где бы тот ни лежал. Ниже мы
       сносим все прежние дети формы разом, и оба узла уходили вместе с
       таблицами. Снаружи это выглядело так, будто пост пишется не на
       подлепру: ни названия, ни картинки, всё как на главной. Форма при
       этом всё время слала куда надо — action у неё на домен подлепры,
       и мы его не трогаем.

       Переносим узлами, а не копиями: за заголовком у лепры закреплён
       обработчик перехода, а за полосой — наш замер высоты картинки,
       который дорисовывает её по загрузке. Порядок сохраняем — сперва
       заголовок, потом полоса, — вставляя оба перед формой по очереди.

       Кегль заголовка потом подгонит замером fitSubsiteHeader: он ищет
       узел по классу, а не по месту в разметке, и переезд ему не
       помеха. */
    var head = f.querySelector('.b-subsite_header');
    var band = f.querySelector('#lm-subband');
    if (head && f.parentNode) f.parentNode.insertBefore(head, f);
    if (band && f.parentNode) f.parentNode.insertBefore(band, f);

    var np = document.createElement('div');
    np.className = 'lm-np';

    var tools = f.querySelector('#js-new_post_body_wysiwyg');
    if (tools) {
      /* инлайновый white-space:nowrap держал панель в одну строку */
      tools.style.removeProperty('white-space');
      np.appendChild(tools);
    }
    var body = f.querySelector('#js-new_post_body');
    if (body) np.appendChild(body);

    /* Категории и опции — в два свёрнутых списка под полем. Развёрнутыми
       это два десятка строк между полем и кнопкой отправки: чтобы просто
       написать пост, приходилось прокручивать их все. */
    var lists = document.createElement('div');
    lists.className = 'lm-np_lists';
    var pack = [
      npList('cats', npTitle(npHeadText(f, /^\s*Выберите категорию/i),
                             'Выберите категорию'),
             npPairs(f, 'input[type="radio"]')),
      npList('flags', npTitle(npHeadText(f, /пециальные опции/i),
                              'Специальные опции'),
             npPairs(f, 'input[type="checkbox"]'))
    ];
    for (var p = 0; p < pack.length; p++) if (pack[p]) lists.appendChild(pack[p].btn);
    for (p = 0; p < pack.length; p++) if (pack[p]) lists.appendChild(pack[p].box);
    if (lists.firstChild) {
      np.appendChild(lists);
      lists.addEventListener('change', function () { npStatus(lists); });
      npStatus(lists);
    }

    var send = document.createElement('div');
    send.className = 'lm-np_send';
    var up = f.querySelector('#js-new_post_file');
    if (up) send.appendChild(up);
    var go = f.querySelector('#js-new_post_submit');
    if (go) send.appendChild(go);
    if (send.firstChild) np.appendChild(send);

    /* Всё, что осталось от таблиц, уходит вместе с ними. Но сначала
       спасаем поля, которых мы не знаем: в сохранённой странице форма
       обходится без служебных, а на живом сайте в ней может лежать что
       угодно, и без такого поля пост просто не отправится. Скрытые
       ничего не займут, видимые встанут внизу — заметно и починимо,
       в отличие от молча пропавшего значения. */
    var keep = document.createElement('div');
    keep.className = 'lm-np_keep';
    var rest = f.querySelectorAll('input, select, textarea, button');
    for (var i = 0; i < rest.length; i++) keep.appendChild(rest[i]);
    if (keep.firstChild) np.appendChild(keep);

    var old = sliceOf(f.childNodes);
    f.appendChild(np);
    for (var k = 0; k < old.length; k++) f.removeChild(old[k]);
  }

  /* ============================================================
     4.3. СЛЕЖЕНИЕ ЗА ПЫНЯМИ
     ============================================================ */

  /* Счётчик в шапке лепра ставит один раз при загрузке и больше не
     трогает — то есть узнать о новом пыне, не перезагружая страницу,
     нельзя. Здесь скрипт спрашивает сам.

     Спрашивается ровно один адрес — счётчик непрочитанных по типам. Это
     важно не только из-за веса (десятки байт против ста тридцати семи
     килобайт у ленты): у каждого уведомления в ленте есть свой адрес
     mark_read, и лепра, показывая ленту, их отмечает. Опрашивай мы
     ленту — слежение молча гасило бы то, о чём собиралось сообщить.

     Заголовки авторизации — те же, что шлёт сама лепра: пара
     X-Futuware-UID и X-Futuware-SID лежит в обычных куках. Без них
     весь /api/ отвечает 404. */

  var API_BASE = '/api/my/notifications/';
  var PYN_SEEN = 'lm-pyn-seen';   /* сколько непрочитанных человек уже видел */

  var apiAuthCache = null;

  function apiAuth() {
    if (apiAuthCache) return apiAuthCache;
    var f = findAuth(authSources());
    if (!f.uid || !f.sid) return null;
    apiAuthCache = {
      'X-Futuware-UID': f.uid.value,
      'X-Futuware-SID': f.sid.value,
      'X-Requested-With': 'XMLHttpRequest',
      'Accept': 'application/json, text/javascript, */*; q=0.01'
    };
    return apiAuthCache;
  }

  /* Отметка о прочтении. Из перехвата на странице уведомлений:
       POST /api/my/notifications/mark_read/          — всё разом
       POST /api/my/notifications/<id>/mark_read/     — по одному (из _links)
       POST /api/my/notifications/mark_seen           — «увидено», гасит
                                                        только цифру
     У всех троих тело — {"csrf_token": "…"}, и это единственное, чего
     в отчёте не было видно откуда. Токен оказался base64 от шестидесяти
     четырёх шестнадцатеричных знаков, так что искать его можно по виду:
     либо готовая строка base64, либо сам hex, который надо закодировать.
     Перебирать имена бессмысленно — лепра могла назвать как угодно. */
  var HEX64 = /^[0-9a-f]{64}$/i;
  var B64_64 = /^[A-Za-z0-9+/]{86}==$/;

  function findCsrf() {
    var all = authSources();
    for (var i = 0; i < all.length; i++) {
      var v = String(all[i].value || '');
      if (B64_64.test(v)) {
        try {
          if (HEX64.test(atob(v)))
            return { where: all[i].where, name: all[i].name, token: v };
        } catch (e) {}
      }
      if (HEX64.test(v)) {
        try {
          return { where: all[i].where, name: all[i].name, token: btoa(v) };
        } catch (e) {}
      }
    }
    /* Запасные пути, по убыванию свежести: подсмотренный в этой вкладке,
       подсмотренный в скрытом окне пыни (там лепра шлёт mark_seen со
       своим токеном) и сохранённый с прошлого раза. */
    var seen = csrfSeen;
    if (!seen) { try { seen = window.lmCsrf || null; } catch (e) {} }
    if (!seen) {
      var kept = null;
      try { kept = localStorage.getItem(CSRF_KEY); } catch (e) {}
      if (kept) {
        var who = null;
        try { who = JSON.parse(kept); } catch (e) {}
        if (who && who.token) {
          /* Записи без владельца — от прежних версий скрипта. Им верить
             нельзя: неизвестно, чья сессия их оставила. */
          if (who.uid && who.uid === currentUid())
            return { where: 'память', name: 'с прошлого раза', token: who.token };
          try { localStorage.removeItem(CSRF_KEY); } catch (e) {}
        } else {
          try { localStorage.removeItem(CSRF_KEY); } catch (e) {}
        }
      }
    }
    return seen ? { where: 'перехват', name: 'запрос лепры', token: seen }
                : null;
  }

  /* Кто сейчас в сессии. Нужен, чтобы не подсунуть чужой токен: у лепры
     он привязан к сессии, а вкладки под разными гражданами открываются
     в одном браузере запросто. */
  function currentUid() {
    var h = apiAuth();
    return h ? String(h['X-Futuware-UID'] || '') : '';
  }

  var CSRF_KEY = 'lm-pyn-csrf';
  var csrfSeen = null;

  /* --- токен для /ajax/ --- */

  /* Токенов у лепры ДВА, и это выяснилось дорогой ценой.
     Тот, что лежит в JSON-теле запросов к /api/, для /ajax/ не годится:
     сервер отвечает двумястами и телом {"status":"ERR","errors":
     [{"code":"invalid_csrf_token"}]}. Голоса из окна пыни уходили в
     никуда именно поэтому.
     Нужный лежит в теле её собственных запросов к /ajax/ — обычной
     строкой csrf_token=… среди прочих полей. Такие запросы лепра шлёт
     на каждой странице сама (/ajax/post_view/, /ajax/interest/
     unread_count/), так что ждать долго не приходится.
     Храним отдельно и тоже с владельцем сессии: под другим гражданином
     чужой токен так же негоден. */
  var AJAX_CSRF_KEY = 'lm-ajax-csrf';
  var AJAX_CSRF_COOKIE = 'lm_ajax_csrf';
  var ajaxCsrfSeen = null;
  var ajaxCsrfFrom = '';        /* откуда взяли — для отчёта */

  /* Хранилище браузера привязано к домену: то, что скрипт запомнил на
     test.leprosorium.ru, на leprosorium.ru недоступно. А ловится токен
     как раз не везде — лепра шлёт свои /ajax/-запросы на страницах
     постов и подсайтов, а на главной ленте может не слать вовсе, пока
     не нажмут «Ещё». Отсюда и «токен /ajax/: НЕТ» на главной при
     пойманном токене на посте.
     Поэтому кладём ещё и в куку на общий домен: куки, в отличие от
     хранилища, у поддоменов общие. Кука своя, не лепровская, живёт
     сутки и уходит вместе с сессией браузера.
     Одинаков ли токен на всех поддоменах, наверняка неизвестно; сессия
     общая, так что скорее да. Если окажется, что нет, отказ придёт
     тем же invalid_csrf_token, и в отчёте будет видно, с какого домена
     токен взят.
     baseDomain() объявлена наверху, в разделе общих настроек: там она
     нужна тем же способом и по той же причине. */
  function ajaxCsrfPut(tok) {
    ajaxCsrfSeen = tok;
    try {
      localStorage.setItem(AJAX_CSRF_KEY, JSON.stringify({
        uid: currentUid(), token: tok, from: location.hostname
      }));
    } catch (e) {}
    try {
      document.cookie = AJAX_CSRF_COOKIE + '=' +
        encodeURIComponent(currentUid() + '|' + location.hostname + '|' + tok) +
        '; domain=.' + baseDomain() + '; path=/; max-age=86400; samesite=lax';
    } catch (e) {}
  }

  function ajaxCsrfCookie() {
    var raw = '';
    try {
      var m = new RegExp('(?:^|; )' + AJAX_CSRF_COOKIE + '=([^;]*)')
        .exec(document.cookie || '');
      raw = m ? decodeURIComponent(m[1]) : '';
    } catch (e) {}
    if (!raw) return null;
    var p = raw.split('|');
    if (p.length < 3 || !p[2]) return null;
    if (p[0] !== currentUid()) return null;    /* чужая сессия */
    return { token: p[2], from: p[1] };
  }

  /* Токен в разметке страницы. Это и есть то место, откуда его берёт
     сам скрипт лепры: он приходит с сервера во встроенном <script>, а
     дальше живёт в замыкании — ни в окне, ни в хранилище его нет,
     потому перебор глобальных переменных и не находил ничего.
     Почему это не нашлось раньше: встроенные скрипты не попадают в
     сохранённые страницы (.mhtml их выбрасывает), и по ним искать было
     нечего. В живом браузере они на месте и читаются свободно.
     Ищем сперва по имени, потом просто по виду: токен — это base64 от
     шестидесяти четырёх шестнадцатеричных знаков, спутать такое с чем-то
     ещё трудно. */
  function csrfFromScripts() {
    var tags;
    try { tags = document.getElementsByTagName('script'); } catch (e) { return null; }
    for (var i = 0; i < tags.length && i < 60; i++) {
      if (tags[i].src) continue;                   /* внешние не читаются */
      var txt = '';
      try { txt = tags[i].textContent || ''; } catch (e) {}
      if (!txt || txt.indexOf('csrf') < 0) continue;
      var m = /csrf[_-]?token["'\s:=]+["']([A-Za-z0-9+/=]{40,160})["']/i.exec(txt);
      if (m && looksLikeCsrf(m[1])) return m[1];
      var any = txt.match(/["']([A-Za-z0-9+/]{80,120}={0,2})["']/g) || [];
      for (var j = 0; j < any.length; j++) {
        var v = any[j].slice(1, -1);
        if (looksLikeCsrf(v)) return v;
      }
    }
    return null;
  }

  function looksLikeCsrf(v) {
    try { return HEX64.test(atob(v)); } catch (e) { return false; }
  }

  function catchAjaxCsrf(url, body) {
    if (ajaxCsrfSeen || !body) return;
    if (String(url || '').indexOf('/ajax/') < 0) return;
    var m = /(?:^|&)csrf_token=([^&]+)/.exec(String(body));
    if (!m) return;
    var tok;
    try { tok = decodeURIComponent(m[1]); } catch (e) { tok = m[1]; }
    if (!tok) return;
    ajaxCsrfFrom = 'перехват на ' + location.hostname;
    ajaxCsrfPut(tok);
  }

  function ajaxCsrf() {
    if (ajaxCsrfSeen) return ajaxCsrfSeen;

    /* Разметка — первый и главный источник: он есть на КАЖДОЙ странице,
       не зависит ни от домена, ни от того, отправляла ли лепра свои
       запросы. Всё остальное ниже — запасные пути. */
    var inPage = csrfFromScripts();
    if (inPage) { ajaxCsrfFrom = 'из разметки'; ajaxCsrfPut(inPage); return inPage; }

    /* Скрытое окно пыни грузит /my/events/ — там лепра свои запросы
       шлёт, и её токен приезжает оттуда. */
    var fromFrame = null;
    try { fromFrame = window.lmAjaxCsrf || null; } catch (e) {}
    if (fromFrame) { ajaxCsrfFrom = 'из окна пыни'; ajaxCsrfPut(fromFrame); return fromFrame; }

    var kept = null;
    try { kept = localStorage.getItem(AJAX_CSRF_KEY); } catch (e) {}
    if (kept) {
      var who = null;
      try { who = JSON.parse(kept); } catch (e) {}
      if (who && who.token && who.uid === currentUid()) {
        ajaxCsrfFrom = 'память ' + (who.from || '?');
        return who.token;
      }
      try { localStorage.removeItem(AJAX_CSRF_KEY); } catch (e) {}
    }

    var ck = ajaxCsrfCookie();
    if (ck) { ajaxCsrfFrom = 'кука, снят на ' + ck.from; return ck.token; }
    return null;
  }

  /* Вызывается из перехвата: тело POST-запроса лепры к её API. */
  function catchCsrf(url, body) {
    catchAjaxCsrf(url, body);
    if (csrfSeen || !body || String(url || '').indexOf('/api/') < 0) return;
    try {
      var j = JSON.parse(body);
      if (j && typeof j.csrf_token === 'string' && j.csrf_token) {
        csrfSeen = j.csrf_token;
        csrfCache = null;      /* пересобрать при следующем обращении */
        /* Кладём рядом с прочим своим: без этого кнопка отметки была бы
           доступна только на той странице, где лепра успела что-то
           отправить, а на остальных отсутствовала бы без объяснений. */
        try {
          /* Вместе с владельцем сессии. Токен привязан к сессии, а не к
             браузеру: под другим гражданином сохранённый с прошлого раза
             уже негоден — сервер отвечает двумястами, но действие молча
             не выполняет. Именно на это ушли впустую первые голоса из
             окна пыни: страница была под одним гражданином, а токен
             лежал от другого. */
          localStorage.setItem(CSRF_KEY, JSON.stringify({
            uid: currentUid(), token: csrfSeen
          }));
        } catch (e) {}
      }
    } catch (e) {}
  }

  var csrfCache = null;

  function csrfToken() {
    if (!csrfCache) csrfCache = findCsrf();
    return csrfCache ? csrfCache.token : null;
  }

  /* Один POST к API лепры с её же телом. */
  function apiPost(path, cb) {
    var h = apiAuth(), tok = csrfToken();
    if (!h || !tok) return cb && cb(false);
    var headers = {};
    Object.keys(h).forEach(function (k) { headers[k] = h[k]; });
    headers['Content-Type'] = 'application/json';
    try {
      fetch(location.protocol + '//' + location.host + path,
            { method: 'POST', credentials: 'same-origin', headers: headers,
              body: JSON.stringify({ csrf_token: tok }) })
        .then(function (r) {
          /* Токен мог протухнуть вместе с сессией — пусть следующий заход
             ищет заново. */
          if (!r.ok) {
            csrfCache = null;
            csrfSeen = null;
            try { localStorage.removeItem(CSRF_KEY); } catch (e) {}
          }
          cb && cb(r.ok);
        })
        .catch(function () { cb && cb(false); });
    } catch (e) { cb && cb(false); }
  }

  /* Отмечаем поимённо, а не «всё разом»: в окне видно двадцать последних,
     а непрочитанных может быть больше. Гасить то, чего человек не видел,
     мы не вправе — для этого есть отдельная кнопка. */
  function markRead(ids, cb) {
    var left = ids.length;
    if (!left) return cb && cb(0);
    var okCount = 0;
    ids.forEach(function (id) {
      apiPost(API_BASE + id + '/mark_read/', function (ok) {
        if (ok) okCount++;
        if (--left === 0) cb && cb(okCount);
      });
    });
  }

  /* Идентификаторы непрочитанных уведомлений внутри узла. Лепра держит
     их в data-notification, а непрочитанность — классом. */
  function unreadIds(root) {
    return sliceOf(root.querySelectorAll(
             '.b-notification-item__unread[data-notification]'))
           .map(function (el) { return el.getAttribute('data-notification'); })
           .filter(Boolean);
  }

  function pynCount(cb) {
    var h = apiAuth();
    if (!h) return cb(null);
    try {
      fetch(location.protocol + '//' + location.host +
            API_BASE + 'unread/count_by_type/',
            { credentials: 'same-origin', headers: h })
        .then(function (r) {
          if (!r.ok) throw new Error('HTTP ' + r.status);
          return r.json();
        })
        .then(function (j) {
          var by = (j && j.count) || {};
          var total = 0;
          Object.keys(by).forEach(function (k) { total += (+by[k] || 0); });
          cb({ total: total, by: by });
        })
        .catch(function () {
          /* Чаще всего это протухшая сессия: человек перелогинился, и в
             куках теперь другой ключ. Сбрасываем разбор, следующий заход
             прочитает куки заново. */
          apiAuthCache = null;
          cb(null);
        });
    } catch (e) { cb(null); }
  }

  /* Счётчик у колокольчика лепра ставит один раз при загрузке и больше
     не трогает. Раз мы всё равно спрашиваем число, обновляем и его —
     иначе выходит нелепость: плашка про новые пыни есть, а рядом в шапке
     старая цифра. Пустая строка вместо нуля: у лепры счётчик пуст, когда
     непрочитанных нет, и рисовать «0» значит выдумывать свой вид. */
  var headerMuted = false;   /* окно пыни открывали — цифру прячем */

  function setHeaderCount(n) {
    /* На самой странице уведомлений счётчиком распоряжается лепра: после
       отрисовки ленты она его опустошает, хотя на сервере уведомления
       остаются непрочитанными (перезагрузка это показывает). Спорить с
       ней там незачем — цифра прыгала бы туда-сюда каждый опрос. */
    if (onEventsPage()) return;
    var want = (headerMuted || n <= 0) ? '' : String(n);
    sliceOf(document.querySelectorAll('.js-events-counter'))
      .forEach(function (el) {
        if (el.textContent !== want) el.textContent = want;
      });
  }

  function seenCount() {
    try {
      var v = parseInt(localStorage.getItem(PYN_SEEN), 10);
      return isNaN(v) ? null : v;
    } catch (e) { return null; }
  }

  function setSeen(n) {
    try { localStorage.setItem(PYN_SEEN, String(n)); } catch (e) {}
  }

  /* Русский счёт: одна пынь, две пыни, пять пыней. */
  function pynWord(n) {
    var t = n % 100, o = n % 10;
    if (t > 10 && t < 20) return 'пыней';
    if (o === 1) return 'пынь';
    if (o >= 2 && o <= 4) return 'пыни';
    return 'пыней';
  }

  function pynNewWord(n) {
    var t = n % 100, o = n % 10;
    if (t > 10 && t < 20) return 'новых';
    if (o === 1) return 'новая';
    if (o >= 2 && o <= 4) return 'новые';
    return 'новых';
  }

  /* Пара форм на тип: при «2 новые пыни» подпись «ответ на комментарий»
     в единственном числе спорит с числом слева. Пока известен один тип
     из ответа лепры (comment_answer), остальные добавятся, когда
     встретятся — выдумывать названия для незнакомых незачем. */
  var PYN_TYPES = {
    comment_answer: ['ответ на комментарий', 'ответы на комментарии'],
    mention: ['упоминание', 'упоминания']
  };

  function pynToastText(n, by) {
    var head = n + ' ' + pynNewWord(n) + ' ' + pynWord(n);
    var kinds = Object.keys(by || {}).filter(function (k) { return +by[k] > 0; });
    if (kinds.length === 1 && PYN_TYPES[kinds[0]])
      head += ' — ' + PYN_TYPES[kinds[0]][n === 1 ? 0 : 1];
    return head;
  }

  var toastTimer = null;

  var PYN_TEXTOK = 'lm-pyn-textok';   /* '1' — лента не гасит счётчик, '0' — гасит */

  /* Глаголы по типу уведомления. Названий для незнакомых типов не
     выдумываем: лучше короткий текст про число, чем уверенная неправда. */
  var PYN_VERB = {
    comment_answer: 'ответил на ваш комментарий',
    mention: 'упомянул вас'
  };

  /* Строение ответа лепры (сокращённо):
     notifications[0].type
     notifications[0].data.comment.body
     notifications[0].data.comment.post.title
     notifications[0].data.comment.user.login   — предположительно
     Логин ищем по нескольким путям: до него отчёт не дотянулся, а
     промахнуться на одном имени поля значит потерять весь текст. */
  function digLogin(o, depth) {
    if (!o || typeof o !== 'object' || (depth || 0) > 3) return '';
    if (typeof o.login === 'string' && o.login) return o.login;
    var keys = ['data', 'comment', 'mention', 'user', 'author', 'from', 'sender'];
    for (var i = 0; i < keys.length; i++) {
      var v = digLogin(o[keys[i]], (depth || 0) + 1);
      if (v) return v;
    }
    return '';
  }

  function noteBrief(item) {
    if (!item) return '';
    var d = item.data || {};
    var c = d.comment || d.mention || {};
    var who = digLogin(item);
    var title = (c.post && c.post.title) || (d.post && d.post.title) || '';
    var verb = PYN_VERB[item.type] || '';

    var parts = [];
    if (who) parts.push(who);
    if (verb) parts.push(verb);
    if (!parts.length) return '';
    var text = parts.join(' ');
    if (title) text += ' в посте «' + String(title).slice(0, 60) + '»';
    return text;
  }

  function pynLatest(cb) {
    var h = apiAuth();
    if (!h) return cb(null);
    try {
      fetch(location.protocol + '//' + location.host + API_BASE + '?per_page=1&page=1',
            { credentials: 'same-origin', headers: h })
        .then(function (r) {
          if (!r.ok) throw new Error('HTTP ' + r.status);
          return r.json();
        })
        .then(function (j) {
          cb((j && j.notifications && j.notifications[0]) || null);
        })
        .catch(function () { cb(null); });
    } catch (e) { cb(null); }
  }

  function textMode() {
    try { return localStorage.getItem(PYN_TEXTOK); } catch (e) { return null; }
  }

  /* У каждого уведомления в ленте есть свой адрес mark_read, и это
     говорит, что простой GET ничего отмечать не должен. «Должен» — не
     «проверено», поэтому первый же раз сверяем счётчик до и после. Если
     он просел, текст выключается навсегда, и слежение остаётся на одном
     счётчике. */
  function verifyText(before) {
    pynCount(function (r) {
      if (!r) return;
      var ok = r.total >= before;
      try { localStorage.setItem(PYN_TEXTOK, ok ? '1' : '0'); } catch (e) {}
      if (!ok) note('лента гасит счётчик — текст в плашке выключен');
    });
  }

  function hideToast() {
    if (toastTimer) { clearTimeout(toastTimer); toastTimer = null; }
    var t = document.getElementById('lm-pyntoast');
    if (t) t.remove();
  }

  /* --- дзинь --- */

  /* Звук делаем сами, через WebAudio. Причины две, и обе принципиальные:
     скрипт не ходит на сторонние адреса, а звуковой файл строкой в
     разметке — это десятки килобайт в каждой вкладке ради двух нот.

     Про разрешение. Safari на iOS не даёт воспроизводить звук, пока на
     странице не было касания, и созданный до касания AudioContext
     остаётся в состоянии suspended навсегда, если его не растолкать.
     Поэтому контекст создаётся ЛЕНИВО — при первом касании, а не при
     загрузке, — и тем же касанием запускается. Обработчик разовый:
     дальше контекст живёт сам.

     Отдельно: не создавать контекст заранее — это ещё и вежливость к
     батарее. Работающий аудиоконтекст держит звуковой поток открытым,
     а вкладок с лепрой у человека может быть несколько. */
  var dingCtx = null;
  var dingArmed = false;

  /* Создать и растолкать контекст. Звать можно только из обработчика
     касания — иначе Safari создаст его сразу в состоянии suspended и
     больше не выпустит. */
  function dingWake() {
    var AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    try {
      if (!dingCtx) dingCtx = new AC();
      if (dingCtx.state === 'suspended') dingCtx.resume();
    } catch (e) { /* звука не будет — плашка всё равно покажется */ }
  }

  function dingArm() {
    if (dingArmed) return;
    dingArmed = true;
    ['touchstart', 'mousedown', 'keydown'].forEach(function (ev) {
      document.addEventListener(ev, dingWake,
                                { once: true, passive: true, capture: true });
    });
  }

  function ding() {
    /* Контекст умеет засыпать сам: Safari усыпляет его, когда вкладка
       уходит в фон, и обратно не будит. Пробуем растолкать — если
       страница на переднем плане, это разрешено; если нет, звука не
       будет, и плашка отработает одна. */
    if (dingCtx && dingCtx.state === 'suspended') {
      try { dingCtx.resume(); } catch (e) {}
    }
    if (!dingCtx || dingCtx.state !== 'running') return;
    var t0 = dingCtx.currentTime;
    /* Две ноты вверх: ми и си второй октавы. Восходящая пара читается
       как «пришло», нисходящая — как «закрылось», одиночная теряется
       среди системных звуков телефона.
       Каждая нота с быстрым нарастанием и мягким спадом: щелчок в
       начале и в конце получается именно от прямоугольного включения
       громкости, а не от самой ноты. */
    [[659.25, 0], [987.77, 0.11]].forEach(function (n) {
      var osc = dingCtx.createOscillator();
      var gain = dingCtx.createGain();
      osc.type = 'sine';
      osc.frequency.value = n[0];
      var at = t0 + n[1];
      gain.gain.setValueAtTime(0.0001, at);
      gain.gain.exponentialRampToValueAtTime(CFG.dingVolume || 0.35, at + 0.012);
      gain.gain.exponentialRampToValueAtTime(0.0001, at + 0.16);
      osc.connect(gain);
      gain.connect(dingCtx.destination);
      osc.start(at);
      osc.stop(at + 0.18);
    });
  }

  /* Сообщить о новых пынях так, как человек попросил. Один вход вместо
     двух вызовов по месту: способов три, а мест, где о пыни сообщают,
     будет больше одного. */
  function pynNotify(text) {
    /* Запасное значение прямо здесь, а не только в CFG. Один раз блок
       настроек уже не записался в файл при правке, и отсутствующее
       CFG.pynSound молча меняло поведение: сравнение с 'push' давало
       ложь, и скрипт пытался дзинькать при выключенном звуке. Проверка
       синтаксиса такого не ловит — как и в случае с пропавшими
       объявлениями переменных, описанным в записке. */
    var how = CFG.pynSound || 'push';
    if (how === 'none') return;
    if (how !== 'push') guard('ding', ding)();
    if (how !== 'ding') showToast(text);
  }

  function showToast(text) {
    hideToast();
    if (!document.body) return;

    var box = document.createElement('div');
    box.id = 'lm-pyntoast';

    /* Кнопка, а не div с обработчиком. Safari на iOS доставляет тап
       обычным блокам ненадёжно: первое касание уходит вхолостую, и
       открыть окно получалось со второго-третьего раза. Настоящий
       интерактивный элемент такого не требует. */
    var label = document.createElement('button');
    label.type = 'button';
    label.className = 'lm-pyntoast_text';
    label.textContent = text;

    var close = document.createElement('button');
    close.type = 'button';
    close.className = 'lm-pyntoast_close';
    close.textContent = '✕';
    close.addEventListener('click', function (e) {
      e.stopPropagation();
      hideToast();
    });

    /* Читать прямо в плашке нечего: одна строка не вместит ни ответа, ни
       ветки. Поэтому тап открывает наше окно пыни — оно уже умеет всё,
       включая разворот исходного комментария, и закрывается на то же
       место страницы, где человек читал. */
    label.addEventListener('click', function () {
      hideToast();
      guard('pynOpen', pynOpen)();
    });

    box.appendChild(label);
    box.appendChild(close);
    /* Сторону ставим классом, а не стилем: правила для верха и низа
       различаются не одним свойством (безопасная зона снизу, отступ от
       шапки сверху), и держать их в CSS честнее, чем собирать в коде. */
    if (CFG.pynToastSide === 'top') box.classList.add('lm-top');
    document.body.appendChild(box);

    toastTimer = setTimeout(hideToast, CFG.pynToast * 1000);
  }

  var watchTimer = null;
  var lastAsk = 0;

  function askPyn() {
    lastAsk = Date.now();
    pynCount(function (res) {
      if (!res) return;
      var seen = seenCount();
      /* Появилось новое — цифру снова показываем, даже если окно уже
         открывали: это уже другие пыни. */
      if (seen !== null && res.total > seen) headerMuted = false;
      guard('setHeaderCount', setHeaderCount)(res.total);
      /* Первый ответ после загрузки страницы запоминаем молча: эти
         непрочитанные не новость — они уже стоят числом в шапке. */
      if (seen === null) return setSeen(res.total);
      if (res.total <= seen) {
        /* Меньше стало — человек прочитал их в другой вкладке или в
           другом браузере. Опускаем отметку, иначе следующая пынь
           окажется «не новее виденного» и промолчит. */
        if (res.total < seen) setSeen(res.total);
        return;
      }
      setSeen(res.total);

      var n = res.total - seen;
      var short = pynToastText(n, res.by);
      var mode = textMode();

      /* Молчим — значит и подробностей не нужно. Запрос за последним
         уведомлением весит около четырёх с половиной килобайт, и делать
         его ради текста, который никто не увидит, незачем. */
      if (CFG.pynSound === 'none') return;
      if (!CFG.pynText || mode === '0') return pynNotify(short);

      /* Текст берём по последнему уведомлению. Если запрос не удался или
         разобрать нечего — показываем короткий вариант, а не молчим. */
      pynLatest(function (item) {
        var brief = noteBrief(item);
        /* Строка одна и узкая. При нескольких новых показываем последний
           пынь целиком и хвост «и ещё N» — это короче и понятнее, чем
           число с типом и тем же текстом следом. */
        pynNotify(!brief ? short
                         : (n === 1 ? brief : brief + ' + ещё ' + (n - 1)));
        if (mode === null) verifyText(res.total);
      });
    });
  }

  function watchPyn() {
    if (!CFG.pynWatch || watchTimer) return;
    if (!apiAuth()) return;      /* ключа нет — спрашивать нечем */

    /* Готовим звук заранее — то есть вешаем ожидание первого касания.
       Здесь, а не в момент, когда дзинькать пора: к тому времени
       касание уже давно было бы, а обработчик на него — нет. */
    if (CFG.pynSound === 'ding' || CFG.pynSound === 'both')
      guard('dingArm', dingArm)();

    var tick = function () {
      if (document.visibilityState === 'hidden') return;
      askPyn();
    };

    watchTimer = setInterval(guard('askPyn', tick), CFG.pynEvery * 1000);

    /* Возврат к вкладке — самый частый случай, когда новое уже накопилось.
       Спрашиваем сразу, но не чаще обычного шага, чтобы переключение
       туда-сюда не превращалось в поток запросов. */
    document.addEventListener('visibilitychange', function () {
      if (document.visibilityState !== 'visible') return;
      if (Date.now() - lastAsk < CFG.pynEvery * 1000) return;
      guard('askPyn', askPyn)();
    });

    guard('askPyn', askPyn)();
  }

  /* ============================================================
     5. ТЁМНАЯ ТЕМА
     ============================================================ */

  /* Ключ общий на все поддомены (см. SHARED_KEYS): тема — это про
     человека, а не про подлепру. */
  var DARK_KEY = 'lm-dark';

  function isDark() {
    return document.documentElement.classList.contains('lm-dark');
  }

  function themeColorValue() { return isDark() ? '#1a1a1a' : '#ffffff'; }

  /* Свой метатег ставим ПЕРВЫМ в head, а не последним. По правилам
     разметки браузер берёт первый подходящий theme-color, а не
     последний — своего у лепры сейчас нет, но появись он, наш в конце
     просто не подействовал бы. */
  function themeMeta() {
    var m = document.querySelector('meta[name="theme-color"][data-lm]');
    if (m) return m;
    var head = document.head || document.documentElement;
    if (!head) return null;
    m = document.createElement('meta');
    m.setAttribute('name', 'theme-color');
    m.setAttribute('data-lm', '1');
    head.insertBefore(m, head.firstChild);
    return m;
  }

  /* Цвет — фон страницы: белый обычно, тёмный при нашей тёмной теме.
     Она сделана инверсией всего документа, поэтому белый там становится
     почти чёрным, и панели должны быть под стать.

     nudge: Safari перерисовывает панели по изменению метатега, а не по
     содержимому страницы, и верхнюю строку обновляет заметно ленивее
     нижней. Поэтому там, где цвет должен смениться прямо сейчас, сперва
     ставим соседний оттенок и через кадр возвращаем нужный: разница в
     один шаг глазу не видна, а обновление вызывает. */
  function setThemeColor(nudge) {
    if (!CFG.themeColor) return;
    var m = themeMeta();
    if (!m) return;
    var want = themeColorValue();
    if (!nudge) { m.setAttribute('content', want); return; }
    m.setAttribute('content', isDark() ? '#1b1b1b' : '#fefefe');
    setTimeout(function () { m.setAttribute('content', want); }, 60);
  }

  /* Затемнение окна покупки перекрывает обе кромки экрана, и Safari
     красит панели по нему. После закрытия окна сам он их не пересчитает,
     поэтому ловим переход «было затемнение — не стало» и обновляем цвет
     принудительно. Следим за подложкой, а не за держателем: держатель
     высотой в один пиксель и виден всегда. */
  var darkOverlayOn = false;

  function syncThemeColor() {
    if (!CFG.themeColor) return;
    var box = document.getElementById('charley_holder');
    var b = box && box.querySelector('.black');
    var now = false;
    if (b) {
      var cs = getComputedStyle(b);
      now = cs.display !== 'none' && cs.visibility !== 'hidden' &&
            parseFloat(cs.opacity) > 0.05;
    }
    if (now === darkOverlayOn) return;
    darkOverlayOn = now;
    if (!now) setThemeColor(true);
  }

  function setDark(on) {
    document.documentElement.classList.toggle('lm-dark', on);
    /* Тему переключают на ходу, и если это случилось на прокрученной
       странице, признак «прокручено» остался бы висеть при выключенной
       липкости. Снимаем сразу; обратно его поставит наблюдатель при
       следующем движении. */
    guard('setStuck', setStuck)(false);
    prefSet(DARK_KEY, on ? '1' : '0');
    var b = document.getElementById('lm-theme');
    /* Знак берём у themeGlyph — одно место на оба вызова, иначе
       указатель начертания рано или поздно потеряется в одном из них. */
    if (b) b.textContent = (on ? '\u2600' : '\u263E') + '\uFE0E';
    setThemeColor(true);
  }

  /* применяем до отрисовки, иначе страница мигнёт белым */
  if (prefGet(DARK_KEY) === '1')
    document.documentElement.classList.add('lm-dark');

  /* Знак на кнопке темы. К символу приписан указатель текстового
     начертания (U+FE0E): без него iOS показывает солнце цветной
     наклейкой-эмодзи, а не знаком в цвет интерфейса — на тёмной теме
     это оранжевое пятно посреди строгой плашки. Луне повезло больше,
     эмодзи-варианта у неё нет, но приписываем обоим: пусть правило
     будет одно. */
  function themeGlyph() {
    return (isDark() ? '\u2600' : '\u263E') + '\uFE0E';
  }

  function ensureThemeToggle() {
    if (document.getElementById('lm-theme')) return;
    var header = document.querySelector('.l-header');
    if (!header) return;

    var b = document.createElement('button');
    b.id = 'lm-theme';
    b.type = 'button';
    b.title = 'светлая / тёмная тема';
    b.textContent = themeGlyph();
    b.addEventListener('click', function (e) {
      e.preventDefault();
      setDark(!isDark());
    });

    var logo = header.querySelector('.b-logo');
    if (logo && logo.parentNode === header) header.insertBefore(b, logo);
    else header.appendChild(b);
  }

  /* ============================================================
     6. НАВИГАЦИЯ ПО КОММЕНТАРИЯМ
     ============================================================ */

  /* Кэш держится отдельно на каждый вид списка. Раньше он был один на
     обоих, и стрелки со средней кнопкой выбивали друг друга: каждый
     тап заново собирал список и дёргал offsetParent у всех
     комментариев треда, а это принудительный пересчёт раскладки. */
  var navCache = {};

  /* Значки лепры, снятые с .b-comments_navigation: сетка 40×40,
     треугольник и маска. Нижняя стрелка у лепры — тот же треугольник,
     повёрнутый в CSS. Рисуем через createElementNS, а не innerHTML. */
  var SVG_NS = 'http://www.w3.org/2000/svg';
  var JUMP_TRIANGLE = '12,32 20,8 28,32';
  var JUMP_MASK = '29.749,20 37,14.821 27.695,14.708 30.506,6.053 ' +
    '22.904,11.198 20,3 17.096,11.198 9.494,6.053 12.305,14.708 ' +
    '3,14.821 10.252,20 3,25.179 12.305,25.292 9.494,33.947 ' +
    '17.096,28.802 20,37 22.904,28.802 30.506,33.947 27.695,25.292 ' +
    '37,25.179';

  function svgNode(name, attrs) {
    var el = document.createElementNS(SVG_NS, name);
    Object.keys(attrs).forEach(function (k) { el.setAttribute(k, attrs[k]); });
    return el;
  }

  function jumpIcon(kind) {
    var svg = svgNode('svg', {
      viewBox: '0 0 40 40', width: '40', height: '40',
      xmlns: SVG_NS, 'aria-hidden': 'true'
    });
    svg.appendChild(svgNode('polygon', {
      fill: CFG.jumpColor,
      points: kind === 'mine' ? JUMP_MASK : JUMP_TRIANGLE
    }));
    if (kind === 'mine') {
      /* глаза маски — красные, у лепры это единственное цветное пятно */
      svg.appendChild(svgNode('ellipse', {
        fill: CFG.jumpEye, cx: '15.842', cy: '18.441', rx: '1.195', ry: '1.173'
      }));
      svg.appendChild(svgNode('ellipse', {
        fill: CFG.jumpEye, cx: '24.573', cy: '18.442', rx: '1.195', ry: '1.172'
      }));
    }
    return svg;
  }

  /* Отступ приземления и порог отбора. Порог обязан быть БОЛЬШЕ отступа:
     иначе комментарий, только что поставленный на отметку приземления,
     снова проходит проверку, и каждый второй тап уходит впустую.

     Оба считаются от высоты липкой плашки: без неё цель садилась на
     шестьдесят пикселей от верха экрана и была видна, с ней — уезжала
     под плашку. Меряем при каждом обращении, а не запоминаем:
     приветствие на узком экране переносится на две строки, и высота
     меняется вместе с поворотом устройства и масштабом страницы.
     Разница в десять пикселей между порогом и отступом сохраняется —
     на ней держится вся навигация по комментариям. */
  function land() { return 60 + topbarH() + navStickH(); }
  function edge() { return land() + 10; }

  function commentsBy(kind) {
    var now = Date.now();
    var kept = navCache[kind];
    if (kept && now - kept.time < 3000) return kept.list;

    var host = document.getElementById('js-comments') || document;
    var list;
    if (kind === 'mine') list = sliceOf(host.querySelectorAll('.comment.mine'));
    else {
      list = sliceOf(host.querySelectorAll('.comment.new'));
      if (!list.length) list = sliceOf(host.querySelectorAll('.comment'));
    }

    /* Скрытые фильтром комментарии дают нулевой прямоугольник. Оставить их
       в списке нельзя: координаты перестают расти монотонно и двоичный
       поиск возвращает элемент выше экрана. */
    list = list.filter(function (el) { return el.offsetParent !== null; });

    navCache[kind] = { list: list, time: now };
    return list;
  }

  /* Счётчики «все комментарии N» и «новые N» — обычный текст в ссылках.
     После кнопки обновления лепра догружает комментарии, но числа оставляет
     прежними. Пересчитываем по документу: считаем то, что реально есть. */
  function refreshCommentCounters() {
    var host = document.getElementById('js-comments');
    var bar = document.querySelector('.b-comments_controls');
    if (!host || !bar) return;

    var total = host.querySelectorAll('.comment').length;
    var fresh = host.querySelectorAll('.comment.new').length;

    var put = function (key, value) {
      var link = bar.querySelector('a[data-key="' + key + '"]');
      if (!link) return;
      var text = link.textContent;
      if (!/\d+\s*$/.test(text)) return;          /* формат не тот — не трогаем */
      var updated = text.replace(/\d+\s*$/, value);
      if (updated !== text) link.textContent = updated;
    };

    put('all', total);
    put('unread', fresh);
  }

  /* ============================================================
     СТРОКА ФИЛЬТРОВ НАД ЛЕНТОЙ КОММЕНТАРИЕВ
     ============================================================

     У лепры это десять органов в одну строку: значок обновления, «все
     комментарии N», «новые N», ссылки, картинки, видео, поле «автор»,
     выбор пола, поле поиска, выбор сортировки. На десктопе они
     укладываются в строку, на телефоне занимают четыре и стоят перед
     каждым тредом стеной.

     Прячем всё, кроме трёх постоянно нужных: обновления и двух
     счётчиков. Остальное уходит в столбик под шевроном.

     Главное решение здесь — НИЧЕГО НЕ ПЕРЕСТАВЛЯТЬ, кроме одного
     переноса в столбик при сборке. Первая задумка была другой: активный
     фильтр вынимать из столбика обратно в строку, а при смене
     возвращать на место. Это значило бы двигать леприны узлы туда-сюда
     на каждое нажатие, помнить их исходный порядок и надеяться, что её
     обработчики переживут переезд.
     Вместо этого активный фильтр показывает САМ ШЕВРОН: подпись на нём
     и есть имя выбранного. Узлы при этом лежат неподвижно, а строка
     говорит ровно то же самое.

     Отсюда и правило показа, которое просил Den:
       выбрано «все»       → рядом видно «новые N»
       выбрано «новые»     → рядом видно «все комментарии N»
       выбрано что-то ещё  → видно оба счётчика, а имя выбранного стоит
                             на шевроне
     Первые два случая выходят сами собой: оба счётчика в строке всегда,
     а лепра красит выбранный своим классом. */

  /* Ключи, которые остаются в строке. Остальное уходит в столбик. */
  var CF_KEEP = { refresh: 1, all: 1, unread: 1 };

  function cfBar() { return document.querySelector('.b-comments_controls'); }

  /* Собрать столбик. Один раз за страницу: метка на самой строке. */
  function cfBuild() {
    var bar = cfBar();
    if (!bar || bar.dataset.lmFilters) return;

    var links = sliceOf(bar.querySelectorAll('a[data-key]'))
      .filter(function (a) { return !CF_KEEP[a.getAttribute('data-key')]; });
    /* Нечего прятать — не городим и шеврон. Так бывает на страницах, где
       лепра показывает урезанную строку. */
    if (!links.length) return;
    bar.dataset.lmFilters = '1';

    var more = document.createElement('button');
    more.type = 'button';
    more.className = 'lm-cf_more';
    /* Подпись и знак — разными узлами: подпись меняется, знак нет, и
       переписывать textContent целиком значило бы каждый раз собирать
       обе части заново. */
    var label = document.createElement('span');
    label.className = 'lm-cf_label';
    var arrow = document.createElement('span');
    arrow.className = 'lm-cf_arrow';
    more.appendChild(label);
    more.appendChild(arrow);

    var box = document.createElement('div');
    box.className = 'lm-cf_box';
    /* Переносим узлами, а не копиями: обработчики фильтров лепра вешает
       на них самих, и importNode их бы не перенёс — эта грабля у нас уже
       записана. Порядок разметки сохраняется сам, forEach идёт по нему. */
    links.forEach(function (a) { box.appendChild(a); });

    bar.appendChild(more);
    bar.appendChild(box);

    more.addEventListener('click', function (e) {
      e.preventDefault();
      bar.classList.toggle('lm-cf__open');
      more.setAttribute('aria-expanded',
        bar.classList.contains('lm-cf__open') ? 'true' : 'false');
    });

    /* Выбрали фильтр — столбик закрывается. С задержкой: сперва должен
       отработать обработчик лепры, а он смотрит на разметку, которая
       при закрытии прячется.
       Поля ввода («автор» и поиск) исключены: в них печатают, и
       схлопывать столбик под пальцем нельзя. */
    box.addEventListener('click', function (e) {
      var t = e.target;
      if (t && t.closest && (t.closest('input') || t.closest('select'))) return;
      setTimeout(function () {
        bar.classList.remove('lm-cf__open');
        more.setAttribute('aria-expanded', 'false');
        guard('cfSync', cfSync)();
      }, 0);
    });

    cfSync();
  }

  /* Подпись шеврона. Лепра помечает выбранный фильтр классом active;
     если выбран один из спрятанных, его имя и стоит на шевроне.
     Текст берём у самого узла и чистим: у полей выбора внутри лежит
     ещё и скрытый select, чей текст в textContent попадает. */
  function cfSync() {
    var bar = cfBar();
    if (!bar || !bar.dataset.lmFilters) return;
    var label = bar.querySelector('.lm-cf_label');
    var box = bar.querySelector('.lm-cf_box');
    if (!label || !box) return;

    var on = box.querySelector('a[data-key].active');
    label.textContent = on ? cfName(on) : 'фильтры';
    bar.classList.toggle('lm-cf__on', !!on);
  }

  function cfName(a) {
    /* У полей выбора видимая подпись лежит в .threshold_select_button —
       берём её, иначе в текст попадут все пункты скрытого select.
       У полей ввода своего текста нет вовсе: имя стоит в
       data-placeholder. */
    var pick = a.querySelector('.threshold_select_button');
    var text = pick ? pick.textContent : a.getAttribute('data-placeholder');
    if (!text) text = a.textContent;
    text = (text || '').replace(/\u00a0/g, ' ').replace(/\s+/g, ' ').trim();
    return text || 'фильтры';
  }

  /* Кнопка обновления догружает комментарии асинхронно, поэтому проверяем
     несколько раз: сразу, через полсекунды, через полторы и через три. */
  function watchRefreshButton() {
    var bar = document.querySelector('.b-comments_controls');
    if (!bar || bar.dataset.lmRefresh) return;
    bar.dataset.lmRefresh = '1';

    var link = bar.querySelector('a[data-key="refresh"]');
    if (!link) return;

    link.addEventListener('click', function () {
      navCache = {};                          /* списки комментариев устарели */
      [0, 500, 1500, 3000].forEach(function (ms) {
        setTimeout(guard('refreshCommentCounters', refreshCommentCounters), ms);
      });
    });
  }

  /* «Свои есть» — именно ПОКАЗАННЫЕ свои. В режиме «только новые» свои
     комментарии в разметке лежат, но скрыты, и прыгать по ним некуда:
     лепра в таком случае гасит маску, гасим и мы. Отсев по offsetParent
     уже сделан внутри commentsBy. */
  function hasMine() { return commentsBy('mine').length > 0; }

  /* Двоичный поиск: комментарии идут по документу сверху вниз, значит их
     координаты монотонны. Одиннадцать замеров вместо двух тысяч — линейный
     обход на длинном треде вешал страницу и грел телефон. */
  function findTarget(list, dir) {
    var lo = 0, hi = list.length - 1, found = null;

    while (lo <= hi) {
      var mid = (lo + hi) >> 1;
      var top = list[mid].getBoundingClientRect().top;
      if (dir > 0) {
        if (top > edge()) { found = mid; hi = mid - 1; } else lo = mid + 1;
      } else {
        if (top < land() - 10) { found = mid; lo = mid + 1; } else hi = mid - 1;
      }
    }
    if (found === null) return null;

    var el = list[found], t = el.getBoundingClientRect().top;
    if (dir > 0 && t <= edge()) return null;
    if (dir < 0 && t >= land() - 10) return null;
    return el;
  }

  function landOn(target) {
    var before = scrollTopNow();
    var wanted = before + target.getBoundingClientRect().top - land();
    wanted = Math.max(0, Math.min(wanted, Math.max(0, docHeight() - window.innerHeight)));

    scrollTopSet(wanted);

    if (scrollTopNow() === before && Math.abs(wanted - before) > 2) {
      try { target.scrollIntoView(true); } catch (e) {}
    }
    note('прыжок: было ' + Math.round(before) +
         ' стало ' + Math.round(scrollTopNow()));
  }

  /* Стрелки ходят по новым; если новых нет — по всем. Так же у лепры. */
  function jumpComment(dir) {
    var list = commentsBy('new');
    if (!list.length) return;

    var target = findTarget(list, dir);
    if (!target) return;
    landOn(target);
  }

  /* Маска ходит только по своим и только вниз, а с последнего своего
     возвращается к первому — по кругу, как на десктопе. Круг делается
     здесь, а не в findTarget: у стрелок его быть не должно, иначе
     дочитанный до конца тред начнёт перекидывать в начало сам. */
  function jumpMine() {
    var list = commentsBy('mine');
    if (!list.length) return;
    landOn(findTarget(list, 1) || list[0]);
  }

  function refreshNavState() {
    var box = document.getElementById('lm-nav');
    if (!box) return;
    /* одиночная кнопка «наверх» живёт своей жизнью: гасить её по
       отсутствию комментариев нельзя, их там и не бывает */
    if (box.classList.contains('lm-nav__top')) return;

    var mineBtn = box.querySelector('.lm-nav_mine');
    if (mineBtn) {
      var has = hasMine();
      mineBtn.disabled = !has;
      mineBtn.classList.toggle('lm-off', !has);
    }

    /* Стрелки гаснут, только когда ходить вообще не по чему. Считать на
       каждой прокрутке, есть ли цель в конкретную сторону, нельзя:
       обход DOM по прокрутке — то, из-за чего грелся телефон. */
    var empty = !commentsBy('new').length;
    sliceOf(box.querySelectorAll('.lm-nav_up, .lm-nav_down'))
      .forEach(function (b) {
        b.disabled = empty;
        b.classList.toggle('lm-off', empty);
      });
  }

  /* Кнопка «наверх» нужна на любой странице, а стрелки по комментариям —
     только там, где комментарии есть. Поэтому набор кнопок разный. */
  function ensureNav() {
    if (document.getElementById('lm-nav')) { refreshNavState(); return; }
    if (!document.body) return;

    var hasComments = !!document.getElementById('js-comments');

    var box = document.createElement('div');
    box.id = 'lm-nav';

    /* Кнопка — площадь нажатия со значком лепры внутри. Значок именно
       вложенный, а не фоновая картинка: фон пришлось бы отдавать
       отдельным файлом или data:URL, а так он остаётся разметкой и
       красится настройками. Выделение и системное меню при удержании
       запрещены стилями. */
    var makeButton = function (kind, cls, title) {
      var b = document.createElement('button');
      b.type = 'button';
      b.className = cls;
      b.appendChild(jumpIcon(kind));
      if (title) b.title = title;
      b.addEventListener('contextmenu', function (e) { e.preventDefault(); });
      return b;
    };

    var toTop = function () {
      scrollTopSet(0);
      if (window.navigator && navigator.vibrate) navigator.vibrate(10);
    };

    /* в самый низ — там форма ответа */
    var toBottom = function () {
      scrollTopSet(Math.max(0, docHeight() - window.innerHeight));
      if (window.navigator && navigator.vibrate) navigator.vibrate(10);
    };

    if (!hasComments) {
      /* страница без комментариев: одна кнопка, и та до поры скрыта */
      box.className = 'lm-nav__top';
      var top = makeButton('arrow', 'lm-nav_toTop', 'в начало страницы');
      top.addEventListener('click', function (e) {
        e.preventDefault(); e.stopPropagation();
        toTop();
      });
      box.appendChild(top);
      document.body.appendChild(box);
      watchTopButton(box);
      return;
    }

    var arrow = function (dir) {
      var b = makeButton('arrow',
        dir < 0 ? 'lm-nav_up' : 'lm-nav_down',
        dir < 0 ? 'к предыдущему комментарию (удержать — в начало)'
                : 'к следующему комментарию (удержать — в конец)');

      /* Долгое нажатие: вверх — к шапке, вниз — к форме ответа. longPress
         гасит следующий click, иначе после отпускания сработал бы и прыжок. */
      var timer = null, longPress = false;

      var startHold = function () {
        longPress = false;
        clearTimeout(timer);
        timer = setTimeout(function () {
          longPress = true;
          if (dir < 0) toTop(); else toBottom();
        }, 500);
      };
      var endHold = function () { clearTimeout(timer); };

      b.addEventListener('touchstart', startHold, { passive: true });
      b.addEventListener('touchend', endHold);
      b.addEventListener('touchcancel', endHold);
      b.addEventListener('mousedown', startHold);
      b.addEventListener('mouseup', endHold);
      b.addEventListener('mouseleave', endHold);

      b.addEventListener('click', guard('jumpComment', function (e) {
        e.preventDefault(); e.stopPropagation();
        endHold();
        if (longPress) { longPress = false; return; }
        jumpComment(dir);
      }));
      return b;
    };

    /* Средняя кнопка — не переключатель режима, а самостоятельный
       прыжок по своим комментариям сверху вниз и по кругу, как на
       десктопе. Переключатель «новые / свои» был нашей выдумкой:
       со стороны он выглядел так же, но стрелки после него ходили
       не туда, куда ждёшь. */
    var mine = makeButton('mine', 'lm-nav_mine',
                          'к следующему своему комментарию');
    mine.addEventListener('click', guard('jumpMine', function (e) {
      e.preventDefault(); e.stopPropagation();
      if (!hasMine()) return;
      jumpMine();
    }));

    box.appendChild(arrow(-1));
    box.appendChild(mine);
    box.appendChild(arrow(1));
    document.body.appendChild(box);
    refreshNavState();
  }

  /* Одиночную кнопку показываем, только когда отлистан хотя бы экран.
     Слушатель дешёвый: сравнивает два числа и переключает класс, никаких
     обходов DOM. */
  function watchTopButton(box) {
    var visible = false;

    var update = function () {
      var should = scrollTopNow() > window.innerHeight;
      if (should === visible) return;
      visible = should;
      box.classList.toggle('lm-visible', should);
    };

    update();
    window.addEventListener('scroll', update, { passive: true });
  }

  /* ============================================================
     6.1. ФОРМА ОТВЕТА
     ============================================================

     Форму по тапу «ответить» рисует скрипт лепры: вставляет
     .b-comments_reply_block последним потомком того .comment, на котором
     нажали. Никакого события об этом нет, а перехватывать её обработчик
     нельзя — он и есть механизм создания формы. Поэтому слушаем сам тап
     и потом несколько раз смотрим, появился ли узел.

     Зачем подкручивать. Комментарий, на который отвечают, чаще всего
     стоит посреди экрана или ниже; форма встаёт под ним, а снизу
     поднимается клавиатура — на поле ввода остаётся полоска в две-три
     строки, и написанное не видно целиком. Ставим верх формы под верхнюю
     кромку: всё, что между ней и клавиатурой, достаётся полю.

     Мгновенно и только мгновенно: плавная прокрутка в этом скрипте
     запрещена — она складывалась сама с собой и уносила страницу на
     десятки тысяч пикселей. */

  var replyWatched = false;

  /* Форма именно этого комментария и именно видимая. Нулевая высота
     означает, что лепра ещё не развернула контейнер (у него анимация
     max-height) — крутить по ней рано, верх ещё уедет. */
  /* Кегль полей формы с поправкой на масштаб страницы. Считаем ровно
     так же, как для поля поиска (searchFontVar), и по той же причине —
     разбор в описании CFG.formFont.

     Масштаб берём из visualViewport.scale: это отношение видимой части
     к раскладке, и меню «Аа» в Safari меняет именно его. Нет
     visualViewport — считаем масштаб единичным; хуже, чем было, от
     этого не станет.

     Нижняя граница — сам formFont, и она не формальность: когда Safari
     всё-таки приблизил страницу к полю, scale становится больше
     единицы, деление даёт тринадцать, и мы бы своими руками сделали
     поле мелким ровно в тот момент, когда этого нельзя.

     Пишем переменную ВСЕГДА, а не по касанию, как поиск. У поиска кегль
     поднимается на время и возвращается, потому что раздутое поле в
     строке ссылок выглядит чужеродно; форма комментария занимает экран
     целиком, и её полю крупный кегль только к лицу. Заодно отпадает
     вопрос «а если Safari решает про приближение до нашего касания». */
  function formFontVar() {
    var vv = window.visualViewport;
    var k = (vv && vv.scale) ? vv.scale : 1;
    formScaleSeen = k;
    var px = Math.ceil(CFG.formFont / k);
    px = Math.min(CFG.formFontMax, Math.max(CFG.formFont, px));
    formFontSeen = px;
    /* Пишем ТОЛЬКО при изменении. Слушатель висит на visualViewport, а
       это событие на iOS приходит не только от клавиатуры, но и от
       прячущейся адресной строки — то есть при обычной прокрутке.
       Масштаб между такими событиями почти никогда не меняется, и
       безусловная запись была бы записью того же значения по многу раз
       за жест. Свойство трогает раскладку, и рассчитывать на то, что
       браузер сам заметит одинаковое значение, не стоит: прокрутка у
       нас под особым присмотром именно потому, что телефон от неё
       грелся. Та же оговорка и теми же словами стоит в
       syncTopbarVars. */
    var el = document.documentElement, v = px + 'px';
    if (el.style.getPropertyValue('--lm-form-font') !== v)
      el.style.setProperty('--lm-form-font', v);
  }

  /* Числа для отчёта: какой масштаб увидели и какой кегль поставили. */
  var formScaleSeen = 1, formFontSeen = 0;

  /* Масштаб страницы меняется без перезагрузки — меню «Аа» и щипок. То
     же событие приходит и от клавиатуры, но повторная запись прежнего
     значения переменной браузеру ничего не стоит. */
  var zoomWatched = false;

  function watchZoom() {
    if (zoomWatched || !window.visualViewport) return;
    zoomWatched = true;
    window.visualViewport.addEventListener('resize',
      guard('formFontVar', formFontVar));
  }

  function replyFormIn(comment) {
    var f = comment.querySelector('.b-comments_reply_block');
    if (!f) return null;
    return f.getBoundingClientRect().height ? f : null;
  }

  function liftReply(form) {
    var before = scrollTopNow();
    var y = Math.max(0, Math.round(
      before + form.getBoundingClientRect().top - CFG.replyTop));
    /* Порог, а не безусловная запись: Safari при фокусе в поле сам
       подтягивает страницу, и лишняя запись — это лишний рывок. */
    if (Math.abs(y - before) < 3) return;
    scrollTopSet(y);
    note('форма ответа: было ' + Math.round(before) +
         ' стало ' + Math.round(scrollTopNow()));
  }

  function watchReply() {
    if (replyWatched || !CFG.replyScroll) return;
    replyWatched = true;

    document.addEventListener('click', function (e) {
      var t = e.target;
      if (!t || !t.closest) return;
      var a = t.closest('a.c_answer');
      /* Только тред открытого поста. Такая же подпись с «ответить» есть
         в ленте уведомлений, но там форма лежит в своём окне, и крутить
         под ней страницу незачем. */
      if (!a || !a.closest('#js-comments_holder')) return;
      var comment = a.closest('.comment');
      if (!comment) return;

      /* Три захода. Первый — когда лепра успела вставить разметку;
         третий — после того, как Safari закончит своё подтягивание поля
         под клавиатуру (оно приходит позже нашего и сбивает установку).
         Каждый заход сам решает, надо ли писать: если страница уже стоит
         как надо, он ничего не делает. */
      [80, 320, 700].forEach(function (ms) {
        setTimeout(guard('liftReply', function () {
          var f = replyFormIn(comment);
          if (f) liftReply(f);
        }), ms);
      });
    }, true);

    /* Второй случай — надпись «Я, пожалуй, напишу комментарий» в конце
       треда. Форма под нею разворачивается на месте, страница под неё
       не крутится, и поле оказывается под клавиатурой.

       Почему это не работало само. При обычном тапе в поле страницу
       подтягивает сам Safari — поэтому для формы, показанной сразу,
       ничего и не требовалось. А тут лепра ставит фокус в поле, пока
       обёртка ещё едет по max-height: Safari считает положение поля в
       этот момент, к концу движения оно уже другое, и подтягивание
       промахивается.

       Заходы те же три и по той же причине: первый — когда разметка на
       месте, последний — когда движение кончилось и клавиатура встала. */
    document.addEventListener('click', function (e) {
      var t = e.target;
      if (!t || !t.closest) return;
      if (!t.closest('.b-comments_controls_new_comment')) return;
      [120, 400, 850].forEach(function (ms) {
        setTimeout(guard('liftReply', function () {
          var f = newCommentForm();
          if (f) liftReply(f);
        }), ms);
      });
    }, true);
  }

  /* ============================================================
     ФОРМА НОВОГО КОММЕНТАРИЯ В КОНЦЕ ТРЕДА
     ============================================================

     Лепра показывает её раскрытой, а закрывается она крестиком, после
     чего на её месте остаётся надпись «Я, пожалуй, напишу комментарий».
     На телефоне это неудобно: развёрнутое поле в двести пикселей плюс
     панель кнопок стоят в конце каждого треда, и до навигации под ними
     приходится листать через пустую форму. Сворачиваем при загрузке —
     надпись остаётся, форма разворачивается по ней.

     Сворачиваем ЕЁ ЖЕ СПОСОБОМ: нажимаем крестик. Прямо переставить
     max-height нельзя — на нём у лепры держится анимация разворота, и
     чужие записи в него кончаются формой, застрявшей полураскрытой (это
     уже записано в общих граблях). Нажатие оставляет лепру в согласии с
     собой: и метка hidden у надписи, и высота обёртки, и её внутреннее
     состояние ставятся её собственным кодом.

     Две предосторожности вокруг нажатия.

     Первая — снимаем href. У крестика он '#', и если обработчик лепры
     ещё не навешен (а при первом проходе он обычно и не навешен),
     нажатие сработает как переход по ссылке: в адресе появится решётка.
     Это не косметика — по решётке у нас открывается отладочная панель,
     и подмена '#lmdebug' на '#' закрыла бы её на ровном месте. Без
     атрибута href ссылка перестаёт быть ссылкой, а обработчик лепры
     находит её по классу и срабатывает как ни в чём не бывало.

     Вторая — возвращаем прокрутку. Схлопывание формы укорачивает
     страницу, и если тред открыт по прямой ссылке на комментарий,
     видимое место уехало бы вниз. */

  function newCommentForm() {
    var box = document.getElementById('js-comments_add_block_bottom');
    if (!box) return null;
    var f = box.querySelector('.b-comments_reply_block');
    return (f && f.getBoundingClientRect().height) ? f : null;
  }

  function foldNewComment() {
    var box = document.getElementById('js-comments_add_block_bottom');
    var toggle = document.getElementById('js-toggle_new_thread_button');
    if (!box || !toggle) return false;
    /* Надпись видна — значит форма уже свёрнута. Ответ утвердительный:
       делать больше нечего. */
    if (!toggle.classList.contains('hidden')) return true;

    var btn = box.querySelector('.b-close_btn');
    if (!btn) return false;

    var href = btn.getAttribute('href');
    var y = scrollTopNow();
    if (href !== null) btn.removeAttribute('href');
    try { btn.click(); } catch (e) {}
    if (href !== null) btn.setAttribute('href', href);
    /* Возврат прокрутки — только если она действительно уехала.

       Сворачивание формы страницу почти никогда не двигает: форма стоит
       в самом низу треда, и укорачивается то, что НИЖЕ видимого места.
       Безусловная запись поэтому в подавляющем большинстве случаев
       возвращала прокрутку туда, где она и так стояла, — то есть была
       записью впустую.

       Впустую, но не бесплатно: при переходе «назад» браузер
       восстанавливает место не мгновенно, а своим чередом, и такая
       запись может попасть в этот промежуток — прочитать положение до
       восстановления и записать его уже после.

       Порог, а не сравнение с нулём: прокрутка гуляет на доли пикселя
       от адресной строки. Та же оговорка стоит в liftReply и по той же
       причине — лишняя запись это лишний рывок. */
    var now = scrollTopNow();
    if (Math.abs(now - y) > 2) scrollTopSet(y);

    return !toggle.classList.contains('hidden');
  }

  /* Несколько заходов: обработчики лепра вешает своим скриптом, и к
     первому проходу их обычно ещё нет. Останавливаемся, как только
     форма свернулась, — и в любом случае после последнего срока, чтобы
     не жать крестик по кругу на странице, где надписи нет вовсе. */
  function watchNewComment() {
    if (!CFG.foldNewComment || watchNewComment.on) return;
    if (!document.getElementById('js-toggle_new_thread_button')) return;
    watchNewComment.on = true;
    var tries = [0, 300, 800, 1600, 2600];
    var step = function (i) {
      if (i >= tries.length) return;
      setTimeout(function () {
        if (guard('foldNewComment', foldNewComment)()) return;
        step(i + 1);
      }, tries[i]);
    };
    step(0);
  }

  /* ============================================================
     6.5. ЭМОДЗИ В ТЁМНОЙ ТЕМЕ
     ============================================================

     Тёмная тема сделана инверсией всей страницы, а картинки и видео
     инвертируются обратно, чтобы остаться собой. С эмодзи этот приём не
     проходит: у лепры они не картинки, а обычный текст — 🌊 и 😂 лежат
     в разметке символами. Инверсия красит их наравне с буквами, и
     весёлое жёлтое лицо становится синим трупом.

     Выбрать текст правилом нельзя, поэтому обходим текстовые узлы и
     заворачиваем найденное в свой <span>, которому в тёмной теме
     возвращаем цвета обратной инверсией — тем же способом, что и
     картинкам.

     Обходим ВСЕГДА, а не только при включённой тёмной теме, и это не
     расточительность. Плёнка filter висит на правиле html.lm-dark и без
     этого класса не делает ничего, зато переключение темы не требует
     заново обойти всю страницу — а обойти пришлось бы, и на треде в
     тысячу комментариев это была бы заметная пауза ровно в тот момент,
     когда человек ждёт мгновенной смены цвета.

     Отбор — главная тонкость. В тех же страницах рядом с эмодзи стоят
     ☆ и →: это значки самой лепры, одноцветные, и они обязаны
     инвертироваться вместе со всем остальным, иначе в подписи повиснет
     светлая звезда на светлом. Поэтому берём не «все символы», а те, у
     которых цветное начертание по умолчанию: Emoji_Presentation плюс
     пиктограммы со знаком эмодзи-начертания U+FE0F. ☆ (U+2606) —
     пиктограмма, но без FE0F показывается знаком, и под образец не
     попадает. Отдельно перечислены флаги (пара региональных
     указателей) и клавиши вида 1️⃣.

     Свойства Unicode в образце требуют флага u и поддержки
     \p{...} — она есть и в Safari, и в Firefox нужных лет, но образец
     всё равно собран в try: негодный образец не должен ронять скрипт на
     первой строке. Запасной — грубый диапазон пиктограмм. */

  var EMO_RE = (function () {
    var pic = '(?:\\p{Emoji_Presentation}|\\p{Extended_Pictographic}\\uFE0F)';
    var tone = '[\\u{1F3FB}-\\u{1F3FF}]?';
    try {
      return new RegExp(
        '(?:' +
          pic + tone +
          '(?:\\u200D' + '(?:\\p{Emoji_Presentation}|\\p{Extended_Pictographic})' +
            '\\uFE0F?' + tone + ')*' +
          '|[\\u{1F1E6}-\\u{1F1FF}]{2}' +        /* флаги */
          '|[0-9#*]\\uFE0F\\u20E3' +             /* клавиши 1️⃣ */
        ')+', 'gu');
    } catch (e) {
      try { return new RegExp('[\\u{1F300}-\\u{1FAFF}]+', 'gu'); }
      catch (e2) { return null; }
    }
  })();

  /* Где ищем: тела постов и комментариев, ники, заглавия. Пынь и
     овощебазу не трогаем — так решено, и расширять список молча не
     надо: каждый новый селектор это ещё один обход документа. */
  var EMO_SEL = '.p_body, .c_body, .c_user, .b-user-login, .b-subsite_header, h1, h2';

  /* Куда не заходим. textarea и input — потому что там текст
     пользователя, и вставленный в него узел уедет в отправляемое поле;
     script и style — по общей причине; code и pre — потому что в них
     важна ровно та строка, что написана. */
  var EMO_SKIP = /^(SCRIPT|STYLE|TEXTAREA|INPUT|SELECT|OPTION|CODE|PRE)$/;

  function emojiWrap(host) {
    if (!EMO_RE || seen.emoji.has(host)) return 0;
    seen.emoji.add(host);

    /* Сперва СОБИРАЕМ подходящие узлы, потом правим. Править прямо в
       обходе нельзя: замена узла на набор узлов сбивает обходчик, и
       часть текста остаётся непросмотренной. Та же причина, по которой
       замер и запись разведены по фазам в сокращении постов. */
    var walker = document.createTreeWalker(host, NodeFilter.SHOW_TEXT, {
      acceptNode: function (n) {
        var p = n.parentNode;
        if (!p || p.nodeType !== 1) return NodeFilter.FILTER_REJECT;
        if (EMO_SKIP.test(p.tagName)) return NodeFilter.FILTER_REJECT;
        if (p.className === 'lm-emo') return NodeFilter.FILTER_REJECT;
        return NodeFilter.FILTER_ACCEPT;
      }
    });
    var list = [], n;
    while ((n = walker.nextNode())) {
      EMO_RE.lastIndex = 0;
      if (EMO_RE.test(n.nodeValue || '')) list.push(n);
    }
    if (!list.length) return 0;

    var done = 0;
    list.forEach(function (node) {
      var text = node.nodeValue, out = document.createDocumentFragment();
      var last = 0, m;
      EMO_RE.lastIndex = 0;
      while ((m = EMO_RE.exec(text))) {
        /* Пустое совпадение образцу с квантификаторами теоретически
           доступно, а зациклился бы цикл вполне практически. */
        if (!m[0].length) { EMO_RE.lastIndex++; continue; }
        if (m.index > last)
          out.appendChild(document.createTextNode(text.slice(last, m.index)));
        var span = document.createElement('span');
        span.className = 'lm-emo';
        span.textContent = m[0];
        out.appendChild(span);
        last = m.index + m[0].length;
        done++;
      }
      if (last < text.length)
        out.appendChild(document.createTextNode(text.slice(last)));
      if (node.parentNode) node.parentNode.replaceChild(out, node);
    });
    return done;
  }

  /* Счётчики для отчёта: сколько мест просмотрено и сколько эмодзи
     завёрнуто. Печатать не только значение, но и его источник — правило
     из записки; здесь источник это «за сколько заходов». */
  var emoHosts = 0, emoFound = 0;

  function fixEmoji() {
    if (!CFG.emojiKeep || !EMO_RE) return;
    var host = root();
    if (!host) return;
    var list = host.querySelectorAll(EMO_SEL);
    for (var i = 0; i < list.length; i++) {
      if (seen.emoji.has(list[i])) continue;
      emoHosts++;
      emoFound += emojiWrap(list[i]);
    }
  }

  /* ============================================================
     7. МЕДИА
     ============================================================ */

  /* Раньше здесь был [class*="media_player"] — поиск по подстроке в атрибуте,
     самый медленный вид селектора, и он выполнялся при каждой прокрутке
     по всему документу. Перечисляем классы явно. */
  var PLAYER_SEL = '.js-media_player, .b-media_player, .b-media_player_preview, ' +
                   '.b-media_player_preview_pic_holder';

  function isEmptyPlayer(el) {
    return !el.querySelector('video, iframe, img, canvas, embed, object');
  }

  /* Часть плееров лепра собирает только по клику. Имитируем тот же клик,
     но заранее — иначе на месте видео пустой прямоугольник. */
  function wakePlayer(el) {
    if (seen.poked.has(el) || !isEmptyPlayer(el)) return;
    seen.poked.add(el);
    var y = scrollTopNow();
    try {
      (el.firstElementChild || el).dispatchEvent(
        new MouseEvent('click', { bubbles: true, cancelable: true, view: window }));
    } catch (e) { /* один плеер не должен ронять остальные */ }
    if (scrollTopNow() !== y) scrollTopSet(y);
  }

  /* Размеры: video сам знает свою пропорцию, iframe — нет. */
  function fixMediaSizes() {
    document.querySelectorAll('video, audio').forEach(function (el) {
      if (seen.media.has(el)) return;
      seen.media.add(el);
      el.removeAttribute('width');
      el.removeAttribute('height');
      el.style.removeProperty('aspect-ratio');
      /* Ширина auto — по той же причине, что и в правиле выше: только
         при незаданной ширине предел по высоте ужимает ролик целиком, а
         не рисует чёрные поля по бокам. */
      el.style.setProperty('width', 'auto', 'important');
      el.style.setProperty('max-width', '100%', 'important');
      el.style.setProperty('height', 'auto', 'important');
      /* Переменная, а не число: попап настроек переписывает её на лету,
         и инлайновое объявление обязано ссылаться на неё же — иначе
         ролики остались бы со старым потолком до перезагрузки.
         ОСТОРОЖНО при проверке: jsdom теряет !important у объявлений со
         значением var() — в атрибуте остаётся голое max-height, и
         приоритет читается пустым. В браузере вес сохраняется. Само по
         себе это не страшно: ровно тот же потолок с тем же весом стоит
         и в таблице стилей, инлайн здесь только страховка для роликов,
         не попавших ни под один селектор. Но если однажды окажется, что
         проверка показывает одно, а телефон другое, — начинать надо
         отсюда. */
      el.style.setProperty('max-height',
        'var(--lm-media-max, ' + CFG.mediaCut + 'vh)', 'important');
    });

    document.querySelectorAll('iframe, embed, object').forEach(function (el) {
      if (seen.media.has(el)) return;
      seen.media.add(el);
      var w = parseFloat(el.getAttribute('width')) || parseFloat(el.style.width);
      var h = parseFloat(el.getAttribute('height')) || parseFloat(el.style.height);
      var ratio = (w && h) ? w / h : 16 / 9;
      el.removeAttribute('width');
      el.removeAttribute('height');
      el.style.setProperty('width', '100%', 'important');
      el.style.setProperty('height', 'auto', 'important');
      el.style.setProperty('aspect-ratio', ratio.toFixed(4), 'important');
    });

    document.querySelectorAll('.js-media_player, .b-media_player').forEach(function (el) {
      if (seen.media.has(el)) return;      /* без этого стили переписывались
                                              на каждом тике прокрутки */
      seen.media.add(el);
      el.style.removeProperty('aspect-ratio');
      el.style.setProperty('height', 'auto', 'important');
      el.style.setProperty('max-width', '100%', 'important');
    });
  }

  /* Многие хостинги кладут обложку рядом с роликом: /abc.mp4 -> /abc.jpg.
     Если такая есть — ставим постером: настоящее превью без загрузки видео. */
  function guessPoster(v, url) {
    if (!url || v.getAttribute('poster')) return;
    var clean = url.split('?')[0];
    var base = clean.replace(/\.(mp4|webm|mov|m4v|ogv)$/i, '');
    if (base === clean) return;

    var exts = ['.jpg', '.jpeg', '.png', '.webp'], i = 0;
    (function next() {
      if (i >= exts.length || v.getAttribute('poster')) return;
      var candidate = base + exts[i++];
      var probe = new Image();
      probe.onload = function () {
        if (!v.getAttribute('poster') && probe.naturalWidth > 1)
          v.setAttribute('poster', candidate);
      };
      probe.onerror = next;
      probe.src = candidate;
    })();
  }

  /* Очередь подготовки. Без неё прыжок по комментариям выводил в зону
     видимости десятки роликов разом: каждый начинал проигрываться,
     главный поток вставал, телефон грелся. */
  var primeQueue = [], primeBusy = 0;

  function primeNext() {
    while (primeBusy < CFG.maxParallelVideos && primeQueue.length) {
      var v = primeQueue.shift();
      if (!v.isConnected) continue;
      primeBusy++;
      doPrimeVideo(v);
    }
  }

  function primeDone() {
    if (primeBusy > 0) primeBusy--;
    primeNext();
  }

  function primeVideo(v) {
    if (v.dataset.lmPrimed) return;
    v.dataset.lmPrimed = '1';
    primeQueue.push(v);
    primeNext();
  }

  function doPrimeVideo(v) {
    v.setAttribute('playsinline', '');
    v.setAttribute('webkit-playsinline', '');
    v.setAttribute('preload', CFG.videoPreload);

    var applyRatio = function () {
      if (v.videoWidth && v.videoHeight)
        v.style.setProperty('aspect-ratio',
          v.videoWidth + ' / ' + v.videoHeight, 'important');
    };

    /* lmSelfPlay отличает наше воспроизведение от пользовательского.
       Тап по системным кнопкам плеера iOS обычными событиями до страницы
       не доходит, а событие play — доходит всегда. */
    v.lmSelfPlay = false;
    v.addEventListener('play', function () {
      if (!v.lmSelfPlay) v.dataset.lmUserPlayed = '1';
    });

    var mayTouch = function () {
      return !v.dataset.lmUserPlayed && v.paused && v.currentTime < 0.5;
    };

    v.addEventListener('loadedmetadata', function () {
      applyRatio();
      if (CFG.videoPoster === 'none') return;
      if (mayTouch() && v.currentTime < 0.01) {
        try { v.currentTime = 0.05; } catch (e) {}
      }
    });
    v.addEventListener('seeked', applyRatio);
    applyRatio();

    guessPoster(v, v.currentSrc || (v.querySelector('source') || {}).src || v.src);

    /* Обработчик лепры на контейнере плеера — это и есть механизм запуска
       видео. Глушить события с элемента нельзя: воспроизведение перестаёт
       работать вовсе. Проверено. */

    if (CFG.videoPoster !== 'frame') { primeDone(); return; }

    /* Первый кадр: коротко проигрываем без звука и сразу ставим на паузу.
       Safari на iOS не грузит видео до касания и рисует пустой прямоугольник;
       в заголовке файла (preload=metadata) картинки нет. */
    setTimeout(function () {
      if (v.readyState >= 2) { primeDone(); return; }
      if (v.dataset.lmUserPlayed || !v.paused) { primeDone(); return; }

      var wasMuted = v.muted, done = false, watchdog;

      var finish = function () {
        if (done) return;
        done = true;
        clearTimeout(watchdog);
        primeDone();
        v.removeEventListener('playing', finish);
        if (v.dataset.lmUserPlayed) {
          v.muted = wasMuted; v.lmSelfPlay = false; return;
        }
        v.pause();
        try { v.currentTime = 0.05; } catch (e) {}
        v.muted = wasMuted;
        v.lmSelfPlay = false;
        applyRatio();
      };

      /* если кадр не пришёл — освобождаем место в очереди принудительно */
      watchdog = setTimeout(finish, 4000);

      v.muted = true;
      v.lmSelfPlay = true;
      /* playing наступает раньше, чем разрешается обещание play() */
      v.addEventListener('playing', finish);

      var p = v.play();
      if (p && p.then) p.then(finish, function () {
        v.muted = wasMuted;
        v.lmSelfPlay = false;
        if (!done) { done = true; clearTimeout(watchdog); primeDone(); }
      });
    }, CFG.posterFallbackDelay);
  }

  var mediaObserver = null;

  function ensureObserver() {
    if (mediaObserver || !('IntersectionObserver' in window)) return;
    mediaObserver = new IntersectionObserver(function (entries) {
      entries.forEach(function (en) {
        if (!en.isIntersecting) return;
        mediaObserver.unobserve(en.target);
        if (en.target.tagName === 'VIDEO') primeVideo(en.target);
        else wakePlayer(en.target);
      });
    }, { rootMargin: CFG.lookAhead + 'px 0px' });
  }

  function registerMedia() {
    ensureObserver();
    var take = function (nodes, fallback) {
      nodes.forEach(function (el) {
        if (seen.obs.has(el)) return;
        seen.obs.add(el);
        if (mediaObserver) mediaObserver.observe(el);
        else fallback(el);
      });
    };
    take(document.querySelectorAll(PLAYER_SEL), wakePlayer);
    take(document.querySelectorAll('video'), primeVideo);
    guard('watchOffscreen', watchOffscreen)();
    guard('watchFree', watchFree)();
    guard('mountVideoLinks', mountVideoLinks)();
  }

  /* --- пауза уехавшего ролика --- */

  /* Наблюдатель отдельный от того, что готовит медиа. У них разные
     задачи и разные границы: тот смотрит с запасом в CFG.lookAhead
     пикселей ВОКРУГ экрана (чтобы успеть подготовить ролик заранее) и
     отписывается от элемента сразу после первого попадания. Этому нужна
     ровно кромка экрана и подписка навсегда — ролик уезжает и
     возвращается сколько угодно раз.
     Порог нулевой: событие приходит и когда ролик показался хоть одной
     строкой, и когда пропал целиком. Гасим только по второму. */
  var offObserver = null;

  function watchOffscreen() {
    if (!CFG.videoPauseOff || !('IntersectionObserver' in window)) return;
    if (!offObserver) {
      offObserver = new IntersectionObserver(function (entries) {
        entries.forEach(function (en) {
          if (en.isIntersecting) return;
          var v = en.target;
          if (v.paused) return;
          /* Своё воспроизведение при добыче первого кадра длится доли
             секунды и само кончается паузой. Влезать в него нечем: наша
             пауза пришлась бы посреди перемотки, и кадра бы не вышло. */
          if (v.lmSelfPlay && !CFG.videoPauseOwn) return;
          try { v.pause(); } catch (e) { /* один ролик не роняет остальные */ }
        });
      }, { threshold: 0 });
    }
    sliceOf(document.querySelectorAll('video')).forEach(function (v) {
      if (seen.offscreen.has(v)) return;
      seen.offscreen.add(v);
      offObserver.observe(v);
    });
  }

  /* --- выгрузка уехавших роликов --- */

  /* Наблюдатель третий по счёту, и опять свой. Первый готовит медиа с
     запасом lookAhead, второй ставит на паузу ушедшее с экрана, этот
     смотрит на границу в videoFreeAhead экранов. Свести их нельзя:
     границы разные, а IntersectionObserver помнит границу с рождения.

     Что здесь делается и чего НЕ делается. Не делается ничего с тем, что
     играет, и с тем, что человек уже запускал руками: потерять место в
     ролике, к которому он вернётся, хуже, чем погреть телефон. Не
     трогается и звук, и обработчики лепры — только источник.

     Отдельная забота — не дать странице прыгнуть. Ролик без источника
     теряет собственные размеры и схлопывается до трёхсот пикселей по
     умолчанию; если это случится ВЫШЕ окна, всё, что ниже, поедет
     вверх прямо под пальцем. Поэтому перед выгрузкой размеры коробки
     записываются в инлайновый стиль и держат место, пока источника нет.
     Это ровно та же осторожность, с какой сделан срез поста выше окна:
     там прокрутка возвращается на величину усадки. */

  var freeObs = null, backObs = null;
  var freeMargin = -1, backMargin = -1;
  var freeCount = 0, freeBack = 0;   /* для отчёта */

  function videoRelease(v) {
    if (v.dataset.lmFreed) return;
    if (!v.paused || v.dataset.lmUserPlayed === '1' || v.lmSelfPlay) return;
    var url = videoUrl(v);
    if (!url) return;

    /* Держим место. Замер один, до всех изменений.
       Ширину и высоту ставим поверх того, что положил fixMediaSizes
       (auto/auto): он размечает каждый ролик ровно один раз и обратно
       их не вернёт, поэтому спорить тут не с кем — но при возвращении
       ролика их надо снять, а не переписать на auto, иначе следующая
       выгрузка запишет уже наши же пиксели вместо настоящих. */
    var r = v.getBoundingClientRect();
    if (r.width && r.height) {
      v.style.setProperty('width', Math.round(r.width) + 'px', 'important');
      v.style.setProperty('height', Math.round(r.height) + 'px', 'important');
    }
    v.dataset.lmFreed = url;
    v.dataset.lmAt = String(v.currentTime || 0);

    /* Источник у лепры лежит в <source>, а не в атрибуте. Убираем и то,
       и другое: при обоих способах браузер должен остаться ни с чем,
       иначе load() просто начнёт качать заново. */
    sliceOf(v.querySelectorAll('source')).forEach(function (sn) {
      sn.dataset.lmSrc = sn.getAttribute('src') || '';
      sn.removeAttribute('src');
    });
    v.removeAttribute('src');
    v.setAttribute('preload', 'none');
    try { v.load(); } catch (e) { /* один ролик не роняет остальные */ }
    freeCount++;
  }

  function videoRestore(v) {
    if (!v.dataset.lmFreed) return;
    var url = v.dataset.lmFreed, at = parseFloat(v.dataset.lmAt) || 0;
    delete v.dataset.lmFreed;
    delete v.dataset.lmAt;

    sliceOf(v.querySelectorAll('source')).forEach(function (sn) {
      if (sn.dataset.lmSrc) sn.setAttribute('src', sn.dataset.lmSrc);
      delete sn.dataset.lmSrc;
    });
    if (!v.querySelector('source[src]')) v.setAttribute('src', url);
    v.setAttribute('preload', 'metadata');
    try { v.load(); } catch (e) {}

    /* Размеры отпускаем не сразу, а когда браузер снова знает свои: до
       этого момента коробка схлопнулась бы ровно так же, как при
       выгрузке, только теперь на глазах у человека. */
    var loose = function () {
      /* Возвращаем то, что было до выгрузки, а не «ничего»: разметку
         роликов делает fixMediaSizes один раз за жизнь узла, и просто
         снять свойства значило бы отдать ролик правилам лепры с её
         жёсткими width/height. */
      v.style.setProperty('width', 'auto', 'important');
      v.style.setProperty('height', 'auto', 'important');
      if (at > 0) { try { v.currentTime = at; } catch (e) {} }
    };
    if (v.readyState >= 1) loose();
    else v.addEventListener('loadedmetadata', loose, { once: true });
    freeBack++;
  }

  /* Готовность к выгрузке. Взводится один раз за страницу — по событию
     load с задержкой, а если load почему-то не придёт, то по
     сторожевому сроку от запуска. Второй путь не перестраховка: на
     странице, отданной из кэша назад-вперёд, load может не случиться
     вовсе — это уже записано у нас в start. */
  var freeReady = false;

  function armFree() {
    if (armFree.on) return;
    armFree.on = true;
    var go = function () {
      if (freeReady) return;
      freeReady = true;
      guard('watchFree', watchFree)();
    };
    window.addEventListener('load', function () {
      setTimeout(go, CFG.videoFreeWait);
    }, { once: true });
    setTimeout(go, CFG.videoFreeWait + 4000);
  }

  function watchFree() {
    if (!CFG.videoFree || !('IntersectionObserver' in window)) return;
    /* Пока страница не устоялась, не выгружаем ничего: наблюдатель
       судил бы о дальности по положению прокрутки, которого ещё нет.
       Разбор — у CFG.videoFreeWait. */
    if (!freeReady) { armFree(); return; }
    var vh = feedHeight();
    if (!vh) return;
    var far = Math.round(vh * CFG.videoFreeAhead);
    var near = Math.round(vh * CFG.videoBackAhead);

    /* Наблюдателей два: дальняя граница решает только выгружать, ближняя
       только возвращать. Между ними мёртвая полоса — см. CFG.videoBackAhead.
       Пересобираются по тем же правилам, что и наблюдатель автоподгрузки,
       и по той же причине: высота экрана на iOS гуляет вместе с
       адресной строкой, а пересборка на каждый чих грела телефон. */
    if (freeObs && Math.abs(far - freeMargin) > 200) {
      freeObs.disconnect(); freeObs = null;
    }
    if (backObs && Math.abs(near - backMargin) > 200) {
      backObs.disconnect(); backObs = null;
    }
    if (!freeObs) {
      freeMargin = far;
      freeObs = new IntersectionObserver(function (entries) {
        entries.forEach(function (en) {
          if (!en.isIntersecting) guard('videoRelease', videoRelease)(en.target);
        });
      }, { rootMargin: far + 'px 0px ' + far + 'px 0px', threshold: 0 });
    }
    if (!backObs) {
      backMargin = near;
      backObs = new IntersectionObserver(function (entries) {
        entries.forEach(function (en) {
          if (en.isIntersecting) guard('videoRestore', videoRestore)(en.target);
        });
      }, { rootMargin: near + 'px 0px ' + near + 'px 0px', threshold: 0 });
    }
    sliceOf(document.querySelectorAll('video')).forEach(function (v) {
      freeObs.observe(v);
      backObs.observe(v);
    });
  }

  /* --- прямая ссылка на файл --- */

  function videoUrl(v) {
    var src = v.currentSrc || v.getAttribute('src') || '';
    if (!src) {
      var s = v.querySelector && v.querySelector('source');
      src = s ? (s.currentSrc || s.getAttribute('src') || '') : '';
    }
    /* Заглушки не в счёт: data: — это картинка-пустышка вместо ролика,
       blob: живёт только в этой вкладке и снаружи не откроется. */
    if (!src || /^(data|blob):/i.test(src)) return '';
    return src;
  }

  function addVideoLink(el, url) {
    if (!url) return;
    /* Ставим ПОСЛЕ плеера, а не внутрь: внутри у лепры своя раскладка с
       абсолютно размеченными кнопками, и ссылка попала бы под них. А
       главное — диско режет тело поста по высоте, и всё, что лежит
       внутри плеера, уходит под срез вместе с ним. */
    var host = (el.closest && el.closest('.js-media_player, .b-media_player')) || el;
    if (!host.parentNode) return;
    if (host.nextSibling && host.nextSibling.classList &&
        host.nextSibling.classList.contains('lm-vlink')) return;

    var a = document.createElement('a');
    a.className = 'lm-vlink';
    a.setAttribute('href', url);
    a.setAttribute('target', '_blank');
    a.setAttribute('rel', 'noopener noreferrer');
    a.textContent = 'Link';
    host.parentNode.insertBefore(a, host.nextSibling);
  }

  /* Адрес ролика известен не сразу: до загрузки заголовка currentSrc
     пуст, а атрибута src у плееров лепры часто нет вовсе — она
     подставляет источник своим скриптом. Поэтому кроме прохода по
     готовым ждём ещё и loadedmetadata. */
  function mountVideoLinks() {
    if (!CFG.videoLink) return;
    sliceOf(document.querySelectorAll('video, .js-media_player iframe'))
      .forEach(function (el) {
        if (seen.vlink.has(el)) return;
        var url = el.tagName === 'IFRAME'
          ? (el.getAttribute('src') || '') : videoUrl(el);
        if (!url) {
          if (el.tagName === 'VIDEO' && !el.dataset.lmVlinkWait) {
            el.dataset.lmVlinkWait = '1';
            el.addEventListener('loadedmetadata', function () {
              guard('mountVideoLinks', mountVideoLinks)();
            }, { once: true });
          }
          return;
        }
        seen.vlink.add(el);
        guard('addVideoLink', addVideoLink)(el, url);
      });
  }

  /* ============================================================
     8. ТАП ПО КАРТИНКЕ
     По умолчанию не делает ничего: картинки у лепры полноразмерные,
     деталь смотрится щипком. Лепровский обработчик при этом всё равно
     глушится — он подменяет узел и сам прокручивает страницу, из-за чего
     экран улетал наверх. Режим 'zoom' в настройках возвращает разворот
     узких картинок на всю ширину по тапу.
     ============================================================ */

  function toggleImage(img) {
    /* запоминаем, где картинка была относительно окна, и возвращаем
       её туда же после изменения размера — иначе страница «прыгает» */
    var before = img.getBoundingClientRect().top;

    if (img.classList.contains('lm-zoomed')) {
      img.classList.remove('lm-zoomed');
      if (img.dataset.lmPrev !== undefined) {
        if (img.dataset.lmPrev) img.setAttribute('style', img.dataset.lmPrev);
        else img.removeAttribute('style');
      }
    } else {
      img.dataset.lmPrev = img.getAttribute('style') || '';
      img.classList.add('lm-zoomed');
    }

    var after = img.getBoundingClientRect().top;
    if (Math.abs(after - before) > 1)
      scrollTopSet(scrollTopNow() + (after - before));
  }

  document.addEventListener('click', function (e) {
    var t = e.target;
    if (!t || t.tagName !== 'IMG' || !t.closest) return;
    if (!t.closest('.c_body, .p_body, .dti, .comment, .post')) return;

    /* настоящую ссылку не трогаем: картинка может вести на другую страницу */
    var a = t.closest('a');
    if (a) {
      var h = a.getAttribute('href') || '';
      if (h && h !== '#' && h.slice(-1) !== '#') return;
    }

    /* Глушим лепровский зум в любом случае — он и был причиной прыжков. */
    e.preventDefault();
    e.stopPropagation();
    if (e.stopImmediatePropagation) e.stopImmediatePropagation();

    if (CFG.imageTap === 'zoom') toggleImage(t);
  }, true);

  /* ============================================================
     8.5. ДИСКО — сокращённый просмотр ленты
     ============================================================ */

  /* В ленте попадаются посты в несколько экранов, и мимо них приходится
     долго листать. Режим показывает у длинного поста только начало:
     немного текста, первую картинку, узкую полосу постепенной
     прозрачности — и целую подпись, по которой пост и опознаётся.

     Что здесь важно знать про разметку лепры. Тело поста — это
     .post > .dt > .dti.p_body, и внутри него ПЛОСКИЙ поток: голый текст,
     <br>, <a>, <b> и картинка, чаще всего одна и в самом конце. Блочных
     детей у тела нет, поэтому «отмерить текст и оставить картинку»
     обрезкой по высоте не выходит — обрезка по высоте оставляет только
     текст, а картинка уходит под срез целиком.

     Отсюда устройство: текст до первой картинки заворачивается в свою
     коробку (.lm-dsc_lead) и обрезается по числу строк, всё после
     картинки — в другую (.lm-dsc_tail) и прячется, а тело обрезается по
     общему бюджету и затягивается маской. Обёртки временные и снимаются
     при развороте: узлы возвращаются на место в прежнем порядке.

     Бюджет считается от высоты ЭКРАНА, а не от высоты поста: смысл в
     том, чтобы место под пальцем было предсказуемым, а не в том, чтобы
     ужать каждый пост на одну и ту же долю. */

  var DISCO_KEY = 'lm-disco';
  var SC_KEY = 'lm-sc';

  /* Перенос состояния со старого имени. Пока режим звался бумбулятором,
     его выключатель лежал под ключом lm-boom; после переименования
     чтение по новому ключу вернуло бы «выключено» тем, у кого он был
     включён. Переносим один раз и старую запись убираем — иначе она
     осталась бы мусором навсегда. */
  (function migrateScKey() {
    var old;
    try { old = localStorage.getItem('lm-boom'); }
    catch (e) { return; }              /* приватный режим — переносить нечем */
    if (old === null) return;
    /* Через общий слой, а не напрямую: перенесённое значение должно сразу
       лечь и в куку, иначе на соседнем поддомене оно снова потеряется. */
    if (prefGet(SC_KEY) === null) prefSet(SC_KEY, old);
    try { localStorage.removeItem('lm-boom'); } catch (e) {}
  })();

  var discoLog = [];        /* решения последнего прохода — для отчёта */
  /* Высота экрана, по которой считается бюджет. Не берётся заново на
     каждом проходе нарочно: Safari меняет innerHeight на семьдесят
     пикселей всякий раз, когда прячет и показывает адресную строку, то
     есть при обычной прокрутке. Считать по ней — значит пересобирать
     все краткопосты по десять раз за минуту. Число обновляется только
     при заметной перемене (поворот экрана, смена масштаба страницы). */
  var discoVh = 0;
  /* Сколько постов ждут своей очереди: они прошли отбор по длине, но
     стоят на экране, и резать их сейчас нельзя. Число нужно, чтобы
     знать, есть ли смысл пересчитывать после прокрутки. Ноль — и
     обработчик прокрутки не делает ничего. */
  var discoPending = 0;
  var discoCount = 0;       /* сколько постов было в ленте на прошлом проходе */
  var discoRuns = 0;        /* сколько раз отбор отработал — для отчёта */
  var discoTouched = 0;     /* сколько постов замеряли на прошлом проходе */
  var discoMs = 0;          /* сколько он занял */

  /* Сколько высоты достаётся телу поста. Подпись остаётся целой, поэтому
     её высота вычитается из бюджета, а не добавляется к нему. Считается
     в двух местах — при срезе и при проверке, не устарел ли срез, — и
     обязано давать одно и то же число, иначе посты пересобирались бы
     без конца. */
  function discoBodyMax(post) {
    var dd = post.querySelector('.dd');
    var budget = Math.round(discoVh * CFG.discoCut / 100);
    return Math.max(CFG.discoMin, budget - (dd ? dd.offsetHeight : 0));
  }

  var DISCO_MEDIA = 'img, video, iframe, object, embed, ' +
                    '.js-media_player, .b-media_player, .b-media_player_preview';

  /* Режим уплотнения — три состояния, а не два:
       0 — ничего не уплотняем
       1 — уплотняем только посты в ленте
       2 — уплотняем посты и комментарии
     Хранится тем же ключом, что и прежнее «включено / выключено», и это
     не лень: старое '1' означало ровно нынешний режим 1, а '0' — режим
     0. То есть перенос состояния не нужен вовсе, чего про ключ
     scroll-connectа сказать было нельзя.
     Всё, что не 1 и не 2, считается нулём: мусор в хранилище должен
     означать «ничего не делаем», а не «делаем непонятно что». */
  function discoMode() {
    var v = prefGet(DISCO_KEY);
    var n = parseInt(v, 10);
    return (n === 1 || n === 2) ? n : 0;
  }

  function discoRemember(mode) {
    prefSet(DISCO_KEY, String(mode));
  }

  /* Два вопроса, которые задаются в разных местах кода. Держим их
     отдельными функциями, а не сравнением с числом по месту: если
     режимов однажды станет четыре, править придётся здесь, а не в
     полутора десятках условий. */
  function discoWanted() { return discoMode() > 0; }
  function discoCommentsOn() { return discoMode() === 2; }

  /* Адреса, на которых лента есть. Разметка поста везде одна и та же
     (.post > .dt > .p_body плюс .dd), поэтому сокращение работает без
     единой правки — отличаются только адреса и обвязка вокруг ленты.
     Список закрытый, а не «всё, где есть посты»: под тем же классом
     .post лепра показывает и одиночный пост с комментариями, и выдачу
     поиска, а там сокращать нечего.
     Формы с pages/N — вторая и дальше страницы; у лепры они во
     множественном числе и без косой на конце, но одиночную и косую
     принимаем заодно, вдруг где-то встретится.
     Косая на конце везде необязательна, и это не придирка: на страницу
     постов профиля лепра ссылается и как /posts/, и как /posts — обе
     ссылки живут на одной и той же странице, и по второй кнопки не
     появлялись. */
  var FEED_PATH = new RegExp(
    '^/(pages?/\\d+/?)?$' +                          /* главная и подлепры */
    '|^/my(/pages?/\\d+)?/?$' +                      /* мои вещи */
    '|^/my/favourites(/pages?/\\d+)?/?$' +           /* избранное */
    '|^/users/[^/]+/posts(/pages?/\\d+)?/?$' +      /* посты профиля */
    '|^/users/[^/]+/favs(/pages?/\\d+)?/?$' +        /* избранное профиля */
    /* Архив. Две формы: сегодняшний день (/archive/) и конкретный
       (/archive/20260816). Косая на конце необязательна — лепра ссылается
       на соседние дни и так, и так. Комментариев в архиве нет, кнопки
       «Ещё? Ещё!» тоже — от обычной ленты он отличается только
       адресом. */
    '|^/archive/(\\d{8}/?)?$'                       /* архив */
  );

  /* Лента, а не страница поста. Признаков два, и оба нужны: контейнер
     #js-posts_holder встречается и на других страницах, а по одному
     адресу нельзя отличить ленту от страницы, которая ещё не
     догрузилась. Прочие разделы «моих вещей» — входящие, комментарии,
     Чарли — под образец не подходят и сюда не попадают. */
  function discoFeed() {
    var h = document.getElementById('js-posts_holder');
    if (h) {
      if (document.getElementById('js-comments')) return null;
      if (!FEED_PATH.test(location.pathname)) return null;
      return h;
    }
    /* Страница поста. Своего контейнера у неё нет — #js-posts_holder
       там не бывает вовсе, — поэтому возвращаем сам .post: всем, кто
       эту функцию зовёт, нужна либо истинность ответа, либо узел, за
       которым можно наблюдать. Посты для сокращения берёт не она, а
       discoPosts, и берёт их по всему содержимому.

       Автоподгрузка от расширения не страдает: она начинается с поиска
       кнопки #js-index_load_more_posts, а ни в архиве, ни на странице
       поста такой кнопки нет — feedButton вернёт null раньше, чем дело
       дойдёт до discoFeed. */
    if (!discoSolo()) return null;
    return document.querySelector('.post');
  }

  /* Страница одиночного поста с комментариями. Адрес один и на главной,
     и на подлепрах: /comments/<номер>/.
     Держим отдельным образцом, а не подмешиваем в FEED_PATH: у этой
     страницы своё поведение — пост на ней режется безусловно, см.
     оговорку про atTop в discoScan. */
  var POST_PATH = /^\/comments\/\d+\/?$/;

  function discoSolo() {
    return !!document.getElementById('js-comments') &&
           POST_PATH.test(location.pathname);
  }

  /* Посты ленты. Раньше брались прямые дети #js-posts_holder — и это
     оказалось неверно: то, что лепра догружает кнопкой «Ещё? Ещё!»,
     в этот контейнер не попадает. В отчёте было видно по номерам: после
     догрузки скрипт по-прежнему видел ровно сорок два поста, а на
     экране их было под сотню. Куда именно кладутся догруженные, знать
     не обязательно — на странице ленты всякий .post и есть пост ленты,
     а страницы, где это не так (пост с комментариями, «мои вещи»),
     отсеяны раньше, в discoFeed. Порядок querySelectorAll — порядок
     разметки, то есть тот же, что на экране. */
  function discoPosts() {
    return sliceOf((root() || document).querySelectorAll('.post'));
  }

  /* Цвет гнезда — обратный к цвету стрелки, если в настройках пусто.
     Так перекраска прыгалок тянет за собой и гнездо: пара «светлая
     стрелка — тёмное гнездо» держится сама. */
  function discoNestColor() {
    if (CFG.discoNest) return CFG.discoNest;
    var m = /(\d+)\D+(\d+)\D+(\d+)/.exec(CFG.jumpColor || '');
    if (!m) return 'rgb(45,44,43)';
    return 'rgb(' + (255 - +m[1]) + ',' + (255 - +m[2]) + ',' + (255 - +m[3]) + ')';
  }

  /* Первый узел тела, который сам является медиа или содержит его.
     Возвращается именно ребёнок тела, а не сама картинка: она бывает
     завёрнута в ссылку, и резать надо по границе ребёнка. */
  function discoFirstMedia(body) {
    var kids = sliceOf(body.childNodes);
    for (var i = 0; i < kids.length; i++) {
      var n = kids[i];
      if (n.nodeType !== 1) continue;
      if ((n.matches && n.matches(DISCO_MEDIA)) || n.querySelector(DISCO_MEDIA))
        return n;
    }
    return null;
  }

  function discoWrap(nodes, cls) {
    if (!nodes.length) return null;
    var box = document.createElement('div');
    box.className = cls;
    nodes[0].parentNode.insertBefore(box, nodes[0]);
    nodes.forEach(function (n) { box.appendChild(n); });
    return box;
  }

  function discoUnwrap(box) {
    if (!box || !box.parentNode) return;
    while (box.firstChild) box.parentNode.insertBefore(box.firstChild, box);
    box.parentNode.removeChild(box);
  }

  /* Значимое ли содержимое: пустые текстовые узлы и одинокие переводы
     строки заворачивать незачем. */
  function discoMeaty(nodes) {
    return nodes.some(function (n) {
      if (n.nodeType === 1) return true;
      return n.nodeType === 3 && n.nodeValue && n.nodeValue.trim();
    });
  }

  /* Развернуть что угодно сокращённое. Один вход на два вида: у поста и
     у комментария разные разборки, а зовущим их местам — полосе,
     стыковке — разница не нужна. */
  function discoOpen(host) {
    if (!host || !host.classList) return;
    if (host.classList.contains('lm-disco_post')) return discoOpenPost(host);
    if (host.classList.contains('lm-disco_comment'))
      return discoOpenComment(host, 'lm-disco_done');
  }

  /* Повесить разворот по тапу на стрелку. Пробовали иначе — прозрачной
     полосой во всю ширину поверх полосы прозрачности; отказались.
     Причина стоит того, чтобы её записать: полоса невидима, и когда под
     ней оказывалась картинка со светлым фоном, растворения не было
     видно вовсе — место переставало читаться как «здесь свёрнуто», и
     тап по нему выглядел случайностью. Видимая стрелка сама сообщает,
     что тут есть что развернуть; невидимая область этого не умеет.
     Кнопка, а не накладка на весь пост, по-прежнему нарочно: у поста с
     одним видео всё видимое место занимает плеер, и тап по нему обязан
     оставаться запуском воспроизведения. */
  function discoTap(nest, host) {
    nest.addEventListener('click', function (e) {
      e.preventDefault();
      e.stopPropagation();
      discoOpen(host);
    });
  }

  /* Гнездо: стрелка разворота, она же цель стыковки при включённом
     scroll-connect. В том режиме нажатий не принимает — разворачивают
     стыковкой. */
  function discoNest(post, dt) {
    var nest = post.querySelector('.lm-dsc_nest');
    if (!nest) {
      nest = document.createElement('button');
      nest.type = 'button';
      nest.className = 'lm-dsc_nest';
      nest.setAttribute('title', 'развернуть');
      var svg = svgNode('svg', {
        viewBox: '0 0 40 40', width: '40', height: '40',
        xmlns: SVG_NS, 'aria-hidden': 'true'
      });
      svg.appendChild(svgNode('polygon', {
        fill: discoNestColor(), points: JUMP_TRIANGLE
      }));
      /* Значок лежит в отдельной коробке: крутиться при стыковке будет
         она, а поворот на 180 остаётся на самом значке. */
      var spin = document.createElement('span');
      spin.className = 'lm-dsc_spin';
      spin.appendChild(svg);
      nest.appendChild(spin);
      discoTap(nest, post);
      post.appendChild(nest);
    }
    /* Середина гнезда — на середине полосы прозрачности. Отсчёт от
       низа тела, а не от бюджета: тело после обрезки текста бывает
       ниже бюджета, и полоса идёт по его настоящему краю. */
    var bottom = dt.offsetTop + dt.offsetHeight;
    nest.style.top = Math.round(bottom - CFG.discoFade / 2 - CFG.jumpSize / 2) + 'px';
    return nest;
  }

  function discoCutPost(post, was) {
    var dt = post.querySelector('.dt');
    var body = post.querySelector('.p_body');
    var dd = post.querySelector('.dd');
    if (!dt || !body) return false;

    if (!discoVh) return false;
    var bodyMax = discoBodyMax(post);

    var media = discoFirstMedia(body);
    var kids = sliceOf(body.childNodes);
    var at = media ? kids.indexOf(media) : kids.length;
    var lead = kids.slice(0, at);
    var tail = media ? kids.slice(at + 1) : [];

    /* Хвост после первой картинки заворачиваем и прячем — пока прячем:
       иначе высота текста считалась бы вместе с ним. Ниже, когда станет
       видно, добирает ли остальное до среза, часть хвоста вернётся. */
    var tailBox = discoMeaty(tail) ? discoWrap(tail, 'lm-dsc_tail lm-dsc_hide')
                                   : null;

    var leadBox = null;
    if (media && discoMeaty(lead)) {
      leadBox = discoWrap(lead, 'lm-dsc_lead');
      /* Межстрочное расстояние. Браузер отдаёт его в пикселях, но не
         всегда: при line-height: normal возвращается слово, а в наших
         же правилах оно задано множителем — и вычисленное значение
         иногда приходит множителем же. Число меньше четырёх пикселями
         быть не может, поэтому такое умножаем на кегль. */
      var cs = getComputedStyle(leadBox);
      var lh = parseFloat(cs.lineHeight);
      if (lh && lh < 4) lh = lh * (parseFloat(cs.fontSize) || 17);
      if (!lh || lh !== lh) lh = 25;                 /* normal — считать нечем */
      var textMax = Math.round(bodyMax * CFG.discoText / 100);
      if (leadBox.offsetHeight > textMax) {
        var rows = Math.max(1, Math.floor(textMax / lh));
        discoCap(leadBox, rows * lh);
        if (CFG.discoDots) {
          var dots = document.createElement('span');
          dots.className = 'lm-dsc_dots';
          dots.textContent = '\u2026';
          if (leadBox.nextSibling)
            leadBox.parentNode.insertBefore(dots, leadBox.nextSibling);
          else leadBox.parentNode.appendChild(dots);
        }
      }
    }

    /* Медиа: остаток бюджета за вычетом того, что уже занял текст.
       'crop' не делает ничего — низ уйдёт под общий срез тела. */
    if (media) {
      var used = leadBox ? leadBox.offsetHeight : 0;
      var dotsEl = post.querySelector('.lm-dsc_dots');
      if (dotsEl) used += dotsEl.offsetHeight;
      var rest = Math.max(60, bodyMax - used);
      var kind = (media.matches && media.matches('img')) || media.querySelector('img')
        ? CFG.discoMedia : CFG.discoVideo;
      if (kind === 'fit') {
        media.classList.add('lm-dsc_fit');
        discoCap(media, rest);
        /* У картинки лепра прописывает размеры прямо в style, и предел
           по высоте без снятия ширины её не ужмёт. */
        var inner = (media.matches && media.matches('img')) ? media
                                                            : media.querySelector('img, video, iframe');
        if (inner && inner !== media) {
          inner.classList.add('lm-dsc_fit');
          discoCap(inner, rest);
        }
      }
    }

    discoCap(dt, bodyMax);
    post.classList.add('lm-disco_post');

    /* Единая высота краткопостов. Текст с картинкой не всегда добирают
       до среза: картинка бывает низкая, и пост выходил на треть ниже
       соседа — при том, что дальше в нём спрятано ещё полтора экрана.
       Если до потолка осталось место, возвращаем хвост в поток: он его
       и займёт, а лишнее срежет тот же потолок. Прячем хвост только
       тогда, когда он всё равно не попал бы в видимую часть — ради
       того и пряталось, чтобы не качать невидимые картинки. */
    if (tailBox && dt.offsetHeight < bodyMax - 8)
      tailBox.classList.remove('lm-dsc_hide');

    post.__lmBudget = bodyMax;   /* по какому потолку собран этот срез */
    /* Высота экрана, при которой посчитан потолок. Нужна не для расчёта,
       а чтобы следующий проход мог пропустить этот пост, НЕ ЗАМЕРЯЯ его
       (см. look). Пока экран не изменился, потолок изменить нечему. */
    post.__lmVh = discoVh;

    /* Замер «было — стало». Считать выгоду заранее нечем: сколько
       уйдёт в хвост и сколько отрежется у текста, видно только после
       того, как это сделано. Поэтому режем, меряем и при малой выгоде
       откатываем — лишний пересчёт раскладки на пост дешевле, чем
       полоса прозрачности с гнездом на посте, где прятать нечего. */
    var after = post.getBoundingClientRect().height;
    var gain = (was || 0) - after;
    post.__lmWas = Math.round(was || 0);
    post.__lmGain = Math.round(gain);
    if (was && gain < Math.round(discoVh * CFG.discoGain / 100)) {
      discoOpenPost(post, 'lm-disco_keep');
      return false;
    }

    discoNest(post, dt);
    return true;
  }

  /* Предел высоты ставим с оглядкой на то, что там стояло раньше.
     На видео скрипт кладёт свой max-height: 80vh !important (см.
     fixMediaSizes), и простое присваивание его затирало: при развороте
     ролик оставался без потолка, а вернуть его было некому — метка
     seen.media стоит, второй раз проход к этому элементу не подойдёт.
     Прежнее значение вместе с признаком !important прячем в свойство
     узла, а не в data-атрибут: атрибут виден в разметке, а она после
     разворота обязана совпадать с исходной знак в знак. */
  function discoCap(el, px) {
    if (!el) return;
    if (el.__lmCap === undefined)
      el.__lmCap = el.style.getPropertyValue('max-height') +
        (el.style.getPropertyPriority('max-height') === 'important' ? '!' : '');
    el.style.setProperty('max-height', Math.round(px) + 'px', 'important');
  }

  /* Снять предел и вместе с ним опустевший style. Пустой атрибут сам по
     себе безвреден, но он остаётся следом на чужом узле. */
  function discoUncap(el) {
    if (!el) return;
    el.style.removeProperty('max-height');
    var kept = el.__lmCap;
    if (kept) {
      var imp = kept.slice(-1) === '!';
      el.style.setProperty('max-height', imp ? kept.slice(0, -1) : kept,
                           imp ? 'important' : '');
    }
    if (el.__lmCap !== undefined) delete el.__lmCap;
    if (!el.getAttribute('style')) el.removeAttribute('style');
  }

  function discoOpenPost(post, mark) {
    discoUncap(post.querySelector('.dt'));

    var dots = post.querySelector('.lm-dsc_dots');
    if (dots && dots.parentNode) dots.parentNode.removeChild(dots);

    var leadBox = post.querySelector('.lm-dsc_lead');
    if (leadBox) { discoUncap(leadBox); discoUnwrap(leadBox); }
    discoUnwrap(post.querySelector('.lm-dsc_tail'));

    sliceOf(post.querySelectorAll('.lm-dsc_fit')).forEach(function (m) {
      m.classList.remove('lm-dsc_fit');
      discoUncap(m);
      if (!m.getAttribute('class')) m.removeAttribute('class');
    });

    var pnest = post.querySelector('.lm-dsc_nest');
    if (pnest && pnest.parentNode) pnest.parentNode.removeChild(pnest);

    post.classList.remove('lm-disco_post');
    /* Раскрытый обратно не сворачиваем — ни сейчас, ни следующим
       проходом. Метки две, и они не про одно и то же: lm-disco_done —
       «человек развернул сам», lm-disco_keep — «срез не окупился».
       Разными их держим ради отчёта: иначе непонятно, что произошло с
       постом. Явный false означает «разобрать молча»: так пост
       раскладывают перед пересборкой под новый потолок, и никакая
       метка ему не нужна. */
    if (mark !== false) post.classList.add(mark || 'lm-disco_done');
  }

  function discoScan() {
    if (!CFG.disco) return;
    if (!document.documentElement.classList.contains('lm-disco')) return;
    var h = discoFeed();
    if (!h) return;

    var vhNow = window.innerHeight || 0;
    if (!vhNow) return;                  /* нулевая высота окна — не считаем */

    /* Пока не применился наш метатег viewport, Safari меряет страницу в
       виртуальном окне шириной 980, и высота окна выходит вдвое-втрое
       больше настоящей. Срез, посчитанный по такой высоте, оставляет от
       поста в полторы тысячи пикселей тысячу — то есть не делает
       ничего, зато навсегда получает отметку «не окупился».
       Признак неготовности — ширина окна заметно больше физической.
       Полуторный запас оставлен под уменьшенный масштаб страницы: при
       нём CSS-ширина бывает 462 при экране 393, и это ещё норма. */
    if (vhNow && window.innerWidth > screenWidth() * 1.6) {
      discoLog = ['окно ещё десктопное (' + window.innerWidth + ' при экране ' +
                  screenWidth() + ') — ждём viewport'];
      return;
    }

    if (!discoVh || Math.abs(vhNow - discoVh) > discoVh * 0.2) discoVh = vhNow;
    discoRuns++;

    var least = Math.round(discoVh * CFG.discoGain / 100);
    var budget = Math.round(discoVh * CFG.discoCut / 100);
    /* Нижняя граница длины. Считается по двум числам сразу, и берётся
       большее. Доля discoKeep — то, что задано настройкой; но пост,
       который короче бюджета плюс требуемой выгоды, всё равно не пройдёт
       проверку «сколько отдал» — его резали, мерили и раскладывали
       обратно, чтобы отказать. При discoCut 50 и discoGain 20 первая
       граница (45%) оказалась ниже второй, и полтора десятка постов
       каждый раз проходили этот бессмысленный круг, а в отчёте стояли
       как «срез не окупился», хотя дело было в длине. */
    var keep = Math.max(discoVh * CFG.discoKeep / 100, budget + least);

    /* Журнал решений последнего прохода — для отладочной панели. Пишем в
       массив, а не в data-атрибуты постов: числа нужны только отчёту, и
       засорять ими чужую разметку незачем. */
    var list = discoPosts(), lines = [];

    discoLog = ['экран: ' + vhNow + ' (в расчёте ' + discoVh + ')' +
                ' | бюджет: ' + budget +
                ' | предел выгоды: ' + least +
                ' | порог длины: ' + Math.round(keep) +
                ' (по доле ' + Math.round(discoVh * CFG.discoKeep / 100) +
                ', по выгоде ' + (budget + least) + ')',
                'постов в ленте: ' + list.length + ' | проходов отбора: ' + discoRuns];

    /* Обход СНИЗУ ВВЕРХ. Срез поста поднимает всё, что под ним, на
       несколько сотен пикселей, и при обходе сверху вниз соседи снизу
       успевали въехать в экран до того, как до них доходила очередь:
       проверка «ниже экрана» их отбрасывала, и они оставались нетронутыми
       навсегда. Снизу вверх этого не случается — сокращение нижнего
       поста верхние с места не сдвигает. */
    discoPending = 0;
    discoCount = list.length;
    /* Считаем, сколько постов проход реально трогал. Числа в отчёте
       нужны затем же, зачем и весь отчёт: если телефон снова начнёт
       греться, сразу видно, идёт ли проход по всей ленте или по
       десятку новых постов. */
    discoTouched = 0;
    var t0 = Date.now();
    for (var k = list.length - 1; k >= 0; k--) look(list[k], k);
    discoMs = Date.now() - t0;
    discoLog[1] += ' | замеряли: ' + discoTouched +
                   ' | проход занял ' + discoMs + 'мс';
    discoLog = discoLog.concat(lines.reverse());

    /* Гнёзда могли появиться или исчезнуть — наблюдателю за полосой у
       середины экрана надо об этом знать. */
    guard('scSync', scSync)();

    function look(post, i) {
      var say = function (what) {
        if (lines.length < 60) lines.push('  ' + i + ' ' + post.id + ' ' + what);
      };
      if (i < CFG.discoFirst) return say('первый — не трогаем');
      if (post.classList.contains('lm-disco_done')) return say('раскрыт вручную');

      /* Быстрый выход для уже сокращённых — ДО единого замера, и это
         главная экономия всего прохода.
         Разобрано на живом телефоне: после автоподгрузки в ленте
         оказывалось полторы сотни постов, а сам проход запускается на
         каждую пачку изменений разметки и на каждое догруженное медиа —
         за сессию их набегало четыре десятка. Каждый проход читал
         прямоугольник у КАЖДОГО поста, а между чтениями шли записи
         (срез новых), и браузер пересчитывал раскладку заново на каждом
         посте. Полторы сотни пересчётов на проход, сорок проходов —
         телефон грелся, а ответ на догрузку не успевал обработаться и
         упирался в сторожевой срок.
         Пост, сокращённый при той же высоте экрана, пересобирать
         незачем: потолок считается от неё и от высоты подписи, а обе
         величины с прошлого раза не менялись. Проверка стоит одного
         сравнения чисел вместо двух обращений к раскладке
         (getBoundingClientRect у поста и offsetHeight у подписи). */
      if (post.classList.contains('lm-disco_post') && post.__lmVh === discoVh)
        return say('сокращён (было ' + post.__lmWas +
                   ', выгода ' + post.__lmGain + ')');

      discoTouched++;
      var r = post.getBoundingClientRect();
      var want = discoBodyMax(post);
      var stale = Math.abs(want - (post.__lmBudget || 0)) > 16;

      /* Уже сокращённый пост может оказаться собран по устаревшему
         потолку: по неверной высоте окна из первого прохода, по подписи,
         которая тогда была на строку выше, или просто до поворота
         экрана. Тогда пересобираем — иначе краткопосты стоят в ленте
         разной высоты, а разнобой тут виден сразу. */
      if (post.classList.contains('lm-disco_post')) {
        if (!stale)
          return say('сокращён (было ' + post.__lmWas +
                     ', выгода ' + post.__lmGain + ')');
        var y0 = scrollTopNow(), h0 = r.height;
        discoOpenPost(post, false);
        guard('discoCutPost', discoCutPost)(post, post.__lmWas);
        var h1 = post.getBoundingClientRect().height;
        if (r.bottom <= 0 && h1 !== h0) scrollTopSet(y0 + (h1 - h0));
        return say('пересобран под потолок ' + want +
                   ' (был ' + Math.round(h0) + ', стал ' + Math.round(h1) + ')');
      }

      /* Отказ «срез не окупился» — не приговор навсегда. Размеры видео
         лепра узнаёт от сервера с запозданием, и пост, который в первом
         проходе был в двести пикселей, через несколько секунд бывает в
         семьсот; а если отказ вынесен по неверному потолку, то он и
         вовсе ни о чём. Поэтому отказ помнит и высоту поста, и потолок,
         и снимается, как только изменилось то или другое. Порог в 15% —
         чтобы не пересчитывать одно и то же от дрожания на пиксель. */
      if (post.classList.contains('lm-disco_keep')) {
        if (!stale && (!(post.__lmWas > 0) || r.height <= post.__lmWas * 1.15))
          return say('срез не окупился (было ' + post.__lmWas +
                     ', выгода ' + post.__lmGain + ')');
        post.classList.remove('lm-disco_keep');
      }

      if (!r.height || r.height < keep)
        return say('h=' + Math.round(r.height) + ' короткий');

      /* Пост под пальцем не трогаем: срез утащил бы страницу прямо во
         время чтения. Ниже экрана режем свободно — там ничего не
         сдвинется. Выше экрана тоже режем, но с возвратом прокрутки на
         ту же величину: пост целиком за верхней кромкой, и насколько он
         укоротился, ровно настолько надо подкрутить страницу назад,
         чтобы видимое осталось на месте. Без этого посты, мимо которых
         человек успел пролистать, оставались длинными навсегда — а это
         как раз те, к которым он вернётся.
         Третий случай — страница стоит в самом верху. Там срез
         безопасен даже для поста на виду: над ним ничего нет, верх его
         остаётся на месте, а поднимается только то, до чего человек
         ещё не добрался. Без этого послабления первый пост ленты
         оставался бы целым до тех пор, пока его не пролистают. */
      var below = r.top >= vhNow;
      var above = r.bottom <= 0;
      /* Страница поста — особый случай, и послабление тут не «как в
         самом верху», а безусловное. Пост на ней ровно один и стоит
         первым: под ним ничего нет, кроме комментариев, а сдвинуть
         комментарии вверх — это и есть то, ради чего сокращение
         затевалось. Без этой оговорки пост сокращался бы только при
         заходе на самый верх страницы, а при заходе по прямой ссылке
         на глубокий комментарий (страница уже проскроллена) оставался
         бы целым — то есть работал бы через раз и непонятно почему. */
      var atTop = scrollTopNow() <= 4 || discoSolo();
      if (!below && !above && !atTop) {
        discoPending++;
        return say('h=' + Math.round(r.height) + ' top=' + Math.round(r.top) +
                   ' на экране — ждём');
      }
      if (above && !CFG.discoAbove)
        return say('h=' + Math.round(r.height) + ' выше экрана — не трогаем');

      var y0 = scrollTopNow();
      var done = guard('discoCutPost', discoCutPost)(post, r.height);
      if (done && above && post.__lmGain > 0) scrollTopSet(y0 - post.__lmGain);
      say('h=' + Math.round(r.height) + (above ? ' (выше экрана)' : '') +
          (done ? ' → срезан, выгода ' + post.__lmGain
                : ' → не окупился, выгода ' + post.__lmGain));
    }
  }

  /* Размеры видео приходят от сервера с запозданием, картинки грузятся
     кто когда — и пост, который в первом проходе был коротким, через
     секунду оказывается в три экрана. Наблюдатель за узлами этого не
     ловит: узлов не добавляется, меняется только размер уже стоящего.
     Поэтому слушаем сами события загрузки и назначаем пересчёт. Обе
     ловушки в фазе перехвата: ни load у картинки, ни loadedmetadata у
     видео не всплывают. */
  var discoTimer = null;

  function discoLater() {
    if (discoTimer) return;
    discoTimer = setTimeout(function () {
      discoTimer = null;
      discoRefresh();
    }, 400);
  }

  /* Погоня за содержимым после смены адреса. Адрес меняется сразу, а
     лента приезжает ответом сервера — когда, неизвестно. Наблюдать за
     её появлением нечем: пока вкладка «посты» не открыта, контейнера
     ленты на странице нет, а вешать наблюдателя на всю страницу мы уже
     пробовали — этим захлебнулась догрузка «Ещё? Ещё!».
     Поэтому не наблюдение, а несколько попыток по расписанию: полсекунды,
     полторы, три. Стоит это трёх дешёвых проверок, зато не зависит ни от
     скорости сети, ни от того, чем лепра вставляет содержимое. */
  function discoChase() {
    if (!CFG.disco) return;
    discoRefresh();
    [500, 1500, 3000].forEach(function (ms) {
      setTimeout(function () { discoRefresh(); }, ms);
    });
  }

  /* Полный пересмотр состояния диско: где мы, нужны ли кнопки, что резать.
     Три действия всегда идут вместе и всегда в этом порядке — метка на
     <html> нужна отбору, а кнопки нужны человеку независимо от того,
     нашлось ли что резать.
     Вызывается отовсюду, где страница могла измениться, и в том числе по
     смене адреса без перезагрузки: вкладки профиля лепра переключает
     своим скриптом, адрес меняет через историю, а страницу не
     перезагружает. Отсюда и картина «тап по вкладке — кнопок нет, а
     после обновления есть»: полный обход к тому времени давно отработал
     и больше не повторялся. */
  function discoRefresh() {
    if (!CFG.disco) return;
    guard('discoSync', discoSync)();
    guard('discoMountButtons', discoMountButtons)();
    guard('discoWatchFeed', discoWatchFeed)();
    guard('feedWatch', feedWatch)();
    guard('discoScan', discoScan)();
    guard('discoScanComments', discoScanComments)();
  }

  /* Пересчёт после прокрутки. Общее правило скрипта — прокрутка не
     запускает обходов DOM, и оно остаётся в силе: обработчик сначала
     смотрит на счётчик ожидающих и при нуле выходит, не трогая ничего.
     Ждущие берутся только оттуда, где без прокрутки не обойтись: пост
     прошёл отбор, но стоит на экране, и резать его под пальцем нельзя.
     Раньше такой пост так и оставался длинным навсегда — это и было
     видно после «Ещё? Ещё!»: догруженные посты появляются ровно на
     экране, единственный проход по ним приходится на этот момент, а
     потом человек листает дальше, и пересчитывать некому.
     Задержка в 300 мс отмеряется от ПОСЛЕДНЕГО события: Safari шлёт их
     и во время инерции, так что к сроку страница уже стоит.
     Обработчик пассивный: он ничего не отменяет, и браузеру не нужно
     ждать его, чтобы продолжить прокрутку. */
  var discoScrollTimer = null;

  function discoWatchScroll() {
    if (!CFG.disco || discoWatchScroll.on) return;
    discoWatchScroll.on = true;
    window.addEventListener('scroll', function () {
      if (discoScrollTimer) clearTimeout(discoScrollTimer);
      discoScrollTimer = setTimeout(function () {
        discoScrollTimer = null;
        /* Две причины пересчитать: кто-то ждал ухода с экрана, или в
           ленте прибавилось постов — например, их догрузили туда, где
           наблюдатель их не видит. Проверка дешёвая и делается раз на
           остановку прокрутки, а не на каждое событие. */
        if (!document.documentElement.classList.contains('lm-disco')) return;
        var now = document.querySelectorAll('.post').length;
        if (!discoPending && now === discoCount) return;
        discoCount = now;
        guard('discoScan', discoScan)();
      }, 300);
    }, { passive: true });
  }

  /* Наблюдатель за лентой. Общий (watchDom) смотрит за
     #js-posts_holder, а догруженное кнопкой «Ещё? Ещё!» ложится мимо
     него — значит и добавления узлов он не видит, и пересчёта не
     назначает.
     Смотрим за самим контейнером и за его родителем, и только за
     СПИСКОМ ДЕТЕЙ, без поддерева. Поддерево здесь вредно вдвойне: в
     него попадает всё, что делают и лепра, и мы сами (срез — это тоже
     добавление узлов), и на каждую такую мелочь назначался бы пересчёт
     с замерами раскладки. Пока лепра вставляет полсотни постов с
     картинками, это превращается в постоянную драку за главный поток.
     Посты кладут либо в контейнер, либо рядом с ним, — оба места
     покрыты; а если лепра однажды спрячет их глубже, есть запасной
     путь: пересчёт после остановки прокрутки, который сверяет число
     постов. */
  function discoWatchFeed() {
    if (!CFG.disco || !('MutationObserver' in window)) return;

    /* Смена адреса без перезагрузки. Вешается один раз и живёт до конца
       страницы: вкладки профиля переключаются скриптом лепры, а адрес
       меняется через историю — кнопка «назад» и наши переходы приходят
       сюда. */
    if (!discoWatchFeed.route) {
      discoWatchFeed.route = true;
      window.addEventListener('popstate', discoChase);
      window.addEventListener('hashchange', discoChase);
      /* history.pushState события не порождает — ни одного, никакого.
         А вкладки профиля лепра переключает именно им: адрес меняется,
         содержимое подгружается, и узнать об этом снаружи нельзя. Поэтому
         оборачиваем оба метода истории: свой вызов делаем ПОСЛЕ родного,
         чтобы поведение страницы не менялось ни на йоту. */
      ['pushState', 'replaceState'].forEach(function (name) {
        var orig = history[name];
        if (typeof orig !== 'function') return;
        history[name] = function () {
          var out = orig.apply(this, arguments);
          discoChase();
          return out;
        };
      });
    }

    var h = document.getElementById('js-posts_holder');
    if (!h || h === discoWatchFeed.at) return;

    /* Контейнер ленты бывает заменён целиком — при переключении вкладок
       лепра вставляет на его место новый. Наблюдатель, повешенный на
       старый узел, при этом остаётся смотреть в никуда, поэтому держим
       ссылку на тот, за которым следим, и при подмене вешаем заново. */
    if (discoWatchFeed.obs) discoWatchFeed.obs.disconnect();
    discoWatchFeed.at = h;
    discoWatchFeed.obs = new MutationObserver(function (records) {
      for (var i = 0; i < records.length; i++)
        if (records[i].addedNodes && records[i].addedNodes.length) return discoLater();
    });
    discoWatchFeed.obs.observe(h, { childList: true });
    if (h.parentNode) discoWatchFeed.obs.observe(h.parentNode, { childList: true });
  }

  /* ------------------------------------------------------------
     АВТОПОДГРУЗКА ЛЕНТЫ
     ------------------------------------------------------------

     Устройство простое до неприличия: наблюдатель видимости смотрит за
     кнопкой «Ещё? Ещё!» с запасом в feedAhead экранов снизу. Кнопка
     вошла в эту зону — жмём её от имени человека.

     Почему наблюдатель, а не обработчик прокрутки: правило скрипта —
     прокрутка не запускает обходов DOM (телефон грелся, тапы залипали).
     IntersectionObserver ничего не считает, пока цель далеко, а когда
     близко — отдаёт готовое событие.

     Почему rootMargin пересобирается: он задаётся при создании
     наблюдателя и потом не меняется, а высота экрана меняется — поворот
     телефона, смена масштаба страницы. Держим ссылку на то значение, по
     которому наблюдатель собран, и при расхождении собираем заново.

     Отдельная тонкость — «занято». Лепра догружает посты запросом, и
     пока ответа нет, кнопка остаётся на месте и в зоне видимости.
     Второе нажатие в этот момент либо уйдёт впустую, либо догрузит одну
     и ту же страницу дважды. Поэтому после нажатия ставим замок и
     снимаем его, только когда в ленте прибавилось постов (или вышло
     время ожидания — на случай, если запрос не удался). */

  var feedObs = null;
  var feedMargin = -1;       /* запас, по которому собран наблюдатель */
  var feedVh = 0;            /* высота экрана, замороженная (см. ниже) */
  var feedBusy = false;
  var feedLoads = 0;         /* сколько раз подгрузили сами */
  var feedSeen = 0;          /* постов было на момент нажатия */
  var feedBuilds = 0;        /* сколько раз пересобирали наблюдателя */
  var feedLog = '';          /* для отчёта */

  /* Высота экрана для расчёта запаса — ЗАМОРОЖЕННАЯ, и это не мелочь.
     На iOS адресная строка прячется и показывается прямо во время
     прокрутки, и window.innerHeight гуляет на сотню пикселей туда-сюда.
     Запас считается от неё, а наблюдатель видимости пересобирается при
     изменении запаса — и первая сборка этого куска пересобирала его на
     каждом лёгком проходе, то есть на каждой пачке изменений разметки.
     Пока лепра догружала посты, изменения шли потоком: наблюдатель
     создавался и разрушался десятки раз в секунду, телефон грелся, а
     подгрузка до конца так и не доходила.
     Ровно эти же грабли уже были у режима уплотнения — там высота
     заморожена в discoVh по той же причине. Повторил ошибку, хотя она
     записана; чиню тем же способом.
     Обновляем только при изменении больше чем на пятую часть: поворот
     экрана и смена масштаба страницы такую разницу дают, а адресная
     строка — нет. */
  function feedHeight() {
    var now = window.innerHeight || 0;
    if (!now) return feedVh;
    if (!feedVh || Math.abs(now - feedVh) > feedVh * 0.2) feedVh = now;
    return feedVh;
  }

  function feedButton() {
    var b = document.getElementById('js-index_load_more_posts');
    if (!b) return null;
    /* Спрятанную не трогаем: лепра прячет её, когда лента кончилась.
       Проверяем прямоугольником, а не классом: скрывать она умеет и
       классом hidden, и стилем, и удалением — см. общие грабли. */
    if (!b.getClientRects().length) return null;
    return b;
  }

  function feedWatch() {
    if (!CFG.feedAuto || !('IntersectionObserver' in window)) return;
    if (!discoFeed()) {
      /* Ушли с ленты — наблюдатель ни к чему, а счётчик подгрузок
         начинается заново: предел feedAutoMax задуман на один заход
         чтения, а не на всю жизнь вкладки. */
      if (feedObs) { feedObs.disconnect(); feedObs = null; feedMargin = -1; }
      feedLoads = 0;
      return;
    }
    var btn = feedButton();
    if (!btn) return;

    var vh = feedHeight();
    if (!vh) return;
    var margin = Math.round(vh * CFG.feedAhead);
    /* Порог пересборки, а не точное сравнение. Даже с замороженной
       высотой запас может отличаться на пиксель-другой после поворота,
       и пересобирать наблюдателя ради этого незачем: пять экранов
       против пяти экранов и двух пикселей — одно и то же. */
    if (feedObs && Math.abs(margin - feedMargin) > 200) {
      feedObs.disconnect(); feedObs = null;
    }
    if (!feedObs) {
      feedMargin = margin;
      feedBuilds++;
      feedObs = new IntersectionObserver(function (entries) {
        for (var i = 0; i < entries.length; i++)
          if (entries[i].isIntersecting) return guard('feedPull', feedPull)();
      }, { rootMargin: '0px 0px ' + margin + 'px 0px', threshold: 0 });
    }
    /* Подписываем без всяких меток «уже подписан». Метка тут была, и она
       давала тупик: наблюдателя пересобирали, а кнопку с уже стоящей
       меткой на нового наблюдателя не подписывали — она оставалась без
       присмотра навсегда, и автоподгрузка молча кончалась.
       Повторная подписка того же элемента на того же наблюдателя по
       стандарту не делает ничего, так что беречь тут нечего. */
    feedObs.observe(btn);
  }

  function feedPull() {
    if (feedBusy) return;
    if (feedLoads >= CFG.feedAutoMax) {
      feedLog = 'предел ' + CFG.feedAutoMax + ' исчерпан — дальше руками';
      return;
    }
    var btn = feedButton();
    if (!btn) return;
    var holder = discoFeed();
    if (!holder) return;

    feedBusy = true;
    feedLoads++;
    feedSeen = discoPosts().length;
    var t0 = Date.now();
    feedLog = 'подгрузка ' + feedLoads + ' из ' + CFG.feedAutoMax +
              ' (было постов ' + feedSeen + ')';
    btn.click();

    /* Ждём прибавления постов.
       Первая сборка ждала только наблюдателем за детьми #js-posts_holder
       — и на устройстве раз за разом писала «ответа не дождались», хотя
       посты приходили. Причина в старых граблях лепры, записанных ещё в
       записке: догруженное кнопкой «Ещё? Ещё!» ложится МИМО
       #js-posts_holder. Наблюдатель за его прямыми детьми таких
       добавлений не видит вовсе, замок держался до сторожевого срока, и
       следующая подгрузка начиналась через двенадцать секунд — то есть
       не начиналась.
       Считаем поэтому так же, как их считает сам режим уплотнения:
       discoPosts() по всему содержимому. Наблюдатель остаётся быстрым
       путём, но смотрит шире — и на родителя тоже; а рядом с ним стоит
       редкий опрос как страховка от разметки, которую наблюдатель не
       охватит. Тридцать проверок за двенадцать секунд — цена, которую
       можно себе позволить один раз на подгрузку. */
    var done = false;
    var finish = function (why) {
      if (done) return;
      done = true;
      obs.disconnect();
      clearInterval(poll);
      clearTimeout(timer);
      feedBusy = false;
      feedLog += ' — ' + why + ' за ' + (Date.now() - t0) + 'мс';
      /* Кнопку лепра переставляет в конец обновлённой ленты, а иногда
         заменяет узел целиком: подписываемся заново. */
      guard('feedWatch', feedWatch)();
    };
    var check = function () {
      var n = discoPosts().length;
      if (n > feedSeen) finish('стало ' + n);
    };
    var obs = new MutationObserver(check);
    obs.observe(holder, { childList: true });
    if (holder.parentNode) obs.observe(holder.parentNode, { childList: true });
    var poll = setInterval(check, 400);
    /* Сторожевой срок. Двенадцати секунд не хватало: в отчёте с
       устройства запрос /ajax/index/moar/ занял 23.8 секунды — лепра
       отдаёт разом четыре десятка постов на четверть мегабайта, и на
       телефоне по мобильной сети это долго. Замок снимался раньше
       ответа, следующая подгрузка начиналась впустую, а прежняя
       засчитывалась в предел.
       Сорок пять секунд — не «на всякий случай», а с запасом ко вдвое
       худшему из виденного. Срок этот только страховка от запроса,
       который не вернётся вовсе: в нормальном случае замок снимает
       появление постов. */
    var timer = setTimeout(function () { finish('ответа не дождались'); },
                           CFG.feedWait);
  }

  function discoWatchMedia() {
    if (!CFG.disco || discoWatchMedia.on) return;
    discoWatchMedia.on = true;
    ['loadedmetadata', 'load'].forEach(function (ev) {
      document.addEventListener(ev, function (e) {
        var t = e.target;
        if (!t || !t.tagName) return;
        if (t.tagName !== 'IMG' && t.tagName !== 'VIDEO' && t.tagName !== 'IFRAME') return;
        if (!document.documentElement.classList.contains('lm-disco')) return;
        discoLater();
      }, true);
    });
  }

  function discoRestore() {
    sliceOf(document.querySelectorAll('.lm-disco_post')).forEach(function (p) {
      discoOpenPost(p);
    });
    sliceOf(document.querySelectorAll('.lm-disco_comment')).forEach(function (c) {
      discoOpenComment(c);
    });
    discoVh = 0;
    sliceOf(document.querySelectorAll('.lm-disco_done, .lm-disco_keep'))
      .forEach(function (p) {
        p.classList.remove('lm-disco_done');
        p.classList.remove('lm-disco_keep');
      });
  }

  /* ------------------------------------------------------------
     УПЛОТНЕНИЕ КОММЕНТАРИЕВ (режим 2)
     ------------------------------------------------------------

     Отдельный проход, а не расширение постового. Общего у них меньше,
     чем кажется: у поста бюджет считается с оглядкой на подпись под
     телом, тело делится на текст, первую картинку и хвост, а выгода
     проверяется замером «было — стало» с откатом. Комментарию всё это
     не нужно — подпись лежит отдельным узлом рядом, делить нечего, и
     решение принимается по одному числу, высоте .c_body.
     Общими остались только кирпичи: discoCap/discoUncap для потолка и
     тот же значок-стрелка.

     Тред бывает на тысячу комментариев, поэтому обход экономный: берём
     только те, что ещё не размечены, и меряем ровно один
     прямоугольник на комментарий. Скрытые фильтром (нулевой высоты)
     пропускаем — по той же причине, что и в навигации по комментариям:
     у них нет высоты, и любое решение по ней будет ложным. */

  function discoThread() {
    return document.getElementById('js-comments');
  }

  /* Бюджет тела комментария. В отличие от постового, вычитать нечего:
     подпись .c_footer — сосед .c_body, а не его содержимое. */
  function discoCommentMax() {
    return Math.max(CFG.discoMin, Math.round(discoVh * CFG.commentCut / 100));
  }

  function discoNestComment(comment, body) {
    var nest = comment.querySelector('.lm-dsc_nest');
    if (!nest) {
      nest = document.createElement('button');
      nest.type = 'button';
      /* Второй класс остался как признак «это комментарий» — им
         пользуется отчёт. Из работы scroll-connectа комментарии больше
         не исключены: стрелка и гнездо у них те же, значит и стыковка
         должна быть та же, иначе один и тот же значок в ленте и в треде
         вёл бы себя по-разному. */
      nest.className = 'lm-dsc_nest lm-dsc_nest__c';
      nest.setAttribute('title', 'развернуть');
      var svg = svgNode('svg', {
        viewBox: '0 0 40 40', width: '40', height: '40',
        xmlns: SVG_NS, 'aria-hidden': 'true'
      });
      svg.appendChild(svgNode('polygon', {
        fill: CFG.jumpColor, points: JUMP_TRIANGLE
      }));
      var spin = document.createElement('span');
      spin.className = 'lm-dsc_spin';
      spin.appendChild(svg);
      nest.appendChild(spin);
      discoTap(nest, comment);
      comment.appendChild(nest);
    }
    /* Координату здесь НЕ ставим — её считает и проставляет вызывающий,
       всем стрелкам разом. Причина в раскладке: замер положения после
       чужой записи заставляет браузер пересчитывать страницу, и в треде
       на тысячу комментариев это тысяча пересчётов подряд. */
    return nest;
  }

  function discoOpenComment(comment, mark) {
    var body = comment.querySelector('.c_body');
    discoUncap(body);
    var cnest = comment.querySelector('.lm-dsc_nest');
    if (cnest && cnest.parentNode) cnest.parentNode.removeChild(cnest);
    comment.classList.remove('lm-disco_comment');
    delete comment.__lmBudget;
    if (mark) comment.classList.add(mark);
  }

  function discoScanComments() {
    if (!CFG.disco || !discoCommentsOn()) return;
    var box = discoThread();
    if (!box) return;

    var vhNow = window.innerHeight || 0;
    if (!vhNow) return;
    /* Та же защита, что и в ленте: до применения нашего метатега Safari
       меряет страницу в виртуальном окне 980, и бюджет выходит втрое
       больше настоящего. */
    if (window.innerWidth > screenWidth() * 1.6) return;
    if (!discoVh || Math.abs(vhNow - discoVh) > discoVh * 0.2) discoVh = vhNow;

    var budget = discoCommentMax();
    /* Порог: режем только то, что отдаёт заметно больше бюджета.
       Полоса прозрачности со стрелкой на комментарии, от которого
       спрятаны две строки, — это шум, а не польза. Число берём то же,
       что и у постов (discoGain): смысл у него тот же самый, и второй
       ползунок ради него заводить незачем. */
    var least = Math.round(discoVh * CFG.discoGain / 100);

    /* Три отдельных прохода вместо одного — из-за раскладки. Тред бывает
       на тысячу комментариев, и если в одном цикле мерить высоту и тут
       же ставить потолок, каждый следующий замер заставляет браузер
       пересчитывать раскладку заново: тысяча замеров — тысяча
       пересчётов, и телефон встаёт колом на несколько секунд.
       Поэтому сначала ТОЛЬКО читаем, потом ТОЛЬКО пишем, потом снова
       читаем разом и пишем разом. Пересчётов выходит два вместо
       тысячи. */

    /* 1. Замеры. Ничего не меняем. */
    var todo = [];
    sliceOf(box.querySelectorAll('.comment')).forEach(function (c) {
      if (c.classList.contains('lm-disco_done')) return;   /* развернули сами */
      var body = c.querySelector('.c_body');
      if (!body) return;
      var cut = c.classList.contains('lm-disco_comment');
      /* Уже срезанный трогаем, только если бюджет изменился — а он
         меняется при повороте экрана и при движении ползунка. */
      if (cut && c.__lmBudget === budget) return;
      todo.push({ c: c, body: body, cut: cut, h: cut ? 0 : body.offsetHeight });
    });
    if (!todo.length) return;

    /* 2. Правки. Ничего не меряем. Разложенные обратно уходят на
       следующий проход: их настоящая высота станет известна, только
       когда потолок снят, а это уже запись. */
    var again = false;
    todo.forEach(function (t) {
      if (t.cut) { discoOpenComment(t.c); again = true; return; }
      if (!t.h) return;                   /* скрыт фильтром — решать нечего */
      if (t.h <= budget + least) return;
      discoCap(t.body, budget);
      t.c.classList.add('lm-disco_comment');
      t.c.__lmBudget = budget;
      t.done = true;
    });

    /* 3. Стрелки. Сначала считаем координаты всем сразу, потом всем
       сразу проставляем: между чтением и записью не должно быть ни
       одной чужой записи, иначе пересчёт вернётся. */
    var place = [];
    todo.forEach(function (t) {
      if (!t.done) return;
      var nest = discoNestComment(t.c, t.body);
      place.push({ nest: nest,
                   bottom: t.body.offsetTop + t.body.offsetHeight });
    });
    place.forEach(function (q) {
      q.nest.style.top =
        Math.round(q.bottom - CFG.discoFade / 2 - CFG.jumpSize / 2) + 'px';
    });

    /* Гнёзда появились — наблюдателю стыковки надо об этом знать.
       Раньше этой строки не было, и scroll-connect в треде не работал до
       первого нажатия на кнопку: гнёзда создавались, а подписать их на
       наблюдение было некому. В ленте то же самое делает discoScan, и
       оттуда ошибку было не видно. */
    guard('scSync', scSync)();

    /* Если что-то разложили обратно под новый бюджет, собрать заново
       некому: этот проход уже отработал. Назначаем следующий. */
    if (again) setTimeout(guard('discoScanComments', discoScanComments), 0);
  }

  /* ============================================================
     8.6. SCROLL-CONNECT — стыковка прокруткой
     ============================================================ */

  /* Как это устроено. Гнёзда на краткопостах в этом режиме невидимы.
     Наблюдатель видимости следит за узкой полосой вокруг середины
     экрана — её ширина задана в пикселях (discoZone), а не долей, чтобы
     не зависеть от того, поднята ли адресная строка. Пока в полосе
     пусто, не работает ничего: ни обработчиков прокрутки, ни замеров.
     Как только гнездо в неё входит, запускается покадровый цикл, и он
     читает ОДИН прямоугольник — того гнезда, что ближе к середине.
     Из расстояния до середины получается прозрачность (обоим сразу) и
     решение о стыковке.

     Почему не обработчик прокрутки: он срабатывает и там, где ничего не
     происходит, а полоса вокруг середины — это меньше пятой части
     ленты. Покадровый цикл дороже, но живёт он только внутри полосы. */

  var scObs = null;        /* наблюдатель за полосой у середины */
  var scBand = -1;         /* отступ полосы, по которому он собран */
  var scGen = 0;           /* поколение наблюдателя: метки на гнёздах */
  var scLive = [];         /* гнёзда, сейчас находящиеся в полосе */
  var scFrame = 0;         /* заявка на кадр */
  var scBusy = false;      /* идёт оборот — не мешать */
  var scTarget = null;     /* гнездо, к которому сейчас примеряемся */
  var scSince = 0;         /* когда оно вошло в допуск */
  var scShown = null;      /* кому последний раз задавали прозрачность */
  var scSeen = { dist: 0, near: 0, held: 0 };   /* для отчёта */

  /* Прозрачность и положение задаём с весом !important. Кажется лишним —
     это же инлайн, — но нет: в нашей же таблице стилей стоит правило
     `html.lm-sconnect .lm-dsc_nest { opacity: 0 !important }`, и обычное
     инлайновое объявление ему проигрывает. Именно на этом первая сборка
     и попалась: посты раскрывались стыковкой, а ни стрелки, ни гнезда,
     ни оборота видно не было — прозрачность считалась и записывалась
     исправно, только браузер её не применял. То же и с левым краем
     стрелки: в правиле стоит left: 0 !important.
     Проверять такое надо по вычисленному стилю, а не по .style — в
     .style значение лежит как ни в чём не бывало. */
  function scPut(el, prop, value) {
    if (el) el.style.setProperty(prop, value, 'important');
  }

  function scDrop(el, prop) {
    if (el) el.style.removeProperty(prop);
  }

  function scOn() {
    return CFG.disco && document.documentElement.classList.contains('lm-sconnect');
  }

  function scArrow() {
    var a = document.getElementById('lm-dsc_arrow');
    if (a) return a;
    a = document.createElement('div');
    a.id = 'lm-dsc_arrow';
    a.setAttribute('aria-hidden', 'true');
    var svg = svgNode('svg', {
      viewBox: '0 0 40 40', width: '40', height: '40',
      xmlns: SVG_NS, 'aria-hidden': 'true'
    });
    svg.appendChild(svgNode('polygon', {
      fill: CFG.jumpColor, points: JUMP_TRIANGLE
    }));
    var spin = document.createElement('span');
    spin.className = 'lm-dsc_spin';
    spin.appendChild(svg);
    a.appendChild(spin);
    (document.body || document.documentElement).appendChild(a);
    return a;
  }

  /* Собрать (или пересобрать) наблюдателя и раздать его новым гнёздам.
     Вызывается после каждого отбора: гнёзда появляются вместе со
     срезами, а полоса зависит от высоты экрана. */
  function scSync() {
    if (!scOn()) return scStop();
    if (!('IntersectionObserver' in window)) return;
    var vh = window.innerHeight || 0;
    if (!vh) return;

    var band = Math.max(0, Math.round(vh / 2 - CFG.discoZone));
    if (!scObs || band !== scBand) {
      if (scObs) scObs.disconnect();
      scBand = band;
      scGen++;
      scLive = [];
      scObs = new IntersectionObserver(function (entries) {
        entries.forEach(function (en) {
          var at = scLive.indexOf(en.target);
          if (en.isIntersecting) { if (at < 0) scLive.push(en.target); }
          else if (at >= 0) scLive.splice(at, 1);
        });
        if (scLive.length) scWake();
        else scHide();
      }, { rootMargin: -band + 'px 0px ' + -band + 'px 0px' });
    }

    sliceOf(document.querySelectorAll('.lm-dsc_nest')).forEach(function (n) {
      if (n.__lmGen === scGen) return;
      n.__lmGen = scGen;
      scObs.observe(n);
    });
  }

  function scWake() {
    if (!scFrame) scFrame = requestAnimationFrame(scTick);
  }

  /* Погасить и остановиться. Прозрачность снимаем только с того гнезда,
     которому её задавали: чужие трогать незачем, а перебирать все —
     работа на ровном месте. */
  function scHide() {
    if (scFrame) { cancelAnimationFrame(scFrame); scFrame = 0; }
    if (scShown) { scDrop(scShown, 'opacity'); scShown = null; }
    scDrop(document.getElementById('lm-dsc_arrow'), 'opacity');
    scTarget = null;
    scSince = 0;
    scSeen = { dist: 0, near: 0, held: 0 };
  }

  function scStop() {
    scHide();
    if (scObs) { scObs.disconnect(); scObs = null; scBand = -1; }
    scLive = [];
    var a = document.getElementById('lm-dsc_arrow');
    if (a && a.parentNode) a.parentNode.removeChild(a);
  }

  function scTick() {
    scFrame = 0;
    if (!scOn() || scBusy) return;
    var vh = window.innerHeight || 0;
    if (!vh || !scLive.length) return scHide();

    var mid = vh / 2, best = null, bd = 0, i, n, r, d;
    for (i = 0; i < scLive.length; i++) {
      n = scLive[i];
      if (!n.parentNode) continue;
      r = n.getBoundingClientRect();
      d = (r.top + r.height / 2) - mid;
      if (!best || Math.abs(d) < Math.abs(bd)) { best = n; bd = d; }
    }
    if (!best) return scHide();

    /* Смена цели — выдержку начинаем заново. */
    if (best !== scTarget) {
      if (scShown && scShown !== best) scDrop(scShown, 'opacity');
      scTarget = best;
      scSince = 0;
      /* Пока не увидим цель ВНЕ допуска, стыковка не взводится: иначе
         пост, оказавшийся у середины сам по себе (соседа развернули,
         страницу восстановили после перезагрузки), раскрывался бы без
         участия человека. */
      best.__lmArmed = !CFG.discoArm;
    }

    var away = Math.abs(bd);
    var near = Math.pow(Math.max(0, 1 - away / CFG.discoZone), CFG.discoCurve);
    var arrow = scArrow();
    scPut(best, 'opacity', near);
    scPut(arrow, 'opacity', near);
    /* Стрелку ставим по горизонтали ровно на гнездо: гнездо стоит у
       левого края поста, а поля страницы бывают разные. */
    r = best.getBoundingClientRect();
    scPut(arrow, 'left', Math.round(r.left) + 'px');
    scShown = best;

    if (away > CFG.discoDock) {
      best.__lmArmed = true;
      scSince = 0;
    } else if (best.__lmArmed) {
      if (!scSince) scSince = Date.now();
      else if (Date.now() - scSince >= CFG.discoHold) return scDock(best);
    }

    scSeen = {
      dist: Math.round(bd),
      near: Math.round(near * 100),
      held: scSince ? Date.now() - scSince : 0
    };
    scFrame = requestAnimationFrame(scTick);
  }

  function scDock(nest) {
    /* Ищем не «пост», а «сокращённое»: с тех пор как уплотняются и
       комментарии, гнездо может висеть и на .comment. Опираемся на
       наши собственные метки, а не на классы лепры, — они стоят ровно
       на том, что развернётся, и одинаковы для обоих видов. */
    var host = nest.parentNode;
    while (host && !(host.classList &&
                     (host.classList.contains('lm-disco_post') ||
                      host.classList.contains('lm-disco_comment'))))
      host = host.parentNode;
    if (!host) return scHide();

    scBusy = true;
    scSince = 0;
    var arrow = scArrow();
    /* Прозрачность на время оборота — полная у обоих: они уже сошлись,
       и мигание от расстояния только мешало бы смотреть. */
    scPut(nest, 'opacity', '1');
    scPut(arrow, 'opacity', '1');
    nest.classList.add('lm-dock');
    arrow.classList.add('lm-dock');

    setTimeout(function () {
      arrow.classList.remove('lm-dock');
      nest.classList.remove('lm-dock');
      scBusy = false;
      /* Разворот идёт вниз: верх поста или комментария стоит на месте,
         всё остальное уезжает за нижнюю кромку. Подкручивать ничего не
         надо. */
      guard('discoOpen', discoOpen)(host);
      scHide();
      guard('scSync', scSync)();
    }, CFG.discoSpin);
  }

  /* Навесить пару кнопок в третью колонку. Отдельным проходом, а не при
     сборке навигационной штуки, и вот почему. Сборка идёт в первом же
     проходе, а он случается сразу, не дожидаясь конца разбора страницы:
     шапка к этому времени уже разобрана, а контейнер ленты — он лежит
     заметно ниже — ещё нет. Признак «это лента» тогда даёт ложное нет,
     кнопки не появляются, и второго шанса у них не было: навигационная
     штука собирается один раз.
     Ловилось это плохо: на стенде страница разобрана целиком до запуска
     скрипта, и гонки там не бывает вовсе — только на устройстве, и не
     на всякой странице, а на той, где разметка до ленты длиннее.
     Проход идёт при каждом полном обходе и сам чинит обе стороны: на
     ленте кнопки появятся, как только контейнер разобран, а на прочих
     страницах уберутся, если успели встать. */
  /* Где кнопкам место. Не там же, где работает сокращение, и нарочно:
     профиль — это одна страница с вкладками, которые лепра переключает
     своим скриптом, не перезагружая её. Ловить момент появления ленты
     мы, конечно, ловим, но полагаться на одну эту ловлю оказалось
     ненадёжно: пока не открыта вкладка «посты», ленты нет вовсе, и
     наблюдать не за чем. Поэтому на всех вкладках профиля кнопки стоят
     сразу — нажать их можно и до открытия ленты, состояние всё равно
     общее на весь сайт, и на вкладке «посты» режим окажется уже
     включённым. */
  /* Где показывать пиктограммы. К ленте и профилю добавился тред: режим
     2 работает именно там, и переключать его, не видя комментариев,
     было бы гаданием. */
  function discoButtonsFit() {
    return !!discoFeed() || !!discoThread() ||
           /^\/users\/[^\/]+(\/|$)/.test(location.pathname);
  }

  function discoMountButtons() {
    if (!CFG.disco) return;
    var extra = document.querySelector('.lm-navthing_extra');
    if (!extra) return;
    var pad = extra.querySelector('.lm-disco_pad');
    if (!discoButtonsFit()) {
      if (pad && pad.parentNode) pad.parentNode.removeChild(pad);
      return;
    }
    if (pad) return;
    extra.insertBefore(discoButtons(), extra.firstChild);
  }

  /* Класс на <html> — единственный признак включённого режима для CSS.
     Ставится только на ленте: на прочих страницах кнопок нет, и метка
     там означала бы включённое, но неработающее.
     lm-sconnect без lm-disco не бывает: сокращать нечего, и стыковать не с
     чем. Кнопка при этом остаётся нажатой — состояние помнится, и как
     только включат DISCO, микрогеймификация окажется на месте. */
  function discoSync() {
    if (!CFG.disco) return;
    var on = discoWanted() && !!discoFeed();
    document.documentElement.classList.toggle('lm-disco', on);
    /* Метка scroll-connectа теперь ставится и в треде: стыковка работает
       и на сокращённых комментариях. Условие — есть ЧТО стыковать: либо
       уплотнённая лента, либо уплотнённые комментарии. */
    var cOn = discoCommentsOn() && !!discoThread();
    document.documentElement.classList.toggle('lm-sconnect',
      (on || cOn) && scWanted());
    /* Метка треда — своя и независимая. Раньше здесь стояло, что двух
       классов разом не будет никогда: лента и комментарии на одной
       странице не встречались, потому что discoFeed прямо отказывался
       считать лентой страницу с #js-comments. Теперь отказ снят —
       одиночный пост на странице комментариев сокращается наравне с
       лентой, — и оба класса на такой странице стоят вместе.
       Порознь их держать тем более важно: правила разные, и «уплотнён
       пост» с «уплотнён комментарий» не должны доставаться друг другу
       по недосмотру. */
    document.documentElement.classList.toggle('lm-disco_c', cOn);
  }

  function scWanted() {
    return prefGet(SC_KEY) === '1';
  }

  function scRemember(on) {
    prefSet(SC_KEY, on ? '1' : '0');
  }

  /* Три пиктограммы вместо кнопки «disco» и кнопка scroll-connect под
     ними. Пиктограммы нарисованы в том же ключе, что и значки типа
     ленты у лепры: квадрат 26 со скруглением, внутри тёмные полосы,
     выбранный подсвечен серым rgb(220,218,218) — её же оттенком.
     Смысл рисунка прямой: верхняя половина значка — пост, нижняя —
     комментарий. Целая полоса значит «показывается целиком», пара
     тонких — «уплотнено». Отсюда и три картинки: две целых, целая с
     парой, две пары.
     Рисуем прямоугольниками, а не текстом: подписи в 26 пикселей не
     помещаются, а в третьей колонке и без того тесно. Смысл значков
     объясняет подсказка по тапу (см. bindHint). */
  /* Заливка полос. Не чёрная: рядом лежит выбранный значок с подложкой
     rgb(220,218,218), и чёрные полосы на ней выглядят чернильной
     кляксой, тогда как значки ленты у лепры нарисованы мягче. Но и не
     светлее подложки — иначе на невыбранных значках (у них подложки
     нет, белый фон страницы) полосы поплыли бы. Тёмно-серый ровно между
     этими двумя требованиями. */
  var DISCO_INK = 'rgb(140,140,140)';

  var DISCO_ICONS = [
    { mode: 0, rows: [[3, 8], [13, 8]],
      hint: 'ничего не уплотняем' },
    { mode: 1, rows: [[3, 3.5], [7.5, 3.5], [13, 8]],
      hint: 'уплотняем только посты' },
    { mode: 2, rows: [[3, 3.5], [7.5, 3.5], [13, 3.5], [17.5, 3.5]],
      hint: 'уплотняем посты и комментарии' }
  ];

  function discoIcon(rows) {
    var svg = svgNode('svg', {
      viewBox: '0 0 24 24', width: '24', height: '24',
      xmlns: SVG_NS, 'aria-hidden': 'true'
    });
    rows.forEach(function (r) {
      svg.appendChild(svgNode('rect', {
        x: '3', y: String(r[0]), width: '18', height: String(r[1]),
        rx: '1', fill: DISCO_INK
      }));
    });
    return svg;
  }

  function discoButtons() {
    var pad = document.createElement('div');
    pad.className = 'lm-disco_pad';

    var row = document.createElement('div');
    row.className = 'lm-disco_modes';
    var picks = DISCO_ICONS.map(function (d) {
      var b = document.createElement('button');
      b.type = 'button';
      b.className = 'lm-disco_mode';
      b.dataset.lmMode = String(d.mode);
      b.appendChild(discoIcon(d.rows));
      bindHint(b, d.hint);
      row.appendChild(b);
      return b;
    });

    var sc = document.createElement('button');
    sc.type = 'button';
    sc.className = 'lm-disco_btn lm-disco_btn__sc';
    sc.textContent = 'scroll-connect';

    function show() {
      var m = discoMode();
      picks.forEach(function (b) {
        var on = parseInt(b.dataset.lmMode, 10) === m;
        b.classList.toggle('lm-on', on);
        b.setAttribute('aria-pressed', on ? 'true' : 'false');
      });
      /* В режиме «ничего не уплотняем» стыковать не с чем: гнёзд нет
         вовсе. Кнопку в этом положении гасим и нажатой не показываем —
         иначе она обещает работу, которой не будет. Само состояние в
         памяти при этом сохраняется: вернули уплотнение — вернулся и
         scroll-connect таким, каким его оставили.
         От РЕЖИМА кнопка зависит, от вида страницы — нет: в режимах 1 и
         2 она одинаково доступна и в ленте, и в треде. */
      var live = m > 0 && scWanted();
      sc.disabled = (m === 0);
      sc.classList.toggle('lm-on', live);
      sc.setAttribute('aria-pressed', live ? 'true' : 'false');
    }

    picks.forEach(function (b) {
      b.addEventListener('click', function (e) {
        e.preventDefault();
        var was = discoMode(), now = parseInt(b.dataset.lmMode, 10);
        if (was === now) return;
        discoRemember(now);
        show();
        /* Разбирать раньше, чем собирать: при переходе 2 → 1 надо снять
           срезы с комментариев, а при 1 → 0 — со всего сразу. Порядок
           обратный ломался бы на переходе 2 → 1: пересборка постов
           прошла бы, а комментарии остались бы срезанными. */
        guard('discoRestore', discoRestore)();
        guard('discoSync', discoSync)();
        if (now > 0) {
          guard('discoScan', discoScan)();
          guard('discoScanComments', discoScanComments)();
        }
        guard('scSync', scSync)();
      });
    });

    sc.addEventListener('click', function (e) {
      e.preventDefault();
      scRemember(!scWanted());
      show();
      guard('discoSync', discoSync)();
      guard('scSync', scSync)();
    });

    show();
    pad.appendChild(row);
    pad.appendChild(sc);
    return pad;
  }

  /* ============================================================
     9. ДИАГНОСТИКА
     Три тапа по левому верхнему углу или #lmdebug в адресе.
     Выключается через CFG.debug.
     ============================================================ */

  function describe(el) {
    var s = el.tagName.toLowerCase();
    if (el.id) s += '#' + el.id;
    var c = el.getAttribute && el.getAttribute('class');
    if (c) s += '.' + c.trim().split(/\s+/).slice(0, 4).join('.');
    return s;
  }

  function positionedParent(el) {
    var n = el.parentElement, d = 0;
    while (n && d < 8) {
      var pos = getComputedStyle(n).position;
      if (pos !== 'static') return describe(n) + ' (' + pos + ')';
      n = n.parentElement; d++;
    }
    return '\u2014';
  }

  function reportOverflow(L) {
    L.push('--- вылезает за экран ---');
    var bad = scanOverflow(true);
    if (!bad.length) L.push('(ничего)');
    bad.slice(0, 40).forEach(function (b) {
      L.push(describe(b.el) + '  L=' + Math.round(b.r.left) +
             ' R=' + Math.round(b.r.right) + ' w=' + Math.round(b.r.width));
    });
  }

  /* Всё, что всплывает поверх страницы: подложки, модальные окна,
     подсказки. Обычные разделы отчёта их не видят: они ходят по
     содержимому страницы, а окно живёт своей жизнью — и, как выяснилось,
     не обязательно рядом с содержимым.
     Показываем цепочку предков (чьё окно — лепры, капчи, расширения),
     инлайновые стили (в них пишут ширину и координаты) и потомков,
     вышедших за края: при рамке шириной ровно в экран виновато
     содержимое, а оно статическое и в перечень слоёв не попадает. */
  function reportOverlays(L) {
    var W = document.documentElement.clientWidth, n = 0;

    L.push('ширина окна ' + W);

    eachLayer(function (el, r) {
      if (n >= 12) return;
      n++;
      var cs = getComputedStyle(el);
      L.push('');
      L.push('[' + n + '] ' + describe(el) +
             '  pos=' + cs.position + ' z=' + cs.zIndex +
             ' L=' + Math.round(r.left) + ' R=' + Math.round(r.right) +
             ' T=' + Math.round(r.top) + ' B=' + Math.round(r.bottom) +
             ' w=' + Math.round(r.width) + ' h=' + Math.round(r.height) +
             (r.right > W + 1 || r.left < -1 ? '  ЗА ЭКРАНОМ' : ''));

      var path = [], p = el.parentElement, i = 0;
      while (p && p !== document.body && i++ < 4) {
        path.push(describe(p));
        p = p.parentElement;
      }
      L.push('   в: ' + (path.length ? path.join(' < ') : 'прямо в body'));

      var st = (el.getAttribute('style') || '').replace(/\s+/g, ' ').trim();
      if (st) L.push('   style="' + st.slice(0, 200) + '"');

      var out = [];
      sliceOf(el.querySelectorAll('*')).forEach(function (k) {
        if (out.length > 12) return;
        var kr = k.getBoundingClientRect();
        if (!kr.width && !kr.height) return;
        if (kr.right <= W + 1 && kr.left >= -1) return;
        out.push('     ' + describe(k) +
                 '  L=' + Math.round(kr.left) + ' R=' + Math.round(kr.right) +
                 ' w=' + Math.round(kr.width) +
                 ' pos=' + getComputedStyle(k).position);
      });
      if (out.length) {
        L.push('   содержимое за краями экрана:');
        out.forEach(function (s) { L.push(s); });
      }

      L.push('   разметка: ' +
             el.innerHTML.replace(/ on[a-z]+="[^"]*"/g, '')
                         .replace(/\s+/g, ' ').trim().slice(0, 700));
    });

    if (!n) L.push('(слоёв нет — окно надо открыть ДО отчёта)');
  }

  /* Чем страница догружает содержимое. Понадобилось для пыни: ленту
     уведомлений строит скрипт лепры уже в браузере, и в ответе сервера
     её нет — значит, она приходит отдельным запросом, а каким именно,
     из сохранённой страницы не узнать (скрипты в MHTML не попадают).
     Хуки на fetch и XMLHttpRequest тут не годятся: скрипт может жить в
     отдельном окружении и до вызовов лепры не дотянуться. Хронология
     ресурсов общая на весь документ и видна всем. */
  function reportNetwork(L) {
    L.push('', '--- сетевые запросы ---');
    var list = [];
    try { list = performance.getEntriesByType('resource') || []; } catch (e) {}
    var n = 0;
    list.forEach(function (r) {
      if (n >= 30) return;
      if (r.initiatorType !== 'xmlhttprequest' && r.initiatorType !== 'fetch') return;
      n++;
      L.push(r.name.replace(/^https?:\/\/(www\.)?/, '').slice(0, 110) +
             '  ' + Math.round(r.duration) + 'мс' +
             (r.transferSize ? ' ' + Math.round(r.transferSize / 1024) + 'КБ' : ''));
    });
    if (!n) L.push('(запросов не было)');

    L.push('', '--- перехвачено (метод и заголовки) ---');
    /* Раньше на пустом списке тут стояло «скрипт живёт в отдельном
       окружении». Это враньё: чаще всего список пуст потому, что на
       странице все запросы шумовые и отсеяны, либо потому, что нужный
       ушёл раньше, чем встал хук (так уходит /api/replacements/).
       Поэтому теперь показываем сами числа, а выводы делаем по ним. */
    L.push('хук на fetch: ' +
             (window.fetch && window.fetch.lmHooked ? 'стоит' : 'НЕТ') +
           ' | прошло через хук: ' + NET_SEEN +
           ' | отсеяно как шум: ' + NET_NOISE);
    if (!NET.length)
      L.push('(ничего по существу — к своему API лепра ходит на странице',
             ' уведомлений, а из окна пыни запросы видны разделом ниже)');
    NET.slice(0, 40).forEach(function (s) { L.push(s); });

    /* Окно пыни — отдельное окружение, наш перехват в главном окне его
       вызовов не видит. Внутри работает свой писец, складывающий строки
       сюда. Ради этого раздела всё и затевалось: он показывает, чем
       лепра зовёт своё API и что при этом отмечает прочитанным. */
    L.push('', '--- перехвачено в окне пыни ---');
    var fr = [], ran = 0;
    try { fr = window.lmPynNet || []; } catch (e) {}
    try { ran = window.lmPynRan || 0; } catch (e) {}
    L.push('окно создавалось: ' + pynFrames +
           ' | скрипт внутри запускался: ' + ran +
           ' | записано строк: ' + fr.length);
    if (!fr.length && pynFrames && !ran)
      L.push('окно открывали, а скрипт в нём не запускался — значит',
             'менеджер юзерскриптов внедряет только в верхний фрейм.',
             'Проверить у него настройку про фреймы.');
    if (!fr.length && !pynFrames)
      L.push('(окно пыни в этой вкладке ещё не открывали)');
    fr.slice(0, 40).forEach(function (s) { L.push(s); });
  }

  function reportFloats(L) {
    L.push('', '--- плавающие колонки ---');
    var n = 0;
    root().querySelectorAll('div, aside, section, ul').forEach(function (el) {
      if (n >= 10) return;
      var cs = getComputedStyle(el);
      if (cs.cssFloat === 'none') return;
      var r = el.getBoundingClientRect();
      if (r.width < 80) return;
      n++;
      L.push(describe(el) + ' float=' + cs.cssFloat +
             ' w=' + Math.round(r.width) + ' css-width=' + cs.width);
    });
    if (!n) L.push('(нет)');
  }

  /* Инлайновый элемент, текст которого перенёсся на несколько строк, отдаёт
     из getBoundingClientRect объединяющий прямоугольник: он накрывает и то,
     что стоит слева от первой строки, и то, что справа от последней. Отсюда
     ложные «наложения» на ровном месте. Поэтому сравниваем не габарит, а
     строчные фрагменты. */
  function fragments(el, r) {
    var list = el.getClientRects();
    if (!list || list.length < 2) return [r];
    var out = [];
    for (var i = 0; i < list.length && i < 16; i++) {
      if (list[i].width > 1 && list[i].height > 1) out.push(list[i]);
    }
    return out.length ? out : [r];
  }

  function lines(c) { return c.f.length > 1 ? ' (строк: ' + c.f.length + ')' : ''; }

  function rectsArea(rs) {
    var s = 0;
    for (var i = 0; i < rs.length; i++) s += rs[i].width * rs[i].height;
    return s;
  }

  /* Лепра прячет формы покупки не классом, а высотой: контейнеру ставится
     height: 0 с overflow: hidden, и содержимое обрезается. Прямоугольники
     у обрезанного содержимого остаются прежние, поэтому в отчёте оно
     исправно «перекрывало» соседей — треть страницы магазина уходила на
     наложения, которых глазом не видно. Считаем невидимым всё, что лежит
     внутри обрезающего предка нулевой высоты. */
  function insideCollapsed(el) {
    for (var p = el.parentElement; p && p !== document.body; p = p.parentElement) {
      if (p.clientHeight > 0 && p.clientWidth > 0) continue;
      var cs = getComputedStyle(p);
      if (cs.overflow === 'hidden' || cs.overflowY === 'hidden' ||
          cs.overflowX === 'hidden') return true;
    }
    return false;
  }

  /* Скрытое прозрачностью тоже даёт ложные наложения: у лепры меню
     отписок в каждом уведомлении — это абсолютно позиционированный
     список с opacity: 0 и visibility: hidden, который раскрывается
     наведением. Прямоугольники у него настоящие, и в отчёте он
     исправно перекрывал подписи всех уведомлений подряд. */
  function insideInvisible(el) {
    if (getComputedStyle(el).visibility === 'hidden') return true;
    for (var p = el; p && p !== document.body; p = p.parentElement) {
      if (parseFloat(getComputedStyle(p).opacity) === 0) return true;
    }
    return false;
  }

  /* Наложения ищем попарно среди «листьев» — элементов без вложенных блоков.
     Самый частый вид поломки при переносе десктопной вёрстки, и на глаз
     заметен не всегда. */
  function reportOverlaps(L) {
    L.push('', '--- наложения ---');
    var cand = [];
    var all = root().querySelectorAll(
      'a, span, label, input, button, select, li, p, h1, h2, h3, strong, em, div');

    for (var i = 0; i < all.length && cand.length < 300; i++) {
      var el = all[i];
      if (el.closest('#lm-debug') || el.closest('.plupload')) continue;
      if (el.querySelector('a, span, label, input, button, select, div')) continue;
      var r = el.getBoundingClientRect();
      if (r.width < 4 || r.height < 4) continue;
      if (r.bottom < -2000 || r.top > window.innerHeight + 4000) continue;
      if (insideCollapsed(el)) continue;
      if (insideInvisible(el)) continue;
      cand.push({ el: el, r: r, f: fragments(el, r) });
    }

    var found = 0;
    for (var a = 0; a < cand.length && found < 12; a++) {
      for (var b = a + 1; b < cand.length && found < 12; b++) {
        var A = cand[a], B = cand[b];
        if (A.el.contains(B.el) || B.el.contains(A.el)) continue;
        /* дешёвая отсечка по габаритам: если не пересекаются они,
           не пересекутся и фрагменты */
        var w = Math.min(A.r.right, B.r.right) - Math.max(A.r.left, B.r.left);
        var h = Math.min(A.r.bottom, B.r.bottom) - Math.max(A.r.top, B.r.top);
        if (w <= 1 || h <= 1) continue;

        var inter = 0;
        for (var i = 0; i < A.f.length; i++) {
          for (var j = 0; j < B.f.length; j++) {
            var fw = Math.min(A.f[i].right, B.f[j].right) -
                     Math.max(A.f[i].left, B.f[j].left);
            var fh = Math.min(A.f[i].bottom, B.f[j].bottom) -
                     Math.max(A.f[i].top, B.f[j].top);
            if (fw > 1 && fh > 1) inter += fw * fh;
          }
        }
        if (inter <= 1) continue;
        var small = Math.min(rectsArea(A.f), rectsArea(B.f));
        if (inter < small * 0.3) continue;
        found++;
        L.push(describe(A.el) + lines(A) + '  [' +
               (A.el.textContent || '').trim().slice(0, 20) + ']');
        L.push('   \u2195 перекрывает \u2195');
        L.push(describe(B.el) + lines(B) + '  [' +
               (B.el.textContent || '').trim().slice(0, 20) + ']');
        L.push('   pos: ' + getComputedStyle(A.el).position + ' / ' +
               getComputedStyle(B.el).position);
        L.push('   предок A: ' + positionedParent(A.el));
        L.push('   предок B: ' + positionedParent(B.el));
        L.push('');
      }
    }
    if (!found) L.push('(наложений не найдено)');
  }

  function reportMedia(L) {
    L.push('', '--- видео ---');
    var vids = root().querySelectorAll('video');
    L.push('всего video: ' + vids.length);

    /* Сводка по всем роликам сразу. Шести подробных строк хватало, пока
       лента была одностраничной; с автоподгрузкой их стало четыре
       десятка, и вопрос «греется ли телефон из-за медиа» по шести
       первым не решается.
       Главное здесь — сколько данных лежит в буферах. preload=metadata
       обещает, что дальше заголовка ролик не качается, но обещание это
       Safari трактует свободно: он дотягивает до готовности к
       воспроизведению, и сорок таких пайплайнов работают все разом.
       Печатаем распределение по готовности, суммарную длину буферов и
       сколько роликов сейчас за пределами экрана: если буферы набиты у
       тех, кого не видно, — виновник найден, и лечится это выгрузкой
       уехавших, а не уменьшением ленты. */
    var vh0 = window.innerHeight || 0;
    var rs = [0, 0, 0, 0, 0], buffered = 0, withBuf = 0, off = 0, playing = 0;
    var netIdle = 0, netLoad = 0;
    sliceOf(vids).forEach(function (v) {
      rs[Math.min(4, v.readyState || 0)]++;
      if (!v.paused) playing++;
      if (v.networkState === 2) netLoad++;
      if (v.networkState === 1) netIdle++;
      try {
        var b = v.buffered, sec = 0;
        for (var j = 0; j < b.length; j++) sec += b.end(j) - b.start(j);
        if (sec > 0) { withBuf++; buffered += sec; }
      } catch (e) {}
      var rr = v.getBoundingClientRect();
      if (rr.bottom < 0 || rr.top > vh0) off++;
    });
    L.push('  готовность: 0=' + rs[0] + ' 1=' + rs[1] + ' 2=' + rs[2] +
           ' 3=' + rs[3] + ' 4=' + rs[4] +
           ' | играет: ' + playing + ' | за экраном: ' + off);
    L.push('  в буферах: ' + Math.round(buffered) + ' с у ' + withBuf +
           ' роликов | сеть: качают ' + netLoad + ', простаивают ' + netIdle);
    if (CFG.videoFree) {
      var freedNow = root().querySelectorAll('video[data-lm-freed]').length;
      L.push('  выгружено сейчас: ' + freedNow +
             ' | всего выгрузок: ' + freeCount + ', возвратов: ' + freeBack +
             ' | границы: выгрузка ' +
             (freeMargin >= 0 ? freeMargin + 'px' : '?') +
             ', возврат ' + (backMargin >= 0 ? backMargin + 'px' : '?'));
    }
    for (var i = 0; i < Math.min(vids.length, 6); i++) {
      var v = vids[i], r = v.getBoundingClientRect();
      L.push('  readyState=' + v.readyState +
             ' ' + v.videoWidth + 'x' + v.videoHeight +
             ' rect=' + Math.round(r.width) + 'x' + Math.round(r.height) +
             ' ratio=' + (v.style.aspectRatio || '-'));
      L.push('    preload=' + v.getAttribute('preload') +
             ' poster=' + (v.getAttribute('poster') || '-').slice(0, 60) +
             ' userPlayed=' + (v.dataset.lmUserPlayed || '0'));
    }

    var players = root().querySelectorAll('.js-media_player, .b-media_player');
    var empty = null;
    for (var q = 0; q < players.length; q++)
      if (isEmptyPlayer(players[q])) { empty = players[q]; break; }
    L.push('плееров: ' + players.length +
           ', пустых: ' + (empty ? 'есть' : 'нет'));
    if (empty) L.push(empty.outerHTML.slice(0, 500));

    /* Потолок высоты и то, как он сработал. Одного числа из настроек мало:
       vh считается от экрана с убранной адресной строкой, и сколько это в
       пикселях, на глаз не скажешь. Печатаем и заданное, и получившееся —
       расхождение сразу видно. */
    var capVar = getComputedStyle(document.documentElement)
      .getPropertyValue('--lm-media-max').trim();
    L.push('потолок медиа: ' + (capVar || '(нет)') +
           ' (в настройках ' + CFG.mediaCut + '%, высота окна ' +
           (window.innerHeight || 0) + ')');
    var tall = [];
    sliceOf(root().querySelectorAll('.p_body img, .c_body img, ' +
                                    '.p_body video, .c_body video, ' +
                                    '.js-media_player video'))
      .forEach(function (m) {
        var r = m.getBoundingClientRect();
        if (r.height) tall.push({ el: m, h: r.height, w: r.width });
      });
    tall.sort(function (a, b) { return b.h - a.h; });
    tall.slice(0, 4).forEach(function (t) {
      var nat = t.el.tagName === 'VIDEO'
        ? (t.el.videoWidth + '\u00d7' + t.el.videoHeight)
        : ((t.el.naturalWidth || '?') + '\u00d7' + (t.el.naturalHeight || '?'));
      L.push('  ' + t.el.tagName.toLowerCase() +
             ' на экране ' + Math.round(t.w) + '\u00d7' + Math.round(t.h) +
             ', свои размеры ' + nat);
    });
  }

  /* Панель «показывать / сортировать / только новое». Интервалы здесь
     складываются из четырёх источников: собственные поля пунктов, поля
     самих полей выбора, пробельные узлы между инлайновыми элементами и
     внутренние отступы select'а, который в Safari рисует стрелку внутри
     своей коробки. Глазом эти четыре не различить, поэтому меряем зазор
     между соседями напрямую и рядом печатаем, из чего он складывается. */
  function reportFilters(L) {
    var box = document.querySelector('.b-my_posts_feed_controls');
    if (!box) { L.push('(нет)'); return; }

    var p = box.querySelector('p') || box;
    L.push(p.outerHTML.replace(/<option[\s\S]*?<\/option>/g, '')
                      .replace(/ on[a-z]+="[^"]*"/g, '')
                      .replace(/\s+/g, ' ').slice(0, 500));

    var kids = sliceOf(p.childNodes).filter(function (n) {
      if (n.nodeType === 3) return !!n.nodeValue.replace(/\s/g, '').length ||
                                   n.nodeValue.length > 0;
      return n.nodeType === 1;
    });
    L.push('узлов в строке: ' + kids.length + ' (текстовых пробельных: ' +
           kids.filter(function (n) {
             return n.nodeType === 3 && !n.nodeValue.trim();
           }).length + ')');

    /* Всё, что реально занимает место: пункты и поля внутри них. */
    var prev = null;
    sliceOf(p.querySelectorAll(
      '.b-my_posts_feed_controls_item, select, input, label')).forEach(function (el) {
      var cs = getComputedStyle(el), r = el.getBoundingClientRect();
      if (cs.display === 'none' || (!r.width && !r.height)) return;
      var isItem = el.classList.contains('b-my_posts_feed_controls_item');
      L.push((isItem ? '' : '   ') + describe(el).slice(0, 40) +
             ' L=' + Math.round(r.left) + ' R=' + Math.round(r.right) +
             ' w=' + Math.round(r.width) +
             ' mar=' + cs.margin + ' pad=' + cs.padding +
             ' style="' + (el.getAttribute('style') || '') + '"');
      if (isItem) {
        if (prev) L.push('  ЗАЗОР между пунктами: ' +
                         Math.round(r.left - prev.right) + 'px');
        prev = r;
      }
    });

    /* Зазор, который видит человек, считается не от коробок пунктов,
       а от края нарисованного поля до края следующего. */
    var ctrls = sliceOf(p.querySelectorAll('select, input, label'))
      .filter(function (el) {
        var r = el.getBoundingClientRect();
        return getComputedStyle(el).display !== 'none' && r.width > 0;
      });
    for (var i = 1; i < ctrls.length; i++) {
      var a = ctrls[i - 1].getBoundingClientRect(),
          b = ctrls[i].getBoundingClientRect();
      if (b.left < a.left) continue;              /* перенос строки */
      L.push('ВИДИМЫЙ зазор ' + ctrls[i - 1].nodeName.toLowerCase() +
             ' \u2192 ' + ctrls[i].nodeName.toLowerCase() + ': ' +
             Math.round(b.left - a.right) + 'px');
    }
  }

  /* Диско. Показывает три вещи, которые иначе приходится
     угадывать по скриншоту: какой бюджет получился на этом экране, кого
     отбор счёл длинным, и что вышло у сокращённых постов по частям —
     сколько занял текст, сколько осталось картинке, где встало гнездо. */
  function reportDisco(L) {
    L.push('', '--- диско ---');
    if (!CFG.disco) { L.push('выключен настройкой'); return; }
    var MODE = ['ничего не уплотняем', 'только посты', 'посты и комментарии'];
    L.push('режим ' + discoMode() + ' — ' + MODE[discoMode()] +
           ' | scroll-connect ' + (scWanted() ? 'включён' : 'выключен') +
           ' | лента: ' + (discoFeed() ? 'да' : 'нет') +
           ' | тред: ' + (discoThread() ? 'да' : 'нет') +
           ' | метки: ' +
           (document.documentElement.classList.contains('lm-disco') ? 'lm-disco ' : '') +
           (document.documentElement.classList.contains('lm-disco_c') ? 'lm-disco_c ' : '') +
           (document.documentElement.classList.contains('lm-sconnect') ? 'lm-sconnect' : '') );
    /* Комментарии — отдельной строкой: у них свой бюджет и свой порог,
       и если срезов нет, первым делом надо понять, кого не хватило —
       длины комментариев или высоты экрана. */
    if (discoThread()) {
      var cc = sliceOf(document.querySelectorAll('.lm-disco_comment'));
      var all = document.querySelectorAll('#js-comments_holder .comment').length;
      L.push('комментарии: срезано ' + cc.length + ' из ' + all +
             ' | бюджет ' + discoCommentMax() +
             ' (' + CFG.commentCut + '% от ' + (discoVh || '?') + ')' +
             ' | порог выгоды ' + Math.round((discoVh || 0) * CFG.discoGain / 100));
    }
    if (CFG.feedAuto) {
      var fb = document.getElementById('js-index_load_more_posts');
      L.push('автоподгрузка: ' + (feedLog || 'пока не понадобилась') +
             ' | кнопка: ' + (!fb ? 'нет в разметке'
                              : (fb.getClientRects().length ? 'на месте' : 'спрятана')) +
             ' | запас ' + (feedMargin >= 0 ? feedMargin + 'px' : 'не задан') +
             ' (' + CFG.feedAhead + ' экрана от ' + (feedVh || '?') + ')' +
             ' | сборок наблюдателя: ' + feedBuilds);
    }
    if (!discoLog.length) L.push('(проход не отработал)');
    else discoLog.forEach(function (s) { L.push(s); });

    var cut = sliceOf(document.querySelectorAll('.lm-disco_post'));
    var keep = sliceOf(document.querySelectorAll('.lm-disco_keep'));

    if (scOn()) {
      L.push('scroll-connect: полоса ±' + CFG.discoZone +
             ' | допуск ' + CFG.discoDock +
             ' | выдержка ' + CFG.discoHold +
             ' | оборот ' + CFG.discoSpin + 'мс на ' + (360 * CFG.discoTurns) +
             '°');
      L.push('  гнёзд в полосе: ' + scLive.length +
             ' | цель: ' + (scTarget ? 'есть' : 'нет') +
             ' | до середины: ' + scSeen.dist +
             ' | яркость: ' + scSeen.near + '%' +
             ' | держим: ' + scSeen.held + 'мс' +
             ' | цикл: ' + (scFrame ? 'идёт' : 'спит'));
    }
    L.push('сокращено сейчас: ' + cut.length +
           ' | ждут ухода с экрана: ' + discoPending +
           ' | срез не окупился: ' + keep.length +
           ' | нижний предел выгоды: ' + Math.round(discoVh * CFG.discoGain / 100));
    cut.slice(0, 12).forEach(function (post) {
      var dt = post.querySelector('.dt');
      var dd = post.querySelector('.dd');
      var lead = post.querySelector('.lm-dsc_lead');
      var nest = post.querySelector('.lm-dsc_nest');
      var fit = post.querySelector('.lm-dsc_fit');
      L.push('  ' + post.id +
             ' было=' + (post.__lmWas === undefined ? '?' : post.__lmWas) +
             ' стало=' + Math.round(post.getBoundingClientRect().height) +
             ' выгода=' + (post.__lmGain === undefined ? '?' : post.__lmGain) +
             ' тело=' + (dt ? Math.round(dt.offsetHeight) : '-') +
             '/' + (dt ? (dt.style.maxHeight || '-') : '-') +
             ' потолок=' + post.__lmBudget + '/' + discoBodyMax(post) +
             ' подпись=' + (dd ? Math.round(dd.offsetHeight) : '-') +
             ' текст=' + (lead ? Math.round(lead.offsetHeight) +
                                 (lead.style.maxHeight ? ' (обрезан)' : '') : 'нет') +
             ' многоточие=' + (post.querySelector('.lm-dsc_dots') ? 'да' : 'нет') +
             ' хвост=' + (post.querySelector('.lm-dsc_hide') ? 'спрятан'
                          : post.querySelector('.lm-dsc_tail') ? 'в потоке' : 'нет') +
             ' вписано=' + (fit ? fit.style.maxHeight : 'нет') +
             ' гнездо=' + (nest ? nest.style.top : 'нет'));
    });
  }

  /* Профиль. Без таблицы стилей лепры под рукой ширины и отступы здесь
     приходится угадывать, а угадывание стабильно стоит трёх лишних кругов.
     Отчёт отвечает на три вопроса сразу: чем нарисована серая полоса, кто
     режет ширину заметки и откуда боковые поля у блока пользователя. */
  function reportProfile(L) {
    var block = document.querySelector('.b-user_block');
    if (!block) { L.push('(страница не профиль)'); return; }

    var W = document.documentElement.clientWidth;

    function line(pad, el) {
      var cs = getComputedStyle(el), r = el.getBoundingClientRect();
      return pad + describe(el).slice(0, 44) +
             ' disp=' + cs.display + ' pos=' + cs.position +
             ' fl=' + cs.cssFloat +
             ' w=' + cs.width + ' maxw=' + cs.maxWidth +
             ' pad=' + cs.padding + ' mar=' + cs.margin +
             ' bg=' + cs.backgroundColor +
             (cs.backgroundImage === 'none' ? '' : ' bgimg=есть') +
             ' | L=' + Math.round(r.left) + ' w=' + Math.round(r.width) +
             ' h=' + Math.round(r.height);
    }

    L.push('CSS-ширина ' + W);
    L.push(line('блок: ', block));

    L.push('', 'узлы блока (широкие или бестекстовые):');
    sliceOf(block.querySelectorAll('*')).slice(0, 120).forEach(function (el) {
      var cs = getComputedStyle(el);
      if (cs.display === 'none') return;
      var r = el.getBoundingClientRect();
      if (r.height < 8) return;
      var empty = (el.textContent || '').replace(/[\s\u00a0]/g, '') === '';
      if (!empty && r.width > W * 0.5) return;      /* нормальные широкие — не интересны */
      L.push(line('  ', el));
    });

    var n = noteEl();
    L.push('', 'заметка: ' + (n ? JSON.stringify(noteText(n).slice(0, 60)) : '(нет)'));
    if (n) {
      var el = n, d = 0;
      while (el && d < 7 && el !== document.body) {
        L.push(line('  ', el));
        el = el.parentElement; d++;
      }
    }

    /* Окно голосов: если хвостик показывает мимо счётчика или окно всё
       ещё за краем — здесь видно, к чему оно на самом деле прицеплено
       и какие у него координаты. Гадать про это дороже, чем напечатать. */
    var vp = document.querySelector('.b-votes_popup:not(.invisible)');
    L.push('', 'окно голосов: ' + (vp ? 'открыто' : '(закрыто)'));
    if (vp) {
      L.push(line('  ', vp));
      L.push('  сдвиг: ' + (vp.style.transform || '(нет)') +
             ' | предок по позиции: ' + positionedParent(vp));
      var an = popupAnchor(vp);
      if (an) L.push(line('  якорь: ', an));
      sliceOf(vp.querySelectorAll('.b-votes_popup_arrow')).forEach(function (t) {
        L.push(line('  хвостик: ', t));
      });
    }

    var pn = document.querySelector('.b-user_public_notes');
    if (pn) {
      L.push('', 'строка заметок:');
      L.push(line('  ', pn));
      sliceOf(pn.children).forEach(function (c) {
        if (getComputedStyle(c).display === 'none') return;
        L.push(line('    ', c));
      });
    }
  }

  /* Снимки лесенки по ходу загрузки. Отчёт снимается руками, то есть
     через несколько секунд после того, как страница открылась, — а
     жаловались на то, КАК ОНА ОТКРЫВАЕТСЯ. Между этими двумя моментами
     умещаются пять полных проходов, прыжок браузера к якорю и все наши
     перестройки, и любая из них могла бы поправить картинку, которую
     человек уже увидел. Поэтому каждый полный проход оставляет короткую
     запись: когда, при какой ширине и где стоял целевой комментарий.
     Дороже одного getBoundingClientRect на проход это не стоит. */
  var threadSnaps = [];
  var threadStart = Date.now();

  function threadSnap() {
    if (threadSnaps.length > 8) return;
    var anchor = (location.hash || '').replace(/^#/, '');
    if (!anchor) return;
    var el;
    try { el = document.querySelector('[id="' + anchor.replace(/["\\]/g, '') + '"]'); }
    catch (e) { return; }
    if (!el || !el.classList.contains('comment')) return;
    var r = el.getBoundingClientRect();
    var cs = getComputedStyle(el);
    threadSnaps.push('+' + (Date.now() - threadStart) + 'мс' +
      ' сдвиг=' + Math.round(window.pageXOffset || 0) +
      ' окно=' + document.documentElement.clientWidth +
      ' документ=' + document.documentElement.scrollWidth +
      ' padL=' + cs.paddingLeft +
      ' L=' + Math.round(r.left) + ' R=' + Math.round(r.right));
  }

  /* Лесенка комментариев. Раздел писался под одну задачу: ветка, открытая
     по прямой ссылке на глубокий комментарий, встаёт прижатой к правому
     краю. Причин у такой картинки ровно две, и они лечатся по-разному —
     либо у комментария и правда большой левый отступ, либо отступ в
     порядке, а страница уехала вбок (браузер прокручивает к якорю, и
     прокрутка эта горизонтальная).
     Различить их одним взглядом нельзя, а угадывать в этом скрипте уже
     дорого обходилось. Поэтому печатаем и то и другое: вычисленный
     отступ, настоящие координаты комментария и текста внутри него,
     ширину документа и текущий сдвиг по горизонтали. */
  function reportThreads(L) {
    L.push('', '--- лесенка комментариев ---');
    var box = document.getElementById('js-comments');
    if (!box) return L.push('(комментариев на странице нет)');

    L.push('сдвиг страницы вбок: window=' + Math.round(window.pageXOffset || 0) +
           ' html=' + Math.round(document.documentElement.scrollLeft || 0) +
           ' body=' + Math.round(document.body ? document.body.scrollLeft : 0));
    L.push('ширина: окно=' + document.documentElement.clientWidth +
           ' документ=' + document.documentElement.scrollWidth +
           ' body=' + (document.body ? document.body.scrollWidth : '?') +
           ' лента комментариев=' + Math.round(box.getBoundingClientRect().width));

    /* Показываем не все подряд, а по одному представителю на ступень —
       иначе на тысячном треде раздел вытеснит собой весь отчёт. Плюс
       отдельно тот комментарий, на который указывает адрес: жалоба
       именно про него, и он может оказаться не самым глубоким. */
    var target = null;
    var anchor = (location.hash || '').replace(/^#/, '');
    if (anchor) target = box.querySelector('[id="' + anchor.replace(/"/g, '') + '"]');

    var byLevel = {}, deepest = -1;
    sliceOf(box.querySelectorAll('.comment')).forEach(function (c) {
      var lvl = parseInt(c.getAttribute('data-tree_level'), 10);
      if (!(lvl >= 0)) {
        var m = /(?:^|\s)indent_(\d+)(?:\s|$)/.exec(c.className || '');
        lvl = m ? parseInt(m[1], 10) : -1;
      }
      if (!(lvl >= 0)) return;
      if (lvl > deepest) deepest = lvl;
      if (!byLevel[lvl]) byLevel[lvl] = c;
    });

    function line(tag, c) {
      var cs = getComputedStyle(c), r = c.getBoundingClientRect();
      var body = c.querySelector('.c_body');
      var br = body ? body.getBoundingClientRect() : null;
      L.push(tag +
             ' класс=' + (/(?:^|\s)(indent_\d+)/.exec(c.className || '') || [, '(нет)'])[1] +
             ' level=' + (c.getAttribute('data-tree_level') || '?') +
             ' padL=' + cs.paddingLeft + ' marL=' + cs.marginLeft +
             ' | комментарий L=' + Math.round(r.left) + ' R=' + Math.round(r.right) +
             (br ? ' | текст L=' + Math.round(br.left) + ' W=' + Math.round(br.width) : ''));
    }

    if (target) line('целевой:', target);
    var levels = Object.keys(byLevel).map(Number).sort(function (a, b) { return a - b; });
    levels.forEach(function (lvl) {
      if (lvl && lvl !== deepest && lvl % 3) return;   /* 0, каждый третий и самый глубокий */
      line('  ступень ' + lvl + ':', byLevel[lvl]);
    });
    L.push('самая глубокая ступень на странице: ' + deepest);
    if (threadSnaps.length) {
      L.push('снимки по ходу загрузки:');
      threadSnaps.forEach(function (s) { L.push('  ' + s); });
    } else if (location.hash) {
      L.push('снимков нет: якорь в адресе есть, но комментария с таким id не нашлось');
    }
  }

  /* Пынь: всё про окно, звук и голосование в одном месте. Раньше эти
     строки стояли в разделе «диско» — они дописывались туда, потому что
     кода было на три строки и заводить раздел казалось излишеством. В
     отчёте их после этого было не найти. */
  function reportPyn(L) {
    L.push('', '--- пынь ---');
    var open = !!document.getElementById('lm-pyn');
    L.push('окно: ' + (open
      ? ('открыто, слежение ' + (pynLiveTimer ? 'идёт' : 'не идёт') +
         ', отметка ' + (pynLiveSeen < 0 ? 'ещё не снята' : pynLiveSeen) +
         ', опрос раз в ' + CFG.pynLiveEvery + 'с' +
         ', опросов ' + pynLiveTicks +
         ', правило: ' + (CFG.pynAutoRead ? 'любое непрочитанное'
                                          : 'рост отметки') +
         (pynLiveBusy ? ', СЕЙЧАС ЗАНЯТО' : '') +
         (pynLiveLog ? ', последняя подгрузка: ' + pynLiveLog : ''))
      : 'закрыто'));
    L.push('сообщаем «' + CFG.pynSound + '»' +
           ', плашка ' + (CFG.pynToastSide === 'top' ? 'сверху' : 'снизу') +
           ' | звук: ' +
           (CFG.pynSound === 'push' ? 'не нужен'
            : !dingArmed ? 'слежение не запущено'
            : !dingCtx ? 'ждём первого касания'
            : dingCtx.state));

    var list = null;
    try { list = window.lmPynJson; } catch (e) {}
    L.push('голосовалки: построено ' + pynVoteMounted +
           ', рейтингов найдено ' + pynRateFound +
           ', уже отданных голосов ' + pynVoteMine +
           ' (из них по нашей памяти ' +
           Object.keys(pynVoteCast).length + ')' +
           ' | данные: ' + (list ? list.length + ' записей, ' + pynFreshFrom : 'нет') +
           ' | токен /ajax/: ' +
           (ajaxCsrf() ? (ajaxCsrfFrom || 'есть') : 'НЕТ') +
           ' | токен /api/: ' + (csrfToken() ? 'есть' : 'НЕТ') +
           ' | гражданин: ' + (currentUid() || 'неизвестен'));
    /* Что вообще лежит в данных о комментарии. Нужно затем, чтобы найти
       поле «мой голос»: сейчас уже поставленные голоса в окне не
       подсвечиваются, а имя поля мы не знаем и гадать не будем. */
    if (list && list.length) {
      var c0 = list[0] && list[0].data && list[0].data.comment;
      if (c0) {
        var keys = [];
        for (var k in c0) if (c0.hasOwnProperty(k)) {
          var t = typeof c0[k];
          keys.push(k + (t === 'object' ? '{}' : '=' + String(c0[k]).slice(0, 24)));
        }
        L.push('поля комментария в данных: ' + keys.join(', ').slice(0, 600));
      }
    }
    /* Построчно по каждому уведомлению: что в данных, что в памяти.
       Раздел временный, под один вопрос — почему после перезапуска
       браузера подсвечиваются голоса подлепр и не подсвечиваются голоса
       главной. Версий было две (кэш ленты и молчание user_vote), обе
       объясняли половину; гадать третий раз дороже, чем напечатать. */
    var mem = 0;
    try { mem = Object.keys(pynVoteCast).length; } catch (e) {}
    L.push('память голосов: ' + mem + ' записей' +
           ' | записей за эту страницу: ' + votesSaved +
           (votesFail ? ' | ОШИБКА записи: ' + votesFail : '') +
           ' | в хранилище: ' + (function () {
             var raw = null;
             try { raw = localStorage.getItem(VOTES_KEY); } catch (e) {}
             if (!raw) return 'пусто';
             var j = null;
             try { j = JSON.parse(raw); } catch (e) {}
             return j && j.list ? (j.list.length + ' под гражданином ' + j.uid)
                                : 'испорчено';
           })());

    var box = document.getElementById('lm-pyn');
    if (box) {
      L.push('по уведомлениям (id / домен / user_vote / наша память):');
      sliceOf(box.querySelectorAll('.b-notification-item[data-lm-cid]'))
        .slice(0, 20).forEach(function (it) {
          var cid = it.getAttribute('data-lm-cid');
          var dat = pynComment(it);
          var host = (it.getAttribute('data-lm-origin') || '')
            .replace('https://', '').replace('.leprosorium.ru', '') || '?';
          L.push('  ' + cid + ' / ' + host +
                 ' / ' + (dat ? (JSON.stringify(dat.user_vote) || 'нет поля') +
                                 '→' + pynMyVote(dat)
                              : 'нет данных') +
                 ' / ' + (pynVoteCast.hasOwnProperty(cid)
                            ? pynVoteCast[cid] : '—') +
                 ' / кнопка ' + (it.querySelector('.lm-pyn_vote_btn.lm-on')
                                   ? 'нажата' : 'нет') +
                 ' / данные ' + (pynMatchWay[cid] || '?') +
                 ' / id в данных ' + (dat && dat.id !== undefined ? dat.id : '—'));
        });
    } else {
      L.push('(окно закрыто — построчной картины нет; откройте окно и снимите отчёт заново)');
    }

    if (pynReplyLog.length) {
      L.push('отправленные ответы:');
      pynReplyLog.forEach(function (v) { L.push('  ' + v); });
    }
    if (pynVoteLog.length) {
      L.push('отправленные голоса:');
      pynVoteLog.forEach(function (v) { L.push('  ' + v); });
    } else {
      L.push('отправленных голосов пока не было');
    }
  }

  /* Общие настройки: что лежит в куке, что в зеркале и откуда взято
     действующее значение. Печатаем ИСТОЧНИК, а не только величину:
     строка «тема: тёмная» ничего не говорит о том, разъехались ли
     поддомены, а «тема: 1 (кука) зеркало 0» говорит сразу. */
  function reportPrefs(L) {
    L.push('', '--- общие настройки ---');
    L.push('домен куки: .' + baseDomain());
    SHARED_KEYS.forEach(function (k) {
      var c = prefCookieRead(k);
      var m = null;
      try { m = localStorage.getItem(k); } catch (e) { m = '(нет доступа)'; }
      var src = c !== null ? 'кука' : (m !== null ? 'зеркало' : 'ничего');
      L.push('  ' + k + ': ' + (c !== null ? c : (m !== null ? m : '—')) +
             ' (' + src + ')' +
             (c !== null && m !== c ? ' | зеркало: ' + (m === null ? '—' : m) : ''));
    });
  }

  /* Голосовалки: настоящие замеры вместо «на глаз кажется мельче».
     Печатаем и площадь нажатия (сам элемент), и видимую коробку
     (псевдоэлемент) — они разного размера нарочно, и без разделения
     сообщение «кнопка 26, а выглядит на 24» звучало бы как поломка.
     Рядом — источник ширины: какое правило её задало. Строка «26×26»
     закрывает вопрос сама, а строка «24×24 ← .comment .vote_button»
     ещё и говорит, кто виноват. */
  function reportVotes(L) {
    L.push('', '--- голосовалки ---');
    var spots = [
      ['пост',    '.dd .vote .vote_button'],
      ['камент',  '#js-comments_holder .comment .c_vote .vote_button'],
      ['карма',   '.b-karma_button'],
      ['пынь',    '.lm-pyn_vote_btn'],
      ['счётчик', '.vote_result']
    ];
    spots.forEach(function (pair) {
      var el = document.querySelector(pair[1]);
      if (!el) { L.push('  ' + pair[0] + ': нет на странице'); return; }
      var r = el.getBoundingClientRect();
      var line = '  ' + pair[0] + ': ' +
                 Math.round(r.width) + '×' + Math.round(r.height);
      var cs = window.getComputedStyle(el, '::before');
      var bw = cs && cs.width, bh = cs && cs.height;
      if (bw && bw !== 'auto' && bw !== '0px')
        line += ', коробка ' + bw + '×' + bh;
      line += ', кегль ' + window.getComputedStyle(el).fontSize;
      L.push(line);
    });

    /* Строка подписи целиком: голосовалка стоит в ней первым элементом,
       и вопрос «влезает ли» решается только числами. Печатаем ширину
       голосовалки, ширину строки и её высоту — по высоте видно, на
       сколько строк подпись перенеслась (одна строка с голосовалкой
       ростом 28 плюс поля). */
    /* Точка: сколько их и привязан ли слушатель. Вопрос «на этой
       странице точка не нажимается» распадается на три разных: точек
       нет вовсе / точки есть, но слушателя нет / всё есть, а столбик не
       виден. Три числа отличают их сразу, без гаданий. */
    L.push('  точек: ' + document.querySelectorAll('.lm-more').length +
           ', слушатель ' + (moreBound ? 'привязан' : 'НЕТ') +
           ', открыт ' + (document.querySelector('.lm-more_box.lm-on') ? 'да' : 'нет'));
    /* За чем следит наблюдатель. Если подписи на странице лепровские, а
       точек ноль — вопрос всегда один: дошёл ли до этого содержимого
       проход. Имя узла отвечает на него сразу. */
    L.push('  фон страницы: ' + pageBg());
    /* По каждой таблице оформления отдельно: их две, и застрять может
       любая. Плюс адрес картинки полосы — если её нет, сразу видно, не
       нашлось правило или не построился узел. */
    var subs = subsiteSheets();
    L.push('  таблиц оформления: ' + subs.length);
    subs.forEach(function (l, i) {
      var st = null;
      try { st = l.sheet; } catch (e) { st = null; }
      L.push('    ' + (i + 1) + ') ' + l.tagName.toLowerCase() + ' ' +
             (l.dataset.lmDone ? 'проредили ' + l.dataset.lmDone
                : !st ? 'ждём загрузки (media=' + (l.getAttribute('media') || '—') + ')'
                : 'ЗАГРУЖЕНА, НО НЕ ТРОНУТА') +
             ' | ' + ((l.getAttribute('href') || '').slice(-30) ||
                      (l.textContent || '').replace(/\s+/g, ' ').slice(0, 30)));
    });
    L.push('  полоса заголовка: ' +
           (!subsiteArt ? 'картинки не нашлось'
             : document.getElementById('lm-subband') ? 'построена'
             : 'адрес есть, узла нет'));
    /* Набор тонов и то, что реально получилось у трёх слоёв. На профиле
       у лепры своя серая заливка в три этажа, и вопрос «почему верх не
       потемнел» решается только сравнением этих трёх чисел. */
    var lay = [['страница', document.querySelector('.l-i-wrapper')],
               ['тело',     document.querySelector('.l-content_wrapper, .b-posts_holder')],
               ['карточка', document.querySelector('.post, .comment .c_i')]];
    L.push('  набор: ' + (CFG.cardsLift ? 'светлые карточки' : 'заводской') + ' | ' +
           lay.map(function (pair) {
             return pair[0] + ': ' + (pair[1]
               ? window.getComputedStyle(pair[1]).backgroundColor : '—');
           }).join(', '));

    var wa = watchDom.at;
    L.push('  наблюдатель: ' + (wa ? (wa.id || wa.tagName.toLowerCase()) : 'НЕ ПОСТАВЛЕН') +
           ', адрес отслеживается: ' + (routeWatched ? 'да' : 'НЕТ'));

    var ddi = document.querySelector('.dd .ddi');
    if (ddi) {
      var vr = ddi.querySelector('.vote');
      var rr = ddi.getBoundingClientRect();
      L.push('  подпись поста: строка ' + Math.round(rr.width) + '×' +
             Math.round(rr.height) +
             (vr ? ', голосовалка ' + Math.round(vr.getBoundingClientRect().width) : ', голосовалки в строке нет') +
             ', вылет ' + Math.max(0, ddi.scrollWidth - ddi.clientWidth));
    }
  }

  /* Настоящий фон под постом. Спор «белый он или нет» решается только
     замером: в таблице стилей лепры body покрашен в чистый белый, но
     подлепры красят себя сами, тёмная тема выворачивает всё наизнанку,
     а экран телефона добавляет свой оттенок поверх любого из этих
     ответов. Идём вверх от поста до первого предка, у которого фон не
     прозрачный, и печатаем цвет вместе с именем этого предка — без
     имени цифра ничего не объясняет. */
  function pageBg() {
    var el = document.querySelector('.post, .comment .c_i') || document.body;
    while (el && el !== document.documentElement) {
      var c = window.getComputedStyle(el).backgroundColor;
      if (c && c !== 'transparent' && !/rgba\(0,\s*0,\s*0,\s*0\)/.test(c))
        return c + ' (' + (el.id || el.className || el.tagName).toString().split(' ')[0] + ')';
      el = el.parentElement;
    }
    return 'нигде не задан — значит, белый по умолчанию';
  }

  /* Замер 100vw пробным узлом. Узел ставим и убираем тут же: держать
     его на странице незачем, а один замер стоит одного пересчёта
     раскладки — цена отчёта, а не работы скрипта. */
  function vwProbe() {
    try {
      var d = document.createElement('div');
      d.style.cssText = 'position:absolute;left:-9999px;top:0;' +
                        'width:100vw;height:1px;pointer-events:none';
      document.body.appendChild(d);
      var w = Math.round(d.getBoundingClientRect().width);
      d.parentNode.removeChild(d);
      return w;
    } catch (e) { return '?'; }
  }

  function report() {
    var L = ['Lepra Mobile v' + VERSION,
             'URL: ' + location.pathname,
             'экран устройства: ' + screenWidth() +
               ' | окно: ' + window.innerWidth +
               ' | CSS-ширина: ' + document.documentElement.clientWidth,
             'ширина документа: ' + document.documentElement.scrollWidth,
             /* Сколько на самом деле стоит 100vw. Число нужно ровно для
                одного вопроса: следует ли vw за масштабом страницы.
                Пока оно совпадает с CSS-шириной, всё в порядке; разойдётся —
                значит вернулась история с формой за правым краем, и
                искать надо там, где ширина задана в vw.
                Мерим пробным узлом, а не считаем: посчитать это нечем. */
             '100vw = ' + vwProbe() + ' (CSS-ширина ' +
               document.documentElement.clientWidth + ')',
             /* Масштаб страницы и посчитанный по нему кегль полей формы.
                Если форма опять уедет вправо, первым делом сюда: кегль
                ниже шестнадцати «на глаз» — это приближение Safari, а
                масштаб, застрявший на единице, — это visualViewport,
                который нам его не отдал. */
             'масштаб: ' + Math.round(formScaleSeen * 100) / 100 +
               ' | кегль формы: ' + formFontSeen +
               ' (база ' + CFG.formFont + ', потолок ' + CFG.formFontMax + ')',
             /* Возврат «назад». Печатаем не только исход, но и его
                источник — правило из записки: строка «не трогаем»
                означает обычный переход, «записи нет» — что снимка не
                было, «по узлу …» — что сработало и по какому. */
             'возврат назад: ' + (backOn() ? 'ведём' : 'не ведём') +
               ' | ' + (backLog || '—'),
             'лёгких проходов: ' + lightRuns + ' | суммарно ' + lightMs +
               'мс | самый долгий ' + lightWorst + 'мс',
             /* Эмодзи: обойдено мест и завёрнуто знаков. Строка нужна
                прежде всего затем, чтобы отличить «не сработало» от
                «нечего было заворачивать»: ноль найденных при нуле
                обойдённых мест — это про образец или про селекторы, а
                ноль найденных при трёхстах обойдённых — про страницу. */
             'эмодзи: обойдено мест ' + emoHosts + ', завёрнуто ' + emoFound +
               (EMO_RE ? '' : ' (образец не собрался)'),
             ''];
    if (CFG.mournOff) {
      /* Строка временная, вместе с самой настройкой. Нужна на случай,
         если серый фон где-то останется: тогда сразу видно, погасили мы
         хоть что-нибудь и не оказалась ли траурная таблица закрытой для
         чтения (так бывает у подключённых с чужого домена — их правила
         браузер читать не даёт, и найти нужную нечем). */
      var shN = 0, shClosed = 0;
      try {
        shN = document.styleSheets.length;
        for (var si = 0; si < shN; si++) {
          try { void document.styleSheets[si].cssRules; }
          catch (e) { shClosed++; }
        }
      } catch (e) {}
      L.push('таблиц стилей: ' + shN + ', недоступных: ' + shClosed +
             ', траурных погашено: ' + mournOffCount, '');
    }
    var R = CFG.report || {};
    if (R.overflow) reportOverflow(L);
    if (R.network) reportNetwork(L);
    if (R.floats) reportFloats(L);
    if (R.overlaps) reportOverlaps(L);
    if (R.media) reportMedia(L);
    if (R.disco) reportDisco(L);
    if (R.threads) reportThreads(L);
    if (R.pyn) reportPyn(L);
    if (R.prefs) reportPrefs(L);
    if (R.votes) reportVotes(L);

    /* Разметка подписи поста и шапки: чтобы не гадать, чем именно
       прячутся значки и что двигает приветствие. */
    if (R.postFooter) {
    L.push('', '--- подпись поста ---');
    var ddi = document.querySelector('.dd .ddi');
    if (!ddi) L.push('(нет)');
    else {
      L.push(ddi.outerHTML.replace(/<svg[\s\S]*?<\/svg>/g, '[svg]')
                          .replace(/\s+/g, ' ').slice(0, 700));
      L.push('');
      sliceOf(ddi.querySelectorAll('a, span.b-post_controls, span.lm-icons')).slice(0, 18)
        .forEach(function (el) {
          var cs = getComputedStyle(el), r = el.getBoundingClientRect();
          L.push('  ' + describe(el).slice(0, 46) +
                 ' disp=' + cs.display +
                 ' va=' + cs.verticalAlign +
                 ' fs=' + cs.fontSize +
                 ' top=' + Math.round(r.top) + ' h=' + Math.round(r.height));
        });
    }

    }

    if (R.commentFooter) {
    L.push('', '--- подпись комментария ---');
    var cf = document.querySelector('#js-comments_holder .comment .c_footer');
    if (!cf) L.push('(нет)');
    else {
      L.push(cf.outerHTML.replace(/<svg[\s\S]*?<\/svg>/g, '[svg]')
                         .replace(/\s+/g, ' ').slice(0, 700));
      L.push('');
      var cfr = cf.getBoundingClientRect(), cfs = getComputedStyle(cf);
      L.push('контейнер: disp=' + cfs.display + ' wrap=' + cfs.flexWrap +
             ' gap=' + cfs.gap + ' lh=' + cfs.lineHeight +
             ' L=' + Math.round(cfr.left) + ' w=' + Math.round(cfr.width) +
             ' h=' + Math.round(cfr.height));

      sliceOf(cf.querySelectorAll('*')).slice(0, 20).forEach(function (el) {
        var cs = getComputedStyle(el), r = el.getBoundingClientRect();
        if (cs.display === 'none') return;
        L.push('  ' + describe(el).slice(0, 44) +
               ' disp=' + cs.display +
               ' pos=' + cs.position +
               ' fs=' + cs.fontSize +
               ' L=' + Math.round(r.left) + ' top=' + Math.round(r.top) +
               ' w=' + Math.round(r.width) + ' h=' + Math.round(r.height));
      });
    }

    }

    if (R.header) {
    L.push('', '--- шапка: приветствие ---');
    var tg = document.querySelector('.l-header_tagline');
    if (!tg) L.push('(нет)');
    else {
      var hd = document.querySelector('.l-header');
      var hcs = getComputedStyle(hd), tcs = getComputedStyle(tg);
      var hr = hd.getBoundingClientRect(), tr = tg.getBoundingClientRect();
      L.push('шапка: display=' + hcs.display + ' justify=' + hcs.justifyContent +
             ' L=' + Math.round(hr.left) + ' w=' + Math.round(hr.width));
      L.push('приветствие: flex=' + tcs.flex + ' align=' + tcs.textAlign +
             ' L=' + Math.round(tr.left) + ' w=' + Math.round(tr.width));
      var inner = tg.querySelector('.b-header_tagline');
      if (inner) {
        var ir = inner.getBoundingClientRect(), ics = getComputedStyle(inner);
        L.push('текст: align=' + ics.textAlign + ' margin=' + ics.margin +
               ' L=' + Math.round(ir.left) + ' w=' + Math.round(ir.width));
      }
    }

    /* Раздел назывался «шапка: поиск» и искал форму внутри .l-header —
       с переездом поиска в навигационную штуку он перестал что-либо
       находить и несколько версий печатал «(нет)». Ищем форму там,
       где она есть. */
    }

    if (R.search) {
    L.push('', '--- поиск ---');
    var sf = document.querySelector('.b-header_search form');
    if (!sf) L.push('(нет)');
    else {
      L.push(sf.outerHTML.replace(/ on[a-z]+="[^"]*"/g, '')
                         .replace(/\s+/g, ' ').slice(0, 400));
      var scs = getComputedStyle(sf), sr = sf.getBoundingClientRect();
      L.push('форма: disp=' + scs.display + ' justify=' + scs.justifyContent +
             ' gap=' + scs.gap +
             ' L=' + Math.round(sr.left) + ' R=' + Math.round(sr.right));
      sliceOf(sf.querySelectorAll('*')).slice(0, 10).forEach(function (el) {
        var cs = getComputedStyle(el), r = el.getBoundingClientRect();
        L.push('  ' + describe(el).slice(0, 40) +
               ' disp=' + cs.display + ' pos=' + cs.position +
               ' left=' + cs.left +
               ' w=' + cs.width + ' pad=' + cs.padding +
               ' mar=' + cs.margin +
               ' | L=' + Math.round(r.left) + ' R=' + Math.round(r.right) +
               ' h=' + Math.round(r.height));
        ['::before', '::after'].forEach(function (p) {
          var ps = getComputedStyle(el, p);
          if (!ps || ps.content === 'none' || ps.display === 'none') return;
          L.push('    ' + p + ' content=' + ps.content +
                 ' disp=' + ps.display + ' w=' + ps.width +
                 ' pad=' + ps.padding + ' mar=' + ps.margin);
        });
      });
    }

    /* Динамический список. Числа отсюда — единственный способ понять,
       чьи координаты доехали до экрана: лепра пишет свои инлайном, мы
       свои переменными, и спор между ними виден только по факту. */
    var rcs = getComputedStyle(document.documentElement);
    L.push('переменные: pull=' + (rcs.getPropertyValue('--lm-srch-pull') || '(нет)').trim() +
           ' qsTop=' + (rcs.getPropertyValue('--lm-qs-top') || '(нет)').trim() +
           ' qsMax=' + (rcs.getPropertyValue('--lm-qs-max') || '(нет)').trim() +
           ' | классы: ' + (document.documentElement.className || '(нет)'));
    L.push('кегль ввода: ' + (rcs.getPropertyValue('--lm-srch-font') || '(не ставили)').trim() +
           ' (база ' + CFG.searchFocusFont + ', потолок ' + CFG.searchFontMax +
           ', масштаб при касании ' + (srchScaleSeen ? srchScaleSeen.toFixed(3) : '(не касались)') + ')');
    L.push('оттяжка снята с формы: ' + (srchPullSeen || '(не снималась)'));
    var qs = document.querySelector('.b-quick_search_container');
    if (!qs) L.push('динамопоиск: нет в разметке');
    else {
      var qcs = getComputedStyle(qs), qr = qs.getBoundingClientRect();
      L.push('динамопоиск инлайном: ' + (qs.getAttribute('style') || '(пусто)'));
      L.push('  pos=' + qcs.position + ' z=' + qcs.zIndex +
             ' top=' + qcs.top + ' left=' + qcs.left + ' right=' + qcs.right +
             ' w=' + qcs.width + ' maxh=' + qcs.maxHeight);
      L.push('  факт: L=' + Math.round(qr.left) + ' R=' + Math.round(qr.right) +
             ' T=' + Math.round(qr.top) + ' B=' + Math.round(qr.bottom) +
             ' h=' + Math.round(qr.height));
      var qin = qs.querySelector('.b-quick_search');
      if (qin) {
        var qis = getComputedStyle(qin), qir = qin.getBoundingClientRect();
        L.push('  список: h=' + qis.height + ' maxh=' + qis.maxHeight +
               ' overflow=' + qis.overflowY + ' факт=' + Math.round(qir.height));
      }
      var vv2 = window.visualViewport;
      if (vv2)
        L.push('  видимая часть: offsetTop=' + Math.round(vv2.offsetTop) +
               ' h=' + Math.round(vv2.height) + ' scale=' + vv2.scale);
    }

    }

    if (R.profile) {
      L.push('', '--- профиль ---');
      reportProfile(L);
    }

    if (R.filters) {
      L.push('', '--- панель фильтров ---');
      reportFilters(L);
    }

    if (R.layers) {
      L.push('', '--- слои поверх страницы ---');
      reportOverlays(L);
    }

    L.push('', '--- журнал скрипта ---');
    if (!LOG.length) L.push('(пусто — ошибок не было)');
    else LOG.forEach(function (m) { L.push(m); });

    /* Список погашенных — чтобы про них не забыть. Раздел, о котором
       не помнишь, всё равно что удалённый. */
    var off = Object.keys(R).filter(function (k) { return !R[k]; });
    if (off.length) L.push('', 'выключены разделы (CFG.report): ' + off.join(', '));

    return L.join('\n');
  }

  /* Инспектор: следующий тап показывает элемент под пальцем.
     Заменил собой десяток итераций «угадай, какой это селектор». */
  function inspectAt(el) {
    var L = ['Lepra Mobile v' + VERSION, 'ТЫК ПО ЭЛЕМЕНТУ', '',
             '--- цепочка родителей ---'];

    var chain = [], n = el, d = 0;
    while (n && n.tagName && d < 7) { chain.push(describe(n)); n = n.parentElement; d++; }
    L.push(chain.join('\n  < '));

    var r = el.getBoundingClientRect();
    L.push('', '--- сам элемент ---');
    L.push('размер ' + Math.round(r.width) + 'x' + Math.round(r.height) +
           ' pos=' + getComputedStyle(el).position);
    L.push(el.outerHTML.slice(0, 700));

    /* ближайший крупный контейнер: там обычно и лежат data-атрибуты */
    var box = el, steps = 0;
    while (box.parentElement && steps < 6) {
      var br = box.getBoundingClientRect();
      if (br.height > 80 && br.width > 80) break;
      box = box.parentElement; steps++;
    }
    if (box !== el) {
      L.push('', '--- контейнер ---');
      L.push(describe(box));
      L.push(box.outerHTML.slice(0, 900));
    }
    showPanel(L.join('\n'));
  }

  function armInspector() {
    closePanel();
    var handler = function (e) {
      e.preventDefault();
      e.stopPropagation();
      if (e.stopImmediatePropagation) e.stopImmediatePropagation();
      document.removeEventListener('click', handler, true);
      inspectAt(e.target);
    };
    document.addEventListener('click', handler, true);
  }

  /* Ленту уведомлений лепра собирает в браузере: тянет шаблоны из
     /static/views/notifications/ и данные из /api/my/notifications/.
     Первая же проба этого адреса вернула 404 при том, что сама лепра
     ходит туда успешно, — значит, дело не в адресе, а в чём-то ещё:
     заголовке, параметрах или правах. Гадать по одному варианту в круг
     дорого, поэтому проба перебирает их сразу и показывает ответ на
     каждый. */
  /* Ключ к API лепры. Перехват в окне пыни показал, чем она авторизует
     свои запросы: не куками, а парой заголовков X-Futuware-UID и
     X-Futuware-SID (плюс обычный X-Requested-With). Без них весь /api/
     отвечает 404 — отсюда и брались все прошлые загадки.

     Значения её собственный скрипт откуда-то читает, и читать их он может
     только из доступного JS: из куки, из глобальной переменной или из
     разметки. Ищем по всем трём местам. */

  var API_UID_KEYS = ['uid', 'futuware_uid', 'user_id', 'userid'];
  var API_SID_KEYS = ['sid', 'futuware_sid', 'session_id', 'sessionid'];
  var HEX32 = /^[0-9a-f]{32}$/i;

  /* Все места, где скрипт лепры может держать пару, — и все они доступны
     нам: куки без HttpOnly, оба хранилища и глобальные переменные.
     Возвращаем плоский список «источник → имя → значение», чтобы искать
     дальше не по одному месту, а сразу везде. */
  function authSources() {
    var all = [];

    try {
      String(document.cookie || '').split(';').forEach(function (part) {
        var i = part.indexOf('=');
        if (i < 0) return;
        all.push({ where: 'кука', name: part.slice(0, i).trim(),
                   value: part.slice(i + 1).trim() });
      });
    } catch (e) {}

    [['localStorage', window.localStorage],
     ['sessionStorage', window.sessionStorage]].forEach(function (pair) {
      try {
        var st = pair[1];
        if (!st) return;
        for (var i = 0; i < st.length && i < 100; i++) {
          var k = st.key(i);
          all.push({ where: pair[0], name: k, value: String(st.getItem(k) || '') });
        }
      } catch (e) {}
    });

    /* Глобальные переменные перебираем целиком, а не по списку имён:
       csrf-токен лепра держит где-то в своём скрипте, и как он там
       называется, мы не знаем. Заглядываем и на уровень внутрь простых
       объектов — настройки сайта обычно лежат одним таким. */
    try {
      var keys = Object.keys(window).slice(0, 400);
      keys.forEach(function (k) {
        var v;
        try { v = window[k]; } catch (e) { return; }
        if (v && (typeof v === 'string' || typeof v === 'number')) {
          all.push({ where: 'window', name: k, value: String(v) });
          return;
        }
        if (!v || typeof v !== 'object' || v.nodeType) return;
        var inner;
        try { inner = Object.keys(v).slice(0, 40); } catch (e) { return; }
        inner.forEach(function (k2) {
          var v2;
          try { v2 = v[k2]; } catch (e) { return; }
          if (v2 && typeof v2 === 'string')
            all.push({ where: 'window.' + k, name: k2, value: v2 });
        });
      });
    } catch (e) {}

    return all;
  }

  /* Искать по именам ненадёжно: лепра могла назвать их как угодно.
     Поэтому сначала по имени, а если не вышло — по виду значения.
     SID — тридцать два шестнадцатеричных знака; UID — то же число,
     что стоит в data-user_id у любого своего комментария. */
  function findAuth(all) {
    var byName = function (names) {
      for (var i = 0; i < names.length; i++)
        for (var j = 0; j < all.length; j++)
          if (all[j].name === names[i] && all[j].value) return all[j];
      return null;
    };

    var mine = document.querySelector('[data-user_id]');
    var myId = mine && mine.getAttribute('data-user_id');

    var uid = byName(API_UID_KEYS);
    if (!uid && myId) {
      for (var i = 0; i < all.length; i++)
        if (all[i].value === myId) { uid = all[i]; break; }
      if (!uid) uid = { where: 'разметка', name: 'data-user_id', value: myId };
    }

    var sid = byName(API_SID_KEYS);
    if (!sid) {
      for (var k = 0; k < all.length; k++)
        if (HEX32.test(all[k].value)) { sid = all[k]; break; }
    }

    return { uid: uid, sid: sid };
  }

  function pynProbe() {
    var base = location.protocol + '//' + location.host;
    var all = authSources();
    var found = findAuth(all);
    var uid = found.uid, sid = found.sid;

    /* Значений не показываем: отчёт уходит в переписку, а SID — это ключ
       от сессии. Только где нашли, как называется и сколько знаков. */
    var hide = function (x) {
      return x ? x.where + ' ' + x.name + ' (' + String(x.value).length + ' знаков)'
               : 'НЕ НАЙДЕН';
    };

    var csrf = findCsrf();
    var out = ['Проба API пыни',
               'источник: ' + base,
               'CSRF: ' + (csrf ? csrf.where + ' ' + csrf.name : 'НЕ НАЙДЕН'),
               'просмотрено мест: ' + all.length +
                 ' (' + all.map(function (x) { return x.where + ':' + x.name; })
                          .slice(0, 25).join(', ') + ')',
               'UID: ' + hide(uid),
               'SID: ' + hide(sid),
               ''];

    if (!uid || !sid) {
      out.push('Без пары UID+SID пробовать нечего: лепра авторизует запросы',
               'к /api/ именно ими. Значит её скрипт держит их не там, где',
               'мы ищем, — надо смотреть дальше.');
      return showPanel(out.join('\n'));
    }

    var auth = {
      'X-Futuware-UID': uid.value,
      'X-Futuware-SID': sid.value,
      'X-Requested-With': 'XMLHttpRequest',
      'Accept': 'application/json, text/javascript, */*; q=0.01'
    };

    /* Счётчик — первым: он и нужен для слежения за пынями, и, в отличие
       от ленты, ничего не отмечает прочитанным. Ленту пробуем следом,
       чтобы знать, годится ли она для мгновенного открытия окна. */
    var tries = [
      ['счётчик непрочитанных', '/api/my/notifications/unread/count_by_type/', auth, 400],
      ['счётчик без заголовков', '/api/my/notifications/unread/count_by_type/', {}, 200],
      /* одна штука и подлиннее: по ней будем разбирать поля для текста
         в плашке, а двадцать в отчёт всё равно не влезут */
      ['лента (одна штука)', '/api/my/notifications/?per_page=1&page=1', auth, 1800]
    ];

    showPanel(out.join('\n') + '\nжду ответов…');

    var i = 0;
    var next = function () {
      if (i >= tries.length) return showPanel(out.join('\n'));
      var t = tries[i++];
      var say = function (s, body) {
        out.push(t[0] + '  →  ' + s);
        out.push('   ' + t[1]);
        if (body) out.push('   ' + body.slice(0, t[3] || 300).replace(/\s+/g, ' '));
        out.push('');
      };
      fetch(base + t[1], { method: 'GET', credentials: 'same-origin', headers: t[2] })
        .then(function (r) {
          return r.text().then(function (x) {
            say('HTTP ' + r.status + '  ' + x.length + ' знаков', x);
          });
        })
        .catch(function (e) { say('ошибка: ' + ((e && e.message) || e)); })
        .then(next);
    };
    next();
  }

  function closePanel() {
    var old = document.getElementById('lm-debug');
    if (old) old.remove();
  }

  function showPanel(text) {
    closePanel();

    var p = document.createElement('div');
    p.id = 'lm-debug';

    var copy = document.createElement('button');
    copy.textContent = 'скопировать';
    copy.onclick = function () {
      if (!navigator.clipboard) return;
      navigator.clipboard.writeText(text).then(
        function () { copy.textContent = 'скопировано'; },
        function () { copy.textContent = 'не вышло, выделяйте руками'; });
    };

    var close = document.createElement('button');
    close.textContent = 'закрыть';
    close.onclick = closePanel;

    var pick = document.createElement('button');
    pick.textContent = 'тык по элементу';
    pick.onclick = armInspector;

    var probe = document.createElement('button');
    probe.textContent = 'ответ пыни';
    probe.onclick = pynProbe;

    var body = document.createElement('div');
    body.textContent = text;

    p.appendChild(copy);
    p.appendChild(close);
    p.appendChild(pick);
    p.appendChild(probe);
    p.appendChild(body);
    document.body.appendChild(p);
  }

  function panel() {
    if (document.getElementById('lm-debug')) { closePanel(); return; }
    showPanel(report());
  }

  if (CFG.debug) {
    window.lmDebug = panel;

    /* три быстрых тапа по левому верхнему углу */
    var taps = [];
    document.addEventListener('touchstart', function (e) {
      /* touches бывает пустым: касание может прийти не от пальца, а от
         чужого скрипта событием без списка точек — и обработчик падал. */
      var t = e.touches && e.touches[0];
      if (!t || t.clientX > 60 || t.clientY > 60) return;
      var now = Date.now();
      taps = taps.filter(function (x) { return now - x < 1500; });
      taps.push(now);
      if (taps.length >= 3) { taps = []; panel(); }
    }, { passive: true });

    window.addEventListener('hashchange', function () { setTimeout(panel, 100); });
  }

  /* ============================================================
     9.5. ВОЗВРАТ НА ПРЕЖНЕЕ МЕСТО ПО КНОПКЕ «НАЗАД»
     ============================================================

     Жалоба с Андроида: кнопка «назад» в Firefox приводит не туда, откуда
     ушли, а к самой шапке. На айфоне этого нет.

     Восстановлением места заведует браузер, и делает он это по числу
     пикселей, снятому в момент ухода. Число верно ровно до тех пор, пока
     страница той же высоты. Наша ею не бывает: viewport, разбор колонок,
     потолок высоты медиа, выгрузка ушедших роликов и особенно уплотнение
     постов меняют высоту на тысячи пикселей, и меняют её ПОСЛЕ того, как
     браузер уже восстановил прокрутку. Дальше всё зависит от того, кто
     когда: WebKit восстанавливает позже и попадает, Gecko — раньше,
     упирается в тогдашнюю высоту документа и прижимается к верху.

     Проверить эту догадку на устройстве мне нечем, поэтому чинится она
     не догадкой, а способом, которому всё равно, кто прав: держим место
     сами и не пикселями, а УЗЛОМ. Запоминаем не «сорок тысяч сверху», а
     «пост p2531675, и его верх был на сорока пикселях ниже кромки».
     Такая привязка переживает любое изменение высоты — в том числе
     уплотнение, которое меняет её больше всего.

     Айфона это не касается вовсе: без Firefox в строке опознания весь
     раздел молчит, включая запись в хранилище.

     Запись — по pagehide, а не по прокрутке. Правило «прокрутка не
     запускает обходов DOM» тут в силе: снимок стоит одного обхода
     видимых узлов, и делать его тридцать раз в секунду незачем.

     Если Firefox сохранит страницу в кэше назад-вперёд, скрипт при
     возврате не перезапустится вовсе, место восстановит сам браузер, и
     наша запись просто никому не понадобится. Мешать этому мы не
     мешаем. */

  var BACK_KEY = 'lm-back';

  function backOn() {
    if (CFG.backRestore === 'off') return false;
    if (CFG.backRestore === 'on') return true;
    return /Firefox\/\d/.test(navigator.userAgent || '');
  }

  /* Ключ страницы: путь и запрос, без решётки. Решётка сюда попасть не
     должна — по ней открывается отладочная панель и приходят прямые
     ссылки на комментарий, а место на странице от этого не меняется. */
  function backWhere() { return location.pathname + location.search; }

  /* Опорный узел — первый пост или комментарий, чей низ ещё виден.
     Именно первый видимый, а не ближайший к середине: у поста в три
     экрана середина приходится на его же тело, и «вернуться к середине»
     значило бы вернуться неизвестно куда. Верхняя кромка однозначна. */
  function backSnap() {
    var host = root();
    if (!host) return null;
    var list = host.querySelectorAll('.post[id], .comment[id]');
    for (var i = 0; i < list.length; i++) {
      var r = list[i].getBoundingClientRect();
      if (r.bottom > 0) return { k: list[i].id, o: Math.round(r.top) };
    }
    return null;
  }

  function backSave() {
    if (!backOn()) return;
    var snap = backSnap();
    var data = {
      w: backWhere(),
      y: Math.round(scrollTopNow()),
      k: snap ? snap.k : '',
      o: snap ? snap.o : 0
    };
    /* Верх страницы не запоминаем: возвращаться к нему браузер и так
       умеет, а запись стёрла бы прежнюю, настоящую. */
    if (!data.y && !data.k) return;
    try { sessionStorage.setItem(BACK_KEY, JSON.stringify(data)); } catch (e) {}
  }

  function backRead() {
    try {
      var raw = sessionStorage.getItem(BACK_KEY);
      var d = raw && JSON.parse(raw);
      return (d && d.w === backWhere()) ? d : null;
    } catch (e) { return null; }
  }

  /* Как сюда попали. Восстанавливаем в двух случаях: «назад-вперёд» —
     ради чего всё и затевалось, и «перезагрузка» — потому что взяв
     восстановление на себя (scrollRestoration: manual), мы отняли его у
     браузера ЦЕЛИКОМ, а не только для кнопки «назад». Не вернув место
     после обновления страницы, мы починили бы одно и сломали другое.

     Обычный переход по ссылке в список не входит: он должен
     открываться сверху.

     Два источника: новый (тип записи в журнале производительности) и
     старый, на случай если новый недоступен. Возвращаем строку, а не
     да/нет, — она уходит в отчёт: знать, почему не сработало, важнее,
     чем знать, что не сработало. */
  function backWhy() {
    try {
      var e = performance.getEntriesByType &&
              performance.getEntriesByType('navigation')[0];
      if (e && e.type)
        return (e.type === 'back_forward' || e.type === 'reload') ? e.type : '';
    } catch (err) {}
    try {
      var t = performance.navigation && performance.navigation.type;
      if (t === 2) return 'back_forward';
      if (t === 1) return 'reload';
    } catch (err) {}
    return '';
  }

  var backLog = '';

  /* Один заход восстановления. Возвращает true, когда попал: тогда
     остальные заходы отменяются.
     Мажем по узлу, а если узла на месте нет (лента перетасовалась,
     комментарий свернулся) — по пикселям, как умеет браузер. Хуже, чем
     сейчас, от этого не станет. */
  function backGo(d) {
    var el = d.k && document.getElementById(d.k);
    if (el) {
      var r = el.getBoundingClientRect();
      var want = scrollTopNow() + r.top - d.o;
      if (Math.abs(r.top - d.o) <= 2) return true;
      scrollTopSet(want);
      backLog = 'по узлу ' + d.k + ' (смещение ' + d.o + ')';
      /* Проверяем сразу же: если высота ещё не устоялась, прокрутка
         упрётся в конец документа и до места не дотянет. */
      return Math.abs(el.getBoundingClientRect().top - d.o) <= 2;
    }
    if (!d.y) return true;
    if (Math.abs(scrollTopNow() - d.y) <= 2) return true;
    scrollTopSet(d.y);
    backLog = 'по пикселям (' + d.y + ', узла ' + (d.k || '—') + ' на месте нет)';
    return Math.abs(scrollTopNow() - d.y) <= 2;
  }

  function backRestore() {
    if (!backOn()) return;
    var why = backWhy();
    if (!why) { backLog = 'обычный переход — не трогаем'; return; }
    var d = backRead();
    if (!d) { backLog = why + ': записи для этой страницы нет'; return; }
    backLog = why + ': ищем место';

    /* Заходы те же по смыслу, что у формы ответа: первый — когда
       разметка на месте, последние — когда сокращение постов и потолки
       медиа уже отработали и высота перестала прыгать. */
    var tries = [0, 300, 800, 1600, 2600, 4000];
    var step = function (i) {
      if (i >= tries.length) return;
      setTimeout(function () {
        if (guard('backGo', backGo)(d)) return;
        step(i + 1);
      }, tries[i]);
    };
    step(0);
  }

  function watchBack() {
    if (!backOn() || watchBack.on) return;
    watchBack.on = true;
    /* Ручное восстановление: иначе браузер сделает своё поверх нашего, и
       спорить с ним придётся каждому заходу. Ставим только там, где
       раздел вообще работает, — WebKit остаётся с заводским поведением,
       которое его устраивает. */
    try { history.scrollRestoration = 'manual'; } catch (e) {}
    window.addEventListener('pagehide', guard('backSave', backSave));
    /* На Андроиде уход со страницы не всегда доходит до pagehide —
       вкладку могут просто увести в фон. Снимок при этом лишним не
       будет: он перепишется следующим. */
    document.addEventListener('visibilitychange', function () {
      if (document.visibilityState === 'hidden') guard('backSave', backSave)();
    });
  }

  /* ============================================================
     10. ЗАПУСК
     ============================================================ */

  /* Полный проход: тяжёлые обходы DOM только здесь, не при прокрутке. */
  /* Погасить траурную таблицу стилей лепры. См. CFG.mournOff.
     Ищем по первым правилам, а не по адресу: адрес у неё меняется от
     сборки к сборке, а вставлена она бывает и ссылкой, и прямо в
     разметку. Первых пяти правил хватает — приставка `html .l-content`
     стоит в самом начале.
     Чужие таблицы читать разрешено не всегда: у подключённых с другого
     домена (шрифты Google) обращение к cssRules бросает исключение.
     Такую помечаем просмотренной и идём дальше. */
  function dropMourning() {
    if (!CFG.mournOff) return;
    var sheets = document.styleSheets;
    for (var i = 0; i < sheets.length; i++) {
      var sh = sheets[i];
      if (sh.__lmSeen) continue;
      if (sh.ownerNode && sh.ownerNode.id === 'lepra-mobile-css') { sh.__lmSeen = 1; continue; }
      var rules;
      try { rules = sh.cssRules; } catch (e) { sh.__lmSeen = 1; continue; }
      if (!rules || !rules.length) continue;   /* ещё не разобрана — вернёмся */
      sh.__lmSeen = 1;
      for (var j = 0; j < rules.length && j < 5; j++) {
        var sel = rules[j].selectorText || '';
        if (sel.indexOf('html .l-content') === 0) {
          sh.disabled = true;
          mournOffCount++;
          break;
        }
      }
    }
  }

  var mournOffCount = 0;   /* сколько таблиц погашено — для отчёта */

  function fullPass() {
    /* Первым делом: контейнер ленты или комментариев мог появиться
       только что — вкладкой профиля, например, — и наблюдатель обязан
       переехать на него. Сам разберётся, менять ли что-нибудь. */
    guard('watchDom', watchDom)();
    guard('killSubsiteCss', killSubsiteCss)();
    guard('dropMourning', dropMourning)();
    /* Свои голоса поднимаем из памяти один раз за страницу — до того,
       как их спросит первое же открытое окно пыни. */
    if (!fullPass.votes) { fullPass.votes = 1; guard('votesLoad', votesLoad)(); }
    /* Прогреваем токен для /ajax/: ищем его в разметке сразу, а не в
       момент, когда он понадобился. Так он успевает лечь в общую для
       поддоменов куку — и на странице, где его в разметке не окажется,
       возьмётся оттуда. */
    guard('ajaxCsrf', ajaxCsrf)();
    guard('threadSnap', threadSnap)();
    guard('ensureThemeToggle', ensureThemeToggle)();
    guard('setThemeColor', setThemeColor)();
    guard('ensureNav', ensureNav)();
    guard('watchRefreshButton', watchRefreshButton)();
    guard('cfBuild', cfBuild)();
    guard('watchReply', watchReply)();
    /* Кегль полей формы — до того, как в форму ткнут: решение о
       приближении Safari принимает в момент нажатия, и поднимать кегль
       по касанию было бы поздно. */
    guard('formFontVar', formFontVar)();
    guard('watchZoom', watchZoom)();
    guard('watchNewComment', watchNewComment)();
    guard('compactPostFooters', compactPostFooters)();
    guard('compactCommentFooters', compactCommentFooters)();
    /* класс страницы — до перестройки шапки: она смотрит на него */
    guard('markTabsPage', markTabsPage)();
    guard('markFraudPage', markFraudPage)();
    guard('relayoutHeader', relayoutHeader)();
    /* строго после шапки: она собирает шапку, за которой встаёт блок */
    guard('buildNavthing', buildNavthing)();
    /* Строго после неё: значки переезжают в третью колонку, а селектор
       подсказок привязан к колонке — до переезда искать нечего. */
    guard('mountFeedHints', mountFeedHints)();
    guard('fixEventsPage', fixEventsPage)();
    guard('watchPyn', watchPyn)();
    guard('fixNewPost', fixNewPost)();
    guard('fixRanks', fixRanks)();
    guard('syncVeg', syncVeg)();
    /* строго после навигационной штуки: она забирает из правой колонки
       подлепры порог постов */
    guard('buildSubsitePince', buildSubsitePince)();
    /* после пенсне: оно забирает из-под девиза правую колонку, и до этого
       ширина у заголовка бывает другой */
    guard('fitSubsiteHeader', fitSubsiteHeader)();
    /* после навигационной штуки: подписи и кегль поля выбора порога
       считаются по её третьей колонке. Сокращение подписей — раньше
       замера: мерить надо то, что видно в свёрнутом виде */
    guard('prepThreshold', prepThreshold)();
    guard('fitThreshold', fitThreshold)();
    guard('watchSearch', watchSearch)();
    guard('markProfileArt', markProfileArt)();
    guard('fixUserNote', fixUserNote)();
    guard('moveKarmaToName', moveKarmaToName)();
    guard('watchVotesPopup', watchVotesPopup)();
    guard('fitVotesPopup', fitVotesPopup)();
    guard('fitOverlays', fitOverlays)();
    guard('groupNotesRow', groupNotesRow)();
    guard('compactCitizen', compactCitizen)();
    guard('fixUsersList', fixUsersList)();
    guard('buildUsersRows', buildUsersRows)();
    /* результаты поиска догружаются кнопкой «Ещё? Ещё!» */
    guard('shortenSearchStats', shortenSearchStats)();
    guard('watchUserCards', watchUserCards)();
    guard('fixMyThings', fixMyThings)();
    guard('shortenSubNav', shortenSubNav)();
    guard('fitSelects', fitSelects)();
    /* строку фильтров меряем ПОСЛЕ подгонки полей: до неё ширины ещё не те */
    guard('fitFiltersRow', fitFiltersRow)();
    /* строки настроек списка граждан меряем после подгонки полей */
    guard('fitUsersRows', fitUsersRows)();
    guard('shortenTabs', shortenTabs)();
    guard('unfloatWide', unfloatWide)();
    /* Эмодзи — до замеров медиа и сокращения: обёртка строчная и высоты
       не меняет, но пусть разметка будет окончательной к моменту, когда
       по ней начнут считать бюджеты. */
    guard('fixEmoji', fixEmoji)();
    guard('registerMedia', registerMedia)();
    guard('fixMediaSizes', fixMediaSizes)();
    guard('fixOverflow', fixOverflow)();
    /* Сокращение — последним: бюджет считается по высотам, а высоты
       медиа выставляет проход выше. У поста с видео до этого высота
       нулевая, и он не прошёл бы отбор по длине. */
    guard('discoWatchMedia', discoWatchMedia)();
    guard('discoWatchScroll', discoWatchScroll)();
    discoRefresh();
  }

  /* Лёгкий проход при прокрутке: только поиск по конкретным селекторам.
     Полный обход здесь занимал главный поток на секунды. */
  /* Учёт стоимости лёгких проходов. Их запускает наблюдатель за
     разметкой, и на длинной ленте они идут пачками: в отчёте с
     устройства при 206 постах отбор диско отработал 79 раз, то есть
     столько же раз прошёл и весь остальной список — а в нём полтора
     десятка обходов документа. Сам отбор мы удешевили, и он теперь
     занимает ноль миллисекунд; следующий подозреваемый — всё
     остальное, и до цифр обвинять его нельзя.
     Считаем суммарно, а не по каждому вызову: нужен порядок величины,
     а не профиль. Замер стоит одного Date.now на проход. */
  var lightRuns = 0, lightMs = 0, lightWorst = 0;

  function lightPass() {
    var lt0 = Date.now();
    lightRuns++;
    lightBody();
    var lms = Date.now() - lt0;
    lightMs += lms;
    if (lms > lightWorst) lightWorst = lms;
  }

  function lightBody() {
    /* Догруженные комментарии и посты приходят со своими эмодзи. Проход
       дешёвый: обойдённые тела помечены, и повторный заход до них не
       доходит вовсе. */
    guard('fixEmoji', fixEmoji)();
    /* Тред лепра дособирает после загрузки, и формы в конце к первому
       полному проходу может ещё не быть. Проход сам уходит ни с чем,
       если уже отработал. */
    guard('watchNewComment', watchNewComment)();
    guard('registerMedia', registerMedia)();
    guard('fixMediaSizes', fixMediaSizes)();
    /* заметка профиля: лепра переписывает её содержимое своим скриптом */
    guard('maybeShortenNote', maybeShortenNote)();
    /* окно голосов наполняется списком после ответа сервера — переставляем
       его ещё раз, когда узлы списка уже на месте */
    guard('fitVotesPopup', fitVotesPopup)();
    guard('fitOverlays', fitOverlays)();
    guard('syncThemeColor', syncThemeColor)();
    /* комментарии могли догрузиться — числа и подписи устарели */
    guard('refreshCommentCounters', refreshCommentCounters)();
    /* Строка фильтров: лепра собирает её своим скриптом, и к первому
       полному проходу её может ещё не быть. Сборка сама уходит ни с чем,
       если уже отработала; подпись шеврона обновляем всегда — выбранный
       фильтр меняется без единого добавления узлов. */
    guard('cfBuild', cfBuild)();
    guard('cfSync', cfSync)();
    guard('compactPostFooters', compactPostFooters)();
    guard('compactCommentFooters', compactCommentFooters)();
    /* лента уведомлений собирается скриптом лепры после загрузки, а
       дальше дописывается прокруткой — значков к первому проходу нет */
    guard('fixEventsPage', fixEventsPage)();
    /* список граждан догружается кнопкой «Загрузить ещё» */
    guard('fixUsersList', fixUsersList)();
    guard('buildUsersRows', buildUsersRows)();
    /* результаты поиска приходят ответом сервера, строку счёта лепра
       переписывает заново */
    guard('shortenSearchStats', shortenSearchStats)();
    /* лента догружается «Ещё? Ещё!», у постов с видео высота появляется
       только после подгрузки заголовка ролика, а вкладки профиля лепра
       переключает вовсе без перезагрузки — во всех трёх случаях меняется
       и то, что резать, и то, нужны ли кнопки */
    discoRefresh();
  }

  function start() {
    /* Слежение — до восстановления: снимок надо начать снимать в любом
       случае, даже если возвращать сейчас нечего. */
    guard('watchBack', watchBack)();
    guard('backRestore', backRestore)();
    guard('watchSubsiteCss', watchSubsiteCss)();
    fullPass();
    /* Слушатели нажатий вешаем ЗДЕСЬ, а не только по load. Раньше они
       ставились единственный раз — в обработчике load, — и это тихая
       зависимость от того, что load вообще случится и что до него
       ничего не упадёт. Оба условия небесплатны: рядом стоял
       незащищённый watchDom, и его падение унесло бы с собой обе
       привязки; а на странице, открытой из кэша назад-вперёд, load
       может и не прийти.
       Обе функции идемпотентны (свои флаги), так что повторный вызов по
       load ничего не портит и оставлен как подстраховка. */
    guard('watchTaps', watchTaps)();
    guard('watchMore', watchMore)();
    guard('watchRoute', watchRoute)();
    setTimeout(fullPass, 800);
    setTimeout(fullPass, 2500);
    if (CFG.debug && /lmdebug/.test(location.hash + location.search))
      setTimeout(panel, 400);
  }

  if (document.readyState === 'loading')
    document.addEventListener('DOMContentLoaded', start);
  else start();

  window.addEventListener('load', function () {
    setTimeout(fullPass, 300);
    guard('watchDom', watchDom)();
    guard('watchTaps', watchTaps)();
    guard('watchMore', watchMore)();
  });
  window.addEventListener('orientationchange', function () { setTimeout(fullPass, 300); });

  /* Масштаб страницы Den меняет прямо на ходу, и CSS-ширина скачет от 462
     до 340 без поворота экрана. Пересчитывать надо только то, что подобрано
     замером; полный проход сюда вешать нельзя — resize в Safari прилетает
     и от прячущейся адресной строки, то есть при обычной прокрутке.
     Поэтому: сверяем ширину и трогаем один заголовок. */
  var resizeTimer = null;

  window.addEventListener('resize', function () {
    if (resizeTimer) return;
    resizeTimer = setTimeout(function () {
      resizeTimer = null;
      if (document.documentElement.clientWidth === titleWidth) return;
      guard('fitSubsiteHeader', fitSubsiteHeader)();
      guard('fitThreshold', fitThreshold)();
    }, 300);
  });

  /* Прокрутка сама по себе ничего не запускает: раньше каждые 150 мс шёл
     поиск по всему документу, а лента длиной в сорок тысяч пикселей делает
     это дорогим. Новые узлы (догрузка комментариев, разворот веток) ловит
     наблюдатель за изменениями — он срабатывает только когда есть что
     обрабатывать. */
  var mutationTimer = null;

  function scheduleLightPass() {
    if (mutationTimer) return;
    mutationTimer = setTimeout(function () {
      mutationTimer = null;
      lightPass();
    }, 400);
  }

  /* Модальное окно лепра рисует в ответ на нажатие. Наблюдатель за узлами
     ловит не всякое: часть окон уже лежит в разметке скрытой, и лепра
     только меняет им стиль — добавления узлов при этом нет. Поэтому после
     каждого нажатия проверяем слои отдельно, тремя заходами: разметка,
     раскладка и анимация появления доходят до конца не сразу. */
  function watchTaps() {
    document.addEventListener('click', function () {
      [60, 260, 700].forEach(function (ms) {
        setTimeout(guard('fitOverlays', fitOverlays), ms);
        setTimeout(guard('syncThemeColor', syncThemeColor), ms);
      });
    }, true);
  }

  /* Наблюдатель за добавлением узлов.

     Вызывается не единожды, а при каждом полном проходе, и вот почему.
     Вкладки профиля («посты», «комментарии») лепра переключает без
     перезагрузки: меняет адрес через историю и вставляет содержимое
     ответом сервера. На голом профиле ни ленты, ни комментариев ещё
     нет, наблюдатель садится на body — и всё бы ничего, но контейнер
     появляется ПОСЛЕ, и правильнее смотреть за ним. Держим ссылку на
     узел, за которым следим; сменился — переподписываемся.

     Наблюдать за body всё время нельзя: с subtree это вся страница, и
     мы это уже проходили — бесконечная череда проходов и греющийся
     телефон. Поэтому body только как временное пристанище, пока
     настоящего контейнера нет. */
  function watchDom() {
    if (!('MutationObserver' in window) || !document.body) return;
    var target = document.getElementById('js-comments_holder') ||
                 document.getElementById('js-posts_holder') ||
                 document.body;
    if (target === watchDom.at) return;
    if (watchDom.obs) watchDom.obs.disconnect();
    watchDom.at = target;
    watchDom.obs = new MutationObserver(function (records) {
      for (var i = 0; i < records.length; i++)
        if (records[i].addedNodes && records[i].addedNodes.length)
          return scheduleLightPass();
    });
    watchDom.obs.observe(target, { childList: true, subtree: true });
  }

  /* Смена адреса без перезагрузки.

     Это и есть причина, по которой на вкладке профиля подпись
     оставалась лепровской, а после обновления страницы того же адреса
     становилась нашей. Вкладка меняет адрес через history.pushState, а
     этот метод НЕ ПОРОЖДАЕТ НИКАКИХ СОБЫТИЙ — ни одного, никакого.
     Обёртка вокруг него в скрипте была, но звала она только
     discoChase(), то есть занималась исключительно уплотнением, да и то
     лишь при включённом CFG.disco. Всё остальное — подписи, даты,
     значки под точкой — про переключение вкладки не узнавало вовсе.

     Теперь обёртка общая и зовёт полный проход. Три захода с задержкой:
     содержимое приходит ответом сервера уже ПОСЛЕ смены адреса, и
     единственный проход в момент вызова застал бы пустое место.
     Проходы идемпотентны, лишний ничего не портит.

     Свой вызов делаем после родного, чтобы поведение страницы не
     менялось ни на йоту. */
  var routeWatched = false;

  function watchRoute() {
    if (routeWatched) return;
    routeWatched = true;

    var after = function () {
      setTimeout(fullPass, 60);
      setTimeout(fullPass, 500);
      setTimeout(fullPass, 1500);
    };

    window.addEventListener('popstate', after);
    window.addEventListener('hashchange', after);
    ['pushState', 'replaceState'].forEach(function (name) {
      var orig = history[name];
      if (typeof orig !== 'function') return;
      history[name] = function () {
        var out = orig.apply(this, arguments);
        after();
        return out;
      };
    });
  }
})();
